def _canonical_operational_document(value: Any) -> Any:
    """Return plain JSON for setup identity, independent of container type."""
    return json.loads(_canonical_binding(value))


def _operational_attestation_binding(value: Mapping[str, Any]) -> dict[str, Any]:
    """Keep one bounded, plain attestation identity for setup binding."""
    allowed = (
        "dataset_id",
        "dataset_version",
        "source_type",
        "market_type",
        "row_count",
        "observed_row_count",
        "completeness",
        "start_timestamp",
        "end_timestamp",
        "contamination_result",
        "provenance_version",
        "policy_version",
        "reason",
        "attestation_hash",
        "verified_at",
        "status",
    )
    result = {
        key: value[key]
        for key in allowed
        if key in value and value[key] is not None
    }
    bindings = value.get("constituent_bindings", value.get("constituents"))
    if "constituent_count" in value:
        result["constituent_count"] = value["constituent_count"]
    elif isinstance(bindings, (list, tuple)):
        result["constituent_count"] = len(bindings)
    digest = next(
        (
            value[key]
            for key in (
                "canonical_digest",
                "constituent_bindings_digest",
                "constituent_digest",
                "bindings_digest",
            )
            if value.get(key) not in (None, "")
        ),
        None,
    )
    if digest is None and isinstance(bindings, (list, tuple)):
        digest = _hash_document(bindings)
    if digest is not None:
        result["canonical_digest"] = digest
        result["constituent_bindings_digest"] = digest
    return _canonical_operational_document(result)


def _operational_boundary_binding(value: Mapping[str, Any]) -> dict[str, Any]:
    """Keep one bounded, plain dataset-boundary identity for setup binding."""
    result = {
        key: value[key]
        for key in _OPERATIONAL_BOUNDARY_FIELDS
        if key in value and value[key] is not None
    }
    split_boundaries = value.get("split_boundaries")
    if isinstance(split_boundaries, Mapping):
        bounded_splits: dict[str, dict[str, Any]] = {}
        for name in ("development", "validation", "final"):
            descriptor = split_boundaries.get(name)
            if not isinstance(descriptor, Mapping):
                continue
            bounded_splits[name] = {
                key: descriptor[key]
                for key in _OPERATIONAL_SPLIT_BOUNDARY_FIELDS
                if key in descriptor and descriptor[key] is not None
            }
        if bounded_splits:
            result["split_boundaries"] = bounded_splits
    return _canonical_operational_document(result)




def _campaign_configuration_key(value: Mapping[str, Any]) -> str:
    template = str(value.get("template", value.get("family", ""))).strip().lower()
    parameters = value.get("parameters")
    if not isinstance(parameters, Mapping):
        parameters = {
            key: value[key]
            for key in ("lookback", "threshold")
            if key in value
        }
    normalized_parameters: dict[str, Any] = {}
    for key, parameter in parameters.items():
        if isinstance(parameter, (list, tuple)) and len(parameter) == 1:
            parameter = parameter[0]
        normalized_parameters[str(key)] = parameter
    return _canonical_binding({"template": template, "parameters": normalized_parameters})
def _campaign_row_identity(row: Mapping[str, Any], index: int) -> str:
    for name in ("row_identity", "source_snapshot_id", "snapshot_id", "observation_id"):
        value = row.get(name)
        if value is not None and str(value).strip():
            return str(value).strip()
    market = str(row.get("market_id", row.get("symbol", ""))).strip()
    timestamp = str(row.get("timestamp", row.get("source_timestamp", ""))).strip()
    if market or timestamp:
        return f"{market}@{timestamp}"
    return f"row:{index}"


def _campaign_row_manifest(rows: Sequence[Mapping[str, Any]]) -> list[dict[str, str]]:
    return [
        {
            "row_identity": _campaign_row_identity(row, index),
            "content_hash": _hash_document(row),
        }
        for index, row in enumerate(rows)
    ]


def _campaign_split_ranges(count: int) -> dict[str, tuple[int, int]]:
    train_end = max(0, int(count * 0.60))
    validation_end = max(train_end, int(count * 0.80))
    if count:
        train_end = min(count, max(1, train_end))
        validation_end = min(count, max(train_end, validation_end))
    return {
        "development": (0, train_end),
        "validation": (train_end, validation_end),
        "final": (validation_end, count),
    }


def _campaign_compact_row_provenance(rows: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    """Return bounded evidence that authenticates the complete ordered rows.

    The manifest is materialized only while computing its digest.  Persisted
    campaign/proposal payloads carry the digest and split boundary identities,
    never the per-row manifest itself.
    """
    manifest = _campaign_row_manifest(rows)
    timestamps = [
        parse_timestamp(row.get("timestamp", row.get("source_timestamp")))
        for row in rows
    ]
    timestamps = [value for value in timestamps if value is not None]
    split_boundaries: dict[str, dict[str, Any]] = {}
    for name, (start, end) in _campaign_split_ranges(len(rows)).items():
        part = manifest[start:end]
        split: dict[str, Any] = {
            "start_index": start,
            "end_index": end,
            "row_count": len(part),
        }
        if part:
            split.update(
                {
                    "first_row_identity": part[0]["row_identity"],
                    "last_row_identity": part[-1]["row_identity"],
                    "first_content_hash": part[0]["content_hash"],
                    "last_content_hash": part[-1]["content_hash"],
                }
            )
        split_boundaries[name] = split
    digest = _hash_document(manifest)
    return {
        "schema_version": "axiom-compact-row-provenance-v1",
        "row_count": len(rows),
        "exact_cutoff": max(timestamps).isoformat() if timestamps else None,
        "ordered_row_manifest_digest": digest,
        # ``root`` is an explicit alias for consumers that call the ordered
        # manifest commitment a Merkle/root digest; both names are one value.
        "ordered_row_manifest_root": digest,
        "content_hash": digest,
        "split_boundaries": split_boundaries,
    }


def _campaign_rows_for_split(
    rows: Sequence[Mapping[str, Any]],
    descriptor: Any,
) -> list[Mapping[str, Any]]:
    """Resolve a compact split descriptor while checking its row identities."""
    if isinstance(descriptor, (list, tuple)):
        # Read-only compatibility for campaigns persisted before compact
        # provenance. New payloads never take this path.
        identities = {
            str(item.get("row_identity"))
            for item in descriptor
            if isinstance(item, Mapping)
        }
        return [
            row
            for index, row in enumerate(rows)
            if _campaign_row_identity(row, index) in identities
        ]
    if not isinstance(descriptor, Mapping):
        raise AutonomousResearchError(
            "DATASET_PROVENANCE_INVALID",
            "campaign split provenance is missing",
        )
    try:
        start = int(descriptor.get("start_index"))
        end = int(descriptor.get("end_index"))
        expected_count = int(descriptor.get("row_count"))
    except (TypeError, ValueError):
        raise AutonomousResearchError(
            "DATASET_PROVENANCE_INVALID",
            "campaign split provenance indexes are invalid",
        ) from None
    if start < 0 or end < start or end > len(rows):
        raise AutonomousResearchError(
            "DATASET_PROVENANCE_INVALID",
            "campaign split provenance indexes exceed the dataset boundary",
        )
    manifest = _campaign_row_manifest(rows)
    part = list(rows[start:end])
    part_manifest = manifest[start:end]
    if expected_count != len(part):
        raise AutonomousResearchError(
            "DATASET_PROVENANCE_INVALID",
            "campaign split row count changed after enqueue",
        )
    if part_manifest:
        if (
            str(descriptor.get("first_row_identity", "")).strip()
            != part_manifest[0]["row_identity"]
            or str(descriptor.get("last_row_identity", "")).strip()
            != part_manifest[-1]["row_identity"]
            or str(descriptor.get("first_content_hash", "")).strip()
            != part_manifest[0]["content_hash"]
            or str(descriptor.get("last_content_hash", "")).strip()
            != part_manifest[-1]["content_hash"]
        ):
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                "campaign split boundary identity changed after enqueue",
            )
    return part


def _variant_count(plan: ExperimentPlan) -> int:
    count = 1
    for values in plan.parameters.values():
        count *= len(values)
    return count






def _binding_value(value: Any) -> str | None:
    """Normalize a persisted binding value without turning ``None`` into text."""
    if value is None:
        return None
    text = str(value).strip()
    return text or None


def _rolling_identity_values(
    value: Any,
    *names: str,
    max_depth: int = _ROLLING_MAX_PROVENANCE_DEPTH,
) -> tuple[set[str], bool]:
    """Collect candidate identity from bounded authoritative containers.

    Lifecycle payloads carry both identity/provenance and large observation
    manifests.  Walking every value makes an attestation's constituent list
    look like candidate identity and exhausts the traversal budget.  Mapping
    containers remain recursively inspectable for strict conflict detection;
    known bulk arrays are deliberately opaque because they are not identity
    authority.
    """
    values: set[str] = set()
    pending: list[tuple[Any, int, str | None]] = [(value, 0, None)]
    seen: set[int] = set()
    truncated = False
    visited = 0
    wanted = frozenset(names)
    while pending:
        item, depth, parent_key = pending.pop()
        if isinstance(item, Mapping):
            marker = id(item)
            if marker in seen:
                truncated = True
                continue
            seen.add(marker)
            visited += 1
            if visited > 512:
                truncated = True
                break
            for name in wanted:
                raw = item.get(name)
                # Structured identity fields are ambiguous, not absent.  A
                # mapping/list must never be silently ignored and allow the
                # remaining scalar candidate id to pass validation.
                if isinstance(raw, (Mapping, list, tuple)):
                    truncated = True
                    continue
                candidate = _binding_value(raw)
                if candidate:
                    values.add(candidate)
            if depth >= max_depth:
                # Only traversable mappings/sequences make this node
                # truncated; opaque bulk arrays do not consume the budget.
                if any(
                    isinstance(child, Mapping)
                    or (
                        isinstance(child, (list, tuple))
                        and str(key).strip().lower() not in _ROLLING_NON_AUTHORITATIVE_ARRAY_KEYS
                    )
                    for key, child in item.items()
                ):
                    truncated = True
                continue
            children = list(item.items())
            if len(children) > 512:
                truncated = True
                children = children[:512]
            for key, child in reversed(children):
                key_name = str(key).strip().lower()
                if isinstance(child, (list, tuple)):
                    if key_name in _ROLLING_NON_AUTHORITATIVE_ARRAY_KEYS:
                        continue
                    if len(child) > 128:
                        truncated = True
                    pending.append((child, depth + 1, key_name))
                elif isinstance(child, Mapping):
                    pending.append((child, depth + 1, key_name))
        elif isinstance(item, (list, tuple)):
            if parent_key in _ROLLING_NON_AUTHORITATIVE_ARRAY_KEYS:
                continue
            if depth > max_depth:
                if item:
                    truncated = True
                continue
            for child in reversed(item[:128]):
                pending.append((child, depth + 1, parent_key))
            if len(item) > 128:
                truncated = True
    return values, truncated


def _rolling_candidate_values(value: Any) -> tuple[set[str], bool]:
    return _rolling_identity_values(value, "candidate_id", "candidate", "strategy_candidate_id")


def _rolling_payload_without_created_at(value: Mapping[str, Any]) -> dict[str, Any]:
    """Return the complete immutable payload identity for retry comparisons."""
    return {
        str(key): child
        for key, child in value.items()
        if str(key) != "created_at"
    }


def _scope_binding(plan: ExperimentPlan) -> dict[str, Any]:
    """Return the canonical, recomputed authority carried by every worker artifact."""
    return {
        "market_scope": plan.market_scope.as_dict(),
        "market_scope_hash": plan.market_scope_hash,
        "market_scope_version": plan.market_scope_version,
        "scope_hash": plan.market_scope_hash,
        "scope_version": plan.market_scope_version,
        "dataset_selector": dict(plan.as_dict()["dataset_selector"]),
    }
def _operational_setup_fields(
    strategy: Any,
    plan: ExperimentPlan | None = None,
    *,
    dataset_attestation: Mapping[str, Any] | None = None,
    dataset_boundary: Mapping[str, Any] | None = None,
    include_live_extensions: bool = True,
) -> dict[str, Any]:
    """Return setup material for an explicitly versioned operational plan."""
    if plan is None:
        return {}
    protocol = plan.campaign_protocol
    protocol_v2 = (
        isinstance(protocol, Mapping)
        and str(protocol.get("schema_version", "")).strip() == CAMPAIGN_SCHEMA_V2
    )
    try:
        strategy_document = _normalized_strategy_document(strategy)
    except Exception:
        strategy_document = strategy
    exploratory = bool(
        include_live_extensions
        and isinstance(strategy_document, Mapping)
        and _exploratory_live_requested(strategy_document)
    )
    if not protocol_v2 and not exploratory:
        return {}
    config: dict[str, Any] = {}
    config.update(_scope_binding(plan))
    config.update(
        {
            "dataset_id": plan.dataset_id,
            "dataset_version": plan.dataset_version,
            "plan_id": plan.plan_id,
            "plan_hash": plan.plan_hash,
        }
    )
    attestation_binding = (
        _operational_attestation_binding(dataset_attestation)
        if isinstance(dataset_attestation, Mapping)
        else None
    )
    boundary_binding = (
        _operational_boundary_binding(dataset_boundary)
        if isinstance(dataset_boundary, Mapping)
        else None
    )
    if attestation_binding is not None:
        config["dataset_attestation"] = attestation_binding
    if boundary_binding is not None:
        config["dataset_boundary"] = boundary_binding
    if exploratory:
        config["operating_policy"] = dict(EXPLORATORY_LIVE_POLICY)
    if not exploratory:
        config["legacy_predeclared"] = True
    setup = _operational_setup_for_strategy(strategy, config)
    if setup is None:
        return {}
    canonical_setup = _canonical_operational_document(setup)
    result = {
        "operational_setup": canonical_setup,
        "operational_setup_hash": _operational_setup_hash(canonical_setup),
    }
    # Keep the exact immutable source bindings beside the setup.  Forward
    # registration recomputes the setup from this material and must see the
    # same attestation/boundary as the initial candidate registration.
    if attestation_binding is not None:
        result["dataset_attestation"] = attestation_binding
    if boundary_binding is not None:
        result["dataset_boundary"] = boundary_binding
    return result


def _strategy_with_operational_overlay(
    plan: ExperimentPlan,
    strategy: StrategyDefinition,
) -> StrategyDefinition:
    """Attach the canonical directional predicate only for supported plans."""
    protocol = plan.campaign_protocol
    protocol_v2 = (
        isinstance(protocol, Mapping)
        and str(protocol.get("schema_version", "")).strip() == CAMPAIGN_SCHEMA_V2
    )
    source = plan.strategy_document
    source_parameters = source.get("parameters") if isinstance(source, Mapping) else None
    predicate = (
        source_parameters.get("entry_predicate")
        if isinstance(source_parameters, Mapping)
        else None
    )
    document = strategy.to_dict()
    metadata = document.get("metadata")
    exploratory = (
        isinstance(metadata, Mapping)
        and str(metadata.get("operating_policy", "")).strip()
        == EXPLORATORY_LIVE_POLICY_VERSION
    )
    if not protocol_v2 and not exploratory:
        return strategy
    if predicate is None and exploratory:
        predicate = _ABSOLUTE_MOVE_PREDICATE
    if (
        not isinstance(predicate, Mapping)
        or _canonical_binding(predicate) != _canonical_binding(_ABSOLUTE_MOVE_PREDICATE)
    ):
        return strategy
    parameters = document.get("parameters")
    if not isinstance(parameters, Mapping) or "entry_predicate" in parameters:
        return strategy
    document["parameters"] = {
        **dict(parameters),
        "entry_predicate": dict(predicate),
    }
    return load_strategy(document)


def _strategy_metadata(strategy: StrategyDefinition) -> dict[str, Any]:
    metadata = strategy.metadata if isinstance(strategy.metadata, Mapping) else {}
    role = str(metadata.get("research_role", "")).strip()
    return {
        "research_role": role or None,
        "selection_excluded": bool(metadata.get("selection_excluded", False)),
        "proven_zero_edge": bool(metadata.get("proven_zero_edge", False)),
    }




def _canonical_binding(value: Any) -> str:
    def plain(item: Any) -> Any:
        if isinstance(item, datetime):
            # Persisted JSON bindings carry ISO strings while store readers
            # may return datetime objects.  Canonicalize both forms without
            # weakening any value comparison.
            return ensure_utc(item).isoformat()
        if isinstance(item, Mapping):
            return {str(key): plain(child) for key, child in item.items()}
        if isinstance(item, (list, tuple)):
            return [plain(child) for child in item]
        if isinstance(item, (set, frozenset)):
            return [plain(child) for child in sorted(item, key=str)]
        return item
    return json.dumps(plain(value), sort_keys=True, separators=(",", ":"), allow_nan=False, default=str)

def _rolling_number(value: Any, default: Decimal = Decimal("0")) -> Decimal:
    if isinstance(value, bool) or value is None:
        return default
    try:
        parsed = Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError):
        return default
    return parsed if parsed.is_finite() else default



def _rolling_strict_count(
    value: Any,
    name: str,
    *,
    default: int | None = None,
) -> int | None:
    """Parse a count without accepting truncation or non-finite values."""
    if value is None:
        return default
    if isinstance(value, bool):
        raise ValueError(f"{name} must be a non-negative integer")
    try:
        parsed = Decimal(str(value))
    except (InvalidOperation, TypeError, ValueError, OverflowError) as exc:
        raise ValueError(f"{name} must be a non-negative integer") from exc
    if not parsed.is_finite() or parsed < 0 or parsed != parsed.to_integral_value():
        raise ValueError(f"{name} must be a non-negative integer")
    return int(parsed)


_ROLLING_CANONICAL_ACCOUNTING_FIELDS = (
    "accounting_available",
    "initial_cash",
    "cash",
    "equity",
    "realized_pnl",
    "unrealized_pnl",
    "net_pnl",
    "fees",
    "costs",
    "allocated_capital",
    "capital_at_risk",
    "open_positions",
    "opening_fills",
    "closing_fills",
    "partial_closing_fills",
    "completed_round_trips",
)
_ROLLING_CANONICAL_MONETARY_FIELDS = (
    "initial_cash",
    "cash",
    "equity",
    "realized_pnl",
    "unrealized_pnl",
    "net_pnl",
    "fees",
    "costs",
    "allocated_capital",
    "capital_at_risk",
)


def _rolling_canonical_accounting_complete(value: Any) -> bool:
    if not isinstance(value, Mapping):
        return False
    if any(value.get(name) is None for name in _ROLLING_CANONICAL_ACCOUNTING_FIELDS):
        return False
    for name in _ROLLING_CANONICAL_MONETARY_FIELDS:
        item = value.get(name)
        if isinstance(item, bool):
            return False
        try:
            parsed = Decimal(str(item))
        except (InvalidOperation, TypeError, ValueError, OverflowError):
            return False
        if not parsed.is_finite():
            return False
    return True
def _operational_stage_projection(
    *,
    rows: Sequence[Any] = (),
    events: Sequence[Any] = (),
    fills: Sequence[Any] = (),
    ledgers: Sequence[Any] = (),
    curve: Sequence[Any] = (),
    valid_observations: int | None = None,
    remaining_positions: Any = None,
) -> dict[str, Any]:
    """Project execution stages without collapsing accounting or input reasons.

    This is deliberately a projection-only helper.  It consumes durable event
    and fill records when available, while keeping path exclusions, venue
    blockers, policy rejects, and unavailable accounting in separate buckets.
    Legacy sources without an operational gate therefore remain readable and
    report zero approved paper attempts rather than implying admission.
    """
    # Source rows alone are historical/canonical input, not operational stage
    # evidence.  Do not manufacture zero-valued stage metrics when the caller
    # has no event, fill, ledger, curve, or explicit observation projection.
    if not any(
        (
            events,
            fills,
            ledgers,
            curve,
            valid_observations is not None,
            remaining_positions is not None,
        )
    ):
        return {}

    def increment(bucket: dict[str, int], reason: Any, amount: int = 1) -> None:
        code = str(reason or "UNKNOWN").strip().upper() or "UNKNOWN"
        bucket[code] = bucket.get(code, 0) + max(1, int(amount))

    def payload_of(value: Any) -> Mapping[str, Any]:
        if not isinstance(value, Mapping):
            return {}
        payload = value.get("payload")
        return payload if isinstance(payload, Mapping) else value

    def event_view(value: Any) -> dict[str, Any]:
        if not isinstance(value, Mapping):
            return {}
        payload = payload_of(value)
        result = dict(value)
        result.update(payload)
        if value.get("status") is not None:
            result.setdefault("status", value.get("status"))
        return result

    def side_of(value: Any) -> str:
        if not isinstance(value, Mapping):
            return ""
        metadata = value.get("metadata")
        metadata = metadata if isinstance(metadata, Mapping) else {}
        side = value.get("side", metadata.get("side", ""))
        return str(getattr(side, "value", side)).strip().lower()

    def is_exit(value: Any) -> bool:
        if not isinstance(value, Mapping):
            metadata = getattr(value, "metadata", {})
            metadata = metadata if isinstance(metadata, Mapping) else {}
            kind = metadata.get("execution_kind", metadata.get("kind"))
            side = getattr(getattr(value, "side", None), "value", getattr(value, "side", ""))
        else:
            metadata = value.get("metadata")
            metadata = metadata if isinstance(metadata, Mapping) else {}
            kind = value.get("execution_kind", metadata.get("execution_kind", metadata.get("kind")))
            side = value.get("side", metadata.get("side", ""))
        kind_name = str(kind or "").strip().lower()
        side_name = str(getattr(side, "value", side)).strip().lower()
        return kind_name in {"exit", "close", "closing", "managed_exit"} or side_name in {
            "sell",
            "sell_yes",
            "sell_no",
        }

    def fill_mapping(value: Any) -> Mapping[str, Any]:
        if isinstance(value, Fill):
            metadata = value.metadata if isinstance(value.metadata, Mapping) else {}
            return {
                "side": getattr(value.side, "value", value.side),
                "quantity": value.quantity,
                "price": value.price,
                "fees": value.fees,
                "slippage": value.slippage,
                "metadata": metadata,
                "execution_kind": metadata.get("execution_kind"),
                "execution_status": metadata.get("execution_status"),
                "partial": metadata.get("partial"),
            }
        return value if isinstance(value, Mapping) else {}

    path_exclusions: dict[str, int] = {}
    accounting_limits: dict[str, int] = {}
    for raw in rows:
        if not isinstance(raw, Mapping):
            continue
        source_reason = raw.get("_rolling_source_rejection") or raw.get(
            "_rolling_timestamp_rejection"
        )
        accounting_reason = raw.get("_rolling_accounting_rejection")
        if source_reason:
            increment(path_exclusions, source_reason)
        if accounting_reason:
            reason = str(accounting_reason).strip().upper()
            if reason.startswith(("ACCOUNTING_", "PAPER_RESOLVED_BET_", "PERSISTENCE_")):
                increment(accounting_limits, reason)
            elif not source_reason:
                increment(path_exclusions, reason)

    entry_eligible = 0
    event_attempts = 0
    approved_attempts = 0
    managed_exit_attempts = 0
    policy_rejects: dict[str, int] = {}
    venue_blockers: dict[str, int] = {}
    gate_applied = False
    saw_event_entry_signal = False
    for raw in events:
        event = event_view(raw)
        if not event:
            continue
        operational = event.get("operational_evidence")
        operational = operational if isinstance(operational, Mapping) else {}
        gate_applied = gate_applied or bool(
            operational
            or event.get("operational_policy")
            or event.get("operational_policy_hash")
        )
        evidence = event.get("evaluation_evidence")
        evidence = evidence if isinstance(evidence, Mapping) else {}
        eligible = event.get("entry_eligible", evidence.get("entry_eligible"))
        is_exit_event = is_exit(event)
        if eligible is True and not is_exit_event:
            entry_eligible += 1
            saw_event_entry_signal = True
        status = str(event.get("status", "")).strip().upper()
        outcomes = event.get("outcomes", ())
        outcomes = tuple(str(item).strip().upper() for item in outcomes) if isinstance(
            outcomes, (list, tuple, set, frozenset)
        ) else ()
        attempted = bool(event.get("order_attempted")) or "ORDER_ATTEMPT" in outcomes
        if attempted:
            event_attempts += 1
            if is_exit_event:
                managed_exit_attempts += 1
            approved = (
                event.get("risk_approved") is True
                or operational.get("risk_approved") is True
                or operational.get("allowed") is True
            )
            if approved:
                approved_attempts += 1
        rejected = status in {
            "RISK_REJECTED",
            "POLICY_REJECTED",
            "BLOCKED",
            "REJECTED",
        } or bool(event.get("risk_rejected"))
        if rejected:
            reasons = event.get("blockers", operational.get("blockers", ()))
            reasons = list(reasons) if isinstance(
                reasons, (list, tuple, set, frozenset)
            ) else []
            reason = event.get(
                "reason_code",
                event.get("reason", operational.get("reason_code")),
            )
            if reason:
                reasons.append(reason)
            reasons.extend(
                outcome
                for outcome in outcomes
                if outcome != "ORDER_ATTEMPT"
                and any(
                    marker in outcome
                    for marker in (
                        "RISK",
                        "REJECT",
                        "BLOCK",
                        "VENUE",
                        "MIN_",
                        "ACCOUNTING",
                        "PERSISTENCE",
                    )
                )
            )
            if not reasons:
                reasons.append(status or "UNKNOWN")
            seen_reasons: set[str] = set()
            for reason in reasons:
                reason_name = str(reason).strip().upper()
                if not reason_name or reason_name in seen_reasons:
                    continue
                seen_reasons.add(reason_name)
                increment(policy_rejects, reason_name)
                if reason_name.startswith(("VENUE_", "MIN_")):
                    increment(venue_blockers, reason_name)
                if reason_name.startswith(
                    ("ACCOUNTING_", "PERSISTENCE_", "PAPER_RESOLVED_BET_")
                ):
                    increment(accounting_limits, reason_name)
        if status in {"INPUT_EXCLUDED", "PATH_EXCLUDED", "EXCLUDED"}:
            reason = event.get("reason_code", event.get("reason"))
            if reason:
                increment(path_exclusions, reason)
    if not saw_event_entry_signal:
        for raw in curve:
            if not isinstance(raw, Mapping):
                continue
            evidence = raw.get("evaluation_evidence")
            evidence = evidence if isinstance(evidence, Mapping) else {}
            if evidence.get("entry_eligible") is True and not is_exit(raw):
                entry_eligible += 1
        if not entry_eligible:
            for raw in rows:
                view = payload_of(raw)
                if view.get("entry_eligible") is True:
                    entry_eligible += 1

    fill_count = 0
    partial_count = 0
    managed_exit_fills = 0
    for raw in fills:
        item = fill_mapping(raw)
        if not item:
            continue
        fill_count += 1
        metadata = item.get("metadata")
        metadata = metadata if isinstance(metadata, Mapping) else {}
        status = str(
            item.get("execution_status", metadata.get("execution_status", ""))
        ).strip().upper()
        if item.get("partial") is True or status in {"PARTIAL", "PARTIAL_FILL", "PARTIALLY_FILLED"}:
            partial_count += 1
        if is_exit(item):
            managed_exit_fills += 1

    position_ids: list[str] = []
    if isinstance(remaining_positions, Mapping):
        position_ids = [str(key) for key in remaining_positions if str(key).strip()]
    elif isinstance(remaining_positions, (list, tuple, set, frozenset)):
        position_ids = [str(item) for item in remaining_positions if str(item).strip()]
    elif remaining_positions not in (None, ""):
        try:
            position_ids = [str(remaining_positions)] if int(remaining_positions) > 0 else []
        except (TypeError, ValueError):
            position_ids = []
    if not position_ids:
        for raw in ledgers:
            if not isinstance(raw, Mapping):
                continue
            item = payload_of(raw)
            open_positions = item.get("open_positions", item.get("remaining_positions", ()))
            if isinstance(open_positions, (list, tuple, set, frozenset)):
                position_ids.extend(str(value) for value in open_positions if str(value).strip())

    completed = 0
    gross: Decimal | None = None
    realized: Decimal | None = None
    unrealized: Decimal | None = None
    net: Decimal | None = None
    if ledgers:
        completed = sum(
            int(_rolling_number(payload_of(item).get("completed_outcomes", 1), Decimal("0")))
            for item in ledgers
            if isinstance(item, Mapping)
        )
        def total(name: str) -> Decimal:
            return sum(
                (_rolling_number(payload_of(item).get(name), Decimal("0")) for item in ledgers if isinstance(item, Mapping)),
                Decimal("0"),
            )
        realized = total("realized_pnl")
        unrealized = total("unrealized_pnl")
        net = total("net_pnl")
        if all(
            isinstance(item, Mapping) and payload_of(item).get("gross_pnl") is not None
            for item in ledgers
        ):
            gross = total("gross_pnl")
        else:
            gross = net + total("fees") + total("slippage")

    valid = valid_observations
    if valid is None:
        valid = sum(
            1
            for raw in rows
            if isinstance(raw, Mapping)
            and not raw.get("_rolling_source_rejection")
            and not raw.get("_rolling_timestamp_rejection")
        )
    stage = {
        "operational_gate_applied": bool(gate_applied),
        "valid_observations": int(valid),
        "entry_eligible_signals": int(entry_eligible),
        "genuine_entry_signals": int(entry_eligible),
        "risk_approved_paper_order_attempts": int(approved_attempts),
        "risk_approved_order_attempts": int(approved_attempts),
        "paper_order_attempts": int(event_attempts),
        "policy_risk_rejects_by_reason": dict(sorted(policy_rejects.items())),
        "risk_rejects_by_reason": dict(sorted(policy_rejects.items())),
        "venue_minimum_blockers_by_reason": dict(sorted(venue_blockers.items())),
        "input_path_exclusions_by_reason": dict(sorted(path_exclusions.items())),
        "persistence_accounting_limits_by_reason": dict(sorted(accounting_limits.items())),
        "fills": int(fill_count),
        "partial_fills": int(partial_count),
        "managed_exit_attempts": int(managed_exit_attempts),
        "managed_exit_fills": int(managed_exit_fills),
        "remaining_positions": len(set(position_ids)),
        "remaining_position_ids": sorted(set(position_ids)),
        "completed_outcomes": int(completed),
        "gross_result": gross,
        "realized_result": realized,
        "unrealized_result": unrealized,
        "net_result": net,
        "negative_economics": bool(net is not None and net < 0),

        "economic_result_available": net is not None,
    }
    return stage

def _operational_identity_projection(*sources: Any) -> dict[str, Any]:
    """Collect immutable setup/settings identity from runtime evidence."""
    result: dict[str, Any] = {}
    seen: set[int] = set()
    pending: list[tuple[Any, int]] = [(source, 0) for source in sources]
    setup_names = ("operational_setup",)
    settings_names = (
        "active_settings",
        "settings_snapshot",
        "operational_settings",
        "settings",
    )
    identity_names = {
        "operational_setup_hash": "operational_setup_hash",
        "settings_config_id": "settings_config_id",
        "settings_generation": "settings_generation",
        "settings_config_hash": "settings_config_hash",
        "control_generation": "control_generation",
    }
    settings_identity_names = {
        "config_id": "settings_config_id",
        "generation": "settings_generation",
        "config_hash": "settings_config_hash",
        "settings_config_id": "settings_config_id",
        "settings_generation": "settings_generation",
        "settings_config_hash": "settings_config_hash",
    }
    while pending:
        item, depth = pending.pop()
        if not isinstance(item, Mapping) or depth > 4 or id(item) in seen:
            continue
        seen.add(id(item))
        for name in setup_names:
            value = item.get(name)
            if isinstance(value, Mapping) and "operational_setup" not in result:
                result["operational_setup"] = _canonical_operational_document(value)
        for name, target in identity_names.items():
            value = item.get(name)
            if value not in (None, "") and target not in result:
                result[target] = value
        for name in settings_names:
            value = item.get(name)
            if isinstance(value, Mapping):
                if "active_settings" not in result:
                    result["active_settings"] = dict(value)
                for identity_name, target in settings_identity_names.items():
                    identity_value = value.get(identity_name)
                    if identity_value not in (None, "") and target not in result:
                        result[target] = identity_value
                pending.append((value, depth + 1))
        for key, value in item.items():
            if isinstance(value, Mapping):
                pending.append((value, depth + 1))
    setup = result.get("operational_setup")
    if isinstance(setup, Mapping) and "operational_setup_hash" not in result:
        result["operational_setup_hash"] = _operational_setup_hash(setup)
    return result


def _rolling_actual_ledger_accounting(
    projected: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    available_from: datetime,
    available_through: datetime,
) -> dict[str, Any]:
    """Build the canonical accounting document from exact PAPER ledgers.

    This path is observed accounting, not simulation output.  It therefore
    carries an explicit ACTUAL_LEDGER kind at its caller and never fabricates
    evaluator status.  A resolved-bet ledger may omit portfolio cash fields;
    in that narrow exact-ledger projection, allocated capital and net PnL
    define the isolated account view deterministically.
    """
    unavailable: dict[str, Any] = {
        "accounting_available": False,
        "accounting_complete": False,
        "accounting_partial": True,
        "initial_cash": None,
        "cash": None,
        "equity": None,
        "realized_pnl": None,
        "unrealized_pnl": None,
        "net_pnl": None,
        "fees": None,
        "costs": None,
        "allocated_capital": None,
        "capital_at_risk": None,
        "open_positions": [],
        "opening_fills": 0,
        "closing_fills": 0,
        "partial_closing_fills": 0,
        "completed_round_trips": 0,
        "available_from": available_from.isoformat(),
        "available_through": available_through.isoformat(),
    }
    def unavailable_result(reason: str | None = None) -> dict[str, Any]:
        result = dict(unavailable)
        if reason:
            result["accounting_unavailable_reason"] = reason
        return result
    docs = [
        dict(accounting)
        for row, accounting in projected
        if isinstance(row, Mapping)
        and not row.get("_rolling_partial")
        and isinstance(accounting, Mapping)
    ]
    if not docs or len(docs) != len(projected):
        return unavailable_result()
    if any(
        doc.get("accounting_available") is False
        or doc.get("accounting_complete") is False
        or doc.get("accounting_partial") is True
        for doc in docs
    ):
        return unavailable_result()

    def decimal_value(value: Any) -> Decimal | None:
        if value is None or isinstance(value, bool):
            return None
        try:
            parsed = Decimal(str(value))
        except (InvalidOperation, TypeError, ValueError, OverflowError):
            return None
        return parsed if parsed.is_finite() else None

    def required_sum(name: str, *aliases: str) -> Decimal | None:
        values: list[Decimal] = []
        for doc in docs:
            raw = next(
                (doc.get(key) for key in (name,) + aliases if doc.get(key) is not None),
                None,
            )
            parsed = decimal_value(raw)
            if parsed is None:
                return None
            values.append(parsed)
        return sum(values, Decimal("0"))

    monetary: dict[str, Decimal | None] = {
        "realized_pnl": required_sum("realized_pnl"),
        "unrealized_pnl": required_sum("unrealized_pnl"),
        "net_pnl": required_sum(
            "net_pnl", "allocated_capital_net_return", "net_return"
        ),
        "fees": required_sum("fees", "fee_costs"),
        "costs": required_sum("costs", "slippage_costs"),
        "allocated_capital": required_sum(
            "allocated_capital", "capital_at_risk", "paper_sizing", "paper_size"
        ),
        "capital_at_risk": required_sum("capital_at_risk", "allocated_capital"),
    }
    if any(value is None for value in monetary.values()):
        return unavailable_result()

    def endpoint(name: str, fallback: Decimal) -> Decimal | None:
        values = [
            decimal_value(doc.get(name))
            for doc in docs
            if doc.get(name) is not None
        ]
        if any(value is None for value in values):
            return None
        return values[-1] if values else fallback

    initial_cash = endpoint("initial_cash", monetary["allocated_capital"] or Decimal("0"))
    net_pnl = monetary["net_pnl"] or Decimal("0")
    cash = endpoint(
        "cash",
        initial_cash + net_pnl if initial_cash is not None else Decimal("0"),
    )
    equity = endpoint("equity", cash if cash is not None else Decimal("0"))
    if initial_cash is None or cash is None or equity is None:
        return unavailable_result()

    activity_limit_error: str | None = None

    def activity(name: str, *, default: Any) -> Any:
        nonlocal activity_limit_error
        values = [doc.get(name) for doc in docs if doc.get(name) is not None]
        if not values:
            return default
        if all(isinstance(value, (list, tuple)) for value in values):
            merged: list[Any] = []
            for value in values:
                merged.extend(list(value))
                if (
                    name == "open_positions"
                    and len(merged) > _ROLLING_OPEN_POSITIONS_LIMIT
                ):
                    activity_limit_error = _ROLLING_OPEN_POSITIONS_LIMIT_REASON
                    return None
            return merged
        counts: list[int] = []
        for value in values:
            try:
                parsed = _rolling_strict_count(value, name)
            except ValueError:
                return None
            counts.append(int(parsed or 0))
        return sum(counts)

    completed = activity("completed_round_trips", default=None)
    if completed is None:
        completed = activity("completed_outcomes", default=0)
    if not isinstance(completed, int) or completed < 0:
        return unavailable_result()
    open_positions = activity("open_positions", default=[])
    if isinstance(open_positions, int):
        if open_positions != 0:
            return unavailable_result()
        open_positions = []

    def activity_count(name: str) -> int | None:
        value = activity(name, default=0)
        if isinstance(value, (list, tuple)):
            return len(value)
        return value if isinstance(value, int) else None

    opening_fills = activity_count("opening_fills")
    closing_fills = activity_count("closing_fills")
    partial_closing_fills = activity_count("partial_closing_fills")
    if any(
        value is None
        for value in (open_positions, opening_fills, closing_fills, partial_closing_fills)
    ):
        return unavailable_result(activity_limit_error)
    drawdown_values = [
        decimal_value(doc.get("drawdown"))
        for doc in docs
        if doc.get("drawdown") is not None
    ]
    reliability_values = [
        decimal_value(doc.get("reliability"))
        for doc in docs
        if doc.get("reliability") is not None
    ]
    if any(value is None for value in (*drawdown_values, *reliability_values)):
        return unavailable_result()
    return {
        "accounting_available": True,
        "accounting_complete": True,
        "accounting_partial": False,
        **monetary,
        "initial_cash": initial_cash,
        "cash": cash,
        "equity": equity,
        "open_positions": list(open_positions),
        "opening_fills": opening_fills,
        "closing_fills": closing_fills,
        "partial_closing_fills": partial_closing_fills,
        "completed_round_trips": completed,
        "open_position_count": len(open_positions),
        "drawdown": max(drawdown_values, default=Decimal("0")),
        "reliability": (
            sum(reliability_values, Decimal("0")) / Decimal(len(reliability_values))
            if reliability_values
            else Decimal("1")
        ),
        "available_from": available_from.isoformat(),
        "available_through": available_through.isoformat(),
    }

def _rolling_model_document_error(model: Any) -> str | None:
    """Return a stable failure reason for one persisted model document."""
    if not isinstance(model, Mapping):
        return "MODEL_INPUT_MISSING"
    unknown = set(str(key) for key in model) - _ROLLING_MODEL_DOCUMENT_FIELDS
    if unknown:
        return "MODEL_PLAN_NOT_EXECUTABLE"
    if not any(key in model for key in _ROLLING_MODEL_DOCUMENT_FIELDS):
        return "MODEL_INPUT_MISSING"
    if "field" in model:
        field_name = model.get("field")
        if not isinstance(field_name, str) or not field_name.strip():
            return "MODEL_INPUT_INVALID"
    if "probability" in model or "yes_probability" in model:
        if evaluate_model_document_probability(model, {}) is None:
            return "MODEL_INPUT_INVALID"
    return None

def _rolling_model_document_hash(model: Mapping[str, Any]) -> str:
    try:
        return _content_hash(dict(model))
    except (TypeError, ValueError, OverflowError, RecursionError) as exc:
        raise ValueError("MODEL_PLAN_NOT_EXECUTABLE") from exc

def _rolling_model_resolution_record(
    source_type: str,
    model_hash: str,
    *,
    plan_id: str | None = None,
) -> dict[str, Any]:
    """Keep model provenance intentionally small and hash-addressable."""
    return {
        "source_type": str(source_type),
        "plan_id": plan_id,
        "model_hash": str(model_hash),
    }

def _rolling_model_authoritative_row(
    value: Any,
    *,
    verified_field: str | None = None,
) -> dict[str, Any]:
    """Strip unverified model aliases while preserving wrapped observations."""
    if not isinstance(value, Mapping):
        return {}
    wrappers = {
        "payload",
        "snapshot",
        "data",
        "observation",
        "result",
        "outcome",
    }
    result: dict[str, Any] = {}
    for key, child in value.items():
        normalized = str(key).strip().lower()
        if normalized in _ROLLING_MODEL_OVERRIDE_FIELDS:
            if verified_field is not None and str(key) == verified_field:
                result[key] = child
            continue
        if normalized in wrappers and isinstance(child, Mapping):
            result[key] = _rolling_model_authoritative_row(
                child,
                verified_field=verified_field,
            )
        else:
            # Order-book/market payloads are intentionally opaque here:
            # their ``p`` and ``probability`` fields are legitimate prices.
            result[key] = child
    return result

def _rolling_timestamp(value: Any) -> datetime | None:
    if isinstance(value, datetime):
        return ensure_utc(value)
    if value is None:
        return None
    try:
        return parse_timestamp(value)
    except (TypeError, ValueError, OverflowError):
        return None


def _rolling_hash(value: Any) -> str:
    return "sha256:" + hashlib.sha256(_canonical_binding(value).encode("utf-8")).hexdigest()
def _rolling_provenance_hash(value: Any) -> str:
    try:
        encoded = _canonical_binding(value)
    except (TypeError, ValueError, OverflowError, RecursionError):
        encoded = repr(value)
    return "sha256:" + hashlib.sha256(encoded.encode("utf-8", "replace")).hexdigest()


def _rolling_provenance_compact(value: Any, depth: int = 0) -> Any:
    if depth >= _ROLLING_MAX_PROVENANCE_DEPTH:
        return {
            "omitted": True,
            "reason": "DEPTH_LIMIT",
            "sha256": _rolling_provenance_hash(value),
        }
    if isinstance(value, Mapping):
        items = sorted(value.items(), key=lambda pair: str(pair[0]))
        result = {
            str(key): _rolling_provenance_compact(child, depth + 1)
            for key, child in items[:64]
        }
        if len(items) > 64:
            result["_omitted_fields"] = [
                str(key) for key, _ in items[64:128]
            ]
            result["_truncated"] = True
        return result
    if isinstance(value, (list, tuple)):
        result = [_rolling_provenance_compact(child, depth + 1) for child in value[:64]]
        if len(value) > 64:
            result.append(
                {
                    "omitted": True,
                    "reason": "ITEM_LIMIT",
                    "sha256": _rolling_provenance_hash(value[64:]),
                }
            )
        return result
    if isinstance(value, str):
        if len(value) <= 1024:
            return value
        return {
            "omitted": True,
            "reason": "STRING_LIMIT",
            "sha256": _rolling_provenance_hash(value),
            "preview": value[:256],
        }
    if isinstance(value, (int, float, bool)) or value is None:
        return value
    return str(value)[:1024]


def _rolling_provenance_bound(value: Mapping[str, Any]) -> dict[str, Any]:
    compacted = _rolling_provenance_compact(value)
    encoded = _canonical_binding(compacted)
    if len(encoded.encode("utf-8")) <= _ROLLING_MAX_PROVENANCE_BYTES:
        return dict(compacted) if isinstance(compacted, Mapping) else {"value": compacted}
    source_hash = _rolling_provenance_hash(value)
    output: dict[str, Any] = {
        "provenance_schema": "axiom-rolling-provenance-v1",
        "provenance_truncated": True,
        "provenance_sha256": source_hash,
        "provenance_original_bytes": len(encoded.encode("utf-8")),
        "provenance_omitted_fields": [],
    }
    priority = (
        "candidate_id",
        "rolling_research",
        "research_mode",
        "mode",
        "validation_version",
        "predecessor_enrollment_id",
        "predecessor_candidate_id",
        "source_candidate_id",
        "source_trial_id",
        "research_trial_id",
        "predecessor_strategy_id",
        "predecessor_strategy_version",
        "source_config_hash",
        "market_scope",
        "market_scope_hash",
        "market_scope_version",
        "scope",
        "dataset_selector",
        "dataset_id",
        "dataset_version",
        "predecessor_provenance",
        "original_rejection",
        "original_economic_outcome",
        "entry_policy",
        "exit_policy",
    )
    keys = list(compacted) if isinstance(compacted, Mapping) else []
    ordered_keys = list(dict.fromkeys([*priority, *sorted(keys)]))
    for key in ordered_keys:
        if key not in compacted:
            continue
        candidate = dict(output)
        candidate[key] = compacted[key]
        if len(_canonical_binding(candidate).encode("utf-8")) <= _ROLLING_MAX_PROVENANCE_BYTES:
            output[key] = compacted[key]
            continue
        output["provenance_omitted_fields"].append(str(key))
    if len(_canonical_binding(output).encode("utf-8")) > _ROLLING_MAX_PROVENANCE_BYTES:
        output["provenance_omitted_fields"] = output["provenance_omitted_fields"][:32]
    while len(_canonical_binding(output).encode("utf-8")) > _ROLLING_MAX_PROVENANCE_BYTES:
        removable = next(
            (
                key
                for key in reversed(list(output))
                if key not in {
                    "provenance_schema",
                    "provenance_truncated",
                    "provenance_sha256",
                    "provenance_original_bytes",
                }
            ),
            None,
        )
        if removable is None:
            break
        output.pop(removable, None)
    return output


def _rolling_state_ids(values: Iterable[Any]) -> list[str]:
    """Project identifiers for durable state without retaining the full lineage."""
    result: list[str] = []
    seen: set[str] = set()
    for value in values:
        identifier = str(value or "").strip()
        if not identifier:
            continue
        identifier = identifier[:_MAX_ROLLING_STATE_ID_LENGTH]
        if identifier in seen:
            continue
        seen.add(identifier)
        result.append(identifier)
        if len(result) >= _MAX_ROLLING_STATE_ITEMS:
            break
    return result


def _rolling_state_result(value: Any) -> dict[str, Any]:
    """Keep only compact, scalar evidence fields in restart-facing state."""
    if not isinstance(value, Mapping):
        return {"value": str(value)[:_MAX_ROLLING_STATE_ID_LENGTH]}
    result: dict[str, Any] = {}
    for key in _ROLLING_STATE_RESULT_KEYS:
        if key not in value:
            continue
        item = value[key]
        if key in {"requested_days", "admission_reasons"} and isinstance(item, (list, tuple)):
            result[key] = [
                int(day) if key == "requested_days" and isinstance(day, int) and not isinstance(day, bool)
                else str(day)[:_MAX_ROLLING_STATE_ID_LENGTH]
                for day in item[:16]
                if day is not None
            ]
        elif isinstance(item, (str, int, float, bool)) or item is None:
            result[key] = item if not isinstance(item, str) else item[:_MAX_ROLLING_STATE_ID_LENGTH]
        else:
            result[key] = str(item)[:_MAX_ROLLING_STATE_ID_LENGTH]
    return result


def _rolling_pending_state_result(value: Any) -> dict[str, Any]:
    """Project pending work to its first-class retry identity only.

    Pending records can carry per-attempt diagnostics and exception payloads.
    Those details belong in durable blocker records, not the bounded operator
    snapshot; retaining them would evict otherwise useful pending records.
    """
    projected = _rolling_state_result(value)
    if not isinstance(projected, Mapping):
        return {"value": str(projected)[:_MAX_ROLLING_STATE_ID_LENGTH]}
    result: dict[str, Any] = {}
    for key in (
        "strategy_version_id",
        "research_trial_id",
        "candidate_id",
        "source_class",
        "requested_days",
        "status",
        "reason",
        "next_job",
    ):
        if key not in projected:
            continue
        item = projected[key]
        if isinstance(item, str):
            # Identifiers may use the normal state bound; status/reason/job
            # text gets a smaller bound so diagnostics cannot evict records.
            limit = (
                _MAX_ROLLING_STATE_ID_LENGTH
                if key.endswith("_id")
                else 128
            )
            item = item[:limit]
        result[key] = item
    return result


def _rolling_work_key(
    strategy: Mapping[str, Any],
    requested_days: int,
    source_class: str,
) -> str:
    """Return the stable identity of one strategy/window/source attempt."""
    return _rolling_hash(
        {
            "strategy_version_id": strategy.get("strategy_version_id"),
            "research_trial_id": strategy.get("research_trial_id"),
            "candidate_id": strategy.get("candidate_id"),
            "requested_days": int(requested_days),
            "source_class": _rolling_source_name(source_class),
        }
    )


def _rolling_prerequisite_fingerprint(
    strategy: Mapping[str, Any],
    source_class: str,
    *,
    source_rows: Sequence[Mapping[str, Any]] = (),
    store: Any | None = None,
) -> str:
    """Fingerprint immutable inputs used to suppress unchanged blockers."""
    provenance = strategy.get("provenance")
    provenance = provenance if isinstance(provenance, Mapping) else {}
    binding = _rolling_source_binding(strategy)
    row_material = []
    for row in source_rows[:_MAX_ROLLING_SOURCE_ROWS]:
        if not isinstance(row, Mapping):
            continue
        view = _rolling_snapshot_view(row)
        row_material.append(
            {
                "identity": view.get(
                    "snapshot_id",
                    view.get("source_snapshot_id", view.get("observation_id")),
                ),
                "timestamp": _rolling_row_time(view),
                "lineage": {
                    name: view.get(name)
                    for name in (
                        "dataset_id",
                        "dataset_version",
                        "source_timestamp",
                        "strategy_hash",
                        "strategy_version_id",
                        "research_trial_id",
                        "candidate_id",
                    )
                },
                "source_digest": view.get("source_digest"),
                "accounting_digest": view.get("accounting_digest"),
                "accounting_available": view.get("accounting_available"),
                "accounting_complete": view.get("accounting_complete"),
                "accounting_partial": view.get("accounting_partial"),
                "requested_rows": view.get("requested_rows"),
                "available_rows": view.get("available_rows"),
                "row_digest": _rolling_hash(view),
            }
        )
    plan_id = None
    for owner in (strategy, provenance):
        for name in _ROLLING_MODEL_ID_FIELDS:
            plan_id = _binding_value(owner.get(name))
            if plan_id is not None:
                break
        if plan_id is not None:
            break
    if store is None:
        linked_plan = {"status": "STORE_UNAVAILABLE"}
    elif plan_id is None:
        linked_plan = {"status": "PLAN_ID_MISSING"}
    else:
        plan_loader = getattr(store, "load_experiment_plan", None)
        if not callable(plan_loader):
            linked_plan = {"status": "PLAN_LOADER_UNAVAILABLE"}
        else:
            try:
                loaded_plan = plan_loader(plan_id)
            except Exception as exc:
                linked_plan = {
                    "status": "LOAD_FAILED",
                    "error": type(exc).__name__,
                }
            else:
                if not isinstance(loaded_plan, Mapping):
                    linked_plan = {"status": "MISSING"}
                else:
                    plan_hashes = sorted(
                        {
                            normalized
                            for name in _ROLLING_PLAN_HASH_FIELDS
                            for normalized in [_binding_value(loaded_plan.get(name))]
                            if normalized is not None
                        }
                    )
                    hypothesis_ids = sorted(
                        {
                            normalized
                            for name in _ROLLING_MODEL_HYPOTHESIS_FIELDS
                            for normalized in [_binding_value(loaded_plan.get(name))]
                            if normalized is not None
                        }
                    )
                    linked_plan = {
                        "status": "PRESENT",
                        "plan_id": plan_id,
                        "plan_hashes": plan_hashes,
                        "hypothesis_ids": hypothesis_ids,
                    }
    return _rolling_hash(
        {
            "schema": "rolling-prerequisites-v1",
            "strategy_hash": strategy.get("strategy_hash"),
            "strategy_version_id": strategy.get("strategy_version_id"),
            "research_trial_id": strategy.get("research_trial_id"),
            "candidate_id": strategy.get("candidate_id"),
            "strategy_state": {
                name: strategy.get(name)
                for name in (
                    "strategy_document",
                    "model_document",
                    "model_hash",
                    "plan_id",
                    "plan_hash",
                    "hypothesis_id",
                    "config",
                    "paper_assumptions",
                    "materialized_experiment_id",
                    "observation_intent_id",
                )
                if strategy.get(name) is not None
            },
            "model_lineage": {
                name: provenance.get(name)
                for name in (
                    "plan_id",
                    "plan_hash",
                    "hypothesis_id",
                    "model_hash",
                    "source_trial_id",
                )
                if provenance.get(name) is not None
            },
            "linked_plan": linked_plan,
            "source_class": _rolling_source_name(source_class),
            "source_binding": binding,
            "source_bounds": {
                "from": min(
                    (
                        _rolling_row_time(row)
                        for row in source_rows
                        if isinstance(row, Mapping)
                        and _rolling_row_time(row) is not None
                    ),
                    default=None,
                ),
                "through": max(
                    (
                        _rolling_row_time(row)
                        for row in source_rows
                        if isinstance(row, Mapping)
                        and _rolling_row_time(row) is not None
                    ),
                    default=None,
                ),
            },
            "source_rows": row_material,
        }
    )


def _rolling_work_items(
    strategies: Sequence[Mapping[str, Any]],
) -> tuple[tuple[Mapping[str, Any], int, str], ...]:
    """Build stable candidate-order work for all 7/30-day source windows."""
    ordered = sorted(
        (item for item in strategies if isinstance(item, Mapping)),
        key=lambda item: (
            str(item.get("candidate_id", "")),
            str(item.get("strategy_version_id", "")),
            str(item.get("research_trial_id", "")),
        ),
    )
    return tuple(
        (strategy, days, source)
        for strategy in ordered
        for days in (7, 30)
        for source in ("HISTORICAL", "REPLAY", "PAPER", "LIVE")
    )


def _rolling_cursor_index(
    cursor: Mapping[str, Any] | None,
    work_items: Sequence[tuple[Mapping[str, Any], int, str]],
) -> int:
    if not work_items:
        return 0
    if not isinstance(cursor, Mapping):
        return 0
    next_key = {
        "strategy_version_id": cursor.get("next_strategy_version_id"),
        "research_trial_id": cursor.get("next_research_trial_id"),
        "candidate_id": cursor.get("next_candidate_id"),
        "requested_days": cursor.get("next_requested_days"),
        "source_class": _rolling_source_name(cursor.get("next_source_class")),
    }
    for index, (strategy, days, source) in enumerate(work_items):
        if (
            str(strategy.get("strategy_version_id", "")) == str(next_key["strategy_version_id"] or "")
            and str(strategy.get("research_trial_id", "")) == str(next_key["research_trial_id"] or "")
            and str(strategy.get("candidate_id", "")) == str(next_key["candidate_id"] or "")
            and int(days) == int(next_key["requested_days"] or 0)
            and source == next_key["source_class"]
        ):
            return index
    return 0


def _rolling_cursor_record(
    current: Mapping[str, Any] | None,
    item: tuple[Mapping[str, Any], int, str],
    next_item: tuple[Mapping[str, Any], int, str] | None,
    now: datetime,
) -> dict[str, Any]:
    strategy, days, source = item
    next_values = next_item or item
    next_strategy, next_days, next_source = next_values
    attempts = dict(current.get("attempts", {})) if isinstance(current, Mapping) else {}
    timestamps = dict(current.get("attempt_timestamps", {})) if isinstance(current, Mapping) else {}
    key = _rolling_work_key(strategy, days, source)
    attempts[key] = int(attempts.get(key, 0) or 0) + 1
    timestamps[key] = now.isoformat()
    return {
        "last_strategy_version_id": strategy.get("strategy_version_id"),
        "last_research_trial_id": strategy.get("research_trial_id"),
        "last_candidate_id": strategy.get("candidate_id"),
        "last_requested_days": days,
        "last_source_class": source,
        "next_strategy_version_id": next_strategy.get("strategy_version_id"),
        "next_research_trial_id": next_strategy.get("research_trial_id"),
        "next_candidate_id": next_strategy.get("candidate_id"),
        "next_requested_days": next_days,
        "next_source_class": next_source,
        "attempts": attempts,
        "attempt_timestamps": timestamps,
        "updated_at": now.isoformat(),
    }

def _rolling_enrolled_strategy_version_ids(
    store: Any,
    strategies: Sequence[Mapping[str, Any]],
) -> tuple[str, ...]:
    """Return every accepted strategy-version id, not a display sample."""
    fallback_ids: set[str] = {
        str(item.get("strategy_version_id", "")).strip()
        for item in strategies
        if isinstance(item, Mapping) and str(item.get("strategy_version_id", "")).strip()
    }
    identifiers: set[str] = set()
    authoritative = False
    connection = getattr(store, "connection", None)
    execute = getattr(connection, "execute", None)
    if callable(execute):
        try:
            rows = execute(
                "SELECT DISTINCT strategy_version_id "
                "FROM rolling_strategy_enrollments "
                "WHERE status='ACCEPTED' AND strategy_version_id IS NOT NULL "
                "AND TRIM(strategy_version_id) <> '' ORDER BY strategy_version_id"
            ).fetchall()
        except Exception:
            rows = None
        if rows is not None:
            authoritative = True
            for row in rows:
                try:
                    value = row[0]
                except (IndexError, KeyError, TypeError):
                    value = row.get("strategy_version_id") if isinstance(row, Mapping) else None
                value = str(value or "").strip()
                if value:
                    identifiers.add(value)
    lister = getattr(store, "list_rolling_enrollments", None)
    if callable(lister) and not authoritative:
        try:
            values = lister(status="ACCEPTED", limit=_MAX_ROLLING_DISCOVERY_SCAN)
        except (TypeError, ValueError, RuntimeError):
            values = None
        if values is not None:
            authoritative = True
            for item in values:
                if not isinstance(item, Mapping):
                    continue
                value = str(item.get("strategy_version_id", "")).strip()
                if value:
                    identifiers.add(value)
    # The strategy-document loader already returns validated rolling records.
    # If an in-memory/legacy store has no enrollment rows, retain those
    # validated document ids instead of turning a successful load into an
    # empty identity.
    return tuple(sorted(identifiers or fallback_ids))


def _rolling_refresh_identity(
    strategies: Sequence[Mapping[str, Any]],
    evidence_rows: Sequence[Mapping[str, Any]],
    pending: Sequence[Mapping[str, Any]],
    enrolled_strategy_version_ids: Sequence[str] | None = None,
) -> dict[str, Any]:
    """Build an exact, bounded identity for one rolling refresh.

    The operator payload intentionally keeps only samples of the refresh
    material.  The identity is computed from the complete bounded inputs
    before those samples are projected, so a restart can distinguish a real
    enrollment/evidence/shortage transition from the same daily state.
    Timestamps used only for scheduling are excluded from shortage identity.
    """

    def strategy_identity(item: Mapping[str, Any]) -> dict[str, Any]:
        return {
            "strategy_version_id": str(item.get("strategy_version_id", "")).strip(),
            "research_trial_id": str(item.get("research_trial_id", "")).strip() or None,
            "candidate_id": str(item.get("candidate_id", "")).strip() or None,
            "strategy_hash": str(item.get("strategy_hash", "")).strip() or None,
            "config_hash": str(item.get("config_hash", "")).strip() or None,
            "version": str(item.get("version", "")).strip() or None,
        }

    def evidence_identity(item: Mapping[str, Any]) -> dict[str, Any]:
        digest = str(item.get("evidence_digest", "")).strip()
        if not digest:
            digest = _rolling_hash(
                {
                    str(key): value
                    for key, value in item.items()
                    if str(key) not in {"created_at", "measured_at"}
                }
            )
        return {
            "strategy_version_id": str(item.get("strategy_version_id", "")).strip(),
            "research_trial_id": str(item.get("research_trial_id", "")).strip() or None,
            "candidate_id": str(item.get("candidate_id", "")).strip() or None,
            "evidence_window_id": str(item.get("evidence_window_id", "")).strip(),
            "source_class": str(item.get("source_class", "")).strip().upper(),
            "requested_days": item.get("requested_days"),
            "evidence_digest": digest,
        }

    def shortage_identity(item: Mapping[str, Any]) -> dict[str, Any]:
        # Queue scheduling timestamps are not evidence or shortage identity.
        # Keep every other field so changing a retry reason or its next work is
        # observed exactly rather than relying on a lossy sample projection.
        return {
            str(key): value
            for key, value in item.items()
            if str(key) not in {"available_at", "scheduled_at", "created_at"}
        }

    strategy_values = sorted(
        (strategy_identity(item) for item in strategies if isinstance(item, Mapping)),
        key=_canonical_binding,
    )
    evidence_values = sorted(
        (evidence_identity(item) for item in evidence_rows if isinstance(item, Mapping)),
        key=_canonical_binding,
    )
    shortage_values = sorted(
        (shortage_identity(item) for item in pending if isinstance(item, Mapping)),
        key=_canonical_binding,
    )
    enrolled_ids = tuple(
        sorted(
            {
                str(value).strip()
                for value in (
                    enrolled_strategy_version_ids
                    if enrolled_strategy_version_ids is not None
                    else (
                        item.get("strategy_version_id") for item in strategy_values
                    )
                )
                if str(value).strip()
            }
        )
    )
    strategy_digest = _rolling_hash(enrolled_ids)
    evidence_digest = _rolling_hash(evidence_values)
    shortage_digest = _rolling_hash(shortage_values)
    material = {
        "schema_version": "rolling-refresh-identity-v2",
        "strategy_version_ids": enrolled_ids,
        "evidence": evidence_values,
        "shortages": shortage_values,
    }
    return {
        "schema_version": material["schema_version"],
        "digest": _rolling_hash(material),
        "strategy_digest": strategy_digest,
        "enrolled_strategy_versions_digest": strategy_digest,
        "evidence_digest": evidence_digest,
        "shortage_digest": shortage_digest,
        "strategy_versions_total": len(enrolled_ids),
        "enrolled_strategy_versions_total": len(enrolled_ids),
        "research_trials_total": sum(
            1 for item in strategy_values if item.get("research_trial_id")
        ),
        "evidence_windows_total": len(evidence_values),
        "pending_total": len(shortage_values),
        "strategy_versions": list(enrolled_ids[:_MAX_ROLLING_STATE_ITEMS]),
        "research_trials": _rolling_state_ids(
            item.get("research_trial_id") for item in strategy_values
        ),
        "evidence_windows": _rolling_state_ids(
            item.get("evidence_window_id") for item in evidence_values
        ),
    }


def _rolling_prior_initialization_review(
    prior_state: Mapping[str, Any] | None,
    previous_selection: Mapping[str, Any] | None,
) -> bool:
    """Recognize a persisted no-definition review without guessing from emptiness."""

    records: tuple[Mapping[str, Any], ...] = tuple(
        item for item in (prior_state, previous_selection) if isinstance(item, Mapping)
    )
    for record in records:
        identity = record.get("refresh_identity")
        if isinstance(identity, Mapping):
            try:
                if int(identity.get("strategy_versions_total", -1)) == 0:
                    return True
            except (TypeError, ValueError):
                pass
        for raw_reason in record.get("reasons", ()):
            if str(raw_reason).strip().upper() == "NO_STRATEGY_DEFINITIONS":
                return True
        pending = record.get("pending", ())
        if isinstance(pending, (list, tuple)):
            if any(
                isinstance(item, Mapping)
                and str(item.get("reason", "")).strip().upper()
                == "NO_STRATEGY_DEFINITIONS"
                for item in pending
            ):
                return True
        history = record.get("event_history", ())
        if isinstance(history, (list, tuple)) and history:
            latest = history[-1]
            if isinstance(latest, Mapping):
                if str(latest.get("reason", "")).strip().upper() == "NO_STRATEGY_DEFINITIONS":
                    return True
                if any(
                    str(reason).strip().upper() == "NO_STRATEGY_DEFINITIONS"
                    for reason in latest.get("reasons", ())
                ):
                    return True
    return False


def _rolling_initialization_observe(
    decision: Any,
    refreshed: Mapping[str, Any],
) -> Any:
    """Turn an initialization transition into a paper-only OBSERVE outcome."""

    strategy_ids = {
        str(value).strip()
        for value in refreshed.get("strategy_versions", ())
        if str(value).strip()
    }
    pending_reasons: dict[str, list[str]] = {}
    pending = refreshed.get("pending", ())
    if isinstance(pending, (list, tuple)):
        for item in pending:
            if not isinstance(item, Mapping):
                continue
            strategy_id = str(item.get("strategy_version_id", "")).strip()
            reason = str(item.get("reason", "")).strip() or str(item.get("status", "")).strip()
            if strategy_id and reason:
                pending_reasons.setdefault(strategy_id, []).append(reason)
                strategy_ids.add(strategy_id)

    member_reasons: dict[str, str] = {}
    for member in decision.members:
        strategy_id = str(member.strategy_version_id).strip()
        if strategy_id:
            member_reasons[strategy_id] = (
                str(member.reason).strip() or "INITIALIZATION_OBSERVE"
            )

    reasons = ["INITIALIZATION_OBSERVE"]
    reasons.extend(str(reason) for reason in decision.reasons)
    for strategy_id in sorted(strategy_ids):
        shortage = pending_reasons.get(strategy_id)
        reason = (
            member_reasons.get(strategy_id)
            or (shortage[0] if shortage else None)
            or "INITIALIZATION_OBSERVE"
        )
        reasons.append(f"{strategy_id}:{reason}")
    return replace(
        decision,
        status="OBSERVE",
        members=(),
        reasons=tuple(dict.fromkeys(reasons)),
    )




def _rolling_state_payload(
    *,
    status: str,
    scheduled_at: str,
    queue_item_id: Any,
    queue_status: Any,
    strategies: Sequence[Mapping[str, Any]],
    evidence_rows: Sequence[Mapping[str, Any]],
    pending: Sequence[Mapping[str, Any]],
    source_classes: Sequence[str],
    requested_window_days: Sequence[int],
    source_rows_total: int,
    pending_total: int | None = None,
    enrolled_strategy_version_ids: Sequence[str] | None = None,
) -> dict[str, Any]:
    """Build a bounded operator-job payload for rolling refresh state."""
    enrolled_ids = tuple(
        sorted(
            {
                str(value).strip()
                for value in (
                    enrolled_strategy_version_ids
                    if enrolled_strategy_version_ids is not None
                    else (
                        item.get("strategy_version_id") for item in strategies
                    )
                )
                if str(value).strip()
            }
        )
    )
    strategy_total = len(enrolled_ids)
    evidence_total = len(evidence_rows)
    pending_count = len(pending)
    pending_total = max(pending_count, int(pending_total)) if pending_total is not None else pending_count
    candidate_values = [item.get("candidate_id") for item in strategies if item.get("candidate_id")]
    candidate_total = len(candidate_values)
    strategy_ids = list(enrolled_ids[:_MAX_ROLLING_STATE_ITEMS])
    trial_ids = _rolling_state_ids(item.get("research_trial_id") for item in strategies)
    candidate_ids = _rolling_state_ids(candidate_values)
    evidence_sample = [_rolling_state_result(item) for item in evidence_rows[:_MAX_ROLLING_STATE_ITEMS]]
    pending_sample = [
        _rolling_pending_state_result(item)
        for item in pending[:_MAX_ROLLING_STATE_ITEMS]
    ]
    truncated = {
        "strategy_versions": strategy_total > len(strategy_ids),
        "research_trials": strategy_total > len(trial_ids),
        "candidate_ids": candidate_total > len(candidate_ids),
        "evidence_windows": evidence_total > len(evidence_sample),
        "pending": pending_total > len(pending_sample),
        "source_rows": source_rows_total >= _MAX_ROLLING_TOTAL_ROWS,
    }
    refresh_identity = _rolling_refresh_identity(
        strategies,
        evidence_rows,
        pending,
        enrolled_strategy_version_ids=enrolled_ids,
    )
    state: dict[str, Any] = {
        "status": status,
        "scheduled_at": scheduled_at,
        "queue_item_id": str(queue_item_id or "")[:_MAX_ROLLING_STATE_ID_LENGTH],
        "queue_status": str(queue_status or "")[:_MAX_ROLLING_STATE_ID_LENGTH],
        "strategy_versions": strategy_ids,
        "strategy_versions_total": strategy_total,
        "strategy_versions_truncated": truncated["strategy_versions"],
        "research_trials": trial_ids,
        "research_trials_total": strategy_total,
        "research_trials_truncated": truncated["research_trials"],
        "candidate_ids": candidate_ids,
        "candidate_ids_total": candidate_total,
        "candidate_ids_truncated": truncated["candidate_ids"],
        "evidence_windows": evidence_sample,
        "evidence_windows_total": evidence_total,
        "evidence_windows_truncated": truncated["evidence_windows"],
        "evidence_window_count": evidence_total,
        "pending": pending_sample,
        "next_jobs": sorted(
            {
                "rolling-research-evidence",
                *(
                    str(item.get("next_job")).strip()
                    for item in pending
                    if str(item.get("next_job", "")).strip()
                ),
            }
        ),
        "pending_total": pending_total,
        "pending_truncated": truncated["pending"],
        "source_rows_total": source_rows_total,
        "source_rows_truncated": truncated["source_rows"],
        "source_classes": list(source_classes),
        "requested_window_days": list(requested_window_days),
        "paper_only": True,
        "truncated": any(truncated.values()),
        "refresh_identity": refresh_identity,
        "rolling_review_identity": str(refresh_identity["digest"]),
    }
    while len(_canonical_binding(state).encode("utf-8")) > _MAX_ROLLING_STATE_PAYLOAD_BYTES:
        removable = next(
            (
                name
                for name in ("pending", "evidence_windows", "research_trials")
                if state[name]
            ),
            None,
        )
        if removable is None:
            break
        state[removable].pop()
        state[f"{removable}_truncated"] = True
        state["truncated"] = True
    return state




def _rolling_bound_cursor_state(cursor: Mapping[str, Any]) -> dict[str, Any]:
    """Project durable cursor telemetry without copying unbounded attempt maps."""
    bounded = dict(cursor)
    for name in ("attempts", "attempt_timestamps"):
        values = bounded.get(name)
        if not isinstance(values, Mapping):
            continue
        ordered = list(values.items())
        bounded[f"{name}_total"] = len(ordered)
        if len(ordered) > _MAX_ROLLING_STATE_ITEMS:
            bounded[name] = dict(ordered[-_MAX_ROLLING_STATE_ITEMS:])
            bounded[f"{name}_truncated"] = True
        else:
            bounded[name] = dict(ordered)
    return bounded


def _rolling_bound_operator_state(state: Mapping[str, Any]) -> dict[str, Any]:
    """Keep operator state within Hermes' byte limit without losing identity.

    ``strategy_versions`` and ``candidate_ids`` are the restart identity
    samples.  They are normalized once, kept in deterministic first-seen order,
    and never cardinality-reduced.  Everything else is telemetry or retry
    detail and may be collapsed to its authoritative total/truncated marker.
    """
    bounded = dict(state)
    protected = {"strategy_versions", "candidate_ids"}

    def values_as_list(value: Any) -> list[Any] | None:
        if isinstance(value, (list, tuple)):
            return list(value)
        if isinstance(value, (set, frozenset)):
            return sorted(value, key=str)
        return None

    def mark_truncated(name: str, total: int | None = None) -> None:
        if total is not None and f"{name}_total" not in bounded:
            bounded[f"{name}_total"] = total
        bounded[f"{name}_truncated"] = True
        bounded["truncated"] = True

    def compact_identity(name: str) -> None:
        values = values_as_list(bounded.get(name))
        if values is None:
            return
        bounded[name] = _rolling_state_ids(values)
        if len(values) > len(bounded[name]):
            mark_truncated(name, len(values))

    # These two fields are protected for the entire compaction pass.
    compact_identity("strategy_versions")
    compact_identity("candidate_ids")

    pending_values = values_as_list(bounded.get("pending"))
    if pending_values is not None:
        bounded["pending"] = [
            _rolling_pending_state_result(item)
            for item in pending_values[:_MAX_ROLLING_STATE_ITEMS]
        ]
        if "pending_total" not in bounded:
            bounded["pending_total"] = len(pending_values)
        if len(pending_values) > len(bounded["pending"]):
            mark_truncated("pending")

    # Refresh identity keeps exact digests/totals authoritative.  Its arrays
    # duplicate operator samples and are therefore disposable telemetry.
    identity = bounded.get("refresh_identity")
    if isinstance(identity, Mapping):
        compact_identity_payload = dict(identity)
        for name in ("strategy_versions", "research_trials", "evidence_windows"):
            values = values_as_list(compact_identity_payload.get(name))
            if values is not None:
                compact_identity_payload[name] = _rolling_state_ids(values)
        bounded["refresh_identity"] = compact_identity_payload

    def collapse_collection(name: str) -> bool:
        value = bounded.get(name)
        values = values_as_list(value)
        if values is not None and values:
            bounded[name] = []
            mark_truncated(name, len(values))
            return True
        if isinstance(value, Mapping) and value:
            bounded[name] = {}
            mark_truncated(name, len(value))
            return True
        return False

    def drop_detail(name: str) -> bool:
        if name not in bounded:
            return False
        value = bounded.pop(name)
        if isinstance(value, (Mapping, list, tuple, set, frozenset)):
            mark_truncated(name, len(value))
        else:
            bounded["truncated"] = True
        return True

    def drop_cursor_detail() -> bool:
        cursor = bounded.get("rolling_cursor")
        if not isinstance(cursor, Mapping):
            return False
        compact_cursor = dict(cursor)
        for name in (
            "attempts",
            "attempt_timestamps",
            "errors",
            "error",
            "samples",
            "cursor_samples",
            "history",
            "events",
            "details",
            "diagnostics",
        ):
            if name not in compact_cursor:
                continue
            value = compact_cursor.pop(name)
            if isinstance(value, (Mapping, list, tuple, set, frozenset)):
                compact_cursor[f"{name}_total"] = len(value)
            compact_cursor[f"{name}_truncated"] = True
            bounded["rolling_cursor"] = compact_cursor
            bounded["rolling_cursor_truncated"] = True
            bounded["truncated"] = True
            return True
        return False

    def compact_cursor() -> bool:
        cursor = bounded.get("rolling_cursor")
        if not isinstance(cursor, Mapping):
            return False
        allowed_prefixes = ("last_", "next_")
        compact_cursor_payload = {
            key: value
            for key, value in cursor.items()
            if key.startswith(allowed_prefixes)
            or key in {"updated_at"}
            or key.endswith("_total")
            or key.endswith("_truncated")
        }
        if compact_cursor_payload == dict(cursor):
            return False
        bounded["rolling_cursor"] = compact_cursor_payload
        bounded["rolling_cursor_truncated"] = True
        bounded["truncated"] = True
        return True

    # Removal priority deliberately keeps identity samples last: attempt/error
    # maps, blocker diagnostics, cursor samples, and verbose state go first.
    detail_fields = (
        "attempts",
        "attempt_timestamps",
        "errors",
        "error",
        "error_details",
        "blocker",
        "blocker_detail",
        "blocker_details",
        "cursor_samples",
        "samples",
        "diagnostics",
        "verbose",
        "details",
        "trace",
        "logs",
        "event_history",
        "measured_counters",
    )
    identity_sample_fields = ("strategy_versions", "research_trials", "evidence_windows")
    optional_collections = (
        "terminal_blockers",
        "blocker_records",
        "evidence_windows",
        "research_trials",
        "next_jobs",
        "source_classes",
        "requested_window_days",
        "pending",
    )
    pending_text_fields = ("reason", "next_job", "status", "source_class")
    identity_lengths = (64, 32, 16, 8, 4, 1)

    while len(_canonical_binding(bounded).encode("utf-8")) > _MAX_ROLLING_HERMES_PAYLOAD_BYTES:
        changed = drop_cursor_detail()
        if changed:
            continue
        changed = any(drop_detail(name) for name in detail_fields)
        if changed:
            continue

        identity = bounded.get("refresh_identity")
        if isinstance(identity, Mapping):
            compact_identity_payload = dict(identity)
            removed = False
            for name in identity_sample_fields:
                if name in compact_identity_payload:
                    compact_identity_payload.pop(name)
                    removed = True
                    break
            if removed:
                bounded["refresh_identity"] = compact_identity_payload
                bounded["truncated"] = True
                continue

        changed = any(collapse_collection(name) for name in optional_collections)
        if changed:
            continue
        changed = compact_cursor()
        if changed:
            continue

        pending = bounded.get("pending")
        if isinstance(pending, list):
            stripped = False
            for field_name in pending_text_fields:
                if any(isinstance(item, Mapping) and field_name in item for item in pending):
                    for item in pending:
                        if isinstance(item, dict):
                            item.pop(field_name, None)
                    stripped = True
                    break
            if stripped:
                bounded["truncated"] = True
                continue

        # Remove or collapse any unrecognized optional field before touching
        # the protected identity arrays.  Canonical total/truncated counters
        # remain, so cardinality is still observable after this reduction.
        fallback_names = sorted(
            name
            for name, value in bounded.items()
            if name not in protected
            and not name.endswith("_total")
            and not name.endswith("_truncated")
            and name not in {"truncated", "rolling_review_identity"}
            and isinstance(value, (Mapping, list, tuple, set, frozenset, str))
        )
        changed = False
        for name in fallback_names:
            value = bounded.get(name)
            if isinstance(value, (Mapping, list, tuple, set, frozenset)):
                changed = collapse_collection(name)
            elif isinstance(value, str) and len(value) > 64:
                bounded[name] = value[:64]
                bounded["truncated"] = True
                changed = True
            if changed:
                break
        if changed:
            continue

        # Preserve all identity records, shortening only their display strings
        # as a final pathological-size fallback.  The sample cardinality and
        # order remain unchanged.
        shortened = False
        for limit in identity_lengths:
            for name in ("strategy_versions", "candidate_ids"):
                values = bounded.get(name)
                if not isinstance(values, list):
                    continue
                compact_values = [
                    (value[:limit] if isinstance(value, str) else str(value)[:limit])
                    for value in values
                ]
                if compact_values != values:
                    bounded[name] = compact_values
                    shortened = True
            if shortened:
                break
        if shortened:
            bounded["truncated"] = True
            continue

        # Keep the protected samples, exact totals, and identity digests even
        # when an unknown scalar is pathological.  This final projection is
        # deterministic and makes the byte bound an invariant, not a best
        # effort.
        compact_state = {
            name: value
            for name, value in bounded.items()
            if name in protected
            or name.endswith("_total")
            or name.endswith("_truncated")
            or name in {"truncated", "rolling_review_identity"}
        }
        bounded = compact_state
        break

    return bounded


def _rolling_unique_ids(values: Iterable[Any], *, limit: int = _MAX_ROLLING_HERMES_IDS) -> list[str]:
    """Return deterministic, bounded identifiers for one Hermes request field."""
    result: list[str] = []
    seen: set[str] = set()
    for value in values:
        identifier = str(value or "").strip()
        if (
            not identifier
            or len(identifier) > _MAX_ROLLING_HERMES_ID_LENGTH
            or identifier in seen
        ):
            continue
        seen.add(identifier)
        result.append(identifier)
        if len(result) >= limit:
            break
    return result


def _rolling_hermes_payload(
    strategies: Sequence[Mapping[str, Any]],
    sources: Sequence[str],
    current: datetime,
) -> dict[str, Any]:
    """Build a deduplicated rolling request below ResearchBus's byte limit."""
    payload: dict[str, Any] = {
        "rolling_research": True,
        "strategy_version_ids": _rolling_unique_ids(
            item.get("strategy_version_id") for item in strategies
        ),
        "research_trial_ids": _rolling_unique_ids(
            item.get("research_trial_id") for item in strategies
        ),
        "candidate_ids": _rolling_unique_ids(
            item.get("candidate_id") for item in strategies if item.get("candidate_id")
        ),
        "source_classes": list(sources),
        "requested_window_days": [7, 30],
        "paper_only": True,
    }
    while len(_canonical_binding(payload).encode("utf-8")) >= _MAX_ROLLING_HERMES_PAYLOAD_BYTES:
        fields = [field for field in _ROLLING_HERMES_ID_FIELDS if payload[field]]
        if not fields:
            # The fixed metadata above is intentionally tiny; this fallback
            # keeps the byte-bound invariant true even for pathological input.
            payload = {
                "rolling_research": True,
                "source_classes": list(sources),
                "requested_window_days": [7, 30],
                "paper_only": True,
            }
            break
        field = max(fields, key=lambda name: (len(payload[name]), name))
        payload[field].pop()
    return payload




def _rolling_row_time(row: Mapping[str, Any]) -> datetime | None:
    # Source/observation timestamps are an ordered canonical projection.  Once
    # an upstream source explicitly supplies one, malformed data must not be
    # hidden by falling back to a less authoritative field.
    for key in ("source_timestamp", "timestamp", "observed_at", "event_timestamp", "resolved_at", "time", "created_at"):
        if key in row:
            return _rolling_timestamp(row.get(key))
    return None


def _rolling_window_rows(
    rows: Sequence[Mapping[str, Any]],
    days: int,
    current: datetime,
) -> tuple[list[Mapping[str, Any]], tuple[str, ...]]:
    """Select only rows observed in the requested current-time window."""
    start = ensure_utc(current) - timedelta(days=days)
    through = ensure_utc(current)
    selected: list[Mapping[str, Any]] = []
    rejected: set[str] = set()
    for row in rows:
        if not isinstance(row, Mapping):
            rejected.add("SOURCE_TIMESTAMP_UNPARSEABLE")
            continue
        stamp = _rolling_row_time(row)
        if stamp is None:
            rejected.add("SOURCE_TIMESTAMP_UNPARSEABLE")
        elif stamp > through:
            rejected.add("SOURCE_TIMESTAMP_FUTURE")
        elif stamp >= start:
            selected.append(row)
    return selected, tuple(sorted(rejected))


def _rolling_source_name(value: Any) -> str:
    text = str(value or "").strip().upper().replace("-", "_").replace(" ", "_")
    aliases = {
        "FORWARD_COLLECTED": "LIVE",
        "ORDER_BOOK_SIMULATED": "REPLAY",
        "REPLAY_SIMULATED": "REPLAY",
        "PRICE_PROXY": "HISTORICAL",
        "PAPER_FORWARD": "PAPER",
        "FORWARD_PAPER": "PAPER",
    }
    return aliases.get(text, text or "HISTORICAL")


_ROLLING_PERSISTED_SOURCE_CLASSES: Mapping[str, str] = {
    "HISTORICAL": "HISTORICAL",
    # Storage's persisted source taxonomy uses FORWARD_COLLECTED for the
    # immutable recorded-book catalog; REPLAY remains the requested class in
    # operator/work-item state and input manifests.
    "REPLAY": "FORWARD_COLLECTED",
    "PAPER": "PAPER",
    "LIVE": "FORWARD_COLLECTED",
}
_ROLLING_REPLAY_DATASET_ID = "Polymarket-recorded-book-replay"
_ROLLING_REPLAY_MAX_CATALOGS = _MAX_ROLLING_REPLAY_CATALOGS
_ROLLING_INPUT_MANIFEST_MARKETS = 128
_ROLLING_INPUT_MANIFEST_ROWS = 25_000


def _rolling_book_mapping(row: Mapping[str, Any], side: str) -> Mapping[str, Any] | None:
    """Return one side of a recorded book without interpreting depth levels."""
    view = _rolling_snapshot_view(row)
    names = (
        ("yes_order_book", "order_book", "book_yes")
        if side == "yes"
        else ("no_order_book", "book_no")
    )
    for name in names:
        value = view.get(name)
        if isinstance(value, Mapping):
            if name == "order_book":
                for nested_name in (
                    side,
                    side.upper(),
                    f"{side}_order_book",
                    f"{side.upper()}_ORDER_BOOK",
                ):
                    nested = value.get(nested_name)
                    if isinstance(nested, Mapping):
                        return nested
                if side == "yes":
                    return value
            else:
                return value
    books = view.get("order_books", view.get("books"))
    if isinstance(books, Mapping):
        for name in (side, side.upper(), f"{side}_order_book"):
            value = books.get(name)
            if isinstance(value, Mapping):
                return value
    return None


def _rolling_book_timestamp(book: Mapping[str, Any]) -> datetime | None:
    for name in ("source_timestamp", "timestamp", "provider_timestamp", "observed_at"):
        if name in book:
            return _rolling_timestamp(book.get(name))
    return None


def _rolling_has_paired_timestamped_books(row: Mapping[str, Any]) -> bool:
    """Require timestamped YES and NO mappings, but not executable levels."""
    yes = _rolling_book_mapping(row, "yes")
    no = _rolling_book_mapping(row, "no")
    return (
        yes is not None
        and no is not None
        and _rolling_book_timestamp(yes) is not None
        and _rolling_book_timestamp(no) is not None
    )


def _rolling_replay_row_terminal(row: Mapping[str, Any]) -> bool:
    view = _rolling_snapshot_view(row)
    terminal_values = {
        "RESOLVED_YES",
        "RESOLVED_NO",
        "VOID",
        "RESOLVED",
        "CLOSED",
        "FINAL",
        "COMPLETED",
        "SETTLED",
        "EXPIRED",
        "CANCELLED",
        "CANCELED",
    }
    for name in ("settlement", "resolution", "status"):
        value = str(view.get(name, "")).strip().upper().replace("-", "_")
        if value in terminal_values:
            return True
    return any(view.get(name) is True for name in ("closed", "terminal", "is_terminal"))


def _rolling_publisher_source_record_hash(record: Mapping[str, Any]) -> str:
    payload = record.get("payload")
    if not isinstance(payload, Mapping):
        raise ValueError("source snapshot payload is missing")
    snapshot_id = str(record.get("snapshot_id", "")).strip()
    market_id = str(record.get("market_id", "")).strip()
    source_timestamp = record.get("source_timestamp")
    observed_at = record.get("observed_at")
    if (
        not snapshot_id
        or not market_id
        or _rolling_timestamp(source_timestamp) is None
        or _rolling_timestamp(observed_at) is None
    ):
        raise ValueError("source snapshot identity is incomplete")
    return _rolling_hash(
        {
            "snapshot_id": snapshot_id,
            "market_id": market_id,
            "source_timestamp": source_timestamp,
            "observed_at": observed_at,
            "payload": payload,
        }
    )

def _rolling_market_scope_ids(binding: Mapping[str, Any]) -> set[str]:
    scope = binding.get("market_scope", binding.get("scope"))
    if isinstance(scope, Mapping):
        values = scope.get("market_ids", scope.get("markets", ()))
    else:
        values = binding.get("market_ids", binding.get("market_id", ()))
    if isinstance(values, str):
        values = (values,)
    return {
        str(value).strip()
        for value in (values or ())
        if str(value).strip()
    }


def _rolling_input_manifest(
    rows: Sequence[Mapping[str, Any]],
    *,
    source: str,
    dataset_id: str | None = None,
    dataset_version: str | None = None,
) -> dict[str, Any]:
    """Build bounded deterministic coverage/gap evidence for selected rows."""
    market_rows: dict[str, list[Mapping[str, Any]]] = {}
    exclusions: dict[str, int] = {}
    for row in rows[:_ROLLING_INPUT_MANIFEST_ROWS]:
        if not isinstance(row, Mapping):
            exclusions["NON_MAPPING"] = exclusions.get("NON_MAPPING", 0) + 1
            continue
        view = _rolling_snapshot_view(row)
        market_id = str(view.get("market_id", "")).strip() or "<missing>"
        market_rows.setdefault(market_id, []).append(row)
        reason = row.get("_rolling_source_rejection") or row.get(
            "_rolling_accounting_rejection"
        )
        if reason:
            key = str(reason)
            exclusions[key] = exclusions.get(key, 0) + 1
    paths: list[dict[str, Any]] = []
    total_gaps = 0
    max_gap = 0
    for market_id in sorted(market_rows)[:_ROLLING_INPUT_MANIFEST_MARKETS]:
        values = market_rows[market_id]
        stamps = sorted(
            stamp
            for stamp in (
                _rolling_row_time(_rolling_snapshot_view(row)) for row in values
            )
            if stamp is not None
        )
        market_gaps = 0
        for row in values:
            if (
                source == "REPLAY"
                and not _rolling_replay_row_terminal(row)
                and not _rolling_has_paired_timestamped_books(row)
            ):
                market_gaps += 1
        gaps = [
            int((right - left).total_seconds())
            for left, right in zip(stamps, stamps[1:])
            if right >= left
        ]
        path_max_gap = max(gaps, default=0)
        total_gaps += market_gaps
        max_gap = max(max_gap, path_max_gap)
        paths.append(
            {
                "market_id": market_id,
                "first_timestamp": stamps[0].isoformat() if stamps else None,
                "last_timestamp": stamps[-1].isoformat() if stamps else None,
                "rows": len(values),
                "gap_count": market_gaps,
                "max_gap_seconds": path_max_gap,
            }
        )
    valid_count = sum(
        1
        for row in rows
        if isinstance(row, Mapping)
        and not row.get("_rolling_source_rejection")
        and not row.get("_rolling_accounting_rejection")
        and _rolling_row_time(_rolling_snapshot_view(row)) is not None
    )
    row_count = len(rows)
    return {
        "dataset_id": dataset_id,
        "dataset_version": dataset_version,
        "mode": (
            "RECORDED_BOOK_REPLAY"
            if source == "REPLAY"
            else "PRICE_PROXY_RESEARCH"
            if source == "HISTORICAL"
            else str(source)
        ),
        "source_class": source,
        "market_paths": paths,
        "first_timestamp": (
            min(
                (
                    _rolling_row_time(_rolling_snapshot_view(row))
                    for row in rows
                    if isinstance(row, Mapping)
                    and _rolling_row_time(_rolling_snapshot_view(row)) is not None
                ),
                default=None,
            ).isoformat()
            if any(
                isinstance(row, Mapping)
                and _rolling_row_time(_rolling_snapshot_view(row)) is not None
                for row in rows
            )
            else None
        ),
        "last_timestamp": (
            max(
                (
                    _rolling_row_time(_rolling_snapshot_view(row))
                    for row in rows
                    if isinstance(row, Mapping)
                    and _rolling_row_time(_rolling_snapshot_view(row)) is not None
                ),
                default=None,
            ).isoformat()
            if any(
                isinstance(row, Mapping)
                and _rolling_row_time(_rolling_snapshot_view(row)) is not None
                for row in rows
            )
            else None
        ),
        "rows": row_count,
        "valid_rows": valid_count,
        "gap_count": total_gaps,
        "max_gap_seconds": max_gap,
        "exclusion_counts": dict(sorted(exclusions.items())),
        "blocker_counts": dict(sorted(exclusions.items())),
        "completeness": (
            str(Decimal(valid_count) / Decimal(row_count))
            if row_count
            else "0"
        ),
        "partial": bool(valid_count != row_count or total_gaps),
        "truncated": len(rows) > _ROLLING_INPUT_MANIFEST_ROWS,
    }


def _rolling_persisted_source_class(value: Any) -> str:
    """Map a requested rolling source to the storage source class."""
    source = _rolling_source_name(value)
    return _ROLLING_PERSISTED_SOURCE_CLASSES.get(source, source)


_ROLLING_SOURCE_TYPES: Mapping[str, frozenset[str]] = {
    "HISTORICAL": frozenset({"HISTORICAL", "PRICE_PROXY"}),
    "REPLAY": frozenset(
        {"REPLAY", "REPLAY_SIMULATED", "ORDER_BOOK_SIMULATED", "FORWARD_COLLECTED"}
    ),
    "PAPER": frozenset({"PAPER", "PAPER_FORWARD", "FORWARD_PAPER"}),
    "LIVE": frozenset({"LIVE", "FORWARD_COLLECTED"}),
}
_ROLLING_SOURCE_QUERY_TYPES: Mapping[str, tuple[str, ...]] = {
    # Storage persists only forward snapshots.  REPLAY is loaded from its
    # immutable catalog below, never from the historical snapshot table.
    "LIVE": ("FORWARD_COLLECTED",),
}




def _rolling_source_binding(record: Mapping[str, Any]) -> dict[str, Any]:
    """Extract one exact selector/scope binding and reject contradictions."""
    containers: list[Mapping[str, Any]] = [record]
    for name in (
        "payload",
        "provenance",
        "strategy_document",
        "strategy",
        "accounting",
        "canonical_accounting",
        "strategy_accounting",
        "resolved_bet",
        "experiment_plan",
        "plan",
        "forward_config",
        "config",
    ):
        child = record.get(name)
        if isinstance(child, Mapping):
            containers.append(child)
            nested_provenance = child.get("provenance")
            if isinstance(nested_provenance, Mapping):
                containers.append(nested_provenance)
    selectors: list[Mapping[str, Any]] = []
    for container in containers:
        raw = container.get("dataset_selector")
        if isinstance(raw, Mapping):
            selectors.append(raw)
    fields = (
        "dataset_id",
        "dataset_version",
        "version",
        "plan_id",
        "plan_hash",
        "dataset_attestation",
        "dataset_boundary",
        "operational_setup",
        "operational_setup_hash",
        "predecessor_operational_setup_hash",
        "market_scope",
        "market_scope_hash",
        "market_scope_version",
        "scope",
        "scope_hash",
        "scope_version",
        "market_id",
        "market_ids",
        "candidate_id",
        "research_trial_id",
        "trial_id",
        "strategy_hash",
        "source_strategy_hash",
        "rolling_strategy_hash",
        "strategy_version_id",
        "experiment_id",
    )
    binding: dict[str, Any] = {}
    direct_fields = set(fields)
    for field in fields:
        values: list[Any] = []
        for selector in selectors:
            value = selector.get(field)
            if value is not None and value != "":
                values.append(value)
        for container in containers:
            if field in direct_fields:
                # Dataset aliases are read from dataset_selector above.  A
                # nested strategy document's DSL ``version`` is not a
                # dataset version.
                if field == "version" and (
                    container is not record
                    or "strategy_version_id" in container
                    or "strategy_hash" in container
                ):
                    continue
                value = container.get(field)
                if value is not None and value != "":
                    values.append(value)
        distinct = {_canonical_binding(value) for value in values}
        if len(distinct) > 1:
            raise ValueError(f"conflicting rolling dataset/scope selector: {field}")
        if values:
            binding[field] = values[0]
    if "trial_id" in binding:
        if (
            "research_trial_id" in binding
            and _canonical_binding(binding["research_trial_id"])
            != _canonical_binding(binding["trial_id"])
        ):
            raise ValueError("conflicting rolling dataset/scope selector: research_trial_id")
        binding.setdefault("research_trial_id", binding["trial_id"])
    return binding
def _rolling_dataset_identity(record: Mapping[str, Any]) -> tuple[Any, Any]:
    """Require one dataset id/version across every persisted authority."""
    containers: list[Mapping[str, Any]] = [record]
    for name in (
        "payload",
        "provenance",
        "experiment_plan",
        "plan",
        "forward_config",
        "config",
    ):
        value = record.get(name)
        if isinstance(value, Mapping):
            containers.append(value)
            nested = value.get("provenance")
            if isinstance(nested, Mapping):
                containers.append(nested)
    values: dict[str, list[Any]] = {"dataset_id": [], "dataset_version": []}

    def add(field: str, value: Any) -> None:
        if value not in (None, ""):
            values[field].append(value)

    for container in containers:
        add("dataset_id", container.get("dataset_id"))
        add("dataset_version", container.get("dataset_version"))
        selector = container.get("dataset_selector")
        if isinstance(selector, Mapping):
            add("dataset_id", selector.get("dataset_id"))
            add(
                "dataset_version",
                selector.get("dataset_version", selector.get("version")),
            )
        for name in ("dataset_boundary", "dataset_attestation"):
            binding = container.get(name)
            if isinstance(binding, Mapping):
                add("dataset_id", binding.get("dataset_id"))
                add(
                    "dataset_version",
                    binding.get("dataset_version", binding.get("version")),
                )
    result: list[Any] = []
    for field in ("dataset_id", "dataset_version"):
        distinct = {_canonical_binding(value) for value in values[field]}
        if len(distinct) > 1:
            raise ValueError(f"conflicting rolling dataset identity: {field}")
        result.append(values[field][0] if values[field] else None)
    return result[0], result[1]



def _rolling_binding_shape_is_valid(value: Any) -> bool:
    """Reject structured/non-finite identity values at source boundaries."""
    if value is None or value == "":
        return True
    if isinstance(value, (Mapping, list, tuple, set, frozenset)):
        return False
    if isinstance(value, float) and not math.isfinite(value):
        return False
    return isinstance(value, (str, int, float, bool))


_ROLLING_SOURCE_BINDING_FIELDS = (
    "dataset_id",
    "dataset_version",
    "version",
    "strategy_hash",
    "strategy_version_id",
    "research_trial_id",
    "candidate_id",
)


def _rolling_source_job_binding(
    record: Mapping[str, Any],
    source: str,
    *,
    experiment_id: str | None = None,
) -> dict[str, Any]:
    """Require the immutable identity carried by a standard source loader."""
    binding = _rolling_source_binding(record)
    expected: dict[str, Any] = {}
    for field in ("strategy_hash", "strategy_version_id", "research_trial_id", "candidate_id"):
        value = _binding_value(binding.get(field))
        if value is None:
            value = _binding_value(record.get(field))
        if value is None:
            raise ValueError(f"{source}_SOURCE_BINDING_REQUIRED")
        expected[field] = value
    if source == "HISTORICAL":
        dataset_id = _binding_value(binding.get("dataset_id"))
        dataset_version = _binding_value(binding.get("dataset_version", binding.get("version")))
        if dataset_id is None or dataset_version is None:
            raise ValueError(f"{source}_DATASET_BINDING_REQUIRED")
        expected["dataset_id"] = dataset_id
        expected["dataset_version"] = dataset_version
    if experiment_id is not None:
        expected["experiment_id"] = experiment_id
    return expected


def _rolling_inject_source_binding(
    raw: Mapping[str, Any],
    expected: Mapping[str, Any],
) -> dict[str, Any]:
    """Inject absent row duplicates while rejecting contradictory lineage."""
    row = dict(raw)
    try:
        current = _rolling_source_binding(row)
    except (TypeError, ValueError):
        row["_rolling_accounting_rejection"] = "SOURCE_BINDING_CONFLICT"
        return row
    for field in _ROLLING_SOURCE_BINDING_FIELDS:
        expected_value = _binding_value(expected.get(field))
        if expected_value is None:
            continue
        actual_value = _binding_value(current.get(field))
        if actual_value is not None and actual_value != expected_value:
            row["_rolling_accounting_rejection"] = "SOURCE_BINDING_CONFLICT"
            return row
        row.setdefault(field, expected_value)
    expected_experiment = _binding_value(expected.get("experiment_id"))
    if expected_experiment is not None:
        actual_experiment = _binding_value(current.get("experiment_id"))
        if actual_experiment is not None and actual_experiment != expected_experiment:
            row["_rolling_accounting_rejection"] = "PAPER_EXPERIMENT_BINDING_CONFLICT"
            return row
        row.setdefault("experiment_id", expected_experiment)
    return row
def _rolling_nested_paper_identity_conflict(
    value: Mapping[str, Any],
    *,
    strategy_hashes: set[str],
    expected: Mapping[str, Any],
) -> str | None:
    """Reject foreign nested identity before flattening a paper ledger row.

    Every mapping/list value is traversed, not just known payload keys.  The
    traversal is deliberately bounded: a cycle is harmless, but an oversized
    or too-deep payload is unproven and therefore rejected rather than skipped.
    """
    aliases: tuple[tuple[str, tuple[str, ...], set[str]], ...] = (
        (
            "strategy_hash",
            ("strategy_hash", "strategy_id", "rolling_strategy_hash"),
            strategy_hashes,
        ),
        (
            "source_strategy_hash",
            ("source_strategy_hash",),
            {_binding_value(expected.get("source_strategy_hash")) or ""},
        ),
        (
            "strategy_version_id",
            ("strategy_version_id",),
            {_binding_value(expected.get("strategy_version_id")) or ""},
        ),
        (
            "research_trial_id",
            ("research_trial_id", "trial_id"),
            {_binding_value(expected.get("research_trial_id")) or ""},
        ),
        (
            "candidate_id",
            ("candidate_id",),
            {_binding_value(expected.get("candidate_id")) or ""},
        ),
        (
            "experiment_id",
            ("experiment_id", "paper_experiment_id"),
            {_binding_value(expected.get("experiment_id")) or ""},
        ),
    )
    values: dict[str, set[str]] = {name: set() for name, _keys, _allowed in aliases}
    visited: set[int] = set()
    node_count = 0
    unproven = False

    def visit(item: Any, depth: int = 0) -> None:
        nonlocal node_count, unproven
        if not isinstance(item, (Mapping, list, tuple)):
            if node_count >= _ROLLING_PAPER_IDENTITY_MAX_NODES:
                unproven = True
            else:
                node_count += 1
            return
        marker = id(item)
        if marker in visited:
            return
        if depth > _ROLLING_PAPER_IDENTITY_MAX_DEPTH:
            unproven = True
            return
        if node_count >= _ROLLING_PAPER_IDENTITY_MAX_NODES:
            unproven = True
            return
        try:
            item_size = len(item)
        except TypeError:
            item_size = 0
        if item_size > _ROLLING_PAPER_IDENTITY_MAX_NODES:
            unproven = True
            return
        visited.add(marker)
        node_count += 1
        if isinstance(item, Mapping):
            for key, child in item.items():
                normalized_key = str(key).strip().lower().replace("-", "_")
                for name, keys, _allowed in aliases:
                    if normalized_key in keys:
                        normalized = _binding_value(child)
                        if normalized is not None:
                            values[name].add(normalized)
                # Do not assume payload field names: identity may be hidden
                # under any nested mapping/list value.
                visit(child, depth + 1)
        else:
            for child in item:
                visit(child, depth + 1)

    visit(value)
    for name, _keys, allowed in aliases:
        observed = values[name]
        if not observed:
            continue
        if not allowed or any(item not in allowed for item in observed):
            return name
        if len(observed) > 1:
            return name
    return "identity_unproven" if unproven else None



def _rolling_rule_scope_market_ids(
    store: Any,
    record: Mapping[str, Any],
    binding: Mapping[str, Any],
    rows: Sequence[Mapping[str, Any]],
    now: datetime,
) -> set[str] | None:
    """Return the exact market set authorized by a RULE_BASED_MARKETS scope."""
    scope = binding.get("market_scope", binding.get("scope"))
    if not isinstance(scope, Mapping):
        return None
    mode = str(scope.get("mode", "")).strip().upper()
    if mode != "RULE_BASED_MARKETS":
        return None
    candidate_id = _binding_value(binding.get("candidate_id"))
    scope_hash = _binding_value(
        binding.get("market_scope_hash", binding.get("scope_hash"))
    )
    scope_version = _binding_value(
        binding.get("market_scope_version", binding.get("scope_version"))
    )
    if not candidate_id or not scope_hash or not scope_version:
        raise ValueError("RULE_BASED_MARKET_SCOPE_BINDING_REQUIRED")
    loader = getattr(store, "load_market_scope_resolution", None)
    resolution: Any = None
    if callable(loader):
        try:
            resolution = loader(
                candidate_id,
                scope_hash=scope_hash,
                scope_version=scope_version,
            )
        except TypeError:
            try:
                resolution = loader(candidate_id)
            except Exception:
                resolution = None
        except Exception:
            resolution = None
    if resolution is not None:
        if hasattr(resolution, "as_dict") and callable(resolution.as_dict):
            resolution = resolution.as_dict()
        if not isinstance(resolution, Mapping):
            raise ValueError("RULE_BASED_MARKET_SCOPE_RESOLUTION_INVALID")
        if (
            _binding_value(resolution.get("candidate_id")) != candidate_id
            or _binding_value(resolution.get("scope_hash")) != scope_hash
            or _binding_value(resolution.get("scope_version")) != scope_version
        ):
            raise ValueError("RULE_BASED_MARKET_SCOPE_RESOLUTION_INVALID")
        if str(resolution.get("status", "")).strip().upper() != "MATCHED":
            raise ValueError("RULE_BASED_MARKET_SCOPE_RESOLUTION_INCOMPLETE")
        matched = resolution.get("matched_markets", ())
        if not isinstance(matched, (list, tuple)):
            raise ValueError("RULE_BASED_MARKET_SCOPE_RESOLUTION_INVALID")
        result: set[str] = set()
        for market in matched:
            if isinstance(market, Mapping):
                market_id = _binding_value(
                    market.get("market_id", market.get("id"))
                )
            else:
                market_id = _binding_value(market)
            if market_id:
                result.add(market_id)
        if not result:
            raise ValueError("RULE_BASED_MARKET_SCOPE_RESOLUTION_INCOMPLETE")
        return result
    # Custom stores may not persist resolutions.  Reuse the canonical resolver
    # against their bounded inventory rather than implementing a second rule
    # matcher here; unresolved or partial results fail closed.
    try:
        from .market_scope import resolve_market_scope
    except (ImportError, AttributeError) as exc:
        raise ValueError("RULE_BASED_MARKET_SCOPE_RESOLVER_UNAVAILABLE") from exc
    inventory: dict[str, Mapping[str, Any]] = {}
    for raw in rows:
        if not isinstance(raw, Mapping):
            continue
        view = _rolling_snapshot_view(raw)
        market_id = _binding_value(
            view.get("market_id", view.get("condition_id", view.get("id")))
        )
        if market_id and market_id not in inventory:
            inventory[market_id] = view
    try:
        resolved = resolve_market_scope(
            candidate_id,
            record,
            tuple(inventory.values()),
            resolved_at=now,
        )
    except Exception as exc:
        raise ValueError("RULE_BASED_MARKET_SCOPE_RESOLUTION_FAILED") from exc
    resolved_status = str(getattr(resolved, "status", "")).strip().upper()
    if resolved_status != "MATCHED":
        raise ValueError("RULE_BASED_MARKET_SCOPE_RESOLUTION_INCOMPLETE")
    matched = getattr(resolved, "matched_markets", ())
    result = {
        market_id
        for market in matched
        if (market_id := _binding_value(getattr(market, "market_id", None)))
    }
    if not result:
        raise ValueError("RULE_BASED_MARKET_SCOPE_RESOLUTION_INCOMPLETE")
    return result
def _rolling_document_is_marked(value: Mapping[str, Any], provenance: Mapping[str, Any] | None = None) -> bool:
    containers = [value]
    if isinstance(provenance, Mapping):
        containers.append(provenance)
    for field_name in ("provenance", "strategy_document", "strategy", "canonical_strategy", "payload"):
        nested = value.get(field_name)
        if isinstance(nested, Mapping):
            containers.append(nested)
            if isinstance(nested.get("provenance"), Mapping):
                containers.append(nested["provenance"])
    for item in containers:
        if item.get("rolling_research") is True or item.get("rolling") is True:
            return True
        if str(item.get("research_mode", "")).strip().upper() in {"ROLLING", "ROLLING_RESEARCH"}:
            return True
        if str(item.get("trial_kind", "")).strip().upper() == "ROLLING_RESEARCH":
            return True
        if str(item.get("source", "")).strip().lower() == "rolling":
            return True
    return False
def _rolling_document_is_draft_bound(
    value: Mapping[str, Any],
    provenance: Mapping[str, Any] | None = None,
) -> bool:
    """Identify draft-bound lineage before it can enter ordinary authority."""
    pending: list[tuple[Mapping[str, Any], int]] = [(value, 0)]
    if isinstance(provenance, Mapping):
        pending.append((provenance, 0))
    seen: set[int] = set()
    while pending:
        item, depth = pending.pop()
        marker = id(item)
        if marker in seen or depth > _ROLLING_MAX_PROVENANCE_DEPTH:
            continue
        seen.add(marker)
        if item.get("draft_bound") is True:
            return True
        for child in item.values():
            if isinstance(child, Mapping):
                pending.append((child, depth + 1))
    return False
def _rolling_campaign_bound(value: Mapping[str, Any]) -> bool:
    """Reject campaign lineage while bounding unrelated bulk observations.

    ``experiment_plan`` is an authoritative campaign container and is checked
    before any general traversal.  Large attestation/observation arrays are
    not campaign authority; treating their length as a campaign marker would
    incorrectly reject otherwise valid frozen candidates.
    """
    active: set[int] = set()
    completed: set[int] = set()
    visited = 0

    def direct_marker(item: Mapping[str, Any]) -> bool:
        if any(
            _binding_value(item.get(name))
            for name in ("campaign_id", "campaign_trial_id", "campaign_configuration_id")
        ):
            return True
        protocol = item.get("campaign_protocol")
        if (
            isinstance(protocol, Mapping)
            or (protocol is not None and str(protocol).strip())
            or str(item.get("source", "")).strip().lower()
            in {"axiom-finite-campaign", "finite-campaign"}
        ):
            return True
        return False

    def visit(item: Any, depth: int = 0, parent_key: str | None = None) -> bool:
        nonlocal visited
        if isinstance(item, (list, tuple)):
            if parent_key in _ROLLING_NON_AUTHORITATIVE_ARRAY_KEYS:
                return False
            marker = id(item)
            if marker in active:
                # Recursive list/tuple payloads are also unproven and must
                # remain fail-closed instead of recursing indefinitely.
                return True
            if marker in completed:
                return False
            active.add(marker)
            try:
                if depth > _ROLLING_MAX_PROVENANCE_DEPTH:
                    return True
                if len(item) > 128:
                    # Unknown bulk arrays remain fail-closed.  Known observation
                    # arrays are handled above and are intentionally ignored.
                    return True
                return any(visit(child, depth + 1, parent_key) for child in item)
            finally:
                active.discard(marker)
                completed.add(marker)
        if not isinstance(item, Mapping):
            return False
        marker = id(item)
        if marker in active:
            # The same object on the current ancestry path is a real cycle;
            # fail closed rather than allowing a recursive campaign payload.
            return True
        if marker in completed:
            # A benign alias to a container already traversed is not a cycle.
            return False
        active.add(marker)
        try:
            visited += 1
            if visited > 512 or depth > _ROLLING_MAX_PROVENANCE_DEPTH:
                return True
            if direct_marker(item):
                return True
            # Check this authoritative container first.  This prevents a large
            # unrelated field encountered earlier in insertion order from hiding
            # a campaign marker nested in the plan.
            plan = item.get("experiment_plan")
            if isinstance(plan, Mapping) and visit(plan, depth + 1, "experiment_plan"):
                return True
            children = list(item.items())
            if len(children) > 512:
                return True
            for key, child in children:
                key_name = str(key).strip().lower()
                if key_name == "experiment_plan":
                    continue
                if isinstance(child, (list, tuple)) and key_name in _ROLLING_NON_AUTHORITATIVE_ARRAY_KEYS:
                    continue
                if visit(child, depth + 1, key_name):
                    return True
            return False
        finally:
            active.discard(marker)
            completed.add(marker)

    return visit(value)


def _rolling_snapshot_view(row: Mapping[str, Any]) -> dict[str, Any]:
    """Merge persisted snapshot/result payloads before terminal metric reads."""
    result: dict[str, Any] = dict(row)
    pending = [
        row.get(name)
        for name in (
            "payload",
            "snapshot",
            "data",
            "observation",
            "result",
            "outcome",
        )
    ]
    seen: set[int] = set()
    while pending:
        value = pending.pop(0)
        if not isinstance(value, Mapping) or id(value) in seen:
            continue
        seen.add(id(value))
        for key, child in value.items():
            if key not in result or result.get(key) in (None, ""):
                result[str(key)] = child
        pending.extend(
            value.get(name)
            for name in (
                "payload",
                "snapshot",
                "data",
                "observation",
                "result",
                "outcome",
                "ledger",
                "ledgers",
                "accounting",
                "canonical_accounting",
                "strategy_accounting",
                "resolved_bet",
                "resolved_bets",
                "fills",
                "fill",
                "position",
                "positions",
            )
        )
    return result


def _rolling_overlap_key(rows: Sequence[Mapping[str, Any]]) -> str:
    exposures: set[str] = set()
    for raw in rows:
        if not isinstance(raw, Mapping):
            continue
        if raw.get("_rolling_source_rejection") or raw.get(
            "_rolling_accounting_rejection"
        ):
            continue
        row = _rolling_snapshot_view(raw)
        for key in (
            "market_id",
            "market_ids",
            "universe_id",
            "universe_version",
            "market_scope_hash",
            "scope_hash",
        ):
            value = row.get(key)
            if isinstance(value, (list, tuple, set, frozenset)):
                exposures.update(
                    str(item).strip() for item in value if str(item).strip()
                )
            elif value is not None and str(value).strip():
                exposures.add(str(value).strip())
    if not exposures:
        return "unknown"
    return "exposure:" + _rolling_hash(sorted(exposures)).removeprefix("sha256:")[:40]

_GENERATED_QUEUE_PROVENANCE_SCHEMA = "axiom-generated-queue-v1"
_GENERATED_QUEUE_KINDS = frozenset({
    "predeclared_starting_set",
    "legacy_scope_successor",
    "mutation_child",
    _NEXT_DATASET_GENERATED_KIND,
})


def _payload_without_generated_provenance(payload: Mapping[str, Any]) -> dict[str, Any]:
    """Return the proposal identity material without its internal marker."""
    result = dict(payload)
    provenance = result.get("provenance")
    if isinstance(provenance, Mapping) and isinstance(provenance.get("internal"), Mapping):
        clean_provenance = dict(provenance)
        clean_provenance.pop("internal", None)
        if clean_provenance:
            result["provenance"] = clean_provenance
        else:
            # A marker is added to otherwise unprovenanced proposals.  Do not
            # leave behind the empty container created solely by removing it;
            # the pre-marker and post-marker identities must be identical.
            result.pop("provenance", None)
    return result


def _proposal_identity(payload: Mapping[str, Any]) -> str:
    return "sha256:" + hashlib.sha256(
        _canonical_binding(_payload_without_generated_provenance(payload)).encode("utf-8")
    ).hexdigest()


def _mark_generated_queue_payload(
    payload: Mapping[str, Any],
    *,
    kind: str,
    dataset_id: str | None,
    dataset_version: str | None,
    attestation_hash: str | None,
) -> dict[str, Any]:
    """Attach a self-authenticating marker to worker-generated proposals."""
    clean = dict(payload)
    provenance = (
        dict(clean.get("provenance"))
        if isinstance(clean.get("provenance"), Mapping)
        else {}
    )
    if not provenance:
        clean.pop("provenance", None)
    provenance["internal"] = {
        "schema": _GENERATED_QUEUE_PROVENANCE_SCHEMA,
        "generated": True,
        "kind": str(kind).strip(),
        "proposal_identity": _proposal_identity(clean),
        "dataset_id": str(dataset_id or "").strip() or None,
        "dataset_version": str(dataset_version or "").strip() or None,
        "attestation_hash": str(attestation_hash or "").strip() or None,
    }
    clean["provenance"] = provenance
    return clean


def _generated_queue_provenance(payload: Mapping[str, Any]) -> Mapping[str, Any] | None:
    provenance = payload.get("provenance")
    if not isinstance(provenance, Mapping):
        return None
    internal = provenance.get("internal")
    if not isinstance(internal, Mapping):
        return None
    if not (
        internal.get("schema") == _GENERATED_QUEUE_PROVENANCE_SCHEMA
        or internal.get("generated") is True
        or str(internal.get("kind", "")).strip() in _GENERATED_QUEUE_KINDS
    ):
        return None
    return internal


def _legacy_dataset_selector_conflict(document: Mapping[str, Any]) -> str | None:
    """Reject contradictory outer/nested dataset selectors before handoff."""
    nested = document.get("experiment_plan")
    nested = nested if isinstance(nested, Mapping) else None
    contexts = (("outer", document), ("nested", nested)) if nested is not None else (("outer", document),)
    values: dict[str, list[tuple[str, str]]] = {"dataset_id": [], "dataset_version": []}
    for label, source in contexts:
        if not isinstance(source, Mapping):
            continue
        selector = source.get("dataset_selector")
        selector = selector if isinstance(selector, Mapping) else {}
        for name, aliases in (
            ("dataset_id", ("dataset_id",)),
            ("dataset_version", ("dataset_version", "version")),
        ):
            for alias in aliases:
                value = selector.get(alias)
                if value is not None and str(value).strip():
                    values[name].append((f"{label}.dataset_selector.{alias}", str(value).strip()))
                value = source.get(alias)
                if value is not None and str(value).strip():
                    values[name].append((f"{label}.{alias}", str(value).strip()))
    for name, entries in values.items():
        distinct = {value for _, value in entries}
        if len(distinct) > 1:
            return "CONFLICTING_DATASET_SELECTOR"
        if name == "dataset_version" and any(
            value.casefold() in _MUTABLE_DATASET_VERSION_ALIASES for value in distinct
        ):
            return "DATASET_VERSION_ALIAS"
    return None

def bootstrap_system_exploratory_admission_policy(
    store: Any,
    *,
    ensure_operating: Callable[[datetime], Mapping[str, Any]],
    risk_binding_loader: Callable[[], Mapping[str, Any]],
    now: datetime,
) -> dict[str, Any]:
    """Atomically establish the exact disarmed system rolling envelope."""
    get_config = getattr(store, "get_operator_config", None)
    saver = getattr(store, "save_admission_policy", None)
    transaction = getattr(store, "transaction", None)
    set_config = getattr(store, "set_operator_config", None)
    set_job = getattr(store, "set_operator_job", None)
    if not all(callable(item) for item in (get_config, saver, transaction, set_config, set_job)):
        raise RollingPolicyBootstrapError("ROLLING_POLICY_TRANSACTION_UNAVAILABLE")
    set_config("rolling_exploratory_bootstrap_required", True)
    ensure_operating(now)
    operating = get_config("rolling_exploratory_operating_policy", None)
    if not isinstance(operating, Mapping):
        raise RollingPolicyBootstrapError("ROLLING_POLICY_BOOTSTRAP_REQUIRED")
    operating = dict(operating)
    binding = dict(risk_binding_loader())
    try:
        validate_system_exploratory_admission_policy(
            None,
            operating,
            binding,
            require_active=False,
        )
    except RollingPolicyBootstrapError:
        raise
    policy_document = default_rolling_admission_policy().as_dict()
    active_template: dict[str, Any] = {
        "policy": policy_document,
        "policy_id": policy_document["policy_id"],
        "version": policy_document["version"],
        "policy_version": policy_document["version"],
        "config_hash": policy_document["config_hash"],
        "operating_policy": operating,
        "exploratory_policy": operating,
        "system_bootstrap_id": SYSTEM_EXPLORATORY_ADMISSION_ID,
        "system_bootstrap_version": SYSTEM_EXPLORATORY_ADMISSION_VERSION,
        **binding,
        "status": "ACTIVE",
        "paper_only": True,
        "live_execution": False,
        "allocation_active": False,
        "canary_armed": False,
    }
    active_template["system_bootstrap_hash"] = _system_bootstrap_hash(
        active_template,
        excluded=frozenset({"activated_at", "activated_by", "system_bootstrap_hash"}),
    )

    def validate_active(value: Any, current_binding: Mapping[str, Any]) -> dict[str, Any]:
        return validate_system_exploratory_admission_policy(
            value,
            operating,
            current_binding,
        ) or {}

    current = get_config("rolling_admission_policy_active", None)
    if isinstance(current, Mapping) and current:
        return validate_active(current, binding)
    if current not in (None, {}):
        raise RollingPolicyBootstrapError("ROLLING_POLICY_BOOTSTRAP_DRIFT")
    saver(policy_document)
    active = dict(active_template)
    active["activated_at"] = now.isoformat()
    active["activated_by"] = "system:bootstrap"
    with transaction(immediate=True):
        current = get_config("rolling_admission_policy_active", None)
        if current not in (None, {}):
            return validate_active(current, dict(risk_binding_loader()))
        current_binding = dict(risk_binding_loader())
        if any(
            str(current_binding.get(key, "")).strip()
            != str(binding.get(key, "")).strip()
            for key in ("risk_config_id", "risk_config_generation", "risk_config_hash")
        ):
            raise RollingPolicyBootstrapError("ROLLING_POLICY_BOOTSTRAP_RISK_DRIFT")
        set_config("rolling_admission_policy_active", active)
        set_job("rolling_admission_policy_active", "ACTIVE", active, resumable=True)
    return active


class AutonomousResearchError(ValueError):
    """A deterministic, auditable queue rejection or unsupported operation."""

    def __init__(self, reason: str, detail: str) -> None:
        self.reason = str(reason).strip().upper() or "AUTONOMOUS_RESEARCH_ERROR"
        self.code = self.reason
        self.detail = str(detail).strip() or self.reason
        super().__init__(f"{self.reason}: {self.detail}")


@dataclass(frozen=True, slots=True)
class AutonomousResearchConfig:
    """Boundaries applied to every autonomous queue cycle and mutation."""

    max_items_per_cycle: int = 1
    lease_seconds: float = 300.0
    total_limit: int = 1000
    family_limit: int = 250
    max_plan_variants: int = 8
    max_children_per_parent: int = 2
    max_generation_depth: int = 2
    max_experiments_per_day: int = 250
    mutation_enabled: bool = True
    promotion_criteria: PromotionCriteria = field(default_factory=PromotionCriteria)
    scope_resolution_freshness_sla_seconds: float | None = None
    observation_setup_migration_freshness_sla_seconds: float | None = None

    def __post_init__(self) -> None:
        for name in (
            "max_items_per_cycle",
            "total_limit",
            "family_limit",
            "max_plan_variants",
            "max_children_per_parent",
            "max_generation_depth",
            "max_experiments_per_day",
        ):
            value = getattr(self, name)
            if isinstance(value, bool) or not isinstance(value, int) or value < 0:
                raise ValueError(f"{name} must be a non-negative integer")
        if self.max_items_per_cycle < 1:
            raise ValueError("max_items_per_cycle must be positive")
        if self.max_plan_variants < 1 or self.max_plan_variants > MAX_PLAN_VARIANTS:
            raise ValueError(f"max_plan_variants must be between one and {MAX_PLAN_VARIANTS}")
        lease = float(self.lease_seconds)
        if not math.isfinite(lease) or lease <= 0:
            raise ValueError("lease_seconds must be finite and positive")
        object.__setattr__(self, "lease_seconds", lease)
        if not isinstance(self.mutation_enabled, bool):
            raise ValueError("mutation_enabled must be boolean")
        if not isinstance(self.promotion_criteria, PromotionCriteria):
            raise ValueError("promotion_criteria must be PromotionCriteria")
        if self.scope_resolution_freshness_sla_seconds is not None:
            freshness = float(self.scope_resolution_freshness_sla_seconds)
            if not math.isfinite(freshness) or freshness <= 0:
                raise ValueError("scope_resolution_freshness_sla_seconds must be finite and positive")
            object.__setattr__(self, "scope_resolution_freshness_sla_seconds", freshness)
        if self.observation_setup_migration_freshness_sla_seconds is not None:
            freshness = float(self.observation_setup_migration_freshness_sla_seconds)
            if not math.isfinite(freshness) or freshness <= 0:
                raise ValueError(
                    "observation_setup_migration_freshness_sla_seconds must be finite and positive"
                )
            object.__setattr__(
                self,
                "observation_setup_migration_freshness_sla_seconds",
                freshness,
            )


@dataclass(frozen=True, slots=True)
class AutonomousQueueCycle:
    released: int
    claimed: int
    completed: int
    rejected: int
    failed: int
    results: tuple[Mapping[str, Any], ...] = ()
    legacy_recovery: tuple[Mapping[str, Any], ...] = ()

    def as_record(self) -> dict[str, Any]:
        return {
            "released": self.released,
            "claimed": self.claimed,
            "completed": self.completed,
            "rejected": self.rejected,
            "failed": self.failed,
            "results": [dict(item) for item in self.results],
            "legacy_recovery": [dict(item) for item in self.legacy_recovery],
            "paper_only": True,
        }


class AutonomousResearchProcessor:
    """Claim and execute bounded paper research with a locked holdout.

    Ordinary autonomous trials receive only train and validation partitions.
    The holdout remains locked until an explicitly authorized post-selection
    assessment; it is never used to select variants, mutate strategies, or
    qualify a canary.
    """

    @staticmethod
    def predeclared_starting_set() -> tuple[Mapping[str, Any], ...]:
        """Return the small deterministic strategy set owned by Axiom."""
        return tuple(
            {
                "template": str(item["template"]),
                "parameters": {
                    str(name): tuple(values)
                    for name, values in dict(item["parameters"]).items()
                },
                **(
                    {"model_document": dict(item["model_document"])}
                    if isinstance(item.get("model_document"), Mapping)
                    else {}
                ),
                **(
                    {"metadata": dict(item["metadata"])}
                    if isinstance(item.get("metadata"), Mapping)
                    else {}
                ),
            }
            for item in PREDECLARED_STRATEGY_STARTING_SET
        )

    def enqueue_predeclared_starting_set(
        self,
        proposal: Mapping[str, Any],
        *,
        strategies: Sequence[Mapping[str, Any]] | None = None,
        priority: int = 0,
        available_at: datetime | None = None,
    ) -> tuple[ResearchQueueItem, ...]:
        """Durably enqueue Axiom's deterministic starter trials.

        The caller provides research data selectors and assumptions, not
        candidate/proposal ids.  Each family gets a deterministic identity and
        bounded one-variant plan; queue dedupe makes retries idempotent.
        """
        if not isinstance(proposal, Mapping):
            raise TypeError("proposal must be a mapping")
        selected = tuple(strategies) if strategies is not None else self.predeclared_starting_set()
        if not selected or len(selected) > self.config.max_plan_variants:
            raise AutonomousResearchError(
                "EXPERIMENT_BUDGET_EXCEEDED",
                "predeclared strategy set is empty or exceeds the node bound",
            )
        base = dict(proposal)
        base.pop("proposal_id", None)
        base.pop("hypothesis_id", None)
        observation_handoff = base.get("observation_handoff")
        successor_dedupe_key = None
        if isinstance(observation_handoff, Mapping):
            predecessor_queue_id = str(
                observation_handoff.get("predecessor_queue_id", "")
            ).strip()
            handoff_version = str(
                observation_handoff.get("version", "")
            ).strip()
            if predecessor_queue_id and handoff_version:
                successor_dedupe_key = (
                    f"predeclared-successor:{predecessor_queue_id}:{handoff_version}"
                )
        items: list[ResearchQueueItem] = []
        for index, strategy in enumerate(selected):
            if not isinstance(strategy, Mapping):
                raise AutonomousResearchError("UNSUPPORTED_STRATEGY_FAMILY", "predeclared strategy must be a mapping")
            template = str(strategy.get("template", strategy.get("family", ""))).strip().lower()
            parameters = strategy.get("parameters", {})
            if not template or not isinstance(parameters, Mapping):
                raise AutonomousResearchError("UNSUPPORTED_STRATEGY_FAMILY", "predeclared strategy requires template and parameters")
            raw_metadata = strategy.get("metadata")
            metadata = dict(raw_metadata) if isinstance(raw_metadata, Mapping) else {}
            role = str(strategy.get("research_role", metadata.get("research_role", ""))).strip()
            if role:
                metadata["research_role"] = role
            if "selection_excluded" in strategy:
                metadata["selection_excluded"] = bool(strategy["selection_excluded"])
            if "proven_zero_edge" in strategy:
                metadata["proven_zero_edge"] = bool(strategy["proven_zero_edge"])
            plan = base.get("experiment_plan")
            plan_document = dict(plan) if isinstance(plan, Mapping) else {}
            plan_document.update(
                {
                    "template": template,
                    "parameters": dict(parameters),
                    "max_variants": 1,
                    "paper_only": True,
                }
            )
            model_document = strategy.get("model_document")
            if isinstance(model_document, Mapping):
                plan_document["model_document"] = dict(model_document)
            strategy_document = strategy.get("strategy_document")
            if metadata:
                strategy_document = dict(strategy_document) if isinstance(strategy_document, Mapping) else {
                    "version": 1,
                    "market_type": MarketType.PREDICTION.value,
                    "family": template,
                    "probability_model": "plan-model-probability",
                    "resolution_aware": True,
                    "resolution_inputs": ["expiry", "settlement"],
                }
                strategy_document["metadata"] = metadata
                plan_document["strategy_document"] = strategy_document
            material = {
                "schema": "axiom-predeclared-starting-set-v1",
                "base": base,
                "template": template,
                "parameters": dict(parameters),
                "model_document": dict(model_document) if isinstance(model_document, Mapping) else None,
                "metadata": metadata,
                "index": index,
            }
            proposal_id = "predeclared-" + hashlib.sha256(
                _canonical_binding(material).encode("utf-8")
            ).hexdigest()[:24]
            item_payload = {
                **base,
                "proposal_id": proposal_id,
                "experiment_plan": plan_document,
                "paper_only": True,
                "predeclared_starting_set": True,
            }
            # Keep the attestation binding sourced from the plan before
            # compatibility defaults are added to the stored payload.
            selector = item_payload.get("dataset_selector")
            selector = selector if isinstance(selector, Mapping) else plan_document.get("dataset_selector")
            selector = selector if isinstance(selector, Mapping) else plan_document
            dataset_id = str(
                selector.get("dataset_id") or item_payload.get("dataset_id") or plan_document.get("dataset_id") or ""
            ).strip() or None
            dataset_version = str(
                selector.get("dataset_version")
                or selector.get("version")
                or item_payload.get("dataset_version")
                or plan_document.get("dataset_version")
                or ""
            ).strip() or None
            attestation_hash = None
            attestation_loader = getattr(self.store, "load_dataset_integrity_attestation", None)
            if callable(attestation_loader) and dataset_id and dataset_version:
                try:
                    attestation = attestation_loader(dataset_id, dataset_version)
                except Exception:
                    attestation = None
                if isinstance(attestation, Mapping):
                    attestation_hash = str(attestation.get("attestation_hash", "")).strip() or None
            # Processing normalizes worker payloads before checking the
            # self-authenticating marker. Store that same canonical shape so a
            # sparse predeclared proposal does not reject itself at claim time.
            item_payload = _normalize_hypothesis_payload(
                item_payload,
                source_fallback=str(
                    getattr(self.bus, "author", "")
                    or getattr(self.bus, "source", "")
                    or "hermes"
                ).strip()
                or "hermes",
            )
            item_payload = _mark_generated_queue_payload(
                item_payload,
                kind="predeclared_starting_set",
                dataset_id=dataset_id,
                dataset_version=dataset_version,
                attestation_hash=attestation_hash,
            )
            item = self.bus.submit_hypothesis(
                item_payload,
                dedupe_key=(
                    successor_dedupe_key
                    or f"predeclared:{proposal_id}:{attestation_hash or 'unattested'}"
                ),
                priority=priority,
                available_at=available_at,
            )
            items.append(item)
        return tuple(items)

    submit_predeclared_starting_set = enqueue_predeclared_starting_set

    def _persist_predeclared_seed_evidence(
        self,
        evidence: Mapping[str, Any],
        *,
        dataset_id: str,
        dataset_version: str | None,
    ) -> bool:
        """Persist one blocked seed decision as immutable research evidence.

        A dataset binding can produce different blocked decisions as its
        persisted provenance changes.  The binding is the experiment
        namespace, while the canonical evidence digest identifies one
        append-only decision attempt within that namespace.  This keeps
        retries of an identical observation idempotent without allowing a
        later blocker to collide with, or overwrite, its predecessor.
        """
        saver = getattr(self.store, "save_report_if_absent", None)
        if not callable(saver):
            return False
        version = str(dataset_version or "").strip()
        binding_id = "autonomous-predeclared-seed:" + str(dataset_id).strip()
        if version:
            binding_id += ":" + version
        evidence_id = hashlib.sha256(
            _canonical_binding(dict(evidence)).encode("utf-8")
        ).hexdigest()[:24]
        report_id = f"{binding_id}:{evidence_id}"
        try:
            return bool(
                saver(
                    report_id,
                    dict(evidence),
                    experiment_id=binding_id,
                )
            )
        except Exception:
            # A failed evidence write must never turn a fail-closed seed gate
            # into an untrusted queue submission.
            return False

    def _predeclared_seed_blocker(
        self,
        *,
        blocker: str,
        detail: str,
        dataset_id: str,
        dataset_version: str | None,
        catalog: Mapping[str, Any] | None = None,
        attestation: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Build the exact prerequisite projection for a blocked seed."""
        normalized_blocker = str(blocker).strip().upper() or "DATASET_PROVENANCE_INVALID"
        normalized_detail = str(detail).strip() or normalized_blocker
        if normalized_blocker == "DATASET_ATTESTATION_MISSING":
            next_action = "PERSIST_CURRENT_HISTORICAL_DATASET_ATTESTATION"
        elif normalized_blocker == "DATASET_ATTESTATION_STALE":
            next_action = "REFRESH_CURRENT_HISTORICAL_DATASET_ATTESTATION"
        elif "CONTAMIN" in normalized_detail.upper():
            next_action = "REMOVE_FORWARD_CONTAMINATION_AND_REATTEST_HISTORICAL_DATASET"
        else:
            next_action = "REPAIR_HISTORICAL_DATASET_PROVENANCE_AND_REATTEST"
        catalog_map = catalog if isinstance(catalog, Mapping) else {}
        attestation_map = attestation if isinstance(attestation, Mapping) else {}
        return {
            "report_type": "autonomous_predeclared_seed_blocked",
            "progress": "BLOCKED",
            "blocker": normalized_blocker,
            "reason": normalized_detail,
            "next_action": next_action,
            "required_dataset": {
                "dataset_id": str(dataset_id).strip() or None,
                "dataset_version": str(dataset_version or "").strip() or None,
                "source_type": "HISTORICAL",
                "market_type": MarketType.PREDICTION.value,
                "attestation_status": "CURRENT",
                "contamination_result": "PASS",
            },
            "catalog_identity": {
                "dataset_id": str(catalog_map.get("dataset_id", "")).strip() or None,
                "dataset_version": str(
                    catalog_map.get("dataset_version", catalog_map.get("version", ""))
                ).strip()
                or None,
                "instrument": str(catalog_map.get("instrument", "")).strip() or None,
                "row_count": catalog_map.get("row_count"),
                "completeness": catalog_map.get("completeness"),
            },
            "attestation": {
                "status": str(attestation_map.get("status", "")).strip().upper() or None,
                "contamination_result": attestation_map.get("contamination_result"),
                "attestation_hash": attestation_map.get("attestation_hash"),
                "reason": attestation_map.get("reason"),
            },
            "queue_items_enqueued": 0,
            "variants_tested": 0,
            "paper_only": True,
            "research_only": True,
        }

    def _enqueue_predeclared_from_persisted_scope(self, now: datetime) -> tuple[ResearchQueueItem, ...]:
        """Seed bounded prediction research from the persisted historical catalog.

        The seed is deterministic and policy-bound: the aggregate historical
        dataset and canonical POLYMARKET forward rules are selected before any
        candidate performance is inspected.  The exact dataset catalog and
        current integrity attestation are validated through the same
        provenance contract used by ordinary hypothesis processing before a
        queue row can be created. Queue deduplication makes this safe to invoke
        on every normal worker tick.
        """
        def enqueue_successors() -> tuple[ResearchQueueItem, ...]:
            # A previous worker may have terminally rejected only the transient
            # historical-lookback gate.  That immutable row must not be revived:
            # enqueue one linked successor identity whose paper observation
            # lineage can collect current-market evidence.  Genuine schema or
            # strategy rejections remain untouched.
            successors: list[ResearchQueueItem] = []
            existing_successors: dict[tuple[str, str], ResearchQueueItem] = {}
            try:
                existing_rows = self.bus.list(limit=4096)
            except (TypeError, ValueError, RuntimeError):
                existing_rows = ()
            for existing in existing_rows:
                existing_handoff = existing.payload.get("observation_handoff")
                if not isinstance(existing_handoff, Mapping):
                    continue
                predecessor_id = str(
                    existing_handoff.get("predecessor_queue_id", "")
                ).strip()
                handoff_version = str(existing_handoff.get("version", "")).strip()
                if predecessor_id and handoff_version:
                    existing_successors[(predecessor_id, handoff_version)] = existing
            def has_normalized_lineage(previous: ResearchQueueItem) -> bool:
                candidate_ids: set[str] = set()
                payload_candidate = previous.payload.get("candidate_id")
                if str(payload_candidate or "").strip():
                    candidate_ids.add(str(payload_candidate).strip())
                result = previous.result if isinstance(previous.result, Mapping) else {}
                result_candidates = result.get("candidate_results", ())
                if isinstance(result_candidates, Sequence) and not isinstance(
                    result_candidates, (str, bytes, bytearray)
                ):
                    for candidate in result_candidates:
                        if isinstance(candidate, Mapping) and str(
                            candidate.get("candidate_id", "")
                        ).strip():
                            candidate_ids.add(str(candidate["candidate_id"]).strip())
                loaders = {
                    "experiment": getattr(self.store, "load_experiment", None),
                    "lifecycle": getattr(self.store, "load_candidate_lifecycle", None),
                    "strategy": getattr(self.store, "load_strategy_version", None),
                    "trial": getattr(self.store, "load_research_trial", None),
                    "enrollment": getattr(self.store, "load_rolling_enrollment", None),
                }
                for candidate_id in candidate_ids:
                    records: list[Mapping[str, Any]] = []
                    for loader in (loaders["experiment"], loaders["lifecycle"]):
                        if not callable(loader):
                            continue
                        try:
                            value = loader(candidate_id)
                        except (TypeError, ValueError, RuntimeError):
                            value = None
                        if isinstance(value, Mapping):
                            records.append(value)
                    identifiers = {
                        str(record.get(field, "")).strip()
                        for record in records
                        for field in (
                            "strategy_version_id",
                            "research_trial_id",
                            "enrollment_id",
                        )
                        if str(record.get(field, "")).strip()
                    }
                    strategy_version_id = next(
                        (
                            str(record.get("strategy_version_id", "")).strip()
                            for record in records
                            if str(record.get("strategy_version_id", "")).strip()
                        ),
                        "",
                    )
                    trial_id = next(
                        (
                            str(record.get("research_trial_id", "")).strip()
                            for record in records
                            if str(record.get("research_trial_id", "")).strip()
                        ),
                        "",
                    )
                    if (
                        not strategy_version_id
                        or not trial_id
                        or not callable(loaders["strategy"])
                        or not callable(loaders["trial"])
                    ):
                        continue
                    try:
                        version = loaders["strategy"](strategy_version_id)
                        trial = loaders["trial"](trial_id)
                    except (TypeError, ValueError, RuntimeError):
                        continue
                    if not isinstance(version, Mapping) or not isinstance(trial, Mapping):
                        continue
                    if not callable(loaders["enrollment"]):
                        return True
                    enrollment_id = next(
                        (
                            identifier
                            for identifier in identifiers
                            if identifier.startswith("rolling-enrollment-")
                        ),
                        "",
                    )
                    if enrollment_id:
                        try:
                            enrollment = loaders["enrollment"](enrollment_id)
                        except (TypeError, ValueError, RuntimeError):
                            enrollment = None
                        if isinstance(enrollment, Mapping) and str(
                            enrollment.get("status", "")
                        ).strip().upper() == "ACCEPTED":
                            return True
                return False
            def is_transient_predeclared(previous: ResearchQueueItem) -> bool:
                payload = previous.payload
                if (
                    previous.item_type != "hypothesis"
                    or previous.status is not ResearchQueueStatus.REJECTED
                    or not bool(payload.get("predeclared_starting_set"))
                    or str(previous.last_error or "").strip().casefold()
                    != "at least three chronological observations are required"
                ):
                    return False
                result = previous.result if isinstance(previous.result, Mapping) else {}
                candidates = result.get("candidate_results")
                if not isinstance(candidates, Sequence) or isinstance(
                    candidates, (str, bytes, bytearray)
                ):
                    return False
                if not any(
                    isinstance(candidate, Mapping)
                    and str(candidate.get("reason_code", "")).strip().upper()
                    == "INSUFFICIENT_DATA"
                    and str(candidate.get("reason", "")).strip().casefold()
                    == "at least three chronological observations are required"
                    for candidate in candidates
                ):
                    return False
                internal = _generated_queue_provenance(payload)
                if isinstance(internal, Mapping):
                    return (
                        internal.get("generated") is True
                        and str(internal.get("kind", "")).strip()
                        == "predeclared_starting_set"
                        and str(internal.get("proposal_identity", "")).strip()
                        == _proposal_identity(payload)
                    )

                if str(payload.get("source", "")).strip() != (
                    "axiom-autonomous-predeclared"
                ):
                    return False
                proposal_id = str(
                    payload.get("proposal_id", payload.get("hypothesis_id", ""))
                ).strip()
                dedupe_key = str(previous.dedupe_key or "").strip()
                if (
                    not proposal_id
                    or not dedupe_key.startswith("predeclared:")
                    or dedupe_key.removeprefix("predeclared:") != proposal_id
                ):
                    return False
                plan_document = payload.get("experiment_plan")
                if not isinstance(plan_document, Mapping):
                    return False
                try:
                    plan = ExperimentPlan.from_proposal(payload)
                except (ExperimentPlanError, TypeError, ValueError, RuntimeError):
                    return False
                if plan.market_type is not MarketType.PREDICTION:
                    return False
                template = str(
                    plan_document.get("template", payload.get("template", ""))
                ).strip().lower()
                parameters = plan_document.get(
                    "parameters", payload.get("parameters", {})
                )
                if not template or not isinstance(parameters, Mapping):
                    return False
                for starter in PREDECLARED_STRATEGY_STARTING_SET:
                    if str(starter.get("template", "")).strip().lower() != template:
                        continue
                    expected = starter.get("parameters", {})
                    if not isinstance(expected, Mapping) or set(parameters) != set(expected):
                        continue
                    def parameter_matches(value: Any, expected_value: Any) -> bool:
                        if isinstance(expected_value, (list, tuple, set, frozenset)):
                            if isinstance(value, (list, tuple, set, frozenset)):
                                return len(value) == 1 and next(iter(value)) in expected_value
                            return value in expected_value
                        return value == expected_value

                    if all(
                        parameter in expected
                        and parameter_matches(parameter_value, expected[parameter])
                        for parameter, parameter_value in parameters.items()
                    ):
                        return True

            state_loader = getattr(self.store, "get_scheduler_state", None)
            state_setter = getattr(self.store, "set_scheduler_state", None)
            state: Mapping[str, Any] = {}
            cursor = {}
            if callable(state_loader):
                try:
                    loaded_state = state_loader(_PREDECLARED_SUCCESSOR_STATE_NAME)
                except (TypeError, ValueError, RuntimeError):
                    loaded_state = None
                if isinstance(loaded_state, Mapping):
                    state = loaded_state
                    raw_cursor = loaded_state.get("cursor")
                    if isinstance(raw_cursor, Mapping):
                        cursor = dict(raw_cursor)
            list_kwargs: dict[str, Any] = {
                "status": ResearchQueueStatus.REJECTED,
                "limit": _MAX_PREDECLARED_SUCCESSOR_SCAN,
            }
            if (
                cursor.get("priority") is not None
                and str(cursor.get("created_at", "")).strip()
                and str(cursor.get("item_id", "")).strip()
            ):
                list_kwargs.update(
                    {
                        "after_priority": int(cursor["priority"]),
                        "after_created_at": str(cursor["created_at"]),
                        "after_item_id": str(cursor["item_id"]),
                    }
                )
            try:
                rejected_rows = self.bus.list(**list_kwargs)
                if not rejected_rows and list_kwargs.get("after_item_id"):
                    list_kwargs = {
                        "status": ResearchQueueStatus.REJECTED,
                        "limit": _MAX_PREDECLARED_SUCCESSOR_SCAN,
                    }
                    cursor = {}
                    rejected_rows = self.bus.list(**list_kwargs)
            except (TypeError, ValueError, RuntimeError):
                rejected_rows = ()
            last_scanned = rejected_rows[-1] if rejected_rows else None
            for previous in rejected_rows:
                if not is_transient_predeclared(previous):
                    continue
                plan_document = previous.payload.get("experiment_plan")
                if has_normalized_lineage(previous):
                    continue
                plan_document = plan_document if isinstance(plan_document, Mapping) else {}
                template = str(
                    plan_document.get("template", previous.payload.get("template", ""))
                ).strip().lower()
                parameters = plan_document.get("parameters", previous.payload.get("parameters", {}))
                if not template or not isinstance(parameters, Mapping):
                    continue
                strategy_document = plan_document.get("strategy_document")
                metadata = (
                    strategy_document.get("metadata", {})
                    if isinstance(strategy_document, Mapping)
                    else {}
                )
                strategy: dict[str, Any] = {
                    "template": template,
                    "parameters": dict(parameters),
                }
                if isinstance(metadata, Mapping):
                    strategy["metadata"] = dict(metadata)
                model_document = plan_document.get("model_document")
                if isinstance(model_document, Mapping):
                    strategy["model_document"] = dict(model_document)
                result = previous.result if isinstance(previous.result, Mapping) else {}
                predecessor_candidate_id = ""
                candidate_results = result.get("candidate_results")
                if isinstance(candidate_results, Sequence) and not isinstance(
                    candidate_results, (str, bytes, bytearray)
                ):
                    predecessor_candidate_id = next(
                        (
                            str(candidate.get("candidate_id", "")).strip()
                            for candidate in candidate_results
                            if isinstance(candidate, Mapping)
                            and str(candidate.get("candidate_id", "")).strip()
                        ),
                        "",
                    )
                predecessor_observation_intent_id = ""
                lifecycle_loader = getattr(self.store, "load_candidate_lifecycle", None)
                if predecessor_candidate_id and callable(lifecycle_loader):
                    try:
                        lifecycle = lifecycle_loader(predecessor_candidate_id)
                    except (TypeError, ValueError, RuntimeError):
                        lifecycle = None
                    if isinstance(lifecycle, Mapping):
                        lifecycle_payload = lifecycle.get("payload")
                        if isinstance(lifecycle_payload, Mapping):
                            predecessor_observation_intent_id = str(
                                lifecycle_payload.get("paper_observation_intent_id", "")
                            ).strip()
                if predecessor_candidate_id and not predecessor_observation_intent_id:
                    for intent in ForwardTestRegistry(self.store).list_observation_intents():
                        config = intent.config if isinstance(intent.config, Mapping) else {}
                        if str(config.get("candidate_id", "")).strip() == predecessor_candidate_id:
                            predecessor_observation_intent_id = str(
                                intent.experiment_id
                            ).strip()
                            break
                handoff = {
                    "version": "predeclared-observation-v1",
                    "predecessor_queue_id": previous.item_id,
                    "predecessor_dedupe_key": previous.dedupe_key,
                    "predecessor_status": previous.status.value,
                    "predecessor_last_error": previous.last_error,
                    "predecessor_candidate_id": predecessor_candidate_id or None,
                    "predecessor_observation_intent_id": (
                        predecessor_observation_intent_id or None
                    ),
                    "predecessor_profitability_inherited": False,
                    "predecessor_allocation_authority_inherited": False,
                }
                existing = existing_successors.get(
                    (previous.item_id, str(handoff["version"]))
                )
                if existing is not None:
                    successors.append(existing)
                    continue
                successor_proposal = dict(previous.payload)
                successor_proposal["observation_handoff"] = handoff
                successor_proposal["predeclared_successor"] = True
                try:
                    successors.extend(
                        self.enqueue_predeclared_starting_set(
                            successor_proposal,
                            strategies=(strategy,),
                            priority=0,
                            available_at=now,
                        )
                    )
                except (AutonomousResearchError, ResearchBusPermissionError, TypeError, ValueError, RuntimeError):
                    continue
            if callable(state_setter):
                next_state = {
                    "schema_version": "autonomous-predeclared-successor-v1",
                    "updated_at": ensure_utc(now).isoformat(),
                    "cursor": (
                        {
                            "priority": int(getattr(last_scanned, "priority", 0)),
                            "created_at": (
                                last_scanned.created_at.isoformat()
                                if isinstance(last_scanned.created_at, datetime)
                                else str(last_scanned.created_at or "")
                            ),
                            "item_id": last_scanned.item_id,
                        }
                        if last_scanned is not None
                        else None
                    ),
                }
                try:
                    state_setter(_PREDECLARED_SUCCESSOR_STATE_NAME, next_state)
                except (TypeError, ValueError, RuntimeError):
                    pass
            return tuple(successors)
        early_successors = enqueue_successors()
        expected_dataset_id = "Polymarket-historical"
        list_catalog = getattr(self.store, "list_dataset_catalog", None)
        if not callable(list_catalog):
            evidence = self._predeclared_seed_blocker(
                blocker="DATASET_CATALOG_MISSING",
                detail="store has no persisted historical dataset catalog",
                dataset_id=expected_dataset_id,
                dataset_version=None,
            )
            self._persist_predeclared_seed_evidence(
                evidence,
                dataset_id=expected_dataset_id,
                dataset_version=None,
            )
            return early_successors
        try:
            catalogs = list_catalog(market_type="prediction", limit=128)
        except Exception as exc:
            evidence = self._predeclared_seed_blocker(
                blocker="DATASET_CATALOG_UNAVAILABLE",
                detail=f"historical dataset catalog could not be loaded: {exc}",
                dataset_id=expected_dataset_id,
                dataset_version=None,
            )
            self._persist_predeclared_seed_evidence(
                evidence,
                dataset_id=expected_dataset_id,
                dataset_version=None,
            )
            return early_successors
        if not isinstance(catalogs, Sequence):
            evidence = self._predeclared_seed_blocker(
                blocker="DATASET_CATALOG_INVALID",
                detail="historical dataset catalog result is not a sequence",
                dataset_id=expected_dataset_id,
                dataset_version=None,
            )
            self._persist_predeclared_seed_evidence(
                evidence,
                dataset_id=expected_dataset_id,
                dataset_version=None,
            )
            return early_successors
        def catalog_instrument(item: Mapping[str, Any]) -> str:
            return str(item.get("instrument", "")).strip().upper()

        def catalog_version(item: Mapping[str, Any]) -> str:
            return str(item.get("dataset_version") or item.get("version") or "").strip()

        def complete(item: Any) -> bool:
            if not isinstance(item, Mapping):
                return False
            try:
                metadata = item.get("metadata")
                metadata = metadata if isinstance(metadata, Mapping) else {}
                metadata_instrument = str(metadata.get("instrument", "")).strip().upper()
                return (
                    bool(str(item.get("dataset_id", "")).strip())
                    and bool(catalog_version(item))
                    and catalog_version(item).casefold() not in _MUTABLE_DATASET_VERSION_ALIASES
                    and str(item.get("source_type", "")).strip().upper() == "HISTORICAL"
                    and str(item.get("market_type", "")).strip().lower() == MarketType.PREDICTION.value
                    and catalog_instrument(item) == "POLYMARKET"
                    and (not metadata_instrument or metadata_instrument == catalog_instrument(item))
                    and _finite(item.get("completeness"), 0.0) >= 1.0
                    and int(item.get("row_count", 0) or 0) > 0
                    and not item.get("missing_ranges")
                )
            except (TypeError, ValueError, OverflowError):
                return False
        catalog = next(
            (
                item
                for item in catalogs
                if isinstance(item, Mapping)
                and str(item.get("dataset_id", "")).strip() == expected_dataset_id
            ),
            None,
        )
        if catalog is None:
            evidence = self._predeclared_seed_blocker(
                blocker="DATASET_CATALOG_MISSING",
                detail=f"no historical Polymarket catalog for {expected_dataset_id}",
                dataset_id=expected_dataset_id,
                dataset_version=None,
            )
            self._persist_predeclared_seed_evidence(
                evidence,
                dataset_id=expected_dataset_id,
                dataset_version=None,
            )
            return early_successors
        dataset_version = catalog_version(catalog)
        instrument = catalog_instrument(catalog)
        if not complete(catalog):
            source_type = str(catalog.get("source_type", "")).strip().upper()
            market_type = str(catalog.get("market_type", "")).strip().lower()
            if instrument != "POLYMARKET":
                detail = (
                    f"historical dataset catalog instrument {instrument or '<missing>'} "
                    f"does not normalize to POLYMARKET for {expected_dataset_id}"
                )
            elif dataset_version.casefold() in _MUTABLE_DATASET_VERSION_ALIASES:
                detail = (
                    f"historical dataset catalog version {dataset_version!r} is a mutable alias; "
                    "an immutable dataset version is required"
                )
            elif source_type != "HISTORICAL":
                detail = (
                    f"dataset catalog source_type {source_type or '<missing>'} "
                    f"is not HISTORICAL for {expected_dataset_id}"
                )
            elif market_type != MarketType.PREDICTION.value:
                detail = (
                    f"dataset catalog market_type {market_type or '<missing>'} "
                    f"is not prediction for {expected_dataset_id}"
                )
            else:
                detail = f"historical dataset catalog is incomplete for {expected_dataset_id}"
            evidence = self._predeclared_seed_blocker(
                blocker="DATASET_CATALOG_INVALID",
                detail=detail,
                dataset_id=expected_dataset_id,
                dataset_version=dataset_version or None,
                catalog=catalog,
            )
            self._persist_predeclared_seed_evidence(
                evidence,
                dataset_id=expected_dataset_id,
                dataset_version=dataset_version or None,
            )
            return early_successors
        dataset_id = str(catalog.get("dataset_id", "")).strip()
        instrument = catalog_instrument(catalog)
        market_scope = {
            "schema_version": "1",
            "mode": "RULE_BASED_MARKETS",
            # PRICE_PROXY rows are intentionally compact.  The bounded scope
            # uses the catalog's attested instrument identity; liquidity and
            # spread are current-book evidence, not historical price-path
            # inputs.
            "instrument": instrument,
            "filters": {},
            "regime_restrictions": {},
            "provenance": "canonical",
        }
        methodology = {
            "research_mode": "PRICE_PROXY_RESEARCH",
            "initial_cash": 10_000.0,
            "allocation": 0.25,
            "predeclared_starting_set": True,
        }
        assumptions = {
            "version": "price-proxy-v1",
            "fee_bps": 10.0,
            "slippage_bps": 5.0,
            "roundtrip_fee_bps": 20.0,
            "roundtrip_slippage_bps": 10.0,
            "cost_sensitivity": {
                "fee_bps": [10.0, 20.0],
                "slippage_bps": [5.0, 10.0],
            },
        }
        exit_policy = {"type": "fixed_holding_period", "holding_period": 1}
        allowed_features = ["timestamp", "market_id", "yes_mid"]
        proposal = {
            "proposal_id": f"predeclared-seed:{dataset_id}:{dataset_version}",
            "statement": "Evaluate bounded Polymarket price-path momentum and mean reversion.",
            "dataset_selector": {
                "dataset_id": dataset_id,
                "dataset_version": dataset_version,
                "source_type": "HISTORICAL",
            },
            "source": "axiom-autonomous-predeclared",
            "tests": ["bounded chronological price-proxy backtest and validation"],
            "market_type": MarketType.PREDICTION.value,
            "dataset_id": dataset_id,
            "dataset_version": dataset_version,
            "market_scope": market_scope,
            "allowed_features": allowed_features,
            "time_split": "train-validation-holdout",
            "min_samples": 30,
            "min_trades": 20,
            "max_variants": 1,
            "paper_only": True,
            "assumptions": assumptions,
            "exit_policy": exit_policy,
            "methodology": methodology,
            "experiment_plan": {
                "market_type": MarketType.PREDICTION.value,
                "market_scope": market_scope,
                "dataset_id": dataset_id,
                "dataset_version": dataset_version,
                "allowed_features": allowed_features,
                "time_split": "train-validation-holdout",
                "min_samples": 30,
                "min_trades": 20,
                "assumptions": assumptions,
                "exit_policy": exit_policy,
                "methodology": methodology,
            },
        }
        try:
            plan = ExperimentPlan.from_proposal(proposal)
            self._validate_persisted_dataset_provenance(plan)
        except (AutonomousResearchError, ExperimentPlanError, TypeError, ValueError, RuntimeError) as exc:
            attestation_loader = getattr(self.store, "load_dataset_integrity_attestation", None)
            try:
                attestation = (
                    attestation_loader(dataset_id, dataset_version)
                    if callable(attestation_loader)
                    else None
                )
            except Exception:
                attestation = None
            blocker = str(getattr(exc, "reason", "")).strip().upper() or "DATASET_PROVENANCE_INVALID"
            detail = str(getattr(exc, "detail", "")).strip() or str(exc)
            evidence = self._predeclared_seed_blocker(
                blocker=blocker,
                detail=detail,
                dataset_id=dataset_id,
                dataset_version=dataset_version,
                catalog=catalog,
                attestation=attestation if isinstance(attestation, Mapping) else None,
            )
            self._persist_predeclared_seed_evidence(
                evidence,
                dataset_id=dataset_id,
                dataset_version=dataset_version,
            )
            return early_successors
        try:
            queued = self.enqueue_predeclared_starting_set(
                proposal,
                priority=0,
                available_at=now,
            )
        except (AutonomousResearchError, ResearchBusPermissionError, TypeError, ValueError, RuntimeError) as exc:
            blocker = str(getattr(exc, "reason", "")).strip().upper() or "PREDECLARED_SEED_ENQUEUE_FAILED"
            evidence = self._predeclared_seed_blocker(
                blocker=blocker,
                detail=str(getattr(exc, "detail", "")).strip() or str(exc),
                dataset_id=dataset_id,
                dataset_version=dataset_version,
                catalog=catalog,
            )
            self._persist_predeclared_seed_evidence(
                evidence,
                dataset_id=dataset_id,
                dataset_version=dataset_version,
            )
            return early_successors


        return tuple([*queued, *early_successors])
    def __init__(
        self,
        store: AxiomStore,
        *,
        bus: DurableResearchBus | None = None,
        config: AutonomousResearchConfig | None = None,
        clock: Callable[[], datetime] = utc_now,
        current_market_discoverer: Callable[[datetime], Any] | None = None,
    ) -> None:
        self.store = store
        self.bus = bus or DurableResearchBus(store)
        self.config = config or AutonomousResearchConfig()
        self.clock = clock
        self.current_market_discoverer = current_market_discoverer
        self.lifecycle = CandidateLifecycleManager(store, criteria=self.config.promotion_criteria)
        self._campaign_active_state: dict[str, Any] = {}
        self._rolling_last_current_discovery: dict[str, Any] = {
            "status": "NOT_RUN",
        }

    def _rolling_scope_draft(self) -> Mapping[str, Any] | None:
        """Read the unactivated scope draft without granting it authority.

        The operator owns this record.  A draft is usable here only as a
        paper-preview input: the canonical scope/hash pair is recomputed and
        every execution/authorization flag must be explicitly disarmed.
        Active operating policy and portfolio selection are intentionally not
        consulted or modified by this loader.

        The return contract intentionally remains ``Mapping | None``.  The
        bounded validation trace is kept separately so callers that only need
        the usable draft do not accidentally treat an invalid present draft as
        an absent one.
        """
        self._rolling_last_scope_draft_trace = {
            "status": "UNAVAILABLE",
            "reason": "SCOPE_DRAFT_UNAVAILABLE",
            "validation_status": "MISSING",
            "present": False,
        }

        def reject(reason: str, *, status: str = "INVALID") -> None:
            self._rolling_last_scope_draft_trace = {
                "status": "UNAVAILABLE",
                "reason": reason,
                "validation_status": status,
                "present": True,
            }

        loader = getattr(self.store, "get_operator_config", None)
        if not callable(loader):
            reject("SCOPE_DRAFT_LOADER_UNAVAILABLE", status="UNAVAILABLE")
            self._rolling_last_scope_draft_trace["present"] = False
            return None
        try:
            raw = loader("rolling_exploratory_scope_draft", None)
        except (TypeError, ValueError, RuntimeError):
            reject("SCOPE_DRAFT_LOAD_FAILED", status="UNAVAILABLE")
            self._rolling_last_scope_draft_trace["present"] = False
            return None
        if raw is None:
            return None
        if not isinstance(raw, Mapping):
            reject("SCOPE_DRAFT_INVALID_DOCUMENT")
            return None
        if str(raw.get("status", "")).strip().upper() != "DRAFT":
            reject("SCOPE_DRAFT_STATUS_INVALID")
            return None
        draft_id = str(raw.get("draft_id", "")).strip()
        if not draft_id:
            reject("SCOPE_DRAFT_ID_MISSING")
            return None
        if any(
            raw.get(name) is not expected
            for name, expected in (
                ("paper_only", True),
                ("live_execution", False),
                ("allocation_active", False),
                ("canary_armed", False),
            )
        ):
            reject("SCOPE_DRAFT_FLAGS_INVALID")
            return None
        supported_market_types = raw.get("supported_market_types")
        if isinstance(supported_market_types, (list, tuple)):
            normalized_types = {
                str(value).strip().casefold()
                for value in supported_market_types
                if str(value).strip()
            }
            if normalized_types and "prediction" not in normalized_types:
                reject("SCOPE_DRAFT_MARKET_TYPE_UNSUPPORTED")
                return None
        source_scope = raw.get("scope")
        if not isinstance(source_scope, Mapping):
            reject("SCOPE_DRAFT_SCOPE_INVALID")
            return None
        try:
            scope = normalize_market_scope(source_scope)
        except (TypeError, ValueError, ExperimentPlanError):
            reject("SCOPE_DRAFT_SCOPE_INVALID")
            return None
        declared_hash = str(raw.get("scope_hash", "")).strip()
        declared_version = str(raw.get("scope_version", "")).strip()
        if declared_hash != scope.scope_hash:
            reject("SCOPE_DRAFT_SCOPE_HASH_MISMATCH")
            return None
        if declared_version != scope.scope_version:
            reject("SCOPE_DRAFT_SCOPE_VERSION_MISMATCH")
            return None
        declared_draft_hash = str(raw.get("draft_hash", "")).strip()
        if declared_draft_hash != _rolling_hash(
            {key: value for key, value in raw.items() if key != "draft_hash"}
        ):
            reject("SCOPE_DRAFT_HASH_MISMATCH")
            return None
        # Preserve the canonical draft fields and any bounded provenance
        # supplied by the operator; strategy/setup material is never inferred
        # from active configuration.
        result = {
            **dict(raw),
            "draft_id": draft_id,
            "draft_hash": declared_draft_hash,
            "status": "DRAFT",
            "scope": scope.as_dict(),
            "scope_hash": scope.scope_hash,
            "scope_version": scope.scope_version,
            "paper_only": True,
            "live_execution": False,
            "allocation_active": False,
            "canary_armed": False,
        }
        for key in (
            "strategy_definitions",
            "canonical_strategy_definitions",
            "supported_templates",
            "templates",
            "strategies",
            "operational_setups",
            "setup_definitions",
            "policy_provenance",
            "supported_market_types",
            "category_restriction",
            "exclusions",
            "provenance",
        ):
            value = raw.get(key)
            if value is not None:
                result[key] = value
        self._rolling_last_scope_draft_trace = {
            "status": "VALID",
            "reason": "SCOPE_DRAFT_VALID",
            "validation_status": "VALID",
            "present": True,
            "draft_id": draft_id,
            "draft_hash": declared_draft_hash,
            "scope_hash": scope.scope_hash,
            "scope_version": scope.scope_version,
        }
        return result

    @staticmethod
    def _rolling_draft_strategy_specs(
        draft: Mapping[str, Any],
    ) -> tuple[Mapping[str, Any], ...]:
        """Extract at most the supported paper-preview definitions from draft."""
        values: Any = None
        for key in (
            "strategy_definitions",
            "canonical_strategy_definitions",
            "supported_templates",
            "templates",
            "strategies",
        ):
            candidate = draft.get(key)
            if candidate is not None:
                values = candidate
                break
        if values is None:
            values = PREDECLARED_STRATEGY_STARTING_SET
        if isinstance(values, Mapping):
            values = values.get("records", values.get("rows", values.get("items", (values,))))
        if not isinstance(values, (list, tuple)):
            return ()
        return tuple(item for item in values[:_EXPLORATORY_MEMBER_MAX] if isinstance(item, Mapping))

    def _rolling_scope_draft_documents(
        self,
        now: datetime,
    ) -> tuple[tuple[dict[str, Any], ...], Mapping[str, Any]]:
        """Materialize a bounded paper preview from the operator's draft."""
        draft = self._rolling_scope_draft()
        if draft is None:
            trace = getattr(self, "_rolling_last_scope_draft_trace", None)
            return (
                (),
                dict(trace)
                if isinstance(trace, Mapping)
                else {"status": "UNAVAILABLE", "reason": "SCOPE_DRAFT_UNAVAILABLE"},
            )
        documents = self._rolling_system_current_market_documents(now, draft=draft)
        strategy_specs = self._rolling_draft_strategy_specs(draft)
        direct_market_count = int(
            getattr(self, "_rolling_last_current_direct_market_count", 0) or 0
        )
        strategy_spec_count = int(
            getattr(self, "_rolling_last_current_strategy_spec_count", 0) or 0
        )
        invalid_strategy_count = int(
            getattr(self, "_rolling_last_current_invalid_strategy_count", 0) or 0
        )
        discovery = getattr(
            self,
            "_rolling_last_current_discovery",
            {"status": "NOT_RUN"},
        )
        discovery = dict(discovery) if isinstance(discovery, Mapping) else {
            "status": "NO_RESULT",
        }
        discovery_cycle = discovery.get("cycle")
        discovery_cycle = (
            discovery_cycle if isinstance(discovery_cycle, Mapping) else {}
        )
        discovery_status = str(discovery.get("status", "")).upper()
        discovery_ready = (
            discovery_status == "OK"
            and (
                int(discovery_cycle.get("markets_attempted", 0) or 0) > 0
                or str(discovery_cycle.get("discovery_coverage_status", "")).upper()
                in {"NO_MATCHING_MARKETS", "COMPLETE"}
            )
            and str(discovery_cycle.get("discovery_coverage_status", "")).upper()
            != "ERROR"
        )
        try:
            from .experiment_plan import normalize_market_scope

            effective_filter_trace = self._rolling_draft_filter_trace(
                draft,
                normalize_market_scope(draft["scope"]),
                strategy_specs,
            )
        except (TypeError, ValueError, ExperimentPlanError):
            effective_filter_trace = {
                "category_mode": "INVALID",
                "declared_categories": [],
                "effective_categories": [],
                "effective_noncategory_filters": {},
                "active_frozen_historical_scope": {
                    "applied_to_draft_discovery": False,
                },
            }
        evidence_attribution: Mapping[str, Any] = {}
        for document in documents:
            resolution_document = document.get("scope_resolution")
            resolution_document = (
                resolution_document
                if isinstance(resolution_document, Mapping)
                else {}
            )
            resolution_provenance = resolution_document.get("provenance")
            if isinstance(resolution_provenance, Mapping) and isinstance(
                resolution_provenance.get("evidence_attribution"),
                Mapping,
            ):
                evidence_attribution = dict(
                    resolution_provenance["evidence_attribution"]
                )
                break

        all_documents = tuple(
            document for document in documents if isinstance(document, Mapping)
        )

        def compatible_bindings(document: Mapping[str, Any]) -> tuple[Mapping[str, Any], ...]:
            raw_bindings = document.get("market_bindings")
            if isinstance(raw_bindings, Mapping):
                raw_bindings = (raw_bindings,)
            if not isinstance(raw_bindings, (list, tuple)):
                return ()
            return tuple(
                binding
                for binding in raw_bindings
                if isinstance(binding, Mapping)
                and str(binding.get("market_id", binding.get("id", ""))).strip()
                and str(binding.get("yes_token_id", binding.get("yes_token", ""))).strip()
                and str(binding.get("no_token_id", binding.get("no_token", ""))).strip()
            )

        materialized_documents = tuple(
            document
            for document in all_documents
            if compatible_bindings(document)
        )
        materialized_market_ids = list(
            dict.fromkeys(
                str(binding.get("market_id", binding.get("id", ""))).strip()
                for document in materialized_documents
                for binding in compatible_bindings(document)
                if str(binding.get("market_id", binding.get("id", ""))).strip()
            )
        )
        compatible_binding_count = sum(
            len(compatible_bindings(document)) for document in materialized_documents
        )
        documents = materialized_documents
        valid_strategy_definition_count = len(all_documents)
        supported_strategy_definition_count = max(
            0,
            strategy_spec_count - invalid_strategy_count,
        )
        trace = {
            "status": "MATERIALIZED" if documents else "NO_SUITABLE_MATERIALIZED_INSTANCE",
            "discovery": discovery,
            "effective_category_filters": effective_filter_trace,
            "draft_id": draft["draft_id"],
            "evidence_attribution": dict(evidence_attribution),
            "scope_hash": draft["scope_hash"],
            "scope_version": draft["scope_version"],
            "draft_hash": draft["draft_hash"],
            "paper_only": True,
            "live_execution": False,
            "allocation_active": False,
            "canary_armed": False,
            "supported_templates": [
                str(
                    item.get(
                        "template",
                        item.get(
                            "family",
                            (
                                item.get("strategy_document", {}).get("family", "")
                                if isinstance(item.get("strategy_document"), Mapping)
                                else ""
                            ),
                        ),
                    )
                ).strip().lower()
                for item in strategy_specs
                if isinstance(item, Mapping)
                and str(
                    item.get(
                        "template",
                        item.get(
                            "family",
                            (
                                item.get("strategy_document", {}).get("family", "")
                                if isinstance(item.get("strategy_document"), Mapping)
                                else ""
                            ),
                        ),
                    )
                ).strip()
            ],
            "strategy_spec_count": strategy_spec_count,
            "supported_strategy_definition_count": supported_strategy_definition_count,
            "valid_strategy_definition_count": valid_strategy_definition_count,
            "invalid_strategy_count": invalid_strategy_count,
            "invalid_strategy_reasons": list(
                getattr(self, "_rolling_last_current_invalid_strategy_reasons", ())
            ),
            "direct_market_count": direct_market_count,
            "compatible_binding_count": compatible_binding_count,
            "materialized_members": len(documents),
            "materialized_member_count": len(documents),
            "materialized_market_count": len(materialized_market_ids),
            "materialized_market_ids": materialized_market_ids,
        }
        if not documents:
            if (
                invalid_strategy_count >= strategy_spec_count
                and strategy_spec_count
            ):
                trace["reason"] = (
                    "INVALID_STRATEGY_SETUP"
                    if "INVALID_STRATEGY_SETUP"
                    in trace.get("invalid_strategy_reasons", ())
                    else "INVALID_STRATEGY_DEFINITIONS"
                )
            elif discovery_status == "PROVIDER_FAILURE":
                trace["reason"] = "DISCOVERY_PROVIDER_FAILURE"
            elif discovery_status == "APPLICATION_ERROR":
                trace["reason"] = "DISCOVERY_APPLICATION_ERROR"
            elif discovery_status == "NO_RESULT":
                trace["reason"] = "DISCOVERY_NO_RESULT"
            elif discovery_status == "RESULT_ERROR":
                trace["reason"] = "DISCOVERY_RESULT_ERROR"
            elif not discovery_ready:
                trace["reason"] = "DISCOVERY_NOT_EXAMINED"
            elif strategy_spec_count == 0:
                trace["reason"] = "NO_SUPPORTED_STRATEGY_TEMPLATES"
            else:
                trace["reason"] = "NO_SUITABLE_MATERIALIZED_INSTANCE"
        return documents, trace

    @staticmethod
    def _rolling_draft_filter_trace(
        draft: Mapping[str, Any],
        scope_policy: Any,
        strategy_specs: Sequence[Mapping[str, Any]],
    ) -> dict[str, Any]:
        """Describe effective discovery filters without inheriting strategy selectors."""
        scope_filters = (
            dict(scope_policy.filters)
            if isinstance(getattr(scope_policy, "filters", None), Mapping)
            else {}
        )
        categories = [
            str(value).strip().casefold()
            for value in getattr(scope_policy, "categories", ())
            if str(value).strip()
        ]
        ignored_sources: list[str] = []
        for index, spec in enumerate(strategy_specs):
            if not isinstance(spec, Mapping):
                continue
            source = spec.get("strategy_document", spec.get("canonical_strategy"))
            source = source if isinstance(source, Mapping) else spec
            market_filters = source.get("market_filters")
            if isinstance(market_filters, Mapping) and any(
                key in market_filters
                for key in ("category", "categories", "tag_id", "tag_ids")
            ):
                ignored_sources.append(f"strategy[{index}].market_filters")
            experiment_plan = source.get("experiment_plan")
            if isinstance(experiment_plan, Mapping):
                nested_scope = experiment_plan.get("market_scope")
                if isinstance(nested_scope, Mapping) and any(
                    key in nested_scope
                    for key in ("category", "categories", "filters", "tag_id", "tag_ids")
                ):
                    ignored_sources.append(f"strategy[{index}].experiment_plan.market_scope")
            selector = source.get("selector", source.get("market_selector"))
            if isinstance(selector, Mapping) and any(
                key in selector for key in ("label", "labels", "tag_id", "tag_ids")
            ):
                ignored_sources.append(f"strategy[{index}].selector")
            if any(key in source for key in ("tag_id", "tag_ids", "gamma_tag_id")):
                ignored_sources.append(f"strategy[{index}].gamma_tag_id")
        policy_provenance = draft.get("policy_provenance")
        policy_provenance = (
            policy_provenance if isinstance(policy_provenance, Mapping) else {}
        )

        def scope_ref(value: Any) -> dict[str, Any]:
            if not isinstance(value, Mapping):
                return {}
            return {
                key: value.get(key)
                for key in ("source", "scope_hash", "scope_version")
                if value.get(key) is not None
            }

        return {
            "category_mode": "UNRESTRICTED" if not categories else "RESTRICTED",
            "declared_categories": categories,
            "effective_categories": categories,
            "effective_category_filter": scope_filters.get("category"),
            "effective_noncategory_filters": {
                str(key): value
                for key, value in scope_filters.items()
                if str(key) not in {"category", "categories"}
            },
            "inherited_category_sources_ignored": sorted(set(ignored_sources)),
            "selector_labels_applied": False,
            "gamma_tag_id_applied": False,
            "profitability_filters_inherited": False,
            "active_frozen_historical_scope": {
                "active": scope_ref(policy_provenance.get("active_scope")),
                "frozen": scope_ref(policy_provenance.get("frozen_scope")),
                "applied_to_draft_discovery": False,
            },
        }
    def _rolling_system_current_market_documents(
        self,
        now: datetime,
        *,
        draft: Mapping[str, Any] | None = None,
    ) -> tuple[dict[str, Any], ...]:
        """Create canonical paper identities from bounded current evidence.

        ``draft`` is an explicitly disarmed operator preview.  It follows the
        same fresh tracked-market checks as the active system route, but never
        reads or changes active/frozen market authority.
        """
        draft_preview = isinstance(draft, Mapping)
        self._rolling_last_current_direct_market_count = 0
        self._rolling_last_current_strategy_spec_count = 0
        self._rolling_last_current_invalid_strategy_count = 0
        self._rolling_last_current_invalid_strategy_reasons: list[str] = []
        tracked_loader = getattr(self.store, "tracked_polymarket_markets", None)
        resolver_saver = getattr(self.store, "save_market_scope_resolution", None)
        loader = getattr(self.store, "get_operator_config", None)
        if not callable(tracked_loader):
            return ()
        if draft_preview:
            operating = draft
        else:
            if not callable(loader):
                return ()
            try:
                operating = loader("rolling_exploratory_operating_policy", None)
            except (TypeError, ValueError, RuntimeError):
                operating = None
        if not isinstance(operating, Mapping):
            return ()
        if not draft_preview:
            if str(operating.get("mode", "")).strip().upper() != "EXPLORATORY_LIVE":
                return ()
            try:
                if loader("rolling_exploratory_bootstrap_required", False) is not True:
                    return ()
                active = loader("rolling_admission_policy_active", None)
                validate_system_exploratory_admission_policy(
                    active if isinstance(active, Mapping) else None,
                    operating,
                    self._rolling_risk_binding(self._rolling_policy()),
                )
            except (AttributeError, TypeError, ValueError, RuntimeError):
                return ()
        scope = operating.get("scope")
        if not isinstance(scope, Mapping):
            return ()
        try:
            from .experiment_plan import normalize_market_scope
            from .market_scope import resolve_market_scope

            # ``bounded_pool_cap`` is an operating-policy transport bound and
            # ``provenance`` is an operating source label, not scope-policy
            # authority. Keep both out of canonical scope hashing so a fresh
            # current-market resolution remains schema-valid.
            scope_for_resolution = {
                key: value
                for key, value in scope.items()
                if str(key) not in {"bounded_pool_cap", "provenance"}
            }
            scope_policy = normalize_market_scope(scope_for_resolution)
        except (ImportError, AttributeError, TypeError, ValueError):
            return ()
        try:
            tracked = tracked_loader(
                active_only=True,
                now=ensure_utc(now),
                include_payload=True,
                limit=_EXPLORATORY_POOL_CAP,
            )
        except (AttributeError, TypeError, ValueError, RuntimeError):
            tracked = ()
        records: list[dict[str, Any]] = []
        for item in tracked or ():
            if not isinstance(item, Mapping):
                continue
            payload = item.get("payload")
            payload = dict(payload) if isinstance(payload, Mapping) else {}
            metadata = payload.get("metadata")
            metadata = dict(metadata) if isinstance(metadata, Mapping) else {}
            snapshot = payload.get("snapshot")
            snapshot = dict(snapshot) if isinstance(snapshot, Mapping) else {}
            record = {**payload, **metadata, **snapshot}
            record["market_id"] = item.get("market_id", record.get("market_id"))
            record["observed_at"] = (
                item.get("observed_at", record.get("observed_at"))
            )
            def raw_value(name: str) -> Any:
                for source in (record, payload, metadata, snapshot):
                    if isinstance(source, Mapping) and source.get(name) is not None:
                        return source.get(name)
                return None

            original_provider = str(raw_value("provider") or raw_value("source") or "").strip()
            original_source_type = str(raw_value("source_type") or "").strip().upper()
            original_instrument = str(
                raw_value("instrument") or raw_value("instrument_type") or ""
            ).strip().casefold()
            if (
                original_provider.casefold() != "polymarket"
                or original_source_type not in {"CURRENT", "FORWARD_COLLECTED"}
                or (
                    original_instrument
                    and original_instrument
                    not in {
                        "polymarket",
                        "prediction",
                        "prediction_market",
                        "predictionmarket",
                        "market",
                    }
                )
            ):
                continue
            # The resolver requires a current authority projection, but the
            # original provider/source/instrument are validated and retained
            # verbatim. Generic prediction labels do not override the venue
            # authority established by the exact Polymarket provider.
            record["original_provider"] = original_provider
            record["original_source_type"] = original_source_type
            record["original_instrument"] = original_instrument
            record.pop("instrument", None)
            record.pop("instrument_type", None)
            record["source_type"] = "CURRENT"
            record["payload"] = {
                key: value
                for key, value in payload.items()
                if key not in {"instrument", "instrument_type", "source_type"}
            }
            record["payload"]["source_type"] = "CURRENT"
            record["metadata"] = {
                key: value
                for key, value in metadata.items()
                if key not in {"instrument", "instrument_type", "source_type"}
            }
            record["snapshot"] = {
                key: value
                for key, value in snapshot.items()
                if key not in {"instrument", "instrument_type", "source_type"}
            }
            record["source_type"] = "CURRENT"
            record["instrument"] = "POLYMARKET"
            records.append(record)
        candidate_prefix = (
            str(operating.get("draft_id", "")).strip()
            if draft_preview
            else SYSTEM_EXPLORATORY_ADMISSION_ID
        )
        if not candidate_prefix:
            return ()
        try:
            resolution = resolve_market_scope(
                candidate_prefix,
                {"market_scope": scope_policy.as_dict()},
                records,
                resolved_at=ensure_utc(now),
                max_matches=_EXPLORATORY_POOL_CAP,
                max_markets=_EXPLORATORY_POOL_CAP,
            )
        except (TypeError, ValueError, RuntimeError):
            return ()
        resolution_mapping = (
            resolution.as_dict()
            if hasattr(resolution, "as_dict") and callable(resolution.as_dict)
            else {}
        )
        matched = resolution_mapping.get(
            "matched_markets",
            resolution_mapping.get("resolved_markets", ()),
        )
        if not isinstance(matched, (list, tuple)):
            matched = ()

        def depth_valid(value: Any, token_id: str | None = None) -> bool:
            if not isinstance(value, Mapping):
                return False
            attached_token = value.get("token_id", value.get("asset_id"))
            if (
                token_id
                and attached_token not in (None, "")
                and str(attached_token).strip() != token_id
            ):
                return False
            for side in ("bids", "asks"):
                levels = value.get(side)
                if not isinstance(levels, (list, tuple)):
                    return False
                if not any(
                    isinstance(level, Mapping)
                    and _rolling_number(level.get("price", level.get("px"))).is_finite()
                    and _rolling_number(level.get("size", level.get("quantity", level.get("qty")))).is_finite()
                    and _rolling_number(level.get("price", level.get("px"))) > 0
                    and _rolling_number(level.get("size", level.get("quantity", level.get("qty")))) > 0
                    for level in levels
                ):
                    return False
            return True

        def token_books(
            record: Mapping[str, Any],
            item: Mapping[str, Any],
        ) -> tuple[tuple[str, Mapping[str, Any]], ...]:
            result: list[tuple[str, Mapping[str, Any]]] = []
            for alias, token_key in (
                ("yes", "yes_token_id"),
                ("no", "no_token_id"),
            ):
                token_id = str(item.get(token_key, "")).strip()
                found: Mapping[str, Any] | None = None
                for source in (item, record, record.get("snapshot"), record.get("payload")):
                    if not isinstance(source, Mapping):
                        continue
                    for name in ("order_books", "books"):
                        books = source.get(name)
                        if isinstance(books, Mapping):
                            for key in (token_id, alias, alias.upper()):
                                candidate = books.get(key)
                                if isinstance(candidate, Mapping):
                                    found = candidate
                                    break
                        if found is not None:
                            break
                    if found is None:
                        for name in (
                            f"{alias}_order_book",
                            f"{alias}_book",
                        ):
                            candidate = source.get(name)
                            if isinstance(candidate, Mapping):
                                found = candidate
                                break
                    if found is None:
                        for name in ("order_book", "book"):
                            candidate = source.get(name)
                            if not isinstance(candidate, Mapping):
                                continue
                            exact = candidate.get(token_id)
                            if isinstance(exact, Mapping):
                                found = exact
                                break
                            nested = candidate.get(alias, candidate.get(alias.upper()))
                            if isinstance(nested, Mapping):
                                found = nested
                                break
                            if "bids" in candidate or "asks" in candidate:
                                # A single unlabelled snapshot book is the
                                # venue's paired YES/NO projection.
                                found = candidate
                                break
                    if found is not None:
                        break
                if not token_id or not isinstance(found, Mapping):
                    return ()
                result.append((token_id, found))
            return tuple(result)

        def direct_record_valid(item: Mapping[str, Any]) -> bool:
            market_id = str(item.get("market_id", item.get("id", ""))).strip()
            record = records_by_market.get(market_id)
            if not isinstance(record, Mapping):
                return False
            metadata = record.get("metadata")
            snapshot = record.get("snapshot")
            if not isinstance(metadata, Mapping) or not isinstance(snapshot, Mapping):
                return False
            observed_at = parse_timestamp(record.get("observed_at"))
            if (
                observed_at is None
                or observed_at > ensure_utc(now)
                or (
                    ensure_utc(now) - ensure_utc(observed_at)
                ).total_seconds()
                > _EXPLORATORY_MARKET_FRESHNESS_SECONDS
            ):
                return False
            yes_token_id = str(item.get("yes_token_id", "")).strip()
            no_token_id = str(item.get("no_token_id", "")).strip()
            condition_id = str(item.get("condition_id", "")).strip()
            if (
                not yes_token_id
                or not no_token_id
                or not condition_id
                or str(record.get("yes_token_id", "")).strip() != yes_token_id
                or str(record.get("no_token_id", "")).strip() != no_token_id
                or str(record.get("condition_id", "")).strip() != condition_id
                or str(metadata.get("market_id", "")).strip() != market_id
            ):
                return False
            books = token_books(record, item)
            return len(books) == 2 and all(
                depth_valid(book, token_id) for token_id, book in books
            )
        records_by_market = {
            str(record.get("market_id", "")).strip(): record
            for record in records
            if str(record.get("market_id", "")).strip()
        }

        direct_markets = [
            item
            for item in matched
            if isinstance(item, Mapping)
            and str(item.get("market_id", item.get("id", ""))).strip()
            and direct_record_valid(item)
        ][: _EXPLORATORY_POOL_CAP]
        self._rolling_last_current_direct_market_count = len(direct_markets)
        market_ids = tuple(
            str(item.get("market_id", item.get("id", ""))).strip()
            for item in direct_markets
        )
        discovery = getattr(self, "_rolling_last_current_discovery", {})
        discovery_cycle = (
            discovery.get("cycle")
            if isinstance(discovery, Mapping)
            else None
        )
        discovery_cycle = (
            discovery_cycle if isinstance(discovery_cycle, Mapping) else {}
        )
        cycle_started = parse_timestamp(discovery_cycle.get("started_at"))
        cycle_ended = parse_timestamp(discovery_cycle.get("ended_at"))
        current_collected_market_ids: list[str] = []
        reused_fresh_market_ids: list[str] = []
        reused_stale_market_ids: list[str] = []
        for item in matched:
            if not isinstance(item, Mapping):
                continue
            market_id = str(item.get("market_id", item.get("id", ""))).strip()
            record = records_by_market.get(market_id)
            if not market_id or not isinstance(record, Mapping):
                continue
            observed_at = parse_timestamp(record.get("observed_at"))
            if observed_at is None:
                continue
            if (
                cycle_started is not None
                and observed_at >= cycle_started
                and (cycle_ended is None or observed_at <= cycle_ended)
            ):
                current_collected_market_ids.append(market_id)
            elif (
                ensure_utc(now) - observed_at
            ).total_seconds() <= _EXPLORATORY_MARKET_FRESHNESS_SECONDS:
                reused_fresh_market_ids.append(market_id)
            else:
                reused_stale_market_ids.append(market_id)
        partial_collection_failure = (
            str(discovery.get("status", "")).strip().upper()
            in {"PROVIDER_FAILURE", "RESULT_ERROR", "APPLICATION_ERROR"}
            if isinstance(discovery, Mapping)
            else False
        ) or any(
            int(discovery_cycle.get(name, 0) or 0) > 0
            for name in ("errors", "provider_failures", "provider_timeouts")
        )
        evidence_attribution = {
            "current_collected_market_ids": list(
                dict.fromkeys(current_collected_market_ids)
            ),
            "reused_fresh_market_ids": list(
                dict.fromkeys(reused_fresh_market_ids)
            ),
            "reused_stale_market_ids": list(
                dict.fromkeys(reused_stale_market_ids)
            ),
            "partial_collection_failure": bool(partial_collection_failure),
        }

        draft_filter_trace = (
            self._rolling_draft_filter_trace(
                draft,
                scope_policy,
                self._rolling_draft_strategy_specs(draft),
            )
            if draft_preview and isinstance(draft, Mapping)
            else {}
        )
        resolution_mapping["provenance"] = {
            **(
                dict(resolution_mapping.get("provenance"))
                if isinstance(resolution_mapping.get("provenance"), Mapping)
                else {}
            ),
            "source": (
                "rolling-scope-draft"
                if draft_preview
                else "system-bootstrap-current-market"
            ),
            "effective_category_filters": draft_filter_trace,
            "evidence_attribution": dict(evidence_attribution),
            **(
                {
                    "draft_id": str(operating.get("draft_id", "")).strip(),
                    "draft_hash": str(operating.get("draft_hash", "")).strip(),
                    "draft_bound": True,
                    "scope_hash": scope_policy.scope_hash,
                    "scope_version": scope_policy.scope_version,
                    "market_bindings": [
                        dict(binding) for binding in (
                            {
                                "market_id": str(item.get("market_id", item.get("id", ""))).strip(),
                                "condition_id": str(item.get("condition_id", "")).strip(),
                                "yes_token_id": str(item.get("yes_token_id", "")).strip(),
                                "no_token_id": str(item.get("no_token_id", "")).strip(),
                            }
                            for item in direct_markets
                        )
                    ],
                    "supported_market_types": list(
                        operating.get("supported_market_types", ())
                    )
                    if isinstance(operating.get("supported_market_types"), (list, tuple))
                    else [],
                    "exclusions": list(operating.get("exclusions", ()))
                    if isinstance(operating.get("exclusions"), (list, tuple))
                    else [],
                }
                if draft_preview
                else {}
            ),
            "transport": "PolymarketCollector",
            "original_market_provenance": [
                {
                    "market_id": str(item.get("market_id", item.get("id", ""))).strip(),
                    "provider": records_by_market[
                        str(item.get("market_id", item.get("id", ""))).strip()
                    ].get("original_provider"),
                    "source_type": records_by_market[
                        str(item.get("market_id", item.get("id", ""))).strip()
                    ].get("original_source_type"),
                    "instrument": records_by_market[
                        str(item.get("market_id", item.get("id", ""))).strip()
                    ].get("original_instrument"),
                }
                for item in direct_markets
                if str(item.get("market_id", item.get("id", ""))).strip()
                in records_by_market
            ],
            "projected_market_provenance": [
                {
                    "market_id": str(record.get("market_id", "")).strip(),
                    "provider": record.get("original_provider"),
                    "source_type": record.get("original_source_type"),
                    "instrument": record.get("original_instrument"),
                }
                for record in records
            ],
            "bounded_pool_cap": _EXPLORATORY_POOL_CAP,
            "direct_market_count": len(direct_markets),
            "discovered_market_ids": [
                str(item.get("market_id", item.get("id", ""))).strip()
                for item in direct_markets
            ],
            "fresh_metadata_required": True,
            "fresh_token_identity_required": True,
            "fresh_token_book_required": True,
        }
        if callable(resolver_saver):
            try:
                resolver_saver(resolution_mapping, if_absent=True)
            except (AttributeError, TypeError, ValueError, RuntimeError):
                pass
        scope_hash = str(resolution_mapping.get("scope_hash", "")).strip()
        scope_version = str(resolution_mapping.get("scope_version", "")).strip()
        resolution_id = str(resolution_mapping.get("resolution_id", "")).strip()
        market_bindings = tuple(
            {
                "market_id": str(item.get("market_id", item.get("id", ""))).strip(),
                "condition_id": str(item.get("condition_id", "")).strip(),
                "yes_token_id": str(item.get("yes_token_id", "")).strip(),
                "no_token_id": str(item.get("no_token_id", "")).strip(),
                **(
                    {"outcome_token_ids": item.get("outcome_token_ids")}
                    if item.get("outcome_token_ids") is not None
                    else {}
                ),
            }
            for item in direct_markets
        )
        draft_hash = (
            str(draft.get("draft_hash", "")).strip()
            if draft_preview and isinstance(draft, Mapping)
            else ""
        )
        documents: list[dict[str, Any]] = []
        def mark_invalid(reason: str) -> None:
            self._rolling_last_current_invalid_strategy_count += 1
            reasons = getattr(self, "_rolling_last_current_invalid_strategy_reasons", [])
            if reason not in reasons:
                reasons.append(reason)
        draft_specs = (
            self._rolling_draft_strategy_specs(draft)
            if draft_preview and isinstance(draft, Mapping)
            else (
                {
                    "template": family,
                    "parameters": {
                        "lookback": 1,
                        "threshold": 0.05,
                    },
                }
                for family in ("momentum", "mean_reversion")
            )
        )
        for spec in draft_specs:
            if not isinstance(spec, Mapping):
                continue
            self._rolling_last_current_strategy_spec_count += 1
            source = spec.get("strategy_document", spec.get("canonical_strategy"))
            if not isinstance(source, Mapping):
                template = str(spec.get("template", spec.get("family", ""))).strip().lower()
                parameters = spec.get("parameters", {})
                parameters = dict(parameters) if isinstance(parameters, Mapping) else {}
                parameters = {
                    str(key): (
                        value[0]
                        if isinstance(value, (list, tuple)) and len(value) == 1
                        else value
                    )
                    for key, value in parameters.items()
                }
                if not template:
                    mark_invalid("INVALID_STRATEGY_DEFINITION")
                    continue
                if template in {"momentum", "mean_reversion"}:
                    parameters.setdefault("entry_predicate", dict(_ABSOLUTE_MOVE_PREDICATE))
                source = {
                    "version": 1,
                    "market_type": "prediction",
                    "family": template,
                    "parameters": parameters,
                    "probability_model": "market-history",
                    "resolution_aware": True,
                    "resolution_inputs": ["market_history"],
                }
            try:
                definition = load_strategy(source)
            except (TypeError, ValueError, RuntimeError):
                mark_invalid("INVALID_STRATEGY_DEFINITION")
                continue
            strategy_document = definition.to_dict()
            family = str(strategy_document.get("family", "")).strip().lower()
            if not family:
                mark_invalid("INVALID_STRATEGY_DEFINITION")
                continue
            metadata = dict(strategy_document.get("metadata") or {})
            metadata.update(
                dict(spec.get("metadata"))
                if isinstance(spec.get("metadata"), Mapping)
                else {}
            )
            metadata.setdefault(
                "research_role",
                (
                    "PRICE_MOMENTUM_ASSESSMENT"
                    if family == "momentum"
                    else (
                        "PRICE_MEAN_REVERSION_ASSESSMENT"
                        if family == "mean_reversion"
                        else "ZERO_EDGE_CONTROL"
                    )
                ),
            )
            strategy_document["metadata"] = metadata
            setup_definitions = (
                draft.get("operational_setups", draft.get("setup_definitions", {}))
                if draft_preview and isinstance(draft, Mapping)
                else {}
            )
            setup_declared = "operational_setup" in spec
            supplied_setup = spec.get("operational_setup")
            if (
                isinstance(setup_definitions, Mapping)
                and family in setup_definitions
            ):
                setup_declared = True
                supplied_setup = setup_definitions.get(family)
            expected_setup = _operational_setup_for_strategy(
                strategy_document,
                {
                    "market_scope": scope_policy.as_dict(),
                    "operating_policy": EXPLORATORY_LIVE_POLICY_VERSION,
                },
            )
            if not isinstance(expected_setup, Mapping):
                mark_invalid("INVALID_STRATEGY_SETUP")
                continue

            if setup_declared:
                if not isinstance(supplied_setup, Mapping):
                    mark_invalid("INVALID_OPERATIONAL_SETUP")
                    continue
                setup = _canonical_operational_document(supplied_setup)
                if (
                    not isinstance(expected_setup, Mapping)
                    or _canonical_binding(setup)
                    != _canonical_binding(_canonical_operational_document(expected_setup))
                ):
                    mark_invalid("OPERATIONAL_SETUP_MISMATCH")
                    continue
                declared_setup_hash = str(
                    spec.get("operational_setup_hash", "")
                ).strip()
                setup_hash = _operational_setup_hash(setup)
                if declared_setup_hash and declared_setup_hash != setup_hash:
                    mark_invalid("OPERATIONAL_SETUP_HASH_MISMATCH")
                    continue
            elif isinstance(expected_setup, Mapping):
                setup = _canonical_operational_document(expected_setup)
                setup_hash = _operational_setup_hash(setup)
            else:
                setup = None
                setup_hash = None
            strategy_hash = _rolling_hash(strategy_document)
            candidate_id = (
                f"{candidate_prefix}:{family}:"
                f"{_rolling_hash({'scope_hash': scope_hash, 'market_bindings': market_bindings}).removeprefix('sha256:')[:16]}"
            )
            strategy_version_id = "strategy-version-" + _rolling_hash(
                {"strategy_hash": strategy_hash, "candidate_id": candidate_id}
            ).removeprefix("sha256:")[:40]
            trial_id = "research-trial-" + _rolling_hash(
                {
                    "candidate_id": candidate_id,
                    "strategy_version_id": strategy_version_id,
                    "scope_hash": scope_hash,
                    "scope_version": scope_version,
                    "market_bindings": market_bindings,
                    "operational_setup_hash": setup_hash,
                }
            ).removeprefix("sha256:")[:40]
            source_label = (
                "rolling-scope-draft"
                if draft_preview
                else "system-bootstrap-current-market"
            )
            draft_id = (
                str(draft.get("draft_id", "")).strip()
                if draft_preview and isinstance(draft, Mapping)
                else ""
            )
            documents.append(
                {
                    "strategy_document": strategy_document,
                    "strategy_hash": strategy_hash,
                    "strategy_id": family,
                    "version": "1",
                    "candidate_id": candidate_id,
                    "strategy_version_id": strategy_version_id,
                    "research_trial_id": trial_id,
                    "market_bindings": [dict(binding) for binding in market_bindings],
                    **(
                        {
                            "draft_id": draft_id,
                            "draft_hash": draft_hash,
                            "draft_bound": True,
                        }
                        if draft_id and draft_hash
                        else {}
                    ),
                    "market_scope": scope_policy.as_dict(),
                    "market_scope_hash": scope_hash,
                    "market_scope_version": scope_version,
                    "scope_resolution": resolution_mapping,
                    "scope_resolution_id": resolution_id,
                    **(
                        {
                            "operational_setup_hash": setup_hash,
                            "operational_setup": setup,
                        }
                        if isinstance(setup, Mapping)
                        else {}
                    ),
                    "holding_period": 1,
                    "exit_policy": {
                        "type": "fixed_holding_period",
                        "holding_period": 1,
                    },
                    "observation_horizon": {
                        "unit": "observations",
                        "count": 1,
                        "semantics": "per_market_observation_count",
                    },
                    "selection_excluded": bool(
                        spec.get("selection_excluded", family == "probability_mispricing")
                    ),
                    "model_document": (
                        dict(spec["model_document"])
                        if isinstance(spec.get("model_document"), Mapping)
                        else {"model_required": False}
                    ),
                    "provenance": {
                        "rolling_research": True,
                        "research_mode": "ROLLING_RESEARCH",
                        "source": source_label,
                        "candidate_id": candidate_id,
                        "scope_resolution_id": resolution_id,
                        "scope_hash": scope_hash,
                        "scope_version": scope_version,
                        "current_market_ids": list(market_ids),
                        "market_bindings": [dict(binding) for binding in market_bindings],
                        "paper_only": True,
                        "live_execution": False,
                        "allocation_active": False,
                        "canary_armed": False,
                        **(
                            {
                                "draft_id": draft_id,
                                "draft_hash": draft_hash,
                                "draft_bound": True,
                            }
                            if draft_id and draft_hash
                            else {}
                        ),
                    },
                    "paper_only": True,
                    "research_only": True,
                    "execution_scope": "OBSERVATION",
                    **(
                        {
                            "draft_id": draft_id,
                            "draft_hash": draft_hash,
                            "draft_bound": True,
                        }
                        if draft_id and draft_hash
                        else {}
                    ),
                }
            )
        return tuple(documents[:_EXPLORATORY_MEMBER_MAX])
    # Rolling portfolio -------------------------------------------------
    def _rolling_strategy_documents(self) -> tuple[dict[str, Any], ...]:
        """Discover mature legacy candidates and validate them for rolling research.

        Legacy strategy rows are never promoted in place.  They are joined to
        their current lifecycle row by the canonical candidate id, then copied
        into an application-owned rolling identity.  Every rejected join is
        recorded as an immutable enrollment decision.
        """
        found: dict[str, dict[str, Any]] = {}
        enrollment_saver = getattr(self.store, "save_rolling_enrollment", None)

        def decode(value: Any) -> Mapping[str, Any]:
            if isinstance(value, Mapping):
                return value
            if isinstance(value, str):
                try:
                    parsed = json.loads(value)
                except (TypeError, ValueError, json.JSONDecodeError):
                    return {}
                return parsed if isinstance(parsed, Mapping) else {}
            return {}

        def compact(value: Any, depth: int = 0) -> Any:
            return _rolling_provenance_compact(value, depth)

        def candidate_id(row: Mapping[str, Any], payload: Mapping[str, Any]) -> str | None:
            values: set[str] = set()
            truncated = False
            for source in (row, payload):
                found_values, source_truncated = _rolling_candidate_values(source)
                values.update(found_values)
                truncated = truncated or source_truncated
            if truncated or len(values) != 1:
                return None
            return sorted(values)[0]

        def source_value(payload: Mapping[str, Any], *names: str) -> str | None:
            for name in names:
                value = _binding_value(payload.get(name))
                if value:
                    return value
            for name in (
                "provenance",
                "experiment_plan",
                "forward_evidence",
                "result",
                "outcome",
                "config",
                "frozen",
                "payload",
                "lineage",
            ):
                child = payload.get(name)
                if isinstance(child, Mapping):
                    value = source_value(child, *names)
                    if value:
                        return value
            return None

        def source_values(payload: Mapping[str, Any], *names: str) -> list[Any]:
            """Collect all declarations instead of silently selecting the first."""
            wanted = {str(name) for name in names}
            values: list[Any] = []
            seen: set[int] = set()
            pending: list[tuple[Any, int]] = [(payload, 0)]
            while pending:
                item, depth = pending.pop()
                if not isinstance(item, Mapping):
                    continue
                marker = id(item)
                if marker in seen or depth > _ROLLING_MAX_PROVENANCE_DEPTH:
                    continue
                seen.add(marker)
                for key, child in item.items():
                    if str(key) in wanted and child is not None:
                        values.append(child)
                    if isinstance(child, Mapping):
                        pending.append((child, depth + 1))
            return values

        def source_plan_value(payload: Mapping[str, Any]) -> str | None:
            direct = source_value(payload, *_ROLLING_MODEL_ID_FIELDS)
            if direct:
                return direct
            values = {
                normalized
                for raw in source_values(payload, "source_trial_id")
                for normalized in [_binding_value(raw)]
                if normalized is not None and normalized.startswith("plan-")
            }
            return next(iter(values)) if len(values) == 1 else None

        def source_trial_value(payload: Mapping[str, Any]) -> str | None:
            direct = source_value(
                payload,
                "research_trial_id",
                "trial_id",
                "forward_test_id",
                "experiment_id",
            )
            if direct:
                return direct
            values = {
                normalized
                for raw in source_values(payload, "source_trial_id")
                for normalized in [_binding_value(raw)]
                if normalized is not None and not normalized.startswith("plan-")
            }
            return next(iter(values)) if len(values) == 1 else None

        def declarations_conflict(
            *payloads: Mapping[str, Any],
        ) -> tuple[bool, str | None]:
            for names in (
                _ROLLING_MODEL_ID_FIELDS,
                _ROLLING_PLAN_HASH_FIELDS,
                _ROLLING_MODEL_HASH_FIELDS,
                _ROLLING_MODEL_HYPOTHESIS_FIELDS,
            ):
                values = [
                    normalized
                    for payload in payloads
                    for raw in source_values(payload, *names)
                    for normalized in [_binding_value(raw)]
                    if normalized is not None
                ]
                if len(set(values)) > 1:
                    return True, names[0]
            plan_values = {
                normalized
                for payload in payloads
                for raw in source_values(payload, "source_trial_id")
                for normalized in [_binding_value(raw)]
                if normalized is not None and normalized.startswith("plan-")
            }
            if len(plan_values) > 1:
                return True, "source_trial_id"
            declared_plan_values = {
                normalized
                for payload in payloads
                for raw in source_values(payload, *_ROLLING_MODEL_ID_FIELDS)
                for normalized in [_binding_value(raw)]
                if normalized is not None
            }
            if plan_values and declared_plan_values and not plan_values.issubset(
                declared_plan_values
            ):
                return True, "source_trial_id"
            trial_values = {
                normalized
                for payload in payloads
                for raw in source_values(
                    payload,
                    "research_trial_id",
                    "trial_id",
                    "source_trial_id",
                    "forward_test_id",
                    "experiment_id",
                )
                for normalized in [_binding_value(raw)]
                if normalized is not None and not normalized.startswith("plan-")
            }
            if len(trial_values) > 1:
                return True, "source_trial_id"
            model_documents = [
                raw
                for payload in payloads
                for raw in source_values(payload, "model_document")
                if raw is not None
            ]
            model_keys: set[str] = set()
            for model in model_documents:
                if not isinstance(model, Mapping):
                    return True, "model_document"
                try:
                    model_keys.add(_canonical_binding(model))
                except (TypeError, ValueError, OverflowError):
                    return True, "model_document"
            if len(model_keys) > 1:
                return True, "model_document"
            return False, None

        def provenance(
            *,
            candidate: str,
            payload: Mapping[str, Any],
            strategy_row: Mapping[str, Any],
            scope: Mapping[str, Any],
            entry: Mapping[str, Any],
            exit_policy: Mapping[str, Any],
        ) -> dict[str, Any]:
            original_rejection = {
                key: compact(payload[key])
                for key in (
                    "rejection_reason",
                    "reason",
                    "reason_code",
                    "status",
                )
                if key in payload
            }
            original_economic = {
                key: compact(payload[key])
                for key in (
                    "economic_result",
                    "economic_outcome",
                    "result",
                    "outcome",
                    "validation",
                    "forward_evidence",
                    "metrics",
                    "net_return",
                    "realized_pnl",
                    "unrealized_pnl",
                )
                if key in payload
            }
            result = {
                "rolling_research": True,
                "research_mode": "RESEARCH",
                "predecessor_candidate_id": candidate,
                "source_candidate_id": candidate,
                "source_trial_id": source_trial_value(payload),
                "plan_id": source_plan_value(payload),
                "plan_hash": source_value(payload, *_ROLLING_PLAN_HASH_FIELDS),
                "hypothesis_id": source_value(payload, *_ROLLING_MODEL_HYPOTHESIS_FIELDS),
                "model_hash": source_value(
                    payload,
                    "model_hash",
                    "frozen_model_hash",
                    "model_document_hash",
                    "frozen_model_document_hash",
                    "version_model_hash",
                ),
                "source_config_hash": source_value(
                    payload,
                    "config_hash",
                    "source_config_hash",
                ),
                "predecessor_strategy_id": _binding_value(strategy_row.get("strategy_id")),
                "predecessor_strategy_version": _binding_value(strategy_row.get("version")),
                "scope": compact(scope),
                "entry_policy": compact(entry),
                "exit_policy": compact(exit_policy),
                "original_economic_outcome": original_economic,
                "original_rejection": original_rejection,
            }
            return _rolling_provenance_bound(result)
        def origin_base(
            *,
            candidate: str,
            payload: Mapping[str, Any],
            strategy_row: Mapping[str, Any],
        ) -> dict[str, Any]:
            original_provenance = (
                compact(payload["provenance"])
                if "provenance" in payload
                else {}
            )
            return {
                "rolling_research": True,
                "predecessor_candidate_id": candidate,
                "source_candidate_id": candidate,
                "plan_id": source_plan_value(payload),
                "plan_hash": source_value(payload, *_ROLLING_PLAN_HASH_FIELDS),
                "hypothesis_id": source_value(payload, *_ROLLING_MODEL_HYPOTHESIS_FIELDS),
                "model_hash": source_value(
                    payload,
                    "model_hash",
                    "frozen_model_hash",
                    "model_document_hash",
                    "frozen_model_document_hash",
                    "version_model_hash",
                ),
                "source_trial_id": source_trial_value(payload),
                "source_config_hash": source_value(
                    payload,
                    "config_hash",
                    "source_config_hash",
                ),
                "source_strategy_hash": source_value(
                    payload,
                    "source_strategy_hash",
                    "strategy_hash",
                ),
                "rolling_strategy_hash": source_value(
                    payload,
                    "rolling_strategy_hash",
                ),
                "predecessor_strategy_id": _binding_value(strategy_row.get("strategy_id")),
                "predecessor_strategy_version": _binding_value(strategy_row.get("version")),
                "original_provenance": original_provenance,
                "original_economic_outcome": {
                    key: compact(payload[key])
                    for key in (
                        "economic_result",
                        "economic_outcome",
                        "result",
                        "outcome",
                        "validation",
                        "forward_evidence",
                        "metrics",
                        "net_return",
                        "realized_pnl",
                        "unrealized_pnl",
                    )
                    if key in payload
                },
                "original_rejection": {
                    key: compact(payload[key])
                    for key in ("rejection_reason", "reason", "reason_code", "status")
                    if key in payload
                },
            }

        def campaign_markers(*sources: Mapping[str, Any]) -> dict[str, Any]:
            marker_names = (
                "campaign_id",
                "campaign_trial_id",
                "campaign_configuration_id",
                "campaign_protocol",
            )
            markers: dict[str, Any] = {}
            seen: set[int] = set()
            visited = 0

            def visit(item: Any, depth: int = 0, parent_key: str | None = None) -> None:
                nonlocal visited
                if isinstance(item, (list, tuple)):
                    if parent_key in _ROLLING_NON_AUTHORITATIVE_ARRAY_KEYS:
                        return
                    if depth > _ROLLING_MAX_PROVENANCE_DEPTH or len(item) > 128:
                        return
                    for child in item:
                        visit(child, depth + 1, parent_key)
                    return
                if not isinstance(item, Mapping):
                    return
                marker = id(item)
                if marker in seen:
                    return
                seen.add(marker)
                visited += 1
                if visited > 512 or depth > _ROLLING_MAX_PROVENANCE_DEPTH:
                    return
                plan = item.get("experiment_plan")
                if isinstance(plan, Mapping):
                    visit(plan, depth + 1, "experiment_plan")
                for name in marker_names:
                    if name in item and name not in markers:
                        markers[name] = compact(item[name])
                source = str(item.get("source", "")).strip().lower()
                if source in {"axiom-finite-campaign", "finite-campaign"}:
                    markers.setdefault("source", item.get("source"))
                for key, child in item.items():
                    key_name = str(key).strip().lower()
                    if key_name == "experiment_plan":
                        continue
                    if (
                        isinstance(child, (list, tuple))
                        and key_name in _ROLLING_NON_AUTHORITATIVE_ARRAY_KEYS
                    ):
                        continue
                    visit(child, depth + 1, key_name)

            for source in sources:
                visit(source)
            return markers

        enrollment_lister = getattr(self.store, "list_rolling_enrollments", None)

        def predecessor_for(candidate: str) -> tuple[str | None, Mapping[str, Any] | None]:
            if not callable(enrollment_lister):
                return None, None
            try:
                records = enrollment_lister(candidate_id=candidate, limit=256)
            except (TypeError, ValueError, RuntimeError):
                return None, None
            if not isinstance(records, (list, tuple)):
                return None, None
            for prior in records:
                if not isinstance(prior, Mapping):
                    continue
                prior_id = _binding_value(prior.get("enrollment_id"))
                prior_version = _binding_value(prior.get("validation_version"))
                if (
                    prior_id
                    and str(prior.get("status", "")).strip().upper() == "EXCLUDED"
                    and prior_version != _ROLLING_ENROLLMENT_VALIDATION_VERSION
                ):
                    return prior_id, prior
            return None, None

        def enrollment_identity(
            *,
            candidate: str,
            status: str,
            reason: str,
            strategy_version_id: str | None,
            research_trial_id: str | None,
        ) -> str:
            material = {
                "candidate_id": candidate,
                "validation_version": _ROLLING_ENROLLMENT_VALIDATION_VERSION,
                "strategy_version_id": strategy_version_id,
                "research_trial_id": research_trial_id,
                "status": status,
                "reason": reason,
            }
            return "rolling-enrollment-" + _rolling_hash(material).removeprefix("sha256:")[:48]

        def decision(
            *,
            candidate: str,
            status: str,
            reason: str,
            origin: Mapping[str, Any],
            strategy_version_id: str | None = None,
            research_trial_id: str | None = None,
        ) -> None:
            if not callable(enrollment_saver):
                return
            normalized_status = str(status).strip().upper()
            predecessor_id, predecessor = predecessor_for(candidate)
            bounded_origin = dict(origin)
            bounded_origin["validation_version"] = _ROLLING_ENROLLMENT_VALIDATION_VERSION
            if predecessor_id:
                bounded_origin["predecessor_enrollment_id"] = predecessor_id
                prior_provenance = predecessor.get("provenance") if isinstance(predecessor, Mapping) else None
                if isinstance(prior_provenance, Mapping):
                    bounded_origin["predecessor_provenance"] = _rolling_provenance_bound(prior_provenance)
            record = {
                "enrollment_id": enrollment_identity(
                    candidate=candidate,
                    status=normalized_status,
                    reason=reason,
                    strategy_version_id=strategy_version_id,
                    research_trial_id=research_trial_id,
                ),
                "candidate_id": candidate,
                "strategy_version_id": strategy_version_id,
                "research_trial_id": research_trial_id,
                "status": normalized_status,
                "reason": reason,
                "validation_version": _ROLLING_ENROLLMENT_VALIDATION_VERSION,
                "predecessor_enrollment_id": predecessor_id,
                "provenance": _rolling_provenance_bound(bounded_origin),
            }
            try:
                enrollment_saver(record)
            except (TypeError, ValueError, RuntimeError):
                # A corrupt legacy row must not prevent other candidates from
                # being discovered.  The immutable source remains untouched.
                return

        def validate_join(
            strategy_row: Mapping[str, Any],
            lifecycle_row: Mapping[str, Any],
        ) -> dict[str, Any] | None:
            strategy_payload = decode(strategy_row.get("strategy_payload"))
            lifecycle_payload = decode(lifecycle_row.get("candidate_payload"))
            row_candidate = _binding_value(lifecycle_row.get("candidate_id"))
            if (
                _rolling_document_is_draft_bound(strategy_row, strategy_payload)
                or _rolling_document_is_draft_bound(lifecycle_row, lifecycle_payload)
            ):
                draft_candidates, _ = _rolling_candidate_values(
                    {
                        "candidate_id": row_candidate,
                        "strategy_payload": strategy_payload,
                        "lifecycle_payload": lifecycle_payload,
                    }
                )
                draft_candidate = row_candidate or (
                    sorted(draft_candidates)[0]
                    if len(draft_candidates) == 1
                    else None
                )
                if draft_candidate:
                    draft_origin = origin_base(
                        candidate=draft_candidate,
                        payload=lifecycle_payload,
                        strategy_row=strategy_row,
                    )
                    draft_origin["draft_bound"] = True
                    decision(
                        candidate=draft_candidate,
                        status="EXCLUDED",
                        reason="DRAFT_BOUND_LEGACY_AUTHORITY",
                        origin=draft_origin,
                    )
                return None
            # Campaign provenance is authoritative and must win before the
            # general identity walk.  Otherwise a large unrelated attestation
            # can mask the required CAMPAIGN_BOUND exclusion.
            if _rolling_campaign_bound(strategy_payload) or _rolling_campaign_bound(lifecycle_payload):
                campaign_candidates, _ = _rolling_candidate_values(
                    {"candidate_id": row_candidate, "payload": lifecycle_payload}
                )
                campaign_candidate = row_candidate or (
                    sorted(campaign_candidates)[0] if len(campaign_candidates) == 1 else None
                )
                if campaign_candidate:
                    campaign_origin = origin_base(
                        candidate=campaign_candidate,
                        payload=lifecycle_payload,
                        strategy_row=strategy_row,
                    )
                    markers = campaign_markers(strategy_payload, lifecycle_payload)
                    campaign_origin.update(markers)
                    campaign_origin["campaign_markers"] = dict(markers)
                    campaign_origin["campaign_excluded"] = True
                    decision(
                        candidate=campaign_candidate,
                        status="EXCLUDED",
                        reason="CAMPAIGN_BOUND",
                        origin=campaign_origin,
                    )
                return None
            lifecycle_candidates, lifecycle_truncated = _rolling_candidate_values(
                {"candidate_id": row_candidate, "payload": lifecycle_payload}
            )
            if lifecycle_truncated or len(lifecycle_candidates) != 1:
                if row_candidate:
                    decision(
                        candidate=row_candidate,
                        status="EXCLUDED",
                        reason="CANDIDATE_IDENTITY_MISMATCH",
                        origin={
                            "rolling_research": True,
                            "predecessor_candidate_id": row_candidate,
                            "source_candidate_id": sorted(lifecycle_candidates),
                        },
                    )
                return None
            candidate = sorted(lifecycle_candidates)[0]
            strategy_candidates, strategy_truncated = _rolling_candidate_values(strategy_payload)
            if strategy_truncated or (strategy_candidates and strategy_candidates != {candidate}):
                decision(
                    candidate=candidate,
                    status="EXCLUDED",
                    reason="CANDIDATE_IDENTITY_MISMATCH",
                    origin={
                        "rolling_research": True,
                        "predecessor_candidate_id": candidate,
                        "source_candidate_id": sorted(strategy_candidates),
                        "source_trial_id": source_trial_value(lifecycle_payload),
                        "original_economic_outcome": {
                            key: compact(lifecycle_payload[key])
                            for key in ("result", "outcome", "economic_result", "economic_outcome")
                            if key in lifecycle_payload
                        },
                        "original_rejection": {
                            key: compact(lifecycle_payload[key])
                            for key in ("rejection_reason", "reason", "reason_code", "status")
                            if key in lifecycle_payload
                        },
                    },
                )
                return None
            conflicting, field_name = declarations_conflict(
                strategy_payload,
                lifecycle_payload,
            )
            if conflicting:
                decision(
                    candidate=candidate,
                    status="EXCLUDED",
                    reason="MODEL_LINEAGE_AMBIGUOUS",
                    origin={
                        "rolling_research": True,
                        "predecessor_candidate_id": candidate,
                        "source_candidate_id": candidate,
                        "lineage_conflict_field": field_name,
                    },
                )
                return None
            lineage_payload = dict(strategy_payload)
            lineage_payload.update(lifecycle_payload)
            base_origin = origin_base(
                candidate=candidate,
                payload=lineage_payload,
                strategy_row=strategy_row,
            )
            stage = str(lifecycle_row.get("stage", "")).strip().upper()
            if stage not in _ROLLING_MATURE_STAGES:
                decision(
                    candidate=candidate,
                    status="EXCLUDED",
                    reason="LIFECYCLE_NOT_MATURE",
                    origin={**base_origin, "lifecycle_stage": stage},
                )
                return None
            source_candidates = (
                strategy_payload.get("strategy_document"),
                strategy_payload.get("strategy"),
                strategy_payload.get("payload"),
                lifecycle_payload.get("strategy_document"),
                lifecycle_payload.get("strategy"),
            )
            source = next(
                (
                    value
                    for value in source_candidates
                    if isinstance(value, Mapping)
                ),
                None,
            )
            if not isinstance(source, Mapping) and any(
                key in strategy_payload
                for key in ("family", "template", "market_type", "parameters")
            ):
                # ``save_strategy`` persists the DSL document directly,
                # whereas rolling-generated rows carry it under
                # ``strategy_document``.  Both are immutable definitions.
                source = strategy_payload
            if not isinstance(source, Mapping):
                decision(
                    candidate=candidate,
                    status="EXCLUDED",
                    reason="STRATEGY_DEFINITION_MISSING",
                    origin=base_origin,
                )
                return None
            try:
                definition = load_strategy(source)
            except (TypeError, ValueError, RuntimeError) as exc:
                decision(
                    candidate=candidate,
                    status="EXCLUDED",
                    reason="STRATEGY_DSL_INVALID",
                    origin={**base_origin, "error": str(exc)[:256]},
                )
                return None
            scope_value = lifecycle_payload.get("market_scope", lifecycle_payload.get("scope"))
            if not isinstance(scope_value, Mapping):
                plan = lifecycle_payload.get("experiment_plan")
                scope_value = plan.get("market_scope") if isinstance(plan, Mapping) else None
            if not isinstance(scope_value, Mapping):
                decision(
                    candidate=candidate,
                    status="EXCLUDED",
                    reason="SCOPE_INVALID",
                    origin={
                        **base_origin,
                        "next_action": "PERSIST_EXPLICIT_MARKET_SCOPE_AND_SCOPE_IDENTITY",
                        "next_work": "PERSIST_EXPLICIT_MARKET_SCOPE_AND_SCOPE_IDENTITY",
                    },
                )
                return None
            try:
                scope_policy = normalize_market_scope(scope_value)
            except (TypeError, ValueError, ExperimentPlanError) as exc:
                decision(
                    candidate=candidate,
                    status="EXCLUDED",
                    reason="SCOPE_INVALID",
                    origin={
                        **base_origin,
                        "error": str(exc)[:256],
                        "next_action": "REPAIR_EXPLICIT_MARKET_SCOPE_AND_SCOPE_IDENTITY",
                        "next_work": "REPAIR_EXPLICIT_MARKET_SCOPE_AND_SCOPE_IDENTITY",
                    },
                )
                return None
            supplied_hash = source_value(lifecycle_payload, "market_scope_hash", "scope_hash")
            supplied_version = source_value(lifecycle_payload, "market_scope_version", "scope_version")
            if supplied_hash and supplied_hash != scope_policy.scope_hash:
                decision(
                    candidate=candidate,
                    status="EXCLUDED",
                    reason="SCOPE_IDENTITY_MISMATCH",
                    origin={
                        **base_origin,
                        "next_action": "REPAIR_MARKET_SCOPE_IDENTITY",
                        "next_work": "REPAIR_MARKET_SCOPE_IDENTITY",
                    },
                )
                return None
            if supplied_version and supplied_version != scope_policy.scope_version:
                decision(
                    candidate=candidate,
                    status="EXCLUDED",
                    reason="SCOPE_IDENTITY_MISMATCH",
                    origin={
                        **base_origin,
                        "next_action": "REPAIR_MARKET_SCOPE_IDENTITY",
                        "next_work": "REPAIR_MARKET_SCOPE_IDENTITY",
                    },
                )
                return None
            plan = lifecycle_payload.get("experiment_plan")
            plan = plan if isinstance(plan, Mapping) else {}
            model_document_value: Any = None
            model_document_present = False
            for model_owner in (lifecycle_payload, strategy_payload, plan):
                if "model_document" not in model_owner:
                    continue
                model_document_present = True
                model_document_value = model_owner.get("model_document")
                if isinstance(model_document_value, Mapping):
                    break
            model_document = (
                dict(model_document_value)
                if model_document_present and isinstance(model_document_value, Mapping)
                else None
            )
            dataset_selector_value = lifecycle_payload.get("dataset_selector")
            if not isinstance(dataset_selector_value, Mapping):
                dataset_selector_value = plan.get("dataset_selector")
            dataset_selector = (
                dict(dataset_selector_value)
                if isinstance(dataset_selector_value, Mapping)
                else {}
            )
            for field_name in ("dataset_id", "dataset_version"):
                selector_names = (
                    ("dataset_version", "version")
                    if field_name == "dataset_version"
                    else ("dataset_id",)
                )
                direct_value = lifecycle_payload.get(field_name)
                plan_value = plan.get(field_name)
                selector_values = [
                    dataset_selector.get(name)
                    for name in selector_names
                    if dataset_selector.get(name) is not None
                    and str(dataset_selector.get(name)).strip()
                ]
                values = [
                    value
                    for value in (direct_value, plan_value, *selector_values)
                    if value is not None and str(value).strip()
                ]
                if len({_canonical_binding(value) for value in values}) > 1:
                    decision(
                        candidate=candidate,
                        status="EXCLUDED",
                        reason="DATASET_SELECTOR_IDENTITY_MISMATCH",
                        origin=base_origin,
                    )
                    return None
                if values:
                    dataset_selector[field_name] = values[0]
            entry_value = lifecycle_payload.get("entry_policy", lifecycle_payload.get("entry"))
            if entry_value is None:
                entry_value = plan.get("entry_policy", plan.get("entry"))
            if entry_value is None:
                entry_value = {"type": "strategy_signal", "family": definition.family}
            if isinstance(entry_value, str):
                entry_value = {"type": entry_value}
            if not isinstance(entry_value, Mapping) or not str(
                entry_value.get("type", entry_value.get("kind", ""))
            ).strip():
                decision(candidate=candidate, status="EXCLUDED", reason="ENTRY_POLICY_INVALID", origin=base_origin)
                return None
            exit_value = lifecycle_payload.get("exit_policy", lifecycle_payload.get("exit"))
            if exit_value is None:
                exit_value = plan.get("exit_policy", plan.get("exit"))
            if exit_value is None:
                exit_value = {"type": "fixed_holding_period", "holding_period": 1}
            if isinstance(exit_value, str):
                exit_value = {"type": exit_value}
            if not isinstance(exit_value, Mapping):
                decision(candidate=candidate, status="EXCLUDED", reason="EXIT_POLICY_INVALID", origin=base_origin)
                return None
            exit_kind = str(exit_value.get("type", exit_value.get("kind", ""))).strip().lower()
            if exit_kind != "fixed_holding_period":
                decision(candidate=candidate, status="EXCLUDED", reason="EXIT_POLICY_INVALID", origin=base_origin)
                return None
            raw_period = exit_value.get(
                "holding_period",
                exit_value.get("bars", exit_value.get("observations", 1)),
            )
            try:
                holding_period = int(raw_period)
            except (TypeError, ValueError, OverflowError):
                holding_period = 0
            if isinstance(raw_period, bool) or holding_period < 1 or holding_period > 10_000:
                decision(candidate=candidate, status="EXCLUDED", reason="EXIT_POLICY_INVALID", origin=base_origin)
                return None
            mode_value = source_value(lifecycle_payload, "enrollment_mode", "research_mode", "mode")
            mode = str(mode_value or "").strip().upper().replace("-", "_")
            if mode in {"LIVE", "CANARY", "EXECUTION", "TRADING"}:
                decision(candidate=candidate, status="EXCLUDED", reason="ENROLLMENT_MODE_NOT_ALLOWED", origin=base_origin)
                return None
            origin = provenance(
                candidate=candidate,
                payload=lineage_payload,
                strategy_row=strategy_row,
                scope=scope_policy.as_dict(),
                entry=dict(entry_value),
                exit_policy={**dict(exit_value), "holding_period": holding_period},
            )
            origin["market_scope"] = scope_policy.as_dict()
            origin["market_scope_hash"] = scope_policy.scope_hash
            origin["market_scope_version"] = scope_policy.scope_version
            if dataset_selector:
                origin["dataset_selector"] = compact(dataset_selector)
                for field_name in ("dataset_id", "dataset_version"):
                    origin[field_name] = dataset_selector[field_name]
            document = definition.to_dict()
            document.pop("strategy_id", None)
            strategy_hash = _rolling_hash(document)
            document["holding_period"] = holding_period
            document["exit_policy"] = {**dict(exit_value), "holding_period": holding_period}
            document["observation_horizon"] = {
                "unit": "observations",
                "count": holding_period,
                "semantics": "per_market_observation_count",
            }
            document["selection_excluded"] = definition.id == "probability_mispricing"
            config_hash = source_value(lifecycle_payload, "config_hash", "source_config_hash")
            computed_strategy_version_id = "strategy-version-" + _rolling_hash(
                {"strategy_hash": strategy_hash, "candidate_id": candidate}
            ).removeprefix("sha256:")[:40]
            declared_strategy_version_id = _binding_value(
                lifecycle_payload.get("strategy_version_id")
            )
            if (
                declared_strategy_version_id is not None
                and declared_strategy_version_id != computed_strategy_version_id
            ):
                decision(
                    candidate=candidate,
                    status="EXCLUDED",
                    reason="STRATEGY_VERSION_IDENTITY_MISMATCH",
                    origin=base_origin,
                    strategy_version_id=declared_strategy_version_id,
                )
                return None
            strategy_version_id = declared_strategy_version_id or computed_strategy_version_id
            trial_identity = {
                "candidate_id": candidate,
                "strategy_version_id": strategy_version_id,
                "source_trial_id": origin.get("source_trial_id"),
                "source_config_hash": config_hash,
            }
            computed_research_trial_id = "research-trial-" + _rolling_hash(
                trial_identity
            ).removeprefix("sha256:")[:40]
            research_trial_id = (
                _binding_value(lifecycle_payload.get("research_trial_id"))
                or _binding_value(lifecycle_payload.get("trial_id"))
                or computed_research_trial_id
            )
            origin["source_config_hash"] = config_hash
            origin["source_strategy_hash"] = (
                base_origin.get("source_strategy_hash") or strategy_hash
            )
            origin["rolling_strategy_hash"] = strategy_hash
            origin["research_trial_id"] = research_trial_id
            origin["validation_version"] = _ROLLING_ENROLLMENT_VALIDATION_VERSION
            origin["mode"] = "OBSERVATION" if stage == "PAPER_FORWARD" else "RESEARCH"
            origin = _rolling_provenance_bound(origin)
            return {
                "strategy_document": document,
                "holding_period": holding_period,
                "exit_policy": {**dict(exit_value), "holding_period": holding_period},
                "observation_horizon": {
                    "unit": "observations",
                    "count": holding_period,
                    "semantics": "per_market_observation_count",
                },
                "selection_excluded": definition.id == "probability_mispricing",
                "model_document": model_document,
                "plan_id": _binding_value(origin.get("plan_id")),
                "model_hash": _binding_value(origin.get("model_hash")),
                "plan_hash": _binding_value(origin.get("plan_hash")),
                "hypothesis_id": _binding_value(origin.get("hypothesis_id")),
                "strategy_id": _binding_value(strategy_row.get("strategy_id")) or definition.id,
                "version": str(strategy_row.get("version") or definition.version),
                "strategy_hash": strategy_hash,
                "config_hash": config_hash,
                "candidate_id": candidate,
                "strategy_version_id": strategy_version_id,
                "research_trial_id": research_trial_id,
                "source_strategy_hash": origin.get("source_strategy_hash"),
                "rolling_strategy_hash": strategy_hash,
                "validation_version": _ROLLING_ENROLLMENT_VALIDATION_VERSION,
                "provenance": origin,
                "enrollment_id": enrollment_identity(
                    candidate=candidate,
                    status="ACCEPTED",
                    reason="MATURE_NONCAMPAIGN_RESEARCH",
                    strategy_version_id=strategy_version_id,
                    research_trial_id=research_trial_id,
                ),
            }

        connection = getattr(self.store, "connection", None)
        execute = getattr(connection, "execute", None)
        rows: list[Mapping[str, Any]] = []
        legacy_query_completed = False
        if callable(execute):
            scan_remaining = _MAX_ROLLING_DISCOVERY_SCAN
            cursor: tuple[Any, ...] | None = None
            mature_stages = tuple(sorted(_ROLLING_MATURE_STAGES))
            while scan_remaining > 0:
                placeholders = ",".join("?" for _ in mature_stages)
                where = f" WHERE UPPER(COALESCE(c.stage,'')) IN ({placeholders})"
                params: list[Any] = list(mature_stages)
                if cursor is not None:
                    where += (
                        " AND (c.updated_at > ? OR "
                        "(c.updated_at = ? AND c.candidate_id > ?) OR "
                        "(c.updated_at = ? AND c.candidate_id = ? AND s.strategy_id > ?) OR "
                        "(c.updated_at = ? AND c.candidate_id = ? AND s.strategy_id = ? AND s.version > ?))"
                    )
                    params.extend(
                        [
                            cursor[0],
                            cursor[0],
                            cursor[1],
                            cursor[0],
                            cursor[1],
                            cursor[2],
                            cursor[0],
                            cursor[1],
                            cursor[2],
                            cursor[3],
                        ]
                    )
                params.append(min(_ROLLING_DISCOVERY_PAGE, scan_remaining))
                try:
                    queried = execute(
                        "SELECT s.strategy_id,s.version,s.payload_json AS strategy_payload,"
                        "c.candidate_id,c.stage,c.payload_json AS candidate_payload,c.updated_at "
                        "FROM strategies AS s JOIN candidate_lifecycle AS c "
                        "ON c.candidate_id=s.strategy_id OR "
                        "c.candidate_id=CASE WHEN json_valid(s.payload_json) "
                        "THEN json_extract(s.payload_json,'$.candidate_id') ELSE NULL END "
                        f"{where} "
                        "ORDER BY c.updated_at,c.candidate_id,s.strategy_id,s.version LIMIT ?",
                        tuple(params),
                    ).fetchall()
                except Exception:
                    rows = []
                    break
                legacy_query_completed = True
                batch = [dict(row) for row in queried or ()]
                if not batch:
                    break
                rows.extend(batch)
                scan_remaining -= len(batch)
                last = batch[-1]
                next_cursor = (
                    last.get("updated_at"),
                    str(last.get("candidate_id", "")),
                    str(last.get("strategy_id", "")),
                    str(last.get("version", "")),
                )
                if cursor is not None and next_cursor <= cursor:
                    break
                cursor = next_cursor
                if len(batch) < _ROLLING_DISCOVERY_PAGE:
                    break
        if not rows and not legacy_query_completed:
            strategy_lister = getattr(self.store, "list_strategies", None)
            lifecycle_lister = getattr(self.store, "load_candidate_lifecycle", None)
            if callable(strategy_lister) and callable(lifecycle_lister):
                def bounded_legacy_rows(loader: Callable[..., Any]) -> tuple[Any, ...]:
                    """Call only adapters that expose an explicit bounded limit."""
                    try:
                        values = loader(limit=_MAX_ROLLING_DISCOVERY_SCAN)
                    except TypeError as exc:
                        raise ValueError(
                            "ROLLING_DISCOVERY_BOUNDED_SOURCE_UNAVAILABLE"
                        ) from exc
                    if isinstance(values, Mapping):
                        values = values.get("records", values.get("rows", (values,)))
                    if values is None or isinstance(values, (str, bytes)):
                        return ()
                    try:
                        return tuple(islice(values, _MAX_ROLLING_DISCOVERY_SCAN))
                    except TypeError:
                        return ()

                try:
                    strategy_rows = bounded_legacy_rows(strategy_lister)
                    lifecycle_rows = bounded_legacy_rows(lifecycle_lister)
                except ValueError as exc:
                    if str(exc) == "ROLLING_DISCOVERY_BOUNDED_SOURCE_UNAVAILABLE":
                        raise
                    strategy_rows, lifecycle_rows = (), ()
                except (TypeError, RuntimeError):
                    strategy_rows, lifecycle_rows = (), ()
                lifecycle_by_id = {
                    str(item.get("candidate_id")).strip(): item
                    for item in lifecycle_rows
                    if (
                        isinstance(item, Mapping)
                        and str(item.get("candidate_id", "")).strip()
                        and str(item.get("stage", "")).strip().upper() in _ROLLING_MATURE_STAGES
                    )
                }
                for item in strategy_rows:
                    if len(rows) >= _MAX_ROLLING_DISCOVERY_SCAN:
                        break
                    if not isinstance(item, Mapping):
                        continue
                    strategy_payload = item.get("strategy", item.get("payload", {}))
                    strategy_id = str(item.get("strategy_id", "")).strip()
                    payload_candidates, _ = _rolling_candidate_values(decode(strategy_payload))
                    candidate_keys = [strategy_id, str(item.get("candidate_id", "")).strip()]
                    candidate_keys.extend(sorted(payload_candidates))
                    lifecycle = next(
                        (lifecycle_by_id.get(key) for key in candidate_keys if key and lifecycle_by_id.get(key)),
                        None,
                    )
                    if lifecycle is None:
                        continue
                    rows.append(
                        {
                            "strategy_id": strategy_id,
                            "version": item.get("version"),
                            "strategy_payload": strategy_payload,
                            "candidate_id": lifecycle.get("candidate_id"),
                            "stage": lifecycle.get("stage"),
                            "candidate_payload": lifecycle.get("payload"),
                        }
                    )
        for row in rows[:_MAX_ROLLING_DISCOVERY_SCAN]:
            item = validate_join(row, row)
            if item is not None:
                found[item["strategy_hash"] + ":" + str(item["candidate_id"])] = item

        # Existing application-owned rolling rows survive a restart even when
        # the legacy source has been compacted or removed.
        if callable(execute):
            try:
                modern_rows = execute(
                    "SELECT payload_json,strategy_version_id FROM strategy_versions "
                    "ORDER BY created_at,strategy_version_id LIMIT ?",
                    (_MAX_ROLLING_STRATEGIES,),
                ).fetchall()
            except Exception:
                modern_rows = ()
            for row in modern_rows or ():
                payload = decode(row["payload_json"])
                provenance = payload.get("provenance")
                provenance = dict(provenance) if isinstance(provenance, Mapping) else {}
                if _rolling_document_is_draft_bound(payload, provenance):
                    continue
                if not _rolling_document_is_marked(payload, provenance):
                    continue
                source = payload.get("strategy_document", payload.get("canonical_strategy"))
                if not isinstance(source, Mapping) or _rolling_campaign_bound(payload):
                    continue
                canonical_candidates, canonical_truncated = _rolling_candidate_values(provenance)
                payload_candidates, payload_truncated = _rolling_candidate_values(payload)
                if (
                    canonical_truncated
                    or payload_truncated
                    or (
                        payload_candidates
                        and canonical_candidates
                        and payload_candidates != canonical_candidates
                    )
                ):
                    continue
                candidates = canonical_candidates or payload_candidates
                if len(candidates) != 1:
                    continue
                try:
                    definition = load_strategy(source)
                except (TypeError, ValueError, RuntimeError):
                    continue
                item = dict(payload)
                item["strategy_document"] = definition.to_dict()
                item["strategy_version_id"] = row["strategy_version_id"]
                item["provenance"] = _rolling_provenance_bound(provenance)
                item["candidate_id"] = sorted(candidates)[0]
                item.setdefault("research_trial_id", provenance.get("research_trial_id"))
                item.setdefault("strategy_hash", _rolling_hash(item["strategy_document"]))
                item["_strategy_version_existing"] = True
                if item.get("research_trial_id"):
                    found.setdefault(
                        str(item["strategy_hash"]) + ":" + str(item["candidate_id"]),
                        item,
                    )
        ordered = sorted(
            found.values(),
            key=lambda item: (
                str(item.get("strategy_hash", "")),
                str(item.get("candidate_id", "")),
            ),
        )
        return tuple(ordered[:_MAX_ROLLING_STRATEGIES])

    def _rolling_persist_strategy_lineage(
        self,
        documents: Sequence[Mapping[str, Any]],
        now: datetime,
    ) -> tuple[dict[str, Any], ...]:
        saver = getattr(self.store, "save_strategy_version", None)
        trial_saver = getattr(self.store, "save_research_trial", None)
        enrollment_saver = getattr(self.store, "save_rolling_enrollment", None)
        enrollment_lister = getattr(self.store, "list_rolling_enrollments", None)

        def predecessor_for(candidate: str) -> tuple[str | None, Mapping[str, Any] | None]:
            if not callable(enrollment_lister):
                return None, None
            try:
                records = enrollment_lister(candidate_id=candidate, limit=256)
            except (TypeError, ValueError, RuntimeError):
                return None, None
            if not isinstance(records, (list, tuple)):
                return None, None
            for prior in records:
                if not isinstance(prior, Mapping):
                    continue
                prior_id = _binding_value(prior.get("enrollment_id"))
                prior_version = _binding_value(prior.get("validation_version"))
                if (
                    prior_id
                    and str(prior.get("status", "")).strip().upper() == "EXCLUDED"
                    and prior_version != _ROLLING_ENROLLMENT_VALIDATION_VERSION
                ):
                    return prior_id, prior
            return None, None
        persisted: list[dict[str, Any]] = []
        for item in documents:
            document = dict(item["strategy_document"])
            strategy_hash = str(item["strategy_hash"])
            candidate_id = str(item.get("candidate_id") or "").strip() or None
            strategy_version_id = str(item.get("strategy_version_id") or "").strip()
            if not strategy_version_id:
                identity = {"strategy_hash": strategy_hash, "candidate_id": candidate_id}
                strategy_version_id = "strategy-version-" + _rolling_hash(identity).removeprefix("sha256:")[:40]
            source_fields = {
                field_name: item[field_name]
                for field_name in (
                    "dataset_id",
                    "dataset_version",
                    "dataset_selector",
                    "dataset_attestation",
                    "dataset_boundary",
                    "market_scope",
                    "market_scope_hash",
                    "market_scope_version",
                    "scope",
                    "scope_hash",
                    "scope_version",
                    "scope_resolution",
                    "scope_resolution_id",
                    "current_market_ids",
                    "market_bindings",
                    "draft_id",
                    "draft_hash",
                    "draft_bound",
                    "plan_id",
                    "source_plan_id",
                    "plan_hash",
                    "hypothesis_id",
                    "model_hash",
                )
                if field_name in item and item[field_name] is not None
            }
            declared_setup = item.get("operational_setup")
            declared_setup_hash = str(item.get("operational_setup_hash", "") or "").strip()
            expected_setup = _operational_setup_for_strategy(document, source_fields)
            if declared_setup is not None or declared_setup_hash:
                if not isinstance(declared_setup, Mapping):
                    raise ValueError("OPERATIONAL_SETUP_INVALID")
                setup = _canonical_operational_document(declared_setup)
                if (
                    not isinstance(expected_setup, Mapping)
                    or _canonical_binding(setup)
                    != _canonical_binding(_canonical_operational_document(expected_setup))
                ):
                    raise ValueError("OPERATIONAL_SETUP_MISMATCH")
                setup_hash = _operational_setup_hash(setup)
                if declared_setup_hash and declared_setup_hash != setup_hash:
                    raise ValueError("OPERATIONAL_SETUP_HASH_MISMATCH")
            else:
                setup = None
                setup_hash = None
            setup_fields = (
                {
                    "operational_setup": setup,
                    "operational_setup_hash": setup_hash,
                }
                if isinstance(setup, Mapping)
                else {}
            )
            model_document = (
                dict(item["model_document"])
                if isinstance(item.get("model_document"), Mapping)
                else None
            )
            if setup_fields:
                model_document = {"model_required": False}
            provenance_values = dict(item.get("provenance") or {})
            for field_name, value in source_fields.items():
                # Preserve both direct and nested declarations.  A
                # contradiction must remain visible to the source-boundary
                # validator rather than being silently overwritten here.
                provenance_values.setdefault(field_name, value)
            top_plan_ids = {
                normalized
                for field_name in _ROLLING_MODEL_ID_FIELDS
                for normalized in [_binding_value(source_fields.get(field_name))]
                if normalized is not None
            }
            nested_plan_ids = {
                normalized
                for field_name in _ROLLING_MODEL_ID_FIELDS
                for normalized in [_binding_value(provenance_values.get(field_name))]
                if normalized is not None
            }
            all_plan_ids = top_plan_ids | nested_plan_ids
            if len(all_plan_ids) > 1:
                raise ValueError("plan lineage identity conflicts")
            linked_plan_id = next(iter(all_plan_ids), None)
            provenance_source_trial = _binding_value(
                provenance_values.get("source_trial_id")
            )
            if (
                provenance_source_trial is not None
                and provenance_source_trial.startswith("plan-")
                and provenance_source_trial == linked_plan_id
            ):
                # A legacy plan reference was historically persisted under
                # source_trial_id.  Keep it as plan provenance, never as a
                # trial identity, once the linked plan is explicit.
                provenance_values.pop("source_trial_id", None)
            provenance = _rolling_provenance_bound(
                {
                    **provenance_values,
                    "rolling_research": True,
                    "research_mode": "ROLLING_RESEARCH",
                    "candidate_id": candidate_id,
                    "source_candidate_id": candidate_id,
                }
            )
            enrollment_mode = str(provenance.get("mode", "RESEARCH")).strip().upper()
            if enrollment_mode not in _ROLLING_ENROLLMENT_MODES:
                enrollment_mode = "RESEARCH"
            record = {
                "strategy_version_id": strategy_version_id,
                "strategy_id": str(item.get("strategy_id", "")).strip() or str(document.get("family", "strategy")),
                "version": str(item.get("version", "1")),
                "code_hash": strategy_hash,
                "strategy_hash": strategy_hash,
                "config_hash": str(item.get("config_hash", strategy_hash)),
                "created_at": now.isoformat(),
                "strategy_document": document,
                "holding_period": item.get("holding_period", document.get("holding_period")),
                "exit_policy": item.get("exit_policy", document.get("exit_policy")),
                "observation_horizon": item.get(
                    "observation_horizon",
                    document.get("observation_horizon"),
                ),
                "selection_excluded": bool(
                    item.get("selection_excluded", document.get("selection_excluded", False))
                ),
                "model_document": model_document,
                "canonical_strategy": document,
                "enrollment_mode": enrollment_mode,
                "provenance": provenance,
                "candidate_id": candidate_id,
                "execution_scope": "OBSERVATION",
                "research_only": True,
                "paper_only": True,
                **setup_fields,
                **source_fields,
            }
            trial_id = str(item.get("research_trial_id") or provenance.get("research_trial_id") or "").strip()
            if not trial_id:
                trial_identity = {
                    "strategy_version_id": strategy_version_id,
                    "candidate_id": candidate_id,
                    "source_trial_id": provenance.get("source_trial_id"),
                    "source_config_hash": provenance.get("source_config_hash"),
                }
                trial_id = "research-trial-" + _rolling_hash(trial_identity).removeprefix("sha256:")[:40]
            trial = {
                "holding_period": item.get("holding_period", document.get("holding_period")),
                "exit_policy": item.get("exit_policy", document.get("exit_policy")),
                "observation_horizon": item.get(
                    "observation_horizon",
                    document.get("observation_horizon"),
                ),
                "selection_excluded": bool(
                    item.get("selection_excluded", document.get("selection_excluded", False))
                ),
                "research_trial_id": trial_id,
                "trial_id": trial_id,
                "strategy_version_id": strategy_version_id,
                "candidate_id": candidate_id,
                "status": "SCHEDULED",
                "created_at": now.isoformat(),
                "trial_kind": "ROLLING_RESEARCH",
                "strategy_hash": strategy_hash,
                "enrollment_mode": enrollment_mode,
                "requested_window_days": [7, 30],
                "rolling_research": True,
                "execution_scope": "OBSERVATION",
                "research_only": True,
                "paper_only": True,
                **setup_fields,
                "payload": {
                    "strategy_document": document,
                    "model_document": model_document,
                    "provenance": provenance,
                    **setup_fields,
                },
            }
            def immutable_match(existing: Any, expected: Mapping[str, Any]) -> bool:
                if not isinstance(existing, Mapping):
                    return False

                def comparable(value: Mapping[str, Any]) -> Mapping[str, Any]:
                    payload = dict(_rolling_payload_without_created_at(value))
                    payload.setdefault("model_document", None)
                    nested = payload.get("payload")
                    if isinstance(nested, Mapping):
                        nested_payload = dict(nested)
                        nested_payload.setdefault("model_document", None)
                        payload["payload"] = nested_payload
                    return payload

                return _canonical_binding(comparable(existing)) == _canonical_binding(
                    comparable(expected)
                )

            try:
                if callable(saver) and not item.get("_strategy_version_existing"):
                    try:
                        saver(record)
                    except ValueError as exc:
                        loader = getattr(self.store, "load_strategy_version", None)
                        existing = loader(strategy_version_id) if callable(loader) else None
                        if not immutable_match(existing, record):
                            raise exc
                if callable(trial_saver):
                    try:
                        trial_saver(trial)
                    except ValueError as exc:
                        loader = getattr(self.store, "load_research_trial", None)
                        existing = loader(trial_id) if callable(loader) else None
                        if not immutable_match(existing, trial):
                            raise exc
            except (TypeError, ValueError, RuntimeError):
                # Persistence failures are retryable.  Do not create a
                # terminal EXCLUDED enrollment while lineage may be partial:
                # the next pass can reconcile exact immutable identities and
                # insert ACCEPTED under the same deterministic enrollment id.
                continue
            if callable(enrollment_saver) and candidate_id:
                predecessor_id, predecessor = predecessor_for(candidate_id)
                accepted_provenance = dict(provenance)
                accepted_provenance["validation_version"] = _ROLLING_ENROLLMENT_VALIDATION_VERSION
                if predecessor_id:
                    accepted_provenance["predecessor_enrollment_id"] = predecessor_id
                    prior_provenance = predecessor.get("provenance") if isinstance(predecessor, Mapping) else None
                    if isinstance(prior_provenance, Mapping):
                        accepted_provenance["predecessor_provenance"] = _rolling_provenance_bound(prior_provenance)
                try:
                    enrollment_saver(
                        {
                            "enrollment_id": item.get("enrollment_id"),
                            "candidate_id": candidate_id,
                            "strategy_version_id": strategy_version_id,
                            "research_trial_id": trial_id,
                            "status": "ACCEPTED",
                            "reason": "MATURE_NONCAMPAIGN_RESEARCH",
                            "validation_version": _ROLLING_ENROLLMENT_VALIDATION_VERSION,
                            "predecessor_enrollment_id": predecessor_id,
                            "provenance": _rolling_provenance_bound(accepted_provenance),
                        }
                    )
                except (TypeError, ValueError, RuntimeError):
                    # The strategy and trial are still immutable and linked;
                    # a retry can repair only the enrollment projection.
                    pass
            persisted.append({**record, "research_trial_id": trial_id, "candidate_id": candidate_id})
        return tuple(persisted)

    def _load_rolling_historical_dataset(
        self,
        dataset_id: str,
        dataset_version: str,
    ) -> Any | None:
        """Preflight immutable JSON size/row metadata before ``load_dataset``.

        The regular storage loader intentionally serves all dataset consumers.
        Rolling evidence has a stricter source boundary, so inspect SQLite
        metadata first and refuse oversized payloads before storage decodes the
        JSON string or reconstructs catalog-backed records.
        """
        connection = getattr(self.store, "connection", None)
        execute = getattr(connection, "execute", None)
        if not callable(execute):
            raise ValueError("HISTORICAL_DATASET_PREFLIGHT_UNAVAILABLE")
        try:
            payload_lengths = execute(
                "SELECT LENGTH(CAST(payload_json AS BLOB)) AS payload_bytes,"
                "LENGTH(CAST(metadata_json AS BLOB)) AS metadata_bytes "
                "FROM datasets WHERE dataset_id=? AND version=? LIMIT 1",
                (str(dataset_id), str(dataset_version)),
            ).fetchone()
            catalog_lengths = execute(
                "SELECT LENGTH(CAST(metadata_json AS BLOB)) AS metadata_bytes,"
                "LENGTH(CAST(missing_ranges_json AS BLOB)) AS missing_ranges_bytes "
                "FROM dataset_catalog "
                "WHERE dataset_id=? AND dataset_version=? LIMIT 1",
                (str(dataset_id), str(dataset_version)),
            ).fetchone()
        except Exception as exc:
            raise ValueError("HISTORICAL_DATASET_PREFLIGHT_FAILED") from exc

        def integer(value: Any, field: str) -> int | None:
            if value is None:
                return None
            if isinstance(value, bool):
                raise ValueError(f"{field} is invalid")
            try:
                parsed = int(value)
            except (TypeError, ValueError, OverflowError) as exc:
                raise ValueError(f"{field} is invalid") from exc
            if parsed < 0:
                raise ValueError(f"{field} is invalid")
            return parsed

        if payload_lengths is None and catalog_lengths is None:
            raise ValueError("HISTORICAL_DATASET_METADATA_MISSING")

        def check_length(row: Any, field: str) -> None:
            if row is None:
                return
            size = integer(row[field], field)
            if size is None or size > _MAX_ROLLING_DATASET_PAYLOAD_BYTES:
                raise ValueError("HISTORICAL_DATASET_PAYLOAD_TOO_LARGE")

        check_length(payload_lengths, "payload_bytes")
        check_length(payload_lengths, "metadata_bytes")
        check_length(catalog_lengths, "metadata_bytes")
        check_length(catalog_lengths, "missing_ranges_bytes")

        try:
            payload_row = (
                execute(
                    "SELECT LENGTH(CAST(payload_json AS BLOB)) AS payload_bytes,"
                    "CASE WHEN json_valid(payload_json) THEN json_type(payload_json) END AS payload_type,"
                    "json_extract(CASE WHEN json_valid(metadata_json) THEN metadata_json ELSE '{}' END,"
                    "'$.row_count') AS metadata_row_count,"
                    "json_array_length(CASE WHEN json_valid(payload_json) THEN payload_json ELSE '[]' END) "
                    "AS payload_row_count,"
                    "CASE WHEN json_valid(payload_json) "
                    "AND json_type(payload_json,'$.records')='array' "
                    "THEN json_array_length(json_extract(payload_json,'$.records')) END "
                    "AS records_row_count,"
                    "CASE WHEN json_valid(payload_json) "
                    "AND json_type(payload_json,'$.rows')='array' "
                    "THEN json_array_length(json_extract(payload_json,'$.rows')) END "
                    "AS rows_row_count,"
                    "json_array_length(CASE WHEN json_valid(metadata_json) "
                    "AND json_type(metadata_json,'$.records')='array' "
                    "THEN json_extract(metadata_json,'$.records') ELSE '[]' END) "
                    "AS metadata_records_row_count,"
                    "json_array_length(CASE WHEN json_valid(metadata_json) "
                    "AND json_type(metadata_json,'$.rows')='array' "
                    "THEN json_extract(metadata_json,'$.rows') ELSE '[]' END) "
                    "AS metadata_rows_row_count "
                    "FROM datasets WHERE dataset_id=? AND version=? LIMIT 1",
                    (str(dataset_id), str(dataset_version)),
                ).fetchone()
                if payload_lengths is not None
                else None
            )
            catalog_row = (
                execute(
                    "SELECT row_count,"
                    "json_array_length(CASE WHEN json_valid(metadata_json) "
                    "AND json_type(metadata_json,'$.market_versions')='array' "
                    "THEN json_extract(metadata_json,'$.market_versions') ELSE '[]' END) "
                    "AS market_versions_count,"
                    "json_array_length(CASE WHEN json_valid(metadata_json) "
                    "AND json_type(metadata_json,'$.snapshot_manifest')='array' "
                    "THEN json_extract(metadata_json,'$.snapshot_manifest') ELSE '[]' END) "
                    "AS snapshot_manifest_count,"
                    "json_array_length(CASE WHEN json_valid(metadata_json) "
                    "AND json_type(metadata_json,'$.manifest')='array' "
                    "THEN json_extract(metadata_json,'$.manifest') ELSE '[]' END) "
                    "AS manifest_count,"
                    "json_array_length(CASE WHEN json_valid(missing_ranges_json) "
                    "AND json_type(missing_ranges_json)='array' "
                    "THEN missing_ranges_json ELSE '[]' END) "
                    "AS missing_ranges_count "
                    "FROM dataset_catalog "
                    "WHERE dataset_id=? AND dataset_version=? LIMIT 1",
                    (str(dataset_id), str(dataset_version)),
                ).fetchone()
                if catalog_lengths is not None
                else None
            )
        except Exception as exc:
            raise ValueError("HISTORICAL_DATASET_PREFLIGHT_FAILED") from exc

        if payload_row is None and catalog_row is None:
            raise ValueError("HISTORICAL_DATASET_METADATA_MISSING")
        payload_rows: int | None = None
        metadata_rows: int | None = None
        if payload_row is not None:
            payload_bytes = integer(payload_row["payload_bytes"], "payload_bytes")
            payload_type = str(payload_row["payload_type"] or "").strip().lower()
            metadata_rows = integer(
                payload_row["metadata_row_count"],
                "metadata_row_count",
            )
            root_rows = integer(
                payload_row["payload_row_count"],
                "payload_row_count",
            )
            records_rows = integer(
                payload_row["records_row_count"],
                "records_row_count",
            )
            rows_rows = integer(
                payload_row["rows_row_count"],
                "rows_row_count",
            )
            metadata_records_rows = integer(
                payload_row["metadata_records_row_count"],
                "metadata_records_row_count",
            )
            metadata_rows_rows = integer(
                payload_row["metadata_rows_row_count"],
                "metadata_rows_row_count",
            )
            if payload_bytes is None or payload_bytes > _MAX_ROLLING_DATASET_PAYLOAD_BYTES:
                raise ValueError("HISTORICAL_DATASET_PAYLOAD_TOO_LARGE")
            for row_count in (
                metadata_rows,
                root_rows,
                records_rows,
                rows_rows,
                metadata_records_rows,
                metadata_rows_rows,
            ):
                if row_count is not None and row_count > _MAX_ROLLING_SOURCE_ROWS:
                    raise ValueError("HISTORICAL_DATASET_ROW_COUNT_TOO_LARGE")
            if payload_type == "array":
                payload_rows = root_rows
            elif payload_type == "object":
                shaped = [
                    value
                    for value in (records_rows, rows_rows)
                    if value is not None
                ]
                if records_rows is not None and rows_rows is not None and records_rows != rows_rows:
                    raise ValueError("HISTORICAL_DATASET_ROW_COUNT_MISMATCH")
                payload_rows = shaped[0] if shaped else None
            if (
                payload_rows is None
                and metadata_rows is None
                and catalog_row is None
            ):
                raise ValueError("HISTORICAL_DATASET_ROW_COUNT_UNAVAILABLE")
            if (
                payload_rows is not None
                and metadata_rows is not None
                and payload_rows != metadata_rows
            ):
                raise ValueError("HISTORICAL_DATASET_ROW_COUNT_MISMATCH")

        if catalog_row is not None:
            catalog_rows = integer(catalog_row["row_count"], "catalog_row_count")
            catalog_counts = [
                integer(catalog_row[field], field)
                for field in (
                    "market_versions_count",
                    "snapshot_manifest_count",
                    "manifest_count",
                    "missing_ranges_count",
                )
            ]
            if catalog_rows is None:
                raise ValueError("HISTORICAL_DATASET_ROW_COUNT_UNAVAILABLE")
            if catalog_rows > _MAX_ROLLING_SOURCE_ROWS or any(
                count is not None and count > _MAX_ROLLING_SOURCE_ROWS
                for count in catalog_counts
            ):
                raise ValueError("HISTORICAL_DATASET_ROW_COUNT_TOO_LARGE")
            if payload_rows is not None and catalog_rows != payload_rows:
                raise ValueError("HISTORICAL_DATASET_ROW_COUNT_MISMATCH")
        return self.store.load_dataset(dataset_id, dataset_version)

    def _rolling_accounting_projection(
        self,
        row: Mapping[str, Any],
        strategy: Mapping[str, Any],
    ) -> Mapping[str, Any] | None:
        """Return validated explicit strategy accounting, never infer it from prices."""
        existing_rejection = row.get("_rolling_accounting_rejection")
        if existing_rejection and existing_rejection not in (
            "ACCOUNTING_COVERAGE_MISSING",
            "ACCOUNTING_COVERAGE_INVALID",
        ):
            # Source loaders retain rejected rows for auditability, but a
            # permanently contaminated row is never eligible for accounting
            # projection. Coverage rejections are derived from timestamps and
            # must be reevaluated when the payload changes.
            return None
        if existing_rejection in (
            "ACCOUNTING_COVERAGE_MISSING",
            "ACCOUNTING_COVERAGE_INVALID",
        ):
            row.pop("_rolling_accounting_rejection", None)
            row.pop("_rolling_accounting_metric", None)
        view = _rolling_snapshot_view(row)
        quality = str(
            view.get("research_quality", view.get("quality", view.get("source_type", "")))
        ).strip().upper().replace("-", "_")

        def reject(reason: str, metric: str | None = None) -> None:
            row["_rolling_accounting_rejection"] = reason
            if metric:
                row["_rolling_accounting_metric"] = metric

        if quality in {"PRICE_PROXY", "PRICE_PROXY_RESEARCH", "PRICE_REPLAY"}:
            reject("PRICE_PROXY_ACCOUNTING_UNAVAILABLE")
            return None

        accounting: Mapping[str, Any] | None = None
        for name in ("canonical_accounting", "strategy_accounting", "accounting"):
            value = view.get(name)
            if isinstance(value, Mapping):
                accounting = value
                break

        # ForwardPaperEngine persists one canonical resolved-bet payload rather
        # than a second accounting wrapper.  It is accepted only after the
        # PAPER loader has proved the immutable experiment/spec binding.
        paper_experiment = _binding_value(row.get("_paper_experiment_id"))
        if accounting is None and paper_experiment:
            resolved = view.get("resolved_bet")
            if not isinstance(resolved, Mapping) and {
                "net_pnl",
                "capital_at_risk",
                "resolution",
            }.issubset(view):
                resolved = view
            if isinstance(resolved, Mapping):
                resolved_experiment = _binding_value(
                    resolved.get("experiment_id", view.get("experiment_id"))
                )
                resolution = str(resolved.get("resolution", "")).strip().lower()
                if (
                    resolved_experiment != paper_experiment
                    or resolved.get("closed") is not True
                    or resolution
                    not in {"resolved_yes", "resolved_no", "void"}
                ):
                    reject("PAPER_RESOLVED_BET_BINDING_INVALID")
                    return None

                def decimal_value(value: Any) -> Decimal | None:
                    if value is None or isinstance(value, bool):
                        return None
                    try:
                        parsed = Decimal(str(value))
                    except (InvalidOperation, TypeError, ValueError, OverflowError):
                        return None
                    return parsed if parsed.is_finite() else None

                def first_timestamp(*names: str) -> datetime | None:
                    for name in names:
                        timestamp = _rolling_timestamp(resolved.get(name))
                        if timestamp is None:
                            timestamp = _rolling_timestamp(view.get(name))
                        if timestamp is not None:
                            return timestamp
                    return None

                shortage = resolved.get("accounting_shortage")
                if shortage:
                    shortage_fields = (
                        shortage.get("fields")
                        if isinstance(shortage, Mapping)
                        else ()
                    )
                    reject(
                        "PAPER_RESOLVED_BET_ACCOUNTING_INCOMPLETE",
                        str(next(iter(shortage_fields), "accounting")),
                    )
                    return None
                net_pnl = decimal_value(resolved.get("net_pnl"))
                capital = decimal_value(resolved.get("capital_at_risk"))
                fees_value = decimal_value(resolved.get("fees"))
                slippage_value = decimal_value(resolved.get("slippage"))
                if net_pnl is None:
                    reject("ACCOUNTING_METRIC_MISSING", "realized_pnl")
                    return None
                if capital is None:
                    reject("ACCOUNTING_METRIC_MISSING", "allocated_capital")
                    return None
                if fees_value is None:
                    reject("ACCOUNTING_METRIC_MISSING", "fees")
                    return None
                if slippage_value is None:
                    reject("ACCOUNTING_METRIC_MISSING", "costs")
                    return None
                if capital < Decimal("0"):
                    reject("ACCOUNTING_METRIC_NEGATIVE_IMPOSSIBLE", "allocated_capital")
                    return None
                if capital == Decimal("0"):
                    reject("ACCOUNTING_METRIC_NONPOSITIVE", "allocated_capital")
                    return None
                if fees_value < Decimal("0"):
                    reject("ACCOUNTING_METRIC_NEGATIVE_IMPOSSIBLE", "fees")
                    return None
                if slippage_value < Decimal("0"):
                    reject("ACCOUNTING_METRIC_NEGATIVE_IMPOSSIBLE", "costs")
                    return None
                drawdown = min(
                    Decimal("1"),
                    max(Decimal("0"), -net_pnl / capital),
                )
                if "drawdown" in resolved:
                    supplied_drawdown = decimal_value(resolved.get("drawdown"))
                    if supplied_drawdown is None:
                        reject("ACCOUNTING_METRIC_INVALID", "drawdown")
                        return None
                    if supplied_drawdown != drawdown:
                        reject("PAPER_RESOLVED_BET_DRAWDOWN_CONFLICT", "drawdown")
                        return None
                if "unrealized_pnl" in resolved:
                    supplied_unrealized = decimal_value(resolved.get("unrealized_pnl"))
                    if supplied_unrealized is None:
                        reject("ACCOUNTING_METRIC_INVALID", "unrealized_pnl")
                        return None
                    if supplied_unrealized != Decimal("0"):
                        reject(
                            "PAPER_RESOLVED_BET_UNREALIZED_NONZERO",
                            "unrealized_pnl",
                        )
                        return None
                for name, expected in (
                    ("allocated_capital", capital),
                    ("allocated_capital_net_return", net_pnl),
                    ("realized_pnl", net_pnl),
                    ("fees", fees_value),
                    ("costs", slippage_value),
                ):
                    if name not in resolved:
                        continue
                    supplied = decimal_value(resolved.get(name))
                    if supplied is None:
                        reject("ACCOUNTING_METRIC_INVALID", name)
                        return None
                    if supplied != expected:
                        reject("PAPER_RESOLVED_BET_ACCOUNTING_CONFLICT", name)
                        return None
                for name in ("completed_outcomes", "reliability"):
                    if name not in resolved:
                        continue
                    supplied = decimal_value(resolved.get(name))
                    if supplied is None:
                        reject("ACCOUNTING_METRIC_INVALID", name)
                        return None
                    if supplied != Decimal("1"):
                        reject("PAPER_RESOLVED_BET_CONTRACT_CONFLICT", name)
                        return None
                expected_outcome = (
                    "yes"
                    if resolution == "resolved_yes"
                    else "no"
                    if resolution == "resolved_no"
                    else None
                )
                supplied_winner = _binding_value(resolved.get("winning_outcome"))
                if (
                    expected_outcome is not None
                    and supplied_winner is not None
                    and supplied_winner.lower() != expected_outcome
                ):
                    reject("PAPER_RESOLVED_BET_CONTRACT_CONFLICT", "winning_outcome")
                    return None
                available_from = first_timestamp(
                    "observation_open_timestamp",
                    "observation_opened_at",
                    "open_timestamp",
                    "opened_at",
                    "observation_timestamp",
                    "observation_at",
                    "available_from",
                    "coverage_from",
                    "window_start",
                    "timestamp",
                )
                available_through = first_timestamp(
                    "resolved_at",
                    "available_through",
                    "coverage_through",
                    "window_end",
                )
                if available_from is None:
                    reject("ACCOUNTING_COVERAGE_MISSING", "observation_open_timestamp")
                    return None
                if available_through is None:
                    reject("ACCOUNTING_COVERAGE_MISSING", "resolved_at")
                    return None
                if available_from > available_through:
                    reject("ACCOUNTING_COVERAGE_INVALID", "observation_open_timestamp")
                    return None
                accounting = dict(resolved)
                accounting.update(
                    {
                        "allocated_capital": capital,
                        "allocated_capital_net_return": net_pnl,
                        "realized_pnl": net_pnl,
                        "unrealized_pnl": Decimal("0"),
                        "fees": fees_value,
                        "costs": slippage_value,
                        "completed_outcomes": Decimal("1"),
                        "reliability": Decimal("1"),
                        "drawdown": drawdown,
                        "available_from": available_from.isoformat(),
                        "available_through": available_through.isoformat(),
                    }
                )

        if accounting is None:
            reject("ACCOUNTING_MISSING")
            return None

        try:
            binding = _rolling_source_binding(view)
        except (TypeError, ValueError):
            reject("SOURCE_BINDING_CONFLICT")
            return None
        expected_binding = _rolling_source_binding(strategy)
        expected_candidate = _binding_value(
            strategy.get("candidate_id")
            or expected_binding.get("candidate_id")
            or expected_binding.get("source_candidate_id")
        )
        expected_trial = _binding_value(
            strategy.get("research_trial_id")
            or expected_binding.get("research_trial_id")
            or expected_binding.get("trial_id")
        )
        expected_strategy_version = _binding_value(
            strategy.get("strategy_version_id")
            or expected_binding.get("strategy_version_id")
        )
        expected_strategy_hash = _binding_value(
            strategy.get("strategy_hash")
            or expected_binding.get("strategy_hash")
        )
        row_candidate = _binding_value(binding.get("candidate_id"))
        row_trial = _binding_value(binding.get("research_trial_id", binding.get("trial_id")))
        row_strategy_version = _binding_value(binding.get("strategy_version_id"))
        row_strategy_hash = _binding_value(binding.get("strategy_hash"))
        if (
            not expected_candidate
            or not expected_trial
            or not expected_strategy_version
            or not expected_strategy_hash
            or row_candidate != expected_candidate
            or row_trial != expected_trial
            or row_strategy_version != expected_strategy_version
            or row_strategy_hash != expected_strategy_hash
        ):
            reject("SOURCE_BINDING_MISMATCH")
            return None
        if paper_experiment:
            if _binding_value(binding.get("experiment_id")) != paper_experiment:
                reject("PAPER_EXPERIMENT_BINDING_MISMATCH")
                return None
            row_strategy = _binding_value(view.get("strategy_id"))
            if row_strategy and row_strategy != expected_strategy_hash:
                reject("PAPER_STRATEGY_BINDING_MISMATCH")
                return None

        def value_for(*names: str) -> tuple[str | None, Any]:
            for name in names:
                if name in accounting:
                    return name, accounting[name]
            return None, None

        def parse_metric(name: str, raw: Any, *, nonnegative: bool = False, ratio: bool = False) -> Any:
            if raw is None or isinstance(raw, bool) or isinstance(raw, (Mapping, list, tuple, set, frozenset)):
                reject("ACCOUNTING_METRIC_TYPE_INVALID", name)
                return None
            try:
                parsed = Decimal(str(raw))
            except (InvalidOperation, TypeError, ValueError, OverflowError):
                reject("ACCOUNTING_METRIC_MALFORMED", name)
                return None
            if not parsed.is_finite():
                reject("ACCOUNTING_METRIC_NONFINITE", name)
                return None
            if nonnegative and parsed < 0:
                reject("ACCOUNTING_METRIC_NEGATIVE_IMPOSSIBLE", name)
                return None
            if ratio and parsed > 1:
                reject("ACCOUNTING_METRIC_OUT_OF_RANGE", name)
                return None
            if name == "completed_outcomes" and parsed != parsed.to_integral_value():
                reject("ACCOUNTING_METRIC_MALFORMED", name)
                return None
            return parsed

        metric_aliases: dict[str, tuple[str, ...]] = {
            "allocated_capital": ("allocated_capital", "allocated_capital_usd", "paper_size", "paper_sizing"),
            "net_return": ("allocated_capital_net_return", "net_return"),
            "realized_pnl": ("realized_pnl",),
            "unrealized_pnl": ("unrealized_pnl",),
            "fees": ("fees", "fee_costs"),
            "costs": ("costs", "slippage_costs"),
            "drawdown": ("drawdown",),
            "completed_outcomes": ("completed_outcomes", "outcomes"),
            "reliability": ("reliability",),
        }
        parsed_metrics: dict[str, Decimal] = {}
        for metric_name, aliases in metric_aliases.items():
            alias, raw = value_for(*aliases)
            if alias is None:
                reject("ACCOUNTING_METRIC_MISSING", metric_name)
                return None
            parsed = parse_metric(
                metric_name,
                raw,
                nonnegative=metric_name
                in {"allocated_capital", "fees", "costs", "drawdown", "completed_outcomes", "reliability"},
                ratio=metric_name in {"drawdown", "reliability"},
            )
            if parsed is None:
                return None
            parsed_metrics[metric_name] = parsed
        if parsed_metrics["completed_outcomes"] < 0:
            reject("ACCOUNTING_METRIC_NEGATIVE_IMPOSSIBLE", "completed_outcomes")
            return None
        result = dict(accounting)
        for metric_name, parsed in parsed_metrics.items():
            result[metric_name] = parsed
        result["_timestamp"] = _rolling_row_time(view)
        result["_available_from"] = _rolling_timestamp(
            view.get("available_from", view.get("coverage_from", view.get("window_start")))
            or accounting.get("available_from", accounting.get("coverage_from"))
        )
        result["_available_through"] = _rolling_timestamp(
            view.get("available_through", view.get("coverage_through", view.get("window_end")))
            or accounting.get("available_through", accounting.get("coverage_through"))
        )
        if result["_available_from"] is None or result["_available_through"] is None:
            reject("ACCOUNTING_COVERAGE_MISSING")
            return None
        if result["_available_through"] <= result["_available_from"]:
            reject("ACCOUNTING_COVERAGE_INVALID")
            return None
        return result
    def _rolling_replay_catalog_rows(
        self,
        record: Mapping[str, Any],
        now: datetime,
        *,
        scope_market_ids: set[str] | None = None,
    ) -> tuple[list[dict[str, Any]], Mapping[str, Any]]:
        """Rank bounded catalog metadata, then validate payloads in rank order.

        Catalog metadata is the only material decoded during discovery.  The
        immutable dataset payload and publisher snapshots are loaded only for
        one candidate at a time, and validation stops at the first winner.
        """
        connection = getattr(self.store, "connection", None)
        execute = getattr(connection, "execute", None)
        if not callable(execute):
            raise ValueError("REPLAY_DATASET_UNAVAILABLE")
        try:
            descriptors = execute(
                "SELECT dataset_version,row_count,completeness,"
                "start_timestamp,end_timestamp,updated_at,"
                "LENGTH(CAST(metadata_json AS BLOB)) AS metadata_bytes,"
                "LENGTH(CAST(missing_ranges_json AS BLOB)) AS missing_ranges_bytes "
                "FROM dataset_catalog "
                "WHERE dataset_id=? AND source_type=? "
                "ORDER BY updated_at DESC,dataset_id,dataset_version LIMIT ?",
                (
                    _ROLLING_REPLAY_DATASET_ID,
                    "FORWARD_COLLECTED",
                    _ROLLING_REPLAY_MAX_CATALOGS,
                ),
            ).fetchall()
        except Exception as exc:
            raise ValueError("REPLAY_DATASET_UNAVAILABLE") from exc

        binding = _rolling_source_binding(record)
        requested_id = _binding_value(binding.get("dataset_id"))
        requested_version = _binding_value(
            binding.get("dataset_version", binding.get("version"))
        )
        pinned_version = (
            requested_version
            if requested_id == _ROLLING_REPLAY_DATASET_ID
            else None
        )
        scope_ids = (
            set(scope_market_ids)
            if scope_market_ids is not None
            else _rolling_market_scope_ids(binding)
        )
        metadata_budget = 0
        ranked: list[tuple[tuple[Any, ...], dict[str, Any]]] = []

        def integer(value: Any) -> int | None:
            if isinstance(value, bool) or value is None:
                return None
            try:
                parsed = int(value)
            except (TypeError, ValueError, OverflowError):
                return None
            return parsed if parsed >= 0 else None

        def bounded_catalog(descriptor: Any) -> dict[str, Any] | None:
            nonlocal metadata_budget
            version = str(descriptor["dataset_version"] or "").strip()
            expected_count = integer(descriptor["row_count"])
            if (
                not re.fullmatch(r"sha256:[0-9a-f]{64}", version)
                or expected_count is None
                or expected_count > _ROLLING_INPUT_MANIFEST_ROWS
                or (pinned_version is not None and version != pinned_version)
            ):
                return None
            try:
                metadata_bytes = integer(descriptor["metadata_bytes"])
                missing_bytes = integer(descriptor["missing_ranges_bytes"])
            except (KeyError, TypeError):
                return None
            if (
                metadata_bytes is None
                or missing_bytes is None
                or metadata_bytes > _MAX_ROLLING_REPLAY_CATALOG_METADATA_BYTES
                or missing_bytes > _MAX_ROLLING_REPLAY_CATALOG_METADATA_BYTES
                or metadata_budget + metadata_bytes + missing_bytes
                > _MAX_ROLLING_REPLAY_METADATA_BUDGET_BYTES
            ):
                return None
            try:
                raw = execute(
                    "SELECT * FROM dataset_catalog "
                    "WHERE dataset_id=? AND dataset_version=? LIMIT 1",
                    (_ROLLING_REPLAY_DATASET_ID, version),
                ).fetchone()
            except Exception:
                return None
            if raw is None:
                return None
            metadata_json = raw["metadata_json"]
            missing_json = raw["missing_ranges_json"]
            if (
                not isinstance(metadata_json, str)
                or not isinstance(missing_json, str)
                or len(metadata_json.encode("utf-8")) != metadata_bytes
                or len(missing_json.encode("utf-8")) != missing_bytes
            ):
                return None
            # Count bounded arrays without deserializing them.  An oversized
            # manifest is rejected before json.loads can allocate its entries.
            manifest_count = _json_array_count_for_key(
                metadata_json,
                ("snapshot_manifest", "manifest"),
                limit=_ROLLING_INPUT_MANIFEST_ROWS,
            )
            missing_count = _json_array_count(
                missing_json,
                limit=_ROLLING_INPUT_MANIFEST_ROWS,
            )
            if (
                manifest_count is None
                or manifest_count > _ROLLING_INPUT_MANIFEST_ROWS
                or missing_count is None
                or missing_count > _ROLLING_INPUT_MANIFEST_ROWS
            ):
                return None
            try:
                metadata = json.loads(metadata_json)
                missing_ranges = json.loads(missing_json)
            except (TypeError, ValueError, RecursionError):
                return None
            if not isinstance(metadata, Mapping) or not isinstance(
                missing_ranges, list
            ):
                return None
            if (
                str(raw["dataset_id"]).strip() != _ROLLING_REPLAY_DATASET_ID
                or str(raw["source_type"]).strip().upper() != "FORWARD_COLLECTED"
                or str(metadata.get("research_mode", "")).strip().upper().replace("-", "_")
                != "RECORDED_BOOK_REPLAY"
                or len(missing_ranges) > _ROLLING_INPUT_MANIFEST_ROWS
                or any(
                    not isinstance(item, Mapping)
                    or not _rolling_replay_row_terminal(item)
                    for item in missing_ranges
                )
            ):
                return None
            # Replay catalogs are complete immutable snapshots; a catalog
            # carrying any missing range is not eligible for selection.
            if missing_ranges:
                return None
            try:
                completeness = float(raw["completeness"])
            except (TypeError, ValueError, OverflowError):
                return None
            if not math.isfinite(completeness) or completeness != 1.0:
                return None
            manifest = metadata.get("snapshot_manifest", metadata.get("manifest"))
            if (
                not isinstance(manifest, Sequence)
                or isinstance(manifest, (str, bytes))
                or len(manifest) > _ROLLING_INPUT_MANIFEST_ROWS
                or len(manifest) != expected_count
                or any(not isinstance(item, Mapping) for item in manifest)
            ):
                return None

            markets = {
                str(item.get("market_id", "")).strip()
                for item in manifest
                if str(item.get("market_id", "")).strip()
            }
            if scope_ids and not scope_ids.issubset(markets):
                # A non-empty requested scope must be fully represented by
                # the immutable manifest; otherwise downstream filtering
                # would silently label a partial replay as complete.
                return None
            stamps = [
                stamp
                for stamp in (
                    _rolling_timestamp(item.get("source_timestamp"))
                    for item in manifest
                )
                if stamp is not None
            ]
            first = min(stamps) if stamps else _rolling_timestamp(
                raw["start_timestamp"]
            )
            last = max(stamps) if stamps else _rolling_timestamp(raw["end_timestamp"])
            available = _rolling_timestamp(
                metadata.get("available_through", metadata.get("exact_cutoff"))
            ) or _rolling_timestamp(raw["updated_at"])
            manifest_digest = _rolling_hash(list(manifest))
            tie_digest = _rolling_hash(
                {"manifest": manifest_digest, "dataset_version": version}
            )
            catalog = {
                "dataset_id": raw["dataset_id"],
                "dataset_version": raw["dataset_version"],
                "version": raw["dataset_version"],
                "provider": raw["provider"],
                "instrument": raw["instrument"],
                "market_type": raw["market_type"],
                "timeframe": raw["timeframe"],
                "start_timestamp": _rolling_timestamp(raw["start_timestamp"]),
                "end_timestamp": _rolling_timestamp(raw["end_timestamp"]),
                "row_count": int(raw["row_count"]),
                "completeness": completeness,
                "missing_ranges": missing_ranges,
                "quality": raw["quality"],
                "source_type": raw["source_type"],
                "snapshot_id": raw["snapshot_id"],
                "created_at": _rolling_timestamp(raw["created_at"]),
                "updated_at": _rolling_timestamp(raw["updated_at"]),
                "last_updated": _rolling_timestamp(raw["updated_at"]),
                "metadata": metadata,
            }
            metadata_budget += metadata_bytes + missing_bytes
            required_start = ensure_utc(now) - timedelta(days=30)
            scope_complete = bool(scope_ids) and scope_ids.issubset(markets)
            overlap = len(scope_ids & markets) if scope_ids else 0
            lookback_sufficient = bool(
                first is not None
                and first <= required_start
                and last is not None
                and last <= ensure_utc(now)
            )
            coverage_seconds = (
                int((last - first).total_seconds())
                if first is not None and last is not None and last >= first
                else 0
            )
            rank = (
                1,  # source_type is selected by the SQL source gate
                1,  # research_mode is validated above
                1,  # completeness is exactly complete
                1 if not missing_ranges else 0,
                1 if scope_complete else 0,
                overlap,
                1 if lookback_sufficient else 0,
                coverage_seconds,
                available or datetime.min.replace(tzinfo=timezone.utc),
                tie_digest,
                version,
            )
            return {
                "rank": rank,
                "catalog": catalog,
                "manifest": list(manifest),
                "metadata_bytes": metadata_bytes,
            }

        for descriptor in descriptors:
            candidate = bounded_catalog(descriptor)
            if candidate is not None:
                ranked.append((candidate["rank"], candidate))
        if not ranked:
            raise ValueError("REPLAY_DATASET_UNAVAILABLE")
        ranked.sort(key=lambda item: item[0], reverse=True)

        def load_payload(version: str) -> Any | None:
            projection_loader = getattr(
                self.store, "load_dataset_payload_projection", None
            )
            if callable(projection_loader):
                try:
                    return projection_loader(
                        _ROLLING_REPLAY_DATASET_ID,
                        version,
                        max_payload_bytes=_MAX_ROLLING_REPLAY_PAYLOAD_BYTES,
                    )
                except Exception:
                    return None
            try:
                row = execute(
                    "SELECT payload_json FROM datasets "
                    "WHERE dataset_id=? AND version=? LIMIT 1",
                    (_ROLLING_REPLAY_DATASET_ID, version),
                ).fetchone()
                payload_json = row["payload_json"] if row is not None else None
                if not isinstance(payload_json, str):
                    return None
                if len(payload_json.encode("utf-8")) > _MAX_ROLLING_REPLAY_PAYLOAD_BYTES:
                    return None
                return json.loads(payload_json)
            except (TypeError, ValueError, RecursionError):
                return None

        def validate(candidate: Mapping[str, Any]) -> tuple[
            list[dict[str, Any]], Mapping[str, Any]
        ] | None:
            catalog = candidate["catalog"]
            metadata = catalog["metadata"]
            manifest = candidate["manifest"]
            version = str(catalog["dataset_version"])
            values = load_payload(version)
            if isinstance(values, Mapping):
                values = values.get("records", values.get("rows", ()))
            if (
                not isinstance(values, Sequence)
                or isinstance(values, (str, bytes))
                or len(values) > _ROLLING_INPUT_MANIFEST_ROWS
                or len(values) != len(manifest)
                or len(values) != int(catalog["row_count"])
                or any(not isinstance(value, Mapping) for value in values)
            ):
                return None
            rows = [dict(value) for value in values]
            source_loader = getattr(
                self.store, "load_polymarket_snapshots_by_ids", None
            )
            if not callable(source_loader):
                return None
            source_ids = tuple(str(item.get("snapshot_id", "")).strip() for item in manifest)
            if any(not item for item in source_ids) or len(set(source_ids)) != len(source_ids):
                return None
            try:
                source_values = source_loader(
                    source_ids,
                    source_type="FORWARD_COLLECTED",
                )
            except Exception:
                return None
            if isinstance(source_values, Mapping):
                source_by_id = dict(source_values)
            elif isinstance(source_values, Sequence) and not isinstance(
                source_values, (str, bytes)
            ):
                source_by_id = {
                    str(item.get("snapshot_id", "")).strip(): item
                    for item in source_values
                    if isinstance(item, Mapping)
                }
            else:
                return None
            if set(source_by_id) != set(source_ids):
                return None
            for row, expected in zip(rows, manifest):
                snapshot_id = str(
                    row.get("source_snapshot_id", row.get("snapshot_id", ""))
                ).strip()
                expected_snapshot_id = str(expected.get("snapshot_id", "")).strip()
                source_record = source_by_id.get(expected_snapshot_id)
                if not isinstance(source_record, Mapping):
                    return None
                source_hash = str(row.get("source_record_hash", "")).strip()
                expected_hash = str(expected.get("source_record_hash", "")).strip()
                market_id = str(row.get("market_id", "")).strip()
                expected_market = str(expected.get("market_id", "")).strip()
                row_time = _rolling_timestamp(
                    row.get("source_timestamp", row.get("timestamp"))
                )
                manifest_time = _rolling_timestamp(expected.get("source_timestamp"))
                source_time = _rolling_timestamp(source_record.get("source_timestamp"))
                try:
                    recomputed_hash = _rolling_publisher_source_record_hash(
                        source_record
                    )
                except (TypeError, ValueError, ArithmeticError):
                    return None
                if (
                    not snapshot_id
                    or snapshot_id != expected_snapshot_id
                    or str(source_record.get("snapshot_id", "")).strip()
                    != expected_snapshot_id
                    or str(source_record.get("source_type", "")).strip().upper()
                    != "FORWARD_COLLECTED"
                    or not re.fullmatch(r"sha256:[0-9a-f]{64}", source_hash)
                    or source_hash != expected_hash
                    or source_hash != recomputed_hash
                    or not market_id
                    or market_id != expected_market
                    or str(source_record.get("market_id", "")).strip() != expected_market
                    or row_time is None
                    or manifest_time is None
                    or source_time is None
                    or row_time != manifest_time
                    or source_time != manifest_time
                    or str(row.get("source_type", "")).strip().upper()
                    != "FORWARD_COLLECTED"
                ):
                    return None
            cutoff_stamp = _rolling_timestamp(
                metadata.get("exact_cutoff", metadata.get("cutoff"))
            )
            if cutoff_stamp is None:
                return None
            expected_version = _rolling_hash(
                {
                    "dataset_id": _ROLLING_REPLAY_DATASET_ID,
                    "research_mode": "RECORDED_BOOK_REPLAY",
                    "cutoff": cutoff_stamp,
                    "manifest": list(manifest),
                    "rows": rows,
                }
            )
            if expected_version != version:
                return None
            return rows, catalog

        for _rank, candidate in ranked:
            selected = validate(candidate)
            if selected is None:
                continue
            selected_rows, selected_catalog = selected
            selected_id = str(
                selected_catalog.get("dataset_id", _ROLLING_REPLAY_DATASET_ID)
            )
            selected_version = str(selected_catalog["dataset_version"])
            for row in selected_rows:
                row["_rolling_replay_catalog"] = {
                    "dataset_id": selected_id,
                    "dataset_version": selected_version,
                    "research_mode": "RECORDED_BOOK_REPLAY",
                }
                row.setdefault("dataset_id", selected_id)
                row.setdefault("dataset_version", selected_version)
            return selected_rows, selected_catalog
        raise ValueError("REPLAY_DATASET_UNAVAILABLE")
    def _resolve_rolling_model(
        self,
        strategy: Mapping[str, Any],
    ) -> tuple[Mapping[str, Any], Mapping[str, Any]]:
        """Resolve one executable model under immutable rolling lineage.

        A model embedded in the frozen row is preferred, but only after its
        canonical hash agrees with every frozen hash carried by the available
        candidate/trial/version records.  Legacy rows may instead point at
        exactly one immutable experiment plan; the plan's model is accepted
        only after the same hash proof.
        """
        if not isinstance(strategy, Mapping):
            raise ValueError("MODEL_INPUT_MISSING")
        model_required = _rolling_prediction_model_required(strategy)
        if model_required is False:
            # Directional prediction families (and other built-in
            # model-independent families) deliberately evaluate from their
            # observed input path.  A marker is persisted so forward workers
            # have one canonical representation for "no model".
            return dict(_ROLLING_MODEL_FREE_DOCUMENT), _rolling_model_free_resolution()

        def identity_values(
            value: Any,
            names: Sequence[str],
        ) -> tuple[set[str], bool]:
            values: set[str] = set()
            invalid = False
            pending: list[tuple[Any, int, str | None]] = [(value, 0, None)]
            seen: set[int] = set()
            visited = 0
            wanted = frozenset(names)
            while pending:
                item, depth, parent = pending.pop()
                if isinstance(item, Mapping):
                    marker = id(item)
                    if marker in seen:
                        continue
                    seen.add(marker)
                    visited += 1
                    if visited > _ROLLING_PAPER_IDENTITY_MAX_NODES:
                        invalid = True
                        break
                    if depth > _ROLLING_PAPER_IDENTITY_MAX_DEPTH:
                        invalid = True
                        continue
                    for name in wanted:
                        if name not in item:
                            continue
                        raw = item[name]
                        if isinstance(raw, (Mapping, list, tuple, set, frozenset)):
                            invalid = True
                            continue
                        text = _binding_value(raw)
                        if text:
                            values.add(text)
                    for key, child in item.items():
                        key_name = str(key).strip().lower()
                        if isinstance(child, (list, tuple, set, frozenset)):
                            if key_name in _ROLLING_NON_AUTHORITATIVE_ARRAY_KEYS:
                                continue
                            pending.append((child, depth + 1, key_name))
                        elif isinstance(child, Mapping):
                            pending.append((child, depth + 1, key_name))
                elif isinstance(item, (list, tuple, set, frozenset)):
                    if parent in _ROLLING_NON_AUTHORITATIVE_ARRAY_KEYS:
                        continue
                    if len(item) > 128:
                        invalid = True
                    for child in list(item)[:128]:
                        pending.append((child, depth + 1, parent))
            return values, invalid

        def one_identity(
            names: Sequence[str],
            *,
            missing_reason: str = "MODEL_LINEAGE_INCOMPLETE",
        ) -> str | None:
            values, truncated = identity_values(strategy, names)
            if truncated or len(values) > 1:
                raise ValueError("MODEL_LINEAGE_AMBIGUOUS")
            if not values:
                return None
            return next(iter(values))
        legacy_plan_ids: set[str] = set()

        def typed_trial_values(value: Any) -> tuple[set[str], bool]:
            trial_values, trial_invalid = identity_values(
                value,
                ("research_trial_id", "trial_id"),
            )
            source_values, source_invalid = identity_values(
                value,
                ("source_trial_id",),
            )
            legacy_plan_ids.update(
                source_id
                for source_id in source_values
                if source_id.startswith("plan-")
            )
            trial_values.update(
                source_id
                for source_id in source_values
                if not source_id.startswith("plan-")
            )
            return trial_values, trial_invalid or source_invalid


        candidate_id = one_identity(
            ("candidate_id", "candidate", "strategy_candidate_id", "source_candidate_id")
        )
        trial_values, trial_invalid = typed_trial_values(strategy)
        if trial_invalid or len(trial_values) > 1:
            raise ValueError("MODEL_LINEAGE_AMBIGUOUS")
        trial_id = next(iter(trial_values), None)
        strategy_version_id = one_identity(("strategy_version_id",))

        def load_one(
            role: str,
            identifier: str | None,
        ) -> tuple[Mapping[str, Any] | None, bool]:
            if not identifier:
                return None, False
            names = {
                "candidate": "load_candidate_lifecycle",
                "trial": "load_research_trial",
                "version": "load_strategy_version",
            }
            loader = getattr(self.store, names[role], None)
            if not callable(loader):
                return None, False
            try:
                value = loader(identifier)
            except TypeError:
                try:
                    keyword = {
                        "candidate": "candidate_id",
                        "trial": "research_trial_id",
                        "version": "strategy_version_id",
                    }[role]
                    value = loader(**{keyword: identifier})
                except (TypeError, ValueError):
                    return None, False
                except (RuntimeError, sqlite3.Error) as exc:
                    raise ValueError("MODEL_LINEAGE_LOAD_FAILED") from exc
            except ValueError:
                return None, False
            except (RuntimeError, sqlite3.Error) as exc:
                raise ValueError("MODEL_LINEAGE_LOAD_FAILED") from exc
            if isinstance(value, Mapping):
                return value, True
            if isinstance(value, (list, tuple)):
                records = [item for item in value if isinstance(item, Mapping)]
                if len(records) == 1:
                    return records[0], True
                if len(records) > 1:
                    raise ValueError("MODEL_LINEAGE_AMBIGUOUS")
            return None, False

        lineage_records: list[tuple[str, Mapping[str, Any]]] = [
            ("version", strategy)
        ]
        loaded_records: dict[str, bool] = {}
        for role, identifier in (
            ("version", strategy_version_id),
            ("trial", trial_id),
            ("candidate", candidate_id),
        ):
            if not identifier:
                loaded_records[role] = False
                continue
            loaded, available = load_one(role, identifier)
            loaded_records[role] = available
            if loaded is not None:
                lineage_records.append((role, loaded))

        def validate_linkage(
            role: str,
            record: Mapping[str, Any],
        ) -> None:
            expected = {
                "candidate": (candidate_id, ("candidate_id", "candidate", "strategy_candidate_id", "source_candidate_id")),
                "trial": (trial_id, ("research_trial_id", "trial_id", "source_trial_id")),
                "version": (strategy_version_id, ("strategy_version_id",)),
            }
            for field_name, (identity, names) in expected.items():
                if field_name == "trial":
                    values, truncated = typed_trial_values(record)
                else:
                    values, truncated = identity_values(record, names)
                if truncated or (values and identity is not None and values != {identity}):
                    raise ValueError("MODEL_LINEAGE_MISMATCH")
                if values and identity is None:
                    raise ValueError("MODEL_LINEAGE_MISMATCH")
            if role == "trial" and strategy_version_id:
                values, truncated = identity_values(record, ("strategy_version_id",))
                if truncated or values != {strategy_version_id}:
                    raise ValueError("MODEL_LINEAGE_MISMATCH")

        for role, record in lineage_records:
            validate_linkage(role, record)
        for _role, record in lineage_records:
            _trial_values, invalid = typed_trial_values(record)
            if invalid:
                raise ValueError("MODEL_LINEAGE_AMBIGUOUS")

        def named_values(
            value: Any,
            names: Sequence[str],
        ) -> tuple[set[str], bool]:
            values: set[str] = set()
            invalid = False
            pending: list[tuple[Any, int, str | None]] = [(value, 0, None)]
            seen: set[int] = set()
            visited = 0
            wanted = frozenset(names)
            while pending:
                item, depth, parent = pending.pop()
                if isinstance(item, Mapping):
                    marker = id(item)
                    if marker in seen:
                        continue
                    seen.add(marker)
                    visited += 1
                    if visited > 512 or depth > _ROLLING_MAX_PROVENANCE_DEPTH:
                        invalid = True
                        continue
                    for name in wanted:
                        if name not in item:
                            continue
                        raw = item[name]
                        if isinstance(raw, (Mapping, list, tuple, set, frozenset)):
                            invalid = True
                            continue
                        text = _binding_value(raw)
                        if text:
                            values.add(text)
                    children = list(item.items())
                    if len(children) > 512:
                        invalid = True
                        children = children[:512]
                    for key, child in reversed(children):
                        key_name = str(key).strip().lower()
                        if isinstance(child, (list, tuple, set, frozenset)):
                            if key_name in _ROLLING_NON_AUTHORITATIVE_ARRAY_KEYS:
                                continue
                            if len(child) > 128:
                                invalid = True
                            pending.append((child, depth + 1, key_name))
                        elif isinstance(child, Mapping):
                            pending.append((child, depth + 1, key_name))
                elif isinstance(item, (list, tuple, set, frozenset)):
                    if parent in _ROLLING_NON_AUTHORITATIVE_ARRAY_KEYS:
                        continue
                    for child in list(item)[:128]:
                        pending.append((child, depth + 1, parent))
            return values, invalid

        frozen_hashes: set[str] = set()
        for _role, record in lineage_records:
            values, invalid = named_values(record, _ROLLING_MODEL_HASH_FIELDS)
            if invalid:
                raise ValueError("MODEL_LINEAGE_AMBIGUOUS")
            frozen_hashes.update(values)
        frozen_plan_hashes: set[str] = set()
        for _role, record in lineage_records:
            values, invalid = named_values(record, _ROLLING_PLAN_HASH_FIELDS)
            if invalid:
                raise ValueError("MODEL_LINEAGE_AMBIGUOUS")
            frozen_plan_hashes.update(values)

        def embedded_models(
            value: Any,
            origin: str,
            *,
            depth: int = 0,
            seen: set[int] | None = None,
        ) -> list[tuple[Mapping[str, Any], str]]:
            if seen is None:
                seen = set()
            if not isinstance(value, Mapping) or depth > _ROLLING_MAX_PROVENANCE_DEPTH:
                return []
            marker = id(value)
            if marker in seen:
                return []
            seen.add(marker)
            result: list[tuple[Mapping[str, Any], str]] = []
            if "model_document" in value:
                raw_model = value.get("model_document")
                if raw_model is not None and not _rolling_model_free_marker(raw_model):
                    if not isinstance(raw_model, Mapping):
                        raise ValueError("MODEL_PLAN_NOT_EXECUTABLE")
                    result.append((dict(raw_model), origin))
            for key in (
                "payload",
                "provenance",
                "config",
                "forward_config",
                "frozen",
                "lineage",
                "forward_evidence",
                "result",
                "outcome",
            ):
                child = value.get(key)
                if isinstance(child, Mapping):
                    result.extend(
                        embedded_models(child, f"{origin}.{key}", depth=depth + 1, seen=seen)
                    )
            return result

        candidates: list[tuple[Mapping[str, Any], str]] = []
        for role, record in lineage_records:
            candidates.extend(embedded_models(record, f"{role}.embedded"))
        unique_models: list[tuple[Mapping[str, Any], str]] = []
        for model, origin in candidates:
            try:
                identity = _canonical_binding(model)
            except (TypeError, ValueError, OverflowError, RecursionError) as exc:
                raise ValueError("MODEL_PLAN_NOT_EXECUTABLE") from exc
            if any(_canonical_binding(existing) == identity for existing, _ in unique_models):
                continue
            unique_models.append((model, origin))
        if len(unique_models) > 1:
            raise ValueError("MODEL_LINEAGE_AMBIGUOUS")
        embedded_error: str | None = None
        if unique_models:
            embedded_model, _origin = unique_models[0]
            embedded_error = _rolling_model_document_error(embedded_model)
            if embedded_error is None:
                model_hash = _rolling_model_document_hash(embedded_model)
                if not frozen_hashes or frozen_hashes == {model_hash}:
                    return (
                        dict(embedded_model),
                        _rolling_model_resolution_record(
                            "embedded",
                            model_hash,
                        ),
                    )
                embedded_error = "MODEL_LINEAGE_MISMATCH"
            if embedded_error is not None:
                raise ValueError(embedded_error)

        plan_values: set[str] = set()
        for _role, record in lineage_records:
            values, truncated = identity_values(record, _ROLLING_MODEL_ID_FIELDS)
            if truncated:
                raise ValueError("MODEL_LINEAGE_AMBIGUOUS")
            plan_values.update(values)
        plan_values.update(legacy_plan_ids)
        if len(plan_values) > 1:
            raise ValueError("MODEL_LINEAGE_AMBIGUOUS")
        plan_id = next(iter(plan_values), None)
        if not plan_id:
            if embedded_error is not None:
                raise ValueError(embedded_error)
            raise ValueError("MODEL_INPUT_MISSING")
        if not candidate_id or not trial_id or not strategy_version_id:
            raise ValueError("MODEL_LINEAGE_INCOMPLETE")
        if any(not loaded_records.get(role, False) for role in ("candidate", "trial", "version")):
            raise ValueError("MODEL_LINEAGE_INCOMPLETE")

        plan_loader = getattr(self.store, "load_experiment_plan", None)
        if not callable(plan_loader):
            raise ValueError("MODEL_PLAN_MISSING")
        try:
            plan_record = plan_loader(plan_id)
        except (TypeError, ValueError):
            plan_record = None
        except (RuntimeError, sqlite3.Error) as exc:
            raise ValueError("MODEL_LINEAGE_LOAD_FAILED") from exc
        if not isinstance(plan_record, Mapping):
            raise ValueError("MODEL_PLAN_MISSING")
        declared_plan_id = _binding_value(plan_record.get("plan_id"))
        if declared_plan_id and declared_plan_id != plan_id:
            raise ValueError("MODEL_LINEAGE_MISMATCH")
        raw_plan = plan_record.get("plan")
        if not isinstance(raw_plan, Mapping):
            raise ValueError("MODEL_PLAN_NOT_EXECUTABLE")
        plan_identity_values, plan_identity_invalid = identity_values(
            plan_record,
            _ROLLING_MODEL_ID_FIELDS,
        )
        if plan_identity_invalid or plan_identity_values != {plan_id}:
            raise ValueError("MODEL_LINEAGE_MISMATCH")
        plan_hypothesis_id = _binding_value(plan_record.get("hypothesis_id"))
        lineage_hypotheses: set[str] = set()
        for _role, record in lineage_records:
            values, invalid = named_values(record, _ROLLING_MODEL_HYPOTHESIS_FIELDS)
            if invalid:
                raise ValueError("MODEL_LINEAGE_AMBIGUOUS")
            lineage_hypotheses.update(values)
        if len(lineage_hypotheses) > 1:
            raise ValueError("MODEL_LINEAGE_MISMATCH")
        if (
            plan_hypothesis_id
            and lineage_hypotheses
            and lineage_hypotheses != {plan_hypothesis_id}
        ):
            raise ValueError("MODEL_LINEAGE_MISMATCH")
        raw_plan_hypotheses, raw_plan_hypotheses_invalid = identity_values(
            raw_plan,
            _ROLLING_MODEL_HYPOTHESIS_FIELDS,
        )
        if raw_plan_hypotheses_invalid or len(raw_plan_hypotheses) > 1:
            raise ValueError("MODEL_LINEAGE_MISMATCH")
        if (
            plan_hypothesis_id
            and raw_plan_hypotheses
            and raw_plan_hypotheses != {plan_hypothesis_id}
        ):
            raise ValueError("MODEL_LINEAGE_MISMATCH")
        declared_plan_hash = _binding_value(plan_record.get("plan_hash"))
        try:
            canonical_plan_hash = _rolling_hash(raw_plan)
        except (TypeError, ValueError, OverflowError, RecursionError) as exc:
            raise ValueError("MODEL_PLAN_NOT_EXECUTABLE") from exc
        if (
            not declared_plan_hash
            or not declared_plan_hash.startswith("sha256:")
            or declared_plan_hash != declared_plan_hash.lower()
            or declared_plan_hash != canonical_plan_hash
        ):
            raise ValueError("MODEL_PLAN_HASH_MISMATCH")
        if frozen_plan_hashes and frozen_plan_hashes != {canonical_plan_hash}:
            raise ValueError("MODEL_LINEAGE_MISMATCH")
        raw_model = raw_plan.get("model_document")
        if _rolling_model_free_marker(raw_model):
            raw_model = None
        if raw_model is None and any(
            key in raw_plan for key in _ROLLING_MODEL_DOCUMENT_FIELDS
        ):
            raw_model = {
                key: raw_plan[key]
                for key in _ROLLING_MODEL_DOCUMENT_FIELDS
                if key in raw_plan
            }
        if not isinstance(raw_model, Mapping):
            raise ValueError("MODEL_INPUT_MISSING")
        model = dict(raw_model)
        model_error = _rolling_model_document_error(model)
        if model_error is not None:
            raise ValueError(model_error)
        model_hash = _rolling_model_document_hash(model)
        if not frozen_hashes:
            raise ValueError("MODEL_HASH_MISSING")
        if frozen_hashes != {model_hash}:
            raise ValueError("MODEL_LINEAGE_MISMATCH")
        return (
            model,
            _rolling_model_resolution_record(
                "experiment_plan",
                model_hash,
                plan_id=plan_id,
            ),
        )

    _resolve_rolling_model_document = _resolve_rolling_model

    def _migrate_observation_setup_intents(self, now: datetime) -> tuple[Mapping[str, Any], ...]:
        """Repair bounded legacy observation intents during ordinary rolling ticks."""
        registry = ForwardTestRegistry(self.store)
        state_loader = getattr(self.store, "get_scheduler_state", None)
        state_setter = getattr(self.store, "set_scheduler_state", None)
        state_error = False
        try:
            state = (
                state_loader(_OBSERVATION_SETUP_MIGRATION_STATE_NAME)
                if callable(state_loader)
                else None
            )
        except (sqlite3.Error, AttributeError, TypeError, ValueError, RuntimeError):
            state = None
            state_error = True
        if state_error:
            return ()
        cursor = str(state.get("cursor", "")).strip() if isinstance(state, Mapping) else ""
        try:
            scanned = list(
                registry.list_observation_intents(
                    limit=_MAX_OBSERVATION_SETUP_MIGRATION_SCAN,
                    after_experiment_id=cursor or None,
                )
            )
            if cursor and not scanned:
                scanned = list(
                    registry.list_observation_intents(
                        limit=_MAX_OBSERVATION_SETUP_MIGRATION_SCAN
                    )
                )
        except (sqlite3.Error, AttributeError, TypeError, ValueError, RuntimeError):
            scanned = []
        migrated: list[Mapping[str, Any]] = []
        persisted_failures = (
            state.get("failure_history")
            if isinstance(state, Mapping)
            else None
        )
        if not isinstance(persisted_failures, (list, tuple)):
            persisted_failures = (
                state.get("failures", ())
                if isinstance(state, Mapping)
                else ()
            )
        failure_history: list[dict[str, Any]] = [
            dict(item) for item in persisted_failures if isinstance(item, Mapping)
        ]
        failures: list[dict[str, Any]] = []
        def record_failure(item: Mapping[str, Any]) -> None:
            failure = dict(item)
            failures.append(failure)
            failure_history.append(failure)
        stale_blocked = False
        retry_blocked = False
        last_scanned = None
        for intent in scanned:
            last_scanned = intent
            config = getattr(intent, "config", None)
            if not isinstance(config, Mapping):
                continue
            config = dict(config)
            candidate_id = _binding_value(config.get("candidate_id"))
            strategy_document = config.get("strategy_document", config.get("strategy"))
            if not candidate_id or not isinstance(strategy_document, Mapping):
                continue
            # A historical intent is eligible only while its candidate remains
            # in one of the explicit handoff stages.  Missing lifecycle rows
            # and terminal/rejected rows fail closed before any registry write.
            lifecycle_loader = getattr(self.store, "load_candidate_lifecycle", None)
            if not callable(lifecycle_loader):
                continue
            try:
                lifecycle = lifecycle_loader(candidate_id)
            except (
                sqlite3.Error,
                AttributeError,
                KeyError,
                TypeError,
                ValueError,
                RuntimeError,
            ):
                lifecycle = None
            if lifecycle is not None:
                if not isinstance(lifecycle, Mapping):
                    continue
                stage = str(
                    getattr(
                        lifecycle.get("stage"),
                        "value",
                        lifecycle.get("stage"),
                    )
                    or ""
                ).strip().upper()
                if stage not in {
                    "SCHEMA_VALIDATED",
                    "PAPER_FORWARD",
                    "PAPER_PROMOTABLE",
                }:
                    continue
            if (
                config.get("canonical_operational_setup_required") is True
                and config.get("observation_capture_only") is not True
                and isinstance(config.get("observation_handoff"), Mapping)
            ):
                try:
                    setup = config.get("operational_setup")
                    setup_hash = _binding_value(config.get("operational_setup_hash"))
                    linked_spec = next(
                        (
                            candidate
                            for candidate in registry.list()
                            if (
                                isinstance(
                                    getattr(candidate, "config", None), Mapping
                                )
                                and candidate.config.get("market_authority_required")
                                is True
                                and _binding_value(candidate.config.get("candidate_id"))
                                == candidate_id
                                and _binding_value(candidate.experiment_id)
                                == _binding_value(
                                    (
                                        lifecycle.get("payload", {})
                                        if isinstance(lifecycle, Mapping)
                                        else {}
                                    ).get("forward_test_id")
                                )
                                and bool(candidate.allowed_markets)
                            )
                        ),
                        None,
                    )
                    lifecycle_payload = (
                        lifecycle.get("payload")
                        if isinstance(lifecycle, Mapping)
                        else None
                    )
                    if (
                        isinstance(setup, Mapping)
                        and setup_hash
                        and _operational_setup_hash(setup) == setup_hash
                        and linked_spec is not None
                        and isinstance(lifecycle_payload, Mapping)
                        and _binding_value(
                            lifecycle_payload.get("paper_observation_intent_id")
                        )
                        == str(getattr(intent, "experiment_id", "")).strip()
                        and _binding_value(lifecycle_payload.get("forward_test_id"))
                        == str(linked_spec.experiment_id).strip()
                    ):
                        continue
                except (
                    AttributeError,
                    KeyError,
                    TypeError,
                    ValueError,
                    RuntimeError,
                ):
                    pass
            try:
                current_intent_id = str(getattr(intent, "experiment_id", "")).strip()

                def valid_successor(existing: Any) -> bool:
                    existing_id = str(getattr(existing, "experiment_id", "")).strip()
                    existing_config = (
                        existing.config
                        if isinstance(getattr(existing, "config", None), Mapping)
                        else {}
                    )
                    if (
                        not existing_id
                        or existing_id == current_intent_id
                        or _binding_value(existing_config.get("candidate_id"))
                        != candidate_id
                        or not isinstance(
                            existing_config.get("observation_handoff"), Mapping
                        )
                    ):
                        return False
                    if (
                        _binding_value(
                            existing_config["observation_handoff"].get(
                                "predecessor_observation_intent_id"
                            )
                        )
                        != current_intent_id
                    ):
                        return False
                    source_scope = config.get("market_scope", config.get("scope"))
                    existing_scope = existing_config.get(
                        "market_scope", existing_config.get("scope")
                    )
                    if (
                        not isinstance(source_scope, Mapping)
                        or not isinstance(existing_scope, Mapping)
                        or _canonical_binding(source_scope)
                        != _canonical_binding(existing_scope)
                    ):
                        return False
                    try:
                        source_policy = normalize_market_scope(source_scope)
                        existing_policy = normalize_market_scope(existing_scope)
                    except (TypeError, ValueError):
                        return False
                    if source_policy.as_dict() != existing_policy.as_dict():
                        return False
                    scope_ids = tuple(
                        _binding_value(value)
                        for value in source_policy.market_ids
                        if _binding_value(value)
                    )
                    capture_successor = (
                        existing_config.get("observation_capture_only") is True
                    )
                    if capture_successor:
                        for name, expected in {
                            "observation_capture_only": True,
                            "observation_only_lineage": True,
                            "observation_intent": True,
                            "paper_only": True,
                            "selection_excluded": True,
                            "allocation_active": False,
                            "canary_armed": False,
                            "market_authority_required": False,
                        }.items():
                            if (
                                type(existing_config.get(name)) is not bool
                                or existing_config.get(name) is not expected
                            ):
                                return False
                        if existing_config.get("execution_scope") != "OBSERVATION":
                            return False
                        bound_market = _binding_value(
                            existing_config.get("capture_market_id")
                        )
                        if not bound_market:
                            return False
                        current_resolution_loader = getattr(
                            self.store,
                            "load_market_scope_resolution",
                            None,
                        )
                        if not callable(current_resolution_loader):
                            return False
                        try:
                            current_proof = current_resolution_loader(
                                candidate_id,
                                scope_hash=source_policy.scope_hash,
                                scope_version=source_policy.scope_version,
                            )
                            if hasattr(current_proof, "as_dict") and callable(
                                current_proof.as_dict
                            ):
                                current_proof = current_proof.as_dict()
                        except (
                            sqlite3.Error,
                            AttributeError,
                            KeyError,
                            TypeError,
                            ValueError,
                            RuntimeError,
                        ):
                            return False
                        if (
                            not isinstance(current_proof, Mapping)
                            or str(current_proof.get("status", "")).strip().upper()
                            != "MATCHED"
                        ):
                            return False
                        current_matched = current_proof.get(
                            "matched_markets",
                            current_proof.get("resolved_markets", ()),
                        )
                        if isinstance(current_matched, str):
                            current_matched = (current_matched,)
                        if not isinstance(current_matched, (list, tuple, set, frozenset)):
                            return False
                        current_ids = {
                            _binding_value(
                                item.get("market_id", item.get("id"))
                                if isinstance(item, Mapping)
                                else getattr(item, "market_id", item)
                            )
                            for item in current_matched
                            if _binding_value(
                                item.get("market_id", item.get("id"))
                                if isinstance(item, Mapping)
                                else getattr(item, "market_id", item)
                            )
                        }
                        if not current_ids or bound_market not in current_ids:
                            return False
                        existing_current_ids = tuple(
                            sorted(
                                _binding_value(item)
                                for item in existing_config.get("current_market_ids", ())
                                if _binding_value(item)
                            )
                        )
                        if existing_current_ids != tuple(sorted(current_ids)):
                            return False
                        try:
                            strict_sla = float(
                                existing_config.get(
                                    "scope_resolution_freshness_sla_seconds"
                                )
                            )
                        except (TypeError, ValueError, OverflowError):
                            return False
                        if not math.isfinite(strict_sla) or strict_sla <= 0:
                            return False
                        proof = existing_config.get("scope_resolution")
                        lifecycle_payload_for_check = (
                            lifecycle.get("payload")
                            if isinstance(lifecycle, Mapping)
                            else None
                        )
                        lifecycle_proof_for_check = (
                            lifecycle_payload_for_check.get(
                                "scope_resolution",
                                lifecycle_payload_for_check.get(
                                    "market_scope_resolution"
                                ),
                            )
                            if isinstance(lifecycle_payload_for_check, Mapping)
                            else None
                        )
                        if (
                            not isinstance(proof, Mapping)
                            or not isinstance(lifecycle_proof_for_check, Mapping)
                            or _semantic_scope_resolution(lifecycle_proof_for_check)
                            != _semantic_scope_resolution(proof)
                            or str(proof.get("status", "")).strip().upper()
                            != "MATCHED"
                            or _binding_value(proof.get("candidate_id"))
                            != candidate_id
                            or _binding_value(proof.get("scope_hash"))
                            != source_policy.scope_hash
                            or _binding_value(proof.get("scope_version"))
                            != source_policy.scope_version
                        ):
                            return False
                        resolved_at = parse_timestamp(
                            lifecycle_proof_for_check.get("resolved_at")
                        )
                        if (
                            resolved_at is None
                            or (ensure_utc(now) - ensure_utc(resolved_at)).total_seconds()
                            < 0
                            or (ensure_utc(now) - ensure_utc(resolved_at)).total_seconds()
                            > strict_sla
                        ):
                            return False
                    else:
                        if (
                            existing_config.get("canonical_operational_setup_required")
                            is not True
                            or existing_config.get("market_authority_required") is not False
                        ):
                            return False
                        setup = existing_config.get("operational_setup")
                        setup_hash = _binding_value(
                            existing_config.get("operational_setup_hash")
                        )
                        if not isinstance(setup, Mapping) or not setup_hash:
                            return False
                        try:
                            if _operational_setup_hash(setup) != setup_hash:
                                return False
                        except (TypeError, ValueError):
                            return False
                    identity_fields = (
                        "candidate_id",
                        "strategy_version_id",
                        "research_trial_id",
                        "source_strategy_hash",
                        "rolling_strategy_hash",
                        "market_scope_hash",
                        "market_scope_version",
                    )
                    for field in identity_fields:
                        if _binding_value(existing_config.get(field)) != _binding_value(
                            config.get(field)
                        ):
                            return False
                    try:
                        linked = [
                            materialized
                            for materialized in registry.list()
                            if str(getattr(materialized, "experiment_id", "")).strip()
                            != existing_id
                            and bool(materialized.allowed_markets)
                        ]
                    except (AttributeError, TypeError, ValueError, RuntimeError):
                        return False
                    for materialized in linked:
                        materialized_config = (
                            materialized.config
                            if isinstance(getattr(materialized, "config", None), Mapping)
                            else {}
                        )
                        if (
                            _binding_value(materialized_config.get("candidate_id"))
                            != candidate_id
                            or materialized_config.get("market_authority_required")
                            is not True
                            or set(str(item).strip() for item in materialized.allowed_markets)
                            != set(scope_ids)
                        ):
                            continue
                        if _canonical_binding(
                            materialized_config.get("market_scope", {})
                        ) != _canonical_binding(existing_scope):
                            continue
                        if any(
                            _binding_value(materialized_config.get(field))
                            != _binding_value(existing_config.get(field))
                            for field in identity_fields
                        ):
                            continue
                        lifecycle_payload = (
                            lifecycle.get("payload")
                            if isinstance(lifecycle, Mapping)
                            else None
                        )
                        if not isinstance(lifecycle_payload, Mapping):
                            continue
                        if (
                            _binding_value(lifecycle_payload.get("candidate_id"))
                            != candidate_id
                            or _binding_value(
                                lifecycle_payload.get("paper_observation_intent_id")
                            )
                            != existing_id
                            or _binding_value(
                                lifecycle_payload.get("forward_test_id")
                            )
                            != str(materialized.experiment_id).strip()
                            or set(
                                str(item).strip()
                                for item in lifecycle_payload.get(
                                    "allowed_markets", ()
                                )
                            )
                            != set(scope_ids)
                            or _binding_value(lifecycle_payload.get("scope_hash"))
                            != source_policy.scope_hash
                            or _binding_value(lifecycle_payload.get("scope_version"))
                            != source_policy.scope_version
                        ):
                            continue
                        lifecycle_safety_valid = True
                        for name, expected in {
                            "paper_observation_intent": True,
                            "paper_only": True,
                            "research_only": True,
                            "observation_only_lineage": True,
                            "selection_excluded": True,
                            "allocation_active": False,
                            "canary_armed": False,
                        }.items():
                            if (
                                type(lifecycle_payload.get(name)) is not bool
                                or lifecycle_payload.get(name) is not expected
                            ):
                                lifecycle_safety_valid = False
                                break
                        if (
                            not lifecycle_safety_valid
                            or lifecycle_payload.get("execution_scope")
                            != "OBSERVATION"
                        ):
                            continue
                        lifecycle_proof = lifecycle_payload.get(
                            "scope_resolution",
                            lifecycle_payload.get("market_scope_resolution"),
                        )
                        if (
                            not isinstance(lifecycle_proof, Mapping)
                            or _semantic_scope_resolution(lifecycle_proof)
                            != _semantic_scope_resolution(
                                existing_config.get("scope_resolution", {})
                            )
                        ):
                            continue
                        proof_loader = getattr(
                            self.store, "load_market_scope_resolution", None
                        )
                        if callable(proof_loader):
                            try:
                                current_proof = proof_loader(
                                    candidate_id,
                                    scope_hash=source_policy.scope_hash,
                                    scope_version=source_policy.scope_version,
                                )
                            except TypeError:
                                current_proof = proof_loader(candidate_id)
                            if hasattr(current_proof, "as_dict") and callable(
                                current_proof.as_dict
                            ):
                                current_proof = current_proof.as_dict()
                            if isinstance(current_proof, Mapping):
                                if (
                                    _semantic_scope_resolution(current_proof)
                                    != _semantic_scope_resolution(lifecycle_proof)
                                    or str(
                                        current_proof.get("resolved_at", "")
                                    ).strip()
                                    != str(
                                        lifecycle_proof.get("resolved_at", "")
                                    ).strip()
                                ):
                                    return False
                        return True
                    return False

                existing_successor = any(
                    valid_successor(existing) for existing in scanned
                )
            except (sqlite3.Error, AttributeError, TypeError, ValueError, RuntimeError):
                existing_successor = False
            if existing_successor:
                continue
            try:
                derived_setup = _operational_setup_for_strategy(strategy_document, config)
            except (sqlite3.Error, AttributeError, KeyError, TypeError, ValueError, RuntimeError) as exc:
                record_failure(
                    {"experiment_id": str(getattr(intent, "experiment_id", "")), "reason": str(exc)[:160]}
                )
                continue
            capture_marker = config.get("observation_capture_only") is True
            capture_only = capture_marker or derived_setup is None
            if capture_only:
                family = str(strategy_document.get("family", "")).strip().lower()
                parameters = strategy_document.get("parameters")
                if not isinstance(parameters, Mapping):
                    continue
                try:
                    lookback = parameters.get("lookback")
                    threshold = float(parameters.get("threshold"))
                except (TypeError, ValueError, OverflowError):
                    continue
                supported_capture = False
                if family in {"momentum", "mean_reversion"}:
                    supported_capture = (
                        type(lookback) is int
                        and lookback == 1
                        and threshold == 0.05
                    )
                elif family == "probability_mispricing":
                    supported_capture = threshold == 0.05
                if not supported_capture:
                    continue
            unchanged_setup = False
            if not capture_only:
                try:
                    existing_setup = config.get("operational_setup")
                    existing_hash = str(config.get("operational_setup_hash", "") or "").strip()
                    unchanged_setup = (
                        isinstance(existing_setup, Mapping)
                        and existing_hash == _operational_setup_hash(existing_setup)
                        and _canonical_binding(existing_setup) == _canonical_binding(derived_setup)
                    )
                except (sqlite3.Error, AttributeError, KeyError, TypeError, ValueError, RuntimeError) as exc:
                    record_failure(
                        {"experiment_id": str(getattr(intent, "experiment_id", "")), "reason": str(exc)[:160]}
                    )
                    continue
            if unchanged_setup:
                continue
            scope = config.get("market_scope", config.get("scope", {}))
            scope = scope if isinstance(scope, Mapping) else {}
            loader = getattr(self.store, "load_market_scope_resolution", None)
            if not callable(loader):
                continue
            try:
                policy = normalize_market_scope(scope)
                # The persisted row is the sole authority.  In particular,
                # never reuse a proof embedded in the old intent.
                proof = loader(
                    candidate_id,
                    scope_hash=policy.scope_hash,
                    scope_version=policy.scope_version,
                )
                if hasattr(proof, "as_dict") and callable(proof.as_dict):
                    proof = proof.as_dict()
                if not isinstance(proof, Mapping):
                    raise ValueError("CURRENT_SCOPE_PROOF_UNAVAILABLE")
                if str(proof.get("status", "")).strip().upper() != "MATCHED":
                    raise ValueError("CURRENT_SCOPE_PROOF_NOT_MATCHED")
                if str(proof.get("candidate_id", "")).strip() != candidate_id:
                    raise ValueError("CURRENT_SCOPE_PROOF_CANDIDATE_MISMATCH")
                proof_policy = proof.get("policy")
                if isinstance(proof_policy, Mapping):
                    nested_hash = str(
                        proof_policy.get("scope_hash", proof_policy.get("market_scope_hash", ""))
                    ).strip()
                    nested_version = str(
                        proof_policy.get(
                            "scope_version",
                            proof_policy.get("market_scope_version", proof_policy.get("version", "")),
                        )
                    ).strip()
                    if nested_hash and nested_hash != policy.scope_hash:
                        raise ValueError("CURRENT_SCOPE_PROOF_POLICY_HASH_MISMATCH")
                    if nested_version and nested_version != policy.scope_version:
                        raise ValueError("CURRENT_SCOPE_PROOF_POLICY_VERSION_MISMATCH")
                if str(proof.get("scope_hash", proof.get("market_scope_hash", ""))).strip() != policy.scope_hash:
                    raise ValueError("CURRENT_SCOPE_PROOF_HASH_MISMATCH")
                if str(
                    proof.get("scope_version", proof.get("market_scope_version", proof.get("version", "")))
                ).strip() != policy.scope_version:
                    raise ValueError("CURRENT_SCOPE_PROOF_VERSION_MISMATCH")
                resolved_at = parse_timestamp(proof.get("resolved_at"))
                if resolved_at is None:
                    raise ValueError("CURRENT_SCOPE_PROOF_TIMESTAMP_MISSING")
                strict_declared = config.get("scope_resolution_freshness_sla_seconds")
                if "scope_resolution_freshness_sla_seconds" in config:
                    try:
                        strict_value = float(strict_declared)
                    except (TypeError, ValueError, OverflowError):
                        raise ValueError("CURRENT_SCOPE_PROOF_SLA_UNAVAILABLE") from None
                    if not math.isfinite(strict_value) or strict_value <= 0:
                        raise ValueError("CURRENT_SCOPE_PROOF_SLA_UNAVAILABLE")
                freshness_value = getattr(
                    getattr(self, "config", None),
                    "observation_setup_migration_freshness_sla_seconds",
                    None,
                )
                if freshness_value is None:
                    freshness_value = config.get("freshness_sla_seconds")
                if freshness_value is None:
                    freshness_value = getattr(
                        getattr(self, "config", None),
                        "freshness_sla_seconds",
                        None,
                    )
                if freshness_value is None:
                    freshness_value = getattr(
                        getattr(self, "config", None),
                        "scope_resolution_freshness_sla_seconds",
                        None,
                    )
                if freshness_value is None:
                    freshness_value = 3600.0
                try:
                    freshness = float(freshness_value)
                except (TypeError, ValueError, OverflowError):
                    raise ValueError("CURRENT_SCOPE_PROOF_SLA_UNAVAILABLE") from None
                if strict_declared is not None:
                    freshness = min(freshness, float(strict_declared))
                # ``now`` is the rolling tick's start timestamp.  A scope
                # resolver may commit a newer proof while this migration is
                # loading it, so freshness must use a post-load clock read.
                # A proof still in the future relative to that read remains
                # a genuine clock-skew failure.
                clock = getattr(self, "clock", None)
                clock_now = ensure_utc(clock() if callable(clock) else now)
                freshness_now = max(ensure_utc(now), clock_now)
                age = (freshness_now - ensure_utc(resolved_at)).total_seconds()
                if not math.isfinite(freshness) or freshness <= 0 or age < 0 or age > freshness:
                    raise ValueError("CURRENT_SCOPE_PROOF_STALE")

                def proof_ids(value: Any, *, name: str) -> tuple[str, ...]:
                    if value in (None, ""):
                        return ()
                    values = (value,) if isinstance(value, str) else value
                    if not isinstance(values, (list, tuple, set, frozenset)):
                        raise ValueError(f"{name}_MALFORMED")
                    result: list[str] = []
                    for item in values:
                        if isinstance(item, Mapping):
                            item = item.get("market_id", item.get("id"))
                        else:
                            item = getattr(item, "market_id", item)
                        text = str(item).strip() if item is not None else ""
                        if not text or text in result:
                            raise ValueError(f"{name}_MALFORMED")
                        result.append(text)
                    return tuple(result)

                matched_ids = proof_ids(
                    proof.get("matched_markets", proof.get("resolved_markets", ())),
                    name="MATCHED_MARKETS",
                )
                if not matched_ids:
                    raise ValueError("CURRENT_SCOPE_PROOF_EMPTY")
                excluded_ids = proof_ids(
                    proof.get("excluded_markets", proof.get("excluded_market_ids", ())),
                    name="EXCLUDED_MARKETS",
                )
                if set(matched_ids).intersection(excluded_ids):
                    raise ValueError("CURRENT_SCOPE_PROOF_OVERLAP")
                deferred_ids = proof_ids(
                    proof.get("deferred_markets", proof.get("deferred_market_ids", ())),
                    name="DEFERRED_MARKETS",
                )
                if deferred_ids:
                    raise ValueError("CURRENT_SCOPE_PROOF_DEFERRED")
            except (sqlite3.Error, AttributeError, KeyError, TypeError, ValueError, RuntimeError) as exc:
                reason = str(exc)[:160]
                record_failure(
                    {"experiment_id": str(getattr(intent, "experiment_id", "")), "reason": reason}
                )
                if reason == "CURRENT_SCOPE_PROOF_STALE":
                    stale_blocked = True
                    break
                continue
            try:
                strategy: dict[str, Any] = {
                    **config,
                    "candidate_id": candidate_id,
                    "strategy_document": dict(strategy_document),
                    "strategy_hash": _binding_value(
                        config.get("strategy_hash", getattr(intent, "strategy_hash", ""))
                    ),
                    "strategy_version_id": _binding_value(config.get("strategy_version_id")),
                    "research_trial_id": _binding_value(config.get("research_trial_id")),
                    "scope_resolution": dict(proof),
                    "observation_capture_only": capture_only,
                }
                if capture_only:
                    current_market_ids = tuple(
                        sorted(
                            {
                                _binding_value(item)
                                for item in matched_ids
                                if _binding_value(item)
                            }
                        )
                    )
                    supplied_capture_market = _binding_value(
                        strategy.get("capture_market_id")
                    )
                    strategy["capture_market_id"] = (
                        supplied_capture_market
                        if supplied_capture_market in current_market_ids
                        else (current_market_ids[0] if current_market_ids else None)
                    )
                    predecessor_setup_hash = str(
                        strategy.get("operational_setup_hash", "") or ""
                    ).strip()
                    strategy.pop("operational_setup", None)
                    strategy.pop("operational_setup_hash", None)
                    if predecessor_setup_hash:
                        strategy["predecessor_operational_setup_hash"] = predecessor_setup_hash
                else:
                    strategy["operational_setup"] = dict(derived_setup)
                    strategy["operational_setup_hash"] = _operational_setup_hash(derived_setup)
                if not strategy["strategy_hash"]:
                    strategy["strategy_hash"] = str(getattr(intent, "strategy_hash", "")).strip()
            except (sqlite3.Error, AttributeError, KeyError, TypeError, ValueError, RuntimeError) as exc:
                record_failure(
                    {"experiment_id": str(getattr(intent, "experiment_id", "")), "reason": str(exc)[:160]}
                )
                continue
            try:
                binding = self._ensure_rolling_paper_observation(
                    strategy,
                    now,
                    market_ids=matched_ids,
                )
            except (sqlite3.Error, AttributeError, KeyError, RuntimeError, TypeError, ValueError) as exc:
                record_failure(
                    {"experiment_id": str(getattr(intent, "experiment_id", "")), "reason": str(exc)[:160]}
                )
                retryable = isinstance(exc, SQLiteBusyTimeout) or (
                    isinstance(exc, sqlite3.OperationalError)
                    and any(
                        marker in str(exc).lower()
                        for marker in (
                            "database is locked",
                            "database table is locked",
                            "sqlite_busy",
                        )
                    )
                )
                if retryable:
                    retry_blocked = True
                    break
                continue
            # Materialization can perform several durable writes.  Recheck
            # the original proof after those writes and fail closed before
            # linking an observation successor whose authority expired.
            post_clock = getattr(self, "clock", None)
            post_clock_now = ensure_utc(post_clock() if callable(post_clock) else now)
            post_now = max(ensure_utc(now), post_clock_now)
            post_age = (post_now - ensure_utc(resolved_at)).total_seconds()
            if post_age < 0 or post_age > freshness:
                record_failure(
                    {
                        "experiment_id": str(getattr(intent, "experiment_id", "")),
                        "reason": "CURRENT_SCOPE_PROOF_STALE",
                    }
                )
                stale_blocked = True
                break
            if (
                isinstance(binding, Mapping)
                and isinstance(lifecycle, Mapping)
                and callable(getattr(self.store, "load_forward_tests", None))
            ):
                try:
                    intent_id = _binding_value(binding.get("intent_id"))
                    predecessor_intent_ids = {
                        str(getattr(intent, "experiment_id", "")).strip()
                    }
                    source_handoff = config.get("observation_handoff")
                    if isinstance(source_handoff, Mapping):
                        predecessor_intent_ids.add(
                            _binding_value(
                                source_handoff.get("predecessor_observation_intent_id")
                            )
                        )
                    predecessor_intent_ids.discard("")
                    def capture_binding_is_current(candidate: Any) -> bool:
                        candidate_config = (
                            candidate.config
                            if isinstance(
                                getattr(candidate, "config", None), Mapping
                            )
                            else {}
                        )
                        if (
                            candidate_config.get("observation_capture_only")
                            is not True
                        ):
                            return True
                        capture_market_id = _binding_value(
                            candidate_config.get("capture_market_id")
                        )
                        allowed_market_ids = {
                            _binding_value(item)
                            for item in getattr(candidate, "allowed_markets", ())
                            if _binding_value(item)
                        }
                        current_market_ids = {
                            _binding_value(item)
                            for item in matched_ids
                            if _binding_value(item)
                        }
                        return bool(
                            capture_market_id
                            and capture_market_id in allowed_market_ids
                            and capture_market_id in current_market_ids
                        )

                    materialized = next(
                        (
                            candidate
                            for candidate in registry.list()
                            if _binding_value(
                                (
                                    candidate.config
                                    if isinstance(
                                        getattr(candidate, "config", None), Mapping
                                    )
                                    else {}
                                ).get("candidate_id")
                            )
                            == candidate_id
                            and _binding_value(
                                (
                                    candidate.config
                                    if isinstance(
                                        getattr(candidate, "config", None), Mapping
                                    )
                                    else {}
                                ).get("observation_intent_id")
                                or (
                                    candidate.config
                                    if isinstance(
                                        getattr(candidate, "config", None), Mapping
                                    )
                                    else {}
                                ).get("paper_observation_intent_id")
                            )
                            == intent_id
                            and _binding_value(
                                (
                                    (
                                        candidate.config
                                        if isinstance(
                                            getattr(candidate, "config", None), Mapping
                                        )
                                        else {}
                                    ).get("observation_handoff")
                                    or {}
                                ).get("predecessor_observation_intent_id")
                            )
                            in predecessor_intent_ids
                            and (
                                candidate.config
                                if isinstance(
                                    getattr(candidate, "config", None), Mapping
                                )
                                else {}
                            ).get("market_authority_required")
                            is True
                            and set(
                                str(item).strip()
                                for item in getattr(candidate, "allowed_markets", ())
                            )
                            == set(str(item).strip() for item in matched_ids)
                            and capture_binding_is_current(candidate)
                        ),
                        None,
                    )
                    lifecycle_stage = str(
                        getattr(
                            lifecycle.get("stage"),
                            "value",
                            lifecycle.get("stage"),
                        )
                        or ""
                    ).strip()
                    lifecycle_payload = lifecycle.get("payload")
                    if (
                        materialized is not None
                        and intent_id
                        and lifecycle_stage
                        and isinstance(lifecycle_payload, Mapping)
                        and callable(
                            getattr(self.store, "save_candidate_lifecycle", None)
                        )
                    ):
                        materialized_config = (
                            materialized.config
                            if isinstance(
                                getattr(materialized, "config", None), Mapping
                            )
                            else {}
                        )
                        body = dict(lifecycle_payload)
                        body.update(
                            {
                                "candidate_id": candidate_id,
                                "paper_observation_intent": True,
                                "paper_observation_intent_id": intent_id,
                                "forward_test_id": str(
                                    materialized.experiment_id
                                ).strip(),
                                "paper_only": True,
                                "research_only": True,
                                "execution_scope": "OBSERVATION",
                                "observation_only_lineage": True,
                                "selection_excluded": True,
                                "allocation_active": False,
                                "canary_armed": False,
                                "allowed_markets": list(materialized.allowed_markets),
                                "current_market_ids": list(matched_ids),
                                "resolved_market_ids": list(matched_ids),
                                "scope_hash": policy.scope_hash,
                                "scope_version": policy.scope_version,
                                "scope_resolution": dict(proof),
                                "market_scope_resolution": dict(proof),
                            }
                        )
                        for field in (
                            "candidate_id",
                            "strategy_version_id",
                            "research_trial_id",
                            "source_strategy_hash",
                            "rolling_strategy_hash",
                            "market_scope_hash",
                            "market_scope_version",
                        ):
                            if field in materialized_config:
                                body[field] = materialized_config[field]
                        self.store.save_candidate_lifecycle(
                            candidate_id,
                            lifecycle_stage,
                            body,
                            from_stage=lifecycle_stage,
                            reason="reconciled immutable observation successor",
                            timestamp=now,
                        )
                except (
                    sqlite3.Error,
                    AttributeError,
                    KeyError,
                    TypeError,
                    ValueError,
                    RuntimeError,
                ) as exc:
                    record_failure(
                        {
                            "experiment_id": str(getattr(intent, "experiment_id", "")),
                            "reason": f"LIFECYCLE_RECONCILE:{str(exc)[:140]}",
                        }
                    )
            if isinstance(binding, Mapping):
                migrated.append(dict(binding))
                break
        if callable(state_setter):
            next_cursor = (
                cursor
                if stale_blocked or retry_blocked
                else (str(getattr(last_scanned, "experiment_id", "")) if last_scanned is not None else "")
            )
            try:
                state_setter(
                    _OBSERVATION_SETUP_MIGRATION_STATE_NAME,
                    {
                        "schema_version": "autonomous-observation-setup-v1",
                        "updated_at": ensure_utc(now).isoformat(),
                        "cursor": next_cursor,
                        "failure_history": failure_history[-256:],
                        "failures": failures[-64:],
                    },
                )
            except (sqlite3.Error, TypeError, ValueError, RuntimeError):
                pass
        return tuple(migrated)
    def _rolling_current_market_bindings(
        self,
        strategy: Mapping[str, Any],
        now: datetime,
    ) -> tuple[dict[str, Any], ...]:
        """Return a bounded set of fresh, directly validated current markets.

        Scope resolution is the policy authority; tracked metadata/snapshots
        provide the independent public-market freshness and depth proof.  The
        result is intentionally partial: one valid market is enough to keep a
        paper observation moving, while stale or incomplete candidates are
        excluded without rebinding a closed scope.
        """
        candidate_id = _binding_value(strategy.get("candidate_id"))
        if not candidate_id:
            return ()
        loader = getattr(self.store, "load_market_scope_resolution", None)
        if not callable(loader):
            return ()
        scope = _rolling_source_binding(strategy).get(
            "market_scope",
            _rolling_source_binding(strategy).get("scope", {}),
        )
        scope = scope if isinstance(scope, Mapping) else {}
        try:
            policy = normalize_market_scope(scope) if scope else None
            resolution = (
                loader(
                    candidate_id,
                    scope_hash=policy.scope_hash,
                    scope_version=policy.scope_version,
                )
                if policy is not None
                else loader(candidate_id)
            )
        except (AttributeError, TypeError, ValueError, RuntimeError):
            try:
                resolution = loader(candidate_id)
            except (AttributeError, TypeError, ValueError, RuntimeError):
                return ()
        if resolution is None:
            return ()
        status = str(
            getattr(resolution, "status", None)
            if not isinstance(resolution, Mapping)
            else resolution.get("status", "")
        ).strip().upper()
        if status not in {"MATCHED", "PARTIAL"}:
            return ()
        resolved_at = _rolling_timestamp(
            getattr(resolution, "resolved_at", None)
            if not isinstance(resolution, Mapping)
            else resolution.get("resolved_at")
        )
        requested_scope_hash = (
            policy.scope_hash if policy is not None else ""
        )
        requested_scope_version = (
            policy.scope_version if policy is not None else ""
        )
        resolved_scope_hash = _binding_value(
            resolution.get("scope_hash")
            if isinstance(resolution, Mapping)
            else getattr(resolution, "scope_hash", None)
        )
        resolved_scope_version = _binding_value(
            resolution.get("scope_version")
            if isinstance(resolution, Mapping)
            else getattr(resolution, "scope_version", None)
        )
        resolution_policy = (
            resolution.get("policy")
            if isinstance(resolution, Mapping)
            else getattr(resolution, "policy", None)
        )
        if isinstance(resolution_policy, Mapping):
            nested_hash = _binding_value(
                resolution_policy.get(
                    "scope_hash",
                    resolution_policy.get("market_scope_hash"),
                )
            )
            nested_version = _binding_value(
                resolution_policy.get(
                    "scope_version",
                    resolution_policy.get(
                        "market_scope_version",
                        resolution_policy.get("version"),
                    ),
                )
            )
            if (
                (resolved_scope_hash and nested_hash and resolved_scope_hash != nested_hash)
                or (
                    resolved_scope_version
                    and nested_version
                    and resolved_scope_version != nested_version
                )
            ):
                return ()
            resolved_scope_hash = resolved_scope_hash or nested_hash
            resolved_scope_version = resolved_scope_version or nested_version
        if requested_scope_hash and resolved_scope_hash != requested_scope_hash:
            return ()
        if requested_scope_version and resolved_scope_version != requested_scope_version:
            return ()
        if (
            requested_scope_hash
            and requested_scope_version
            and (not resolved_scope_hash or not resolved_scope_version)
        ):
            return ()
        freshness = strategy.get(
            "scope_resolution_freshness_sla_seconds",
            _EXPLORATORY_MARKET_FRESHNESS_SECONDS,
        )
        try:
            freshness = float(freshness)
        except (TypeError, ValueError, OverflowError):
            freshness = _EXPLORATORY_MARKET_FRESHNESS_SECONDS
        if (
            not math.isfinite(freshness)
            or freshness <= 0
            or resolved_at is None
            or resolved_at > ensure_utc(now)
            or (ensure_utc(now) - resolved_at).total_seconds() > freshness
        ):
            return ()
        matched = (
            resolution.get("matched_markets", ())
            if isinstance(resolution, Mapping)
            else getattr(resolution, "matched_markets", ())
        )
        if not isinstance(matched, (list, tuple)):
            return ()
        candidate_markets: list[dict[str, Any]] = []
        for raw in matched[:_EXPLORATORY_POOL_CAP]:
            if isinstance(raw, Mapping):
                item = dict(raw)
            else:
                as_dict = getattr(raw, "as_dict", None)
                item = dict(as_dict()) if callable(as_dict) else {}
            market_id = _binding_value(item.get("market_id", item.get("id")))
            yes_token = _binding_value(
                item.get("yes_token_id", item.get("yesTokenId", item.get("yes_token")))
            )
            no_token = _binding_value(
                item.get("no_token_id", item.get("noTokenId", item.get("no_token")))
            )
            if not market_id or not yes_token or not no_token:
                continue
            candidate_markets.append(
                {
                    "market_id": market_id,
                    "condition_id": _binding_value(item.get("condition_id", item.get("condition"))),
                    "yes_token_id": yes_token,
                    "no_token_id": no_token,
                    "scope_resolution_id": _binding_value(
                        resolution.get("resolution_id")
                        if isinstance(resolution, Mapping)
                        else getattr(resolution, "resolution_id", None)
                    ),
                    "scope_hash": _binding_value(
                        resolution.get("scope_hash")
                        if isinstance(resolution, Mapping)
                        else getattr(resolution, "scope_hash", None)
                    ),
                    "scope_version": _binding_value(
                        resolution.get("scope_version")
                        if isinstance(resolution, Mapping)
                        else getattr(resolution, "scope_version", None)
                    ),
                }
            )
        if not candidate_markets:
            return ()
        tracked_loader = getattr(self.store, "tracked_polymarket_markets", None)
        if not callable(tracked_loader):
            return ()
        market_ids = tuple(item["market_id"] for item in candidate_markets)
        try:
            tracked = tracked_loader(
                active_only=True,
                now=ensure_utc(now),
                include_payload=True,
                market_ids=market_ids,
                limit=_EXPLORATORY_POOL_CAP,
            )
        except (AttributeError, TypeError, ValueError, RuntimeError):
            return ()
        tracked_by_id = {
            _binding_value(item.get("market_id")): item
            for item in (tracked or ())
            if isinstance(item, Mapping) and _binding_value(item.get("market_id"))
        }

        def nested(source: Any, *names: str) -> Any:
            if not isinstance(source, Mapping):
                return None
            for name in names:
                value = source.get(name)
                if value not in (None, ""):
                    return value
            for name in ("metadata", "snapshot", "payload", "extra"):
                child = source.get(name)
                if isinstance(child, Mapping):
                    value = nested(child, *names)
                    if value not in (None, ""):
                        return value
            return None
        def token_from(source: Any, side: str) -> str | None:
            if not isinstance(source, Mapping):
                return None
            direct_names = (
                ("yes_token_id", "yesTokenId", "yes_token", "yes")
                if side == "yes"
                else ("no_token_id", "noTokenId", "no_token", "no")
            )
            direct = nested(source, *direct_names)
            if direct not in (None, "") and not isinstance(direct, (Mapping, list, tuple)):
                return _binding_value(direct)
            for container_name in ("tokens", "outcomes", "outcome_tokens"):
                container = source.get(container_name)
                if isinstance(container, Mapping):
                    value = container.get(side) or container.get(f"{side}_token_id")
                    if value not in (None, "") and not isinstance(value, (Mapping, list, tuple)):
                        return _binding_value(value)
                    if isinstance(value, Mapping):
                        token = nested(value, "token_id", "tokenId", "id")
                        if token not in (None, ""):
                            return _binding_value(token)
                elif isinstance(container, (list, tuple)):
                    for value in container:
                        if not isinstance(value, Mapping):
                            continue
                        label = str(
                            value.get("outcome", value.get("name", value.get("side", "")))
                        ).strip().lower()
                        if label != side:
                            continue
                        token = nested(value, "token_id", "tokenId", "id")
                        if token not in (None, ""):
                            return _binding_value(token)
            return None


        def has_depth(book: Any) -> bool:
            if not isinstance(book, Mapping):
                return False
            sides: list[list[Any]] = []
            for name in ("bids", "asks"):
                rows = book.get(name)
                if not isinstance(rows, (list, tuple)):
                    return False
                finite_rows = []
                for row in rows:
                    if isinstance(row, Mapping):
                        price, size = row.get("price"), row.get("size", row.get("quantity"))
                    elif isinstance(row, (list, tuple)) and len(row) >= 2:
                        price, size = row[0], row[1]
                    else:
                        continue
                    try:
                        price_value, size_value = float(price), float(size)
                    except (TypeError, ValueError, OverflowError):
                        continue
                    if math.isfinite(price_value) and math.isfinite(size_value) and size_value > 0:
                        finite_rows.append(row)
                sides.append(finite_rows)
            return bool(sides[0] and sides[1])

        valid: list[dict[str, Any]] = []
        for item in candidate_markets:
            tracked_item = tracked_by_id.get(item["market_id"])
            if not isinstance(tracked_item, Mapping):
                continue
            observed_at = _rolling_timestamp(tracked_item.get("observed_at"))
            if (
                observed_at is None
                or observed_at > ensure_utc(now)
                or (ensure_utc(now) - observed_at).total_seconds() > freshness
            ):
                continue
            payload = tracked_item.get("payload")
            if not isinstance(payload, Mapping):
                continue
            metadata = nested(payload, "metadata") or {}
            snapshot = nested(payload, "snapshot") or {}
            if not isinstance(metadata, Mapping) or not isinstance(snapshot, Mapping):
                continue
            if _binding_value(nested(metadata, "market_id", "id")) not in {None, item["market_id"]}:
                continue
            tracked_yes = (
                token_from(metadata, "yes")
                or token_from(snapshot, "yes")
                or token_from(payload, "yes")
            )
            tracked_no = (
                token_from(metadata, "no")
                or token_from(snapshot, "no")
                or token_from(payload, "no")
            )
            if tracked_yes != item["yes_token_id"] or tracked_no != item["no_token_id"]:
                continue
            book = nested(snapshot, "order_book", "book") or nested(payload, "order_book", "book")
            if not has_depth(book):
                continue
            if nested(snapshot, "enable_order_book", "enableOrderBook", "book_available") is False:
                continue
            if nested(metadata, "accepting_orders", "accepting-orders") is False:
                continue
            valid.append(
                {
                    **item,
                    "book_depth": "SUITABLE",
                    "outcome_token_id": item["yes_token_id"],
                }
            )
            if len(valid) >= _EXPLORATORY_MEMBER_MAX:
                break
        return tuple(valid)



    def _ensure_rolling_paper_observation(
        self,
        strategy: Mapping[str, Any],
        now: datetime,
        *,
        market_ids: Sequence[str] = (),
    ) -> Mapping[str, Any] | None:
        """Idempotently bind each accepted rolling identity to paper work."""
        candidate_id = _binding_value(strategy.get("candidate_id"))
        strategy_version_id = _binding_value(strategy.get("strategy_version_id"))
        trial_id = _binding_value(strategy.get("research_trial_id"))
        strategy_document = strategy.get("strategy_document", strategy.get("canonical_strategy"))
        if not candidate_id or not strategy_version_id or not trial_id or not isinstance(strategy_document, Mapping):
            raise ValueError("PAPER_OBSERVATION_BINDING_INCOMPLETE")
        model_document: Mapping[str, Any] = {}
        model_resolution: Mapping[str, Any] = {}
        registry = ForwardTestRegistry(self.store)
        source_binding = _rolling_source_binding(strategy)
        dataset_id, dataset_version = _rolling_dataset_identity(strategy)
        dataset_id = dataset_id if dataset_id not in (None, "") else source_binding.get("dataset_id")
        dataset_version = (
            dataset_version
            if dataset_version not in (None, "")
            else source_binding.get("dataset_version")
        )
        scope = source_binding.get("market_scope", source_binding.get("scope", {}))
        scope = scope if isinstance(scope, Mapping) else {}
        scope_resolution = strategy.get("scope_resolution")
        if scope_resolution is None:
            loader = getattr(self.store, "load_market_scope_resolution", None)
            if callable(loader) and scope:
                try:
                    scope_policy = normalize_market_scope(scope)
                    try:
                        scope_resolution = loader(
                            candidate_id,
                            scope_hash=scope_policy.scope_hash,
                            scope_version=scope_policy.scope_version,
                        )
                    except TypeError:
                        scope_resolution = loader(candidate_id)
                except (TypeError, ValueError, AttributeError):
                    scope_resolution = None
        scope_resolution_mapping = _scope_resolution_mapping(scope_resolution)
        if scope_resolution_mapping is not None:
            scope_resolution = scope_resolution_mapping
        selector = {
            key: value
            for key, value in (
                ("dataset_id", dataset_id),
                ("dataset_version", dataset_version),
            )
            if value not in (None, "")
        }
        marker_value = strategy.get("observation_capture_only")
        if "observation_capture_only" in strategy and type(marker_value) is not bool:
            raise ValueError("OBSERVATION_CAPTURE_MARKER_INVALID")
        capture_only = marker_value is True
        if marker_value is None:
            capture_only = (
                "operational_setup" not in strategy
                and "operational_setup_hash" not in strategy
                and _operational_setup_for_strategy(strategy_document, strategy) is None
            )
        current_market_ids = tuple(
            sorted(
                {
                    _binding_value(value)
                    for value in market_ids
                    if _binding_value(value)
                }
            )
        )
        setup_value = strategy.get("operational_setup")
        setup_value = setup_value if isinstance(setup_value, Mapping) else {}
        setup_policy = setup_value.get("setup_policy")
        exploratory = (
            _exploratory_live_requested(strategy)
            or (
                isinstance(setup_policy, Mapping)
                and str(setup_policy.get("mode", "")).strip().upper()
                == "EXPLORATORY_LIVE"
            )
        )
        current_bindings = (
            self._rolling_current_market_bindings(strategy, now)
            if exploratory
            else ()
        )
        valid_binding_ids = {
            str(item.get("market_id", "")).strip()
            for item in current_bindings
            if isinstance(item, Mapping)
        }
        if exploratory and (
            not current_market_ids
            or not valid_binding_ids.intersection(current_market_ids)
        ):
            return {
                "candidate_id": candidate_id,
                "strategy_version_id": strategy_version_id,
                "research_trial_id": trial_id,
                "market_ids": [],
                "status": "WAITING_FOR_DIRECT_CURRENT_MARKET",
                "paper_only": True,
            }
        supplied_capture_market = _binding_value(strategy.get("capture_market_id"))
        capture_market_id = (
            supplied_capture_market
            if capture_only and supplied_capture_market in current_market_ids
            else (current_market_ids[0] if capture_only and current_market_ids else None)
        )
        if "scope_resolution_freshness_sla_seconds" in strategy:
            scope_sla = strategy.get("scope_resolution_freshness_sla_seconds")
        else:
            scope_sla = getattr(
                self.config,
                "scope_resolution_freshness_sla_seconds",
                None,
            )
        if scope_sla is None and isinstance(scope_resolution, Mapping):
            scope_sla = scope_resolution.get(
                "scope_resolution_freshness_sla_seconds",
                scope_resolution.get("freshness_sla_seconds"),
            )
        if capture_only:
            try:
                scope_sla = float(scope_sla)
            except (TypeError, ValueError, OverflowError):
                raise ValueError("CURRENT_SCOPE_PROOF_SLA_UNAVAILABLE") from None
            if not math.isfinite(scope_sla) or scope_sla <= 0:
                raise ValueError("CURRENT_SCOPE_PROOF_SLA_UNAVAILABLE")
        config = {
            "observation_intent": True,
            "observation_only_lineage": True,
            # Registration is an unmaterialized intent.  Authority is granted
            # only by materialize_observation_intent after scope resolution.
            "market_authority_required": False,
            "candidate_id": candidate_id,
            "strategy_version_id": strategy_version_id,
            "research_trial_id": trial_id,
            "plan_id": source_binding.get("plan_id"),
            "plan_hash": source_binding.get("plan_hash"),
            "source_strategy_hash": strategy.get("strategy_hash"),
            "rolling_strategy_hash": strategy.get("strategy_hash"),
            "strategy_document": dict(strategy_document),
            "model_document": dict(model_document),
            "model_resolution": dict(model_resolution),
            "dataset_id": dataset_id,
            "dataset_version": dataset_version,
            "dataset_selector": selector,
            "scope": dict(scope),
            "market_scope": dict(scope),
            "dataset_attestation": source_binding.get("dataset_attestation"),
            "dataset_boundary": source_binding.get("dataset_boundary"),
            "rolling_research": True,
            "research_mode": "ROLLING_RESEARCH",
            "capture_market_id": capture_market_id,
            "current_market_ids": list(current_market_ids),
            "scope_resolution_freshness_sla_seconds": scope_sla,
            "paper_only": True,
            "observation_capture_only": capture_only,
            "execution_scope": "OBSERVATION" if capture_only else None,
            "research_only": True if capture_only else None,
            "selection_excluded": True if capture_only else None,
            "allocation_active": False if capture_only else None,
            "canary_armed": False if capture_only else None,
        }
        if exploratory:
            config["operating_policy"] = dict(EXPLORATORY_LIVE_POLICY)
            config["current_market_bindings"] = [
                dict(item)
                for item in current_bindings
                if isinstance(item, Mapping)
                and str(item.get("market_id", "")).strip() in current_market_ids
            ]
            config["scope_selection_provenance"] = {
                "candidate_id": candidate_id,
                "scope_hash": (
                    scope_resolution.get("scope_hash")
                    if isinstance(scope_resolution, Mapping)
                    else None
                ),
                "scope_version": (
                    scope_resolution.get("scope_version")
                    if isinstance(scope_resolution, Mapping)
                    else None
                ),
                "bounded_pool_cap": _EXPLORATORY_POOL_CAP,
            }
        if not capture_only:
            for safety_key in (
                "execution_scope",
                "research_only",
                "selection_excluded",
                "allocation_active",
                "canary_armed",
                "scope_resolution_freshness_sla_seconds",
                "capture_market_id",
            ):
                config.pop(safety_key, None)
        for name in ("experiment_plan", "plan", "forward_config"):
            value = strategy.get(name)
            if isinstance(value, Mapping):
                config[name] = dict(value)
        declared_setup = source_binding.get("operational_setup")
        declared_setup_hash = str(
            source_binding.get("operational_setup_hash")
            or source_binding.get("predecessor_operational_setup_hash")
            or ""
        ).strip()
        if capture_only:
            if declared_setup_hash:
                config["predecessor_operational_setup_hash"] = declared_setup_hash
            declared_setup = None
            declared_setup_hash = ""
        if declared_setup not in (None, ""):
            if not isinstance(declared_setup, Mapping):
                raise ValueError("OPERATIONAL_SETUP_INVALID")
            config["operational_setup"] = dict(declared_setup)
        if declared_setup_hash:
            config["operational_setup_hash"] = declared_setup_hash
        derived_setup = _operational_setup_for_strategy(strategy_document, config)
        if capture_only:
            config.pop("operational_setup", None)
            config.pop("operational_setup_hash", None)
            supplied_setup = None
        else:
            if derived_setup is not None:
                config["canonical_operational_setup_required"] = True
            supplied_setup = config.get("operational_setup")
            if derived_setup is None and supplied_setup is not None:
                raise ValueError("OPERATIONAL_SETUP_UNSUPPORTED")
            if supplied_setup is None and derived_setup is not None:
                supplied_setup = derived_setup
                config["operational_setup"] = dict(derived_setup)
            elif (
                derived_setup is not None
                and _canonical_binding(supplied_setup) != _canonical_binding(derived_setup)
            ):
                raise ValueError("OPERATIONAL_SETUP_MISMATCH")
            if isinstance(supplied_setup, Mapping):
                canonical_setup_hash = _operational_setup_hash(supplied_setup)
                if declared_setup_hash and declared_setup_hash != canonical_setup_hash:
                    raise ValueError("OPERATIONAL_SETUP_HASH_MISMATCH")
                config["operational_setup_hash"] = canonical_setup_hash
            elif declared_setup_hash:
                raise ValueError("OPERATIONAL_SETUP_MISSING")
        model_document, model_resolution = self._resolve_rolling_model(strategy)
        config["model_document"] = dict(model_document)
        config["model_resolution"] = dict(model_resolution)
        if isinstance(scope_resolution, Mapping):
            config["scope_resolution"] = _public_scope_resolution(scope_resolution)
        expected_config = _canonical_forward_config(config)
        expected_strategy_hash = _content_hash(
            _normalized_strategy_document(strategy_document)
        )
        expected_model_hash = str(model_resolution["model_hash"])
        intent = None
        stale_intent = None
        for existing in registry.list_observation_intents():
            existing_config = existing.config if isinstance(existing.config, Mapping) else {}
            if _binding_value(existing_config.get("candidate_id")) != candidate_id:
                continue
            # Reuse is valid only for the complete immutable identity.  A
            # changed document, paper assumption, selector, scope, or hash
            # intentionally gets a new deterministic observation intent.
            if (
                str(existing.strategy_hash).strip() == expected_strategy_hash
                and str(existing.model_hash).strip() == expected_model_hash
            ):
                identity_ignored = {
                    "observation_handoff",
                    "observation_intent_id",
                    "paper_observation_intent_id",
                    "strategy_document",
                    "scope_resolution",
                    "superseded_observation_intent_ids",
                }
                existing_base = {
                    key: value
                    for key, value in existing_config.items()
                    if key not in identity_ignored
                }
                expected_base = {
                    key: value
                    for key, value in expected_config.items()
                    if key not in identity_ignored
                }
                if _canonical_binding(existing_base) == _canonical_binding(expected_base):
                    intent = existing
                    break
            try:
                existing_canonical = _canonical_forward_config(existing_config)
            except (TypeError, ValueError):
                if stale_intent is None:
                    stale_intent = existing
                continue
            if (
                str(existing.strategy_hash).strip() != expected_strategy_hash
                or str(existing.model_hash).strip() != expected_model_hash
                or _canonical_binding(existing_canonical) != _canonical_binding(expected_config)
            ):
                if stale_intent is None:
                    stale_intent = existing
                continue
            intent = existing
            break
        if intent is None and stale_intent is not None:
            # A persisted hash-only/partial intent is immutable.  Link the
            # repaired intent to it so active discovery suppresses only the
            # stale intent (the candidate identity remains eligible).
            config["observation_handoff"] = {
                "version": (
                    "observation-capture-v1"
                    if capture_only
                    else "operational-setup-repair-v1"
                ),
                "predecessor_candidate_id": None,
                "predecessor_observation_intent_id": stale_intent.experiment_id,
                "predecessor_profitability_inherited": False,
                "predecessor_allocation_authority_inherited": False,
            }
            sibling_ids = sorted(
                {
                    str(existing.experiment_id).strip()
                    for existing in registry.list_observation_intents()
                    if str(existing.experiment_id).strip()
                    and _binding_value(
                        (
                            existing.config
                            if isinstance(existing.config, Mapping)
                            else {}
                        ).get("candidate_id")
                    )
                    == candidate_id
                    and _binding_value(
                        (
                            (
                                existing.config
                                if isinstance(existing.config, Mapping)
                                else {}
                            ).get("observation_handoff")
                            or {}
                        ).get("predecessor_observation_intent_id")
                    )
                    == str(stale_intent.experiment_id).strip()
                    and not (
                        (
                            existing.config
                            if isinstance(existing.config, Mapping)
                            else {}
                        ).get("observation_capture_only")
                        is True
                        and _binding_value(
                            (
                                existing.config
                                if isinstance(existing.config, Mapping)
                                else {}
                            ).get("capture_market_id")
                        )
                        == capture_market_id
                        and tuple(
                            sorted(
                                _binding_value(item)
                                for item in (
                                    (
                                        existing.config
                                        if isinstance(existing.config, Mapping)
                                        else {}
                                    ).get("current_market_ids", ())
                                )
                                if _binding_value(item)
                            )
                        )
                        == current_market_ids
                    )
                }
            )
            if sibling_ids:
                config["superseded_observation_intent_ids"] = sibling_ids
            expected_config = _canonical_forward_config(config)
            for existing in registry.list_observation_intents():
                existing_config = existing.config if isinstance(existing.config, Mapping) else {}
                if (
                    _binding_value(existing_config.get("candidate_id")) == candidate_id
                    and str(existing.strategy_hash).strip() == expected_strategy_hash
                    and str(existing.model_hash).strip() == expected_model_hash
                ):
                    try:
                        if _canonical_binding(_canonical_forward_config(existing_config)) == _canonical_binding(expected_config):
                            intent = existing
                            break
                    except (TypeError, ValueError):
                        continue
        if intent is None:
            intent = registry.register_observation_intent(
                strategy=dict(strategy_document),
                model=dict(model_document) if isinstance(model_document, Mapping) else {},
                config=config,
                registration_timestamp=now,
                candidate_id=candidate_id,
                strategy_version_id=strategy_version_id,
                research_trial_id=trial_id,
                source_strategy_hash=_binding_value(strategy.get("strategy_hash")),
                rolling_strategy_hash=_binding_value(strategy.get("strategy_hash")),
                dataset_selector=selector,
                scope=scope,
                scope_resolution=scope_resolution,
            )
        identifiers = list(
            dict.fromkeys(str(item).strip() for item in market_ids if str(item).strip())
        )
        if not identifiers:
            scoped = scope.get("market_ids", scope.get("markets", ()))
            if isinstance(scoped, str):
                scoped = (scoped,)
            identifiers = list(
                dict.fromkeys(str(item).strip() for item in (scoped or ()) if str(item).strip())
            )
        materialize = getattr(registry, "materialize_observation_intent", None)
        if identifiers and callable(materialize):
            materialize(
                intent,
                allowed_markets=identifiers,
                registration_timestamp=now,
                now=now,
                candidate_id=candidate_id,
                strategy_version_id=strategy_version_id,
                research_trial_id=trial_id,
                source_strategy_hash=_binding_value(strategy.get("strategy_hash")),
                rolling_strategy_hash=_binding_value(strategy.get("strategy_hash")),
                dataset_selector=selector,
                scope=scope,
                scope_resolution=scope_resolution,
            )
        return {
            "intent_id": intent.experiment_id,
            "candidate_id": candidate_id,
            "strategy_version_id": strategy_version_id,
            "research_trial_id": trial_id,
            "market_ids": identifiers,
            "model_resolution": dict(model_resolution),
        }

    def _rolling_source_rows(
        self,
        record: Mapping[str, Any],
        source_class: str,
        now: datetime,
    ) -> list[dict[str, Any]]:
        source = _rolling_source_name(source_class)
        if source not in _ROLLING_SOURCE_TYPES:
            raise ValueError(f"unsupported rolling source class: {source_class}")
        persisted_source = _rolling_persisted_source_class(source)
        try:
            source_binding = _rolling_source_job_binding(record, source)
        except ValueError as exc:
            if str(exc) == "HISTORICAL_DATASET_BINDING_REQUIRED":
                raise ValueError("HISTORICAL_SELECTOR_REQUIRED") from exc
            raise
        binding = _rolling_source_binding(record)
        dataset_id = str(source_binding.get("dataset_id", "")).strip()
        dataset_version = str(source_binding.get("dataset_version", "")).strip()
        strategy_hash = _binding_value(source_binding.get("strategy_hash"))
        expected_candidate = _binding_value(source_binding.get("candidate_id"))
        expected_trial = _binding_value(source_binding.get("research_trial_id"))
        expected_strategy_version = _binding_value(
            source_binding.get("strategy_version_id")
        )
        rows: list[dict[str, Any]] = []
        replay_rule_scope_resolved = False
        replay_scope_market_ids: set[str] | None = None
        if source == "REPLAY":
            replay_scope = binding.get("market_scope", binding.get("scope"))
            if (
                isinstance(replay_scope, Mapping)
                and str(replay_scope.get("mode", "")).strip().upper()
                == "RULE_BASED_MARKETS"
            ):
                replay_rule_scope_resolved = True
                # Resolve persisted scope membership before selecting a broad
                # replay catalog. Missing/partial resolution fails closed.
                replay_scope_market_ids = _rolling_rule_scope_market_ids(
                    self.store,
                    record,
                    binding,
                    (),
                    now,
                )
        if source == "HISTORICAL":
            # Dataset identity alone is not strategy/accounting lineage.
            # Unbound rows remain usable input for canonical evaluation but
            # must not be silently converted into pre-bound accounting.
            loaded = self._load_rolling_historical_dataset(dataset_id, dataset_version)
            if isinstance(loaded, Mapping):
                loaded = loaded.get("records", loaded.get("rows", ()))
            if isinstance(loaded, Sequence) and not isinstance(loaded, (str, bytes)):
                for item in loaded:
                    if not isinstance(item, Mapping):
                        continue
                    try:
                        row_binding = _rolling_source_binding(item)
                    except (TypeError, ValueError):
                        row = dict(item)
                        row["_rolling_lineage_proven"] = False
                        row["_rolling_source_rejection"] = "SOURCE_BINDING_CONFLICT"
                        row["_rolling_accounting_rejection"] = "SOURCE_BINDING_CONFLICT"
                        rows.append(row)
                        continue
                    malformed = any(
                        not _rolling_binding_shape_is_valid(row_binding.get(field))
                        for field in (
                            "dataset_id",
                            "dataset_version",
                            "version",
                            "strategy_hash",
                            "source_strategy_hash",
                            "rolling_strategy_hash",
                            "strategy_version_id",
                            "research_trial_id",
                            "candidate_id",
                        )
                    )
                    if malformed:
                        row = dict(item)
                        row["_rolling_lineage_proven"] = False
                        row["_rolling_source_rejection"] = "SOURCE_BINDING_MALFORMED"
                        row["_rolling_accounting_rejection"] = "SOURCE_BINDING_MALFORMED"
                        rows.append(row)
                        continue
                    required_fields = (
                        "strategy_hash",
                        "strategy_version_id",
                        "research_trial_id",
                        "candidate_id",
                    )
                    missing = any(
                        _binding_value(row_binding.get(field)) is None
                        for field in required_fields
                    )
                    checked = _rolling_inject_source_binding(item, source_binding)
                    if checked.get("_rolling_accounting_rejection"):
                        checked["_rolling_lineage_proven"] = False
                        checked["_rolling_source_rejection"] = checked.get(
                            "_rolling_accounting_rejection"
                        )
                        rows.append(checked)
                    elif missing:
                        # Missing strategy lineage is valid raw market input.
                        # Keep the source row unmodified so attribution is
                        # generated only by this new evaluation result.
                        row = dict(item)
                        row["_rolling_lineage_proven"] = False
                        rows.append(row)
                    else:
                        checked["_rolling_lineage_proven"] = True
                        rows.append(checked)
        elif source == "REPLAY":
            replay_rows, _replay_catalog = self._rolling_replay_catalog_rows(
                record,
                now,
                scope_market_ids=replay_scope_market_ids,
            )
            # The strategy's historical dataset selector is not replay
            # identity.  Catalog identity is carried by each exact row and
            # checked against the immutable manifest above.
            replay_binding = {
                key: value
                for key, value in source_binding.items()
                if key not in {"dataset_id", "dataset_version"}
            }
            for item in replay_rows[:_MAX_FORWARD_ROWS]:
                row = dict(item)
                row["_rolling_lineage_proven"] = False
                if (
                    not _rolling_replay_row_terminal(row)
                    and not _rolling_has_paired_timestamped_books(row)
                ):
                    row["_rolling_source_rejection"] = "REPLAY_BOOK_REQUIRED"
                    row["_rolling_accounting_rejection"] = "REPLAY_BOOK_REQUIRED"
                checked = _rolling_inject_source_binding(row, replay_binding)
                if checked.get("_rolling_accounting_rejection"):
                    checked["_rolling_lineage_proven"] = False
                rows.append(checked)
        elif source == "LIVE":
            loader = getattr(self.store, "load_polymarket_snapshots", None)
            if not callable(loader):
                raise ValueError("SOURCE_LOADER_UNAVAILABLE")
            persisted_types = _ROLLING_SOURCE_QUERY_TYPES[source]
            for source_value in persisted_types:
                # ``load_polymarket_snapshots`` has a deliberately narrow,
                # public signature.  Never retry a TypeError with weaker
                # arguments: an unbound source row is not pre-bound accounting.
                try:
                    values = loader(source_type=source_value, limit=_MAX_FORWARD_ROWS)
                except TypeError as exc:
                    raise ValueError("SOURCE_LOADER_UNSUPPORTED") from exc
                except Exception as exc:
                    raise ValueError("SOURCE_LOAD_FAILED") from exc
                if isinstance(values, Mapping):
                    values = values.get("records", values.get("rows", ()))
                for item_index, item in enumerate(values or ()):
                    if item_index >= _MAX_FORWARD_ROWS:
                        break
                    if not isinstance(item, Mapping):
                        continue
                    if (
                        str(_rolling_snapshot_view(item).get("research_mode", ""))
                        .strip()
                        .upper()
                        .replace("-", "_")
                        == "RECORDED_BOOK_REPLAY"
                    ):
                        continue
                    try:
                        row_binding = _rolling_source_binding(item)
                    except (TypeError, ValueError):
                        row = dict(item)
                        row["_rolling_lineage_proven"] = False
                        row["_rolling_source_rejection"] = "SOURCE_BINDING_CONFLICT"
                        row["_rolling_accounting_rejection"] = "SOURCE_BINDING_CONFLICT"
                        rows.append(row)
                        continue
                    malformed = any(
                        not _rolling_binding_shape_is_valid(row_binding.get(field))
                        for field in (
                            "dataset_id",
                            "dataset_version",
                            "version",
                            "strategy_hash",
                            "source_strategy_hash",
                            "rolling_strategy_hash",
                            "strategy_version_id",
                            "research_trial_id",
                            "candidate_id",
                        )
                    )
                    if malformed:
                        row = dict(item)
                        row["_rolling_lineage_proven"] = False
                        row["_rolling_source_rejection"] = "SOURCE_BINDING_MALFORMED"
                        row["_rolling_accounting_rejection"] = "SOURCE_BINDING_MALFORMED"
                        rows.append(row)
                        continue
                    required_fields = (
                        "strategy_hash",
                        "strategy_version_id",
                        "research_trial_id",
                        "candidate_id",
                    )
                    missing = any(
                        _binding_value(row_binding.get(field)) is None
                        for field in required_fields
                    )
                    conflict = any(
                        (
                            _binding_value(row_binding.get(field)) is not None
                            and _binding_value(row_binding.get(field))
                            != _binding_value(source_binding.get(field))
                        )
                        for field in required_fields
                    )
                    checked = _rolling_inject_source_binding(item, source_binding)
                    if conflict or checked.get("_rolling_accounting_rejection"):
                        checked["_rolling_lineage_proven"] = False
                        checked["_rolling_source_rejection"] = checked.get(
                            "_rolling_accounting_rejection"
                        ) or "SOURCE_BINDING_CONFLICT"
                        checked["_rolling_accounting_rejection"] = (
                            checked.get("_rolling_accounting_rejection")
                            or "SOURCE_BINDING_CONFLICT"
                        )
                        rows.append(checked)
                    elif missing:
                        # Raw live observations are evaluator inputs even
                        # when their strategy lineage has not been attributed.
                        row = dict(item)
                        row["_rolling_lineage_proven"] = False
                        rows.append(row)
                    else:
                        checked["_rolling_lineage_proven"] = True
                        rows.append(checked)
        elif source == "PAPER":
            registry_loader = getattr(self.store, "load_forward_tests", None)
            if not callable(registry_loader):
                raise ValueError("PAPER_REGISTRY_UNAVAILABLE")
            try:
                try:
                    spec_values = registry_loader(limit=_MAX_ROLLING_SOURCE_ROWS)
                    if isinstance(spec_values, Mapping):
                        spec_values = spec_values.get("records", spec_values.get("rows", ()))
                    specs: list[Any] = []
                    for spec in spec_values or ():
                        if len(specs) >= _MAX_ROLLING_SOURCE_ROWS:
                            break
                        specs.append(spec)
                except TypeError:
                    # An adapter without an explicit bounded parameter cannot
                    # safely be used for rolling discovery.
                    specs = []
            except Exception as exc:
                raise ValueError("PAPER_REGISTRY_UNAVAILABLE") from exc
            superseded_spec_ids: set[str] = set()
            linked_forward_ids: set[str] = set()
            linked_intent_ids: set[str] = set()
            lifecycle_loader = getattr(self.store, "load_candidate_lifecycle", None)
            for candidate_spec in specs:
                candidate_config = (
                    candidate_spec.get("config")
                    if isinstance(candidate_spec.get("config"), Mapping)
                    else {}
                )
                superseded_spec_ids.update(
                    str(item).strip()
                    for item in candidate_config.get(
                        "superseded_observation_intent_ids", ()
                    )
                    if str(item).strip()
                )
                handoff = candidate_config.get("observation_handoff")
                if isinstance(handoff, Mapping):
                    predecessor = _binding_value(
                        handoff.get("predecessor_observation_intent_id")
                        or handoff.get("predecessor_forward_test_id")
                    )
                    if predecessor:
                        superseded_spec_ids.add(predecessor)
                if candidate_config.get("observation_intent") is not True:
                    continue
                candidate_id = _binding_value(candidate_config.get("candidate_id"))
                if not candidate_id or not callable(lifecycle_loader):
                    continue
                try:
                    lifecycle = lifecycle_loader(candidate_id)
                except (AttributeError, KeyError, RuntimeError, TypeError, ValueError):
                    continue
                payload = (
                    lifecycle.get("payload")
                    if isinstance(lifecycle, Mapping)
                    else None
                )
                stage = str(
                    getattr(lifecycle.get("stage"), "value", lifecycle.get("stage"))
                    if isinstance(lifecycle, Mapping)
                    else ""
                ).strip().upper()
                if stage not in {"SCHEMA_VALIDATED", "PAPER_FORWARD", "PAPER_PROMOTABLE"}:
                    continue
                if not isinstance(payload, Mapping):
                    continue
                forward_id = _binding_value(payload.get("forward_test_id"))
                intent_id = _binding_value(
                    payload.get("paper_observation_intent_id")
                )
                if forward_id:
                    linked_forward_ids.add(forward_id)
                if intent_id:
                    linked_intent_ids.add(intent_id)
            matched_spec = False
            pending_intent = False
            for spec in specs:
                if not isinstance(spec, Mapping):
                    continue
                spec_strategy_hash = _binding_value(spec.get("strategy_hash"))
                experiment_id = _binding_value(spec.get("experiment_id"))
                config = spec.get("config")
                config = config if isinstance(config, Mapping) else {}
                allowed_markets = (
                    tuple(
                        str(item).strip()
                        for item in spec.get("allowed_markets", ())
                        if str(item).strip()
                    )
                    if isinstance(spec.get("allowed_markets"), (list, tuple))
                    else ()
                )
                is_observation_intent = bool(config.get("observation_intent"))
                is_materialized_intent = (
                    config.get("market_authority_required") is True
                    and bool(allowed_markets)
                )
                # An observation intent is not a PAPER source.  Record an
                # exact unmaterialized intent separately so callers can retry
                # once current market authority is available; never load its
                # ledger as if it were executable paper work.
                is_unmaterialized_intent = (
                    is_observation_intent and not is_materialized_intent
                )
                if is_observation_intent and experiment_id in superseded_spec_ids:
                    continue
                if is_materialized_intent and (
                    experiment_id not in linked_forward_ids
                    and experiment_id not in linked_intent_ids
                ):
                    continue
                source_strategy_hash = _binding_value(
                    config.get("source_strategy_hash")
                ) or spec_strategy_hash
                rolling_strategy_hash = _binding_value(
                    config.get("rolling_strategy_hash")
                ) or spec_strategy_hash
                if (
                    source_strategy_hash != spec_strategy_hash
                    or rolling_strategy_hash != strategy_hash
                ):
                    continue
                try:
                    spec_binding = _rolling_source_binding(
                        {"payload": config, "strategy_hash": spec_strategy_hash}
                    )
                except (TypeError, ValueError):
                    continue
                spec_candidate = _binding_value(spec_binding.get("candidate_id"))
                spec_trial = _binding_value(
                    spec_binding.get("research_trial_id", spec_binding.get("trial_id"))
                )
                spec_strategy_version = _binding_value(
                    spec_binding.get("strategy_version_id")
                )
                if (
                    not experiment_id
                    or spec_candidate != expected_candidate
                    or spec_trial != expected_trial
                    or spec_strategy_version != expected_strategy_version
                ):
                    continue
                if is_unmaterialized_intent:
                    pending_intent = True
                    continue
                matched_spec = True
                row_binding = {
                    **source_binding,
                    "experiment_id": experiment_id,
                }
                if config.get("observation_capture_only") is True:
                    observation_loader = getattr(self.store, "list_paper_observations", None)
                    capture_market_id = _binding_value(config.get("capture_market_id"))
                    configured_markets = {
                        _binding_value(item)
                        for item in allowed_markets
                        if _binding_value(item)
                    }
                    if (
                        not callable(observation_loader)
                        or not capture_market_id
                        or capture_market_id not in configured_markets
                    ):
                        continue
                    try:
                        observation_values = observation_loader(
                            experiment_id,
                            limit=_MAX_ROLLING_SOURCE_ROWS,
                        )
                    except Exception as exc:
                        raise ValueError("PAPER_OBSERVATION_SOURCE_UNAVAILABLE") from exc
                    for item_index, item in enumerate(observation_values or ()):
                        if item_index >= _MAX_ROLLING_SOURCE_ROWS or not isinstance(item, Mapping):
                            break
                        if _binding_value(item.get("market_id")) != capture_market_id:
                            continue
                        payload = item.get("payload")
                        if not isinstance(payload, Mapping):
                            continue
                        source_id = _binding_value(payload.get("source_snapshot_id"))
                        source_timestamp = _rolling_row_time(
                            {"timestamp": payload.get("source_timestamp", item.get("timestamp"))}
                        )
                        observed_timestamp = _rolling_row_time(
                            {"timestamp": item.get("timestamp")}
                        )
                        if (
                            not source_id
                            or source_timestamp is None
                            or observed_timestamp is None
                            or source_timestamp > observed_timestamp
                        ):
                            continue
                        row = dict(payload)
                        row.update(
                            {
                                "observation_id": item.get("observation_id"),
                                "experiment_id": experiment_id,
                                "market_id": capture_market_id,
                                "timestamp": item.get("timestamp"),
                                "source_snapshot_id": source_id,
                                "source_timestamp": source_timestamp,
                                "strategy_hash": strategy_hash,
                                "source_strategy_hash": spec_strategy_hash,
                                "rolling_strategy_hash": strategy_hash,
                                "paper_observation_capture": True,
                                "evaluation_kind": "OBSERVATION_ONLY_DECLINE",
                                "accepted": False,
                                "promotable": False,
                                "selection_excluded": True,
                                "allocation_active": False,
                            }
                        )
                        rows.append(_rolling_inject_source_binding(row, row_binding))
                    continue
                loader = getattr(self.store, "list_paper_bet_ledger", None)
                if not callable(loader):
                    continue
                try:
                    values = loader(experiment_id, limit=_MAX_ROLLING_SOURCE_ROWS)
                except Exception as exc:
                    raise ValueError("PAPER_SOURCE_UNAVAILABLE") from exc
                row_binding = {
                    **source_binding,
                    "experiment_id": experiment_id,
                }
                for item_index, item in enumerate(values or ()):
                    if item_index >= _MAX_ROLLING_SOURCE_ROWS:
                        break
                    if not isinstance(item, Mapping):
                        continue
                    nested_conflict = _rolling_nested_paper_identity_conflict(
                        item,
                        strategy_hashes={strategy_hash, spec_strategy_hash},
                        expected={
                            **source_binding,
                            "source_strategy_hash": spec_strategy_hash,
                            "strategy_hash": strategy_hash,
                            "strategy_version_id": expected_strategy_version,
                            "research_trial_id": expected_trial,
                            "candidate_id": expected_candidate,
                            "experiment_id": experiment_id,
                        },
                    )
                    if nested_conflict is not None:
                        rejected = dict(item)
                        rejected["_rolling_accounting_rejection"] = (
                            "PAPER_IDENTITY_UNPROVEN"
                            if nested_conflict == "identity_unproven"
                            else "PAPER_STRATEGY_BINDING_CONFLICT"
                            if nested_conflict == "strategy_hash"
                            else f"PAPER_{nested_conflict.upper()}_BINDING_CONFLICT"
                        )
                        rows.append(rejected)
                        continue
                    raw_view = _rolling_snapshot_view(item)
                    raw_strategy_values = (
                        item.get("strategy_hash"),
                        item.get("strategy_id"),
                        raw_view.get("strategy_hash"),
                        raw_view.get("strategy_id"),
                    )
                    allowed_hashes = {strategy_hash, spec_strategy_hash}
                    if any(
                        _binding_value(value) is not None
                        and _binding_value(value) not in allowed_hashes
                        for value in raw_strategy_values
                    ):
                        rejected = dict(item)
                        rejected["_rolling_accounting_rejection"] = "PAPER_STRATEGY_BINDING_CONFLICT"
                        rows.append(rejected)
                        continue
                    raw_source_values = (
                        item.get("source_strategy_hash"),
                        raw_view.get("source_strategy_hash"),
                    )
                    if any(
                        _binding_value(value) is not None
                        and _binding_value(value) != spec_strategy_hash
                        for value in raw_source_values
                    ):
                        rejected = dict(item)
                        rejected["_rolling_accounting_rejection"] = "PAPER_SOURCE_STRATEGY_BINDING_CONFLICT"
                        rows.append(rejected)
                        continue
                    translated_item = dict(item)
                    translated_item["strategy_hash"] = strategy_hash
                    translated_item["source_strategy_hash"] = spec_strategy_hash
                    translated_item["rolling_strategy_hash"] = strategy_hash
                    raw_payload = translated_item.get("payload")
                    if isinstance(raw_payload, Mapping):
                        translated_payload = dict(raw_payload)
                        translated_payload["strategy_hash"] = strategy_hash
                        translated_payload["source_strategy_hash"] = spec_strategy_hash
                        translated_payload["rolling_strategy_hash"] = strategy_hash
                        translated_item["payload"] = translated_payload
                    row = _rolling_inject_source_binding(translated_item, row_binding)
                    if row.get("_rolling_accounting_rejection"):
                        rows.append(row)
                        continue
                    row_view = _rolling_snapshot_view(row)
                    if (
                        _binding_value(item.get("experiment_id")) is not None
                        and _binding_value(item.get("experiment_id")) != experiment_id
                    ):
                        row["_rolling_accounting_rejection"] = "PAPER_EXPERIMENT_BINDING_CONFLICT"
                        rows.append(row)
                        continue
                    row_strategy = _binding_value(
                        row_view.get("strategy_hash", row_view.get("strategy_id"))
                    )
                    if row_strategy and row_strategy != strategy_hash:
                        row["_rolling_accounting_rejection"] = "PAPER_STRATEGY_BINDING_CONFLICT"
                        rows.append(row)
                        continue
                    row["_paper_experiment_id"] = experiment_id
                    rows.append(row)
            if not matched_spec:
                if pending_intent:
                    raise ValueError("PAPER_MARKET_AUTHORITY_PENDING")
                raise ValueError("PAPER_SPEC_BINDING_MISMATCH")
        if replay_rule_scope_resolved:
            resolved_scope_market_ids = replay_scope_market_ids
        else:
            resolved_scope_market_ids = _rolling_rule_scope_market_ids(
                self.store,
                record,
                binding,
                rows,
                now,
            )
        normalized: list[dict[str, Any]] = []
        allowed_source_types = _ROLLING_SOURCE_TYPES[source]
        for raw in rows:
            if not isinstance(raw, Mapping):
                continue
            row = _rolling_snapshot_view(raw)
            if row.get("_rolling_accounting_rejection"):
                if source == "REPLAY":
                    replay_scope = (
                        set(resolved_scope_market_ids)
                        if resolved_scope_market_ids is not None
                        else _rolling_market_scope_ids(binding)
                    )
                    if replay_scope and str(row.get("market_id", "")).strip() not in replay_scope:
                        continue
                # Rejected source rows remain observable even when their
                # nested payload declares an incompatible source class.
                row["source_class"] = persisted_source
                row.setdefault("source_type", persisted_source)
                row["requested_source_class"] = source
                row["requested_source_type"] = source
                normalized.append(row)
                continue
            declared_source = str(
                row.get("source_type", row.get("source_class", ""))
            ).strip().upper().replace("-", "_")
            if source == "PAPER" and declared_source == "FORWARD_COLLECTED":
                # ForwardPaperEngine persists its observation rows with the
                # collection source type; this loader's canonical class is
                # still PAPER and remains experiment-bound above.
                declared_source = "PAPER"
            if declared_source and declared_source not in allowed_source_types:
                row["_rolling_source_rejection"] = "SOURCE_TYPE_CONFLICT"
                row["_rolling_accounting_rejection"] = "SOURCE_TYPE_CONFLICT"
            if _rolling_campaign_bound(row):
                row["_rolling_source_rejection"] = "UNTRUSTED_ROLLING_PROVENANCE"
                row["_rolling_accounting_rejection"] = "UNTRUSTED_ROLLING_PROVENANCE"
            if _rolling_row_time(row) is None:
                row["_rolling_timestamp_rejection"] = "SOURCE_TIMESTAMP_UNPARSEABLE"
                row["_rolling_source_rejection"] = "SOURCE_TIMESTAMP_UNPARSEABLE"
                row["_rolling_accounting_rejection"] = "SOURCE_TIMESTAMP_UNPARSEABLE"
            if not str(row.get("market_id", "")).strip():
                row["_rolling_source_rejection"] = "SOURCE_MARKET_ID_MISSING"
                row["_rolling_accounting_rejection"] = "SOURCE_MARKET_ID_MISSING"
            if row.get("_rolling_source_rejection"):
                row["source_class"] = persisted_source
                row.setdefault("source_type", persisted_source)
                row["requested_source_class"] = source
                row["requested_source_type"] = source
                normalized.append(row)
                continue
            view = _rolling_snapshot_view(row)
            has_explicit_accounting = any(
                isinstance(view.get(name), Mapping)
                for name in (
                    "canonical_accounting",
                    "strategy_accounting",
                    "accounting",
                    "resolved_bet",
                )
            )
            should_project_accounting = source == "PAPER" or (
                source == "LIVE"
                and row.get("_rolling_lineage_proven") is True
                and has_explicit_accounting
            )
            if should_project_accounting:
                accounting = self._rolling_accounting_projection(row, record)
                if accounting is None:
                    if row.get("_rolling_accounting_rejection"):
                        row["source_class"] = persisted_source
                        row.setdefault("source_type", persisted_source)
                        row["requested_source_class"] = source
                        row["requested_source_type"] = source
                        normalized.append(row)
                    continue
                row["_rolling_accounting"] = dict(accounting)
            binding_conflict = False
            for field_name in ("dataset_id", "dataset_version", "version"):
                expected = source_binding.get(field_name)
                if expected is None or expected == "":
                    continue
                actual = row.get(field_name)
                if actual is not None and actual != "" and _canonical_binding(actual) != _canonical_binding(expected):
                    binding_conflict = True
                    break
            if binding_conflict:
                row["_rolling_accounting_rejection"] = "SOURCE_BINDING_CONFLICT"
                row["source_class"] = persisted_source
                row.setdefault("source_type", persisted_source)
                row["requested_source_class"] = source
                row["requested_source_type"] = source
                normalized.append(row)
                continue
            scope = binding.get("market_scope", binding.get("scope"))
            scope = scope if isinstance(scope, Mapping) else {}
            if resolved_scope_market_ids is not None:
                expected_markets = resolved_scope_market_ids
            else:
                expected_markets = scope.get(
                    "market_ids",
                    scope.get(
                        "markets",
                        binding.get("market_ids", binding.get("market_id", ())),
                    ),
                )
                if isinstance(expected_markets, str):
                    expected_markets = (expected_markets,)
                expected_markets = {
                    str(item).strip()
                    for item in (expected_markets or ())
                    if str(item).strip()
                }
            if resolved_scope_market_ids is not None and not expected_markets:
                continue
            if expected_markets:
                actual_market = str(row.get("market_id", "")).strip()
                if actual_market not in expected_markets:
                    continue
            row["source_class"] = persisted_source
            row.setdefault("source_type", persisted_source)
            row["requested_source_class"] = source
            row["requested_source_type"] = source
            if _rolling_row_time(row) is not None:
                normalized.append(row)
            else:
                # Keep malformed rows visible to the work-item window filter
                # so the scheduler emits an explicit pending reason instead of
                # silently dropping source material.
                row["_rolling_timestamp_rejection"] = "SOURCE_TIMESTAMP_UNPARSEABLE"
                normalized.append(row)
        normalized.sort(
            key=lambda row: (
                _rolling_row_time(row) or datetime.min.replace(tzinfo=timezone.utc),
                str(row.get("market_id", "")),
                str(row.get("snapshot_id", row.get("observation_id", ""))),
            )
        )
        return normalized[-_MAX_ROLLING_SOURCE_ROWS:]

    def _rolling_capture_decline_evaluation(
        self,
        strategy: Mapping[str, Any],
        rows: Sequence[Mapping[str, Any]],
    ) -> Mapping[str, Any]:
        """Build observation-only progress without invoking strategy research."""
        strategy_document = strategy.get("strategy_document", {})
        family = (
            str(strategy_document.get("family", "")).strip().lower()
            if isinstance(strategy_document, Mapping)
            else ""
        )
        observations = [
            row for row in rows
            if isinstance(row, Mapping)
            and row.get("paper_observation_capture") is True
        ]
        complete = len(observations) >= 3
        reason = (
            (
                "ZERO_EDGE_CONTROL"
                if family == "probability_mispricing"
                else "OPERATIONAL_SETUP_UNDERDETERMINED"
            )
            if complete
            else "INSUFFICIENT_OBSERVATIONS"
        )
        return {
            "evaluation_kind": (
                "OBSERVATION_ONLY_DECLINE"
                if complete
                else "OBSERVATION_ONLY_PROGRESS"
            ),
            "evaluation_version": "legacy-observation-capture:v1",
            "evaluation_run_id": "capture-refresh-" + _rolling_hash(
                {
                    "strategy_version_id": strategy.get("strategy_version_id"),
                    "observation_ids": [row.get("observation_id") for row in observations],
                }
            ).removeprefix("sha256:")[:40],
            "selection_excluded": True,
            "accepted": False,
            "promotable": False,
            "reason": reason,
            "observations": len(observations),
            "evaluator_invoked": False,
            "evaluator_completed": False,
            "portfolio_accounting": {
                "accounting_available": False,
                "accounting_complete": False,
                "accounting_not_applicable": True,
                "allocation_active": False,
                "fills": 0,
                "execution_events": 0,
            },
        }

    def _rolling_canonical_evaluation(
        self,
        strategy: Mapping[str, Any],
        rows: Sequence[Mapping[str, Any]],
        source_class: str,
    ) -> Mapping[str, Any] | None:
        """Evaluate validated market input without requiring prior lineage."""
        requested_source = _rolling_source_name(source_class)
        if requested_source not in {"HISTORICAL", "REPLAY", "LIVE"}:
            return None
        strategy_document = strategy.get("strategy_document", strategy.get("canonical_strategy"))
        operational_setup = strategy.get("operational_setup")
        operational_setup = (
            operational_setup if isinstance(operational_setup, Mapping) else {}
        )
        capture_spec = operational_setup.get("capture_spec")
        capture_spec = capture_spec if isinstance(capture_spec, Mapping) else None
        declared_holding = strategy.get("holding_period")
        if declared_holding is None and isinstance(strategy_document, Mapping):
            declared_holding = strategy_document.get("holding_period")
        if declared_holding is None:
            required_observations = operational_setup.get("required_observations")
            if isinstance(required_observations, Mapping):
                declared_holding = required_observations.get("holding")
        try:
            holding_period = int(declared_holding or 1)
        except (TypeError, ValueError, OverflowError):
            holding_period = 1
        if isinstance(declared_holding, bool) or holding_period < 1:
            holding_period = 1
        declared_exit = strategy.get("exit_policy")
        if declared_exit is None and isinstance(strategy_document, Mapping):
            declared_exit = strategy_document.get("exit_policy")
        if isinstance(declared_exit, Mapping):
            exit_policy: Mapping[str, Any] | str = {
                **dict(declared_exit),
                "type": str(
                    declared_exit.get(
                        "type",
                        declared_exit.get("kind", "fixed_holding_period"),
                    )
                ),
                "holding_period": holding_period,
            }
        elif declared_exit is None:
            holding_semantics = operational_setup.get("holding_semantics")
            if isinstance(holding_semantics, Mapping):
                exit_policy = {
                    "type": "fixed_holding_period",
                    "holding_period": holding_semantics.get("count", holding_period),
                }
            else:
                exit_policy = {
                    "type": "fixed_holding_period",
                    "holding_period": holding_period,
                }
        else:
            exit_policy = str(declared_exit or "fixed_holding_period")
        observation_horizon = strategy.get("observation_horizon")
        if observation_horizon is None and isinstance(strategy_document, Mapping):
            observation_horizon = strategy_document.get("observation_horizon")
        if not isinstance(observation_horizon, Mapping):
            observation_horizon = {
                "unit": "observations",
                "count": holding_period,
                "semantics": "per_market_observation_count",
            }
        else:
            observation_horizon = {
                **dict(observation_horizon),
                "unit": str(observation_horizon.get("unit", "observations")),
                "count": int(observation_horizon.get("count", holding_period)),
                "semantics": str(
                    observation_horizon.get(
                        "semantics",
                        "per_market_observation_count",
                    )
                ),
            }
        selection_excluded = bool(
            strategy.get(
                "selection_excluded",
                isinstance(strategy_document, Mapping)
                and strategy_document.get("selection_excluded", False),
            )
        ) or str(
            strategy.get("strategy_id", strategy_document.get("family", "") if isinstance(strategy_document, Mapping) else "")
        ).strip().lower() == "probability_mispricing"

        def view_of(row: Mapping[str, Any]) -> dict[str, Any]:
            return _rolling_snapshot_view(row)

        def has_book(row: Mapping[str, Any]) -> bool:
            view = view_of(row)
            return any(
                isinstance(view.get(name), Mapping)
                for name in ("order_book", "yes_order_book", "no_order_book")
            )

        price_fields = (
            "yes_mid",
            "no_mid",
            "yes_bid",
            "yes_ask",
            "no_bid",
            "no_ask",
            "price",
            "probability",
            "implied_probability",
        )
        valid_rows: list[dict[str, Any]] = []
        if requested_source == "REPLAY" and any(
            isinstance(raw, Mapping)
            and not _rolling_replay_row_terminal(raw)
            and not _rolling_has_paired_timestamped_books(raw)
            for raw in rows
        ):
            # A non-terminal gap invalidates the requested replay window; do
            # not salvage a smaller price-only subset.
            return None
        if requested_source == "LIVE":
            live_book_rows = [
                raw
                for raw in rows
                if isinstance(raw, Mapping)
                and not raw.get("_rolling_source_rejection")
                and not raw.get("_rolling_accounting_rejection")
                and has_book(raw)
            ]
            if live_book_rows and any(
                not _rolling_has_paired_timestamped_books(raw)
                for raw in live_book_rows
            ):
                return None
        expected_binding = _rolling_source_binding(strategy)
        if requested_source == "REPLAY":
            expected_binding = {
                key: value
                for key, value in expected_binding.items()
                if key not in {"dataset_id", "dataset_version", "version"}
            }
        for raw in rows:
            if not isinstance(raw, Mapping):
                continue
            if raw.get("_rolling_source_rejection") or raw.get(
                "_rolling_accounting_rejection"
            ):
                continue
            try:
                row_binding = _rolling_source_binding(raw)
            except (TypeError, ValueError):
                continue
            if any(
                not _rolling_binding_shape_is_valid(row_binding.get(field))
                for field in (
                    "dataset_id",
                    "dataset_version",
                    "version",
                    "strategy_hash",
                    "source_strategy_hash",
                    "rolling_strategy_hash",
                    "strategy_version_id",
                    "research_trial_id",
                    "candidate_id",
                )
            ):
                continue
            conflict = False
            for field_name in (
                "dataset_id",
                "dataset_version",
                "version",
                "strategy_hash",
                "source_strategy_hash",
                "rolling_strategy_hash",
                "strategy_version_id",
                "research_trial_id",
                "candidate_id",
            ):
                actual = _binding_value(row_binding.get(field_name))
                expected = _binding_value(expected_binding.get(field_name))
                if actual is not None and expected is not None and actual != expected:
                    conflict = True
                    break
            if conflict:
                continue
            view = view_of(raw)
            if _rolling_row_time(view) is None:
                continue
            if not str(view.get("market_id", "")).strip():
                continue
            if (
                requested_source == "REPLAY"
                and not _rolling_replay_row_terminal(raw)
                and not _rolling_has_paired_timestamped_books(raw)
            ):
                # Terminal settlement rows may omit books and still reach the
                # evaluator; only non-terminal replay requires paired books.
                continue
            if not (
                has_book(raw)
                or any(name in view for name in price_fields)
                or "settlement" in view
            ):
                continue
            valid_rows.append(dict(raw))
        if not valid_rows:
            return None
        # A LIVE row carrying a private ledger is accounting input, not a
        # second price-proxy path.  Exact identity was already checked by the
        # source loader; the evidence path will project that ledger directly.
        if requested_source == "LIVE" and not any(has_book(row) for row in valid_rows):
            if any(
                isinstance(view_of(row).get(name), Mapping)
                for row in valid_rows
                for name in (
                    "canonical_accounting",
                    "strategy_accounting",
                    "accounting",
                    "resolved_bet",
                )
            ):
                return None
        mode = (
            "RECORDED_BOOK_REPLAY"
            if requested_source == "REPLAY"
            else (
                "RECORDED_BOOK_REPLAY"
                if requested_source == "LIVE"
                and any(has_book(row) for row in valid_rows)
                else "PRICE_PROXY_RESEARCH"
            )
        )
        source_digest = _rolling_hash(valid_rows)
        document = strategy.get("strategy_document", strategy.get("canonical_strategy"))
        model_document: Mapping[str, Any] | None = None
        model_resolution: Mapping[str, Any] | None = None

        def run_identity(material: Mapping[str, Any]) -> str:
            return (
                "rolling-evaluation:v2:"
                + _rolling_hash(material).removeprefix("sha256:")[:40]
            )

        if not isinstance(document, Mapping):
            evaluation = {
                "evaluation_kind": "CANONICAL_SIMULATION",
                "evaluator_invoked": False,
                "evaluator_completed": False,
                "evaluated_observations": 0,
                "signal_count": 0,
                "diagnostic_summary_count": 0,
                "evaluator_name": None,
                "evaluator_error": "strategy_document is required",
                "evaluator_prerequisite": "STRATEGY_DOCUMENT_REQUIRED",
            }
            portfolio_accounting = {
                "accounting_available": False,
                "initial_cash": None,
                "cash": None,
                "equity": None,
                "realized_pnl": None,
                "unrealized_pnl": None,
                "net_pnl": None,
                "fees": None,
                "costs": None,
                "open_positions": [],
                "opening_fills": 0,
                "closing_fills": 0,
                "partial_closing_fills": 0,
                "completed_round_trips": 0,
            }
            material = {
                "version": "rolling-evaluation:v2:diagnostic",
                "source": requested_source,
                "mode": mode,
                "source_digest": source_digest,
                "evaluation": evaluation,
            }
            return {
                "evaluation_version": "rolling-evaluation:v2:diagnostic",
                "evaluation_kind": "CANONICAL_SIMULATION",
                "evaluation_run_id": run_identity(material),
                "source_digest": source_digest,
                "holding_period": holding_period,
                "exit_policy": exit_policy,
                "observation_horizon": observation_horizon,
                "selection_excluded": selection_excluded,
                "loaded_rows": len(rows),
                "valid_input_rows": len(valid_rows),
                "evaluator_invoked": False,
                "evaluator_completed": False,
                "evaluated_observations": 0,
                "signal_count": 0,
                "diagnostic_summary_count": 0,
                "evaluator_name": None,
                "evaluator_error": evaluation["evaluator_error"],
                "evaluator_prerequisite": evaluation["evaluator_prerequisite"],
                "portfolio_accounting": portfolio_accounting,
                "evaluation": evaluation,
                "metrics": {
                    "portfolio_accounting": portfolio_accounting,
                    "evaluation": evaluation,
                },
                "accounting_available": False,
                "accounting_complete": False,
                "accounting_partial": True,
            }
        model_error: str | None = None
        model_required = _rolling_prediction_model_required(strategy)
        if model_required is False:
            # Directional families consume the market probability path only;
            # no caller/model probability is admitted into this evaluator.
            model_document = None
            model_resolution = _rolling_model_free_resolution()
        else:
            try:
                model_document, model_resolution = self._resolve_rolling_model(strategy)
            except (TypeError, ValueError, RuntimeError) as exc:
                model_error = str(exc).split(":", 1)[0].strip() or "MODEL_INPUT_MISSING"
        verified_field: str | None = None
        if (
            isinstance(model_document, Mapping)
            and "probability" not in model_document
            and "yes_probability" not in model_document
        ):
            field_value = model_document.get("field")
            if isinstance(field_value, str) and field_value.strip():
                verified_field = field_value.strip()
        valid_rows = [
            _rolling_model_authoritative_row(
                row,
                verified_field=verified_field,
            )
            for row in valid_rows
        ]
        source_digest = _rolling_hash(valid_rows)
        evaluator_invoked = False
        try:
            if model_error is not None:
                raise ValueError(model_error)
            definition = load_strategy(document)
            evaluator_invoked = True
            result = run_prediction_research_mode(
                valid_rows,
                definition,
                mode=mode,
                model_document=model_document if isinstance(model_document, Mapping) else None,
                holding_period=holding_period,
                observation_horizon=observation_horizon,
                exit_policy=exit_policy,
            )
        except Exception as exc:
            error = str(exc) or type(exc).__name__
            evaluation = {
                "evaluation_kind": "CANONICAL_SIMULATION",
                "evaluator_invoked": evaluator_invoked,
                "evaluator_completed": False,
                "evaluated_observations": 0,
                "signal_count": 0,
                "diagnostic_summary_count": 1,
                "evaluator_name": None,
                "evaluator_error": error,
                "evaluator_prerequisite": (
                    error
                    if error in {
                        "MODEL_INPUT_MISSING",
                        "MODEL_INPUT_INVALID",
                        "MODEL_HASH_MISSING",
                        "MODEL_LINEAGE_AMBIGUOUS",
                        "MODEL_LINEAGE_INCOMPLETE",
                        "MODEL_LINEAGE_MISMATCH",
                        "MODEL_LINEAGE_LOAD_FAILED",
                        "MODEL_PLAN_MISSING",
                        "MODEL_PLAN_NOT_EXECUTABLE",
                        "MODEL_PLAN_HASH_MISMATCH",
                    }
                    else None
                ),
            }
            if model_resolution is not None:
                evaluation["model_resolution"] = dict(model_resolution)
            portfolio_accounting = {
                "accounting_available": False,
                "initial_cash": None,
                "cash": None,
                "equity": None,
                "realized_pnl": None,
                "unrealized_pnl": None,
                "net_pnl": None,
                "fees": None,
                "costs": None,
                "open_positions": [],
                "opening_fills": 0,
                "closing_fills": 0,
                "partial_closing_fills": 0,
                "completed_round_trips": 0,
            }
            material = {
                "version": "rolling-evaluation:v2:diagnostic",
                "source": requested_source,
                "mode": mode,
                "source_digest": source_digest,
                "evaluation": evaluation,
            }
            return {
                "holding_period": holding_period,
                "exit_policy": exit_policy,
                "observation_horizon": observation_horizon,
                "selection_excluded": selection_excluded,
                "evaluation_version": "rolling-evaluation:v2:diagnostic",
                "evaluation_kind": "CANONICAL_SIMULATION",
                "evaluation_run_id": run_identity(material),
                "source_digest": source_digest,
                "loaded_rows": len(rows),
                "valid_input_rows": len(valid_rows),
                "evaluator_invoked": evaluator_invoked,
                "evaluator_completed": False,
                "evaluated_observations": 0,
                "signal_count": 0,
                "diagnostic_summary_count": 1,
                "evaluator_prerequisite": evaluation.get("evaluator_prerequisite"),
                "evaluator_error": error,
                "portfolio_accounting": portfolio_accounting,
                "evaluation": evaluation,
                "metrics": {
                    "portfolio_accounting": portfolio_accounting,
                    "evaluation": evaluation,
                },
                "accounting_available": False,
                "accounting_complete": False,
                "accounting_partial": True,
                "accounting_unavailable_reason": error,
            }

        metrics = getattr(result, "metrics", {})
        metrics = metrics if isinstance(metrics, Mapping) else {}
        raw_portfolio = metrics.get("portfolio_accounting")
        raw_evaluation = metrics.get("evaluation")
        portfolio_accounting = (
            dict(raw_portfolio) if isinstance(raw_portfolio, Mapping) else {}
        )
        evaluation = dict(raw_evaluation) if isinstance(raw_evaluation, Mapping) else {}
        evaluation.setdefault("evaluation_kind", "CANONICAL_SIMULATION")
        if model_resolution is not None:
            evaluation["model_resolution"] = dict(model_resolution)
        path_manifest = metrics.get("path_manifest")
        if (
            isinstance(path_manifest, Mapping)
            and isinstance(raw_evaluation, Mapping)
            and raw_evaluation.get("evaluator_invoked") is False
            and raw_evaluation.get("evaluator_completed") is False
        ):
            exclusions = path_manifest.get("exclusion_reasons")
            if isinstance(exclusions, Mapping) and exclusions.get("INSUFFICIENT_OBSERVATIONS"):
                # Structural path selection happens before signal evaluation.
                # Preserve that fact as the strategy-level lookback blocker
                # instead of reporting an opaque unavailable evaluator.
                evaluation["evaluator_error"] = "INSUFFICIENT_LOOKBACK"
                evaluation["evaluator_prerequisite"] = "INSUFFICIENT_LOOKBACK"

        # V2 status is authoritative only when the evaluator emitted both
        # nested boolean fields.  A result curve is not an evaluator
        # attestation and must never be used to infer completion.
        explicit_status = isinstance(raw_evaluation, Mapping) and all(
            name in raw_evaluation and isinstance(raw_evaluation.get(name), bool)
            for name in ("evaluator_invoked", "evaluator_completed")
        )
        status_error: str | None = None
        if not explicit_status:
            status_error = "EVALUATOR_STATUS_REQUIRED"
            evaluation["evaluator_invoked"] = (
                raw_evaluation.get("evaluator_invoked") is True
                if isinstance(raw_evaluation, Mapping)
                else False
            )
            evaluation["evaluator_completed"] = False
            evaluation["evaluator_error"] = (
                evaluation.get("evaluator_error") or status_error
            )
            evaluation["evaluator_prerequisite"] = status_error

        # Keep the legacy shape readable, but never treat it as complete
        # canonical accounting.  V2 admission requires the explicit nested
        # portfolio accounting emitted by the evaluator.
        if not portfolio_accounting:
            legacy = metrics.get("portfolio")
            legacy = legacy if isinstance(legacy, Mapping) else {}
            portfolio_accounting = {
                "accounting_available": False,
                "initial_cash": metrics.get("initial_equity"),
                "cash": None,
                "equity": metrics.get("final_equity"),
                "realized_pnl": legacy.get("realized_pnl", metrics.get("realized_pnl")),
                "unrealized_pnl": legacy.get(
                    "unrealized_pnl", metrics.get("unrealized_pnl")
                ),
                "net_pnl": metrics.get("net_pnl"),
                "fees": metrics.get("fees"),
                "costs": metrics.get("costs"),
                "open_positions": list(getattr(result, "unresolved", ()) or ()),
                "opening_fills": 0,
                "closing_fills": 0,
                "partial_closing_fills": 0,
                "completed_round_trips": metrics.get("completed_outcomes"),
            }
        fills = tuple(getattr(result, "fills", ()) or ())
        allocated_capital = Decimal("0")
        for fill in fills:
            metadata = getattr(fill, "metadata", {})
            metadata = metadata if isinstance(metadata, Mapping) else {}
            execution_kind = str(metadata.get("execution_kind", "entry")).strip().lower()
            if execution_kind in {"exit", "close"}:
                continue
            allocated_capital += _rolling_number(
                getattr(fill, "quantity", 0)
            ) * _rolling_number(getattr(fill, "price", 0))

        count_values: dict[str, int] = {}
        count_error: str | None = None
        count_defaults = {
            "evaluated_observations": 0,
            "signal_count": 0,
            "diagnostic_summary_count": (
                0 if evaluation.get("evaluator_completed") is True else 1
            ),
        }
        for name, default in count_defaults.items():
            try:
                parsed = _rolling_strict_count(
                    evaluation.get(name),
                    name,
                    default=default,
                )
            except ValueError:
                count_error = name
                parsed = 0
            count_values[name] = int(parsed or 0)
        if count_error is not None:
            evaluation["evaluator_completed"] = False
            evaluation["evaluator_error"] = "EVALUATOR_COUNT_METRIC_INVALID"
            evaluation["evaluator_prerequisite"] = count_error
            count_values["diagnostic_summary_count"] = 1
        if status_error is not None:
            count_values["diagnostic_summary_count"] = 1

        accounting_count_error: str | None = None
        for name in (
            "completed_round_trips",
            "completed_outcomes",
            "opening_fills",
            "closing_fills",
            "partial_closing_fills",
            "open_position_count",
        ):
            if name not in portfolio_accounting:
                continue
            value = portfolio_accounting.get(name)
            if isinstance(value, (list, tuple, set, frozenset)):
                continue
            try:
                _rolling_strict_count(value, name)
            except ValueError:
                accounting_count_error = name
                portfolio_accounting[name] = None
                break
        if accounting_count_error is not None:
            evaluation["evaluator_completed"] = False
            evaluation["evaluator_error"] = "ACCOUNTING_COUNT_METRIC_INVALID"
            evaluation["evaluator_prerequisite"] = accounting_count_error
        evaluator_invoked = evaluation.get("evaluator_invoked") is True
        evaluator_completed = evaluation.get("evaluator_completed") is True
        evaluator_name = evaluation.get("evaluator_name")
        if evaluator_name is None:
            evaluator_name = metrics.get("evaluator_name")
        evaluated_observations = count_values["evaluated_observations"]
        signal_count = count_values["signal_count"]
        diagnostic_count = count_values["diagnostic_summary_count"]
        if accounting_count_error is not None:
            count_values["diagnostic_summary_count"] = 1
            diagnostic_count = 1
        evaluation.update(
            {
                "evaluation_kind": "CANONICAL_SIMULATION",
                "evaluator_invoked": evaluator_invoked,
                "evaluator_completed": evaluator_completed,
                "evaluated_observations": evaluated_observations,
                "signal_count": signal_count,
                "diagnostic_summary_count": diagnostic_count,
                "evaluator_name": evaluator_name,
                "evaluator_error": evaluation.get("evaluator_error"),
                "evaluator_prerequisite": evaluation.get("evaluator_prerequisite"),
            }
        )


        # Do not synthesize accounting availability from a completed
        # no-signal run (or from any single P&L field).  Every canonical
        # monetary/count field must be present and finite before it can be
        # exposed as available.
        accounting_complete_flag = portfolio_accounting.get("accounting_complete")
        accounting_partial_flag = portfolio_accounting.get("accounting_partial")
        accounting_complete = (
            evaluator_invoked
            and evaluator_completed
            and portfolio_accounting.get("accounting_available") is True
            and (
                accounting_complete_flag is None
                or accounting_complete_flag is True
            )
            and (
                accounting_partial_flag is None
                or accounting_partial_flag is False
            )
            and _rolling_canonical_accounting_complete(portfolio_accounting)
        )
        if not accounting_complete:
            diagnostic_count = max(1, int(diagnostic_count))
            evaluation["diagnostic_summary_count"] = diagnostic_count

        if not accounting_complete:
            portfolio_accounting["accounting_available"] = False
            portfolio_accounting["accounting_complete"] = False
            portfolio_accounting["accounting_partial"] = True
            for name in _ROLLING_CANONICAL_MONETARY_FIELDS:
                value = portfolio_accounting.get(name)
                if not evaluator_completed or value is None:
                    portfolio_accounting[name] = None
                else:
                    try:
                        parsed = Decimal(str(value))
                    except (InvalidOperation, TypeError, ValueError, OverflowError):
                        portfolio_accounting[name] = None
                    else:
                        if isinstance(value, bool) or not parsed.is_finite():
                            portfolio_accounting[name] = None
        else:
            portfolio_accounting["accounting_available"] = True
            portfolio_accounting["accounting_complete"] = True
            portfolio_accounting["accounting_partial"] = False
        if not evaluator_invoked or not evaluator_completed:
            portfolio_accounting["accounting_available"] = False
            for name in _ROLLING_CANONICAL_MONETARY_FIELDS:
                portfolio_accounting[name] = None
        fills = tuple(getattr(result, "fills", ()) or ())
        operational_evidence = _operational_stage_projection(
            rows=valid_rows,
            fills=fills,
            curve=tuple(getattr(result, "equity_curve", ()) or ()),
            remaining_positions=getattr(result, "unresolved", ()),
            valid_observations=evaluated_observations,
        )
        if isinstance(portfolio_accounting, Mapping):
            operational_evidence["completed_outcomes"] = int(
                _rolling_number(
                    portfolio_accounting.get(
                        "completed_round_trips",
                        portfolio_accounting.get("completed_outcomes", 0),
                    ),
                    Decimal("0"),
                )
            )
            if portfolio_accounting.get("accounting_available") is True and evaluator_completed:
                realized = portfolio_accounting.get("realized_pnl")
                unrealized = portfolio_accounting.get("unrealized_pnl")
                net = portfolio_accounting.get("net_pnl")
                fees = portfolio_accounting.get("fees")
                costs = portfolio_accounting.get("costs")
                if all(value is not None for value in (realized, unrealized, net, fees, costs)):
                    net_value = _rolling_number(net)
                    operational_evidence.update(
                        {
                            "realized_result": _rolling_number(realized),
                            "unrealized_result": _rolling_number(unrealized),
                            "net_result": net_value,
                            "gross_result": net_value
                            + _rolling_number(fees)
                            + _rolling_number(costs),
                            "economic_result_available": True,
                        }
                    )
        evaluation["operational_evidence"] = dict(operational_evidence)
        material = {
            "version": "rolling-evaluation:v2",
            "source": requested_source,
            "mode": mode,
            "source_digest": source_digest,
            "portfolio_accounting": portfolio_accounting,
            "evaluation": evaluation,
            "operational_evidence": operational_evidence,
            **(
                {
                    "operational_setup_hash": _operational_setup_hash(operational_setup),
                    "capture_spec": dict(capture_spec),
                }
                if capture_spec is not None
                else {}
            ),
        }
        evaluation_run_id = run_identity(material)
        return {
            "evaluation_version": "rolling-evaluation:v2",
            "evaluation_kind": "CANONICAL_SIMULATION",
            "evaluation_run_id": evaluation_run_id,
            "source_digest": source_digest,
            "holding_period": holding_period,
            "exit_policy": exit_policy,
            "observation_horizon": observation_horizon,
            "selection_excluded": selection_excluded,
            "loaded_rows": len(rows),
            "valid_input_rows": len(valid_rows),
            "evaluator_invoked": evaluation["evaluator_invoked"],
            "evaluator_completed": evaluation["evaluator_completed"],
            **(
                {
                    "operational_setup_hash": _operational_setup_hash(operational_setup),
                    "capture_spec": dict(capture_spec),
                }
                if capture_spec is not None
                else {}
            ),
            "evaluated_observations": evaluated_observations,
            "signal_count": signal_count,
            "diagnostic_summary_count": diagnostic_count,
            "evaluator_name": evaluator_name,
            "evaluator_error": evaluation.get("evaluator_error"),
            "evaluator_prerequisite": evaluation.get("evaluator_prerequisite"),
            "portfolio_accounting": portfolio_accounting,
            "evaluation": evaluation,
            "operational_evidence": operational_evidence,
            "metrics": {
                "portfolio_accounting": portfolio_accounting,
                "evaluation": evaluation,
                "operational_evidence": operational_evidence,
            },
            "accounting_unavailable_reason": (
                evaluation.get("evaluator_error")
                or evaluation.get("evaluator_prerequisite")
                or (
                    "ACCOUNTING_FIELDS_INCOMPLETE"
                    if not accounting_complete
                    else None
                )
            ),
        }
    def _rolling_evidence_record(
        self,
        strategy: Mapping[str, Any],
        rows: Sequence[Mapping[str, Any]],
        source_class: str,
        days: int,
        now: datetime,
        evaluation: Mapping[str, Any] | None = None,
    ) -> dict[str, Any] | None:
        """Build one immutable v2 evidence result from canonical metrics."""
        if days not in {7, 30} or not rows:
            return None
        requested_source = _rolling_source_name(source_class)
        persisted_source = _rolling_persisted_source_class(requested_source)
        if requested_source == "REPLAY" and any(
            isinstance(row, Mapping)
            and not _rolling_replay_row_terminal(row)
            and not _rolling_has_paired_timestamped_books(row)
            for row in rows
        ):
            # Do not salvage a smaller replay subset from an incomplete
            # window; missing non-terminal paired books is a hard blocker.
            return None
        canonical_required = requested_source in {"HISTORICAL", "REPLAY", "LIVE"}
        # PAPER is the sole exact-account-ledger source.  Every other source,
        # including unbound LIVE price-proxy rows, is evaluated canonically.
        capture_source = any(
            isinstance(row, Mapping)
            and row.get("paper_observation_capture") is True
            for row in rows
        )
        actual_ledger = requested_source == "PAPER" and not capture_source
        if evaluation is None and canonical_required:
            evaluation = self._rolling_canonical_evaluation(
                strategy, rows, requested_source
            )

        def dec(value: Any, default: Decimal = Decimal("0")) -> Decimal:
            if value is None or isinstance(value, bool):
                return default
            try:
                parsed = Decimal(str(value))
            except (InvalidOperation, TypeError, ValueError, OverflowError):
                return default
            return parsed if parsed.is_finite() else default

        valid_times = [
            _rolling_row_time(_rolling_snapshot_view(row))
            for row in rows
            if isinstance(row, Mapping)
            and not row.get("_rolling_source_rejection")
            and not row.get("_rolling_accounting_rejection")
            and _rolling_row_time(_rolling_snapshot_view(row)) is not None
        ]
        if not valid_times and actual_ledger:
            # Keep an exact but incomplete PAPER ledger observable as an
            # unavailable accounting result; malformed source timestamps still
            # fail closed without materializing an evidence window.
            valid_times = [
                _rolling_row_time(_rolling_snapshot_view(row))
                for row in rows
                if isinstance(row, Mapping)
                and _rolling_row_time(_rolling_snapshot_view(row)) is not None
            ]
        if not valid_times:
            return None
        evaluation_map = dict(evaluation) if isinstance(evaluation, Mapping) else {}
        nested_metrics = evaluation_map.get("metrics")
        nested_metrics = nested_metrics if isinstance(nested_metrics, Mapping) else {}
        canonical_accounting = evaluation_map.get("portfolio_accounting")
        if not isinstance(canonical_accounting, Mapping):
            canonical_accounting = nested_metrics.get("portfolio_accounting")
        canonical_accounting = (
            dict(canonical_accounting)
            if isinstance(canonical_accounting, Mapping)
            else None
        )
        canonical_evaluation = evaluation_map.get("evaluation")
        operational_evidence = evaluation_map.get("operational_evidence")
        operational_evidence = (
            dict(operational_evidence)
            if isinstance(operational_evidence, Mapping)
            else {}
        )
        paper_events: list[Mapping[str, Any]] = []
        paper_fills: list[Any] = []
        if actual_ledger:
            experiment_ids = {
                str(row.get("_paper_experiment_id", "")).strip()
                for row in rows
                if isinstance(row, Mapping)
                and str(row.get("_paper_experiment_id", "")).strip()
            }
            event_loader = getattr(self.store, "list_paper_execution_events", None)
            fill_loader = getattr(self.store, "load_fills", None)
            if callable(event_loader):
                for experiment_id in sorted(experiment_ids):
                    try:
                        values = event_loader(
                            experiment_id,
                            limit=_MAX_ROLLING_SOURCE_ROWS,
                        )
                    except (TypeError, ValueError, RuntimeError):
                        values = ()
                    if isinstance(values, Sequence) and not isinstance(values, (str, bytes)):
                        paper_events.extend(
                            item for item in values if isinstance(item, Mapping)
                        )
            if callable(fill_loader):
                strategy_hash = str(strategy.get("strategy_hash", "")).strip()
                try:
                    values = fill_loader(strategy_id=strategy_hash)
                except (TypeError, ValueError, RuntimeError):
                    values = ()
                if isinstance(values, Sequence) and not isinstance(values, (str, bytes)):
                    for item in values:
                        metadata = getattr(item, "metadata", {})
                        metadata = metadata if isinstance(metadata, Mapping) else {}
                        if (
                            isinstance(item, Fill)
                            and str(metadata.get("paper_experiment_id", "")).strip()
                            in experiment_ids
                        ):
                            paper_fills.append(item)
            operational_evidence = _operational_stage_projection(
                rows=rows,
                events=paper_events,
                fills=paper_fills,
                ledgers=rows,
                valid_observations=sum(
                    1
                    for row in rows
                    if isinstance(row, Mapping)
                    and not row.get("_rolling_source_rejection")
                    and not row.get("_rolling_timestamp_rejection")
                ),
            )
        if canonical_accounting is not None:
            # Evidence schema bounds the immutable open-position projection.
            # Canonical evaluators may report a larger inventory, but the
            # evidence record must fail closed rather than hand an oversized
            # document to RollingEvidence.from_mapping during digesting.
            raw_positions = canonical_accounting.get("open_positions")
            positions_valid = isinstance(
                raw_positions, (list, tuple, set, frozenset)
            )
            if positions_valid and isinstance(raw_positions, (set, frozenset)):
                try:
                    raw_positions = tuple(
                        sorted(raw_positions, key=_canonical_binding)
                    )
                except (TypeError, ValueError, ArithmeticError):
                    positions_valid = False
            if (
                not positions_valid
                or raw_positions is None
                or len(raw_positions) > _ROLLING_OPEN_POSITIONS_LIMIT
            ):
                canonical_accounting["open_positions"] = []
                canonical_accounting["accounting_available"] = False
                canonical_accounting["accounting_complete"] = False
                canonical_accounting["accounting_partial"] = True
                canonical_accounting["accounting_unavailable_reason"] = (
                    _ROLLING_OPEN_POSITIONS_LIMIT_REASON
                    if positions_valid
                    and raw_positions is not None
                    and len(raw_positions) > _ROLLING_OPEN_POSITIONS_LIMIT
                    else "ACCOUNTING_OPEN_POSITIONS_INVALID"
                )
            else:
                canonical_accounting["open_positions"] = list(raw_positions)
            # The storage contract compares top-level monetary fields with
            # their nested accounting projection byte-for-byte.  Evaluators
            # commonly emit floats while the immutable evidence projection is
            # decimal text; normalize the nested copy before persistence so
            # equivalent values do not look like contradictory provenance.
            for name in (
                "initial_cash",
                "cash",
                "equity",
                "realized_pnl",
                "unrealized_pnl",
                "net_pnl",
                "fees",
                "costs",
                "allocated_capital",
                "capital_at_risk",
            ):
                value = canonical_accounting.get(name)
                if value is None:
                    continue
                try:
                    parsed = Decimal(str(value))
                except (InvalidOperation, TypeError, ValueError, OverflowError):
                    continue
                if parsed.is_finite() and not isinstance(value, bool):
                    canonical_accounting[name] = str(parsed)
        if not isinstance(canonical_evaluation, Mapping):
            canonical_evaluation = nested_metrics.get("evaluation")
        canonical_evaluation = (
            dict(canonical_evaluation)
            if isinstance(canonical_evaluation, Mapping)
            else {}
        )
        if actual_ledger:
            # PAPER rows are measured from the exact account ledger.  They do
            # not execute the evaluator and must remain explicit about that.
            canonical_accounting = None
            canonical_evaluation = {
                "evaluation_kind": "ACTUAL_LEDGER",
                "evaluator_invoked": False,
                "evaluator_completed": False,
                "evaluated_observations": 0,
                "signal_count": 0,
                "diagnostic_summary_count": 0,
                "evaluator_name": None,
                "evaluator_error": None,
                "evaluator_prerequisite": None,
            }
        else:
            canonical_evaluation.setdefault("evaluation_kind", "CANONICAL_SIMULATION")
            if canonical_evaluation.get("evaluation_kind") != "CANONICAL_SIMULATION":
                canonical_evaluation["evaluator_invoked"] = False
                canonical_evaluation["evaluator_completed"] = False
                canonical_evaluation["evaluator_error"] = (
                    canonical_evaluation.get("evaluator_error")
                    or "EVALUATION_KIND_INVALID"
                )
                canonical_evaluation["evaluator_prerequisite"] = (
                    canonical_evaluation.get("evaluator_prerequisite")
                    or "EVALUATION_KIND_INVALID"
                )
        canonical_status_valid = isinstance(canonical_evaluation, Mapping) and all(
            name in canonical_evaluation and isinstance(canonical_evaluation.get(name), bool)
            for name in ("evaluator_invoked", "evaluator_completed")
        )
        if not canonical_status_valid:
            canonical_evaluation["evaluator_invoked"] = False
            canonical_evaluation["evaluator_completed"] = False
            canonical_evaluation["evaluator_error"] = (
                canonical_evaluation.get("evaluator_error")
                or "EVALUATOR_STATUS_REQUIRED"
            )
            canonical_evaluation["evaluator_prerequisite"] = (
                canonical_evaluation.get("evaluator_prerequisite")
                or "EVALUATOR_STATUS_REQUIRED"
            )
            canonical_evaluation["diagnostic_summary_count"] = 1
        if canonical_accounting is not None:
            accounting_complete_flag = canonical_accounting.get("accounting_complete")
            accounting_partial_flag = canonical_accounting.get("accounting_partial")
            accounting_flags_unusable = (
                (
                    accounting_complete_flag is not None
                    and accounting_complete_flag is not True
                )
                or (
                    accounting_partial_flag is not None
                    and accounting_partial_flag is not False
                )
            )
            accounting_unusable = (
                canonical_accounting.get("accounting_available") is not True
                or not _rolling_canonical_accounting_complete(canonical_accounting)
                or accounting_flags_unusable
                or (
                    canonical_required
                    and (
                        canonical_evaluation.get("evaluator_invoked") is not True
                        or canonical_evaluation.get("evaluator_completed") is not True
                    )
                )
            )
            if accounting_unusable:
                canonical_accounting["accounting_available"] = False
                canonical_accounting["accounting_complete"] = False
                canonical_accounting["accounting_partial"] = True
        if canonical_required and canonical_accounting is None:
            # A missing canonical result is an explicit unavailable evaluation,
            # never permission to consume a row's private accounting.
            canonical_accounting = {
                "accounting_available": False,
                "initial_cash": None,
                "cash": None,
                "equity": None,
                "realized_pnl": None,
                "unrealized_pnl": None,
                "net_pnl": None,
                "fees": None,
                "costs": None,
                "open_positions": [],
                "opening_fills": 0,
                "closing_fills": 0,
                "partial_closing_fills": 0,
                "completed_round_trips": 0,
            }
            canonical_evaluation["evaluator_invoked"] = False
            canonical_evaluation["evaluator_completed"] = False
            canonical_evaluation.setdefault("evaluated_observations", 0)
            canonical_evaluation.setdefault("signal_count", 0)
            try:
                diagnostic_default = _rolling_strict_count(
                    canonical_evaluation.get("diagnostic_summary_count"),
                    "diagnostic_summary_count",
                    default=0,
                )
            except ValueError:
                diagnostic_default = 0
            canonical_evaluation["diagnostic_summary_count"] = max(
                1,
                int(diagnostic_default or 0),
            )
            canonical_evaluation.setdefault("evaluator_name", None)
            canonical_evaluation["evaluator_error"] = (
                canonical_evaluation.get("evaluator_error")
                or "CANONICAL_EVALUATION_UNAVAILABLE"
            )
            canonical_evaluation["evaluator_prerequisite"] = (
                canonical_evaluation.get("evaluator_prerequisite")
                or "CANONICAL_EVALUATION_UNAVAILABLE"
            )
            evaluation_map.setdefault(
                "evaluation_version", "rolling-evaluation:v2"
            )
            evaluation_map.setdefault(
                "evaluation_run_id",
                "rolling-evaluation:v2:"
                + _rolling_hash(
                    {
                        "source": requested_source,
                        "rows": rows,
                        "reason": canonical_evaluation[
                            "evaluator_prerequisite"
                        ],
                    }
                ).removeprefix("sha256:")[:40],
            )
            evaluation_map.setdefault("source_digest", _rolling_hash(rows))

        projected: list[tuple[Mapping[str, Any], Mapping[str, Any]]] = []
        partial_accounting = False
        if canonical_required:
            pa = canonical_accounting or {}
            start = next(
                (
                    _rolling_timestamp(pa.get(name))
                    for name in ("available_from", "coverage_from", "window_start")
                    if _rolling_timestamp(pa.get(name)) is not None
                ),
                min(valid_times),
            )
            through = next(
                (
                    _rolling_timestamp(pa.get(name))
                    for name in (
                        "available_through",
                        "coverage_through",
                        "window_end",
                    )
                    if _rolling_timestamp(pa.get(name)) is not None
                ),
                max(valid_times),
            )
            if through < start:
                return None
            available = (
                pa.get("accounting_available") is True
                and _rolling_canonical_accounting_complete(pa)
                and (
                    pa.get("accounting_complete") is None
                    or pa.get("accounting_complete") is True
                )
                and (
                    pa.get("accounting_partial") is None
                    or pa.get("accounting_partial") is False
                )
            )
            complete = (
                canonical_evaluation.get("evaluator_invoked") is True
                and canonical_evaluation.get("evaluator_completed") is True
                and available
            )
            partial_accounting = not available or not complete

            opening_fills = pa.get("opening_fills")
            opening_fill_rows = (
                list(opening_fills)
                if isinstance(opening_fills, (list, tuple))
                else []
            )
            allocated = pa.get("allocated_capital", pa.get("capital_at_risk"))
            realized = pa.get("realized_pnl")
            unrealized = pa.get("unrealized_pnl")
            net_pnl = pa.get("net_pnl")
            fees = pa.get("fees")
            costs = pa.get("costs")
            completed = pa.get(
                "completed_round_trips",
                pa.get("completed_outcomes", 0),
            )
            reliability = pa.get(
                "reliability",
                Decimal("1") if available else Decimal("0"),
            )
            drawdown = pa.get("drawdown", 0)
            projected.append(
                (
                    {"_rolling_canonical": True},
                    {
                        "_available_from": start,
                        "_available_through": through,
                        "allocated_capital": dec(allocated) if available else Decimal("0"),
                        "allocated_capital_net_return": (
                            dec(net_pnl if net_pnl is not None else realized)
                            if available
                            else Decimal("0")
                        ),
                        "realized_pnl": dec(realized) if available else Decimal("0"),
                        "unrealized_pnl": dec(unrealized) if available else Decimal("0"),
                        "fees": dec(fees) if available else Decimal("0"),
                        "costs": dec(costs) if available else Decimal("0"),
                        "drawdown": dec(drawdown) if available else Decimal("0"),
                        "completed_outcomes": completed,
                        "reliability": dec(reliability),
                        "execution_feasibility": pa.get("execution_feasibility"),
                    },
                )
            )
        else:
            # PAPER and exact-identity LIVE ledgers retain their validated
            # accounting projection.  Raw unbound rows never enter this path.
            for row in rows:
                if not isinstance(row, Mapping):
                    partial_accounting = True
                    continue
                if row.get("_rolling_source_rejection") or row.get(
                    "_rolling_accounting_rejection"
                ):
                    partial_accounting = True
                    continue
                accounting = row.get("_rolling_accounting")
                if not isinstance(accounting, Mapping):
                    accounting = self._rolling_accounting_projection(row, strategy)
                if isinstance(accounting, Mapping):
                    projected.append((row, accounting))
                else:
                    partial_accounting = True
            if not projected:
                projected.append(
                    (
                        {"_rolling_partial": True},
                        {
                            "_available_from": min(valid_times),
                            "_available_through": max(valid_times),
                            "allocated_capital": Decimal("0"),
                            "allocated_capital_net_return": Decimal("0"),
                            "realized_pnl": Decimal("0"),
                            "unrealized_pnl": Decimal("0"),
                            "fees": Decimal("0"),
                            "costs": Decimal("0"),
                            "drawdown": Decimal("0"),
                            "completed_outcomes": Decimal("0"),
                            "reliability": Decimal("0"),
                        },
                    )
                )
                partial_accounting = True

        intervals: list[tuple[datetime, datetime]] = []
        for _row, accounting in projected:
            start = accounting.get("_available_from")
            through = accounting.get("_available_through")
            if isinstance(start, datetime) and isinstance(through, datetime):
                if through >= start:
                    intervals.append((start, through))
        if not intervals:
            return None
        intervals.sort()
        merged: list[tuple[datetime, datetime]] = []
        for start, through in intervals:
            if not merged or start > merged[-1][1]:
                merged.append((start, through))
            elif through > merged[-1][1]:
                merged[-1] = (merged[-1][0], through)
        available_from = min(start for start, _through in intervals)
        available_through = max(through for _start, through in intervals)
        if actual_ledger:
            canonical_accounting = _rolling_actual_ledger_accounting(
                () if partial_accounting else projected,
                available_from=available_from,
                available_through=available_through,
            )
            partial_accounting = (
                partial_accounting
                or canonical_accounting.get("accounting_available") is not True
                or canonical_accounting.get("accounting_complete") is not True
                or canonical_accounting.get("accounting_partial") is not False
            )
        actual_coverage = sum(
            int((through - start).total_seconds()) for start, through in merged
        )
        selected = list(projected)

        count_error: str | None = None

        def count_value(value: Any, name: str = "count") -> int:
            nonlocal count_error
            try:
                parsed = _rolling_strict_count(value, name, default=0)
            except ValueError:
                count_error = name
                return 0
            return int(parsed or 0)

        def collection_count(value: Any, name: str = "count") -> int:
            if isinstance(value, (list, tuple, set, frozenset)):
                return len(value)
            return count_value(value, name)
        def aggregate(name: str, *aliases: str) -> Decimal:
            return sum(
                (
                    dec(next((item.get(key) for key in (name,) + aliases if item.get(key) is not None), 0))
                    for _row, item in selected
                ),
                Decimal("0"),
            )

        allocated_capital = aggregate(
            "allocated_capital", "paper_sizing", "paper_size"
        )
        net_return = aggregate(
            "allocated_capital_net_return", "net_return", "net_pnl"
        )
        realized_pnl = aggregate("realized_pnl")
        unrealized_pnl = aggregate("unrealized_pnl")
        fees = aggregate("fees", "fee_costs")
        costs = aggregate("costs", "slippage_costs")
        completed_values: list[int] = []
        for _row, item in selected:
            raw_completed = next(
                (
                    item.get(key)
                    for key in ("completed_outcomes", "completed_round_trips")
                    if item.get(key) is not None
                ),
                None,
            )
            completed_values.append(count_value(raw_completed, "completed_outcomes"))
        completed = sum(completed_values) if count_error is None else 0

        reliabilities = [dec(item.get("reliability")) for _row, item in selected]
        reliability = (
            sum(reliabilities, Decimal("0")) / Decimal(len(reliabilities))
            if reliabilities
            else Decimal("0")
        )
        drawdown = max(
            (dec(item.get("drawdown")) for _row, item in selected),
            default=Decimal("0"),
        )
        feasibility: Any = None
        for _row, item in selected:
            if item.get("execution_feasibility") is not None:
                feasibility = item["execution_feasibility"]
                break
        provenance = (
            strategy.get("provenance")
            if isinstance(strategy.get("provenance"), Mapping)
            else {}
        )
        candidate_id = str(
            strategy.get("candidate_id") or provenance.get("candidate_id") or ""
        ).strip() or None
        trial_id = str(
            strategy.get("research_trial_id")
            or provenance.get("research_trial_id")
            or ""
        ).strip() or None
        source_binding = _rolling_source_binding(strategy)
        source_digest = str(
            evaluation_map.get("source_digest") or _rolling_hash(rows)
        )
        accounting_digest = str(
            evaluation_map.get("accounting_digest")
            or _rolling_hash(canonical_accounting or [dict(item) for _row, item in selected])
        )
        evaluated_observations = evaluation_map.get(
            "evaluated_observations",
            canonical_evaluation.get("evaluated_observations", 0),
        )
        dataset_id = _binding_value(source_binding.get("dataset_id"))
        dataset_version = _binding_value(
            source_binding.get("dataset_version", source_binding.get("version"))
        )
        if requested_source == "REPLAY":
            for row in rows:
                catalog_binding = (
                    row.get("_rolling_replay_catalog")
                    if isinstance(row, Mapping)
                    else None
                )
                if isinstance(catalog_binding, Mapping):
                    dataset_id = _binding_value(catalog_binding.get("dataset_id"))
                    dataset_version = _binding_value(
                        catalog_binding.get("dataset_version")
                    )
                    break
        manifest_rows = (
            [
                _rolling_model_authoritative_row(row)
                if isinstance(row, Mapping)
                else {}
                for row in rows
            ]
            if canonical_required
            else rows
        )
        input_manifest = _rolling_input_manifest(
            manifest_rows,
            source=requested_source,
            dataset_id=dataset_id,
            dataset_version=dataset_version,
        )
        operational_identity = _operational_identity_projection(
            strategy,
            evaluation_map,
            canonical_evaluation,
            *paper_events,
            *rows,
        )
        if (
            (
                operational_identity.get("operational_setup") is not None
                or operational_identity.get("operational_setup_hash") not in (None, "")
            )
            and operational_identity.get("settings_config_id") in (None, "")
        ):
            active_loader = getattr(self.store, "load_canary_setting_config", None)
            active_settings = None
            if callable(active_loader):
                try:
                    active_settings = active_loader(status="ACTIVE")
                except (TypeError, ValueError, RuntimeError):
                    active_settings = None
            if isinstance(active_settings, Mapping):
                values = active_settings.get("values", active_settings.get("settings"))
                if isinstance(values, Mapping):
                    operational_identity["active_settings"] = dict(values)
                operational_identity["settings_config_id"] = active_settings.get("config_id")
                operational_identity["settings_generation"] = active_settings.get("generation")
                operational_identity["settings_config_hash"] = active_settings.get(
                    "config_hash"
                )
                operational_identity["operational_settings_available"] = True
                operational_identity["operational_settings_blocker"] = None
            else:
                operational_identity["operational_settings_available"] = False
                operational_identity["operational_settings_blocker"] = (
                    "ACTIVE_SETTINGS_UNAVAILABLE"
                )
        resolved_provenance = evaluation_map.get("model_resolution")
        if not isinstance(resolved_provenance, Mapping):
            for nested in (
                canonical_evaluation,
                nested_metrics.get("evaluation"),
            ):
                if isinstance(nested, Mapping) and isinstance(
                    nested.get("model_resolution"), Mapping
                ):
                    resolved_provenance = nested["model_resolution"]
                    break
        if isinstance(resolved_provenance, Mapping):
            compact_resolution = {
                key: resolved_provenance.get(key)
                for key in ("source_type", "plan_id", "model_hash")
            }
            evaluation_map["model_resolution"] = compact_resolution
            canonical_evaluation.setdefault("model_resolution", compact_resolution)
            input_manifest = dict(input_manifest)
            input_manifest["model_resolution"] = compact_resolution
        signal_count = evaluation_map.get(
            "signal_count", canonical_evaluation.get("signal_count", 0)
        )
        diagnostic_count = evaluation_map.get(
            "diagnostic_summary_count",
            canonical_evaluation.get("diagnostic_summary_count", 0),
        )
        for name, value in (
            ("evaluated_observations", evaluated_observations),
            ("signal_count", signal_count),
            ("diagnostic_summary_count", diagnostic_count),
        ):
            try:
                parsed = _rolling_strict_count(value, name, default=0)
            except ValueError:
                count_error = name
                parsed = 0
            if name == "evaluated_observations":
                evaluated_observations = int(parsed or 0)
            elif name == "signal_count":
                signal_count = int(parsed or 0)
            else:
                diagnostic_count = int(parsed or 0)
        if actual_ledger:
            evaluator_invoked = False
            evaluator_completed = False
        else:
            evaluator_invoked = canonical_evaluation.get("evaluator_invoked")
            evaluator_completed = canonical_evaluation.get("evaluator_completed")
        status_valid = all(
            isinstance(value, bool)
            for value in (evaluator_invoked, evaluator_completed)
        )
        if canonical_required and not status_valid:
            evaluator_invoked = False
            evaluator_completed = False
            count_error = count_error or "EVALUATOR_STATUS_REQUIRED"
            diagnostic_count = max(1, int(diagnostic_count))
        else:
            evaluator_invoked = evaluator_invoked is True
            evaluator_completed = evaluator_completed is True
        if count_error is not None:
            evaluator_completed = False
            diagnostic_count = max(1, int(diagnostic_count))
            canonical_evaluation["evaluator_completed"] = False
            canonical_evaluation["diagnostic_summary_count"] = diagnostic_count
            canonical_evaluation["evaluator_error"] = (
                canonical_evaluation.get("evaluator_error")
                or evaluation_map.get("evaluator_error")
                or "EVALUATOR_COUNT_METRIC_INVALID"
            )
            canonical_evaluation["evaluator_prerequisite"] = (
                canonical_evaluation.get("evaluator_prerequisite")
                or evaluation_map.get("evaluator_prerequisite")
                or count_error
            )
        if canonical_required and canonical_accounting is not None and (
            not evaluator_invoked
            or not evaluator_completed
            or (
                canonical_accounting.get("accounting_complete") is not None
                and canonical_accounting.get("accounting_complete") is not True
            )
            or (
                canonical_accounting.get("accounting_partial") is not None
                and canonical_accounting.get("accounting_partial") is not False
            )
        ):
            canonical_accounting["accounting_available"] = False
            canonical_accounting["accounting_complete"] = False
            canonical_accounting["accounting_partial"] = True
        if canonical_required:
            partial_accounting = (
                partial_accounting
                or evaluator_invoked is not True
                or evaluator_completed is not True
            )
        if count_error is not None:
            partial_accounting = True
        if partial_accounting:
            diagnostic_count = max(1, int(diagnostic_count))
            canonical_evaluation["diagnostic_summary_count"] = diagnostic_count
        evaluation_version = str(
            evaluation_map.get("evaluation_version") or "rolling-evaluation:v2"
        )
        evaluation_run_id = str(
            evaluation_map.get("evaluation_run_id")
            or (
                "rolling-evaluation:v2:"
                + _rolling_hash(
                    {
                        "strategy_version_id": strategy.get("strategy_version_id"),
                        "source": requested_source,
                        "days": days,
                        "source_digest": source_digest,
                        "accounting_digest": accounting_digest,
                        "evaluated_observations": evaluated_observations,
                        "signal_count": signal_count,
                    }
                ).removeprefix("sha256:")[:40]
            )
        )
        evidence_identity = {
            "evaluation_run_id": evaluation_run_id,
            "evaluation_version": evaluation_version,
            "evaluation_kind": (
                "CANONICAL_SIMULATION" if canonical_required else "ACTUAL_LEDGER"
            ),
            "strategy_version_id": strategy["strategy_version_id"],
            "candidate_id": candidate_id,
            "research_trial_id": trial_id,
            "source_class": persisted_source,
            "requested_source_class": requested_source,
            "source_binding": source_binding,
            "requested_days": days,
            "available_from": available_from,
            "available_through": available_through,
            "actual_coverage_seconds": actual_coverage,
            "source_digest": source_digest,
            "accounting_digest": accounting_digest,
            "input_manifest": input_manifest,
            "operational_identity": operational_identity,
            "operational_evidence": operational_evidence,
        }
        evidence_digest = _rolling_hash(evidence_identity)
        window_id = (
            "rolling-evaluation:v2:evidence:"
            + evidence_digest.removeprefix("sha256:")[:40]
        )

        supersedes: str | None = None
        lister = getattr(self.store, "list_strategy_evidence_windows", None)
        if not callable(lister):
            raise AutonomousResearchError(
                "PREDECESSOR_LOOKUP_UNAVAILABLE",
                "list_strategy_evidence_windows is unavailable",
            )
        try:
            try:
                signature = inspect.signature(lister)
            except (TypeError, ValueError):
                signature = None
            if signature is None:
                prior_rows = lister(
                    strategy_version_id=str(strategy.get("strategy_version_id")),
                    limit=10_000,
                )
            else:
                parameters = signature.parameters
                strategy_parameter = parameters.get("strategy_version_id")
                keyword_strategy = (
                    strategy_parameter is not None
                    and strategy_parameter.kind
                    in (
                        inspect.Parameter.POSITIONAL_OR_KEYWORD,
                        inspect.Parameter.KEYWORD_ONLY,
                    )
                )
                accepts_arbitrary_keywords = any(
                    parameter.kind is inspect.Parameter.VAR_KEYWORD
                    for parameter in parameters.values()
                )
                if keyword_strategy or accepts_arbitrary_keywords:
                    prior_rows = lister(
                        strategy_version_id=str(strategy.get("strategy_version_id")),
                        limit=10_000,
                    )
                else:
                    prior_rows = lister(
                        str(strategy.get("strategy_version_id")),
                        limit=10_000,
                    )
            if prior_rows is None or isinstance(
                prior_rows,
                (Mapping, str, bytes, bytearray),
            ):
                raise TypeError("evidence window listing must be an iterable of records")
            prior_evidence: list[RollingEvidence] = []
            for prior in prior_rows:
                if not isinstance(prior, Mapping):
                    raise TypeError(
                        "evidence window listing contains a non-record item"
                    )
                parsed_prior = RollingEvidence.from_mapping(prior)
                if (
                    parsed_prior.evidence_window_id == window_id
                    or parsed_prior.evaluation_run_id == evaluation_run_id
                ):
                    continue
                prior_evidence.append(parsed_prior)
            latest = _latest_windows(prior_evidence)
        except Exception as exc:
            raise AutonomousResearchError(
                "PREDECESSOR_LOOKUP_UNAVAILABLE",
                str(exc) or type(exc).__name__,
            ) from exc

        active_prior = (
            latest.get(str(strategy.get("strategy_version_id")), {})
            .get(requested_source, {})
            .get(days)
        )
        if active_prior is not None:
            supersedes = active_prior.evidence_window_id

        unavailable_reason = (
            evaluation_map.get("evaluator_error")
            or canonical_evaluation.get("evaluator_error")
            or evaluation_map.get("evaluator_prerequisite")
            or canonical_evaluation.get("evaluator_prerequisite")
            or (
                canonical_accounting.get("accounting_unavailable_reason")
                if isinstance(canonical_accounting, Mapping)
                else None
            )
            or (
                "EVALUATOR_COUNT_METRIC_INVALID"
                if count_error is not None
                else None
            )
        )
        valid_input_default = len(valid_times)
        if actual_ledger:
            valid_input_default = sum(
                1
                for row in rows
                if isinstance(row, Mapping)
                and not row.get("_rolling_source_rejection")
                and not row.get("_rolling_accounting_rejection")
                and _rolling_row_time(_rolling_snapshot_view(row)) is not None
            )
        valid_input_rows = evaluation_map.get("valid_input_rows", valid_input_default)
        try:
            valid_input_rows = _rolling_strict_count(
                valid_input_rows,
                "valid_input_rows",
                default=valid_input_default,
            )

        except ValueError:
            count_error = count_error or "valid_input_rows"
            valid_input_rows = 0
        declined_evaluations = count_value(
            canonical_evaluation.get("declined_evaluations", 0),
            "declined_evaluations",
        )
        positions = (
            collection_count(
                canonical_accounting.get("open_positions", ()),
                "positions",
            )
            if isinstance(canonical_accounting, Mapping)
            else 0
        )
        openings = (
            collection_count(
                canonical_accounting.get("opening_fills", 0),
                "openings",
            )
            if isinstance(canonical_accounting, Mapping)
            else 0
        )
        if actual_ledger and partial_accounting and unavailable_reason is None:
            unavailable_reason = next(
                (
                    str(row.get("_rolling_accounting_rejection"))
                    for row in rows
                    if isinstance(row, Mapping)
                    and row.get("_rolling_accounting_rejection")
                ),
                None,
            )
        if count_error is not None:
            partial_accounting = True
        if partial_accounting and unavailable_reason is None:
            unavailable_reason = (
                "EVALUATOR_COUNT_METRIC_INVALID"
                if count_error is not None
                else "ACCOUNTING_FIELDS_INCOMPLETE"
            )
        top_level_realized = realized_pnl if not partial_accounting else None
        top_level_unrealized = unrealized_pnl if not partial_accounting else None
        # Accounting result fields are deliberately projected only when the
        # immutable accounting path is complete.  Stage counts remain useful
        # evidence even when monetary values are unavailable.
        if operational_evidence:
            if isinstance(canonical_accounting, Mapping):
                raw_positions = canonical_accounting.get("open_positions", ())
                if (
                    "remaining_positions" not in operational_evidence
                    and isinstance(raw_positions, (list, tuple, set, frozenset))
                ):
                    operational_evidence["remaining_positions"] = len(raw_positions)
                    operational_evidence["remaining_position_ids"] = sorted(
                        str(value) for value in raw_positions if str(value).strip()
                    )
            if partial_accounting:
                for name in (
                    "gross_result",
                    "realized_result",
                    "unrealized_result",
                    "net_result",
                ):
                    operational_evidence[name] = None
                operational_evidence["economic_result_available"] = False
                operational_evidence["negative_economics"] = None
            else:
                gross_result = net_return + fees + costs
                operational_evidence.update(
                    {
                        "gross_result": gross_result,
                        "realized_result": realized_pnl,
                        "unrealized_result": unrealized_pnl,
                        "net_result": net_return,
                        "economic_result_available": True,
                        "negative_economics": net_return < Decimal("0"),
                    }
                )
        evaluation_map["operational_evidence"] = dict(operational_evidence)
        canonical_evaluation["operational_evidence"] = dict(operational_evidence)
        declared_holding = evaluation_map.get(
            "holding_period",
            strategy.get("holding_period"),
        )
        if declared_holding is None:
            document = strategy.get("strategy_document", strategy.get("canonical_strategy"))
            if isinstance(document, Mapping):
                declared_holding = document.get("holding_period")
        try:
            evidence_holding_period = int(declared_holding or 1)
        except (TypeError, ValueError, OverflowError):
            evidence_holding_period = 1
        if isinstance(declared_holding, bool) or evidence_holding_period < 1:
            evidence_holding_period = 1
        evidence_exit_policy = evaluation_map.get("exit_policy", strategy.get("exit_policy"))
        evidence_horizon = evaluation_map.get(
            "observation_horizon",
            strategy.get("observation_horizon"),
        )
        if not isinstance(evidence_horizon, Mapping):
            evidence_horizon = {
                "unit": "observations",
                "count": evidence_holding_period,
                "semantics": "per_market_observation_count",
            }
        observation_gap_seconds = max(
            (
                Decimal(str((later - earlier).total_seconds()))
                for earlier, later in zip(sorted(valid_times), sorted(valid_times)[1:])
            ),
            default=Decimal("0"),
        )
        strategy_provenance = (
            strategy.get("provenance")
            if isinstance(strategy.get("provenance"), Mapping)
            else {}
        )
        draft_id = str(
            strategy.get("draft_id")
            or strategy_provenance.get("draft_id")
            or ""
        ).strip()
        draft_hash = str(
            strategy.get("draft_hash")
            or strategy_provenance.get("draft_hash")
            or ""
        ).strip()
        scope_hash = str(
            strategy.get("scope_hash")
            or strategy.get("market_scope_hash")
            or strategy_provenance.get("scope_hash")
            or ""
        ).strip()
        scope_version = str(
            strategy.get("scope_version")
            or strategy.get("market_scope_version")
            or strategy_provenance.get("scope_version")
            or ""
        ).strip()
        draft_bound = bool(
            strategy.get("draft_bound") is True
            and strategy_provenance.get("draft_bound") is True
            and draft_id
            and draft_hash
            and scope_hash
            and scope_version
        )
        if not draft_bound:
            draft_id = ""
        record = {
            "strategy_version_id": strategy["strategy_version_id"],
            "holding_period": evidence_holding_period,
            "exit_policy": evidence_exit_policy,
            "observation_horizon": dict(evidence_horizon),
            "selection_excluded": bool(
                evaluation_map.get(
                    "selection_excluded",
                    strategy.get("selection_excluded", False),
                )
            ),
            "observation_gap_seconds": str(observation_gap_seconds),
            "candidate_id": candidate_id,
            "research_trial_id": trial_id,
            "evidence_window_id": window_id,
            "evaluation_run_id": evaluation_run_id,
            "evaluation_version": evaluation_version,
            "evaluation_kind": (
                "CANONICAL_SIMULATION" if canonical_required else "ACTUAL_LEDGER"
            ),
            "supersedes_evidence_id": supersedes,
            "available_from": available_from.isoformat(),
            "available_through": available_through.isoformat(),
            "requested_days": days,
            "actual_coverage_seconds": actual_coverage,
            "observation_completeness": str(
                min(
                    Decimal("1"),
                    Decimal(actual_coverage) / Decimal(days * 86400),
                )
            ),
            "source_class": persisted_source,
            "requested_source_class": requested_source,
            "input_manifest": input_manifest,
            "paper_sizing_assumptions": {
                "currency": "USD",
                "allocated_capital": (
                    str(allocated_capital) if not partial_accounting else None
                ),
                "sizing_model": "canonical_accounting",
            },
            "paper_fee_assumptions": {"fee_rate": "0", "fee_bps": "0"},
            "paper_slippage_assumptions": {
                "slippage_rate": "0",
                "slippage_bps": "0",
            },
            "allocated_capital_net_return": (
                str(net_return) if not partial_accounting else None
            ),
            "realized_pnl": (
                str(top_level_realized) if top_level_realized is not None else None
            ),
            "unrealized_pnl": (
                str(top_level_unrealized)
                if top_level_unrealized is not None
                else None
            ),
            "fees": str(fees) if not partial_accounting else None,
            "costs": str(costs) if not partial_accounting else None,
            "slippage": str(costs) if not partial_accounting else None,
            "execution_feasibility": (
                "" if feasibility is None else feasibility
            ),
            "drawdown": str(drawdown if not partial_accounting else Decimal("0")),
            "completed_outcomes": completed if not partial_accounting else 0,
            "reliability": str(reliability if not partial_accounting else Decimal("0")),
            "evidence_digest": "",
            "overlap_key": _rolling_overlap_key(
                [
                    row
                    for row in rows
                    if isinstance(row, Mapping)
                    and not row.get("_rolling_source_rejection")
                    and not row.get("_rolling_accounting_rejection")
                    and _rolling_row_time(_rolling_snapshot_view(row)) is not None
                    and str(
                        _rolling_snapshot_view(row).get("market_id", "")
                    ).strip()
                ]
            ),
            "accounting_complete": bool(not partial_accounting),
            "accounting_partial": bool(partial_accounting),
            "accounting_available": bool(
                canonical_accounting is not None
                and canonical_accounting.get("accounting_available") is True
                and not partial_accounting
            ),
            "admitted": bool(not partial_accounting and completed > 0),
            "admission_reasons": (
                []
                if not partial_accounting and completed > 0
                else ["ACCOUNTING_UNAVAILABLE"]
                if partial_accounting
                else ["MINIMUM_OUTCOMES_UNMET"]
            ),
            "loaded_rows": len(rows),
            "valid_input_rows": int(valid_input_rows or 0),
            "evaluator_invoked": evaluator_invoked,
            "evaluator_completed": evaluator_completed,
            "evaluated_observations": evaluated_observations,
            "signal_count": signal_count,
            "diagnostic_summary_count": diagnostic_count,
            "requested_rows": len(rows),
            "available_rows": int(valid_input_rows or 0),
            # Legacy aliases remain truthful: evaluated_rows is actual evaluator
            # output, never the number of loaded source rows.
            "evaluated_rows": evaluated_observations,
            "signals": signal_count,
            "declined_evaluations": declined_evaluations,
            "positions": positions,
            "open_positions": list(
                canonical_accounting.get("open_positions", ())
            )[:_ROLLING_OPEN_POSITIONS_LIMIT]
            if isinstance(canonical_accounting, Mapping)
            else [],
            "openings": openings,
            "accounting_unavailable_reason": (
                unavailable_reason if partial_accounting else None
            ),
            "evaluator_name": evaluation_map.get(
                "evaluator_name", canonical_evaluation.get("evaluator_name")
            ),
            "evaluator_error": evaluation_map.get(
                "evaluator_error", canonical_evaluation.get("evaluator_error")
            ),
            "evaluator_prerequisite": evaluation_map.get(
                "evaluator_prerequisite",
                canonical_evaluation.get("evaluator_prerequisite"),
            ),
            "source_digest": source_digest,
            "accounting_digest": accounting_digest,
            "portfolio_accounting": dict(canonical_accounting or {}),
            "evaluation": dict(canonical_evaluation),
            "operational_evidence": dict(operational_evidence),
            "metrics": {
                "portfolio_accounting": dict(canonical_accounting or {}),
                "evaluation": dict(canonical_evaluation),
                "operational_evidence": dict(operational_evidence),
            },
            "paper_only": True,
            "rolling_research": True,
            **(
                {
                    "draft_id": draft_id,
                    "draft_hash": draft_hash,
                    "draft_bound": True,
                    "scope_hash": scope_hash,
                    "scope_version": scope_version,
                    "operational_setup_hash": strategy.get("operational_setup_hash"),
                    "market_bindings": list(strategy.get("market_bindings", ())),
                }
                if draft_bound
                else {}
            ),
        }
        source_scope_resolution = next(
            (
                source.get("scope_resolution", source.get("market_scope_resolution"))
                for source in (strategy, strategy_provenance)
                if isinstance(
                    source.get("scope_resolution", source.get("market_scope_resolution")),
                    Mapping,
                )
            ),
            None,
        )
        source_market_bindings = next(
            (
                source.get("market_bindings")
                for source in (strategy, strategy_provenance)
                if isinstance(source.get("market_bindings"), (list, tuple))
            ),
            None,
        )
        if isinstance(source_scope_resolution, Mapping):
            record["scope_resolution"] = dict(source_scope_resolution)
        if isinstance(source_market_bindings, (list, tuple)):
            record["market_bindings"] = [
                dict(binding) if isinstance(binding, Mapping) else binding
                for binding in source_market_bindings
            ]
        if strategy_provenance:
            record["provenance"] = dict(strategy_provenance)
        if operational_evidence:
            record["operational_evidence"] = dict(operational_evidence)
            # Direct aliases are compatibility projections only.  Never let a
            # stage metric overwrite a canonical legacy/evaluation field such
            # as ``completed_outcomes``.
            for name, value in operational_evidence.items():
                if name not in record:
                    record[name] = value
        if operational_identity:
            record["operational_identity"] = dict(operational_identity)
            for name, value in operational_identity.items():
                if name not in record:
                    record[name] = value
            # Evidence describes the operational run; only the existing
            # admission policy may promote or allocate it.
            record["admitted"] = False
            record["admission_reasons"] = ["OPERATIONAL_EVIDENCE_NOT_ADMISSION"]
        if operational_evidence:
            for source_name, output_name in (
                ("gross_result", "gross_pnl"),
                ("realized_result", "realized_result"),
                ("unrealized_result", "unrealized_result"),
                ("net_result", "net_pnl"),
            ):
                if source_name in operational_evidence and output_name not in record:
                    record[output_name] = operational_evidence[source_name]
        record["evidence_digest"] = RollingEvidence.from_mapping(record).evidence_digest
        return record

    def _ensure_exploratory_live_bootstrap(self, now: datetime) -> Mapping[str, Any]:
        """Persist the disarmed paper operating policy exactly once.

        This is an application-owned control record, not an execution
        authorization.  It gives the rolling scheduler a stable versioned
        policy/scope provenance while leaving account, venue, limits, and
        order transport untouched.
        """
        policy_config_key = "rolling_exploratory_operating_policy"
        scope_policy = {
            "schema_version": "1",
            "mode": "RULE_BASED_MARKETS",
            "instrument": "POLYMARKET",
            "market_ids": [],
            "filters": {},
            "provenance": "public-current-market",
            "bounded_pool_cap": _EXPLORATORY_POOL_CAP,
        }
        desired = {
            **dict(EXPLORATORY_LIVE_POLICY),
            "scope": scope_policy,
            "paper_only": True,
            "allocation_active": False,
            "canary_armed": False,
            "created_by": "autonomous-rolling-scheduler",
            "updated_at": ensure_utc(now).isoformat(),
        }
        desired["config_hash"] = _content_hash(
            {
                key: value
                for key, value in desired.items()
                if key not in {"updated_at", "config_hash"}
            }
        )
        loader = getattr(self.store, "get_operator_config", None)
        setter = getattr(self.store, "set_operator_config", None)
        existing = None
        if callable(loader):
            try:
                existing = loader(policy_config_key, None)
            except (TypeError, ValueError, RuntimeError):
                existing = None
        if not isinstance(existing, Mapping) and callable(setter):
            try:
                setter(policy_config_key, desired)
                existing = desired
            except (TypeError, ValueError, RuntimeError):
                existing = None
        return {
            "status": "PERSISTED" if isinstance(existing, Mapping) else "DEFERRED",
            "policy_id": EXPLORATORY_LIVE_POLICY.get("policy_id"),
            "policy_version": EXPLORATORY_LIVE_POLICY.get("version"),
            "config_hash": (
                existing.get("config_hash")
                if isinstance(existing, Mapping)
                else desired["config_hash"]
            ),
            "scope": dict(scope_policy),
            "paper_only": True,
            "allocation_active": False,
            "canary_armed": False,
        }

    def refresh_rolling_evidence(
        self,
        now: datetime | None = None,
        *,
        skip_observation_setup_migration: bool = False,
    ) -> Mapping[str, Any]:
        current = ensure_utc(now or self.clock())
        config_loader = getattr(self.store, "get_operator_config", None)
        preexisting_operating = None
        if callable(config_loader):
            try:
                preexisting_operating = config_loader(
                    "rolling_exploratory_operating_policy",
                    None,
                )
            except (TypeError, ValueError, RuntimeError):
                preexisting_operating = None
        try:
            bootstrap_required = (
                callable(config_loader)
                and config_loader("rolling_exploratory_bootstrap_required", False) is True
            )
        except (TypeError, ValueError, RuntimeError):
            bootstrap_required = True
        bootstrap = self._ensure_exploratory_live_bootstrap(current)
        try:
            policy = self._rolling_policy()
        except (TypeError, ValueError, KeyError):
            policy = default_rolling_admission_policy()
        if bootstrap_required:
            blocker = self._rolling_bootstrap_blocker(policy)
            if blocker is not None:
                return {
                    "status": "BLOCKED",
                    "blocker": blocker,
                    "bootstrap": dict(bootstrap),
                    "paper_only": True,
                    "live_execution": False,
                    "queue_item_id": None,
                    "pending": [],
                    "pending_total": 0,
                    "evidence_windows": [],
                    "evidence_windows_total": 0,
                    "observations": [],
                    "observations_total": 0,
                }
        migrated_observations = (
            ()
            if skip_observation_setup_migration
            else self._migrate_observation_setup_intents(current)
        )
        operating_policy = None
        if callable(config_loader):
            try:
                operating_policy = config_loader(
                    "rolling_exploratory_operating_policy",
                    None,
                )
            except (TypeError, ValueError, RuntimeError):
                operating_policy = None
        system_bootstrap_authority = False
        operating_candidate = (
            preexisting_operating
            if isinstance(preexisting_operating, Mapping)
            else None
        )
        if (
            isinstance(operating_candidate, Mapping)
            and str(operating_candidate.get("mode", "")).strip().upper()
            == "EXPLORATORY_LIVE"
        ):
            marker = False
            try:
                marker = callable(config_loader) and (
                    config_loader("rolling_exploratory_bootstrap_required", False)
                    is True
                )
                if not marker:
                    if (
                        str(operating_candidate.get("created_by", "")).strip()
                        != "autonomous-rolling-scheduler"
                    ):
                        raise RollingPolicyBootstrapError(
                            "ROLLING_POLICY_BOOTSTRAP_REQUIRED"
                        )
                else:
                    active = config_loader("rolling_admission_policy_active", None)
                    validate_system_exploratory_admission_policy(
                        active if isinstance(active, Mapping) else None,
                        operating_candidate,
                        self._rolling_risk_binding(policy),
                    )
                    system_bootstrap_authority = True
            except (RollingPolicyBootstrapError, TypeError, ValueError, RuntimeError) as exc:
                blocker = (
                    exc.code
                    if isinstance(exc, RollingPolicyBootstrapError)
                    else "ROLLING_POLICY_BOOTSTRAP_DRIFT"
                )
                return {
                    "status": "BLOCKED",
                    "blocker": blocker,
                    "bootstrap": dict(bootstrap),
                    "paper_only": True,
                    "live_execution": False,
                    "queue_item_id": None,
                    "pending": [],
                    "pending_total": 0,
                    "evidence_windows": [],
                    "evidence_windows_total": 0,
                    "observations": [],
                    "observations_total": 0,
                }
        system_bootstrap_active = system_bootstrap_authority
        draft_for_discovery = self._rolling_scope_draft()
        self._rolling_last_current_discovery = {"status": "NOT_RUN"}
        if callable(self.current_market_discoverer) and (
            system_bootstrap_active or draft_for_discovery is not None
        ):
            try:
                should_discover = True
                if system_bootstrap_active and draft_for_discovery is None:
                    selection_loader = getattr(
                        self.store,
                        "load_current_portfolio_selection",
                        None,
                    )
                    selection = (
                        selection_loader()
                        if callable(selection_loader)
                        else None
                    )
                    selected_members = (
                        selection.get("members", ())
                        if isinstance(selection, Mapping)
                        else ()
                    )
                    should_discover = isinstance(selected_members, (list, tuple)) and not selected_members
                if should_discover:
                    try:
                        parameters = inspect.signature(
                            self.current_market_discoverer
                        ).parameters
                    except (TypeError, ValueError):
                        parameters = {}
                    accepts_draft = (
                        "draft" in parameters
                        or any(
                            parameter.kind is inspect.Parameter.VAR_KEYWORD
                            for parameter in parameters.values()
                        )
                    )
                    if draft_for_discovery is not None and accepts_draft:
                        discovery_result = self.current_market_discoverer(
                            current,
                            draft=draft_for_discovery,
                        )
                    else:
                        discovery_result = self.current_market_discoverer(current)
                    as_record = getattr(discovery_result, "as_record", None)
                    recorded = as_record() if callable(as_record) else discovery_result
                    if isinstance(recorded, Mapping):
                        provider_failure = (
                            int(recorded.get("provider_failures", 0) or 0) > 0
                            or int(recorded.get("provider_timeouts", 0) or 0) > 0
                        )
                        result_error = (
                            int(recorded.get("errors", 0) or 0) > 0
                            or str(
                                recorded.get("discovery_coverage_status", "")
                            ).upper()
                            == "ERROR"
                        )
                        self._rolling_last_current_discovery = {
                            "status": (
                                "PROVIDER_FAILURE"
                                if provider_failure
                                else ("RESULT_ERROR" if result_error else "OK")
                            ),
                            "cycle": dict(recorded),
                        }
                    else:
                        self._rolling_last_current_discovery = {
                            "status": "NO_RESULT",
                            "result_type": type(discovery_result).__name__,
                        }
            except (AttributeError, TypeError, ValueError, RuntimeError, HTTPFetchError) as exc:
                known_provider_failure = (
                    isinstance(exc, HTTPFetchError)
                    or getattr(exc, "deadline_expired", False) is True
                )
                self._rolling_last_current_discovery = {
                    "status": (
                        "PROVIDER_FAILURE"
                        if known_provider_failure
                        else "APPLICATION_ERROR"
                    ),
                    "error_type": type(exc).__name__,
                    "error": str(exc)[:512],
                }
        draft_documents, draft_trace = self._rolling_scope_draft_documents(current)
        draft_preview_active = str(draft_trace.get("status", "")).upper() != "UNAVAILABLE"
        system_documents = (
            self._rolling_system_current_market_documents(current)
            if not draft_preview_active
            else ()
        )
        documents = (
            draft_documents
            if draft_preview_active
            else (
                system_documents
                if system_bootstrap_active
                else self._rolling_strategy_documents()
            )
        )
        strategies = self._rolling_persist_strategy_lineage(documents, current)
        sources = ("HISTORICAL", "REPLAY", "PAPER", "LIVE")
        queue_payload = _rolling_hermes_payload(strategies, sources, current)
        queue_identity = dict(queue_payload)
        queue_identity.pop("available_at", None)
        queue_item = self.bus.submit_review_request(
            queue_payload,
            dedupe_key="rolling-research:" + _rolling_hash(queue_identity),
            available_at=current,
        )
        evidence_rows: list[dict[str, Any]] = []
        pending: list[dict[str, Any]] = []
        pending_total = 0
        saver = getattr(self.store, "save_strategy_evidence_window", None)
        cursor_loader = getattr(self.store, "load_rolling_evidence_cursor", None)
        cursor_saver = getattr(self.store, "save_rolling_evidence_cursor", None)
        blocker_loader = getattr(self.store, "load_rolling_evidence_blocker", None)
        blocker_saver = getattr(self.store, "save_rolling_evidence_blocker", None)
        cursor = cursor_loader() if callable(cursor_loader) else None
        source_cache: dict[str, list[dict[str, Any]]] = {}
        source_cache_errors: dict[str, tuple[str, str, str]] = {}
        total_rows = 0
        attempted = 0
        work_items = _rolling_work_items(strategies)
        start_index = _rolling_cursor_index(cursor, work_items)

        def add_pending(item: Mapping[str, Any]) -> None:
            nonlocal pending_total
            pending_total += 1
            if len(pending) < _MAX_ROLLING_QUEUE_RESULTS:
                entry = dict(item)
                entry.setdefault("next_job", "rolling-research-evidence")
                pending.append(entry)

        def work_payload(
            strategy: Mapping[str, Any],
            days: int,
            source: str,
            *,
            status: str,
            reason: str,
            **extra: Any,
        ) -> dict[str, Any]:
            return {
                "strategy_version_id": strategy.get("strategy_version_id"),
                "research_trial_id": strategy.get("research_trial_id"),
                "candidate_id": strategy.get("candidate_id"),
                "source_class": source,
                "requested_days": days,
                "status": status,
                "reason": reason,
                **extra,
            }

        transient_blockers = {
            "SOURCE_LOAD_FAILED",
            "EVIDENCE_PERSISTENCE_UNAVAILABLE",
            "EVIDENCE_PERSISTENCE_FAILED",
            "INSUFFICIENT_EVIDENCE",
            "HISTORICAL_DATASET_EMPTY",
            "PREDECESSOR_LOOKUP_UNAVAILABLE",
            "NO_SUITABLE_MATERIALIZED_INSTANCE",
        }
        def is_terminal_blocker(record: Mapping[str, Any]) -> bool:
            reason = str(record.get("blocker") or "")
            payload = record.get("payload")
            payload = payload if isinstance(payload, Mapping) else {}
            non_retryable = bool(
                record.get("non_retryable") or payload.get("non_retryable")
            )
            terminal = bool(record.get("terminal") or payload.get("terminal"))
            if non_retryable or _rolling_reason_is_immutable(reason):
                return True
            return terminal and reason not in transient_blockers

        def persist_blocker(
            strategy: Mapping[str, Any],
            days: int,
            source: str,
            fingerprint: str,
            reason: str,
            detail: str = "",
        ) -> None:
            # A blocker without source/prerequisite material must not become
            # durable state; doing so would suppress a later corrected retry.
            if not str(fingerprint or "").strip():
                return
            immutable = _rolling_reason_is_immutable(reason)
            retryable = not immutable
            if callable(blocker_saver):
                try:
                    blocker_saver(
                        {
                            "work_key": _rolling_work_key(strategy, days, source),
                            "strategy_version_id": strategy.get("strategy_version_id"),
                            "research_trial_id": strategy.get("research_trial_id"),
                            "candidate_id": strategy.get("candidate_id"),
                            "requested_days": days,
                            "source_class": source,
                            "prerequisite_fingerprint": fingerprint,
                            "blocker": reason,
                            "detail": detail,
                            "last_attempted_at": current.isoformat(),
                            "retryable": retryable,
                            "non_retryable": immutable,
                            "terminal": immutable,
                            "next_attempt_at": (
                                (current + timedelta(minutes=5)).isoformat()
                                if retryable
                                else None
                            ),
                            "payload": {
                                "strategy_hash": strategy.get("strategy_hash"),
                                "dataset_id": strategy.get("dataset_id"),
                                "dataset_version": strategy.get("dataset_version"),
                                "retryable": retryable,
                                "non_retryable": immutable,
                                "terminal": immutable,
                                "next_attempt_at": (
                                    (current + timedelta(minutes=5)).isoformat()
                                    if retryable
                                    else None
                                ),
                            },
                        }
                    )
                except (TypeError, ValueError, RuntimeError):
                    pass

        def blocked(
            strategy: Mapping[str, Any],
            days: int,
            source: str,
            fingerprint: str,
        ) -> Mapping[str, Any] | None:
            if not callable(blocker_loader):
                return None
            try:
                record = blocker_loader(
                    work_key=_rolling_work_key(strategy, days, source),
                    prerequisite_fingerprint=fingerprint,
                )
            except (TypeError, ValueError, RuntimeError):
                return None
            if not isinstance(record, Mapping):
                return None
            if is_terminal_blocker(record):
                return record
            next_attempt = _rolling_timestamp(record.get("next_attempt_at"))
            if next_attempt is None:
                payload = record.get("payload")
                if isinstance(payload, Mapping):
                    next_attempt = _rolling_timestamp(payload.get("next_attempt_at"))
            if next_attempt is not None and next_attempt > current:
                return record
            return None


        for offset in range(len(work_items)):
            if total_rows >= _MAX_ROLLING_TOTAL_ROWS and attempted:
                break
            index = (start_index + offset) % len(work_items) if work_items else 0
            if not work_items:
                break
            strategy, days, source = work_items[index]
            attempted += 1
            source_payload = dict(strategy)
            source_payload["payload"] = {
                **dict(strategy.get("provenance") or {}),
                "strategy_document": strategy.get("strategy_document"),
            }
            work_key = _rolling_work_key(strategy, days, source)
            try:
                pre_fingerprint = _rolling_prerequisite_fingerprint(
                    strategy,
                    source,
                    store=self.store,
                )
            except (TypeError, ValueError, RuntimeError):
                pre_fingerprint = _rolling_hash(
                    {
                        "strategy_version_id": strategy.get("strategy_version_id"),
                        "research_trial_id": strategy.get("research_trial_id"),
                        "candidate_id": strategy.get("candidate_id"),
                        "source_class": source,
                    }
                )
            # Source-free fingerprints are not sufficient to suppress a row
            # blocker: corrected source/prerequisite state must be loaded and
            # retried before an immutable decision can be reused.
            try:
                binding = _rolling_source_binding(source_payload)
                cache_key = _rolling_hash(
                    {
                        "source_class": source,
                        "dataset_selector": binding,
                        "strategy_hash": strategy.get("strategy_hash"),
                    }
                )
            except (TypeError, ValueError) as exc:
                reason = _rolling_source_exception_reason(exc)
                if reason == "SOURCE_LOAD_FAILED":
                    reason = "SOURCE_SELECTOR_INVALID"
                immutable = _rolling_reason_is_immutable(reason)
                fingerprint = _rolling_hash({"pre": pre_fingerprint, "reason": reason})
                persist_blocker(strategy, days, source, fingerprint, reason, str(exc))
                add_pending(
                    work_payload(
                        strategy,
                        days,
                        status="BLOCKED",
                        reason=reason,
                        terminal=immutable,
                        retryable=not immutable,
                        next_attempt_at=(
                            None
                            if immutable
                            else (current + timedelta(minutes=5)).isoformat()
                        ),
                    )
                )
                cache_key = ""
                rows = None
            else:
                if cache_key in source_cache_errors:
                    reason, error, fingerprint = source_cache_errors[cache_key]
                    immutable = _rolling_reason_is_immutable(reason)
                    # This is an in-memory duplicate from the current tick;
                    # its preflight fingerprint remains attached for durable
                    # retry and blocker correlation.
                    add_pending(
                        work_payload(
                            strategy,
                            days,
                            source,
                            status="BLOCKED",
                            reason=reason,
                            error=error,
                            blocker_fingerprint=fingerprint,
                            terminal=immutable,
                            retryable=not immutable,
                            next_attempt_at=(
                                None
                                if immutable
                                else (current + timedelta(minutes=5)).isoformat()
                            ),
                        )
                    )
                    rows = None
                elif cache_key not in source_cache:
                    try:
                        if source == "PAPER":
                            current_bindings = self._rolling_current_market_bindings(
                                strategy,
                                current,
                            )
                            binding_result = self._ensure_rolling_paper_observation(
                                strategy,
                                current,
                                market_ids=tuple(
                                    item["market_id"]
                                    for item in current_bindings
                                    if isinstance(item, Mapping)
                                    and str(item.get("market_id", "")).strip()
                                ),
                            )
                            if (
                                isinstance(binding_result, Mapping)
                                and binding_result.get("status")
                                == "WAITING_FOR_DIRECT_CURRENT_MARKET"
                            ):
                                source_cache[cache_key] = []
                                add_pending(
                                    work_payload(
                                        strategy,
                                        days,
                                        source,
                                        status="BLOCKED",
                                        reason="WAITING_FOR_DIRECT_CURRENT_MARKET",
                                        next_attempt_at=(
                                            current + timedelta(minutes=5)
                                        ).isoformat(),
                                    )
                                )
                                rows = []
                            else:
                                source_cache[cache_key] = self._rolling_source_rows(
                                    source_payload, source, current
                                )
                        else:
                            source_cache[cache_key] = self._rolling_source_rows(
                                source_payload, source, current
                            )
                    except Exception as exc:
                        error = f"{type(exc).__name__}: {str(exc)[:256]}"
                        reason = _rolling_source_exception_reason(exc)
                        immutable = _rolling_reason_is_immutable(reason)
                        # A preflight fingerprint still authenticates the
                        # immutable request and source binding when no rows
                        # can be loaded.  Include the normalized error so a
                        # corrected prerequisite receives a new blocker key.
                        fingerprint = _rolling_hash(
                            {
                                "pre": pre_fingerprint,
                                "reason": reason,
                                "error": str(exc)[:256],
                            }
                        )
                        persist_blocker(
                            strategy,
                            days,
                            source,
                            fingerprint,
                            reason,
                            error,
                        )
                        source_cache_errors[cache_key] = (reason, error, fingerprint)
                        add_pending(
                            work_payload(
                                strategy,
                                days,
                                source,
                                status="BLOCKED",
                                reason=reason,
                                error=error,
                                blocker_fingerprint=fingerprint,
                                terminal=immutable,
                                retryable=not immutable,
                                next_attempt_at=(
                                    None
                                    if immutable
                                    else (current + timedelta(minutes=5)).isoformat()
                                ),
                            )
                        )
                        rows = None
                    else:
                        rows = source_cache[cache_key]
                else:
                    rows = source_cache[cache_key]
            if rows is not None:
                window_rows, timestamp_rejections = _rolling_window_rows(
                    rows,
                    days,
                    current,
                )
                remaining = max(0, _MAX_ROLLING_TOTAL_ROWS - total_rows)
                bounded_rows = list(window_rows[:remaining]) if remaining else []
                total_rows += len(bounded_rows)
                for timestamp_reason in timestamp_rejections:
                    add_pending(
                        work_payload(
                            strategy,
                            days,
                            source,
                            status="PARTIAL" if bounded_rows else "DEFERRED",
                            reason=timestamp_reason,
                            rejected_rows=True,
                            next_attempt_at=(current + timedelta(minutes=5)).isoformat(),
                        )
                    )
                try:
                    fingerprint = _rolling_prerequisite_fingerprint(
                        strategy,
                        source,
                        source_rows=rows,
                        store=self.store,
                    )
                except (TypeError, ValueError, RuntimeError):
                    fingerprint = ""
                prior_blocker = (
                    blocked(strategy, days, source, fingerprint)
                    if fingerprint
                    else None
                )
                if prior_blocker is not None:
                    prior_terminal = is_terminal_blocker(prior_blocker)
                    add_pending(
                        work_payload(
                            strategy,
                            days,
                            source,
                            status="BLOCKED",
                            reason=str(prior_blocker.get("blocker") or "BLOCKED"),
                            blocker_fingerprint=fingerprint,
                            terminal=prior_terminal,
                            retryable=not prior_terminal,
                            next_attempt_at=prior_blocker.get("next_attempt_at"),
                        )
                    )
                else:
                    rejection_reasons = sorted(
                        {
                            str(row.get("_rolling_accounting_rejection"))
                            for row in bounded_rows
                            if isinstance(row, Mapping)
                            and row.get("_rolling_accounting_rejection")
                        }
                    )
                    replay_book_blocked = (
                        source == "REPLAY"
                        and any(
                            isinstance(row, Mapping)
                            and not _rolling_replay_row_terminal(row)
                            and not _rolling_has_paired_timestamped_books(row)
                            for row in bounded_rows
                        )
                    )
                    capture_source = any(
                        isinstance(row, Mapping)
                        and row.get("paper_observation_capture") is True
                        for row in bounded_rows
                    )
                    evaluation = (
                        self._rolling_capture_decline_evaluation(strategy, bounded_rows)
                        if capture_source
                        else (
                            None
                            if replay_book_blocked
                            else self._rolling_canonical_evaluation(
                                strategy, bounded_rows, source
                            )
                        )
                    )
                    recorded_book = any(
                        isinstance(_rolling_snapshot_view(row).get(name), Mapping)
                        for row in bounded_rows
                        if isinstance(row, Mapping)
                        for name in ("order_book", "yes_order_book", "no_order_book")
                    )
                    canonical_required = (
                        not capture_source
                        and (
                            source in {"HISTORICAL", "REPLAY"}
                            or (source == "LIVE" and recorded_book)
                        )
                    )
                    canonical_reason: str | None = None
                    if canonical_required:
                        if replay_book_blocked:
                            canonical_reason = "REPLAY_BOOK_REQUIRED"
                        elif not isinstance(evaluation, Mapping):
                            canonical_reason = "CANONICAL_EVALUATION_UNAVAILABLE"
                        else:
                            evaluation_kind = evaluation.get("evaluation_kind")
                            evaluation_invoked = evaluation.get("evaluator_invoked")
                            evaluation_completed = evaluation.get("evaluator_completed")
                            accounting = evaluation.get("portfolio_accounting")
                            accounting_available = (
                                accounting.get("accounting_available")
                                if isinstance(accounting, Mapping)
                                else evaluation.get("accounting_available")
                            )
                            if evaluation_kind != "CANONICAL_SIMULATION":
                                canonical_reason = "EVALUATION_KIND_INVALID"
                            elif evaluation_invoked is not True:
                                canonical_reason = str(
                                    evaluation.get("evaluator_error")
                                    or evaluation.get("evaluator_prerequisite")
                                    or "EVALUATOR_INVOCATION_REQUIRED"
                                )
                            elif evaluation_completed is not True:
                                canonical_reason = str(
                                    evaluation.get("evaluator_error")
                                    or evaluation.get("evaluator_prerequisite")
                                    or "CANONICAL_EVALUATION_UNAVAILABLE"
                                )
                            elif accounting_available is not True:
                                canonical_reason = str(
                                    evaluation.get("evaluator_error")
                                    or evaluation.get("evaluator_prerequisite")
                                    or "ACCOUNTING_UNAVAILABLE"
                                )
                        if canonical_reason:
                            persist_blocker(
                                strategy,
                                days,
                                source,
                                fingerprint,
                                canonical_reason,
                            )
                            add_pending(
                                work_payload(
                                    strategy,
                                    days,
                                    source,
                                    status=(
                                        "BLOCKED"
                                        if _rolling_reason_is_immutable(canonical_reason)
                                        else "PARTIAL"
                                    ),
                                    reason=canonical_reason,
                                    blocker_fingerprint=fingerprint,
                                    terminal=_rolling_reason_is_immutable(canonical_reason),
                                    retryable=not _rolling_reason_is_immutable(canonical_reason),
                                    next_attempt_at=(
                                        None
                                        if _rolling_reason_is_immutable(canonical_reason)
                                        else (current + timedelta(minutes=5)).isoformat()
                                    ),
                                )
                            )
                    predecessor_lookup_error: AutonomousResearchError | None = None
                    try:
                        evidence = self._rolling_evidence_record(
                            strategy,
                            bounded_rows,
                            source,
                            days,
                            current,
                            evaluation=evaluation,
                        )
                    except AutonomousResearchError as exc:
                        if exc.reason != "PREDECESSOR_LOOKUP_UNAVAILABLE":
                            raise
                        predecessor_lookup_error = exc
                        evidence = None
                        persist_blocker(
                            strategy,
                            days,
                            source,
                            fingerprint,
                            exc.reason,
                            exc.detail,
                        )

                    rejection_reasons_set = {
                        str(row.get("_rolling_accounting_rejection"))
                        for row in bounded_rows
                        if isinstance(row, Mapping)
                        and row.get("_rolling_accounting_rejection")
                    }
                    if (
                        source == "PAPER"
                        and isinstance(evidence, Mapping)
                        and evidence.get("accounting_unavailable_reason")
                        == _ROLLING_OPEN_POSITIONS_LIMIT_REASON
                    ):
                        rejection_reasons_set.add(_ROLLING_OPEN_POSITIONS_LIMIT_REASON)
                    rejection_reasons = sorted(rejection_reasons_set)
                    for rejection in rejection_reasons:
                        rejection_immutable = _rolling_reason_is_immutable(rejection)
                        # Persist before attempting the evidence save.  A row
                        # can be rejected without yielding an evidence record,
                        # and the exact reason must still reach operator state.
                        persist_blocker(
                            strategy,
                            days,
                            source,
                            fingerprint,
                            rejection,
                        )
                        add_pending(
                            work_payload(
                                strategy,
                                days,
                                source,
                                status="PARTIAL" if evidence is not None else "BLOCKED",
                                reason=rejection,
                                blocker_fingerprint=fingerprint,
                                terminal=rejection_immutable,
                                retryable=not rejection_immutable,
                                next_attempt_at=(
                                    None
                                    if rejection_immutable
                                    else (current + timedelta(minutes=5)).isoformat()
                                ),
                            )
                        )
                    if evidence is None:
                        reason = (
                            predecessor_lookup_error.reason
                            if predecessor_lookup_error is not None
                            else canonical_reason
                            or (
                                "HISTORICAL_DATASET_EMPTY"
                                if not bounded_rows and source == "HISTORICAL"
                                else "INSUFFICIENT_EVIDENCE"
                            )
                        )
                        add_pending(
                            work_payload(
                                strategy,
                                days,
                                source,
                                status=(
                                    "BLOCKED"
                                    if predecessor_lookup_error is not None
                                    else "DEFERRED"
                                ),
                                reason=reason,
                                error=(
                                    predecessor_lookup_error.detail
                                    if predecessor_lookup_error is not None
                                    else None
                                ),
                                blocker_fingerprint=fingerprint,
                                terminal=False,
                                retryable=True,
                                next_attempt_at=(
                                    current + timedelta(minutes=5)
                                ).isoformat(),
                            )
                        )
                    elif not callable(saver):
                        persist_blocker(
                            strategy,
                            days,
                            source,
                            fingerprint,
                            "EVIDENCE_PERSISTENCE_UNAVAILABLE",
                        )
                        add_pending(
                            work_payload(
                                strategy,
                                days,
                                source,
                                status="BLOCKED",
                                reason="EVIDENCE_PERSISTENCE_UNAVAILABLE",
                                blocker_fingerprint=fingerprint,
                                terminal=False,
                                retryable=True,
                                next_attempt_at=(current + timedelta(minutes=5)).isoformat(),
                            )
                        )
                    else:
                        try:
                            saver(evidence)
                        except (TypeError, ValueError, RuntimeError) as exc:
                            reason = "EVIDENCE_PERSISTENCE_FAILED"
                            persist_blocker(
                                strategy, days, source, fingerprint, reason, str(exc)
                            )
                            add_pending(
                                work_payload(
                                    strategy,
                                    days,
                                    source,
                                    status="BLOCKED",
                                    reason=reason,
                                    error=str(exc)[:256],
                                    blocker_fingerprint=fingerprint,
                                    terminal=False,
                                    retryable=True,
                                    next_attempt_at=(
                                        current + timedelta(minutes=5)
                                    ).isoformat(),
                                )
                            )
                        else:
                            evidence_rows.append(evidence)
            next_item = work_items[(index + 1) % len(work_items)]
            cursor_record = _rolling_cursor_record(cursor, (strategy, days, source), next_item, current)
            cursor = cursor_record
            if callable(cursor_saver):
                try:
                    cursor_saver(cursor_record)
                except (TypeError, ValueError, RuntimeError):
                    pass
        if not strategies:
            proposal_items: tuple[Any, ...] = ()
            proposal_error: str | None = None
            try:
                proposal_items = tuple(self._enqueue_predeclared_from_persisted_scope(current) or ())
            except (AutonomousResearchError, ResearchBusPermissionError, TypeError, ValueError, RuntimeError) as exc:
                proposal_error = f"{type(exc).__name__}: {str(exc)[:256]}"
            if proposal_error is not None:
                fallback_reason = "PROPOSAL_PATH_FAILED"
            elif draft_preview_active:
                fallback_reason = str(
                    draft_trace.get("reason") or "NO_SUITABLE_MATERIALIZED_INSTANCE"
                )
            elif proposal_items:
                fallback_reason = "STRATEGY_DEFINITIONS_QUEUED"
            else:
                fallback_reason = "NO_STRATEGY_DEFINITIONS"
            fallback = {
                "strategy_version_id": None,
                "source_class": "ALL",
                "requested_days": [7, 30],
                "status": "SCHEDULED" if proposal_error is None else "ERROR",
                "reason": fallback_reason,
                "next_job": "predeclared_starting_set",
                "proposal_queue_item_ids": [
                    str(item.item_id)
                    for item in proposal_items
                    if getattr(item, "item_id", None)
                ],
            }
            if proposal_error is not None:
                fallback["error"] = proposal_error
            add_pending(fallback)
        # Review identity must describe the complete current discovery set.  Do
        # not query append-only ACCEPTED enrollments here: superseded versions
        # are historical lineage, not members of this refresh's strategy set.
        enrolled_strategy_version_ids = tuple(
            sorted(
                {
                    str(item.get("strategy_version_id", "")).strip()
                    for item in documents
                    if isinstance(item, Mapping)
                    and str(item.get("strategy_version_id", "")).strip()
                }
            )
        )
        state = _rolling_state_payload(
            status="SCHEDULED",
            scheduled_at=current.isoformat(),
            queue_item_id=queue_item.item_id,
            queue_status=queue_item.status.value,
            strategies=strategies,
            evidence_rows=evidence_rows,
            pending=pending,
            source_classes=sources,
            requested_window_days=(7, 30),
            source_rows_total=total_rows,
            pending_total=pending_total,
            enrolled_strategy_version_ids=enrolled_strategy_version_ids,
        )
        state["scope_draft_trace"] = dict(draft_trace)
        draft_strategy_ids = {
            str(item.get("strategy_version_id", "")).strip()
            for item in strategies
            if isinstance(item, Mapping)
            and item.get("draft_bound") is True
            and str(item.get("draft_id", "")).strip() == str(
                draft_trace.get("draft_id", "")
            ).strip()
            and str(item.get("draft_hash", "")).strip() == str(
                draft_trace.get("draft_hash", "")
            ).strip()
        }
        evaluator_decisions: list[dict[str, Any]] = []
        for item in evidence_rows:
            if (
                not isinstance(item, Mapping)
                or str(item.get("strategy_version_id", "")).strip()
                not in draft_strategy_ids
            ):
                continue
            metrics = item.get("metrics")
            metrics = metrics if isinstance(metrics, Mapping) else {}
            evaluation = metrics.get("evaluation")
            if not isinstance(evaluation, Mapping):
                continue
            base = {
                "evaluation_run_id": item.get("evaluation_run_id"),
                "strategy_version_id": item.get("strategy_version_id"),
                "evaluation_kind": evaluation.get(
                    "evaluation_kind", item.get("evaluation_kind")
                ),
                "evaluator_invoked": evaluation.get("evaluator_invoked"),
                "evaluator_completed": evaluation.get("evaluator_completed"),
                "source_class": item.get("source_class"),
            }
            explicit = (
                evaluation.get("decision")
                or evaluation.get("reason")
                or evaluation.get("evaluator_error")
                or evaluation.get("evaluator_prerequisite")
            )
            if explicit:
                evaluator_decisions.append({**base, "decision": str(explicit)})
            reason_counts = evaluation.get("reason_counts")
            if isinstance(reason_counts, Mapping):
                for reason, count in sorted(reason_counts.items(), key=lambda pair: str(pair[0])):
                    if str(reason).strip():
                        evaluator_decisions.append(
                            {**base, "decision": str(reason), "count": count}
                        )
            if not explicit and not isinstance(reason_counts, Mapping):
                evaluator_decisions.append(base)
        def trace_compatible_bindings(
            strategy: Mapping[str, Any],
        ) -> tuple[Mapping[str, Any], ...]:
            raw_bindings = strategy.get("market_bindings")
            if isinstance(raw_bindings, Mapping):
                raw_bindings = (raw_bindings,)
            if not isinstance(raw_bindings, (list, tuple)):
                return ()
            return tuple(
                binding
                for binding in raw_bindings
                if isinstance(binding, Mapping)
                and str(binding.get("market_id", binding.get("id", ""))).strip()
                and str(binding.get("yes_token_id", binding.get("yes_token", ""))).strip()
                and str(binding.get("no_token_id", binding.get("no_token", ""))).strip()
            )

        materialized_strategies = tuple(
            strategy
            for strategy in strategies
            if isinstance(strategy, Mapping)
            and trace_compatible_bindings(strategy)
        )
        materialized_market_ids = list(
            dict.fromkeys(
                str(binding.get("market_id", binding.get("id", ""))).strip()
                for strategy in materialized_strategies
                for binding in trace_compatible_bindings(strategy)
                if str(binding.get("market_id", binding.get("id", ""))).strip()
            )
        )
        compatible_binding_count = sum(
            len(trace_compatible_bindings(strategy))
            for strategy in materialized_strategies
        )
        valid_strategy_definition_count = (
            draft_trace.get("valid_strategy_definition_count")
            if draft_preview_active
            else len(strategies)
        )
        try:
            valid_strategy_definition_count = max(
                0, int(valid_strategy_definition_count or 0)
            )
        except (TypeError, ValueError, OverflowError):
            valid_strategy_definition_count = len(strategies)
        supported_strategy_definition_count = (
            draft_trace.get(
                "supported_strategy_definition_count",
                draft_trace.get("strategy_spec_count", valid_strategy_definition_count),
            )
            if draft_preview_active
            else valid_strategy_definition_count
        )
        try:
            supported_strategy_definition_count = max(
                0, int(supported_strategy_definition_count or 0)
            )
        except (TypeError, ValueError, OverflowError):
            supported_strategy_definition_count = valid_strategy_definition_count
        state["strategy_discovery_trace"] = {
            "source": (
                "scope-draft-preview"
                if draft_preview_active
                else (
                    "system-bootstrap"
                    if system_bootstrap_active
                    else "legacy-enrollment"
                )
            ),
            "discovery": (
                dict(draft_trace.get("discovery"))
                if isinstance(draft_trace.get("discovery"), Mapping)
                else {}
            ),
            "materialization_reason": draft_trace.get("reason"),
            "supported_templates": list(draft_trace.get("supported_templates", ())),
            "materialized_strategy_count": len(materialized_strategies),
            "supported_strategy_definition_count": supported_strategy_definition_count,
            "valid_strategy_definition_count": valid_strategy_definition_count,
            "compatible_binding_count": compatible_binding_count,
            "materialized_member_count": len(materialized_strategies),
            "materialized_market_count": len(materialized_market_ids),
            "materialized_market_ids": materialized_market_ids,
            "evaluator_decisions": evaluator_decisions[: _MAX_ROLLING_QUEUE_RESULTS],
            "paper_only": True,
            "live_execution": False,
        }
        state["rolling_cursor"] = (
            _rolling_bound_cursor_state(cursor)
            if isinstance(cursor, Mapping)
            else {}
        )
        state["requested_work_items"] = len(work_items)
        state["attempted_work_items"] = attempted
        state["last_attempted_tuple"] = {
            key: state["rolling_cursor"].get(key)
            for key in (
                "last_strategy_version_id",
                "last_research_trial_id",
                "last_candidate_id",
                "last_requested_days",
                "last_source_class",
            )
        }
        state["next_durable_work"] = {
            key: state["rolling_cursor"].get(key)
            for key in (
                "next_strategy_version_id",
                "next_research_trial_id",
                "next_candidate_id",
                "next_requested_days",
                "next_source_class",
            )
        }
        state["available_evidence_windows"] = len(evidence_rows)
        state["admitted_evidence_windows"] = sum(
            1 for item in evidence_rows if item.get("admitted") is True
        )
        state["measured_counters"] = {
            name: sum(int(item.get(name, 0) or 0) for item in evidence_rows)
            for name in (
                "requested_rows",
                "available_rows",
                "loaded_rows",
                "valid_input_rows",
                "evaluated_rows",
                "evaluated_observations",
                "signals",
                "signal_count",
                "diagnostic_summary_count",
                "declined_evaluations",
                "positions",
                "openings",
                "completed_outcomes",
            )
        }
        state["operating_state"] = "observing"
        state["next_work"] = "refresh_rolling_evidence"
        state["next_portfolio_review_at"] = (
            current + timedelta(days=1)
        ).isoformat()
        latest_evaluation = max(
            (
                item
                for item in evidence_rows
                if item.get("evaluation_run_id")
            ),
            key=lambda item: str(item.get("measured_at", "")),
            default=None,
        )
        state["last_successful_evaluation"] = (
            {
                "evaluation_run_id": latest_evaluation.get("evaluation_run_id"),
                "strategy_version_id": latest_evaluation.get("strategy_version_id"),
                "measured_at": latest_evaluation.get("measured_at"),
            }
            if latest_evaluation is not None
            else None
        )
        state["evaluation_counts"] = {
            "attempted": attempted,
            "successful": len(evidence_rows),
            "pending": pending_total,
        }
        state["no_entry_reason"] = (
            {
                "category": "EVIDENCE",
                "reason": "NO_QUALIFYING_SELECTION",
                "resolver": "refresh_rolling_evidence",
                "next_scheduled_action": "refresh_rolling_evidence",
            }
            if not evidence_rows or not any(item.get("admitted") is True for item in evidence_rows)
            else None
        )
        blocker_lister = getattr(self.store, "list_rolling_evidence_blockers", None)
        try:
            blockers = (
                blocker_lister(limit=_MAX_ROLLING_QUEUE_RESULTS)
                if callable(blocker_lister)
                else []
            )
        except (TypeError, ValueError, RuntimeError):
            blockers = []
        state["terminal_blockers"] = [
            _rolling_state_result(item)
            for item in blockers
            if isinstance(item, Mapping)
        ]
        state["exploratory_live_bootstrap"] = dict(bootstrap)
        # ``set_operator_job`` is also consumed by Hermes adapters.  Bound the
        # final payload after cursor/counter details are attached, while the
        # explicit ``*_total`` counters retain exact work cardinality.
        state = _rolling_bound_operator_state(state)
        setter = getattr(self.store, "set_operator_job", None)
        if callable(setter):
            setter("rolling-research-evidence", "SCHEDULED", state, resumable=True)
        return state

    def _rolling_risk_binding(self, policy: RollingAdmissionPolicy) -> dict[str, Any]:
        active_config = None
        active_loader = getattr(self.store, "load_canary_setting_config", None)
        if callable(active_loader):
            try:
                active_config = active_loader(state="ACTIVE")
            except TypeError:
                try:
                    active_config = active_loader()
                except Exception:
                    active_config = None
            except Exception:
                active_config = None
        if not isinstance(active_config, Mapping):
            for name in ("load_active_risk_config", "active_risk_config", "get_active_risk_config"):
                loader = getattr(self.store, name, None)
                if callable(loader):
                    try:
                        value = loader()
                    except Exception:
                        value = None
                    if isinstance(value, Mapping):
                        active_config = value
                        break
        return system_risk_binding_from_active_config(active_config, policy)

    def _rolling_bootstrap_blocker(
        self,
        policy: RollingAdmissionPolicy,
    ) -> str | None:
        loader = getattr(self.store, "get_operator_config", None)
        if not callable(loader):
            return None
        try:
            bootstrap_required = loader("rolling_exploratory_bootstrap_required", False) is True
        except (TypeError, ValueError, RuntimeError):
            bootstrap_required = True
        operating = loader("rolling_exploratory_operating_policy", None)
        if operating is None:
            return "ROLLING_POLICY_BOOTSTRAP_REQUIRED" if bootstrap_required else None
        if not bootstrap_required:
            return None
        active = loader("rolling_admission_policy_active", None)
        try:
            validate_system_exploratory_admission_policy(
                active if isinstance(active, Mapping) else None,
                operating if isinstance(operating, Mapping) else operating,
                self._rolling_risk_binding(policy),
            )
        except RollingPolicyBootstrapError as exc:
            return exc.code
        return None

    def _rolling_policy(self) -> RollingAdmissionPolicy:
        default = default_rolling_admission_policy()
        active_payload = None
        config_loader = getattr(self.store, "get_operator_config", None)
        if callable(config_loader):
            try:
                configured = config_loader("rolling_admission_policy_active", None)
            except TypeError:
                configured = config_loader("rolling_admission_policy_active")
            except Exception:
                configured = None
            if isinstance(configured, Mapping) and any(
                key in configured for key in ("policy_id", "version", "policy_version", "config_hash")
            ):
                active_payload = configured
        if active_payload is None:
            job_loader = getattr(self.store, "get_operator_job", None)
            active_record = job_loader("rolling_admission_policy_active") if callable(job_loader) else None
            active_payload = active_record.get("payload") if isinstance(active_record, Mapping) else None
            if (
                not isinstance(active_payload, Mapping)
                and isinstance(active_record, Mapping)
                and any(key in active_record for key in ("policy_id", "version", "policy_version", "config_hash"))
            ):
                active_payload = active_record
        if isinstance(active_payload, Mapping) and isinstance(active_payload.get("policy"), Mapping):
            active_payload = active_payload["policy"]
        if active_payload is not None:
            if not isinstance(active_payload, Mapping):
                raise ValueError("active rolling admission policy payload is invalid")
            policy_id = str(active_payload.get("policy_id", "")).strip()
            version = str(active_payload.get("version", active_payload.get("policy_version", ""))).strip()
            expected_hash = str(active_payload.get("config_hash", "")).strip()
            if not policy_id or not version or not expected_hash:
                raise ValueError("active rolling admission policy identity is incomplete")
            loader = getattr(self.store, "load_admission_policy", None)
            if not callable(loader):
                raise ValueError("active rolling admission policy loader is unavailable")
            stored = loader(policy_id, version)
            if not isinstance(stored, Mapping):
                raise ValueError("active rolling admission policy is missing")
            policy = RollingAdmissionPolicy.from_mapping(stored)
            if policy.policy_id != policy_id or policy.version != version or str(policy.config_hash) != expected_hash:
                raise ValueError("active rolling admission policy identity mismatch")
            return policy
        loader = getattr(self.store, "load_admission_policy", None)
        if callable(loader):
            stored = loader(default.policy_id, default.version)
            if isinstance(stored, Mapping):
                return RollingAdmissionPolicy.from_mapping(stored)
        saver = getattr(self.store, "save_admission_policy", None)
        if callable(saver):
            saver(default.as_dict())
        return default

    def review_rolling_portfolio(
        self,
        now: datetime | None = None,
        force: bool = False,
        *,
        skip_observation_setup_migration: bool = False,
    ) -> Mapping[str, Any]:
        """Review only persisted rolling evidence and commit an append-only selection."""
        requested_now = ensure_utc(now or self.clock())
        refreshed = self.refresh_rolling_evidence(
            requested_now,
            skip_observation_setup_migration=skip_observation_setup_migration,
        )
        if str(refreshed.get("status") or "").upper() == "BLOCKED":
            return {
                **dict(refreshed),
                "review_status": "BLOCKED",
                "selection": None,
                "proposal": None,
                "paper_only": True,
                "live_execution": False,
            }
        policy = self._rolling_policy()
        previous = self.active_portfolio_selection()
        review_state_loader = getattr(self.store, "load_portfolio_review_state", None)
        prior_state = review_state_loader() if callable(review_state_loader) else None
        effective_now = requested_now
        if isinstance(previous, Mapping):
            previous_selected_at = _rolling_timestamp(previous.get("selected_at"))
            if previous_selected_at is not None and previous_selected_at > effective_now:
                effective_now = previous_selected_at
        current = effective_now
        current_identity = (
            refreshed.get("refresh_identity")
            if isinstance(refreshed.get("refresh_identity"), Mapping)
            else {}
        )
        prior_identity = (
            prior_state.get("refresh_identity")
            if isinstance(prior_state, Mapping)
            and isinstance(prior_state.get("refresh_identity"), Mapping)
            else {}
        )
        prior_initialization = _rolling_prior_initialization_review(prior_state, previous)
        try:
            current_strategy_total = int(current_identity.get("strategy_versions_total", -1))
        except (TypeError, ValueError):
            current_strategy_total = -1
        prior_digest = str(
            prior_identity.get("digest")
            if prior_identity
            else (prior_state.get("rolling_review_identity") if isinstance(prior_state, Mapping) else "")
        ).strip()
        current_digest = str(current_identity.get("digest", "")).strip()
        refresh_changed = bool(prior_digest and current_digest and prior_digest != current_digest)
        if not prior_identity and isinstance(prior_state, Mapping):
            prior_pending = prior_state.get("pending")
            current_pending = refreshed.get("pending")
            if isinstance(prior_pending, (list, tuple)) and isinstance(current_pending, (list, tuple)):
                refresh_changed = _rolling_hash(prior_pending) != _rolling_hash(current_pending)
        initialization_transition = prior_initialization and (
            current_strategy_total > 0 or refresh_changed
        )
        due = _rolling_timestamp(prior_state.get("review_due_at")) if isinstance(prior_state, Mapping) else None
        bypass_due = bool(force or initialization_transition)
        if not bypass_due and due is not None and current < due and previous is not None:
            return self.rolling_portfolio_state()
        current_draft_trace = refreshed.get("scope_draft_trace")
        current_draft_trace = (
            current_draft_trace if isinstance(current_draft_trace, Mapping) else {}
        )
        current_draft_id = str(current_draft_trace.get("draft_id", "")).strip()
        current_draft_hash = str(current_draft_trace.get("draft_hash", "")).strip()

        def evidence_is_authorized(row: Mapping[str, Any]) -> bool:
            provenance = row.get("provenance")
            provenance = provenance if isinstance(provenance, Mapping) else {}
            if not _rolling_document_is_draft_bound(row, provenance):
                return True
            if not current_draft_id or not current_draft_hash:
                return False
            row_draft_id = str(
                row.get("draft_id") or provenance.get("draft_id") or ""
            ).strip()
            row_draft_hash = str(
                row.get("draft_hash") or provenance.get("draft_hash") or ""
            ).strip()
            return (
                row_draft_id == current_draft_id
                and row_draft_hash == current_draft_hash
            )

        lister = getattr(self.store, "list_strategy_evidence_windows", None)
        if callable(lister):
            try:
                evidence_rows = lister(limit=10_000)
            except TypeError:
                try:
                    evidence_rows = lister()
                except Exception:
                    evidence_rows = ()
            except Exception:
                evidence_rows = ()
        else:
            evidence_rows = ()
        evidence_rows = tuple(
            row
            for row in (evidence_rows or ())
            if isinstance(row, Mapping)
            and _rolling_document_is_marked(
                row,
                row.get("provenance") if isinstance(row.get("provenance"), Mapping) else None,
            )
            and evidence_is_authorized(row)
            and not _rolling_campaign_bound(row)
        )
        risk = self._rolling_risk_binding(policy)
        accounting_loader = getattr(self.store, "canary_risk_accounting", None)
        accounting_available = callable(accounting_loader)
        accounting_unavailable_reason = ""
        accounting_legacy_compatibility = not accounting_available
        accounting_fail_closed = False
        accounting: Mapping[str, Any] = {}
        if accounting_available:
            try:
                raw_accounting = accounting_loader(now=current)
            except Exception:
                accounting_available = False
                accounting_fail_closed = True
                accounting_unavailable_reason = "CANARY_RISK_ACCOUNTING_UNAVAILABLE"
            else:
                if isinstance(raw_accounting, Mapping):
                    accounting = raw_accounting
                else:
                    accounting_available = False
                    accounting_fail_closed = True
                    accounting_unavailable_reason = "CANARY_RISK_ACCOUNTING_INVALID"
        else:
            # AxiomStore implements this method.  Keep only an explicitly
            # marked compatibility path for tiny legacy test doubles; it is
            # never presented as production accounting availability.
            accounting_unavailable_reason = "CANARY_RISK_ACCOUNTING_UNAVAILABLE"

        previous_allocations: dict[str, Decimal] = {}
        if isinstance(previous, Mapping):
            prior_members = previous.get("members", previous.get("selected_members", ()))
            if isinstance(prior_members, (list, tuple)):
                for raw_member in prior_members:
                    if not isinstance(raw_member, Mapping):
                        continue
                    strategy_id = str(raw_member.get("strategy_version_id", "")).strip()
                    allocation = _rolling_number(raw_member.get("allocation"))
                    if strategy_id and allocation > 0:
                        previous_allocations[strategy_id] = allocation

        reserved_raw = accounting.get("rolling_strategy_reserved_usd")
        reserved_by_strategy: dict[str, Decimal] = {}
        reservations_invalid = not (
            "rolling_global_reserved_usd" in accounting
            and "rolling_strategy_reserved_usd" in accounting
            and isinstance(reserved_raw, Mapping)
        )
        detail_total = Decimal("0")
        if isinstance(reserved_raw, Mapping):
            for raw_strategy_id, raw_reserved in reserved_raw.items():
                strategy_id = str(raw_strategy_id).strip()
                if not strategy_id or isinstance(raw_reserved, bool):
                    reservations_invalid = True
                    continue
                try:
                    reserved = Decimal(str(raw_reserved))
                except (InvalidOperation, TypeError, ValueError):
                    reservations_invalid = True
                    continue
                if not reserved.is_finite() or reserved < 0:
                    reservations_invalid = True
                    continue
                detail_total += reserved
                if reserved > 0:
                    reserved_by_strategy[strategy_id] = reserved
        raw_global_reserved = accounting.get("rolling_global_reserved_usd")
        global_reserved = Decimal("0")
        if isinstance(raw_global_reserved, bool) or raw_global_reserved is None:
            reservations_invalid = True
        else:
            try:
                global_reserved = Decimal(str(raw_global_reserved))
            except (InvalidOperation, TypeError, ValueError):
                reservations_invalid = True
            else:
                if not global_reserved.is_finite() or global_reserved < 0:
                    reservations_invalid = True
                    global_reserved = Decimal("0")
        if reservations_invalid or detail_total != global_reserved:
            accounting_fail_closed = True
            accounting_available = False
            accounting_unavailable_reason = "ROLLING_STRATEGY_RESERVATIONS_UNAVAILABLE"
        active_obligations = max(Decimal("0"), global_reserved)
        if active_obligations <= 0 and reserved_by_strategy:
            active_obligations = sum(reserved_by_strategy.values(), Decimal("0"))
        uncovered_obligations = sum(
            (
                max(
                    Decimal("0"),
                    reserved - previous_allocations.get(strategy_id, Decimal("0")),
                )
                for strategy_id, reserved in reserved_by_strategy.items()
            ),
            Decimal("0"),
        )
        if accounting_fail_closed:
            # Unknown external obligations reserve the entire global budget;
            # this forces OBSERVE and prevents any new allocation.
            uncovered_obligations = max(
                uncovered_obligations,
                max(Decimal("0"), _rolling_number(risk.get("global_budget"))),
            )
            active_obligations = max(active_obligations, uncovered_obligations)
        risk["active_obligations"] = str(active_obligations)
        risk["runtime_active_obligations"] = str(active_obligations)
        risk["uncovered_obligations"] = str(uncovered_obligations)
        risk["external_obligations"] = str(uncovered_obligations)
        risk["rolling_strategy_reserved_usd"] = {
            strategy_id: str(reserved)
            for strategy_id, reserved in sorted(reserved_by_strategy.items())
        }
        risk["runtime_accounting_available"] = accounting_available
        risk["runtime_accounting_metadata"] = {
            "source": "canary_risk_accounting",
            "available": accounting_available,
            **(
                {"unavailable_reason": accounting_unavailable_reason}
                if not accounting_available
                else {}
            ),
            **(
                {"compatibility": "legacy_unavailable"}
                if accounting_legacy_compatibility
                else {}
            ),
        }
        risk["runtime_accounting_legacy_compatibility"] = accounting_legacy_compatibility
        if not accounting_available:
            risk["runtime_accounting_unavailable_reason"] = accounting_unavailable_reason
        global_budget = max(Decimal("0"), _rolling_number(risk.get("global_budget")))
        if accounting_fail_closed:
            uncovered_obligations = global_budget
            active_obligations = max(active_obligations, uncovered_obligations)
            risk["active_obligations"] = str(active_obligations)
            risk["runtime_active_obligations"] = str(active_obligations)
            risk["uncovered_obligations"] = str(uncovered_obligations)
            risk["external_obligations"] = str(uncovered_obligations)
        available_budget = max(Decimal("0"), global_budget - uncovered_obligations)
        risk["available_budget"] = str(available_budget)
        effective_policy = replace(policy, global_budget=global_budget, config_hash=policy.config_hash)
        evaluation_previous = previous
        if bypass_due and isinstance(previous, Mapping):
            # The pure evaluator has its own cadence guard.  Adjust only the
            # in-memory input for this one material/explicit review, while
            # preserving RollingSelection's selected_at/review_due_at ordering.
            evaluation_previous = dict(previous)
            selected_at = _rolling_timestamp(evaluation_previous.get("selected_at"))
            evaluation_previous["review_due_at"] = max(
                current,
                selected_at or current,
            ).isoformat()
        def uncovered_for_members(rows: Sequence[Any]) -> Decimal:
            if accounting_fail_closed:
                return global_budget
            allocations_by_strategy: dict[str, Decimal] = {}
            for row in rows:
                strategy_id = str(getattr(row, "strategy_version_id", "")).strip()
                allocation = _rolling_number(getattr(row, "allocation", "0"))
                if strategy_id and allocation > 0:
                    allocations_by_strategy[strategy_id] = allocation
            return sum(
                (
                    max(
                        Decimal("0"),
                        reserved - allocations_by_strategy.get(strategy_id, Decimal("0")),
                    )
                    for strategy_id, reserved in reserved_by_strategy.items()
                ),
                Decimal("0"),
            )

        def force_accounting_observe(selection: Any) -> Any:
            if not accounting_fail_closed:
                return selection
            reason = REASON_EXTERNAL_OBLIGATIONS_EXCEED_BUDGET
            members = tuple(
                member.with_status("OBSERVE", reason, allocation=Decimal("0"), action="OBSERVE")
                for member in selection.members
            )
            return replace(
                selection,
                status="OBSERVE",
                members=members,
                reasons=tuple(dict.fromkeys((*selection.reasons, reason))),
            )

        decision = evaluate_rolling_selection(
            effective_policy,
            evidence_rows,
            evaluation_previous,
            current,
            external_obligations=uncovered_obligations,
        )
        if initialization_transition:
            decision = _rolling_initialization_observe(decision, refreshed)
        decision = force_accounting_observe(decision)
        recomputed_uncovered = uncovered_for_members(decision.members)
        if recomputed_uncovered != uncovered_obligations:
            uncovered_obligations = recomputed_uncovered
            decision = evaluate_rolling_selection(
                effective_policy,
                evidence_rows,
                evaluation_previous,
                current,
                external_obligations=uncovered_obligations,
            )
            if initialization_transition:
                decision = _rolling_initialization_observe(decision, refreshed)
        else:
            uncovered_obligations = recomputed_uncovered
        risk["uncovered_obligations"] = str(uncovered_obligations)
        risk["external_obligations"] = str(uncovered_obligations)
        risk["available_budget"] = str(max(Decimal("0"), global_budget - uncovered_obligations))
        prior_event_history = (
            list(prior_state.get("event_history", []))
            if isinstance(prior_state, Mapping)
            and isinstance(prior_state.get("event_history"), list)
            else []
        )
        proposed_budget_remaining = max(
            Decimal("0"),
            _rolling_number(risk.get("available_budget")),
        )
        proposal_risk_snapshot = {
            "risk_config_id": risk.get("risk_config_id"),
            "risk_config_generation": risk.get("risk_config_generation"),
            "risk_config_hash": risk.get("risk_config_hash"),
            "global_budget": risk.get("global_budget"),
            "active_obligations": risk.get("active_obligations"),
            "uncovered_obligations": risk.get("uncovered_obligations"),
            "external_obligations": risk.get("external_obligations"),
            "available_budget": risk.get("available_budget"),
            "runtime_accounting_available": risk.get("runtime_accounting_available"),
            "runtime_accounting_metadata": risk.get("runtime_accounting_metadata"),
        }
        proposal_risk_digest = _rolling_hash(proposal_risk_snapshot)
        event_history = (
            prior_event_history
            + [{"at": current.isoformat(), "status": decision.status, "reasons": list(decision.reasons)}]
        )[-128:]
        members = [
            member.as_dict()
            for member in decision.members
            if member.candidate_id and member.research_trial_id
        ]
        evidence_by_strategy: dict[str, Mapping[str, Any]] = {}
        for raw_evidence in evidence_rows:
            if not isinstance(raw_evidence, Mapping):
                continue
            strategy_key = str(raw_evidence.get("strategy_version_id", "")).strip()
            if strategy_key:
                evidence_by_strategy[strategy_key] = raw_evidence
        enriched_members: list[dict[str, Any]] = []
        exploratory_member_count = 0
        exploratory_proposal_count = 0
        for member in members:
            row = evidence_by_strategy.get(
                str(member.get("strategy_version_id", "")).strip()
            )
            identity = row.get("operational_identity") if isinstance(row, Mapping) else None
            identity = identity if isinstance(identity, Mapping) else {}
            setup = identity.get("operational_setup")
            if isinstance(setup, Mapping):
                member["operational_setup"] = dict(setup)
                member["operational_setup_hash"] = identity.get(
                    "operational_setup_hash",
                    _operational_setup_hash(setup),
                )
                member["setup_id"] = setup.get("setup_id")
                member["setup_version"] = setup.get(
                    "setup_version",
                    setup.get("contract_version"),
                )
                setup_policy = setup.get("setup_policy")
                if (
                    isinstance(setup_policy, Mapping)
                    and str(setup_policy.get("mode", "")).strip().upper()
                    == "EXPLORATORY_LIVE"
                ):
                    exploratory_member_count += 1
                    member["operating_policy"] = dict(setup_policy)
                    member["paper_only"] = True
                    member["allocation_active"] = False
                    if (
                        exploratory_proposal_count < _EXPLORATORY_MEMBER_MAX
                        and proposed_budget_remaining >= _EXPLORATORY_PAPER_ALLOCATION
                        and str(member.get("status", "")).strip().upper()
                        in {"PAPER", "RETAINED"}
                        and _rolling_number(member.get("allocation")) <= 0
                    ):
                        member["proposed_allocation"] = str(
                            _EXPLORATORY_PAPER_ALLOCATION
                        )
                        proposed_budget_remaining -= _EXPLORATORY_PAPER_ALLOCATION
                        exploratory_proposal_count += 1
                    member["canary_armed"] = False
                scope = setup.get("market_scope_policy")
                if isinstance(scope, Mapping):
                    member["scope"] = dict(scope)
                    member["scope_hash"] = (
                        scope.get("market_scope_hash") or scope.get("scope_hash")
                    )
                    member["scope_version"] = (
                        scope.get("market_scope_version") or scope.get("scope_version")
                    )
            if isinstance(row, Mapping):
                source_provenance = row.get("provenance")
                source_provenance = (
                    source_provenance
                    if isinstance(source_provenance, Mapping)
                    else {}
                )
                source_candidates = (row, source_provenance, identity)

                def source_value(name: str) -> Any:
                    for source in source_candidates:
                        if source.get(name) not in (None, ""):
                            return source.get(name)
                    return None

                for key in (
                    "candidate_id",
                    "research_trial_id",
                    "strategy_version_id",
                    "evidence_window_id",
                    "evidence_digest",
                    "draft_id",
                    "draft_hash",
                    "draft_bound",
                    "scope_hash",
                    "scope_version",
                    "operational_setup_hash",
                ):
                    value = source_value(key)
                    if value not in (None, ""):
                        member[key] = value
                raw_bindings = next(
                    (
                        source.get("market_bindings")
                        for source in source_candidates
                        if isinstance(source.get("market_bindings"), (list, tuple))
                    ),
                    None,
                )
                if isinstance(raw_bindings, (list, tuple)):
                    member["market_bindings"] = [
                        dict(binding) if isinstance(binding, Mapping) else binding
                        for binding in raw_bindings
                    ]
                source_scope_resolution = next(
                    (
                        source.get("scope_resolution", source.get("market_scope_resolution"))
                        for source in source_candidates
                        if isinstance(
                            source.get("scope_resolution", source.get("market_scope_resolution")),
                            Mapping,
                        )
                    ),
                    None,
                )
                if isinstance(source_scope_resolution, Mapping):
                    member["scope_resolution"] = dict(source_scope_resolution)
                if source_provenance:
                    member["provenance"] = dict(source_provenance)
            enriched_members.append(member)
        members = enriched_members
        proposed_allocation_total = sum(
            (
                _rolling_number(member.get("proposed_allocation"))
                for member in members
                if isinstance(member, Mapping)
                and member.get("proposed_allocation") not in (None, "")
            ),
            Decimal("0"),
        )
        exploratory_policy = (
            dict(EXPLORATORY_LIVE_POLICY)
            if exploratory_member_count
            else None
        )
        # Removed members are not funded selection rows, but their immutable
        # identities must remain in the committed payload until the runtime
        # observes and completes the corresponding exit obligation.
        removed_members: list[dict[str, Any]] = []
        removed_ids: set[str] = set()

        def preserve_removed(raw: Any) -> None:
            if len(removed_members) >= _MAX_ROLLING_EXIT_LINEAGE or not isinstance(raw, Mapping):
                return
            strategy_id = str(raw.get("strategy_version_id", "")).strip()
            if not strategy_id or strategy_id in removed_ids:
                return
            item = dict(raw)
            item["status"] = "PAUSED"
            item["action"] = "REDUCE"
            item["allocation"] = "0"
            removed_members.append(item)
            removed_ids.add(strategy_id)

        for member in decision.removed_members:
            preserve_removed(member.as_dict())
        if isinstance(previous, Mapping):
            prior_removed = previous.get("removed_members", ())
            if isinstance(prior_removed, (list, tuple)):
                for raw in prior_removed:
                    preserve_removed(raw)
            prior_members = previous.get("members", previous.get("selected_members", ()))
            if isinstance(prior_members, (list, tuple)):
                for raw in prior_members:
                    if isinstance(raw, Mapping) and (
                        str(raw.get("status", "")).strip().upper() in {"REMOVED", "PAUSED"}
                        or str(raw.get("action", "")).strip().upper() == "REDUCE"
                    ):
                        preserve_removed(raw)
        selection_id = "rolling-selection-" + _rolling_hash({
            "policy": policy.config_hash,
            "risk": risk,
            "at": current,
            "refresh_identity": current_identity.get("digest"),
            "members": members,
            "removed_members": removed_members,
            "status": decision.status,
        }).removeprefix("sha256:")[:40]
        selection = {
            "portfolio_selection_id": selection_id,
            "selection_id": selection_id,
            "policy_id": policy.policy_id,
            "policy_version": policy.version,
            "risk_config_id": risk["risk_config_id"],
            "active_risk_config_id": risk["risk_config_id"],
            "risk_config_generation": risk["risk_config_generation"],
            "active_risk_config_generation": risk["risk_config_generation"],
            "risk_config_hash": risk["risk_config_hash"],
            "active_risk_config_hash": risk["risk_config_hash"],
            "global_budget": risk["global_budget"],
            "active_obligations": risk["active_obligations"],
            "runtime_active_obligations": risk["runtime_active_obligations"],
            "uncovered_obligations": risk["uncovered_obligations"],
            "external_obligations": risk["external_obligations"],
            "available_budget": risk["available_budget"],
            "runtime_accounting_available": risk["runtime_accounting_available"],
            "runtime_accounting_metadata": risk["runtime_accounting_metadata"],
            **(
                {
                    "runtime_accounting_unavailable_reason": risk[
                        "runtime_accounting_unavailable_reason"
                    ]
                }
                if not risk["runtime_accounting_available"]
                else {}
            ),
            "selected_at": current.isoformat(),
            "review_due_at": decision.review_due_at.isoformat() if decision.review_due_at else current.isoformat(),
            "status": decision.status,
            "reasons": list(decision.reasons),
            "score_formula": decision.score_formula,
            "formula_version": decision.formula_version,
            "policy_config": decision.policy_config,
            "removed_members": removed_members,
            "removed_member_evidence_history": dict(decision.removed_member_evidence_history),
            "last_membership_change_at": (
                decision.last_membership_change_at.isoformat()
                if decision.last_membership_change_at is not None
                else None
            ),
            "paper_only": True,
            "proposed_allocation_total": str(proposed_allocation_total),
            "proposed_allocation_risk_snapshot": dict(proposal_risk_snapshot),
            "proposed_allocation_risk_digest": proposal_risk_digest,
        }
        if exploratory_policy is not None:
            selection["operating_policy"] = dict(exploratory_policy)
            selection["exploratory_policy"] = dict(exploratory_policy)
        members = [
            {
                **member,
                "portfolio_selection_id": selection_id,
                "admission_policy_id": policy.policy_id,
                "admission_policy_version": policy.version,
                "risk_config_id": risk["risk_config_id"],
                "risk_config_generation": risk["risk_config_generation"],
                "risk_config_hash": risk["risk_config_hash"],
            }
            for member in members
        ]
        committer = getattr(self.store, "commit_portfolio_selection", None)
        state_saver = getattr(self.store, "save_portfolio_review_state", None)
        review_payload = {
            "portfolio_selection_id": selection_id,
            "review_due_at": selection["review_due_at"],
            "reviewed_at": current.isoformat(),
            "status": decision.status,
            "active_obligations": risk["active_obligations"],
            "runtime_active_obligations": risk["runtime_active_obligations"],
            "uncovered_obligations": risk["uncovered_obligations"],
            "external_obligations": risk["external_obligations"],
            "proposed_allocation_total": str(proposed_allocation_total),
            "proposed_allocation_risk_snapshot": dict(proposal_risk_snapshot),
            "proposed_allocation_risk_digest": proposal_risk_digest,
            "available_budget": risk["available_budget"],
            "runtime_accounting_available": risk["runtime_accounting_available"],
            "runtime_accounting_metadata": risk["runtime_accounting_metadata"],
            **(
                {
                    "runtime_accounting_unavailable_reason": risk[
                        "runtime_accounting_unavailable_reason"
                    ]
                }
                if not risk["runtime_accounting_available"]
                else {}
            ),
            "reasons": list(decision.reasons),
            "event_history": event_history,
            "removed_member_evidence_history": dict(decision.removed_member_evidence_history),
            "last_membership_change_at": selection["last_membership_change_at"],
            "pending": refreshed.get("pending", []),
            "next_jobs": refreshed.get("next_jobs", []),
            "refresh_identity": current_identity,
            "rolling_review_identity": current_identity.get("digest"),
            "initialization_transition": initialization_transition,
            "updated_at": current.isoformat(),
        }
        def persist_selection_and_review() -> Mapping[str, Any] | None:
            committed_value: Mapping[str, Any] | None = None
            if callable(committer):
                committed_result = committer(selection, members)
                if isinstance(committed_result, Mapping):
                    committed_value = committed_result
            if callable(state_saver):
                state_saver(review_payload)
            return committed_value

        transaction_factory = getattr(self.store, "transaction", None)
        if callable(transaction_factory):
            try:
                transaction_context = transaction_factory(immediate=True)
            except TypeError:
                transaction_context = transaction_factory()
            with transaction_context:
                committed = persist_selection_and_review()
        else:
            committed = persist_selection_and_review()
        committed_selection = (
            dict(committed)
            if isinstance(committed, Mapping)
            else {**selection, "members": members}
        )
        if not risk["runtime_accounting_available"]:
            committed_selection.setdefault(
                "runtime_accounting_unavailable_reason",
                risk["runtime_accounting_unavailable_reason"],
            )
        committed_selection.setdefault(
            "last_membership_change_at",
            selection["last_membership_change_at"],
        )
        committed_selection.setdefault("removed_members", removed_members)
        state = {
            "status": decision.status,
            "controller_status": "SCHEDULED" if refreshed.get("pending") else "READY",
            "portfolio_selection_id": selection_id,
            "selection": committed_selection,
            "event_history": event_history,
            "removed_member_evidence_history": dict(decision.removed_member_evidence_history),
            "last_membership_change_at": selection["last_membership_change_at"],
            "k": len(members),
            "actual": len(members),
            "actionable": sum(
                1
                for member in members
                if str(member.get("status", "")).upper() in {"ACTIVE", "PAPER", "REDUCE"}
                and _rolling_number(member.get("allocation")) > 0
            ),
            "active_obligations": risk["active_obligations"],
            "runtime_active_obligations": risk["runtime_active_obligations"],
            "uncovered_obligations": risk["uncovered_obligations"],
            "external_obligations": risk["external_obligations"],
            "available_budget": risk["available_budget"],
            **(
                {
                    "runtime_accounting_unavailable_reason": risk[
                        "runtime_accounting_unavailable_reason"
                    ]
                }
                if not risk["runtime_accounting_available"]
                else {}
            ),
            "policy": policy.as_dict(),
            "active_policy_identity": {
                "policy_id": policy.policy_id,
                "policy_version": policy.version,
                "config_hash": policy.config_hash,
            },
            **(
                {"operating_policy": dict(exploratory_policy)}
                if exploratory_policy is not None
                else {}
            ),
            "risk_binding": risk,
            "reasons": list(decision.reasons),
            "pending": refreshed.get("pending", []),
            "cold_start_requirements": refreshed.get("pending", []),
            "next_jobs": refreshed.get("next_jobs", []),
            "refresh_identity": current_identity,
            "rolling_review_identity": current_identity.get("digest"),
            "initialization_transition": initialization_transition,
            "paper_only": True,
        }
        return state

    def rolling_portfolio_state(self) -> Mapping[str, Any]:
        current = self.active_portfolio_selection()
        review_loader = getattr(self.store, "load_portfolio_review_state", None)
        review = review_loader() if callable(review_loader) else None
        policy = self._rolling_policy()
        risk = self._rolling_risk_binding(policy)
        members = list(current.get("members", ())) if isinstance(current, Mapping) else []
        pending = review.get("pending", []) if isinstance(review, Mapping) else []
        runtime_accounting_reason = (
            review.get("runtime_accounting_unavailable_reason")
            if isinstance(review, Mapping)
            else None
        )
        if not runtime_accounting_reason and isinstance(current, Mapping):
            runtime_accounting_reason = current.get("runtime_accounting_unavailable_reason")
        if runtime_accounting_reason:
            risk["runtime_accounting_unavailable_reason"] = runtime_accounting_reason
        state = {
            "controller_status": str(review.get("status", "COLD_START") if isinstance(review, Mapping) else "COLD_START"),
            "portfolio_selection_id": current.get("portfolio_selection_id") if isinstance(current, Mapping) else None,
            "last_membership_change_at": (
                (
                    current.get("last_membership_change_at")
                    if isinstance(current, Mapping)
                    else None
                )
                or (
                    review.get("last_membership_change_at")
                    if isinstance(review, Mapping)
                    else None
                )
            ),
            "k": int(current.get("k", len(members))) if isinstance(current, Mapping) else 0,
            "actual": len(members),
            "actionable": sum(
                1
                for member in members
                if str(member.get("status", "")).upper() in {"ACTIVE", "PAPER", "REDUCE"}
                and _rolling_number(member.get("allocation")) > 0
            ),
            "policy": policy.as_dict(),
            "active_policy_identity": {
                "policy_id": (
                    current.get("policy_id", policy.policy_id)
                    if isinstance(current, Mapping)
                    else policy.policy_id
                ),
                "policy_version": (
                    current.get("policy_version", policy.version)
                    if isinstance(current, Mapping)
                    else policy.version
                ),
                "config_hash": policy.config_hash,
            },
            **(
                {
                    "operating_policy": current.get(
                        "operating_policy",
                        current.get("exploratory_policy"),
                    )
                }
                if isinstance(current, Mapping)
                and isinstance(
                    current.get("operating_policy", current.get("exploratory_policy")),
                    Mapping,
                )
                else {}
            ),
            "risk_binding": risk,
            "active_rows": members,
            "global_limits_usage": {
                "global_budget": risk["global_budget"],
                "allocated": str(sum((_rolling_number(member.get("allocation")) for member in members), Decimal("0"))),
                "active_obligations": (
                    review.get("active_obligations", risk.get("active_obligations", "0"))
                    if isinstance(review, Mapping)
                    else risk.get("active_obligations", "0")
                ),
                "runtime_active_obligations": (
                    review.get("runtime_active_obligations", risk.get("runtime_active_obligations", "0"))
                    if isinstance(review, Mapping)
                    else risk.get("runtime_active_obligations", "0")
                ),
                "uncovered_obligations": (
                    review.get("uncovered_obligations", "0")
                    if isinstance(review, Mapping)
                    else "0"
                ),
                "external_obligations": (
                    review.get("external_obligations", "0")
                    if isinstance(review, Mapping)
                    else "0"
                ),
                "available_budget": (
                    review.get("available_budget", risk.get("available_budget", risk["global_budget"]))
                    if isinstance(review, Mapping)
                    else risk.get("available_budget", risk["global_budget"])
                ),
            },
            "event_history": review.get("event_history", []) if isinstance(review, Mapping) else [],
            "removed_member_evidence_history": review.get("removed_member_evidence_history", {}) if isinstance(review, Mapping) else {},
            "next_jobs": (
                review.get("next_jobs")
                if isinstance(review, Mapping) and isinstance(review.get("next_jobs"), list)
                else [{"job_name": "rolling-research-evidence", "status": "SCHEDULED" if pending else "COMPLETED"}]
            ),
            "cold_start_requirements": pending,
            "refresh_identity": review.get("refresh_identity", {}) if isinstance(review, Mapping) else {},
            "rolling_review_identity": review.get("rolling_review_identity") if isinstance(review, Mapping) else None,
            "paper_only": True,
        }
        if runtime_accounting_reason:
            state["runtime_accounting_unavailable_reason"] = runtime_accounting_reason
        return state

    def active_portfolio_selection(self) -> Mapping[str, Any] | None:
        loader = getattr(self.store, "load_current_portfolio_selection", None)
        if not callable(loader):
            return None
        try:
            value = loader()
        except Exception:
            return None
        return dict(value) if isinstance(value, Mapping) else None

    @staticmethod
    def campaign_job_name(campaign_id: str) -> str:
        value = str(campaign_id).strip()
        if not value or len(value) > 128:
            raise ValueError("campaign_id must be bounded non-empty text")
        return f"polymarket-research-campaign:{value}"
    @staticmethod
    def _campaign_plan_id(campaign_id: str, trial_id: str) -> str:
        """Return a bounded plan identity while preserving short legacy IDs."""
        campaign = str(campaign_id).strip()
        trial = str(trial_id).strip()
        candidate = f"campaign-plan:{campaign}:{trial}"
        if re.fullmatch(r"[A-Za-z0-9._:-]{1,128}", candidate):
            return candidate
        # Hash the complete source IDs so truncating the readable prefix cannot
        # make distinct long campaign/trial pairs collide.
        digest = _hash_document(
            {"campaign_id": campaign, "trial_id": trial}
        ).split(":", 1)[-1][:24]
        canonical = re.sub(r"[^A-Za-z0-9._:-]+", "-", candidate)
        return f"{canonical[:103]}:{digest}"


    @staticmethod
    def campaign_configurations() -> tuple[Mapping[str, Any], ...]:
        """Return the fixed, one-variant Polymarket generator grid."""
        return tuple(dict(item) for item in POLYMARKET_CAMPAIGN_GRID)

    @staticmethod
    def _campaign_configuration_allowlist(
        configurations: Sequence[Mapping[str, Any]],
        configuration_allowlist: Any,
    ) -> frozenset[str]:
        """Resolve an operator selection to exact members of the fixed grid."""
        if (
            isinstance(configuration_allowlist, (str, bytes, bytearray))
            or isinstance(configuration_allowlist, Mapping)
            or not isinstance(configuration_allowlist, Sequence)
        ):
            raise ValueError("configuration_allowlist must be a non-string sequence")
        if len(configuration_allowlist) > len(configurations):
            raise ValueError("configuration_allowlist exceeds the campaign configuration grid")
        known_ids = {
            str(item.get("configuration_id", ""))
            for item in configurations
            if isinstance(item, Mapping) and str(item.get("configuration_id", "")).strip()
        }
        selected: set[str] = set()
        for raw_id in configuration_allowlist:
            if not isinstance(raw_id, str):
                raise ValueError("configuration_allowlist entries must be strings")
            configuration_id = raw_id.strip()
            if not configuration_id:
                raise ValueError("configuration_allowlist entries must not be blank")
            if configuration_id in selected:
                raise ValueError(
                    f"configuration_allowlist contains duplicate configuration id: {configuration_id}"
                )
            if configuration_id not in known_ids:
                raise ValueError(
                    f"configuration_allowlist contains unknown configuration id: {configuration_id}"
                )
            selected.add(configuration_id)
        return frozenset(selected)


    @staticmethod
    def _campaign_dataset_rows(store: AxiomStore, dataset_id: str, dataset_version: str) -> list[Mapping[str, Any]]:
        loaded = store.load_dataset(dataset_id, dataset_version)
        if isinstance(loaded, Mapping) and isinstance(loaded.get("records"), Sequence):
            loaded = loaded["records"]
        if not isinstance(loaded, Sequence) or isinstance(loaded, (str, bytes)):
            return []
        rows = [_normalize_row(row) for row in loaded if isinstance(row, Mapping)]
        rows = [row for row in rows if row is not None]
        if any(
            str(row.get("source_type", "HISTORICAL")).strip().upper()
            != "HISTORICAL"
            for row in rows
        ):
            raise AutonomousResearchError(
                "SOFTWARE_OR_INPUT_ERROR",
                "campaign dataset rows contain FORWARD_COLLECTED evidence",
            )
        rows.sort(
            key=lambda row: (
                parse_timestamp(row.get("timestamp", row.get("source_timestamp"))) or datetime.min.replace(tzinfo=timezone.utc),
                _campaign_row_identity(row, 0),
                _hash_document(row),
            )
        )
        return rows[:_MAX_DATASET_ROWS]

    def _campaign_prior_configuration_keys(
        self,
        protocol_id: str | None = None,
    ) -> set[str]:
        target_protocol = str(protocol_id or "").strip()
        keys: set[str] = set()
        lister = getattr(self.store, "list_experiment_plans", None)
        if callable(lister):
            try:
                records = lister(limit=10_000, newest_first=False)
            except TypeError:
                records = lister(limit=10_000)
            except Exception:
                records = ()
            for record in records or ():
                if not isinstance(record, Mapping):
                    continue
                plan = record.get("plan")
                if not isinstance(plan, Mapping):
                    continue
                if target_protocol == CAMPAIGN_PROTOCOL_V2_ID:
                    protocol = plan.get("campaign_protocol")
                    if (
                        isinstance(protocol, Mapping)
                        and str(protocol.get("schema_version") or "").strip()
                        == CAMPAIGN_SCHEMA_V1
                    ):
                        continue
                template = str(plan.get("template", plan.get("experiment_family", ""))).strip().lower()
                parameters = plan.get("parameters")
                if template in {"momentum", "mean_reversion"} and isinstance(parameters, Mapping):
                    names = tuple(sorted(parameters))
                    value_sets = tuple(
                        tuple(value) if isinstance(value, (list, tuple)) else (value,)
                        for value in (parameters[name] for name in names)
                    )
                    for values in product(*value_sets):
                        keys.add(
                            _campaign_configuration_key(
                                {
                                    "template": template,
                                    "parameters": dict(zip(names, values)),
                                }
                            )
                        )
        # Queue rows and immutable reports are evidence too.  A rejected
        # candidate is never reopened merely because its queue row is still
        # visible.
        try:
            queued = self.store.list_research_items(limit=10_000)
        except Exception:
            queued = ()
        for record in queued or ():
            payload = record.get("payload") if isinstance(record, Mapping) else None
            plan = payload.get("experiment_plan") if isinstance(payload, Mapping) else None
            if isinstance(plan, Mapping):
                if target_protocol == CAMPAIGN_PROTOCOL_V2_ID:
                    protocol = plan.get("campaign_protocol")
                    if (
                        isinstance(protocol, Mapping)
                        and str(protocol.get("schema_version") or "").strip()
                        == CAMPAIGN_SCHEMA_V1
                    ):
                        continue
                template = str(plan.get("template", "")).strip().lower()
                parameters = plan.get("parameters")
                if template in {"momentum", "mean_reversion"} and isinstance(parameters, Mapping):
                    names = tuple(sorted(parameters))
                    value_sets = tuple(
                        tuple(value) if isinstance(value, (list, tuple)) else (value,)
                        for value in (parameters[name] for name in names)
                    )
                    for values in product(*value_sets):
                        keys.add(
                            _campaign_configuration_key(
                                {
                                    "template": template,
                                    "parameters": dict(zip(names, values)),
                                }
                            )
                        )
        return keys
    @staticmethod
    def _campaign_v2_protocol(value: Any) -> bool:
        """Recognize only an unambiguous, canonical V2 protocol envelope."""
        if not isinstance(value, Mapping):
            return False
        schema_version = str(value.get("schema_version", "")).strip()
        protocol_id = str(value.get("protocol_id", "")).strip()
        # Do not let a single forged marker upgrade a V1/legacy document.
        return (
            schema_version == CAMPAIGN_SCHEMA_V2
            and protocol_id == CAMPAIGN_PROTOCOL_V2_ID
        )

    @staticmethod
    def _campaign_protocol_digest(value: Mapping[str, Any]) -> str | None:
        digest = str(value.get("protocol_hash", "")).strip()
        if len(digest) != 71 or not digest.startswith("sha256:"):
            return None
        try:
            int(digest[7:], 16)
        except (TypeError, ValueError):
            return None
        return digest if digest == digest.lower() else None

    @staticmethod
    def _campaign_operational_setup_binding(
        value: Mapping[str, Any],
    ) -> tuple[str, str] | None:
        setup = value.get("operational_setup")
        setup_hash = str(value.get("operational_setup_hash", "")).strip()
        if not isinstance(setup, Mapping) or not setup_hash:
            return None
        setup_id = str(setup.get("setup_id", "")).strip()
        family = str(setup.get("family", "")).strip().lower()
        if family not in {"momentum", "mean_reversion"}:
            return None
        if setup_id != f"{family}:absolute-move-v1:L1:H1":
            return None
        if (
            str(setup.get("contract_schema", "")).strip() != "axiom-operational-setup"
            or str(setup.get("contract_version", "")).strip() != "1"
            or str(setup.get("market_type", "")).strip().lower() != "prediction"
        ):
            return None
        manifest = setup.get("assessment_manifest_ref")
        if not isinstance(manifest, Mapping):
            return None
        # A V2 setup is not durable evidence without an immutable attestation
        # identity.  Boundary-only setups must remain eligible for reruns.
        if not str(manifest.get("attestation_hash", "")).strip():
            return None
        if not str(manifest.get("dataset_id", "")).strip() or not str(
            manifest.get("dataset_version", "")
        ).strip():
            return None
        try:
            canonical_hash = _operational_setup_hash(setup)
        except (RecursionError, TypeError, ValueError, OverflowError):
            return None
        if setup_hash != canonical_hash:
            return None
        return setup_id, setup_hash

    @staticmethod
    def _campaign_exact_configuration_identity(
        value: Mapping[str, Any],
        configuration_id: Any,
    ) -> bool:
        """Require one canonical scalar member of the V2 operational grid."""
        configuration = str(configuration_id or "").strip()
        if configuration not in _OPERATIONAL_CAMPAIGN_CONFIGURATION_IDS:
            return False
        family, separator, suffix = configuration.partition(":")
        if not separator or suffix != "lookback-1:threshold-0.05":
            return False
        declared_configuration = value.get("configuration_id")
        if (
            declared_configuration is not None
            and str(declared_configuration).strip() != configuration
        ):
            return False
        template = str(value.get("template", "")).strip().lower()
        if template != family:
            return False
        experiment_family = value.get("experiment_family")
        if (
            experiment_family is not None
            and str(experiment_family).strip().lower() != family
        ):
            return False
        parameters = value.get("parameters")
        if not isinstance(parameters, Mapping):
            return False
        if (
            len(parameters) != 2
            or {str(name).strip().lower() for name in parameters}
            != {"lookback", "threshold"}
        ):
            return False

        def scalar(parameter: Any) -> Any:
            if isinstance(parameter, (list, tuple)):
                if len(parameter) != 1:
                    return None
                return parameter[0]
            return parameter

        lookback = scalar(parameters.get("lookback"))
        threshold = scalar(parameters.get("threshold"))
        if (
            isinstance(lookback, bool)
            or not isinstance(lookback, (int, float))
            or not math.isfinite(float(lookback))
            or float(lookback) != 1.0
            or isinstance(threshold, bool)
            or not isinstance(threshold, (int, float))
            or not math.isfinite(float(threshold))
            or abs(float(threshold) - 0.05) > 1e-12
        ):
            return False
        return True


    @staticmethod
    def _campaign_setup_matches_configuration(
        setup_value: Mapping[str, Any],
        configuration_id: Any,
    ) -> bool:
        configuration = str(configuration_id or "").strip()
        if configuration not in _OPERATIONAL_CAMPAIGN_CONFIGURATION_IDS:
            return False
        setup = setup_value.get("operational_setup")
        if not isinstance(setup, Mapping):
            return False
        family = configuration.split(":", 1)[0]
        return (
            str(setup.get("family", "")).strip().lower() == family
            and str(setup.get("setup_id", "")).strip()
            == f"{family}:absolute-move-v1:L1:H1"
        )

    @staticmethod
    def _campaign_setup_matches_boundary(
        setup_value: Mapping[str, Any],
        boundary: Mapping[str, Any] | None,
    ) -> bool:
        if not isinstance(boundary, Mapping):
            return True
        setup = setup_value.get("operational_setup")
        manifest = setup.get("assessment_manifest_ref") if isinstance(setup, Mapping) else None
        if not isinstance(manifest, Mapping):
            return False
        for field in ("dataset_id", "dataset_version"):
            expected = str(boundary.get(field, "")).strip()
            if expected and str(manifest.get(field, "")).strip() != expected:
                return False
        expected_digest = str(
            boundary.get("ordered_row_manifest_digest", boundary.get("content_hash", ""))
        ).strip()
        if expected_digest and str(manifest.get("manifest_digest", "")).strip() != expected_digest:
            return False
        expected_attestation = str(boundary.get("attestation_hash", "")).strip()
        if expected_attestation and str(manifest.get("attestation_hash", "")).strip() != expected_attestation:
            return False
        return True

    def _campaign_plan_evidence_binding(
        self,
        record: Mapping[str, Any] | None,
        plan: Mapping[str, Any],
        setup_value: Mapping[str, Any],
        *,
        boundary: Mapping[str, Any] | None = None,
        expected_protocol_hash: str | None = None,
    ) -> tuple[str, str] | None:
        """Validate a setup carried by one immutable experiment-plan source."""
        protocol = plan.get("campaign_protocol")
        if not self._campaign_v2_protocol(protocol):
            return None
        assert isinstance(protocol, Mapping)
        protocol_hash = self._campaign_protocol_digest(protocol)
        if protocol_hash is None or (
            expected_protocol_hash is not None and protocol_hash != expected_protocol_hash
        ):
            return None
        campaign_id = str(plan.get("campaign_id", "")).strip()
        trial_id = str(plan.get("campaign_trial_id", "")).strip()
        configuration_id = str(plan.get("campaign_configuration_id", "")).strip()
        if not campaign_id or not trial_id or not configuration_id:
            return None
        if str(protocol.get("campaign_id", "")).strip() != campaign_id:
            return None
        # Setup identity is not enough: a copied setup must remain tied to the
        # exact scalar configuration declared by this immutable plan.
        if not self._campaign_exact_configuration_identity(plan, configuration_id):
            return None
        selector = plan.get("dataset_selector")
        setup = setup_value.get("operational_setup")
        setup_manifest = setup.get("assessment_manifest_ref") if isinstance(setup, Mapping) else None
        if (
            not isinstance(selector, Mapping)
            or not isinstance(setup_manifest, Mapping)
            or str(selector.get("dataset_id", "")).strip()
            != str(setup_manifest.get("dataset_id", "")).strip()
            or str(selector.get("dataset_version", "")).strip()
            != str(setup_manifest.get("dataset_version", "")).strip()
        ):
            return None
        if not self._campaign_setup_matches_configuration(setup_value, configuration_id):
            return None
        binding = self._campaign_operational_setup_binding(setup_value)
        if binding is None or not self._campaign_setup_matches_boundary(setup_value, boundary):
            return None
        template = str(plan.get("template", plan.get("experiment_family", ""))).strip().lower()
        raw_parameters = plan.get("parameters")
        parameters = dict(raw_parameters) if isinstance(raw_parameters, Mapping) else {}
        normalized_parameters = {
            str(name): (
                value[0] if isinstance(value, (list, tuple)) and len(value) == 1 else value
            )
            for name, value in parameters.items()
        }
        expected_template = configuration_id.split(":", 1)[0]
        if template != expected_template:
            return None
        manifest = plan.get("configuration_manifest")
        if isinstance(manifest, Mapping):
            expected_manifest = {
                "configuration_id": configuration_id,
                "template": template,
                "parameters": normalized_parameters,
            }
            try:
                manifest_matches = _canonical_binding(manifest) == _canonical_binding(
                    expected_manifest
                )
            except (RecursionError, TypeError, ValueError, OverflowError):
                return None
            if not manifest_matches:
                return None
        if record is not None:
            stored_plan_id = str(record.get("plan_id", "")).strip()
            stored_hash = str(record.get("plan_hash", "")).strip()
            plan_id = str(plan.get("plan_id", "")).strip()
            if not stored_plan_id or not stored_hash:
                return None
            if plan_id and plan_id != stored_plan_id:
                return None
            if stored_hash != _hash_document(plan):
                return None
            stored_hypothesis = str(record.get("hypothesis_id", "")).strip()
            plan_hypothesis = str(plan.get("hypothesis_id", "")).strip()
            if not stored_hypothesis or (plan_hypothesis and stored_hypothesis != plan_hypothesis):
                return None
        return binding

    def _campaign_queue_evidence_binding(
        self,
        record: Mapping[str, Any],
        *,
        expected_protocol_hash: str | None = None,
    ) -> tuple[str, str] | None:
        payload = record.get("payload")
        if not isinstance(payload, Mapping):
            return None
        plan = payload.get("experiment_plan")
        setup = payload if isinstance(payload, Mapping) else None
        if not isinstance(plan, Mapping) or not isinstance(setup, Mapping):
            return None
        protocol = plan.get("campaign_protocol")
        if not isinstance(protocol, Mapping):
            return None
        protocol_hash = self._campaign_protocol_digest(protocol)
        if (
            protocol_hash is None
            or (
                expected_protocol_hash is not None
                and protocol_hash != expected_protocol_hash
            )
            or str(payload.get("campaign_protocol_hash", "")).strip() != protocol_hash
        ):
            return None
        campaign_id = str(payload.get("campaign_id", "")).strip()
        trial_id = str(payload.get("campaign_trial_id", "")).strip()
        configuration_id = str(payload.get("campaign_configuration_id", "")).strip()
        if (
            not campaign_id
            or not trial_id
            or not configuration_id
            or str(plan.get("campaign_id", "")).strip() != campaign_id
            or str(plan.get("campaign_trial_id", "")).strip() != trial_id
            or str(plan.get("campaign_configuration_id", "")).strip() != configuration_id
        ):
            return None
        payload_dataset_id = str(payload.get("dataset_id", "")).strip()
        payload_dataset_version = str(payload.get("dataset_version", "")).strip()
        if not payload_dataset_id or not payload_dataset_version:
            return None
        selector = plan.get("dataset_selector")
        if isinstance(selector, Mapping) and (
            str(selector.get("dataset_id", "")).strip() != payload_dataset_id
            or str(selector.get("dataset_version", "")).strip() != payload_dataset_version
        ):
            return None
        plan_boundary = plan.get("dataset_boundary")
        boundary = dict(plan_boundary) if isinstance(plan_boundary, Mapping) else {}
        boundary["dataset_id"] = payload_dataset_id
        boundary["dataset_version"] = payload_dataset_version
        plan_id = str(plan.get("plan_id", "")).strip()
        loader = getattr(self.store, "load_experiment_plan", None)
        if not plan_id or not callable(loader):
            return None
        try:
            persisted = loader(plan_id)
        except Exception:
            return None
        if not isinstance(persisted, Mapping) or not isinstance(persisted.get("plan"), Mapping):
            return None
        persisted_plan = persisted["plan"]
        if _canonical_binding(persisted_plan) != _canonical_binding(plan):
            return None
        if (
            str(persisted.get("plan_hash", "")).strip() != _hash_document(plan)
            or (
                str(payload.get("hypothesis_id", "")).strip()
                and str(payload.get("hypothesis_id", "")).strip()
                != str(persisted.get("hypothesis_id", "")).strip()
            )
        ):
            return None
        return self._campaign_plan_evidence_binding(
            persisted,
            plan,
            setup,
            boundary=boundary,
            expected_protocol_hash=protocol_hash,
        )

    def _campaign_prior_operational_setup_bindings(self) -> set[tuple[str, str]]:
        """Return setup identities from fully bound V2 durable evidence only."""
        bindings: set[tuple[str, str]] = set()

        lister = getattr(self.store, "list_experiment_plans", None)
        if callable(lister):
            try:
                records = lister(limit=10_000, newest_first=False)
            except TypeError:
                records = lister(limit=10_000)
            except Exception:
                records = ()
            for record in records or ():
                if not isinstance(record, Mapping):
                    continue
                plan = record.get("plan")
                if not isinstance(plan, Mapping):
                    continue
                if self._campaign_v2_protocol(plan.get("campaign_protocol")):
                    binding = self._campaign_plan_evidence_binding(record, plan, plan)
                    if binding is not None:
                        bindings.add(binding)

        try:
            queued = self.store.list_research_items(limit=10_000)
        except Exception:
            queued = ()
        for record in queued or ():
            if not isinstance(record, Mapping):
                continue
            binding = self._campaign_queue_evidence_binding(record)
            if binding is not None:
                bindings.add(binding)

        job_lister = getattr(self.store, "list_operator_jobs", None)
        if callable(job_lister):
            try:
                jobs = job_lister(
                    job_prefix="polymarket-research-campaign:",
                    limit=10_000,
                )
            except TypeError:
                try:
                    jobs = job_lister(limit=10_000)
                except Exception:
                    jobs = ()
            except Exception:
                jobs = ()
            for record in jobs or ():
                if not isinstance(record, Mapping):
                    continue
                payload = record.get("payload")
                if not isinstance(payload, Mapping):
                    continue
                job_name = str(record.get("job_name", "")).strip()
                job_campaign_id = job_name.removeprefix("polymarket-research-campaign:")
                if job_campaign_id != str(payload.get("campaign_id", "")).strip():
                    continue
                protocol = payload.get("protocol")
                if not self._campaign_v2_protocol(protocol) or not isinstance(protocol, Mapping):
                    continue
                protocol_hash = _hash_document(protocol)
                if (
                    str(payload.get("protocol_hash", "")).strip() != protocol_hash
                    or self._campaign_protocol_digest({"protocol_hash": protocol_hash}) is None
                    or str(payload.get("schema_version", "")).strip() != CAMPAIGN_SCHEMA_V2
                    or str(payload.get("protocol_id", "")).strip() != CAMPAIGN_PROTOCOL_V2_ID
                    or str(payload.get("campaign_id", "")).strip()
                    != str(protocol.get("campaign_id", "")).strip()
                ):
                    continue
                boundary = protocol.get("dataset_boundary")
                reassessment_boundaries = payload.get("reassessment_boundaries")
                trials = payload.get("trials")
                if not isinstance(trials, Sequence) or isinstance(trials, (str, bytes)):
                    continue
                operational_setups = protocol.get("operational_setups")
                if not isinstance(operational_setups, Mapping):
                    continue
                for trial in trials:
                    if not isinstance(trial, Mapping):
                        continue
                    configuration_id = str(trial.get("configuration_id", "")).strip()
                    trial_id = str(trial.get("trial_id", "")).strip()
                    trial_configuration = trial.get("configuration")
                    if (
                        not trial_id
                        or not isinstance(trial_configuration, Mapping)
                        or str(trial_configuration.get("configuration_id", "")).strip()
                        != configuration_id
                        or str(trial_configuration.get("template", "")).strip().lower()
                        != configuration_id.split(":", 1)[0]
                        or not self._campaign_exact_configuration_identity(
                            trial_configuration,
                            configuration_id,
                        )
                    ):
                        continue
                    reassessment_of = str(trial.get("reassessment_of", "")).strip()
                    trial_boundary = boundary
                    if reassessment_of:
                        trial_boundary = (
                            reassessment_boundaries.get(trial_id)
                            if isinstance(reassessment_boundaries, Mapping)
                            else None
                        )
                    if not isinstance(trial_boundary, Mapping):
                        continue
                    setup = (
                        {
                            "operational_setup": trial.get("operational_setup"),
                            "operational_setup_hash": trial.get("operational_setup_hash"),
                        }
                        if isinstance(trial.get("operational_setup"), Mapping)
                        else None
                    )
                    declared = operational_setups.get(configuration_id)
                    if (
                        setup is None
                        or self._campaign_operational_setup_binding(setup) is None
                        or (
                            not reassessment_of
                            and (
                                not isinstance(declared, Mapping)
                                or _canonical_binding(setup) != _canonical_binding(declared)
                            )
                        )
                    ):
                        continue
                    if not self._campaign_setup_matches_configuration(setup, configuration_id):
                        continue
                    if not self._campaign_setup_matches_boundary(setup, trial_boundary):
                        continue
                    # A job trial consumes a setup only after its plan and
                    # queue references resolve to the same immutable source.
                    plan_id = str(trial.get("plan_id", "")).strip()
                    plan_hash = str(trial.get("plan_hash", "")).strip()
                    queue_item_id = str(trial.get("queue_item_id", "")).strip()
                    loader = getattr(self.store, "load_experiment_plan", None)
                    queue_loader = getattr(self.store, "get_research_item", None)
                    if (
                        not plan_id
                        or not plan_hash
                        or not queue_item_id
                        or not callable(loader)
                        or not callable(queue_loader)
                    ):
                        continue
                    try:
                        persisted = loader(plan_id)
                        queue_record = queue_loader(queue_item_id)
                    except Exception:
                        continue
                    if (
                        not isinstance(persisted, Mapping)
                        or not isinstance(persisted.get("plan"), Mapping)
                        or str(persisted.get("plan_hash", "")).strip() != plan_hash
                        or not isinstance(queue_record, Mapping)
                    ):
                        continue
                    persisted_plan = persisted["plan"]
                    trial_binding = self._campaign_plan_evidence_binding(
                        persisted,
                        persisted_plan,
                        setup,
                        boundary=trial_boundary,
                        expected_protocol_hash=protocol_hash,
                    )
                    if trial_binding is None:
                        continue
                    queue_payload = queue_record.get("payload")
                    if not isinstance(queue_payload, Mapping):
                        continue
                    if (
                        str(queue_payload.get("campaign_id", "")).strip()
                        != str(payload.get("campaign_id", "")).strip()
                        or str(queue_payload.get("campaign_trial_id", "")).strip()
                        != str(trial.get("trial_id", "")).strip()
                        or str(queue_payload.get("campaign_configuration_id", "")).strip()
                        != configuration_id
                    ):
                        continue
                    queue_binding = self._campaign_queue_evidence_binding(
                        queue_record,
                        expected_protocol_hash=protocol_hash,
                    )
                    if queue_binding == trial_binding:
                        bindings.add(queue_binding)
        return bindings


    @staticmethod
    def _campaign_split_manifests(rows: Sequence[Mapping[str, Any]]) -> dict[str, dict[str, Any]]:
        """Return compact split commitments, not the historical row lists."""
        return dict(_campaign_compact_row_provenance(rows)["split_boundaries"])

    @staticmethod
    def _campaign_default_protocol(
        *,
        campaign_id: str,
        dataset_id: str,
        dataset_version: str,
        rows: Sequence[Mapping[str, Any]],
        configurations: Sequence[Mapping[str, Any]],
        qualification_gates: Mapping[str, Any] | None,
        finalist_count: int,
        observation_horizon: int,
        protocol_id: str = CAMPAIGN_PROTOCOL_V1_ID,
        attestation_hash: str | None = None,
        dataset_attestation: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        provenance = _campaign_compact_row_provenance(rows)
        manifests = dict(provenance["split_boundaries"])
        boundary = {
            "schema_version": provenance["schema_version"],
            "dataset_id": dataset_id,
            "dataset_version": dataset_version,
            "source_type": "HISTORICAL",
            "exact_cutoff": provenance["exact_cutoff"],
            "row_count": provenance["row_count"],
            "ordered_row_manifest_digest": provenance["ordered_row_manifest_digest"],
            "ordered_row_manifest_root": provenance["ordered_row_manifest_root"],
            "content_hash": provenance["content_hash"],
            "split_boundaries": dict(manifests),
        }
        if str(attestation_hash or "").strip():
            boundary["attestation_hash"] = str(attestation_hash).strip()
        protocol_identity = str(protocol_id).strip()
        if protocol_identity not in {CAMPAIGN_PROTOCOL_V1_ID, CAMPAIGN_PROTOCOL_V2_ID}:
            raise ValueError("unsupported campaign protocol")
        schema_version = (
            CAMPAIGN_SCHEMA_V2
            if protocol_identity == CAMPAIGN_PROTOCOL_V2_ID
            else CAMPAIGN_SCHEMA_V1
        )
        required_features = (
            ["timestamp", "market_id", "yes_mid"]
            if protocol_identity == CAMPAIGN_PROTOCOL_V2_ID
            else ["timestamp", "market_id", "yes_mid", "yes_bid", "yes_ask", "settlement"]
        )
        versioned_setup = protocol_identity == CAMPAIGN_PROTOCOL_V2_ID
        canonical_attestation = (
            _operational_attestation_binding(dataset_attestation)
            if isinstance(dataset_attestation, Mapping)
            else {}
        )
        supplied_attestation_hash = str(attestation_hash or "").strip()
        if supplied_attestation_hash:
            if (
                canonical_attestation
                and str(canonical_attestation.get("attestation_hash", "")).strip()
                not in {"", supplied_attestation_hash}
            ):
                raise ValueError("dataset attestation hash does not match its bounded identity")
            canonical_attestation.setdefault("attestation_hash", supplied_attestation_hash)
        if versioned_setup:
            invalid_ids = {
                str(configuration.get("configuration_id", "")).strip()
                for configuration in configurations
                if not isinstance(configuration, Mapping)
                or str(configuration.get("configuration_id", "")).strip()
                not in _OPERATIONAL_CAMPAIGN_CONFIGURATION_IDS
            }
            if invalid_ids:
                raise ValueError(
                    "V2 campaigns allow only exact operational configuration ids"
                )
        setup_scope = {
            "mode": "RULE_BASED_MARKETS",
            "instrument": "POLYMARKET",
            "filters": {},
            "regime_restrictions": {},
            "provenance": "canonical",
        }
        operational_setups: dict[str, dict[str, Any]] = {}
        if versioned_setup:
            for configuration in configurations:
                family = str(configuration.get("template", "")).strip().lower()
                raw_parameters = configuration.get("parameters")
                parameters = dict(raw_parameters) if isinstance(raw_parameters, Mapping) else {}
                scalar_parameters = {
                    name: (
                        value[0]
                        if isinstance(value, (list, tuple)) and len(value) == 1
                        else value
                    )
                    for name, value in parameters.items()
                }
                strategy_parameters = dict(parameters)
                try:
                    exact_setup = (
                        family in {"momentum", "mean_reversion"}
                        and int(scalar_parameters.get("lookback")) == 1
                        and math.isfinite(float(scalar_parameters.get("threshold")))
                        and abs(float(scalar_parameters.get("threshold")) - 0.05) <= 1e-12
                    )
                except (TypeError, ValueError, OverflowError):
                    exact_setup = False
                if not exact_setup:
                    continue
                strategy_parameters["entry_predicate"] = dict(_ABSOLUTE_MOVE_PREDICATE)
                strategy_document = {
                    "version": 1,
                    "market_type": MarketType.PREDICTION.value,
                    "family": family,
                    "parameters": strategy_parameters,
                    "probability_model": "plan-model-probability",
                    "resolution_aware": True,
                    "resolution_inputs": ["expiry", "settlement"],
                    "metadata": {
                        "operational_setup_id": configuration.get("configuration_id"),
                        "model_required": False,
                    },
                }
                setup = _operational_setup_for_strategy(
                    strategy_document,
                    {
                        "market_scope": setup_scope,
                        "dataset_id": dataset_id,
                        "dataset_version": dataset_version,
                        # Keep the bounded attestation separate from the
                        # row boundary; the setup manifest must commit to
                        # attestation rotation even when rows are unchanged.
                        "dataset_attestation": canonical_attestation,
                        "dataset_boundary": boundary,
                    },
                )
                if setup is not None:
                    setup = _canonical_operational_document(setup)
                    operational_setups[str(configuration.get("configuration_id", ""))] = {
                        "operational_setup": setup,
                        "operational_setup_hash": _operational_setup_hash(setup),
                    }
        fixed_generator = {
            "families": ["momentum", "mean_reversion"],
            "lookbacks": [1] if versioned_setup else [1, 3, 5],
            "thresholds": [0.05] if versioned_setup else [0.02, 0.05],
            **({"entry_predicate": dict(_ABSOLUTE_MOVE_PREDICATE)} if versioned_setup else {}),
            "automatic_mutations": False,
        }
        return {
            "schema_version": schema_version,
            **({"protocol_id": protocol_identity} if versioned_setup else {}),
            "campaign_id": campaign_id,
            "scientific_rationale": (
                "Test whether short price-path momentum or mean-reversion "
                "signals survive a fixed chronological paper evaluation after costs."
            ),
            "dataset_boundary": boundary,
            "configuration_manifest": [dict(item) for item in configurations],
            "fixed_generator": fixed_generator,
            **(
                {
                    "operational_setups": operational_setups,
                    "contract": {
                        "schema": "axiom-operational-setup",
                        "version": "1",
                        "setups": sorted(operational_setups),
                    },
                }
                if versioned_setup
                else {}
            ),
            "entry_rules": (
                {
                    "predicate": dict(_ABSOLUTE_MOVE_PREDICATE),
                    "predicate_raw": "abs(delta_probability) >= 0.05",
                    "positive_delta": "BUY YES",
                    "negative_delta": "BUY NO",
                    "strength_formula": "delta_probability / 0.05",
                    "eligibility_separate_from_strength": True,
                    "price_path": "same-market observed quote only",
                    "selection_partition": "validation",
                }
                if versioned_setup
                else {
                    "signal": "strategy score exceeds absolute threshold",
                    "price_path": "same-market observed quote only",
                    "selection_partition": "validation",
                }
            ),
            "exit_rules": {
                "type": "fixed_holding_period",
                "unit": "observations",
                "count": int(observation_horizon),
            },
            "required_features": required_features,
            "scope": {
                "market_type": "prediction",
                "instrument": "POLYMARKET",
                "paper_only": True,
            },
            "observation_horizon": {
                "unit": "observations",
                "count": int(observation_horizon),
                "semantics": "per_market_observation_count",
            },
            "costs": {
                **({"source": "recorded_book"} if versioned_setup else {}),
                "fee_bps": 10.0,
                "slippage_bps": 5.0,
            },
            "qualification_gates": dict(
                qualification_gates
                or {"min_expectancy": 0.0, "min_samples": 3, "min_trades": 0}
            ),
            "budget_limit": CAMPAIGN_BUDGET_LIMIT,
            "budget_version": "v1",
            "validation_policy": {
                "chronological": True,
                "selection_metric": "validation_expectancy",
                "automatic_mutations": False,
                "one_variant_per_trial": True,
            },
            "final_assessment_policy": {
                "evaluate_once": True,
                "max_finalists": int(finalist_count),
                "select_from": "validation_only",
                "untouched_until_validation_complete": True,
            },
            "protected_row_identity_manifests": manifests,
            "reassessment_limit": 1,
            "reassessment_version": "v1",
        }

    @staticmethod
    def _campaign_state_defaults(
        payload: Mapping[str, Any],
        protocol: Mapping[str, Any],
        *,
        campaign_id: str,
        now: datetime,
    ) -> dict[str, Any]:
        """Fill fields introduced after the first durable campaign writer."""
        state = dict(payload)
        boundary = protocol.get("dataset_boundary")
        boundary = boundary if isinstance(boundary, Mapping) else {}
        raw_trials = state.get("trials")
        trials = [
            item
            for item in (raw_trials if isinstance(raw_trials, Sequence) and not isinstance(raw_trials, (str, bytes)) else ())
            if isinstance(item, Mapping)
        ]
        if "schema_version" not in state:
            state["schema_version"] = protocol.get(
                "schema_version",
                "polymarket-finite-campaign-v1",
            )
        if "campaign_id" not in state:
            state["campaign_id"] = campaign_id
        if "status" not in state:
            state["status"] = "PLANNED"
        if "reassessment_boundaries" not in state:
            state["reassessment_boundaries"] = {}
        if "base_proposal" not in state:
            state["base_proposal"] = {}
        if "dataset_id" not in state:
            state["dataset_id"] = boundary.get("dataset_id")
        if "dataset_version" not in state:
            state["dataset_version"] = boundary.get("dataset_version")
        if "last_evidence_identity" not in state:
            initial_identity = str(boundary.get("attestation_hash", "")).strip()
            state["last_evidence_identity"] = initial_identity or None
        if "budget_limit" not in state:
            state["budget_limit"] = protocol.get("budget_limit", CAMPAIGN_BUDGET_LIMIT)
        if "budget_used" not in state:
            state["budget_used"] = 0
        if "budget_remaining" not in state:
            try:
                budget_limit = int(state["budget_limit"])
            except (TypeError, ValueError, OverflowError):
                budget_limit = CAMPAIGN_BUDGET_LIMIT
                state["budget_limit"] = budget_limit
            try:
                budget_used = int(state["budget_used"])
            except (TypeError, ValueError, OverflowError):
                budget_used = 0
                state["budget_used"] = budget_used
            state["budget_remaining"] = max(0, budget_limit - budget_used)
        if "fixed_configuration_count" not in state:
            manifest = protocol.get("configuration_manifest")
            state["fixed_configuration_count"] = (
                len(manifest)
                if isinstance(manifest, Sequence) and not isinstance(manifest, (str, bytes))
                else len(trials)
            )
        if "trials" not in state or not isinstance(state.get("trials"), Sequence) or isinstance(
            state.get("trials"),
            (str, bytes),
        ):
            state["trials"] = []
            trials = []
        if "counts" not in state or not isinstance(state.get("counts"), Mapping):
            state["counts"] = {}
        counts = dict(state["counts"])
        status_counts = {
            "planned": sum(str(item.get("status", "")).upper() == "PLANNED" for item in trials),
            "running": sum(str(item.get("status", "")).upper() == "RUNNING" for item in trials),
            "economic_rejection": sum(
                str(item.get("status", "")).upper() == "ECONOMIC_REJECTION"
                for item in trials
            ),
            "data_insufficient": sum(
                str(item.get("status", "")).upper() == "DATA_INSUFFICIENT"
                for item in trials
            ),
            "software_or_input_error": sum(
                str(item.get("status", "")).upper() == "SOFTWARE_OR_INPUT_ERROR"
                for item in trials
            ),
            "validation_qualified": sum(
                str(item.get("status", "")).upper() == "VALIDATION_QUALIFIED"
                for item in trials
            ),
            "final_assessment": sum(
                str(item.get("status", "")).upper() == "FINAL_ASSESSMENT"
                for item in trials
            ),
            "qualified": 0,
        }
        for key, default in status_counts.items():
            counts.setdefault(key, default)
        state["counts"] = counts
        for key, default in (
            ("selection_excluded_evidence", []),
            ("qualified_candidate_ids", []),
            ("finalist_candidate_ids", []),
            ("final_assessment_evaluated", False),
            ("reassessment_count", 0),
            ("last_result", None),
            ("next_real_job", None),
            ("created_at", ensure_utc(now).isoformat()),
            ("last_updated_at", ensure_utc(now).isoformat()),
            ("paper_only", True),
            ("research_only", True),
        ):
            state.setdefault(key, default)
        return state

    @staticmethod
    def _campaign_protocol_state(payload: Mapping[str, Any]) -> tuple[Mapping[str, Any], str]:
        protocol = payload.get("protocol")
        if not isinstance(protocol, Mapping):
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign operator job has no durable protocol",
            )
        protocol_hash = _hash_document(protocol)
        declared_hash = str(payload.get("protocol_hash", "")).strip()
        if not declared_hash or declared_hash != protocol_hash:
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign operator job protocol identity does not match its canonical protocol",
            )
        return protocol, protocol_hash

    @staticmethod
    def _campaign_trial_boundary(
        payload: Mapping[str, Any],
        protocol: Mapping[str, Any],
        trial: Mapping[str, Any],
    ) -> Mapping[str, Any]:
        trial_id = str(trial.get("trial_id", "")).strip()
        reassessment_of = str(trial.get("reassessment_of", "")).strip()
        if reassessment_of:
            boundaries = payload.get("reassessment_boundaries")
            boundary = boundaries.get(trial_id) if isinstance(boundaries, Mapping) else None
        else:
            boundary = protocol.get("dataset_boundary")
        if not isinstance(boundary, Mapping):
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                f"durable campaign boundary is missing for trial {trial_id}",
            )
        return boundary

    def _validate_campaign_plan_binding(
        self,
        payload: Mapping[str, Any],
        trial: Mapping[str, Any],
        plan: ExperimentPlan,
        *,
        queue_payload: Mapping[str, Any] | None = None,
    ) -> tuple[Mapping[str, Any], Mapping[str, Any]]:
        protocol, protocol_hash = self._campaign_protocol_state(payload)
        campaign_id = str(payload.get("campaign_id", "")).strip()
        reference = plan.campaign_protocol
        if not isinstance(reference, Mapping):
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign plan has no compact durable protocol reference",
            )
        expected_reference = {
            "schema_version": protocol.get("schema_version"),
            "campaign_id": campaign_id,
            "protocol_hash": protocol_hash,
            "budget_version": protocol.get("budget_version"),
            "reassessment_version": protocol.get("reassessment_version"),
        }
        if self._campaign_v2_protocol(protocol):
            expected_reference["protocol_id"] = CAMPAIGN_PROTOCOL_V2_ID
        # ExperimentPlan normalizes the compact reference by copying the
        # separately persisted trial fields into ``campaign_protocol``.  Bind
        # the protocol identity itself exactly, while leaving those bounded
        # projections to the field-level checks below.
        reference_identity = {
            key: reference.get(key)
            for key in expected_reference
            if key in reference
        }
        if reference_identity != expected_reference:
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign plan protocol reference is not bound to the durable protocol",
            )
        unexpected_reference_fields = set(reference) - set(expected_reference) - {
            "dataset_boundary",
            "configuration_manifest",
            "observation_horizon",
            "qualification_gates",
            "validation_policy",
            "final_assessment_policy",
        }
        if unexpected_reference_fields:
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign plan protocol reference contains unapproved duplicated protocol fields",
            )
        if plan.campaign_id != campaign_id:
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign plan campaign_id does not match the durable campaign",
            )
        trial_id = str(trial.get("trial_id", "")).strip()
        if plan.campaign_trial_id != trial_id:
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign plan trial_id does not match the durable campaign trial",
            )
        trial_setup = trial.get("operational_setup")
        if isinstance(trial_setup, Mapping):
            trial_setup_hash = str(trial.get("operational_setup_hash", "")).strip()
            if trial_setup_hash != _operational_setup_hash(trial_setup):
                raise AutonomousResearchError(
                    "CAMPAIGN_PROTOCOL_INVALID",
                    "campaign trial operational setup hash is not canonical",
                )
            if queue_payload is not None and (
                _canonical_binding(queue_payload.get("operational_setup"))
                != _canonical_binding(trial_setup)
                or str(queue_payload.get("operational_setup_hash", "")).strip()
                != trial_setup_hash
            ):
                raise AutonomousResearchError(
                    "CAMPAIGN_QUEUE_BINDING_MISMATCH",
                    "campaign queue operational setup is not durably bound",
                )
        configuration_id = str(trial.get("configuration_id", "")).strip()
        if plan.campaign_configuration_id != configuration_id:
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign plan configuration does not match the durable campaign trial",
            )
        if queue_payload is not None and str(queue_payload.get("campaign_protocol_hash", "")).strip() != protocol_hash:
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign queue protocol hash does not match the durable protocol",
            )
        boundary = self._campaign_trial_boundary(payload, protocol, trial)
        if boundary.get("missing_ranges"):
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign trial boundary contains explicit missing dataset ranges",
            )
        expected_digest = str(
            boundary.get("ordered_row_manifest_digest", boundary.get("content_hash", ""))
        ).strip()
        plan_boundary = plan.dataset_boundary
        plan_digest = (
            str(plan_boundary.get("ordered_row_manifest_digest", plan_boundary.get("content_hash", ""))).strip()
            if isinstance(plan_boundary, Mapping)
            else ""
        )
        if not expected_digest or plan_digest != expected_digest:
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign plan boundary digest does not match the durable trial boundary",
            )
        selector_id = str(plan.dataset_id or "").strip()
        selector_version = str(plan.dataset_version or "").strip()
        if (
            selector_id != str(boundary.get("dataset_id", "")).strip()
            or selector_version != str(boundary.get("dataset_version", "")).strip()
        ):
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign plan dataset selector does not match the durable trial boundary",
            )
        durable_configuration = trial.get("configuration")
        manifest = plan.configuration_manifest
        if not isinstance(durable_configuration, Mapping) or not isinstance(manifest, Mapping):
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign trial configuration is not durably bound",
            )
        expected_manifest = {
            "configuration_id": configuration_id,
            "template": durable_configuration.get("template"),
            "parameters": dict(durable_configuration.get("parameters", {})),
        }
        if _canonical_binding(manifest) != _canonical_binding(expected_manifest):
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign plan configuration manifest is not durably bound",
            )
        return protocol, boundary

    def _campaign_trial_from_payload(
        self,
        payload: Mapping[str, Any],
        *,
        campaign_id: str,
        trial_id: str,
    ) -> tuple[Mapping[str, Any], Mapping[str, Any]]:
        record = self.store.get_operator_job(self.campaign_job_name(campaign_id))
        state_payload = record.get("payload") if isinstance(record, Mapping) else None
        if not isinstance(state_payload, Mapping):
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign operator job is missing",
            )
        trials = state_payload.get("trials")
        trial = next(
            (
                item
                for item in trials
                if isinstance(item, Mapping) and str(item.get("trial_id", "")).strip() == trial_id
            ),
            None,
        ) if isinstance(trials, Sequence) and not isinstance(trials, (str, bytes)) else None
        if trial is None:
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                f"campaign trial {trial_id} is missing from the durable operator job",
            )
        return state_payload, trial

    def _campaign_queue_plan(
        self,
        state: Mapping[str, Any],
        trial: Mapping[str, Any],
    ) -> ExperimentPlan:
        protocol, _ = self._campaign_protocol_state(state)
        boundary = self._campaign_trial_boundary(state, protocol, trial)
        config = trial.get("configuration") if isinstance(trial.get("configuration"), Mapping) else {}
        campaign_id = str(state.get("campaign_id", "")).strip()
        trial_id = str(trial.get("trial_id", "")).strip()
        configuration_id = str(trial.get("configuration_id", "")).strip()
        if (
            str(protocol.get("schema_version", "")).strip() == CAMPAIGN_SCHEMA_V2
            and configuration_id not in _OPERATIONAL_CAMPAIGN_CONFIGURATION_IDS
        ):
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "V2 campaign configuration is not an exact operational setup",
            )
        base = state.get("base_proposal") if isinstance(state.get("base_proposal"), Mapping) else {}
        raw_base_plan = base.get("experiment_plan") if isinstance(base.get("experiment_plan"), Mapping) else base
        plan_document = dict(raw_base_plan)
        for redundant in ("exact_dataset_row_boundary", "protected_rows", "protected_row_identity_manifests"):
            plan_document.pop(redundant, None)
        protocol_reference = {
            "schema_version": protocol.get("schema_version"),
            "campaign_id": campaign_id,
            "protocol_hash": _hash_document(protocol),
            "budget_version": protocol.get("budget_version"),
            "reassessment_version": protocol.get("reassessment_version"),
        }
        if self._campaign_v2_protocol(protocol):
            protocol_reference["protocol_id"] = CAMPAIGN_PROTOCOL_V2_ID
        family = str(config.get("template", "")).strip().lower()
        raw_parameters = config.get("parameters")
        parameters = dict(raw_parameters) if isinstance(raw_parameters, Mapping) else {}
        versioned_setup = str(protocol.get("schema_version", "")).strip() == CAMPAIGN_SCHEMA_V2
        if versioned_setup:
            parameters.pop("entry_predicate", None)
        try:
            exact_directional_setup = (
                versioned_setup
                and family in {"momentum", "mean_reversion"}
                and int(parameters.get("lookback")) == 1
                and math.isfinite(float(parameters.get("threshold")))
                and abs(float(parameters.get("threshold")) - 0.05) <= 1e-12
            )
        except (TypeError, ValueError, OverflowError):
            exact_directional_setup = False
        strategy_parameters = (
            {**parameters, "entry_predicate": dict(_ABSOLUTE_MOVE_PREDICATE)}
            if exact_directional_setup
            else dict(parameters)
        )
        plan_document.update(
            {
                "plan_id": self._campaign_plan_id(campaign_id, trial_id),
                "hypothesis_id": f"campaign-hypothesis:{campaign_id}:{trial_id}",
                "campaign_id": campaign_id,
                "campaign_trial_id": trial_id,
                "campaign_configuration_id": configuration_id,
                "campaign_protocol": protocol_reference,
                "dataset_boundary": {
                    "ordered_row_manifest_digest": str(
                        boundary.get("ordered_row_manifest_digest", boundary.get("content_hash", ""))
                    ).strip()
                },
                "configuration_manifest": {
                    "configuration_id": configuration_id,
                    "template": config.get("template"),
                    "parameters": dict(parameters),
                },
                "observation_horizon": protocol.get("observation_horizon", {"unit": "observations", "count": 1}),
                "qualification_gates": protocol.get("qualification_gates", {}),
                "validation_policy": protocol.get("validation_policy", {}),
                "final_assessment_policy": protocol.get("final_assessment_policy", {}),
                "template": config.get("template"),
                "parameters": {
                    str(name): [value]
                    for name, value in parameters.items()
                },
                "max_variants": 1,
                "trial_budget": {"limit": 1, "locked": True},
                "paper_only": True,
                "dataset_selector": {
                    **(
                        dict(plan_document.get("dataset_selector", {}))
                        if isinstance(plan_document.get("dataset_selector"), Mapping)
                        else {}
                    ),
                    "dataset_id": boundary.get("dataset_id"),
                    "dataset_version": boundary.get("dataset_version"),
                },
            }
        )
        if exact_directional_setup:
            plan_document["strategy_document"] = {
                "version": 1,
                "market_type": MarketType.PREDICTION.value,
                "family": family,
                "parameters": strategy_parameters,
                "probability_model": "plan-model-probability",
                "resolution_aware": True,
                "resolution_inputs": ["expiry", "settlement"],
                "metadata": {
                    "operational_setup_id": configuration_id,
                    "model_required": False,
                },
            }
        plan_document.pop("scientific_rationale", None)
        plan_document.setdefault("market_type", "prediction")
        plan_document.setdefault("market_scope", {
            "mode": "RULE_BASED_MARKETS",
            "instrument": "POLYMARKET",
            "provenance": "canonical",
        })
        plan_document.setdefault("time_split", "train-validation-holdout")
        plan_document.setdefault("metrics", ("expectancy", "drawdown", "trade_count", "sample_count"))
        plan_document.setdefault("min_samples", int(protocol.get("qualification_gates", {}).get("min_samples", 3)))
        plan_document.setdefault("min_trades", int(protocol.get("qualification_gates", {}).get("min_trades", 0)))
        plan_document["allowed_features"] = list(protocol.get("required_features", ()))
        plan_document.setdefault("assumptions", protocol.get("costs", {}))
        plan_document.setdefault("exit_policy", {
            "type": "fixed_holding_period",
            "holding_period": int(protocol.get("observation_horizon", {}).get("count", 1)),
        })
        plan_document.setdefault("filters", {})
        plan_document.setdefault("experiment_family", config.get("template"))
        return ExperimentPlan.from_mapping(plan_document, hypothesis_id=plan_document["hypothesis_id"])



    def _campaign_queue_next(self, now: datetime) -> Mapping[str, Any] | None:
        campaign_id = str(self._campaign_active_state.get("campaign_id", "")).strip()
        job_name = self.campaign_job_name(campaign_id)
        # Queue binding, plan persistence, and the campaign cursor advance are
        # one durable operation.  An immediate transaction also serializes
        # concurrent/restarted workers before either can spend the same slot.
        with self.store.transaction(immediate=True):
            state = dict(self.store.get_operator_job(job_name) or {})
            payload = state.get("payload") if isinstance(state.get("payload"), Mapping) else {}
            payload = dict(payload)
            trials = [dict(item) for item in payload.get("trials", ()) if isinstance(item, Mapping)]
            next_trial = next(
                (
                    item
                    for item in trials
                    if item.get("status") == "PLANNED"
                    and str(item.get("reassessment_of", "")).strip()
                ),
                None,
            )
            if next_trial is None:
                next_trial = next((item for item in trials if item.get("status") == "PLANNED"), None)
            if next_trial is None:
                return None
            protocol, protocol_hash = self._campaign_protocol_state(payload)
            if (
                str(protocol.get("schema_version", "")).strip() == CAMPAIGN_SCHEMA_V2
                and str(next_trial.get("configuration_id", "")).strip()
                not in _OPERATIONAL_CAMPAIGN_CONFIGURATION_IDS
            ):
                raise AutonomousResearchError(
                    "CAMPAIGN_PROTOCOL_INVALID",
                    "V2 campaign cannot enqueue a non-operational configuration",
                )
            plan = self._campaign_queue_plan(payload, next_trial)
            boundary = self._campaign_trial_boundary(payload, protocol, next_trial)
            self._validate_campaign_dataset_provenance(
                str(boundary.get("dataset_id", "")).strip(),
                str(boundary.get("dataset_version", "")).strip(),
                boundary=boundary,
                plan=plan,
            )
            campaign_trial_id = str(next_trial.get("trial_id", "")).strip()
            queue_payload = {
                "proposal_id": plan.hypothesis_id,
                "hypothesis_id": plan.hypothesis_id,
                "statement": str(protocol.get("scientific_rationale", "Finite Polymarket campaign")),
                "source": "axiom-finite-campaign",
                "tests": ["chronological validation on the protected dataset boundary"],
                "dataset_id": plan.dataset_id,
                "dataset_version": plan.dataset_version,
                "time_split": plan.methodology.get("time_split", "train-validation-holdout"),
                "experiment_plan": plan.as_dict(),
                "campaign_id": campaign_id,
                "campaign_trial_id": campaign_trial_id,
                "campaign_configuration_id": next_trial.get("configuration_id"),
                "campaign_protocol_hash": protocol_hash,
                "paper_only": True,
                "predeclared_starting_set": False,
                "automatic_mutations": False,
            }
            if isinstance(next_trial.get("operational_setup"), Mapping):
                queue_payload["operational_setup"] = dict(next_trial["operational_setup"])
                queue_payload["operational_setup_hash"] = str(
                    next_trial.get("operational_setup_hash", "")
                ).strip() or _operational_setup_hash(next_trial["operational_setup"])
            dedupe_key = f"campaign:{campaign_id}:{campaign_trial_id}"
            queued = next(
                (
                    item
                    for item in self.bus.list_campaign_trials(campaign_id, limit=10_000)
                    if str(item.payload.get("campaign_trial_id", "")).strip() == campaign_trial_id
                ),
                None,
            )
            if queued is not None:
                existing_payload = queued.payload
                existing_plan = existing_payload.get("experiment_plan")
                existing_plan_matches = False
                if isinstance(existing_plan, Mapping):
                    try:
                        existing_bound_plan = ExperimentPlan.from_mapping(
                            existing_plan,
                            hypothesis_id=str(existing_payload.get("hypothesis_id", "")).strip() or None,
                        )
                    except (ExperimentPlanError, TypeError, ValueError):
                        existing_bound_plan = None
                    existing_plan_matches = (
                        existing_bound_plan is not None
                        and existing_bound_plan.plan_id == plan.plan_id
                        and existing_bound_plan.plan_hash == plan.plan_hash
                    )
                if (
                    str(existing_payload.get("campaign_id", "")).strip() != campaign_id
                    or str(existing_payload.get("proposal_id", "")).strip() != plan.hypothesis_id
                    or str(existing_payload.get("hypothesis_id", "")).strip() != plan.hypothesis_id
                    or not existing_plan_matches
                    or str(existing_payload.get("campaign_protocol_hash", "")).strip() != protocol_hash
                ):
                    raise AutonomousResearchError(
                        "CAMPAIGN_QUEUE_BINDING_MISMATCH",
                        f"existing queue binding does not match planned trial {campaign_trial_id}",
                    )
            else:
                # Keep the plan PENDING until the queue write succeeds.  If
                # payload validation rejects the trial, this transaction rolls
                # back and the trial remains PLANNED for operator diagnosis.
                self.store.save_experiment_plan(
                    plan.plan_id,
                    plan.as_dict(),
                    hypothesis_id=plan.hypothesis_id,
                    plan_hash=plan.plan_hash,
                    status="PENDING",
                    timestamp=now,
                )
                queued = self.bus.submit_campaign_trial(
                    queue_payload,
                    campaign_id=campaign_id,
                    trial_id=campaign_trial_id,
                    dedupe_key=dedupe_key,
                    available_at=now,
                )
            for item in trials:
                if item.get("trial_id") == campaign_trial_id:
                    item.update(
                        {
                            "status": "RUNNING",
                            "proposal_id": plan.hypothesis_id,
                            "hypothesis_id": plan.hypothesis_id,
                            "plan_id": plan.plan_id,
                            "plan_hash": plan.plan_hash,
                            "queue_item_id": queued.item_id,
                            "queued_at": ensure_utc(now).isoformat(),
                        }
                    )
            payload["trials"] = trials
            counts = dict(payload.get("counts") or {})
            counts["planned"] = max(0, int(counts.get("planned", 0)) - 1)
            counts["running"] = int(counts.get("running", 0)) + 1
            payload["counts"] = counts
            payload["budget_used"] = int(payload.get("budget_used", 0)) + 1
            payload["budget_remaining"] = max(0, CAMPAIGN_BUDGET_LIMIT - payload["budget_used"])
            payload["status"] = "RUNNING"
            payload["next_real_job"] = None
            payload["last_updated_at"] = ensure_utc(now).isoformat()
            self.store.set_operator_job(job_name, "RUNNING", payload, resumable=True, timestamp=now)
            self._campaign_active_state = payload
            return {
                "trial_id": campaign_trial_id,
                "queue_item_id": queued.item_id,
                "proposal_id": plan.hypothesis_id,
                "hypothesis_id": plan.hypothesis_id,
                "plan_id": plan.plan_id,
                "plan_hash": plan.plan_hash,
            }

    def start_polymarket_campaign(
        self,
        campaign_id: str,
        proposal: Mapping[str, Any] | None = None,
        *,
        dataset_id: str | None = None,
        dataset_version: str | None = None,
        protocol_id: str | None = None,
        observation_horizon: int = 1,
        finalist_count: int = CAMPAIGN_MAX_FINALISTS,
        qualification_gates: Mapping[str, Any] | None = None,
        configuration_allowlist: Sequence[str] | None = None,
        now: datetime | None = None,
    ) -> Mapping[str, Any]:
        """Persist a finite protocol and queue exactly its next trial."""
        current = ensure_utc(now or self.clock())
        campaign = str(campaign_id).strip()
        if not campaign:
            raise ValueError("campaign_id is required")
        if isinstance(observation_horizon, bool) or not isinstance(observation_horizon, int) or observation_horizon < 1:
            raise ValueError("observation_horizon must be a positive observation count")
        if isinstance(finalist_count, bool) or not 1 <= int(finalist_count) <= CAMPAIGN_MAX_FINALISTS:
            raise ValueError("finalist_count exceeds the campaign safety bound")
        source = dict(proposal or {})
        inferred_protocol_id = (
            CAMPAIGN_PROTOCOL_V2_ID
            if campaign.startswith(f"{CAMPAIGN_PROTOCOL_V2_ID}:")
            else CAMPAIGN_PROTOCOL_V1_ID
        )
        resolved_protocol_id = str(
            protocol_id or source.get("protocol_id") or inferred_protocol_id
        ).strip()
        if resolved_protocol_id not in {CAMPAIGN_PROTOCOL_V1_ID, CAMPAIGN_PROTOCOL_V2_ID}:
            raise ValueError("unsupported campaign protocol")
        if resolved_protocol_id == CAMPAIGN_PROTOCOL_V2_ID and observation_horizon != 1:
            raise ValueError("operational setups require holding horizon 1 observation")
        canonical_configurations: tuple[Mapping[str, Any], ...] | None = None
        selected_configuration_ids: frozenset[str] | None = None
        if configuration_allowlist is not None:
            canonical_configurations = self.campaign_configurations()
            selected_configuration_ids = self._campaign_configuration_allowlist(
                canonical_configurations,
                configuration_allowlist,
            )
            if (
                resolved_protocol_id == CAMPAIGN_PROTOCOL_V2_ID
                and not selected_configuration_ids.issubset(
                    _OPERATIONAL_CAMPAIGN_CONFIGURATION_IDS
                )
            ):
                raise ValueError(
                    "V2 campaigns allow only exact operational configuration ids"
                )
        elif resolved_protocol_id == CAMPAIGN_PROTOCOL_V2_ID:
            canonical_configurations = tuple(
                item
                for item in self.campaign_configurations()
                if str(item.get("configuration_id", "")).strip()
                in _OPERATIONAL_CAMPAIGN_CONFIGURATION_IDS
            )
            selected_configuration_ids = frozenset(
                str(item["configuration_id"]) for item in canonical_configurations
            )
        job_name = self.campaign_job_name(campaign)
        existing = self.store.get_operator_job(job_name)
        if isinstance(existing, Mapping):
            # A scheduler restart may observe a protocol written by the
            # pre-compact writer after it crashed before its first queue
            # commit.  Re-read and repair under the writer lock so two
            # restarts cannot each spend the same first campaign slot.
            with self.store.transaction(immediate=True):
                durable = self.store.get_operator_job(job_name)
                if not isinstance(durable, Mapping):
                    return {}
                existing_payload = dict(durable.get("payload") or {})
                protocol = existing_payload.get("protocol")
                if not isinstance(protocol, Mapping):
                    self._campaign_protocol_state(existing_payload)
                protocol_hash = _hash_document(protocol)
                declared_hash = str(existing_payload.get("protocol_hash", "")).strip()
                if declared_hash and declared_hash != protocol_hash:
                    raise AutonomousResearchError(
                        "CAMPAIGN_PROTOCOL_INVALID",
                        "campaign operator job protocol identity does not match its canonical protocol",
                    )
                payload_status = str(existing_payload.get("status", "")).strip().upper()
                record_status = str(durable.get("status", "")).strip().upper()
                if (
                    payload_status in CAMPAIGN_TERMINAL_STATUSES
                    or record_status in CAMPAIGN_TERMINAL_STATUSES
                    or str(existing_payload.get("supersession_reason", "")).strip().upper()
                    == "SUPERSEDED_PROTOCOL"
                ):
                    # Terminal campaigns are immutable evidence.  Validate an
                    # already-declared hash, but do not rewrite legacy rows or
                    # enqueue a successor.
                    if declared_hash:
                        self._campaign_protocol_state(existing_payload)
                    self._campaign_active_state = existing_payload
                    return existing_payload
                if not str(existing_payload.get("status", "")).strip():
                    existing_payload["status"] = record_status or "PLANNED"
                if "protocol_hash" not in existing_payload or not declared_hash:
                    existing_payload["protocol_hash"] = protocol_hash
                resumed_payload = self._campaign_state_defaults(
                    existing_payload,
                    protocol,
                    campaign_id=campaign,
                    now=current,
                )
                status = str(resumed_payload.get("status", "PLANNED")).strip().upper()
                if resumed_payload != dict(durable.get("payload") or {}):
                    self.store.set_operator_job(
                        job_name,
                        status,
                        resumed_payload,
                        resumable=True,
                        timestamp=current,
                    )
                self._campaign_active_state = resumed_payload
                if status == "PLANNED":
                    self._campaign_queue_next(current)
                resumed_record = self.store.get_operator_job(job_name)
                result_payload = (
                    resumed_record.get("payload")
                    if isinstance(resumed_record, Mapping)
                    and isinstance(resumed_record.get("payload"), Mapping)
                    else resumed_payload
                )
            return dict(result_payload)
        resolved_dataset_id = str(
            dataset_id
            or source.get("dataset_id")
            or (
                source.get("dataset_selector", {}).get("dataset_id")
                if isinstance(source.get("dataset_selector"), Mapping)
                else ""
            )
            or "Polymarket-historical"
        ).strip()
        resolved_dataset_version = str(
            dataset_version
            or source.get("dataset_version")
            or (
                source.get("dataset_selector", {}).get("dataset_version")
                if isinstance(source.get("dataset_selector"), Mapping)
                else ""
            )
            or ""
        ).strip()
        if not resolved_dataset_version:
            raise ValueError("dataset_version is required")
        attestation = self._validate_campaign_dataset_provenance(
            resolved_dataset_id,
            resolved_dataset_version,
            source=source,
        )
        rows = self._campaign_dataset_rows(self.store, resolved_dataset_id, resolved_dataset_version)
        if len(rows) != int(attestation.get("row_count", -1)):
            raise AutonomousResearchError(
                "SOFTWARE_OR_INPUT_ERROR",
                "campaign dataset rows do not match the attested catalog count",
            )
        if canonical_configurations is None:
            candidate_configurations = [
                dict(item)
                for item in self.campaign_configurations()
            ]
        else:
            candidate_configurations = [
                dict(item)
                for item in canonical_configurations
                if str(item.get("configuration_id", "")) in selected_configuration_ids
            ]
        if resolved_protocol_id == CAMPAIGN_PROTOCOL_V2_ID:
            candidate_protocol = self._campaign_default_protocol(
                campaign_id=campaign,
                dataset_id=resolved_dataset_id,
                dataset_version=resolved_dataset_version,
                rows=rows,
                configurations=candidate_configurations,
                qualification_gates=qualification_gates,
                finalist_count=int(finalist_count),
                observation_horizon=int(observation_horizon),
                protocol_id=resolved_protocol_id,
                attestation_hash=str(attestation.get("attestation_hash", "")).strip(),
                dataset_attestation=attestation,
            )
            candidate_setups = candidate_protocol.get("operational_setups")
            candidate_setups = candidate_setups if isinstance(candidate_setups, Mapping) else {}
            prior_setups = self._campaign_prior_operational_setup_bindings()
            configurations = []
            for item in candidate_configurations:
                setup = candidate_setups.get(str(item.get("configuration_id", "")).strip())
                binding = (
                    self._campaign_operational_setup_binding(setup)
                    if isinstance(setup, Mapping)
                    else None
                )
                if binding is None or binding not in prior_setups:
                    configurations.append(item)
        else:
            prior = self._campaign_prior_configuration_keys(resolved_protocol_id)
            configurations = [
                item
                for item in candidate_configurations
                if _campaign_configuration_key(item) not in prior
            ]
        if resolved_protocol_id == CAMPAIGN_PROTOCOL_V2_ID and len(configurations) == len(candidate_configurations):
            protocol = candidate_protocol
        else:
            protocol = self._campaign_default_protocol(
                campaign_id=campaign,
                dataset_id=resolved_dataset_id,
                dataset_version=resolved_dataset_version,
                rows=rows,
                configurations=configurations,
                qualification_gates=qualification_gates,
                finalist_count=int(finalist_count),
                observation_horizon=int(observation_horizon),
                protocol_id=resolved_protocol_id,
                attestation_hash=str(attestation.get("attestation_hash", "")).strip(),
                dataset_attestation=attestation,
            )
        protocol_hash = _hash_document(protocol)
        operational_setups = protocol.get("operational_setups", {})
        operational_setups = operational_setups if isinstance(operational_setups, Mapping) else {}
        trials: list[dict[str, Any]] = [
            {
                "trial_id": f"trial:{campaign}:{index:02d}",
                "configuration_id": item["configuration_id"],
                "configuration": dict(item),
                **(
                    dict(operational_setups[item["configuration_id"]])
                    if isinstance(operational_setups.get(item["configuration_id"]), Mapping)
                    else {}
                ),
                "status": "PLANNED",
                "result": None,
            }
            for index, item in enumerate(configurations)
        ]
        # The legacy zero-edge control is evidence, not a new trial.
        control = {
            "configuration_id": "control:zero_edge",
            "template": "probability_mispricing",
            "parameters": {"threshold": 0.05},
            "status": "SELECTION_EXCLUDED",
            "reason": "existing zero-edge control retained; never rerun",
        }
        payload: dict[str, Any] = {
            "schema_version": protocol.get("schema_version", CAMPAIGN_SCHEMA_V1),
            "protocol_id": resolved_protocol_id,
            "campaign_id": campaign,
            "status": "PLANNED" if trials else "CAMPAIGN_EXHAUSTED_NO_QUALIFIED_STRATEGY",
            "protocol": protocol,
            "protocol_hash": protocol_hash,
            "reassessment_boundaries": {},
            "last_evidence_identity": str(attestation.get("attestation_hash", "")).strip() or None,
            "base_proposal": source,
            "dataset_id": resolved_dataset_id,
            "dataset_version": resolved_dataset_version,
            "budget_limit": CAMPAIGN_BUDGET_LIMIT,
            "budget_used": 0,
            "budget_remaining": CAMPAIGN_BUDGET_LIMIT,
            "fixed_configuration_count": len(configurations),
            "counts": {
                "planned": len(trials),
                "running": 0,
                "economic_rejection": 0,
                "data_insufficient": 0,
                "software_or_input_error": 0,
                "validation_qualified": 0,
                "final_assessment": 0,
                "qualified": 0,
            },
            "trials": trials,
            "selection_excluded_evidence": [control],
            "qualified_candidate_ids": [],
            "finalist_candidate_ids": [],
            "final_assessment_evaluated": False,
            "reassessment_count": 0,
            "last_result": None,
            "next_real_job": None,
            "created_at": ensure_utc(current).isoformat(),
            "last_updated_at": ensure_utc(current).isoformat(),
            "paper_only": True,
            "research_only": True,
        }
        job_name = self.campaign_job_name(campaign)
        # This write is deliberately before the first bus write.  A crash
        # between the two leaves a durable protocol that can be resumed.
        self.store.set_operator_job(job_name, payload["status"], payload, resumable=True, timestamp=current)
        self._campaign_active_state = payload
        if trials:
            with self.store.transaction():
                self._campaign_queue_next(current)
        return dict(self.store.get_operator_job(job_name).get("payload", payload))

    start_campaign = start_polymarket_campaign

    def campaign_state(self, campaign_id: str) -> Mapping[str, Any] | None:
        record = self.store.get_operator_job(self.campaign_job_name(campaign_id))
        payload = record.get("payload") if isinstance(record, Mapping) else None
        if isinstance(payload, Mapping):
            self._campaign_active_state = dict(payload)
            return dict(payload)
        return None

    get_campaign_state = campaign_state

    def _campaign_schedule_data_job(
        self,
        payload: dict[str, Any],
        trial: Mapping[str, Any],
        *,
        now: datetime,
        reason: str,
    ) -> str:
        campaign_id = str(payload.get("campaign_id", "")).strip()
        trial_id = str(trial.get("trial_id", "")).strip()
        job_name = f"polymarket-research-data:{campaign_id}:{trial_id}"
        producer_name = f"polymarket-dataset-producer:{campaign_id}:{trial_id}"
        data_payload = {
            "schema_version": "polymarket-research-data-v1",
            "job_kind": "POLYMARKET_RESEARCH_DATA_PREREQUISITE",
            "campaign_id": campaign_id,
            "campaign_trial_id": trial_id,
            "dataset_id": payload.get("dataset_id"),
            "dataset_version": payload.get("dataset_version"),
            "reason": reason,
            "producer_job": producer_name,
            "status_taxonomy": ["SCHEDULED", "RUNNING", "NO_NEW_DATA", "COMPLETE", "FAILED", "EXHAUSTED"],
            "cursor": trial.get("data_cursor"),
            "request_budget": 1,
            "backoff_seconds": 60,
            "next_attempt_at": ensure_utc(now).isoformat(),
            "paper_only": True,
        }
        self.store.set_operator_job(job_name, "SCHEDULED", data_payload, resumable=True, timestamp=now)
        payload["next_real_job"] = job_name
        return job_name

    @staticmethod
    def _campaign_result_classification(result: Mapping[str, Any]) -> str:
        code = str(result.get("reason_code", "")).strip().upper()
        if code in {"INSUFFICIENT_DATA", "DATA_INSUFFICIENT"}:
            return "DATA_INSUFFICIENT"
        if code in {
            "PROCESSING_FAILED",
            "INVALID_PLAN",
            "INVALID_DATASET",
            "SOFTWARE_OR_INPUT_ERROR",
            "DATASET_PROVENANCE_INVALID",
            "DATASET_ATTESTATION_MISSING",
            "DATASET_ATTESTATION_STALE",
            "DATASET_ATTESTATION_CHANGED",
        }:
            return "SOFTWARE_OR_INPUT_ERROR"
        if result.get("accepted") is not False and str(result.get("stage", "")).upper() != CandidateStage.REJECTED.value:
            return "VALIDATION_QUALIFIED"
        return "ECONOMIC_REJECTION"

    def _campaign_final_assessment(self, payload: dict[str, Any], *, now: datetime) -> None:
        if bool(payload.get("final_assessment_evaluated")):
            return
        protocol, _ = self._campaign_protocol_state(payload)
        payload["status"] = "FINAL_ASSESSMENT"
        trials = [dict(item) for item in payload.get("trials", ()) if isinstance(item, Mapping)]
        qualified = [
            item
            for item in trials
            if item.get("status") == "VALIDATION_QUALIFIED"
            and not bool(item.get("selection_excluded"))
        ][: int(protocol.get("final_assessment_policy", {}).get("max_finalists", 1))]
        protected = protocol.get("protected_row_identity_manifests")
        protected = protected if isinstance(protected, Mapping) else {}
        final_manifest = protected.get("final", ())
        boundary = protocol.get("dataset_boundary") if isinstance(protocol, Mapping) else {}
        boundary = boundary if isinstance(boundary, Mapping) else {}
        final_boundary = boundary.get("split_boundaries", {}).get("final", ())
        if not final_boundary:
            final_boundary = final_manifest
        final_ids = {
            str(item.get("row_identity"))
            for item in final_manifest
            if isinstance(item, Mapping)
        } if isinstance(final_manifest, (list, tuple)) else set()
        final_row_count = (
            int(final_manifest.get("row_count", 0))
            if isinstance(final_manifest, Mapping)
            else len(final_ids)
        )
        final_digest = (
            str(boundary.get("ordered_row_manifest_digest", boundary.get("content_hash", ""))).strip()
            if isinstance(boundary, Mapping)
            else ""
        )
        assessments: list[dict[str, Any]] = []
        for trial in qualified:
            plan_id = str(trial.get("plan_id", "")).strip()
            plan_record = self.store.load_experiment_plan(plan_id) if plan_id else None
            raw_plan = plan_record.get("plan") if isinstance(plan_record, Mapping) else None
            if not isinstance(raw_plan, Mapping):
                continue
            try:
                plan = ExperimentPlan.from_mapping(
                    raw_plan,
                    hypothesis_id=str(plan_record.get("hypothesis_id", "")).strip() or None,
                )
                expected_plan_hash = str(trial.get("plan_hash", "")).strip()
                if not expected_plan_hash or expected_plan_hash != plan.plan_hash:
                    raise AutonomousResearchError(
                        "CAMPAIGN_PROTOCOL_INVALID",
                        "campaign final-assessment plan hash is not durably bound",
                    )
                _, trial_boundary = self._validate_campaign_plan_binding(payload, trial, plan)
                trial_protected = protected if not str(trial.get("reassessment_of", "")).strip() else {}
                trial_manifest = trial_protected.get("final", ())
                trial_boundary_splits = trial_boundary.get("split_boundaries", {})
                trial_descriptor = (
                    trial_boundary_splits.get("final", ())
                    if isinstance(trial_boundary_splits, Mapping)
                    else ()
                ) or trial_manifest
                expected_digest = str(
                    trial_boundary.get(
                        "ordered_row_manifest_digest",
                        trial_boundary.get("content_hash", ""),
                    )
                ).strip()
                self._validate_campaign_dataset_provenance(
                    str(trial_boundary.get("dataset_id", "")).strip(),
                    str(trial_boundary.get("dataset_version", "")).strip(),
                    boundary=trial_boundary,
                    plan=plan,
                )
                rows = self._campaign_dataset_rows(
                    self.store,
                    str(trial_boundary.get("dataset_id", "")).strip(),
                    str(trial_boundary.get("dataset_version", "")).strip(),
                )
                actual_provenance = _campaign_compact_row_provenance(rows)
                if (
                    actual_provenance["row_count"] != int(trial_boundary.get("row_count", -1))
                    or actual_provenance["exact_cutoff"] != trial_boundary.get("exact_cutoff")
                    or actual_provenance["ordered_row_manifest_digest"] != expected_digest
                ):
                    raise AutonomousResearchError(
                        "DATASET_PROVENANCE_INVALID",
                        "campaign final-assessment dataset boundary changed",
                    )
                final_rows = _campaign_rows_for_split(rows, trial_descriptor)
                trial_digest = expected_digest
                strategy = _strategy_with_operational_overlay(
                    plan,
                    plan.strategy_for(plan.variants()[0], str(trial.get("candidate_id", trial.get("trial_id")))),
                )
                metrics = dict(self._run_backtest(plan, strategy, final_rows))
                gates = protocol.get("qualification_gates", {})
                sample_check = minimum_sample_check(
                    int(metrics.get("sample_count", 0)),
                    trades=int(metrics.get("filled_trades", 0)),
                    min_observations=int(gates.get("min_samples", 0)),
                    min_trades=int(gates.get("min_trades", 0)),
                )
                passed = (
                    _finite(metrics.get("expectancy"), -math.inf) >= _finite(gates.get("min_expectancy"), 0.0)
                    and bool(sample_check["passed"])
                )
                assessments.append(
                    {
                        "trial_id": trial.get("trial_id"),
                        "candidate_id": trial.get("candidate_id"),
                        "status": "QUALIFIED" if passed else "REJECTED",
                        "passed": passed,
                        "minimum_sample_check": sample_check,
                        "metrics": _compact_evidence(metrics),
                        "protected_row_identity_manifest": dict(trial_descriptor) if isinstance(trial_descriptor, Mapping) else list(trial_manifest),
                        "final_rows_digest": trial_digest,
                        "dataset_boundary": dict(trial_boundary),
                    }
                )
            except (AutonomousResearchError, ExperimentPlanError, TypeError, ValueError) as exc:
                assessments.append(
                    {
                        "trial_id": trial.get("trial_id"),
                        "candidate_id": trial.get("candidate_id"),
                        "status": "SOFTWARE_OR_INPUT_ERROR",
                        "reason": str(exc),
                    }
                )
        qualified_ids = [
            str(item.get("candidate_id"))
            for item in assessments
            if item.get("status") == "QUALIFIED" and str(item.get("candidate_id", "")).strip()
        ]
        finalist_assessment = next(
            (
                item
                for item in assessments
                if item.get("status") == "QUALIFIED"
                and isinstance(item.get("dataset_boundary"), Mapping)
            ),
            None,
        )
        envelope_boundary = (
            dict(finalist_assessment["dataset_boundary"])
            if isinstance(finalist_assessment, Mapping)
            else None
        )
        if envelope_boundary is not None:
            finalist_manifest = finalist_assessment.get("protected_row_identity_manifest")
            persisted_final_manifest = (
                dict(finalist_manifest)
                if isinstance(finalist_manifest, Mapping)
                else list(finalist_manifest)
                if isinstance(finalist_manifest, (list, tuple))
                else {}
            )
            final_digest = str(
                envelope_boundary.get(
                    "ordered_row_manifest_digest",
                    envelope_boundary.get("content_hash", ""),
                )
            ).strip()
            final_row_count = int(envelope_boundary.get("row_count", 0))
        else:
            persisted_final_manifest = (
                dict(final_manifest)
                if isinstance(final_manifest, Mapping)
                else dict(final_boundary)
                if isinstance(final_boundary, Mapping)
                else list(final_manifest)
            )
        payload["final_assessment"] = {
            "evaluated_once": True,
            "assessments": assessments,
            "protected_row_identity_manifest": persisted_final_manifest,
            "protected_row_identity_digest": final_digest,
            "row_count": final_row_count,
            "dataset_boundary": envelope_boundary,
        }
        payload["final_assessment_evaluated"] = True
        payload["qualified_candidate_ids"] = qualified_ids
        payload["counts"]["final_assessment"] = len(assessments)
        payload["counts"]["qualified"] = len(qualified_ids)
        payload["status"] = "COMPLETED_QUALIFIED" if qualified_ids else "CAMPAIGN_EXHAUSTED_NO_QUALIFIED_STRATEGY"
        payload["next_real_job"] = None
        payload["last_updated_at"] = ensure_utc(now).isoformat()

    def _advance_campaign_after_result(
        self,
        item: ResearchQueueItem,
        result: Mapping[str, Any],
        now: datetime,
    ) -> None:
        campaign_id = str(item.payload.get("campaign_id", "")).strip()
        if not campaign_id:
            return
        job_name = self.campaign_job_name(campaign_id)
        record = self.store.get_operator_job(job_name)
        if not isinstance(record, Mapping):
            return
        payload = dict(record.get("payload") or {})
        if (
            str(record.get("status", "")).strip().upper() in CAMPAIGN_TERMINAL_STATUSES
            or str(payload.get("status", "")).strip().upper() in CAMPAIGN_TERMINAL_STATUSES
            or str(payload.get("supersession_reason", "")).strip().upper()
            == "SUPERSEDED_PROTOCOL"
        ):
            return
        trial_id = str(item.payload.get("campaign_trial_id", "")).strip()
        trials = [dict(entry) for entry in payload.get("trials", ()) if isinstance(entry, Mapping)]
        trial = next((entry for entry in trials if str(entry.get("trial_id", "")) == trial_id), None)
        if trial is None or str(trial.get("status", "")).upper() in CAMPAIGN_TRIAL_TERMINAL:
            return
        classification = self._campaign_result_classification(result)
        trial.update(
            {
                "status": classification,
                "candidate_id": result.get("candidate_id"),
                "result": dict(result),
                "completed_at": ensure_utc(now).isoformat(),
            }
        )
        payload["trials"] = trials
        counts = dict(payload.get("counts") or {})
        counts["running"] = max(0, int(counts.get("running", 0)) - 1)
        count_key = classification.lower()
        counts[count_key] = int(counts.get(count_key, 0)) + 1
        payload["counts"] = counts
        payload["last_result"] = {
            "trial_id": trial_id,
            "status": classification,
            "reason_code": result.get("reason_code"),
            "candidate_id": result.get("candidate_id"),
        }
        self._campaign_active_state = payload
        if classification == "DATA_INSUFFICIENT":
            payload["status"] = "WAITING_FOR_DATA"
            self._campaign_schedule_data_job(
                payload,
                trial,
                now=now,
                reason=str(result.get("reason", "insufficient observations")),
            )
        elif classification == "SOFTWARE_OR_INPUT_ERROR":
            # A software/input fault is not a data-readiness condition.  Do
            # not enqueue a prerequisite job that cannot repair the same
            # malformed input; surface a durable operator-review terminal.
            payload["status"] = "SOFTWARE_OR_INPUT_ERROR"
            payload["terminal"] = True
            payload["retry_scheduled"] = False
            payload["next_real_job"] = None
        else:
            payload["status"] = "RUNNING"
            self.store.set_operator_job(job_name, "RUNNING", payload, resumable=True, timestamp=now)
            queued_next = (
                self._campaign_queue_next(now)
                if payload["budget_remaining"] > 0
                else None
            )
            if queued_next is None:
                self._campaign_final_assessment(payload, now=now)
        if classification in {"DATA_INSUFFICIENT", "SOFTWARE_OR_INPUT_ERROR"}:
            payload["next_work"] = payload.get("next_real_job")
            payload["next_scheduled_action"] = (
                "run_campaign_retry"
                if payload.get("next_real_job")
                else "operator_review_terminal_error"
            )
            self.store.set_operator_job(
                job_name,
                payload["status"],
                payload,
                resumable=bool(payload.get("next_real_job")),
                timestamp=now,
            )
        elif payload.get("status") in {"CAMPAIGN_EXHAUSTED_NO_QUALIFIED_STRATEGY", "COMPLETED_QUALIFIED"}:
            self.store.set_operator_job(job_name, payload["status"], payload, resumable=False, timestamp=now)

    def _campaign_reassessment_dataset_identity(
        self,
        payload: Mapping[str, Any],
        evidence_identity: str,
        *,
        dataset_id: str | None,
        dataset_version: str | None,
    ) -> tuple[str, str]:
        current_id = str(payload.get("dataset_id", "")).strip()
        current_version = str(payload.get("dataset_version", "")).strip()
        resolved_id = str(dataset_id or current_id).strip()
        resolved_version = str(dataset_version or "").strip()
        if resolved_version:
            return resolved_id, resolved_version
        if not resolved_id:
            return resolved_id, current_version
        # Attestation hashes are the normal evidence identity. Resolve the
        # exact immutable version instead of guessing from version ordering.
        catalog_lister = getattr(self.store, "list_dataset_catalog", None)
        catalog_loader = getattr(self.store, "load_dataset_catalog", None)
        attestation_loader = getattr(self.store, "load_dataset_integrity_attestation", None)
        candidates: list[str] = []
        if callable(catalog_lister):
            try:
                catalogs = catalog_lister(
                    source_type="HISTORICAL",
                    market_type=MarketType.PREDICTION.value,
                    limit=256,
                )
            except TypeError:
                try:
                    catalogs = catalog_lister(limit=256)
                except Exception:
                    catalogs = ()
            except Exception:
                catalogs = ()
            for catalog in catalogs if isinstance(catalogs, Sequence) else ():
                if not isinstance(catalog, Mapping):
                    continue
                listed_id = str(catalog.get("dataset_id", "")).strip()
                version = str(catalog.get("dataset_version", catalog.get("version", ""))).strip()
                if listed_id == resolved_id and version:
                    candidates.append(version)
        versions = getattr(self.store, "dataset_versions", None)
        if callable(versions):
            try:
                candidates.extend(str(item).strip() for item in versions(resolved_id))
            except Exception:
                pass
        seen: set[str] = set()
        for version in candidates:
            if not version or version in seen or version == current_version:
                continue


            seen.add(version)
            if callable(catalog_loader):
                try:
                    catalog = catalog_loader(resolved_id, version)
                except Exception:
                    continue
                if not isinstance(catalog, Mapping):
                    continue
            if not callable(attestation_loader):
                continue
            try:
                attestation = attestation_loader(resolved_id, version)
            except Exception:
                continue
            if (
                isinstance(attestation, Mapping)
                and str(attestation.get("attestation_hash", "")).strip() == evidence_identity
                and str(attestation.get("status", "")).strip().upper() == "CURRENT"
            ):
                return resolved_id, version
        return resolved_id, current_version
    def _campaign_reassessment_operational_setup(
        self,
        trial: Mapping[str, Any],
        *,
        dataset_id: str,
        dataset_version: str,
        dataset_attestation: Mapping[str, Any],
        dataset_boundary: Mapping[str, Any],
    ) -> tuple[dict[str, Any], str]:
        """Rebind a V2 trial's exact setup to reassessed evidence."""
        configuration_id = str(trial.get("configuration_id", "")).strip()
        configuration = trial.get("configuration")
        if (
            not isinstance(configuration, Mapping)
            or not self._campaign_exact_configuration_identity(
                configuration,
                configuration_id,
            )
        ):
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "V2 reassessment trial configuration is not canonical",
            )
        family = configuration_id.split(":", 1)[0]
        raw_parameters = configuration.get("parameters")
        assert isinstance(raw_parameters, Mapping)

        def scalar(value: Any) -> Any:
            return value[0] if isinstance(value, (list, tuple)) else value

        strategy_document = {
            "version": 1,
            "market_type": MarketType.PREDICTION.value,
            "family": family,
            "parameters": {
                "lookback": 1,
                "threshold": 0.05,
                "entry_predicate": dict(_ABSOLUTE_MOVE_PREDICATE),
            },
            "probability_model": "plan-model-probability",
            "resolution_aware": True,
            "resolution_inputs": ["expiry", "settlement"],
            "metadata": {
                "operational_setup_id": configuration_id,
                "model_required": False,
            },
        }
        # Keep this assertion close to the canonical construction so a future
        # grid edit cannot accidentally make the setup independent of its
        # declared scalar configuration.
        if (
            scalar(raw_parameters.get("lookback")) != 1
            or float(scalar(raw_parameters.get("threshold"))) != 0.05
        ):
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "V2 reassessment trial scalar configuration changed",
            )
        setup = _operational_setup_for_strategy(
            strategy_document,
            {
                "market_scope": {
                    "mode": "RULE_BASED_MARKETS",
                    "instrument": "POLYMARKET",
                    "filters": {},
                    "regime_restrictions": {},
                    "provenance": "canonical",
                },
                "dataset_id": dataset_id,
                "dataset_version": dataset_version,
                "dataset_attestation": _operational_attestation_binding(
                    dataset_attestation
                ),
                "dataset_boundary": dataset_boundary,
            },
        )
        if setup is None:
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "V2 reassessment operational setup could not be constructed",
            )
        canonical_setup = _canonical_operational_document(setup)
        return canonical_setup, _operational_setup_hash(canonical_setup)
    @staticmethod
    def _campaign_boundary_for_dataset(
        dataset_id: str,
        dataset_version: str,
        rows: Sequence[Mapping[str, Any]],
        *,
        attestation_hash: str | None = None,
    ) -> tuple[dict[str, Any], dict[str, dict[str, Any]]]:
        provenance = _campaign_compact_row_provenance(rows)
        boundary = {
            "schema_version": provenance["schema_version"],
            "dataset_id": dataset_id,
            "dataset_version": dataset_version,
            "source_type": "HISTORICAL",
            "exact_cutoff": provenance["exact_cutoff"],
            "row_count": provenance["row_count"],
            "ordered_row_manifest_digest": provenance["ordered_row_manifest_digest"],
            "ordered_row_manifest_root": provenance["ordered_row_manifest_root"],
            "content_hash": provenance["content_hash"],
            "split_boundaries": dict(provenance["split_boundaries"]),
        }
        if str(attestation_hash or "").strip():
            boundary["attestation_hash"] = str(attestation_hash).strip()
        return boundary, dict(provenance["split_boundaries"])

    def reassess_campaign(
        self,
        campaign_id: str,
        *,
        evidence_identity: str,
        dataset_id: str | None = None,
        dataset_version: str | None = None,
        now: datetime | None = None,
    ) -> Mapping[str, Any]:
        """Allow one auditable changed-evidence reassessment only."""
        job_name = self.campaign_job_name(campaign_id)
        record = self.store.get_operator_job(job_name)
        if not isinstance(record, Mapping):
            raise ValueError("campaign does not exist")
        payload = dict(record.get("payload") or {})
        # Terminal campaign outcomes are immutable evidence.  Guard before
        # protocol, identity, provenance, or clock handling so legacy terminal
        # rows cannot be reopened by changed evidence (including v1
        # non-resumable input-error and superseded-protocol rows).
        record_status = str(record.get("status", "")).strip().upper()
        payload_status = str(payload.get("status", "")).strip().upper()
        supersession_reason = (
            str(payload.get("supersession_reason", "")).strip().upper()
            or str(record.get("supersession_reason", "")).strip().upper()
        )
        resumable_marker = payload.get("resumable")
        if resumable_marker is None:
            resumable_marker = record.get("resumable")
        legacy_nonresumable_error = (
            (
                record_status == "SOFTWARE_OR_INPUT_ERROR"
                or payload_status == "SOFTWARE_OR_INPUT_ERROR"
            )
            and (
                resumable_marker is False
                or (
                    isinstance(resumable_marker, str)
                    and resumable_marker.strip().upper() in {"0", "FALSE"}
                )
                or (
                    isinstance(resumable_marker, (int, float))
                    and not isinstance(resumable_marker, bool)
                    and resumable_marker == 0
                )
            )
        )
        if (
            record_status in CAMPAIGN_TERMINAL_STATUSES
            or payload_status in CAMPAIGN_TERMINAL_STATUSES
            or supersession_reason == "SUPERSEDED_PROTOCOL"
            or legacy_nonresumable_error
        ):
            return payload
        current = ensure_utc(now or self.clock())
        protocol, _ = self._campaign_protocol_state(payload)
        identity = str(evidence_identity).strip()
        if not identity:
            raise ValueError("evidence_identity is required")
        boundary = protocol.get("dataset_boundary")
        boundary_identity = (
            str(boundary.get("attestation_hash")).strip()
            if isinstance(boundary, Mapping)
            and boundary.get("attestation_hash") is not None
            else ""
        )
        raw_previous_identity = payload.get("last_evidence_identity")
        previous_identity = (
            str(raw_previous_identity).strip()
            if raw_previous_identity is not None
            else ""
        ) or boundary_identity or None
        if previous_identity is None:
            # Legacy rows without an authenticated prior identity cannot
            # establish that supplied evidence is changed.
            return payload
        if identity == previous_identity or int(payload.get("reassessment_count", 0)) >= 1:
            return payload
        waiting = [
            dict(item)
            for item in payload.get("trials", ())
            if isinstance(item, Mapping) and item.get("status") == "DATA_INSUFFICIENT"
        ]
        if not waiting:
            return payload
        resolved_dataset_id, resolved_dataset_version = self._campaign_reassessment_dataset_identity(
            payload,
            identity,
            dataset_id=dataset_id,
            dataset_version=dataset_version,
        )
        reassessment_attestation = self._validate_campaign_dataset_provenance(
            resolved_dataset_id,
            resolved_dataset_version,
            expected_attestation_hash=identity,
        )
        new_rows = self._campaign_dataset_rows(
            self.store,
            resolved_dataset_id,
            resolved_dataset_version,
        )
        if len(new_rows) != int(reassessment_attestation.get("row_count", -1)):
            raise AutonomousResearchError(
                "SOFTWARE_OR_INPUT_ERROR",
                "campaign reassessment rows do not match the attested catalog count",
            )
        reassessment_boundary, _ = self._campaign_boundary_for_dataset(
            resolved_dataset_id,
            resolved_dataset_version,
            new_rows,
            attestation_hash=str(
                reassessment_attestation.get("attestation_hash", "")
            ).strip(),
        )
        payload["reassessment_count"] = 1
        payload["last_evidence_identity"] = identity
        payload["reassessment_evidence"] = {
            "identity": identity,
            "changed_from": previous_identity,
            "dataset_id": resolved_dataset_id,
            "dataset_version": resolved_dataset_version,
            "recorded_at": ensure_utc(current).isoformat(),
            "auditable": True,
        }
        reassessment_boundaries = dict(payload.get("reassessment_boundaries") or {})
        trials = [dict(item) for item in payload.get("trials", ()) if isinstance(item, Mapping)]
        existing_trial_ids = {
            str(item.get("trial_id", "")).strip()
            for item in trials
        }
        appended = 0
        v2_reassessment = self._campaign_v2_protocol(protocol)
        for old in waiting:
            reassessment_id = f"{old.get('trial_id')}:reassessment-1"
            if reassessment_id in existing_trial_ids:
                continue
            reassessment_trial = {
                "trial_id": reassessment_id,
                "configuration_id": old.get("configuration_id"),
                "configuration": dict(old.get("configuration", {})),
                "status": "PLANNED",
                "reassessment_of": old.get("trial_id"),
                "dataset_id": resolved_dataset_id,
                "dataset_version": resolved_dataset_version,
                "result": None,
            }
            if v2_reassessment:
                setup, setup_hash = self._campaign_reassessment_operational_setup(
                    reassessment_trial,
                    dataset_id=resolved_dataset_id,
                    dataset_version=resolved_dataset_version,
                    dataset_attestation=reassessment_attestation,
                    dataset_boundary=reassessment_boundary,
                )
                reassessment_trial.update(
                    {
                        "operational_setup": setup,
                        "operational_setup_hash": setup_hash,
                    }
                )
            trials.append(reassessment_trial)
            reassessment_boundaries[reassessment_id] = dict(reassessment_boundary)
            existing_trial_ids.add(reassessment_id)
            appended += 1
        payload["reassessment_boundaries"] = reassessment_boundaries
        payload["trials"] = trials
        counts = dict(payload.get("counts") or {})
        counts["planned"] = int(counts.get("planned", 0)) + appended
        payload["counts"] = counts
        payload["status"] = "RUNNING"
        payload["next_real_job"] = None
        self.store.set_operator_job(job_name, "RUNNING", payload, resumable=True, timestamp=current)
        self.store.save_report_if_absent(
            f"campaign-reassessment:{campaign_id}:1",
            {
                "report_type": "polymarket_campaign_reassessment",
                "campaign_id": campaign_id,
                "evidence_identity": identity,
                "changed_from": previous_identity,
                "reassessment_count": 1,
                "paper_only": True,
            },
            experiment_id=job_name,
        )
        self._campaign_active_state = payload
        with self.store.transaction():
            self._campaign_queue_next(current)
        return dict(self.store.get_operator_job(job_name).get("payload", payload))
    def advance_campaign(
        self,
        campaign_id: str,
        *,
        evidence_identity: str | None = None,
        dataset_id: str | None = None,
        dataset_version: str | None = None,
        now: datetime | None = None,
    ) -> Mapping[str, Any]:
        if evidence_identity is not None:
            return self.reassess_campaign(
                campaign_id,
                evidence_identity=evidence_identity,
                dataset_id=dataset_id,
                dataset_version=dataset_version,
                now=now,
            )
        state = self.campaign_state(campaign_id)
        return dict(state or {})

    def _legacy_provenance_state(
        self,
        plan: ExperimentPlan | None,
        document: Mapping[str, Any],
    ) -> dict[str, Any]:
        """Return a bounded, canonical snapshot of successor provenance state."""
        if plan is not None:
            dataset_id = str(plan.dataset_id or "").strip()
            dataset_version = str(plan.dataset_version or "").strip()
            selector = plan.dataset_selector
        else:
            source = document.get("experiment_plan")
            source = source if isinstance(source, Mapping) else document
            raw_selector = source.get("dataset_selector")
            selector = raw_selector if isinstance(raw_selector, Mapping) else source
            dataset_id = str(selector.get("dataset_id") or source.get("dataset_id") or "").strip()
            dataset_version = str(
                selector.get("dataset_version")
                or selector.get("version")
                or source.get("dataset_version")
                or source.get("version")
                or ""
            ).strip()
        declared: dict[str, Any] = {}
        for name in ("source_type", "source", "provider", "timeframe", "interval"):
            value = selector.get(name)
            if value is not None and str(value).strip():
                declared[name] = str(value).strip()
        state: dict[str, Any] = {
            "dataset_id": dataset_id or None,
            "dataset_version": dataset_version or None,
            "declared_selectors": declared,
            "catalog": None,
            "attestation": None,
        }
        if not dataset_id or not dataset_version:
            return state
        catalog_loader = getattr(self.store, "load_dataset_catalog", None)
        if callable(catalog_loader):
            try:
                catalog = catalog_loader(dataset_id, dataset_version)
            except Exception:
                catalog = None
            if isinstance(catalog, Mapping):
                metadata = catalog.get("metadata")
                metadata = metadata if isinstance(metadata, Mapping) else {}
                state["catalog"] = {
                    name: catalog.get(name)
                    for name in (
                        "dataset_id",
                        "dataset_version",
                        "version",
                        "provider",
                        "source",
                        "instrument",
                        "market_type",
                        "timeframe",
                        "source_type",
                        "snapshot_id",
                        "row_count",
                        "completeness",
                        "missing_ranges",
                    )
                    if catalog.get(name) is not None
                }
                state["catalog"]["metadata"] = {
                    name: metadata.get(name)
                    for name in (
                        "provider",
                        "source",
                        "instrument",
                        "market_type",
                        "timeframe",
                        "source_type",
                        "research_quality",
                        "historical_order_book_available",
                        "contamination_result",
                        "provenance_version",
                        "policy_version",
                    )
                    if metadata.get(name) is not None
                }
        attestation_loader = getattr(self.store, "load_dataset_integrity_attestation", None)
        if callable(attestation_loader):
            try:
                attestation = attestation_loader(dataset_id, dataset_version)
            except Exception:
                attestation = None
            if isinstance(attestation, Mapping):
                state["attestation"] = {
                    name: attestation.get(name)
                    for name in (
                        "dataset_id",
                        "dataset_version",
                        "status",
                        "reason",
                        "reasons",
                        "contamination_result",
                        "attestation_hash",
                        "row_count",
                        "completeness",
                        "source_type",
                        "market_type",
                        "execution_fidelity",
                    )
                    if attestation.get(name) is not None
                }
        return state

    def _persist_legacy_recovery_evidence(
        self,
        evidence: Mapping[str, Any],
        *,
        queue_item: ResearchQueueItem | None = None,
        now: datetime,
    ) -> bool:
        """Persist one recovery decision without mutating its predecessor.

        A queued successor gets a queue event so the ordinary activity
        projection can show the handoff before the item is claimed.  A blocked
        predecessor has no queue item to attach to, so it gets one stable
        report per canonical blocker/provenance state.  Both paths remain
        idempotent on the recovery key.
        """
        recovery_key = str(evidence.get("recovery_key", "")).strip()
        detail = dict(evidence)
        state_digest = _legacy_recovery_state_digest(detail)
        detail["provenance_state_digest"] = state_digest
        if isinstance(evidence, dict):
            evidence["provenance_state_digest"] = state_digest
        if queue_item is not None:
            item_id = str(queue_item.item_id).strip()
            if not item_id:
                return False
            try:
                events = self.store.list_research_queue_events(item_id, limit=256)
                if any(
                    isinstance(event, Mapping)
                    and isinstance(event.get("detail"), Mapping)
                    and str(event["detail"].get("recovery_key", "")).strip() == recovery_key
                    for event in events
                ):
                    return True
                self.store.record_research_queue_event(
                    item_id,
                    "LEGACY_SCOPE_RECOVERY",
                    detail,
                    timestamp=now,
                )
                return True
            except (KeyError, RuntimeError, TypeError, ValueError):
                return False

        report_id = (
            "legacy-recovery-"
            + hashlib.sha256(recovery_key.encode("utf-8")).hexdigest()[:24]
            + "-"
            + state_digest.removeprefix("sha256:")
        )
        try:
            if self.store.load_report(report_id) is not None:
                return True
            self.store.save_report_if_absent(
                report_id,
                {"report_type": "legacy_scope_recovery", **detail},
                experiment_id=detail.get("predecessor_candidate_id"),
            )
            return True
        except (RuntimeError, TypeError, ValueError):
            return False

    def _recover_legacy_predecessors(self, now: datetime) -> tuple[Mapping[str, Any], ...]:
        """Run a bounded, deterministic legacy-scope handoff before claiming.

        Only persisted prediction predecessors with a nested target market
        list are eligible for conversion.  Classification and failure
        evidence are durable, while the old lifecycle row is deliberately
        never rewritten.
        """
        page_loader = getattr(self.store, "load_candidate_lifecycle_page", None)
        loader = getattr(self.store, "load_candidate_lifecycle", None)
        if not callable(page_loader) and not callable(loader):
            return ()

        # The cursor is worker state, not processor state.  A processor
        # restart therefore resumes the same keyset page instead of silently
        # returning to the oldest lifecycle rows.
        state_loader = getattr(self.store, "get_scheduler_state", None)
        state_setter = getattr(self.store, "set_scheduler_state", None)
        durable_pagination = (
            callable(page_loader)
            and callable(state_loader)
            and callable(state_setter)
        )
        state: Mapping[str, Any] = {}
        cursor_updated_at: str | None = None
        cursor_candidate_id: str | None = None
        if durable_pagination:
            try:
                loaded_state = state_loader(_LEGACY_RECOVERY_STATE_NAME)
            except (RuntimeError, TypeError, ValueError):
                return ()
            if isinstance(loaded_state, Mapping):
                state = loaded_state
                cursor = loaded_state.get("cursor")
                if isinstance(cursor, Mapping):
                    timestamp = str(cursor.get("updated_at", "")).strip()
                    candidate_id = str(cursor.get("candidate_id", "")).strip()
                    if timestamp and candidate_id:
                        cursor_updated_at = timestamp
                        cursor_candidate_id = candidate_id
        try:
            if callable(page_loader):
                if cursor_updated_at is not None and cursor_candidate_id is not None:
                    records = page_loader(
                        limit=_MAX_LEGACY_RECOVERY_ITEMS,
                        after_updated_at=cursor_updated_at,
                        after_candidate_id=cursor_candidate_id,
                    )
                    # Reaching the end starts a new deterministic pass.  The
                    # first page is read in this same cycle so a lone row (or
                    # a short tail) cannot make the worker idle for a cycle.
                    if not records:
                        cursor_updated_at = None
                        cursor_candidate_id = None
                        records = page_loader(limit=_MAX_LEGACY_RECOVERY_ITEMS)
                else:
                    records = page_loader(limit=_MAX_LEGACY_RECOVERY_ITEMS)
            else:
                records = loader(limit=_MAX_LEGACY_RECOVERY_ITEMS)
        except (RuntimeError, TypeError, ValueError):
            return ()
        if not isinstance(records, list):
            return ()

        candidates: list[Mapping[str, Any]] = []
        for record in records:
            if not isinstance(record, Mapping):
                continue
            payload = record.get("payload")
            if not isinstance(payload, Mapping):
                continue
            plan = payload.get("experiment_plan")
            plan = plan if isinstance(plan, Mapping) else {}
            market_type = plan.get("market_type", payload.get("market_type"))
            if str(market_type or "").strip().lower() != MarketType.PREDICTION.value:
                continue
            if str(payload.get("successor_relation", "")).strip().upper() == "LEGACY_SCOPE_SUCCESSOR":
                continue
            candidates.append(record)

        output: list[Mapping[str, Any]] = []
        from .legacy_scope import (
            CANONICAL_VALID,
            LEGACY_UNAMBIGUOUS,
            LegacyScopeError,
            classify_legacy_scope,
            create_legacy_successor,
        )

        inspected = 0
        cursor_record: Mapping[str, Any] | None = None
        scan_aborted = False
        recovery_limit = min(_MAX_LEGACY_RECOVERY_ITEMS, self.config.max_items_per_cycle)
        for record in candidates:
            if inspected >= recovery_limit:
                break
            inspected += 1
            prior_cursor_record = cursor_record
            cursor_record = record
            payload = record.get("payload")
            assert isinstance(payload, Mapping)
            document = _legacy_recovery_document(record)
            if document is None:
                continue
            selector_reason = _legacy_dataset_selector_conflict(document)
            assessment = classify_legacy_scope(document)
            if assessment.classification == CANONICAL_VALID and selector_reason is None:
                continue
            candidate_id = assessment.candidate_id or str(
                document.get("candidate_id") or record.get("candidate_id") or ""
            ).strip() or None
            nested_target = _nested_legacy_target_market_ids(document)
            plan_document = document.get("experiment_plan")
            target_document = (
                plan_document.get("target")
                if isinstance(plan_document, Mapping)
                else None
            )
            nested_target_unrecognized = nested_target is None and not (
                isinstance(target_document, Mapping) and not target_document
            )
            if selector_reason is not None:
                classification = "INVALID"
                reason = selector_reason
            elif nested_target_unrecognized:
                classification = "INVALID"
                reason = "MISSING_NESTED_TARGET_MARKET_IDS"
            else:
                classification = assessment.classification
                reason = assessment.reason
            frozen_hash = assessment.frozen_hash
            recovery_key = _legacy_recovery_key(record, candidate_id, frozen_hash)
            evidence: dict[str, Any] = {
                "recovery_key": recovery_key,
                "attempt": "LEGACY_SCOPE_RECOVERY",
                "attempted": True,
                "attempted_at": ensure_utc(now).isoformat(),
                "predecessor_candidate_id": candidate_id,
                "predecessor_frozen_hash": frozen_hash,
                "classification": classification,
                "reason_code": reason,
                "scope_hash": assessment.scope_hash,
                "scope_version": assessment.scope_version,
                "progress": "BLOCKED",
                "blocker": reason,
                "next_action": "RETAIN_LEGACY_PREDECESSOR",
                "successor_id": None,
                "queue_item_id": None,
                "queue_status": None,
                "provenance_state": self._legacy_provenance_state(None, document),
                "paper_only": True,
            }
            successor = None
            if classification == LEGACY_UNAMBIGUOUS and assessment.scope is not None:
                try:
                    # The successor is immutable and plan-validated, but its
                    # exact historical dataset binding must also be present in
                    # the store with a current attestation before enqueue.
                    successor = create_legacy_successor(
                        document,
                        source_candidate_id=candidate_id,
                        source_frozen_hash=frozen_hash,
                    )
                    evidence["provenance_state"] = self._legacy_provenance_state(successor.plan, document)
                    validation = validate_hermes_proposal(successor.proposal)
                    if not validation.accepted:
                        detail = "; ".join(validation.reasons) or "proposal rejected"
                        raise LegacyScopeError("PROPOSAL_REJECTED", detail)
                    self._validate_persisted_dataset_provenance(
                        successor.plan,
                        legacy_document=document,
                    )
                    queued_payload = _normalize_hypothesis_payload(
                        dict(validation.normalized or successor.proposal),
                        source_fallback=str(
                            getattr(self.bus, "author", "")
                            or getattr(self.bus, "source", "")
                            or "hermes"
                        ).strip()
                        or "hermes",
                    )
                    attestation_loader = getattr(self.store, "load_dataset_integrity_attestation", None)
                    attestation_hash = None
                    if callable(attestation_loader) and successor.plan.dataset_id and successor.plan.dataset_version:
                        try:
                            attestation = attestation_loader(
                                successor.plan.dataset_id,
                                successor.plan.dataset_version,
                            )
                        except Exception:
                            attestation = None
                        if isinstance(attestation, Mapping):
                            attestation_hash = str(attestation.get("attestation_hash", "")).strip() or None
                    queued_payload = _mark_generated_queue_payload(
                        queued_payload,
                        kind="legacy_scope_successor",
                        dataset_id=successor.plan.dataset_id,
                        dataset_version=successor.plan.dataset_version,
                        attestation_hash=attestation_hash,
                    )
                    dedupe_key = (
                        f"legacy-successor:{successor.successor_id}:"
                        f"{attestation_hash or 'unattested'}"
                    )
                    # Storage derives queue ids from the versioned dedupe key.
                    # Reuse an existing row so identical attestation retries
                    # cannot replace its immutable payload or queue history.
                    queue_item = self.bus.get(
                        "queue-" + hashlib.sha256(dedupe_key.encode("utf-8")).hexdigest()
                    )
                    if queue_item is None:
                        queue_item = self.bus.submit_hypothesis(
                            queued_payload,
                            dedupe_key=dedupe_key,
                            lineage=(successor.predecessor_candidate_id, successor.predecessor_frozen_hash),
                            available_at=now,
                        )
                    evidence.update(
                        {
                            "classification": successor.assessment.classification,
                            "reason_code": "LEGACY_SCOPE_NORMALIZED",
                            "scope_hash": successor.plan.market_scope_hash,
                            "scope_version": successor.plan.market_scope_version,
                            "progress": "ENQUEUED",
                            "blocker": None,
                            "next_action": "CLAIM_AND_PROCESS_CANONICAL_SUCCESSOR",
                            "successor_id": successor.successor_id,
                            "queue_item_id": queue_item.item_id if queue_item is not None else None,
                            "queue_status": queue_item.status.value if queue_item is not None else None,
                        }
                    )
                    persisted = self._persist_legacy_recovery_evidence(
                        evidence,
                        queue_item=queue_item,
                        now=now,
                    )
                except (AutonomousResearchError, LegacyScopeError, ResearchBusPermissionError, RuntimeError, TypeError, ValueError) as exc:
                    blocker = str(getattr(exc, "reason", "")).strip().upper() or "LEGACY_SCOPE_RECOVERY_FAILED"
                    evidence.update(
                        {
                            "reason_code": blocker,
                            "progress": "BLOCKED",
                            "blocker": blocker,
                            "next_action": "RETAIN_LEGACY_PREDECESSOR",
                            "provenance_state": self._legacy_provenance_state(
                                getattr(successor, "plan", None),
                                document,
                            ),
                        }
                    )
                    persisted = self._persist_legacy_recovery_evidence(evidence, now=now)
            else:
                persisted = self._persist_legacy_recovery_evidence(evidence, now=now)
            evidence["evidence_persisted"] = persisted
            output.append(evidence)
            if not persisted:
                # Do not advance beyond an evidence write that failed.  The
                # next cycle retries this candidate from the durable boundary.
                cursor_record = prior_cursor_record
                scan_aborted = True
                break
        if durable_pagination:
            # Once every prediction row in a fetched page was scanned, the
            # final lifecycle row is the safe boundary—even when intervening
            # rows belong to another market type.  If the page had more than
            # the per-cycle cap, retain the last scanned prediction row so
            # unscanned candidates in this page are not skipped.  An evidence
            # failure similarly retains the prior boundary.
            if not scan_aborted and records and len(candidates) <= recovery_limit:
                progress_record = records[-1]
            else:
                progress_record = cursor_record
            next_cursor: dict[str, str] | None = None
            if isinstance(progress_record, Mapping):
                raw_timestamp = progress_record.get("updated_at")
                if isinstance(raw_timestamp, datetime):
                    timestamp = ensure_utc(raw_timestamp).isoformat()
                else:
                    timestamp = str(raw_timestamp or "").strip()
                candidate_id = str(progress_record.get("candidate_id") or "").strip()
                if timestamp and candidate_id:
                    next_cursor = {
                        "updated_at": timestamp,
                        "candidate_id": candidate_id,
                    }
            next_state = dict(state)
            next_state["schema_version"] = "autonomous-legacy-recovery-v1"
            next_state["cursor"] = next_cursor
            try:
                state_setter(_LEGACY_RECOVERY_STATE_NAME, next_state)
            except (RuntimeError, TypeError, ValueError):
                # Evidence remains durable even if a transient state write
                # fails; retrying the page is safe because report keys dedupe.
                pass
        return tuple(output)
    @staticmethod
    def _next_dataset_job_name(plan_id: str) -> str:
        return _NEXT_DATASET_JOB_PREFIX + str(plan_id).strip()

    @staticmethod
    def _bounded_dataset_catalog(
        catalog: Mapping[str, Any] | None,
        *,
        dataset_id: str = "",
        dataset_version: str = "",
    ) -> dict[str, Any] | None:
        """Project catalog identity and aggregate facts without nested metadata."""
        if not isinstance(catalog, Mapping):
            return None
        summary: dict[str, Any] = {}
        for key in (
            "dataset_id",
            "dataset_version",
            "version",
            "provider",
            "instrument",
            "market_type",
            "timeframe",
            "start_timestamp",
            "end_timestamp",
            "row_count",
            "completeness",
            "quality",
            "source_type",
            "snapshot_id",
        ):
            value = catalog.get(key)
            if value is None:
                continue
            summary[key] = value.isoformat() if isinstance(value, datetime) else _compact_value(value)
        if not str(summary.get("dataset_id", "")).strip() and dataset_id:
            summary["dataset_id"] = dataset_id
        if not str(summary.get("dataset_version", summary.get("version", ""))).strip() and dataset_version:
            summary["dataset_version"] = dataset_version
        missing_ranges = catalog.get("missing_ranges")
        if missing_ranges is not None:
            if isinstance(missing_ranges, (list, tuple)):
                summary["missing_ranges_count"] = len(missing_ranges)
                summary["missing_ranges_digest"] = "sha256:" + hashlib.sha256(
                    _canonical_binding(missing_ranges).encode("utf-8")
                ).hexdigest()
            else:
                summary["missing_ranges"] = bool(missing_ranges)
        return summary

    @staticmethod
    def _bounded_dataset_attestation(
        attestation: Mapping[str, Any] | None,
        *,
        dataset_id: str = "",
        dataset_version: str = "",
    ) -> dict[str, Any] | None:
        """Project immutable attestation facts without constituent bindings."""
        if not isinstance(attestation, Mapping):
            return None
        summary: dict[str, Any] = {}
        for key in (
            "dataset_id",
            "dataset_version",
            "source_type",
            "market_type",
            "row_count",
            "observed_row_count",
            "completeness",
            "start_timestamp",
            "end_timestamp",
            "contamination_result",
            "provenance_version",
            "policy_version",
            "reason",
            "attestation_hash",
            "verified_at",
            "status",
        ):
            value = attestation.get(key)
            if value is None:
                continue
            summary[key] = value.isoformat() if isinstance(value, datetime) else _compact_value(value)
        if not str(summary.get("dataset_id", "")).strip() and dataset_id:
            summary["dataset_id"] = dataset_id
        if not str(summary.get("dataset_version", "")).strip() and dataset_version:
            summary["dataset_version"] = dataset_version

        bindings = attestation.get("constituent_bindings", attestation.get("constituents"))
        count: int | None = None
        for key in ("constituent_count", "constituents_count", "market_count"):
            value = attestation.get(key)
            if isinstance(value, int) and not isinstance(value, bool) and value >= 0:
                count = value
                break
        if count is None and isinstance(bindings, (list, tuple)):
            count = len(bindings)
        if count is not None:
            summary["constituent_count"] = count

        digest: str | None = None
        for key in (
            "canonical_digest",
            "constituent_bindings_digest",
            "constituent_digest",
            "bindings_digest",
        ):
            value = attestation.get(key)
            if value is not None and str(value).strip():
                digest = str(value).strip()
                break
        if digest is None and isinstance(bindings, (list, tuple)):
            digest = "sha256:" + hashlib.sha256(
                _canonical_binding(bindings).encode("utf-8")
            ).hexdigest()
        if digest is not None:
            summary["canonical_digest"] = digest
            summary["constituent_bindings_digest"] = digest
        return summary

    def _report_next_dataset_scheduler_error(
        self,
        exc: BaseException | str,
        now: datetime,
        *,
        plan_id: str | None = None,
        candidate_id: str | None = None,
    ) -> None:
        """Expose successor scheduling failures while allowing queue work to continue."""
        message = str(exc).strip() or type(exc).__name__
        code = type(exc).__name__.upper() if not isinstance(exc, str) else "NEXT_DATASET_JOB_SCHEDULER_ERROR"
        state_loader = getattr(self.store, "get_scheduler_state", None)
        state_setter = getattr(self.store, "set_scheduler_state", None)
        if callable(state_setter):
            try:
                current = state_loader(_NEXT_DATASET_SCHEDULER_STATE_NAME) if callable(state_loader) else None
                state = dict(current) if isinstance(current, Mapping) else {}
                state.update(
                    {
                        "status": "DEGRADED",
                        "last_error": message[:2_000],
                        "last_error_code": code,
                        "last_error_at": ensure_utc(now).isoformat(),
                    }
                )
                if plan_id:
                    state["plan_id"] = plan_id
                if candidate_id:
                    state["candidate_id"] = candidate_id
                state_setter(_NEXT_DATASET_SCHEDULER_STATE_NAME, state)
            except Exception:
                pass
        saver = getattr(self.store, "save_report_if_absent", None)
        if not callable(saver):
            return
        report_key = "|".join((code, message, str(plan_id or ""), str(candidate_id or "")))
        report_id = "autonomous-next-dataset-error-" + hashlib.sha256(report_key.encode("utf-8")).hexdigest()[:24]
        try:
            saver(
                report_id,
                {
                    "report_type": "autonomous_next_dataset_scheduler_error",
                    "blocker": "NEXT_DATASET_JOB_SCHEDULER_ERROR",
                    "reason_code": code,
                    "reason": message[:2_000],
                    "plan_id": plan_id,
                    "candidate_id": candidate_id,
                    "timestamp": ensure_utc(now).isoformat(),
                    "paper_only": True,
                },
                experiment_id=plan_id,
            )
        except Exception:
            pass

    @staticmethod
    def _strategy_contract(plan: ExperimentPlan) -> dict[str, Any]:
        """Return the immutable strategy material independent of data version."""
        document = dict(plan.as_dict())
        document.pop("plan_id", None)
        document.pop("hypothesis_id", None)
        selector = document.pop("dataset_selector", {})
        if isinstance(selector, Mapping):
            document["dataset_selector_contract"] = {
                str(key): value
                for key, value in selector.items()
                if str(key) not in {"dataset_id", "dataset_version", "version"}
            }
        return document

    @classmethod
    def _strategy_contract_digest(cls, plan: ExperimentPlan) -> str:
        return "sha256:" + hashlib.sha256(
            _canonical_binding(cls._strategy_contract(plan)).encode("utf-8")
        ).hexdigest()
    @staticmethod
    def _complete_polymarket_catalog(catalog: Any, *, dataset_id: str, version: str) -> bool:
        if not isinstance(catalog, Mapping):
            return False
        catalog_id = str(catalog.get("dataset_id", "")).strip()
        catalog_version = str(catalog.get("dataset_version", catalog.get("version", ""))).strip()
        if (
            catalog_id != dataset_id
            or catalog_version != version
            or not version
            or version.casefold() in _MUTABLE_DATASET_VERSION_ALIASES
            or str(catalog.get("source_type", "")).strip().upper() != "HISTORICAL"
            or str(catalog.get("market_type", "")).strip().lower() != MarketType.PREDICTION.value
            or str(catalog.get("instrument", "")).strip().upper() != "POLYMARKET"
        ):
            return False
        try:
            completeness = float(catalog.get("completeness", 0.0))
            row_count = catalog.get("row_count", 0)
        except (TypeError, ValueError, OverflowError):
            return False
        return (
            math.isfinite(completeness)
            and completeness >= 1.0
            and isinstance(row_count, int)
            and not isinstance(row_count, bool)
            and row_count > 0
            and not catalog.get("missing_ranges")
        )

    def _load_next_dataset_version(
        self,
        *,
        dataset_id: str,
        rejected_version: str,
    ) -> tuple[Mapping[str, Any], Mapping[str, Any]] | None:
        """Find one newer, exact, attested aggregate without touching crypto."""
        catalog_loader = getattr(self.store, "load_dataset_catalog", None)
        attestation_loader = getattr(self.store, "load_dataset_integrity_attestation", None)
        catalog_lister = getattr(self.store, "list_dataset_catalog", None)
        if not callable(catalog_loader) or not callable(attestation_loader) or not callable(catalog_lister):
            return None
        try:
            catalogs = catalog_lister(
                source_type="HISTORICAL",
                market_type=MarketType.PREDICTION.value,
                limit=256,
            )
        except TypeError:
            try:
                catalogs = catalog_lister(limit=256)
            except Exception:
                return None
        except Exception:
            return None
        if not isinstance(catalogs, Sequence):
            return None
        for listed in catalogs:
            if not isinstance(listed, Mapping):
                continue
            version = str(listed.get("dataset_version", listed.get("version", ""))).strip()
            if version == rejected_version or not version:
                continue
            # Re-load by exact identity rather than trusting a broad catalog
            # projection.  Forward/rolling rows never pass this source gate.
            try:
                catalog = catalog_loader(dataset_id, version)
            except Exception:
                continue
            if not self._complete_polymarket_catalog(catalog, dataset_id=dataset_id, version=version):
                continue
            try:
                attestation = attestation_loader(dataset_id, version)
            except Exception:
                # A crypto provider failure or an attestation read failure is
                # evidence for this job only; it must not stop the scheduler.
                continue
            if not isinstance(attestation, Mapping):
                continue
            if (
                str(attestation.get("dataset_id", "")).strip() != dataset_id
                or str(attestation.get("dataset_version", "")).strip() != version
                or str(attestation.get("status", "")).strip().upper() != "CURRENT"
                or str(attestation.get("contamination_result", "")).strip().upper() != "PASS"
                or not str(attestation.get("attestation_hash", "")).strip()
            ):
                continue
            return dict(catalog), dict(attestation)
        return None

    def _predecessor_proposal(self, plan_id: str) -> Mapping[str, Any] | None:
        lister = getattr(self.store, "list_research_items", None)
        if not callable(lister):
            return None
        try:
            items = lister(limit=4096)
        except Exception:
            return None
        if not isinstance(items, Sequence):
            return None
        for item in items:
            if not isinstance(item, Mapping):
                continue
            payload = item.get("payload")
            if not isinstance(payload, Mapping):
                continue
            item_plan_id = str(payload.get("plan_id", "")).strip()
            nested = payload.get("experiment_plan")
            if not item_plan_id and isinstance(nested, Mapping):
                item_plan_id = str(nested.get("plan_id", "")).strip()
            if item_plan_id == plan_id:
                return dict(payload)
        return None

    def _rejection_plan(
        self,
        item: ResearchQueueItem | Mapping[str, Any] | None,
        result: Mapping[str, Any],
    ) -> tuple[ExperimentPlan, str] | None:
        plan_id = str(result.get("plan_id", "")).strip()
        item_payload = (
            item.payload
            if isinstance(item, ResearchQueueItem)
            else item
            if isinstance(item, Mapping)
            else None
        )
        if not plan_id and isinstance(item_payload, Mapping):
            plan_id = str(item_payload.get("plan_id", "")).strip()
        plan_record = self.store.load_experiment_plan(plan_id) if plan_id else None
        raw_plan = plan_record.get("plan") if isinstance(plan_record, Mapping) else None
        if not isinstance(raw_plan, Mapping) and isinstance(item_payload, Mapping):
            raw_plan = item_payload.get("experiment_plan")
        if not isinstance(raw_plan, Mapping):
            return None
        try:
            plan = ExperimentPlan.from_mapping(
                raw_plan,
                hypothesis_id=(
                    str(plan_record.get("hypothesis_id", "")).strip()
                    if isinstance(plan_record, Mapping)
                    else str(result.get("hypothesis_id", "")).strip()
                ) or None,
            )
        except (ExperimentPlanError, TypeError, ValueError):
            return None
        if plan_id and plan.plan_id != plan_id:
            return None
        expected_hash = str(
            plan_record.get("plan_hash", "")
            if isinstance(plan_record, Mapping)
            else result.get("plan_hash", "")
        ).strip()
        if expected_hash and expected_hash != plan.plan_hash:
            return None
        candidates = result.get("candidate_results")
        candidate_ids = [
            str(candidate.get("candidate_id", "")).strip()
            for candidate in candidates
            if isinstance(candidate, Mapping) and str(candidate.get("candidate_id", "")).strip()
        ] if isinstance(candidates, Sequence) and not isinstance(candidates, (str, bytes)) else []
        if not candidate_ids and isinstance(item_payload, Mapping):
            candidate_id = str(item_payload.get("candidate_id", "")).strip()
            if candidate_id:
                candidate_ids.append(candidate_id)
        candidate_id = candidate_ids[0] if candidate_ids else ""
        if not candidate_id:
            return None
        lifecycle_loader = getattr(self.store, "load_candidate_lifecycle", None)
        if callable(lifecycle_loader):
            lifecycle = lifecycle_loader(candidate_id)
            if not isinstance(lifecycle, Mapping):
                return None
            lifecycle_payload = lifecycle.get("payload")
            if not isinstance(lifecycle_payload, Mapping):
                return None
            if str(lifecycle.get("stage", "")).strip().upper() != CandidateStage.REJECTED.value:
                return None
            relation = str(lifecycle_payload.get("successor_relation", "")).strip().upper()
            generated = _generated_queue_provenance(lifecycle_payload)
            if relation == "LEGACY_SCOPE_SUCCESSOR" or (
                isinstance(generated, Mapping)
                and str(generated.get("kind", "")).strip() == "legacy_scope_successor"
            ):
                return None
        if isinstance(item_payload, Mapping):
            relation = str(item_payload.get("successor_relation", "")).strip().upper()
            generated = _generated_queue_provenance(item_payload)
            if relation == "LEGACY_SCOPE_SUCCESSOR" or (
                isinstance(generated, Mapping)
                and str(generated.get("kind", "")).strip() == "legacy_scope_successor"
            ):
                return None
        if (
            plan.market_type is not MarketType.PREDICTION
            or str(plan.dataset_id or "").strip() != "Polymarket-historical"
            or not str(plan.dataset_version).strip()
            or str(plan.dataset_version).casefold() in _MUTABLE_DATASET_VERSION_ALIASES
        ):
            return None
        return plan, candidate_id


    def _waiting_job_payload(
        self,
        plan: ExperimentPlan,
        *,
        candidate_id: str,
        result: Mapping[str, Any],
        now: datetime,
    ) -> dict[str, Any]:
        dataset_id = str(plan.dataset_id or "").strip()
        rejected_version = str(plan.dataset_version).strip()
        catalog_loader = getattr(self.store, "load_dataset_catalog", None)
        attestation_loader = getattr(self.store, "load_dataset_integrity_attestation", None)
        try:
            catalog = catalog_loader(dataset_id, rejected_version) if callable(catalog_loader) else None
        except Exception:
            catalog = None
        try:
            attestation = attestation_loader(dataset_id, rejected_version) if callable(attestation_loader) else None
        except Exception:
            attestation = None
        contract = self._strategy_contract(plan)
        contract_digest = self._strategy_contract_digest(plan)
        next_check = ensure_utc(now) + timedelta(seconds=60)
        return {
            "schema_version": "autonomous-next-dataset-version-v1",
            "job_kind": "POLYMARKET_DATASET_VERSION_SUCCESSOR",
            "progress": "WAITING_FOR_NEW_DATASET_VERSION",
            "predecessor_plan_id": plan.plan_id,
            "predecessor_plan_hash": plan.plan_hash,
            "predecessor_hypothesis_id": plan.hypothesis_id,
            "predecessor_candidate_id": candidate_id,
            "dataset_id": dataset_id,
            "old_dataset_version": rejected_version,
            "rejected_dataset_version": rejected_version,
            "rejected_result": {
                "reason_code": result.get("reason_code"),
                "blocker": result.get("blocker"),
                "accepted": result.get("accepted"),
            },
            "rejected_dataset_catalog": self._bounded_dataset_catalog(
                catalog,
                dataset_id=dataset_id,
                dataset_version=rejected_version,
            ),
            "rejected_dataset_attestation": self._bounded_dataset_attestation(
                attestation,
                dataset_id=dataset_id,
                dataset_version=rejected_version,
            ),
            "required_predicate": {
                "dataset_id": dataset_id,
                "version_distinct_from": rejected_version,
                "source_type": "HISTORICAL",
                "market_type": MarketType.PREDICTION.value,
                "instrument": "POLYMARKET",
                "catalog": {
                    "exact_identity": True,
                    "completeness_min": 1.0,
                    "row_count_min": 1,
                    "missing_ranges": False,
                },
                "attestation": {
                    "status": "CURRENT",
                    "contamination_result": "PASS",
                },
                "rolling_collection_satisfies": False,
            },
            "strategy_contract": contract,
            "strategy_contract_digest": contract_digest,
            "schedule_trigger": _NEXT_DATASET_JOB_TRIGGER,
            "schedule_cadence": _NEXT_DATASET_JOB_CADENCE,
            "schedule_cadence_seconds": 60,
            "next_check_at": next_check.isoformat(),
            "next_run_at": next_check.isoformat(),
            "last_checked_at": ensure_utc(now).isoformat(),
            "dedupe_namespace": "successor",
            "successor_dedupe_template": "successor:{predecessor_plan_id}:{new_dataset_version}",
            "paper_only": True,
            "research_only": True,
        }

    def _create_waiting_next_dataset_job(
        self,
        plan: ExperimentPlan,
        *,
        candidate_id: str,
        result: Mapping[str, Any],
        now: datetime,
    ) -> Mapping[str, Any] | None:
        """Create one durable waiting job; caller may already hold a tx."""
        job_name = self._next_dataset_job_name(plan.plan_id)
        existing = self.store.get_operator_job(job_name)
        if existing is not None:
            return existing
        payload = self._waiting_job_payload(plan, candidate_id=candidate_id, result=result, now=now)
        self.store.set_operator_job(
            job_name,
            _NEXT_DATASET_JOB_STATUS_WAITING,
            payload,
            resumable=True,
            timestamp=now,
        )
        return self.store.get_operator_job(job_name)

    def _maybe_create_waiting_next_dataset_job(
        self,
        item: ResearchQueueItem,
        result: Mapping[str, Any],
        now: datetime,
    ) -> None:
        if (
            result.get("accepted") is not False
            or str(result.get("blocker", "")).strip().upper() != "NO_SUPPORTED_EDGE"
        ):
            return
        try:
            resolved = self._rejection_plan(item, result)
            if resolved is None:
                return
            plan, candidate_id = resolved
            self._create_waiting_next_dataset_job(
                plan,
                candidate_id=candidate_id,
                result=result,
                now=now,
            )
        except Exception as exc:
            # The queue result and rejection remain authoritative if job
            # creation cannot be persisted in this tick, but the scheduler
            # failure must remain visible to operators.
            self._report_next_dataset_scheduler_error(
                exc,
                now,
                plan_id=str(result.get("plan_id", "")).strip() or None,
                candidate_id=str(result.get("candidate_id", "")).strip() or None,
            )

    def _build_dataset_successor(
        self,
        plan: ExperimentPlan,
        *,
        candidate_id: str,
        catalog: Mapping[str, Any],
        attestation: Mapping[str, Any],
        job_payload: Mapping[str, Any],
    ) -> tuple[ExperimentPlan, dict[str, Any], str]:
        version = str(catalog.get("dataset_version", catalog.get("version", ""))).strip()
        old_hash = str(job_payload.get("predecessor_plan_hash", plan.plan_hash)).strip()
        identity = {
            "schema": "axiom-polymarket-dataset-successor-v1",
            "predecessor_plan_id": plan.plan_id,
            "predecessor_plan_hash": old_hash,
            "predecessor_hypothesis_id": plan.hypothesis_id,
            "predecessor_candidate_id": candidate_id,
            "dataset_id": str(plan.dataset_id or "").strip(),
            "dataset_version": version,
        }
        token = hashlib.sha256(_canonical_binding(identity).encode("utf-8")).hexdigest()[:24]
        hypothesis_id = "hypothesis-successor-" + token
        plan_id = "plan-successor-" + token
        plan_document = plan.as_dict()
        plan_document["plan_id"] = plan_id
        plan_document["hypothesis_id"] = hypothesis_id
        selector = dict(plan_document.get("dataset_selector", {}))
        selector["dataset_id"] = str(plan.dataset_id or "").strip()
        selector["dataset_version"] = version
        plan_document["dataset_selector"] = selector
        successor = ExperimentPlan.from_mapping(plan_document, hypothesis_id=hypothesis_id)
        contract_digest = self._strategy_contract_digest(successor)
        if contract_digest != str(job_payload.get("strategy_contract_digest", "")).strip():
            raise AutonomousResearchError(
                "STRATEGY_CONTRACT_CHANGED",
                "successor dataset version changed the immutable strategy contract",
            )
        source = self._predecessor_proposal(plan.plan_id) or {}
        attestation_payload = self._bounded_dataset_attestation(
            attestation,
            dataset_id=str(plan.dataset_id or "").strip(),
            dataset_version=version,
        ) or {}
        proposal = dict(successor.as_dict())
        for name, fallback in (
            ("statement", "Re-evaluate the immutable Polymarket strategy on a new historical dataset version."),
            ("source", "axiom-autonomous-dataset-successor"),
            ("tests", ["bounded chronological backtest and validation"]),
            ("time_split", plan.methodology.get("time_split", "train-validation-holdout")),
        ):
            value = source.get(name, fallback)
            if name == "tests" and (
                not isinstance(value, (list, tuple))
                or not value
                or any(not isinstance(test, str) or not test.strip() for test in value)
            ):
                value = fallback
            proposal[name] = value
        proposal.update(
            {
                "proposal_id": hypothesis_id,
                "hypothesis_id": hypothesis_id,
                "dataset_id": successor.dataset_id,
                "dataset_version": successor.dataset_version,
                "market_type": successor.market_type.value,
                "experiment_plan": successor.as_dict(),
                "dataset_attestation": dict(attestation_payload),
                "strategy_contract_digest": contract_digest,
                "successor_relation": "POLYMARKET_DATASET_VERSION_SUCCESSOR",
                "dataset_successor_predecessor": {
                    "plan_id": plan.plan_id,
                    "plan_hash": plan.plan_hash,
                    "candidate_id": candidate_id,
                },
                "paper_only": True,
            }
        )
        validation = validate_hermes_proposal(proposal, store=self.store)
        if not validation.accepted:
            detail = "; ".join(validation.reasons) or "successor proposal rejected"
            raise AutonomousResearchError("SUCCESSOR_PROPOSAL_INVALID", detail)
        normalized = dict(validation.normalized or proposal)
        validated_plan = ExperimentPlan.from_proposal(normalized)
        if (
            validated_plan.plan_id != plan_id
            or validated_plan.hypothesis_id != hypothesis_id
            or validated_plan.dataset_version != version
            or validated_plan.plan_hash != successor.plan_hash
        ):
            raise AutonomousResearchError(
                "SUCCESSOR_PROPOSAL_INVALID",
                "validated successor identity or dataset binding changed",
            )
        queued_payload = _normalize_hypothesis_payload(
            normalized,
            source_fallback=str(getattr(self.bus, "author", "") or "hermes"),
        )
        queued_payload = _mark_generated_queue_payload(
            queued_payload,
            kind=_NEXT_DATASET_GENERATED_KIND,
            dataset_id=validated_plan.dataset_id,
            dataset_version=validated_plan.dataset_version,
            attestation_hash=str(attestation.get("attestation_hash", "")).strip() or None,
        )
        dedupe_key = f"successor:{plan.plan_id}:{version}"
        return validated_plan, queued_payload, dedupe_key

    @staticmethod
    def _next_dataset_job_is_due(job: Mapping[str, Any], now: datetime) -> bool:
        """Return whether a persisted successor job may be polled now."""
        if str(job.get("status", "")).strip().upper() != _NEXT_DATASET_JOB_STATUS_WAITING:
            return True
        payload = job.get("payload")
        if not isinstance(payload, Mapping):
            return True
        next_check = parse_timestamp(payload.get("next_check_at"))
        # Jobs written before the cadence field existed (or with a malformed
        # value) remain immediately eligible rather than becoming stranded.
        return next_check is None or ensure_utc(now) >= next_check

    def _advance_waiting_next_dataset_job(self, job: Mapping[str, Any], now: datetime) -> None:
        if not self._next_dataset_job_is_due(job, now):
            return
        job_name = str(job.get("job_name", "")).strip()
        if not job_name:
            return
        payload = job.get("payload")
        payload = dict(payload) if isinstance(payload, Mapping) else {}
        status = str(job.get("status", "")).strip().upper()
        if status == _NEXT_DATASET_JOB_STATUS_ENQUEUED:
            queue_id = str(payload.get("queue_item_id", "")).strip()
            queued = self.bus.get(queue_id) if queue_id else None
            if queued is None or queued.status.value not in {"COMPLETED", "ACCEPTED", "REJECTED", "FAILED"}:
                return
            payload.update(
                {
                    "progress": "COMPLETED" if queued.status.value in {"COMPLETED", "ACCEPTED"} else "FAILED",
                    "queue_status": queued.status.value,
                    "successor_result": dict(queued.result) if isinstance(queued.result, Mapping) else None,
                    "last_checked_at": ensure_utc(now).isoformat(),
                }
            )
            self.store.set_operator_job(
                job_name,
                _NEXT_DATASET_JOB_STATUS_COMPLETED
                if queued.status.value in {"COMPLETED", "ACCEPTED"}
                else _NEXT_DATASET_JOB_STATUS_FAILED,
                payload,
                resumable=False,
                timestamp=now,
            )
            return
        if status != _NEXT_DATASET_JOB_STATUS_WAITING:
            return
        dataset_id = str(payload.get("dataset_id", "Polymarket-historical")).strip()
        old_version = str(
            payload.get("rejected_dataset_version", payload.get("old_dataset_version", ""))
        ).strip()
        plan_id = str(payload.get("predecessor_plan_id", "")).strip()
        plan_record = self.store.load_experiment_plan(plan_id) if plan_id else None
        raw_plan = plan_record.get("plan") if isinstance(plan_record, Mapping) else payload.get("predecessor_plan")
        if not isinstance(raw_plan, Mapping):
            return
        try:
            plan = ExperimentPlan.from_mapping(
                raw_plan,
                hypothesis_id=str(
                    (plan_record or {}).get("hypothesis_id", payload.get("predecessor_hypothesis_id", ""))
                ).strip() or None,
            )
        except (ExperimentPlanError, TypeError, ValueError):
            return
        if (
            plan.plan_id != plan_id
            or str(plan.dataset_id or "").strip() != dataset_id
            or str(plan.dataset_version).strip() != old_version
        ):
            return
        found = self._load_next_dataset_version(dataset_id=dataset_id, rejected_version=old_version)
        next_check = ensure_utc(now) + timedelta(seconds=60)
        if found is None:
            payload.update(
                {
                    "progress": "WAITING_FOR_NEW_DATASET_VERSION",
                    "last_checked_at": ensure_utc(now).isoformat(),
                    "next_check_at": next_check.isoformat(),
                    "next_run_at": next_check.isoformat(),
                }
            )
            self.store.set_operator_job(
                job_name,
                _NEXT_DATASET_JOB_STATUS_WAITING,
                payload,
                resumable=True,
                timestamp=now,
            )
            return
        catalog, attestation = found
        candidate_id = str(payload.get("predecessor_candidate_id", "")).strip()
        try:
            successor, queued_payload, dedupe_key = self._build_dataset_successor(
                plan,
                candidate_id=candidate_id,
                catalog=catalog,
                attestation=attestation,
                job_payload=payload,
            )
            self.store.save_experiment_plan(
                successor.plan_id,
                successor.as_dict(),
                hypothesis_id=successor.hypothesis_id,
                plan_hash=successor.plan_hash,
                status="PENDING",
                timestamp=now,
            )
            queue_id = "queue-" + hashlib.sha256(dedupe_key.encode("utf-8")).hexdigest()
            queued = self.bus.get(queue_id)
            if queued is None:
                queued = self.bus.submit_proposal(
                    queued_payload,
                    dedupe_key=dedupe_key,
                    lineage=(plan.plan_id, plan.plan_hash, candidate_id),
                    available_at=now,
                )
            payload.update(
                {
                    "progress": "ENQUEUED",
                    "successor_plan_id": successor.plan_id,
                    "successor_plan_hash": successor.plan_hash,
                    "successor_hypothesis_id": successor.hypothesis_id,
                    "successor_dataset_version": successor.dataset_version,
                    "successor_attestation_hash": attestation.get("attestation_hash"),
                    "queue_item_id": queued.item_id,
                    "queue_status": queued.status.value,
                    "dedupe_key": dedupe_key,
                    "next_check_at": None,
                    "next_run_at": now.isoformat(),
                    "last_checked_at": ensure_utc(now).isoformat(),
                }
            )
            self.store.set_operator_job(
                job_name,
                _NEXT_DATASET_JOB_STATUS_ENQUEUED,
                payload,
                resumable=True,
                timestamp=now,
            )
        except (AutonomousResearchError, ResearchBusPermissionError, ExperimentPlanError, RuntimeError, TypeError, ValueError) as exc:
            payload.update(
                {
                    "progress": "WAITING_FOR_NEW_DATASET_VERSION",
                    "last_error": str(exc),
                    "last_checked_at": ensure_utc(now).isoformat(),
                    "next_check_at": next_check.isoformat(),
                    "next_run_at": next_check.isoformat(),
                }
            )
            self.store.set_operator_job(
                job_name,
                _NEXT_DATASET_JOB_STATUS_WAITING,
                payload,
                last_error=str(exc),
                resumable=True,
                timestamp=now,
            )

    def _poll_waiting_next_dataset_jobs(self, now: datetime) -> None:
        lister = getattr(self.store, "list_operator_jobs", None)
        if callable(lister):
            try:
                jobs = lister()
            except Exception as exc:
                self._report_next_dataset_scheduler_error(exc, now)
                jobs = ()
            if isinstance(jobs, Sequence):
                for job in jobs:
                    if not isinstance(job, Mapping):
                        continue
                    name = str(job.get("job_name", "")).strip()
                    if not name.startswith(_NEXT_DATASET_JOB_PREFIX):
                        continue
                    try:
                        with self.store.transaction():
                            current = self.store.get_operator_job(name)
                            if isinstance(current, Mapping) and self._next_dataset_job_is_due(current, now):
                                self._advance_waiting_next_dataset_job(current, now)
                    except Exception as exc:
                        self._report_next_dataset_scheduler_error(exc, now)

    def _backfill_next_dataset_job(self, now: datetime) -> None:
        lister = getattr(self.store, "list_experiment_plans", None)
        if not callable(lister):
            return
        try:
            plans = lister(limit=256, newest_first=True)
        except TypeError:
            try:
                plans = lister(limit=256)
            except Exception as exc:
                self._report_next_dataset_scheduler_error(exc, now)
                return
        except Exception as exc:
            self._report_next_dataset_scheduler_error(exc, now)
            return
        if not isinstance(plans, Sequence):
            return
        for record in plans:
            if not isinstance(record, Mapping):
                continue
            result = record.get("result")
            if not isinstance(result, Mapping):
                continue
            if (
                result.get("accepted") is not False
                or str(result.get("blocker", "")).strip().upper() != "NO_SUPPORTED_EDGE"
            ):
                continue
            plan_id = str(record.get("plan_id", "")).strip()
            raw_plan = record.get("plan")
            if not plan_id or not isinstance(raw_plan, Mapping):
                continue
            item: ResearchQueueItem | Mapping[str, Any] | None = self._predecessor_proposal(plan_id)
            try:
                resolved = self._rejection_plan(item, result)
            except Exception as exc:
                self._report_next_dataset_scheduler_error(exc, now, plan_id=plan_id)
                continue
            if resolved is None:
                continue
            plan, candidate_id = resolved
            job_name = self._next_dataset_job_name(plan.plan_id)
            try:
                with self.store.transaction():
                    if self.store.get_operator_job(job_name) is not None:
                        continue
                    self._create_waiting_next_dataset_job(
                        plan,
                        candidate_id=candidate_id,
                        result=result,
                        now=now,
                    )
                return
            except Exception as exc:
                self._report_next_dataset_scheduler_error(
                    exc,
                    now,
                    plan_id=plan.plan_id,
                    candidate_id=candidate_id,
                )
                continue

    def _schedule_next_dataset_jobs(self, now: datetime) -> None:
        """Poll resumable successors, then backfill only the latest rejection."""
        self._poll_waiting_next_dataset_jobs(now)
        self._backfill_next_dataset_job(now)

    def process_pending(self, *, worker: str = "research-queue", now: datetime | None = None) -> AutonomousQueueCycle:
        """Claim at most the configured bounded number of items.

        Candidate, plan, budget, and queue completion writes share one SQLite
        transaction.  A crash before commit therefore leaves the lease to
        expire and retries the same deterministic identifiers without creating
        duplicate experiments or lifecycle transitions.
        """
        current = ensure_utc(now or self.clock())
        legacy_recovery = self._recover_legacy_predecessors(current)
        self._enqueue_predeclared_from_persisted_scope(current)
        self._schedule_next_dataset_jobs(current)
        released = self.bus.resume_expired(now=current)
        results: list[Mapping[str, Any]] = []
        claimed = 0
        completed = 0
        rejected = 0
        failed = 0
        for _ in range(self.config.max_items_per_cycle):
            item = self.bus.claim(worker, lease_seconds=self.config.lease_seconds, now=current)
            if item is None:
                break
            claimed += 1
            phase_index = 0

            def phase_event(stage: str, detail: Any | None = None) -> None:
                nonlocal phase_index
                phase_index += 1
                self.store.record_research_queue_event(
                    item.item_id,
                    stage,
                    detail,
                    timestamp=current + timedelta(microseconds=phase_index),
                )
            try:
                with self.store.transaction():
                    phase_event("CLAIM", {"worker": worker, "item_type": item.item_type})
                    phase_event("VALIDATE", {"item_type": item.item_type})
                    result = self._process_item(item, current)
                    result = _bounded_queue_result(result)
                    try:
                        self._advance_campaign_after_result(item, result, current)
                    except (RuntimeError, TypeError, ValueError, KeyError) as campaign_error:
                        campaign_id = str(item.payload.get("campaign_id", "")).strip()
                        if campaign_id:
                            campaign_job = self.campaign_job_name(campaign_id)
                            campaign_record = self.store.get_operator_job(campaign_job)
                            campaign_payload = dict(campaign_record.get("payload") or {}) if isinstance(campaign_record, Mapping) else {}
                            campaign_payload["status"] = "SOFTWARE_OR_INPUT_ERROR"
                            campaign_payload["last_result"] = {
                                "trial_id": item.payload.get("campaign_trial_id"),
                                "status": "SOFTWARE_OR_INPUT_ERROR",
                                "reason": str(campaign_error),
                            }
                            self.store.set_operator_job(
                                campaign_job,
                                "SOFTWARE_OR_INPUT_ERROR",
                                campaign_payload,
                                resumable=False,
                                timestamp=current,
                            )
                    phase_event(
                        "ACCEPT" if result.get("accepted") is not False else "REJECT",
                        {"reason_code": result.get("reason_code")},
                    )
                    for stage in ("BOUNDED_EXPERIMENT", "TEST", "RESULT", "LIFECYCLE"):
                        phase_event(stage, {"item_type": item.item_type})
                    accepted = result.get("accepted") is not False
                    if not accepted:
                        self._maybe_create_waiting_next_dataset_job(item, result, current)
                    phase_event(
                        "COMPLETE",
                        {"item_type": item.item_type, "accepted": accepted},
                    )
                    self.bus.complete(
                        item.item_id,
                        status=ResearchQueueStatus.COMPLETED if accepted else ResearchQueueStatus.REJECTED,
                        result=result,
                        error=None if accepted else str(result.get("reason") or result.get("status") or "rejected"),
                        worker=worker,
                        now=current + timedelta(microseconds=phase_index + 1),
                    )
                if accepted:
                    completed += 1
                else:
                    rejected += 1
                results.append(result)
            except AutonomousResearchError as exc:
                result = _bounded_queue_result(
                    {
                        "accepted": False,
                        "reason_code": exc.reason,
                        "reason": exc.detail,
                        "item_type": item.item_type,
                        "item_id": item.item_id,
                        "paper_only": True,
                    }
                )
                try:
                    self._advance_campaign_after_result(item, result, current)
                except (RuntimeError, TypeError, ValueError, KeyError):
                    pass
                try:
                    with self.store.transaction():
                        phase_event(
                            "REJECT",
                            {"reason_code": exc.reason, "item_type": item.item_type},
                        )
                        self.bus.complete(
                            item.item_id,
                            status=ResearchQueueStatus.REJECTED,
                            result=result,
                            error=str(exc),
                            worker=worker,
                            now=current + timedelta(microseconds=phase_index + 1),
                        )
                    rejected += 1
                    results.append(result)
                except RuntimeError:
                    # The lease may have expired while an operator paused the
                    # process.  The storage lease owner remains authoritative;
                    # a later cycle will release and reclaim it safely.
                    continue
            except Exception as exc:
                result = _bounded_queue_result(
                    {
                        "accepted": False,
                        "reason_code": "PROCESSING_FAILED",
                        "reason": str(exc),
                        "item_type": item.item_type,
                        "item_id": item.item_id,
                        "paper_only": True,
                    }
                )
                try:
                    self._advance_campaign_after_result(item, result, current)
                except (RuntimeError, TypeError, ValueError, KeyError):
                    pass
                try:
                    with self.store.transaction():
                        phase_event(
                            "FAILED",
                            {"reason_code": "PROCESSING_FAILED", "item_type": item.item_type},
                        )
                        self.bus.complete(
                            item.item_id,
                            status=ResearchQueueStatus.FAILED,
                            result=result,
                            error=str(exc),
                            worker=worker,
                            now=current + timedelta(microseconds=phase_index + 1),
                        )
                    failed += 1
                    results.append(result)
                except RuntimeError:
                    continue
        return AutonomousQueueCycle(
            released,
            claimed,
            completed,
            rejected,
            failed,
            tuple(results),
            tuple(legacy_recovery),
        )

    def _materialized_observation_binding(
        self,
        candidate_id: str,
        payload: Mapping[str, Any],
    ) -> tuple[Any, ExperimentPlan, Mapping[str, Any]] | None:
        """Resolve a schema intent only when every immutable binding agrees."""
        if not bool(payload.get("paper_observation_intent")):
            return None
        intent_id = str(payload.get("paper_observation_intent_id", "")).strip()
        if not intent_id:
            return None
        plan_id = str(payload.get("plan_id", "")).strip()
        plan_record = self.store.load_experiment_plan(plan_id) if plan_id else None
        raw_plan = plan_record.get("plan") if isinstance(plan_record, Mapping) else None
        if not isinstance(raw_plan, Mapping):
            return None
        try:
            plan = ExperimentPlan.from_mapping(
                raw_plan,
                hypothesis_id=str(payload.get("hypothesis_id", "")).strip() or None,
            )
            if plan.market_type is not MarketType.PREDICTION:
                return None
            if str(payload.get("plan_hash", "")).strip() != plan.plan_hash:
                return None
            self._validate_persisted_dataset_provenance(plan)
            attestation_loader = getattr(self.store, "load_dataset_integrity_attestation", None)
            attestation = attestation_loader(plan.dataset_id, plan.dataset_version) if callable(attestation_loader) else None
            if not isinstance(attestation, Mapping):
                return None
        except (AutonomousResearchError, ExperimentPlanError, TypeError, ValueError, RuntimeError):
            return None

        registry = ForwardTestRegistry(self.store)
        expected_intent_id = "observation-intent-" + candidate_id
        if intent_id != expected_intent_id:
            return None
        intent = registry.get(intent_id)
        if intent is None or str(intent.experiment_id) != expected_intent_id:
            return None
        intent_config = intent.config if isinstance(intent.config, Mapping) else {}
        if (
            intent_config.get("observation_intent") is not True
            or intent_config.get("market_authority_required") is not False
            or str(intent_config.get("candidate_id", "")).strip() != candidate_id
            or str(intent_config.get("plan_id", "")).strip() != plan.plan_id
            or str(intent_config.get("plan_hash", "")).strip() != plan.plan_hash
            or intent.allowed_markets
        ):
            return None
        spec_candidates: list[Any] = []
        legacy_spec = registry.get("forward-" + candidate_id)
        if legacy_spec is not None:
            spec_candidates.append(legacy_spec)
        spec_candidates.extend(
            item
            for item in registry.list()
            if str(getattr(item, "experiment_id", "")).startswith("forward-" + candidate_id + "-")
        )
        spec = None
        for candidate_spec in spec_candidates:
            config = candidate_spec.config if isinstance(candidate_spec.config, Mapping) else {}
            if (
                str(config.get("candidate_id", "")).strip() == candidate_id
                and str(config.get("plan_id", "")).strip() == plan.plan_id
                and str(config.get("plan_hash", "")).strip() == plan.plan_hash
                and config.get("observation_intent") is True
                and config.get("market_authority_required") is True
                and candidate_spec.allowed_markets
                and len(candidate_spec.allowed_markets) <= PAPER_MARKET_AUTHORITY_CAP
            ):
                spec = candidate_spec
                break
        if spec is None:
            return None
        config = spec.config if isinstance(spec.config, Mapping) else {}
        expected_scope = _scope_binding(plan)
        for name, expected in expected_scope.items():
            if _canonical_binding(intent_config.get(name)) != _canonical_binding(expected):
                return None
            if _canonical_binding(config.get(name)) != _canonical_binding(expected):
                return None
            if _canonical_binding(payload.get(name)) != _canonical_binding(expected):
                return None
        for name, expected in (
            ("dataset_id", plan.dataset_id),
            ("dataset_version", plan.dataset_version),
        ):
            if _canonical_binding(intent_config.get(name)) != _canonical_binding(expected):
                return None
            if _canonical_binding(config.get(name)) != _canonical_binding(expected):
                return None
            if _canonical_binding(payload.get(name)) != _canonical_binding(expected):
                return None
        candidate_strategy = payload.get("strategy")
        forward_strategy = config.get("strategy_document")
        if not isinstance(candidate_strategy, Mapping) or not isinstance(forward_strategy, Mapping):
            return None
        candidate_strategy = dict(candidate_strategy)
        forward_strategy = dict(forward_strategy)
        candidate_strategy.pop("strategy_id", None)
        forward_strategy.pop("strategy_id", None)
        if _canonical_binding(candidate_strategy) != _canonical_binding(forward_strategy):
            return None
        model_required = _rolling_prediction_model_required(candidate_strategy)
        candidate_model = (
            dict(_ROLLING_MODEL_FREE_DOCUMENT)
            if model_required is False
            else plan.model_for() or {"type": "deterministic"}
        )
        forward_model = config.get("model_document")
        if not isinstance(forward_model, Mapping):
            return None
        intent_strategy = intent_config.get("strategy_document")
        intent_model = intent_config.get("model_document")
        if not isinstance(intent_strategy, Mapping) or not isinstance(intent_model, Mapping):
            return None
        intent_strategy = dict(intent_strategy)
        intent_strategy.pop("strategy_id", None)
        if _canonical_binding(candidate_strategy) != _canonical_binding(intent_strategy):
            return None
        if _canonical_binding(candidate_model) != _canonical_binding(forward_model):
            return None
        if _canonical_binding(candidate_model) != _canonical_binding(intent_model):
            return None
        resolution_loader = getattr(self.store, "load_market_scope_resolution", None)
        resolution = resolution_loader(candidate_id) if callable(resolution_loader) else None
        if resolution is None:
            return None
        resolution_document = resolution if isinstance(resolution, Mapping) else {}
        status = str(
            resolution_document.get("status", getattr(resolution, "status", ""))
        ).strip().upper()
        resolved_hash = str(
            resolution_document.get("scope_hash", getattr(resolution, "scope_hash", ""))
        ).strip()
        resolved_version = str(
            resolution_document.get("scope_version", getattr(resolution, "scope_version", ""))
        ).strip()
        matched = resolution_document.get("matched_markets", getattr(resolution, "matched_markets", ()))
        matched_ids = tuple(
            str(
                item.get("market_id", "")
                if isinstance(item, Mapping)
                else getattr(item, "market_id", "")
            ).strip()
            for item in matched
            if str(
                item.get("market_id", "")
                if isinstance(item, Mapping)
                else getattr(item, "market_id", "")
            ).strip()
        )
        if (
            status != "MATCHED"
            or resolved_hash != plan.market_scope_hash
            or resolved_version != plan.market_scope_version
            or matched_ids != tuple(spec.allowed_markets)
        ):
            return None
        existing_attestation = payload.get("dataset_attestation")
        if existing_attestation is not None and _canonical_binding(existing_attestation) != _canonical_binding(attestation):
            return None
        config_attestation = config.get("dataset_attestation")
        if config_attestation is not None and _canonical_binding(config_attestation) != _canonical_binding(attestation):
            return None
        return spec, plan, dict(attestation)

    def _reassess_schema_observation_candidate(
        self,
        record: Mapping[str, Any],
        now: datetime,
    ) -> Mapping[str, Any] | None:
        candidate_id = str(record.get("candidate_id", "")).strip()
        payload = record.get("payload")
        if not candidate_id or not isinstance(payload, Mapping):
            return None
        bound = self._materialized_observation_binding(candidate_id, payload)
        if bound is None:
            return None
        spec, _, attestation = bound
        observations = self.store.list_paper_observations(
            spec.experiment_id,
            limit=_MAX_FORWARD_ROWS,
        )
        execution_events = self.store.list_paper_execution_events(
            spec.experiment_id,
            limit=_MAX_FORWARD_ROWS,
        )
        ledgers = self.store.list_paper_bet_ledger(spec.experiment_id, limit=_MAX_FORWARD_ROWS)
        if not observations and not execution_events and not ledgers:
            return None
        reassessment_record = {
            "candidate_id": candidate_id,
            "stage": CandidateStage.PAPER_FORWARD.value,
            "payload": {**dict(payload), "forward_test_id": spec.experiment_id},
        }
        # Build evidence before comparing identities.  Forward evidence
        # materialization may persist a resolved-bet ledger, and that ledger
        # is part of the digest.  Hashing the pre-materialization rows would
        # make the first reassessment look changed again on the next cycle.
        evidence = self._forward_evidence(reassessment_record, now)
        evidence_identity = str(evidence.get("forward_evidence_identity", "")).strip()
        if not evidence_identity:
            return None
        if str(payload.get("forward_evidence_identity", "")).strip() == evidence_identity:
            return None
        attempts = payload.get("automatic_reassessment_attempts", 0)
        if isinstance(attempts, bool) or not isinstance(attempts, int) or attempts < 0:
            attempts = 0
        if attempts >= _MAX_AUTOMATIC_REASSESSMENTS:
            return None
        body = dict(payload)
        materialized_config = _canonical_forward_config(spec.config)
        materialized_risk = dict(spec.risk_limits)
        materialized_config_hash = _hash_document(
            {"config": materialized_config, "risk_limits": materialized_risk}
        )
        materialized_frozen_hash = hashlib.sha256(
            "|".join(
                (
                    spec.strategy_hash,
                    spec.model_hash,
                    materialized_config_hash,
                )
            ).encode("utf-8")
        ).hexdigest()
        for key, value in (
            ("frozen", True),
            ("strategy_hash", spec.strategy_hash),
            ("model_hash", spec.model_hash),
            ("config_hash", materialized_config_hash),
            ("frozen_hash", materialized_frozen_hash),
            ("forward_config", materialized_config),
            ("risk_snapshot", materialized_risk),
        ):
            body.setdefault(key, value)
        body.update(
            {
                "paper_forward_started": True,
                "forward_test_id": spec.experiment_id,
                "forward_config": materialized_config,
                "registration_timestamp": spec.registration_timestamp.isoformat(),
                "forward_evidence": _compact_evidence(evidence),
                "forward_evidence_identity": evidence_identity,
                "dataset_attestation": dict(attestation),
                "historical_qualification": "PENDING",
                "automatic_reassessment_attempts": attempts + 1,
                "last_automatic_reassessment_at": ensure_utc(now).isoformat(),
                "paper_only": True,
                "research_only": True,
                "selection_excluded": True,
                "allocation_active": False,
                "canary_armed": False,
                "execution_scope": "OBSERVATION",
                "observation_only_lineage": True,
                "holdout_used": False,
            }
        )
        committed = self.store.save_candidate_lifecycle(
            candidate_id,
            CandidateStage.PAPER_FORWARD.value,
            body,
            from_stage=CandidateStage.SCHEMA_VALIDATED.value,
            reason="materialized forward evidence reassessed through canonical paper pipeline",
            timestamp=now,
        )
        if not committed:
            return None
        result = self.lifecycle.get(candidate_id)
        if result is None:
            return None
        self.lifecycle._schedule_readiness_snapshot_stale("LIFECYCLE_ADVANCED")
        result = self._evaluate_forward_candidate(candidate_id, now) or result
        return {
            "candidate_id": candidate_id,
            "stage": result.stage.value,
            "reassessed": True,
            "forward_evidence": _compact_evidence(evidence),
            "evidence_identity": evidence_identity,
            "promotion_reasons": list(self.config.promotion_criteria.evaluate({**body, **evidence})),
        }

    def reevaluate_forward_candidates(self, *, now: datetime | None = None) -> tuple[Mapping[str, Any], ...]:
        """Update active forward evidence and apply configured promotion gates."""
        current = ensure_utc(now or self.clock())
        output: list[Mapping[str, Any]] = []
        records = self.store.load_candidate_lifecycle(limit=10_000)
        if not isinstance(records, list):
            return ()
        for record in records:
            if not isinstance(record, Mapping):
                continue
            stage = str(record.get("stage", "")).strip()
            if stage == CandidateStage.SCHEMA_VALIDATED.value:
                candidate_id = str(record.get("candidate_id", "")).strip()
                if not candidate_id:
                    continue
                try:
                    with self.store.transaction():
                        reassessed = self._reassess_schema_observation_candidate(record, current)
                    if reassessed is not None:
                        output.append(reassessed)
                except (AttributeError, KeyError, RuntimeError, TypeError, ValueError):
                    continue
                continue
            if stage != CandidateStage.PAPER_FORWARD.value:
                continue
            candidate_id = str(record.get("candidate_id", "")).strip()
            if not candidate_id:
                continue
            try:
                with self.store.transaction():
                    evidence = self._forward_evidence(record, current)
                    candidate = self.lifecycle.get(candidate_id)
                    if candidate is None:
                        continue
                    existing = dict(candidate.payload)
                    previous_identity = str(existing.get("forward_evidence_identity", "")).strip()
                    current_identity = str(evidence.get("forward_evidence_identity", "")).strip()
                    changed = (
                        previous_identity != current_identity
                        if previous_identity and current_identity
                        else any(existing.get(key) != value for key, value in evidence.items())
                    )
                    if changed:
                        candidate = self.lifecycle.record_evidence(
                            candidate_id,
                            evidence,
                            expected_stage=CandidateStage.PAPER_FORWARD,
                            expected_handoff=(
                                record.get("payload")
                                if isinstance(record.get("payload"), Mapping)
                                else None
                            ),
                            reason="forward paper evidence update",
                        )
                    reasons = self.config.promotion_criteria.evaluate({**existing, **evidence})
                    hard_reasons = self.config.promotion_criteria.hard_rejection_reasons(evidence)
                    if hard_reasons:
                        candidate = self.lifecycle.reject(
                            candidate_id,
                            hard_reasons[0],
                            evidence=evidence,
                            expected_stage=CandidateStage.PAPER_FORWARD,
                            expected_payload=candidate.payload,
                        )
                    elif not reasons:
                        candidate = self.lifecycle.advance(
                            candidate_id,
                            CandidateStage.PAPER_PROMOTABLE,
                            {**evidence, "holdout_used": False},
                            reason="paper-forward criteria passed; human review required",
                        )
                    output.append(
                        {
                            "candidate_id": candidate_id,
                            "stage": candidate.stage.value,
                            "forward_evidence": _compact_evidence(evidence),
                            "promotion_reasons": list(dict.fromkeys((*reasons, *hard_reasons))),
                        }
                    )
            except (KeyError, RuntimeError, ValueError) as exc:
                output.append({"candidate_id": candidate_id, "stage": "PAPER_FORWARD", "error": str(exc)})
        return tuple(output)

    def _process_item(self, item: ResearchQueueItem, now: datetime) -> Mapping[str, Any]:
        handlers = {
            "hypothesis": self._process_hypothesis,
            "candidate": self._process_candidate,
            "report": self._process_report,
            "review_request": self._process_review_request,
            "experiment_result": self._process_experiment_result,
        }
        handler = handlers.get(str(item.item_type).strip().lower())
        if handler is None:
            raise AutonomousResearchError("UNSUPPORTED_ITEM_TYPE", f"unsupported research item type {item.item_type!r}")
        return handler(item, now)

    def _process_hypothesis(self, item: ResearchQueueItem, now: datetime) -> Mapping[str, Any]:
        proposal = _normalize_hypothesis_payload(item.payload, item)
        predeclared_starting_set = bool(item.payload.get("predeclared_starting_set"))
        predeclared_handoff = item.payload.get("observation_handoff")
        predeclared_handoff = (
            dict(predeclared_handoff)
            if isinstance(predeclared_handoff, Mapping)
            else {}
        )
        generated_scope_binding: tuple[str | None, str | None, str | None, str | None, str | None, str | None] | None = None
        generated_provenance = _generated_queue_provenance(proposal)
        generated_kind_hint = bool(proposal.get("predeclared_starting_set")) or (
            str(proposal.get("successor_relation", "")).strip().upper()
            in {"LEGACY_SCOPE_SUCCESSOR", "POLYMARKET_DATASET_VERSION_SUCCESSOR"}
        )
        if generated_provenance is None and generated_kind_hint:
            raise AutonomousResearchError(
                "GENERATED_PROVENANCE_INVALID",
                "generated queue item is missing its internal provenance marker",
            )
        if generated_provenance is not None:
            try:
                original_plan = ExperimentPlan.from_proposal(proposal)
            except ExperimentPlanError as exc:
                raise AutonomousResearchError(exc.reason, exc.detail) from exc
            # This is deliberately the first scope-dependent operation.  A
            # generated successor must reject a rotated attestation before
            # legacy scope classification, freezing, or lifecycle resolution
            # can produce a less authoritative forward-market reason.
            self._revalidate_generated_queue_item(item, original_plan, proposal)
            if any(
                key in proposal
                for key in ("predecessor_candidate_id", "predecessor_frozen_hash", "frozen_hash")
            ):
                generated_scope_binding = (
                    _binding_value(proposal.get("predecessor_candidate_id")),
                    _binding_value(
                        proposal.get("predecessor_frozen_hash", proposal.get("frozen_hash"))
                    ),
                    _binding_value(original_plan.market_scope_hash),
                    _binding_value(original_plan.market_scope_version),
                    _binding_value(original_plan.dataset_id),
                    _binding_value(original_plan.dataset_version),
                )
        scope_declared = "market_scope" in proposal or any(
            key in proposal
            for key in ("predecessor_candidate_id", "predecessor_frozen_hash", "frozen_hash")
        )
        if scope_declared:
            from .legacy_scope import (
                CANONICAL_VALID,
                LEGACY_UNAMBIGUOUS,
                LegacyScopeError,
                freeze_canonical_scope_proposal,
                handoff_current_scope_resolution,
                validate_frozen_scope_proposal,
            )

            scope_assessment = validate_frozen_scope_proposal(proposal)
            if scope_assessment.classification not in {CANONICAL_VALID, LEGACY_UNAMBIGUOUS}:
                raise AutonomousResearchError(
                    scope_assessment.reason,
                    f"scope proposal classification is {scope_assessment.classification}",
                )
            has_predecessor = any(
                key in proposal
                for key in ("predecessor_candidate_id", "predecessor_frozen_hash", "frozen_hash")
            )
            try:
                if has_predecessor:
                    proposal = freeze_canonical_scope_proposal(
                        proposal,
                        assumptions=proposal.get("assumptions"),
                        current_resolution=proposal.get("current_resolution"),
                        source_candidate_id=proposal.get("predecessor_candidate_id"),
                        source_frozen_hash=proposal.get("predecessor_frozen_hash", proposal.get("frozen_hash")),
                    )
                resolution = proposal.get("current_resolution")
                if isinstance(resolution, Mapping):
                    proposal = handoff_current_scope_resolution(proposal, resolution)
            except (LegacyScopeError, TypeError, ValueError) as exc:
                raise AutonomousResearchError(
                    getattr(exc, "reason", "INVALID_MARKET_SCOPE"),
                    str(exc),
                ) from exc
        validation = validate_hermes_proposal(proposal)
        if not validation.accepted:
            reason_code = next(
                (reason for reason in validation.reasons if re.fullmatch(r"[A-Z][A-Z0-9_]{2,63}", reason)),
                "INVALID_PROPOSAL",
            )
            raise AutonomousResearchError(reason_code, "; ".join(validation.reasons))
        plan = ExperimentPlan.from_proposal(validation.normalized or proposal)
        campaign_boundary: Mapping[str, Any] | None = None
        campaign_id = str(item.payload.get("campaign_id", "")).strip()
        if campaign_id:
            campaign_trial_id = str(item.payload.get("campaign_trial_id", "")).strip()
            campaign_state, campaign_trial = self._campaign_trial_from_payload(
                item.payload,
                campaign_id=campaign_id,
                trial_id=campaign_trial_id,
            )
            _, campaign_boundary = self._validate_campaign_plan_binding(
                campaign_state,
                campaign_trial,
                plan,
                queue_payload=item.payload,
            )
            self._validate_campaign_dataset_provenance(
                str(campaign_boundary.get("dataset_id", "")).strip(),
                str(campaign_boundary.get("dataset_version", "")).strip(),
                boundary=campaign_boundary,
                plan=plan,
            )
            self._validate_persisted_dataset_provenance(plan)
        elif plan.campaign_id:
            raise AutonomousResearchError(
                "CAMPAIGN_PROTOCOL_INVALID",
                "campaign plan is missing its queue campaign binding",
            )
        if generated_scope_binding is None:
            self._revalidate_generated_queue_item(item, plan, proposal)
        else:
            # The frozen successor may not carry the internal marker, but it
            # must remain bound to the exact authenticated predecessor scope
            # and dataset that were checked above.
            frozen_scope_binding = (
                _binding_value(proposal.get("predecessor_candidate_id")),
                _binding_value(
                    proposal.get("predecessor_frozen_hash", proposal.get("frozen_hash"))
                ),
                _binding_value(plan.market_scope_hash),
                _binding_value(plan.market_scope_version),
                _binding_value(plan.dataset_id),
                _binding_value(plan.dataset_version),
            )
            if frozen_scope_binding != generated_scope_binding:
                raise AutonomousResearchError(
                    "GENERATED_PROVENANCE_INVALID",
                    "generated legacy scope freeze changed its authenticated binding",
                )

        if plan.max_variants > self.config.max_plan_variants:
            raise AutonomousResearchError(
                "EXPERIMENT_BUDGET_EXCEEDED",
                f"plan requests {plan.max_variants} variants; node limit is {self.config.max_plan_variants}",
            )
        if _variant_count(plan) > self.config.max_plan_variants:
            raise AutonomousResearchError(
                "EXPERIMENT_BUDGET_EXCEEDED",
                "plan parameter space exceeds the node bound; all declared trials must run",
            )
        variants = plan.variants()
        if len(variants) != _variant_count(plan):
            raise AutonomousResearchError(
                "EXPERIMENT_BUDGET_EXCEEDED",
                "plan variant generation truncated; refusing incomplete trial set",
            )
        if not variants:
            raise AutonomousResearchError("EXPERIMENT_BUDGET_EXCEEDED", "plan produced no bounded variants")
        # Record the immutable plan before attempting historical evaluation so
        # schema-valid paper observation intents survive an insufficient split.
        self.store.save_experiment_plan(
            plan.plan_id,
            plan.as_dict(),
            hypothesis_id=plan.hypothesis_id,
            plan_hash=plan.plan_hash,
            status="ACCEPTED",
            timestamp=now,
        )
        prepared: list[dict[str, Any]] = []
        validation_scores: dict[str, float] = {}
        # Freeze every schema-valid bounded strategy and persist its paper
        # observation intent before loading or judging historical evidence.
        for parameters in variants:
            candidate_id = _candidate_id(
                plan,
                parameters,
                generation=0,
                observation_handoff=predeclared_handoff,
            )
            strategy = _strategy_with_operational_overlay(
                plan,
                plan.strategy_for(parameters, candidate_id),
            )
            self._initialize_candidate(
                plan,
                candidate_id,
                strategy,
                parameters,
                trial_index=len(prepared),
                trial_count=len(variants),
                now=now,
                predeclared_starting_set=predeclared_starting_set,
                predeclared_handoff=predeclared_handoff,
            )
            prepared.append(
                {
                    "trial_index": len(prepared),
                    "candidate_id": candidate_id,
                    "strategy": strategy,
                    "parameters": dict(parameters),
                    "variant_id": plan.variant_id(parameters),
                    "evaluation": None,
                }
            )
        rows, split = self._load_split(plan, boundary_override=campaign_boundary)
        split_counts = {
            "dataset_row_count": len(rows),
            "train_sample_count": len(split.train),
            "validation_sample_count": len(split.validation),
            "holdout_sample_count": len(split.holdout),
        }
        historical_insufficient = len(split.validation) < plan.min_samples
        if not historical_insufficient:
            for candidate in prepared:
                strategy: StrategyDefinition = candidate["strategy"]
                try:
                    evaluation = self._evaluate_datasets(
                        plan,
                        strategy,
                        split.train,
                        split.validation,
                        (),
                    )
                except AutonomousResearchError:
                    raise
                except (KeyError, TypeError, ValueError) as exc:
                    raise AutonomousResearchError("INVALID_DATASET", str(exc)) from exc
                candidate["evaluation"] = evaluation
                validation_scores[str(candidate["candidate_id"])] = _finite(
                    evaluation["validation"].get("expectancy"), 0.0
                )
        self.store.save_experiment_plan(
            plan.plan_id,
            plan.as_dict(),
            hypothesis_id=plan.hypothesis_id,
            plan_hash=plan.plan_hash,
            status="ACCEPTED",
            timestamp=now,
        )
        if historical_insufficient:
            results: list[dict[str, Any]] = []
            historical_sample_count = len(split.validation)
            historical_filled_trades = 0
            historical_sample_check = minimum_sample_check(
                historical_sample_count,
                trades=historical_filled_trades,
                min_observations=plan.min_samples,
                min_trades=plan.min_trades,
            )
            for candidate in prepared:
                candidate_id = str(candidate["candidate_id"])
                strategy: StrategyDefinition = candidate["strategy"]
                observation_reason = (
                    "at least three chronological observations are required"
                    if len(rows) < 3
                    else "INSUFFICIENT_DATA"
                )
                current = self.lifecycle.get(candidate_id)
                if current is not None and current.stage is CandidateStage.SCHEMA_VALIDATED:
                    self.lifecycle.record_evidence(
                        candidate_id,
                        {
                            "historical_qualification": "INSUFFICIENT_DATA",
                            "historical_blocker": "INSUFFICIENT_DATA",
                            "validation": {
                                "sample_count": historical_sample_count,
                                "filled_trades": historical_filled_trades,
                            },
                            "validation_sample_count": historical_sample_count,
                            "validation_filled_trades": historical_filled_trades,
                            "required_validation_samples": plan.min_samples,
                            "required_validation_trades": plan.min_trades,
                            "minimum_sample_check": historical_sample_check,
                            "paper_observation_intent": True,
                            "paper_only": True,
                            "research_only": True,
                        },
                        expected_stage=CandidateStage.SCHEMA_VALIDATED,
                        reason="historical validation remains below required sample minimum",
                    )
                results.append(
                    {
                        "candidate_id": candidate_id,
                        "stage": CandidateStage.SCHEMA_VALIDATED.value,
                        "reason": observation_reason,
                        "reason_code": "INSUFFICIENT_DATA",
                        "forward_test_id": None,
                        "paper_observation_intent": True,
                        "research_only": True,
                        "paper_only": True,
                        "historical_blocker": (
                            f"validation sample count {historical_sample_count} is below {plan.min_samples}"
                        ),
                        "validation_sample_count": historical_sample_count,
                        "validation_filled_trades": historical_filled_trades,
                        "required_validation_samples": plan.min_samples,
                        "required_validation_trades": plan.min_trades,
                        "minimum_sample_check": historical_sample_check,
                        "validation": {
                            "filled_trades": historical_filled_trades,
                        },
                        **split_counts,
                        **_strategy_metadata(strategy),
                    }
                )
            summary = self._hypothesis_result(plan, results, (), split_counts=split_counts)
            if predeclared_starting_set:
                summary = {
                    **dict(summary),
                    "accepted": True,
                    "status": "DEFERRED",
                    "queue_outcome": "OBSERVATION_DEFERRED",
                    "deferred_reason": "INSUFFICIENT_DATA",
                    "paper_observation_intent": True,
                    "research_only": True,
                    "paper_only": True,
                }
            self.store.save_experiment_plan(
                plan.plan_id,
                plan.as_dict(),
                hypothesis_id=plan.hypothesis_id,
                plan_hash=plan.plan_hash,
                status="COMPLETED",
                result=summary,
                timestamp=now,
            )
            self.store.save_report_if_absent(
                "autonomous-" + plan.plan_id,
                {"report_type": "autonomous_experiment_result", **summary},
                experiment_id=plan.plan_id,
            )
            return summary
        results: list[dict[str, Any]] = []
        for candidate in prepared:
            candidate_id = str(candidate["candidate_id"])
            strategy: StrategyDefinition = candidate["strategy"]
            evaluation = candidate["evaluation"]
            validation = (
                evaluation.get("validation", {})
                if isinstance(evaluation, Mapping)
                else {}
            )
            sample_check = minimum_sample_check(
                int(validation.get("sample_count", 0)),
                trades=int(validation.get("filled_trades", 0)),
                min_observations=plan.min_samples,
                min_trades=plan.min_trades,
            )
            if not sample_check["passed"]:
                # Historical qualification is a gate on promotion, not a
                # reason to destroy a canonical paper observation intent.
                insufficient_evidence = {
                    "historical_qualification": "INSUFFICIENT_DATA",
                    "historical_blocker": "INSUFFICIENT_DATA",
                    "validation": _compact_evidence(validation),
                    "validation_sample_count": int(validation.get("sample_count", 0)),
                    "validation_filled_trades": int(validation.get("filled_trades", 0)),
                    "required_validation_samples": plan.min_samples,
                    "required_validation_trades": plan.min_trades,
                    "minimum_sample_check": sample_check,
                    "paper_observation_intent": True,
                    "paper_only": True,
                    "research_only": True,
                }
                self.lifecycle.record_evidence(
                    candidate_id,
                    insufficient_evidence,
                    expected_stage=CandidateStage.SCHEMA_VALIDATED,
                    reason="historical validation remains below required sample or trade minimum",
                )
                result = {
                    "candidate_id": candidate_id,
                    "stage": CandidateStage.SCHEMA_VALIDATED.value,
                    "reason": "INSUFFICIENT_DATA",
                    "reason_code": "INSUFFICIENT_DATA",
                    "forward_test_id": None,
                    **insufficient_evidence,
                }
            else:
                try:
                    result = self._advance_candidate(
                        plan,
                        candidate_id,
                        strategy,
                        evaluation,
                        variant_count=len(prepared),
                        validation_scores=validation_scores,
                        now=now,
                        generation=0,
                        lineage=(),
                    )
                except AutonomousResearchError as exc:
                    current = self.lifecycle.get(candidate_id)
                    if current is not None and current.stage is not CandidateStage.REJECTED:
                        self.lifecycle.reject(candidate_id, exc.reason, evidence={"reason_detail": exc.detail})
                    result = {
                        "candidate_id": candidate_id,
                        "stage": CandidateStage.REJECTED.value,
                        "reason": exc.detail,
                        "reason_code": exc.reason,
                    }
            result = {
                **dict(result),
                **_strategy_metadata(strategy),
                "dataset_row_count": split_counts["dataset_row_count"],
                "train_sample_count": split_counts["train_sample_count"],
                "validation_sample_count": int(validation.get("sample_count", 0)),
                "holdout_sample_count": split_counts["holdout_sample_count"],
                "validation_filled_trades": int(validation.get("filled_trades", 0)),
                "required_validation_samples": plan.min_samples,
                "required_validation_trades": plan.min_trades,
            }
            holdout = evaluation.get("holdout") if isinstance(evaluation, Mapping) else None
            if isinstance(holdout, Mapping):
                result = {
                    **dict(result),
                    "holdout_evaluated": True,
                    "holdout_used_for_selection": False,
                    "holdout": _compact_evidence(holdout),
                }
            results.append(result)
        insufficient_data = any(
            str(item.get("reason_code", "")).strip().upper() == "INSUFFICIENT_DATA"
            for item in results
        )
        mutations = (
            ()
            if bool(item.payload.get("predeclared_starting_set"))
            or bool(item.payload.get("campaign_id"))
            or insufficient_data
            else self._generate_mutations(plan, prepared, validation_scores, now, lineage=())
        )
        summary = self._hypothesis_result(plan, results, mutations, split_counts=split_counts)
        if predeclared_starting_set and insufficient_data:
            summary = {
                **dict(summary),
                "accepted": True,
                "status": "DEFERRED",
                "queue_outcome": "OBSERVATION_DEFERRED",
                "deferred_reason": "INSUFFICIENT_DATA",
                "paper_observation_intent": True,
                "research_only": True,
                "paper_only": True,
            }
        self.store.save_experiment_plan(
            plan.plan_id,
            plan.as_dict(),
            hypothesis_id=plan.hypothesis_id,
            plan_hash=plan.plan_hash,
            status="COMPLETED",
            result=summary,
            timestamp=now,
        )
        self.store.save_report_if_absent(
            "autonomous-" + plan.plan_id,
            {"report_type": "autonomous_experiment_result", **summary},
            experiment_id=plan.plan_id,
        )
        return summary

    def _persist_predeclared_observation_lineage(
        self,
        plan: ExperimentPlan,
        candidate_id: str,
        strategy: StrategyDefinition,
        *,
        dataset_attestation: Mapping[str, Any] | None,
        now: datetime,
        handoff: Mapping[str, Any] | None = None,
    ) -> Mapping[str, Any]:
        """Persist the normalized paper lineage before historical qualification.

        A starter hypothesis is allowed to defer on an immature historical
        split.  Its immutable strategy/trial/enrollment must still exist so
        current-market observations can accumulate without re-running or
        rebinding the starter proposal.
        """
        strategy_document = strategy.to_dict()
        scope_binding = _scope_binding(plan)
        strategy_hash = _rolling_hash(strategy_document)
        scope = dict(scope_binding["market_scope"])
        setup_config: dict[str, Any] = {
            **scope_binding,
            "dataset_id": plan.dataset_id,
            "dataset_version": plan.dataset_version,
            "plan_id": plan.plan_id,
            "plan_hash": plan.plan_hash,
            "dataset_attestation": dataset_attestation,
            "dataset_boundary": plan.dataset_boundary,
        }
        setup_config["legacy_predeclared"] = True
        setup = _operational_setup_for_strategy(strategy_document, setup_config)
        if setup is None:
            setup = {
                "schema_version": "observation-setup-v1",
                "paper_only": True,
                "research_only": True,
                "allocation_active": False,
                "canary_armed": False,
                "market_scope_mode": str(scope.get("mode", "")).strip().upper(),
                "strategy_family": str(strategy_document.get("family", "")).strip(),
            }
        setup = _canonical_operational_document(setup)
        setup_hash = _operational_setup_hash(setup)
        identity = {
            "candidate_id": candidate_id,
            "strategy_hash": strategy_hash,
            "scope_hash": scope_binding["market_scope_hash"],
            "scope_version": scope_binding["market_scope_version"],
            "plan_hash": plan.plan_hash,
        }
        strategy_version_id = "strategy-version-" + _rolling_hash(identity).removeprefix("sha256:")[:40]
        trial_id = "research-trial-" + _rolling_hash(
            {"strategy_version_id": strategy_version_id, "candidate_id": candidate_id}
        ).removeprefix("sha256:")[:40]
        model_document = plan.model_for()
        model_document = dict(model_document) if isinstance(model_document, Mapping) else None
        provenance = _rolling_provenance_bound(
            {
                "source": "predeclared_starting_set",
                "rolling_research": True,
                "research_mode": "ROLLING_RESEARCH",
                "candidate_id": candidate_id,
                "source_candidate_id": candidate_id,
                "plan_id": plan.plan_id,
                "plan_hash": plan.plan_hash,
                "hypothesis_id": plan.hypothesis_id,
                "dataset_id": plan.dataset_id,
                "dataset_version": plan.dataset_version,
                "dataset_attestation": dataset_attestation,
                "market_scope": scope,
                "market_scope_hash": scope_binding["market_scope_hash"],
                "market_scope_version": scope_binding["market_scope_version"],
                "historical_qualification": "PENDING",
                "predecessor_profitability_inherited": False,
                "live_eligibility_inherited": False,
                "paper_only": True,
                "allocation_active": False,
                **(dict(handoff) if isinstance(handoff, Mapping) else {}),
                "predecessor_live_eligibility_inherited": False,
            }
        )
        strategy_record = {
            "strategy_version_id": strategy_version_id,
            "strategy_id": strategy.id,
            "version": str(strategy.version),
            "code_hash": strategy_hash,
            "strategy_hash": strategy_hash,
            "config_hash": setup_hash,
            "created_at": now.isoformat(),
            "strategy_document": strategy_document,
            "canonical_strategy": strategy_document,
            "model_document": model_document,
            "candidate_id": candidate_id,
            "provenance": provenance,
            "observation_only_lineage": True,
            "selection_excluded": True,
            "execution_scope": "OBSERVATION",
            "research_only": True,
            "paper_only": True,
            "allocation_active": False,
            "canary_armed": False,
            "operational_setup": setup,
            "operational_setup_hash": setup_hash,
            **scope_binding,
            "dataset_id": plan.dataset_id,
            "dataset_version": plan.dataset_version,
            "plan_id": plan.plan_id,
            "plan_hash": plan.plan_hash,
            "hypothesis_id": plan.hypothesis_id,
            "observation_handoff": (
                dict(handoff) if isinstance(handoff, Mapping) else {}
            ),
        }
        strategy_saver = getattr(self.store, "save_strategy_version", None)
        if callable(strategy_saver):
            strategy_saver(strategy_record)
        trial = {
            "research_trial_id": trial_id,
            "trial_id": trial_id,
            "strategy_version_id": strategy_version_id,
            "candidate_id": candidate_id,
            "status": "SCHEDULED",
            "trial_kind": "PREDECLARED_OBSERVATION",
            "strategy_hash": strategy_hash,
            "created_at": now.isoformat(),
            "rolling_research": True,
            "execution_scope": "OBSERVATION",
            "research_only": True,
            "paper_only": True,
            "allocation_active": False,
            "canary_armed": False,
            "observation_only_lineage": True,
            "selection_excluded": True,
            "operational_setup": setup,
            "operational_setup_hash": setup_hash,
            "strategy_document": strategy_document,
            "model_document": model_document,
            "provenance": provenance,
            "observation_handoff": (
                dict(handoff) if isinstance(handoff, Mapping) else {}
            ),
            **scope_binding,
        }
        trial_saver = getattr(self.store, "save_research_trial", None)
        if callable(trial_saver):
            trial_saver(trial)
        enrollment_id = "rolling-enrollment-" + _rolling_hash(
            {
                "candidate_id": candidate_id,
                "strategy_version_id": strategy_version_id,
                "research_trial_id": trial_id,
                "validation_version": _ROLLING_ENROLLMENT_VALIDATION_VERSION,
            }
        ).removeprefix("sha256:")[:48]
        enrollment_saver = getattr(self.store, "save_rolling_enrollment", None)
        if callable(enrollment_saver):
            enrollment_saver(
                {
                    "enrollment_id": enrollment_id,
                    "candidate_id": candidate_id,
                    "strategy_version_id": strategy_version_id,
                    "research_trial_id": trial_id,
                    "status": "ACCEPTED",
                    "reason": "PREDECLARED_OBSERVATION_DEFERRED",
                    "validation_version": _ROLLING_ENROLLMENT_VALIDATION_VERSION,
                    "provenance": {
                        **dict(provenance),
                        "enrollment_id": enrollment_id,
                        "strategy_version_id": strategy_version_id,
                        "research_trial_id": trial_id,
                        "observation_only_lineage": True,
                        "predecessor_profitability_inherited": False,
                        "live_eligibility_inherited": False,
                    },
                    "created_at": now.isoformat(),
                }
            )
        return {
            "strategy_version_id": strategy_version_id,
            "research_trial_id": trial_id,
            "enrollment_id": enrollment_id,
            "strategy_hash": strategy_hash,
            "operational_setup_hash": setup_hash,
            "operational_setup": setup,
            "observation_handoff": (
                dict(handoff) if isinstance(handoff, Mapping) else {}
            ),
            "observation_only_lineage": True,
        }

    def _initialize_candidate(
        self,
        plan: ExperimentPlan,
        candidate_id: str,
        strategy: StrategyDefinition,
        parameters: Mapping[str, Any],
        *,
        trial_index: int,
        trial_count: int,
        now: datetime,
        predeclared_starting_set: bool = False,
        predeclared_handoff: Mapping[str, Any] | None = None,
    ) -> Mapping[str, Any]:
        dataset_attestation = (
            self._dataset_attestation(plan, strict=False)
            if plan.market_type is MarketType.PREDICTION
            else None
        )
        legacy_predeclared = bool(
            predeclared_starting_set
            or (
                isinstance(plan.methodology, Mapping)
                and plan.methodology.get("predeclared_starting_set") is True
            )
        )
        payload = self._candidate_payload(
            plan,
            candidate_id,
            strategy,
            parameters,
            variant_id=plan.variant_id(parameters),
            generation=0,
            lineage=(),
            dataset_attestation=dataset_attestation,
            include_live_extensions=not legacy_predeclared,
        )
        # Register the worker-generated identity before any lifecycle
        # transition or observation intent is persisted.  The surrounding
        # queue transaction makes this registration durable with the plan,
        # run, and completion record, while a crash rolls all of them back.
        self.lifecycle.register_idea(candidate_id, payload)
        self._reserve_candidate(plan, candidate_id, now)
        self.store.save_strategy_if_absent(strategy.id, strategy.to_dict())
        lineage = (
            self._persist_predeclared_observation_lineage(
                plan,
                candidate_id,
                strategy,
                dataset_attestation=dataset_attestation,
                now=now,
                handoff=predeclared_handoff,
            )
            if predeclared_starting_set and plan.market_type is MarketType.PREDICTION
            else {}
        )
        self.store.save_experiment_if_absent(
            candidate_id,
            {
                "status": "IDEA",
                "run_id": candidate_id,
                "candidate_id": candidate_id,
                "hypothesis_id": plan.hypothesis_id,
                "plan_id": plan.plan_id,
                "plan_hash": plan.plan_hash,
                **_scope_binding(plan),
                **(
                    {
                        "strategy_version_id": lineage["strategy_version_id"],
                        "research_trial_id": lineage["research_trial_id"],
                        "enrollment_id": lineage["enrollment_id"],
                        "rolling_research": True,
                        "execution_scope": "OBSERVATION",
                        "allocation_active": False,
                        "canary_armed": False,
                    }
                    if lineage
                    else {}
                ),
                "dataset_id": plan.dataset_id,
                "dataset_version": plan.dataset_version,
                **_operational_setup_fields(
                    strategy.to_dict(),
                    plan,
                    dataset_attestation=dataset_attestation,
                    include_live_extensions=not legacy_predeclared,
                    dataset_boundary=plan.dataset_boundary,
                ),
                "trial_index": trial_index,
                "trial_count": trial_count,
                "holdout_evaluated": False,
                "holdout_used_for_selection": False,
                "paper_only": True,
            },
            strategy_id=strategy.id,
        )
        intent = (
            self._register_schema_observation_intent(
                plan,
                candidate_id,
                strategy,
                now,
                dataset_attestation=dataset_attestation,
                lineage=lineage,
            )
            if plan.market_type is MarketType.PREDICTION
            else None
        )
        return {
            "candidate_id": candidate_id,
            "intent": intent,
            **dict(lineage),
        }

    def _register_schema_observation_intent(
        self,
        plan: ExperimentPlan,
        candidate_id: str,
        strategy: StrategyDefinition,
        now: datetime,
        *,
        dataset_attestation: Mapping[str, Any] | None = None,
        lineage: Mapping[str, Any] | None = None,
    ) -> Any:
        model_document = plan.model_for() or {"type": "deterministic"}
        setup_fields: dict[str, Any] = {}
        legacy_predeclared_plan = bool(
            isinstance(plan.methodology, Mapping)
            and plan.methodology.get("predeclared_starting_set") is True
        )
        if plan.market_type is MarketType.CRYPTO_SPOT:
            config: dict[str, Any] = {"paper_only": True}
            risk_limits: Mapping[str, Any] = {"max_position_fraction": 0.0}
            dataset_attestation = None
        else:
            if dataset_attestation is None:
                dataset_attestation = self._dataset_attestation(plan, strict=False)
            config = {
                "execution": "paper_only",
                "market_authority_required": False,
                "rolling_observation": True,
            }
            risk_limits = {"max_position_fraction": 0.05}
            setup_fields = _operational_setup_fields(
                strategy.to_dict(),
                plan,
                dataset_attestation=dataset_attestation,
                dataset_boundary=plan.dataset_boundary,
                include_live_extensions=not (bool(lineage) or legacy_predeclared_plan),
            )
            if setup_fields:
                model_document = {"model_required": False}
        config.update(
            {
                "candidate_id": candidate_id,
                "plan_id": plan.plan_id,
                "plan_hash": plan.plan_hash,
                "dataset_id": plan.dataset_id,
                "dataset_version": plan.dataset_version,
                "strategy_document": strategy.to_dict(),
                "model_document": dict(model_document),
                **setup_fields,
                **_scope_binding(plan),
                "assumptions": dict(plan.assumptions),
                "cost_assumptions": {
                    "fee_bps": plan.assumptions.get("fee_bps"),
                    "slippage_bps": plan.assumptions.get("slippage_bps"),
                    "roundtrip_fee_bps": plan.assumptions.get("roundtrip_fee_bps"),
                    "roundtrip_slippage_bps": plan.assumptions.get("roundtrip_slippage_bps"),
                    "sensitivity": plan.assumptions.get("cost_sensitivity"),
                },
                "exit_policy": dict(plan.exit_policy),
                "research_mode": plan.research_mode,
                "paper_assumptions": {
                    "fees": {
                        "model": "proportional",
                        "fee_bps": str(plan.assumptions.get("fee_bps", 10)),
                    },
                    "slippage": {
                        "model": "proportional",
                        "slippage_bps": str(plan.assumptions.get("slippage_bps", 5)),
                    },
                },
            }
        )
        if isinstance(lineage, Mapping) and lineage:
            config.update(
                {
                    "strategy_version_id": lineage.get("strategy_version_id"),
                    "research_trial_id": lineage.get("research_trial_id"),
                    "enrollment_id": lineage.get("enrollment_id"),
                    "rolling_research": True,
                    "operational_setup_hash": lineage.get("operational_setup_hash"),
                    "observation_only_lineage": bool(
                        lineage.get("observation_only_lineage", True)
                    ),
                    "observation_handoff": (
                        dict(lineage.get("observation_handoff", {}))
                        if isinstance(lineage.get("observation_handoff"), Mapping)
                        else {}
                    ),
                    "legacy_predeclared": True,
                    **(
                        {
                            "dataset_attestation": _operational_attestation_binding(
                                dataset_attestation
                            )
                        }
                        if isinstance(dataset_attestation, Mapping)
                        else {}
                    ),
                    **(
                        {
                            "dataset_boundary": _operational_boundary_binding(
                                plan.dataset_boundary
                            )
                        }
                        if isinstance(plan.dataset_boundary, Mapping)
                        else {}
                    ),
                }
            )
        if legacy_predeclared_plan and not lineage:
            config["legacy_predeclared"] = True
        intent = ForwardTestRegistry(self.store).register_observation_intent(
            strategy=strategy.to_dict(),
            model=dict(model_document),
            config=config,
            registration_timestamp=now,
            risk_limits=risk_limits,
            candidate_id=candidate_id,
        )
        current = self.lifecycle.get(candidate_id)
        if current is not None and current.stage is CandidateStage.IDEA:
            self.lifecycle.advance(
                candidate_id,
                CandidateStage.SCHEMA_VALIDATED,
                {
                    **dict(current.payload),
                    "schema_valid": True,
                    "referenced_features": list(plan.allowed_features),
                    "parameter_ranges_bounded": True,
                    "paper_observation_intent_id": intent.experiment_id,
                    "paper_observation_intent": True,
                    "paper_only": True,
                    "research_only": True,
                    "historical_qualification": "PENDING",
                    **(
                        {
                            "strategy_version_id": lineage.get("strategy_version_id"),
                            "research_trial_id": lineage.get("research_trial_id"),
                            "enrollment_id": lineage.get("enrollment_id"),
                            "execution_scope": "OBSERVATION",
                            "allocation_active": False,
                            "canary_armed": False,
                            "observation_only_lineage": bool(
                                lineage.get("observation_only_lineage", True)
                            ),
                            "observation_handoff": (
                                dict(lineage.get("observation_handoff", {}))
                                if isinstance(
                                    lineage.get("observation_handoff"), Mapping
                                )
                                else {}
                            ),
                            "legacy_predeclared": True,
                        }
                        if isinstance(lineage, Mapping) and lineage
                        else {}
                    ),
                    **(
                        {"dataset_attestation": dict(dataset_attestation)}
                        if dataset_attestation is not None
                        else {}
                    ),
                },
                reason="canonical paper observation intent registered before historical qualification",
            )
        return intent

    def _process_candidate(self, item: ResearchQueueItem, now: datetime) -> Mapping[str, Any]:
        payload = dict(item.payload)
        candidate_id = str(payload.get("candidate_id", "")).strip()
        if not candidate_id:
            raise AutonomousResearchError("INVALID_CANDIDATE", "candidate_id is required")
        raw_generation = payload.get("generation", 0)
        if isinstance(raw_generation, bool) or not isinstance(raw_generation, int) or raw_generation < 0:
            raise AutonomousResearchError("INVALID_CANDIDATE", "generation must be a non-negative integer")
        generation = int(raw_generation)
        if generation > self.config.max_generation_depth:
            raise AutonomousResearchError(
                "GENERATION_DEPTH_EXCEEDED",
                f"candidate generation {generation} exceeds node limit {self.config.max_generation_depth}",
            )
        run_record = self.store.load_experiment(candidate_id)
        if not isinstance(run_record, Mapping):
            raise AutonomousResearchError(
                "UNAUTHENTICATED_CANDIDATE",
                "candidate queue items require a persisted worker-generated run",
            )
        persisted_run_id = _binding_value(run_record.get("run_id"))
        persisted_candidate_id = _binding_value(run_record.get("candidate_id"))
        if persisted_run_id != candidate_id or persisted_candidate_id != candidate_id:
            raise AutonomousResearchError(
                "CANDIDATE_BINDING_MISMATCH",
                "persisted worker run identity does not match candidate_id",
            )
        raw_lineage = payload.get("lineage", ())
        if not isinstance(raw_lineage, (list, tuple)) or len(raw_lineage) > 256:
            raise AutonomousResearchError("INVALID_CANDIDATE", "lineage must be a bounded list")
        lineage = tuple(str(value).strip() for value in raw_lineage if str(value).strip())
        plan_id = str(payload.get("plan_id", "")).strip()
        plan_record = self.store.load_experiment_plan(plan_id) if plan_id else None
        if not isinstance(plan_record, Mapping):
            raise AutonomousResearchError(
                "UNAUTHENTICATED_CANDIDATE",
                "candidate must reference a persisted experiment plan",
            )
        raw_plan = plan_record.get("plan")
        if not isinstance(raw_plan, Mapping):
            raise AutonomousResearchError("INVALID_PLAN", "persisted candidate experiment plan is invalid")
        try:
            plan = ExperimentPlan.from_mapping(raw_plan, hypothesis_id=str(payload.get("hypothesis_id", "")).strip() or None)
        except ExperimentPlanError as exc:
            raise AutonomousResearchError(exc.reason, exc.detail) from exc
        if plan.max_variants > self.config.max_plan_variants:
            raise AutonomousResearchError(
                "EXPERIMENT_BUDGET_EXCEEDED",
                f"plan requests {plan.max_variants} variants; node limit is {self.config.max_plan_variants}",
            )
        raw_max_variants = payload.get("max_variants")
        if raw_max_variants is not None and (
            isinstance(raw_max_variants, bool)
            or not isinstance(raw_max_variants, int)
            or raw_max_variants < 1
            or raw_max_variants > self.config.max_plan_variants
            or raw_max_variants > plan.max_variants
        ):
            raise AutonomousResearchError(
                "EXPERIMENT_BUDGET_EXCEEDED",
                "candidate max_variants exceeds the persisted plan or node limit",
            )
        if generation > 0 and plan.market_type is MarketType.PREDICTION:
            if _generated_queue_provenance(payload) is None:
                raise AutonomousResearchError(
                    "GENERATED_PROVENANCE_INVALID",
                    "generated mutation candidate is missing its internal provenance marker",
                )
            self._revalidate_generated_queue_item(item, plan, payload)
        self._validate_worker_candidate_binding(
            payload,
            candidate_id=candidate_id,
            generation=generation,
            lineage=lineage,
            plan=plan,
            plan_record=plan_record,
            run_record=run_record,
        )
        crypto_binding = self._crypto_binding(plan)
        strategy_value = payload.get("strategy", payload.get("strategy_document"))
        if not isinstance(strategy_value, Mapping):
            raise AutonomousResearchError("UNSUPPORTED_STRATEGY_FAMILY", "candidate strategy document is missing")
        try:
            supplied_strategy = load_strategy(strategy_value)
            raw_parameters = payload.get("parameters")
            if not isinstance(raw_parameters, Mapping):
                raise AutonomousResearchError("CANDIDATE_BINDING_MISMATCH", "candidate parameters are required")
            parameters = dict(raw_parameters)
            if dict(supplied_strategy.parameters) != parameters:
                raise AutonomousResearchError(
                    "CANDIDATE_BINDING_MISMATCH",
                    "candidate strategy parameters do not match candidate parameters",
                )
            strategy = _strategy_with_operational_overlay(
                plan,
                plan.strategy_for(parameters, candidate_id),
            )
            supplied_document = supplied_strategy.to_dict()
            expected_document = strategy.to_dict()
            supplied_document.pop("strategy_id", None)
            expected_document.pop("strategy_id", None)
            if supplied_document != expected_document:
                raise AutonomousResearchError(
                    "UNSUPPORTED_STRATEGY_FAMILY",
                    "candidate strategy does not match its declarative experiment plan",
                )
        except AutonomousResearchError:
            raise
        except Exception as exc:
            raise AutonomousResearchError("UNSUPPORTED_STRATEGY_FAMILY", str(exc)) from exc
        if generation == 0:
            raise AutonomousResearchError(
                "UNAUTHENTICATED_CANDIDATE",
                "generation-zero candidates are produced inline, not accepted from the queue",
            )
        else:
            parent_id = _binding_value(payload.get("parent_id"))
            if _binding_value(run_record.get("strategy_id")) != candidate_id:
                raise AutonomousResearchError(
                    "CANDIDATE_BINDING_MISMATCH",
                    "mutation strategy identity is not the persisted candidate identity",
                )
            persisted_variant = run_record.get("variant")
            if not isinstance(persisted_variant, Mapping) or dict(persisted_variant) != parameters:
                raise AutonomousResearchError(
                    "CANDIDATE_BINDING_MISMATCH",
                    "mutation parameters do not match the persisted worker variant",
                )
            persisted_record_strategy = run_record.get("strategy")
            if not isinstance(persisted_record_strategy, Mapping):
                raise AutonomousResearchError(
                    "CANDIDATE_BINDING_MISMATCH",
                    "mutation strategy document is missing from the persisted worker run",
                )
            stored_document = self.store.load_strategy(candidate_id)
            if not parent_id or not isinstance(stored_document, Mapping):
                raise AutonomousResearchError(
                    "CANDIDATE_BINDING_MISMATCH",
                    "mutation candidate lacks persisted parent strategy",
                )
            try:
                stored_strategy = load_strategy(stored_document)
                recorded_strategy = load_strategy(persisted_record_strategy)
            except Exception as exc:
                raise AutonomousResearchError("CANDIDATE_BINDING_MISMATCH", "persisted mutation strategy is invalid") from exc
            supplied_document = supplied_strategy.to_dict()
            persisted_document = stored_strategy.to_dict()
            recorded_document = recorded_strategy.to_dict()
            supplied_document.pop("strategy_id", None)
            persisted_document.pop("strategy_id", None)
            recorded_document.pop("strategy_id", None)
            if supplied_document != persisted_document or supplied_document != recorded_document:
                raise AutonomousResearchError(
                    "CANDIDATE_BINDING_MISMATCH",
                    "mutation strategy does not match the persisted worker strategy",
                )
            expected_candidate_id = _mutation_candidate_id(parent_id, generation, stored_strategy)
            if candidate_id != expected_candidate_id:
                raise AutonomousResearchError(
                    "CANDIDATE_BINDING_MISMATCH",
                    "mutation candidate_id is not deterministic for its parent lineage",
                )
        rows, split = self._load_split(plan)
        try:
            evaluation = self._evaluate_datasets(plan, strategy, split.train, split.validation)
        except AutonomousResearchError:
            raise
        except (KeyError, TypeError, ValueError) as exc:
            raise AutonomousResearchError("INVALID_DATASET", str(exc)) from exc
        # Direct candidate submissions do not pass through hypothesis
        # expansion; reserve their unit inside the queue transaction too.
        self._reserve_candidate(plan, candidate_id, now)
        current = self.lifecycle.get(candidate_id)
        if current is None:
            candidate_record = {
                **payload,
                "candidate_id": candidate_id,
                "plan_id": plan.plan_id,
                "plan_hash": plan.plan_hash,
                **_scope_binding(plan),
                "holdout_used": False,
            }
            if crypto_binding is not None:
                candidate_record["crypto_provenance"] = crypto_binding
            self.lifecycle.register_idea(candidate_id, candidate_record)
        result = self._advance_candidate(
            plan,
            candidate_id,
            strategy,
            evaluation,
            variant_count=max(1, len(plan.variants())),
            validation_scores={candidate_id: _finite(evaluation["validation"].get("expectancy"), 0.0)},
            now=now,
            generation=generation,
            lineage=lineage,
            crypto_binding=crypto_binding,
        )
        if (
            result.get("stage") in {
                CandidateStage.ROBUSTNESS_CHECKED.value,
                CandidateStage.FROZEN.value,
                CandidateStage.PAPER_FORWARD.value,
                CandidateStage.PAPER_PROMOTABLE.value,
            }
            and generation < self.config.max_generation_depth
        ):
            mutation_ids = self._generate_mutations(
                plan,
                (
                    {
                        "candidate_id": candidate_id,
                        "strategy": strategy,
                        "evaluation": evaluation,
                    },
                ),
                {candidate_id: _finite(evaluation["validation"].get("expectancy"), 0.0)},
                now,
                lineage=lineage,
            )
            if mutation_ids:
                result = {**dict(result), "mutation_candidates": list(mutation_ids)}
        return {**dict(result), **_scope_binding(plan)}

    def _validate_worker_candidate_binding(
        self,
        payload: Mapping[str, Any],
        *,
        candidate_id: str,
        generation: int,
        lineage: Sequence[str],
        plan: ExperimentPlan,
        plan_record: Mapping[str, Any],
        run_record: Mapping[str, Any],
    ) -> None:
        """Accept only candidate payloads created by the durable worker path."""
        for field, expected in (
            ("plan_id", plan.plan_id),
            ("plan_hash", plan.plan_hash),
            ("dataset_id", plan.dataset_id),
            ("dataset_version", plan.dataset_version),
        ):
            supplied = _binding_value(payload.get(field))
            persisted = _binding_value(run_record.get(field))
            if supplied != expected or persisted != expected:
                raise AutonomousResearchError(
                    "CANDIDATE_BINDING_MISMATCH",
                    f"candidate {field} does not match the persisted experiment plan",
                )
        expected_scope = _scope_binding(plan)
        for field, expected in expected_scope.items():
            supplied = payload.get(field)
            persisted = run_record.get(field)
            if _canonical_binding(supplied) != _canonical_binding(expected) or _canonical_binding(persisted) != _canonical_binding(expected):
                raise AutonomousResearchError(
                    "CANDIDATE_BINDING_MISMATCH",
                    f"candidate {field} does not match the persisted experiment plan",
                )
        if _binding_value(plan_record.get("plan_id")) != plan.plan_id or _binding_value(plan_record.get("plan_hash")) != plan.plan_hash:
            raise AutonomousResearchError("CANDIDATE_BINDING_MISMATCH", "candidate plan identity is not exact")

        stored_generation = run_record.get("generation")
        if isinstance(stored_generation, bool) or not isinstance(stored_generation, int) or stored_generation != generation:
            raise AutonomousResearchError("CANDIDATE_BINDING_MISMATCH", "candidate generation is not the persisted worker generation")
        stored_lineage = run_record.get("lineage", ())
        if not isinstance(stored_lineage, (list, tuple)):
            raise AutonomousResearchError("CANDIDATE_BINDING_MISMATCH", "persisted candidate lineage is invalid")
        normalized_stored_lineage = tuple(str(value).strip() for value in stored_lineage if str(value).strip())
        if normalized_stored_lineage != tuple(lineage):
            raise AutonomousResearchError("CANDIDATE_BINDING_MISMATCH", "candidate lineage is not the persisted worker lineage")
        if generation == 0:
            if _binding_value(payload.get("parent_id")) or lineage:
                raise AutonomousResearchError("CANDIDATE_BINDING_MISMATCH", "generation-zero candidates cannot declare lineage")
        else:
            parent_id = _binding_value(payload.get("parent_id"))
            persisted_parent_id = _binding_value(run_record.get("parent_id"))
            if not parent_id or parent_id != persisted_parent_id or parent_id not in lineage:
                raise AutonomousResearchError("CANDIDATE_BINDING_MISMATCH", "mutation parent lineage is not exact")
            if self.lifecycle.get(parent_id) is None:
                raise AutonomousResearchError("CANDIDATE_BINDING_MISMATCH", "mutation parent is not persisted")

    def _process_report(self, item: ResearchQueueItem, now: datetime) -> Mapping[str, Any]:
        payload = compact_report(item.payload)
        report_id = str(payload.get("report_id", item.item_id)).strip() if isinstance(payload, Mapping) else item.item_id
        if not report_id:
            report_id = item.item_id
        self.store.save_report_if_absent(report_id, {"report_type": "informational", "payload": payload})
        return {"accepted": True, "kind": "report", "report_id": report_id, "persisted": True, "paper_only": True}

    def _process_review_request(self, item: ResearchQueueItem, now: datetime) -> Mapping[str, Any]:
        payload = item.payload
        candidate_id = str(payload.get("candidate_id", "")).strip()
        hypothesis_id = str(payload.get("hypothesis_id", "")).strip()
        candidate = self.lifecycle.get(candidate_id) if candidate_id else None
        plan_rows = self.store.list_experiment_plans(hypothesis_id=hypothesis_id, limit=32) if hypothesis_id else []
        response = {
            "accepted": True,
            "kind": "review_request",
            "candidate_id": candidate_id or None,
            "hypothesis_id": hypothesis_id or None,
            "candidate_stage": candidate.stage.value if candidate is not None else None,
            "plans": len(plan_rows),
            "status": "review_output_ready",
            "paper_only": True,
        }
        self.store.save_report_if_absent("review-" + item.item_id, {"report_type": "review", **response})
        return response

    def _process_experiment_result(self, item: ResearchQueueItem, now: datetime) -> Mapping[str, Any]:
        """Attach only evidence derived from a persisted, bound paper run.

        Queue payloads are untrusted input.  In particular, ``result`` and
        ``metrics`` are never copied into lifecycle evidence: a caller can
        submit either field without having run an experiment.  The queue item
        must identify an immutable persisted experiment and the exact plan and
        dataset recorded for the candidate.  Forward metrics are then
        recomputed from the paper observations, execution events, and ledger.
        """
        payload = item.payload
        candidate_id = str(payload.get("candidate_id", "")).strip()
        if not candidate_id:
            raise AutonomousResearchError("INVALID_RESULT", "experiment_result requires candidate_id")
        candidate = self.lifecycle.get(candidate_id)
        if candidate is None:
            raise AutonomousResearchError("INVALID_RESULT", f"unknown candidate {candidate_id}")

        experiment = self.store.load_experiment(candidate_id)
        if not isinstance(experiment, Mapping):
            raise AutonomousResearchError(
                "UNAUTHENTICATED_RESULT",
                "experiment_result requires a persisted immutable worker run",
            )
        self._validate_result_binding(candidate_id, candidate.payload, payload, experiment)

        forward_id = str(candidate.payload.get("forward_test_id", "")).strip()
        if str(payload.get("forward_test_id", "")).strip() != forward_id:
            raise AutonomousResearchError(
                "UNAUTHENTICATED_RESULT",
                "experiment_result forward_test_id does not match the candidate run",
            )
        if candidate.stage is not CandidateStage.PAPER_FORWARD or not forward_id:
            raise AutonomousResearchError(
                "UNTRUSTED_RESULT",
                "experiment_result has no persisted paper forward run to evaluate",
            )
        registry = ForwardTestRegistry(self.store)
        spec = registry.get(forward_id)
        if spec is None:
            raise AutonomousResearchError("UNAUTHENTICATED_RESULT", f"missing persisted forward test {forward_id}")
        self._validate_forward_result_binding(candidate.payload, spec)

        observations = self.store.list_paper_observations(forward_id, limit=_MAX_FORWARD_ROWS)
        execution_events = self.store.list_paper_execution_events(forward_id, limit=_MAX_FORWARD_ROWS)
        ledgers = self.store.list_paper_bet_ledger(forward_id, limit=_MAX_FORWARD_ROWS)
        if not observations and not execution_events and not ledgers:
            raise AutonomousResearchError(
                "UNTRUSTED_RESULT",
                "experiment_result has no persisted paper observations or outcomes",
            )

        # The caller-supplied result/metrics is intentionally ignored.  This
        # is the sole evidence path for a queued experiment result.
        evidence = self._forward_evidence(candidate.as_record(), now)
        evidence["result_attached"] = True
        evidence["holdout_used"] = False
        candidate = self.lifecycle.record_evidence(
            candidate_id,
            evidence,
            expected_stage=CandidateStage.PAPER_FORWARD,
            expected_handoff=candidate.payload,
            reason="bound paper result evaluated from persisted observations",
        )
        self._evaluate_forward_candidate(candidate_id, now)
        response = {
            "accepted": True,
            "kind": "experiment_result",
            "candidate_id": candidate_id,
            "stage": (self.lifecycle.get(candidate_id) or candidate).stage.value,
            "attached": True,
            "paper_only": True,
            "evidence_source": "persisted_paper_observations",
        }
        self.store.save_report_if_absent("result-" + item.item_id, {"report_type": "experiment_result", **response})
        return response

    def _validate_result_binding(
        self,
        candidate_id: str,
        candidate_payload: Mapping[str, Any],
        result_payload: Mapping[str, Any],
        experiment: Mapping[str, Any],
    ) -> None:
        """Require queue identity and immutable plan/dataset bindings to agree."""
        run_id = str(result_payload.get("run_id", result_payload.get("experiment_id", ""))).strip()
        if run_id != candidate_id:
            raise AutonomousResearchError(
                "UNAUTHENTICATED_RESULT",
                "experiment_result run_id does not match the persisted worker run",
            )
        for identity_field in ("run_id", "experiment_id"):
            supplied_identity = result_payload.get(identity_field)
            if supplied_identity is not None and str(supplied_identity).strip() != candidate_id:
                raise AutonomousResearchError(
                    "UNAUTHENTICATED_RESULT",
                    f"experiment_result {identity_field} does not match the persisted worker run",
                )
        persisted_run_id = str(experiment.get("run_id", candidate_id)).strip()
        if persisted_run_id != candidate_id:
            raise AutonomousResearchError("RESULT_BINDING_MISMATCH", "persisted worker run identity does not match")
        experiment_candidate = str(experiment.get("candidate_id", candidate_id)).strip()
        if experiment_candidate != candidate_id:
            raise AutonomousResearchError("RESULT_BINDING_MISMATCH", "persisted worker run candidate_id does not match")

        plan_id = _binding_value(candidate_payload.get("plan_id"))
        plan_hash = _binding_value(candidate_payload.get("plan_hash"))
        dataset_id = _binding_value(candidate_payload.get("dataset_id"))
        dataset_version = _binding_value(candidate_payload.get("dataset_version"))
        if not plan_id or not plan_hash or not dataset_version:
            raise AutonomousResearchError(
                "RESULT_BINDING_MISMATCH",
                "candidate lacks exact persisted plan and dataset binding",
            )
        for field, expected in (
            ("plan_id", plan_id),
            ("plan_hash", plan_hash),
            ("dataset_id", dataset_id),
            ("dataset_version", dataset_version),
        ):
            supplied = _binding_value(result_payload.get(field))
            if supplied != expected:
                raise AutonomousResearchError(
                    "RESULT_BINDING_MISMATCH",
                    f"experiment_result {field} does not match the candidate binding",
                )
            persisted = _binding_value(experiment.get(field))
            if persisted != expected:
                raise AutonomousResearchError(
                    "RESULT_BINDING_MISMATCH",
                    f"persisted worker run {field} does not match the candidate binding",
                )

        plan_record = self.store.load_experiment_plan(plan_id)
        if not isinstance(plan_record, Mapping):
            raise AutonomousResearchError("RESULT_BINDING_MISMATCH", f"missing persisted experiment plan {plan_id}")
        if _binding_value(plan_record.get("plan_hash")) != plan_hash:
            raise AutonomousResearchError("RESULT_BINDING_MISMATCH", "persisted experiment plan hash does not match")
        raw_plan = plan_record.get("plan")
        if not isinstance(raw_plan, Mapping):
            raise AutonomousResearchError("RESULT_BINDING_MISMATCH", "persisted experiment plan is invalid")
        try:
            plan = ExperimentPlan.from_mapping(raw_plan)
        except ExperimentPlanError as exc:
            raise AutonomousResearchError("RESULT_BINDING_MISMATCH", str(exc)) from exc
        if plan.plan_id != plan_id or plan.plan_hash != plan_hash:
            raise AutonomousResearchError("RESULT_BINDING_MISMATCH", "experiment plan identity is not exact")
        if _binding_value(plan.dataset_id) != dataset_id or plan.dataset_version != dataset_version:
            raise AutonomousResearchError("RESULT_BINDING_MISMATCH", "experiment plan dataset binding is not exact")
        expected_scope = _scope_binding(plan)
        for field, expected in expected_scope.items():
            if _canonical_binding(candidate_payload.get(field)) != _canonical_binding(expected):
                raise AutonomousResearchError("RESULT_BINDING_MISMATCH", f"candidate {field} is not canonical")
            if field in result_payload and _canonical_binding(result_payload.get(field)) != _canonical_binding(expected):
                raise AutonomousResearchError("RESULT_BINDING_MISMATCH", f"experiment_result {field} does not match the candidate scope")
            if _canonical_binding(experiment.get(field)) != _canonical_binding(expected):
                raise AutonomousResearchError("RESULT_BINDING_MISMATCH", f"persisted worker run {field} does not match the candidate scope")

    @staticmethod
    def _validate_forward_result_binding(candidate_payload: Mapping[str, Any], spec: Any) -> None:
        forward_id = str(candidate_payload.get("forward_test_id", "")).strip()
        if str(getattr(spec, "experiment_id", "")).strip() != forward_id:
            raise AutonomousResearchError("RESULT_BINDING_MISMATCH", "forward-test identity does not match candidate")
        config = getattr(spec, "config", {})
        if not isinstance(config, Mapping):
            raise AutonomousResearchError("RESULT_BINDING_MISMATCH", "persisted forward-test config is invalid")
        for field in ("plan_id", "dataset_id", "dataset_version"):
            expected = _binding_value(candidate_payload.get(field))
            if _binding_value(config.get(field)) != expected:
                raise AutonomousResearchError(
                    "RESULT_BINDING_MISMATCH",
                    f"forward-test {field} does not match the candidate binding",
                )
        for field in ("market_scope_hash", "market_scope_version", "scope_hash", "scope_version", "market_scope", "dataset_selector"):
            expected = candidate_payload.get(field)
            if _canonical_binding(config.get(field)) != _canonical_binding(expected):
                raise AutonomousResearchError(
                    "RESULT_BINDING_MISMATCH",
                    f"forward-test {field} does not match the candidate scope",
                )

    def _crypto_binding(self, plan: ExperimentPlan) -> dict[str, Any] | None:
        """Resolve and validate immutable crypto inputs from the persisted store."""
        if plan.market_type is not MarketType.CRYPTO_SPOT:
            return None
        dataset_id = plan.dataset_id
        dataset_version = plan.dataset_version
        timeframe = plan.dataset_timeframe
        source = plan.dataset_source
        survivorship = plan.dataset_survivorship
        if not dataset_id or not dataset_version or not timeframe or not source or not survivorship:
            raise AutonomousResearchError(
                "INSUFFICIENT_DATA",
                "crypto plans require exact dataset id, version, timeframe, source, and survivorship provenance",
            )
        if dataset_version.lower() in {"latest", "current", "default", "unversioned"}:
            raise AutonomousResearchError("INSUFFICIENT_DATA", "crypto dataset_version must be immutable and versioned")
        catalog_loader = getattr(self.store, "load_dataset_catalog", None)
        if not callable(catalog_loader):
            raise AutonomousResearchError("INSUFFICIENT_DATA", "crypto research requires a persisted dataset catalog")
        catalog = catalog_loader(dataset_id, dataset_version)
        if not isinstance(catalog, Mapping):
            raise AutonomousResearchError(
                "INSUFFICIENT_DATA",
                f"no exact dataset catalog {dataset_id}/{dataset_version}",
            )
        catalog_id = str(catalog.get("dataset_id", "")).strip()
        catalog_version = str(catalog.get("dataset_version", catalog.get("version", ""))).strip()
        if catalog_id != dataset_id or catalog_version != dataset_version:
            raise AutonomousResearchError("CRYPTO_PROVENANCE_MISMATCH", "dataset catalog identity does not match the plan")
        if str(catalog.get("market_type", "")).strip().lower() != MarketType.CRYPTO_SPOT.value:
            raise AutonomousResearchError("CRYPTO_PROVENANCE_MISMATCH", "dataset catalog market_type is not crypto_spot")
        catalog_timeframe = str(catalog.get("timeframe", "")).strip()
        if catalog_timeframe != timeframe:
            raise AutonomousResearchError("CRYPTO_PROVENANCE_MISMATCH", "dataset timeframe does not match the plan")
        catalog_source = str(catalog.get("provider", catalog.get("source", ""))).strip()
        if catalog_source != source:
            raise AutonomousResearchError("CRYPTO_PROVENANCE_MISMATCH", "dataset source does not match the plan")
        catalog_source_type = str(catalog.get("source_type", "")).strip().upper()
        declared_source_type = plan.dataset_source_type
        if declared_source_type and catalog_source_type != declared_source_type.strip().upper():
            raise AutonomousResearchError("CRYPTO_PROVENANCE_MISMATCH", "dataset source_type does not match the plan")
        if catalog_source_type != "HISTORICAL":
            raise AutonomousResearchError(
                "CRYPTO_PROVENANCE_MISMATCH",
                "crypto autonomous research accepts historical datasets only",
            )
        catalog_metadata = catalog.get("metadata")
        catalog_metadata = dict(catalog_metadata) if isinstance(catalog_metadata, Mapping) else {}
        catalog_survivorship = catalog_metadata.get(
            "survivorship_bias",
            catalog_metadata.get("survivorship", catalog_metadata.get("survivorship_label")),
        )
        if catalog_survivorship is None or str(catalog_survivorship).strip() != survivorship:
            raise AutonomousResearchError("CRYPTO_PROVENANCE_MISMATCH", "dataset survivorship provenance does not match the plan")

        universe_id = plan.universe_id
        universe_version = plan.universe_version
        universe_hash = plan.universe_snapshot_hash
        if not universe_id or not universe_version or not universe_hash:
            raise AutonomousResearchError(
                "INSUFFICIENT_DATA",
                "crypto plans require exact persisted universe id, version, and snapshot_hash",
            )
        if any(
            value.lower() in {"latest", "current", "default", "unversioned"}
            for value in (universe_version, universe_hash)
        ):
            raise AutonomousResearchError("INSUFFICIENT_DATA", "crypto universe binding must be immutable and versioned")
        universe_document = dict(plan.universe or {})
        universe_dataset_id = str(universe_document.get("dataset_id") or f"universe:{universe_id}").strip()
        universe_catalog = catalog_loader(universe_dataset_id, universe_version)
        if not isinstance(universe_catalog, Mapping):
            raise AutonomousResearchError(
                "INSUFFICIENT_DATA",
                f"no exact universe snapshot {universe_dataset_id}/{universe_version}",
            )
        if str(universe_catalog.get("dataset_id", "")).strip() != universe_dataset_id:
            raise AutonomousResearchError("CRYPTO_PROVENANCE_MISMATCH", "universe catalog identity does not match the plan")
        if str(universe_catalog.get("dataset_version", universe_catalog.get("version", ""))).strip() != universe_version:
            raise AutonomousResearchError("CRYPTO_PROVENANCE_MISMATCH", "universe version does not match the plan")
        universe_metadata = universe_catalog.get("metadata")
        universe_metadata = dict(universe_metadata) if isinstance(universe_metadata, Mapping) else {}
        persisted_universe_id = str(universe_metadata.get("universe_id", "")).strip()
        if persisted_universe_id and persisted_universe_id != universe_id:
            raise AutonomousResearchError("CRYPTO_PROVENANCE_MISMATCH", "universe id does not match the persisted snapshot")
        persisted_hash = str(
            universe_metadata.get("snapshot_hash")
            or universe_metadata.get("content_hash")
            or universe_catalog.get("snapshot_hash")
            or ""
        ).strip()
        if persisted_hash != universe_hash:
            raise AutonomousResearchError("CRYPTO_PROVENANCE_MISMATCH", "universe snapshot_hash does not match the persisted snapshot")
        if universe_metadata.get("point_in_time") is not True:
            raise AutonomousResearchError("CRYPTO_PROVENANCE_MISMATCH", "universe snapshot is not point-in-time")

        universe_record_loader = getattr(self.store, "load_dataset_record", None)
        universe_record = (
            universe_record_loader(universe_dataset_id, universe_version)
            if callable(universe_record_loader)
            else None
        )
        universe_rows = universe_record.get("records") if isinstance(universe_record, Mapping) else None
        if isinstance(universe_rows, Mapping):
            universe_rows = universe_rows.get("records", universe_rows.get("rows", ()))
        if not isinstance(universe_rows, (list, tuple)):
            universe_rows = self.store.load_dataset(universe_dataset_id, universe_version)
        if not isinstance(universe_rows, (list, tuple)):
            raise AutonomousResearchError("INSUFFICIENT_DATA", "persisted universe snapshot has no bounded records")
        selected: dict[str, str] = {}
        for row in universe_rows:
            if not isinstance(row, Mapping) or not bool(row.get("selected")):
                continue
            for key in ("binance_symbol", "symbol", "instrument"):
                value = row.get(key)
                if value is not None and _normal_symbol(value):
                    selected.setdefault(_normal_symbol(value), str(value).strip())
        declared_values = universe_document.get("instruments")
        if declared_values is None:
            declared_values = universe_document.get("symbols")
        if declared_values is None:
            declared_values = ()
        if isinstance(declared_values, str) or not isinstance(declared_values, (list, tuple)):
            raise AutonomousResearchError(
                "CRYPTO_PROVENANCE_MISMATCH",
                "plan universe instruments/symbols must be a bounded list",
            )
        if not declared_values:
            raise AutonomousResearchError(
                "CRYPTO_PROVENANCE_MISMATCH",
                "plan universe instruments/symbols must contain at least one symbol",
            )
        declared: set[str] = set()
        for index, value in enumerate(declared_values):
            normalized = _normal_symbol(value)
            if value is None or not str(value).strip() or not normalized:
                raise AutonomousResearchError(
                    "CRYPTO_PROVENANCE_MISMATCH",
                    f"plan universe instruments/symbols contains an empty symbol at index {index}",
                )
            if normalized in declared:
                raise AutonomousResearchError(
                    "CRYPTO_PROVENANCE_MISMATCH",
                    f"plan universe instruments/symbols contains duplicate normalized symbol {normalized!r}",
                )
            declared.add(normalized)
        persisted = set(selected)
        if declared != persisted:
            missing = sorted(persisted - declared)
            unexpected = sorted(declared - persisted)
            raise AutonomousResearchError(
                "CRYPTO_PROVENANCE_MISMATCH",
                "plan universe instruments do not exactly match persisted selected rows: "
                f"declared={sorted(declared)!r}; persisted={sorted(persisted)!r}; "
                f"missing={missing!r}; unexpected={unexpected!r}",
            )

        target = plan.target_instrument
        target_key = _normal_symbol(target)
        if not target_key or target_key not in selected:
            raise AutonomousResearchError(
                "CRYPTO_UNIVERSE_MEMBERSHIP_MISMATCH",
                f"selected instrument {target or '<missing>'} is not a member of the persisted universe",
            )
        return {
            "dataset": {
                "dataset_id": dataset_id,
                "dataset_version": dataset_version,
                "timeframe": catalog_timeframe,
                "source": catalog_source,
                "source_type": catalog_source_type,
                "survivorship_bias": survivorship,
                "snapshot_id": str(catalog.get("snapshot_id", "")).strip(),
            },
            "universe": {
                "universe_id": universe_id,
                "universe_version": universe_version,
                "snapshot_hash": universe_hash,
                "dataset_id": universe_dataset_id,
                "snapshot_id": str(universe_catalog.get("snapshot_id", "")).strip(),
                "methodology": str(universe_document.get("methodology", "")).strip(),
                "point_in_time": True,
            },
            "selected_symbol": selected[target_key],
        }
    def _dataset_attestation(
        self,
        plan: ExperimentPlan,
        *,
        strict: bool = True,
    ) -> Mapping[str, Any]:
        """Load dataset attestation used by frozen scope evidence.

        Automatic queue items and legacy-scope reassessments call this in the
        default strict mode. Ordinary manually submitted proposals retain the
        historical compatibility path: their dataset rows remain the source
        of historical evaluation, while attestation is optional metadata.
        """
        dataset_id = plan.dataset_id
        dataset_version = plan.dataset_version
        if not dataset_id and dataset_version:
            finder = getattr(self.store, "load_dataset_by_version", None)
            try:
                resolved = finder(dataset_version) if callable(finder) else None
            except Exception:
                if strict:
                    raise
                resolved = None
            if isinstance(resolved, Mapping):
                candidate_id = resolved.get("dataset_id")
                if candidate_id is not None and str(candidate_id).strip():
                    dataset_id = str(candidate_id).strip()
        if not dataset_id or not dataset_version:
            if not strict:
                return {}
            raise AutonomousResearchError(
                "DATASET_ATTESTATION_MISSING",
                "frozen scope evidence requires an exact dataset selector",
            )
        loader = getattr(self.store, "load_dataset_integrity_attestation", None)
        verifier = getattr(self.store, "verify_dataset_integrity_attestation", None)
        try:
            attestation = loader(dataset_id, dataset_version) if callable(loader) else None
            if not isinstance(attestation, Mapping) and callable(verifier):
                attestation = verifier(dataset_id, dataset_version)
        except Exception:
            if not strict:
                return {}
            raise
        if not isinstance(attestation, Mapping):
            if not strict:
                return {}
            raise AutonomousResearchError(
                "DATASET_ATTESTATION_MISSING",
                f"no immutable dataset attestation for {dataset_id}/{dataset_version}",
            )
        return dict(attestation)

    def _validate_campaign_dataset_provenance(
        self,
        dataset_id: str,
        dataset_version: str,
        *,
        boundary: Mapping[str, Any] | None = None,
        source: Mapping[str, Any] | None = None,
        plan: ExperimentPlan | None = None,
        expected_attestation_hash: str | None = None,
    ) -> Mapping[str, Any]:
        """Validate a campaign dataset fence before loading any trial rows."""
        identifier = str(dataset_id).strip()
        version = str(dataset_version).strip()

        def invalid(detail: str) -> NoReturn:
            raise AutonomousResearchError("SOFTWARE_OR_INPUT_ERROR", detail)

        if not identifier or not version or version.casefold() in _MUTABLE_DATASET_VERSION_ALIASES:
            invalid("campaign requires an exact immutable dataset id and version")
        catalog_loader = getattr(self.store, "load_dataset_catalog", None)
        if not callable(catalog_loader):
            invalid(f"no persisted dataset catalog for {identifier}/{version}")
        try:
            catalog = catalog_loader(identifier, version)
        except Exception as exc:
            invalid(f"persisted dataset catalog could not be loaded for {identifier}/{version}: {exc}")
        if not isinstance(catalog, Mapping):
            invalid(f"no persisted dataset catalog for {identifier}/{version}")
        catalog_id = str(catalog.get("dataset_id", "")).strip()
        catalog_version = str(catalog.get("dataset_version", catalog.get("version", ""))).strip()
        if catalog_id != identifier or catalog_version != version:
            invalid("campaign dataset catalog identity does not match its frozen boundary")
        if catalog.get("missing_ranges"):
            invalid("campaign dataset catalog contains explicit missing ranges")
        if str(catalog.get("market_type", "")).strip().lower() != MarketType.PREDICTION.value:
            invalid("campaign dataset catalog market_type is not prediction")
        catalog_source_type = str(catalog.get("source_type", "")).strip().upper()
        if catalog_source_type != "HISTORICAL":
            invalid(
                "campaign dataset catalog source_type "
                f"{catalog_source_type or '<missing>'} is not HISTORICAL"
            )
        catalog_instrument = str(catalog.get("instrument", "")).strip().upper()
        if catalog_instrument != "POLYMARKET":
            invalid("campaign dataset catalog instrument is not POLYMARKET")
        if catalog.get("missing_ranges"):
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                "persisted dataset catalog contains explicit missing ranges",
            )
        metadata = catalog.get("metadata")
        metadata = metadata if isinstance(metadata, Mapping) else {}
        metadata_source_type = str(metadata.get("source_type", "")).strip().upper()
        if metadata_source_type and metadata_source_type != "HISTORICAL":
            invalid("campaign dataset metadata source_type is not HISTORICAL")
        if catalog.get("discovery_complete") is False:
            invalid("campaign dataset catalog discovery coverage is incomplete")
        coverage_status = str(metadata.get("coverage_status", "")).strip().upper()
        if coverage_status and coverage_status != "COMPLETE":
            invalid("campaign dataset catalog coverage status is not COMPLETE")
        requested_coverage = metadata.get("requested_coverage")
        if (
            isinstance(requested_coverage, Mapping)
            and requested_coverage.get("discovery_complete") is not True
        ):
            invalid("campaign dataset requested coverage is incomplete")

        declared = source if isinstance(source, Mapping) else {}
        selector = declared.get("dataset_selector")
        selector = dict(selector) if isinstance(selector, Mapping) else {}
        for raw_name, field in (
            ("dataset_source_type", "source_type"),
            ("dataset_source", "source"),
            ("dataset_timeframe", "timeframe"),
        ):
            if raw_name in declared and declared.get(raw_name) is not None:
                selector.setdefault(field, declared.get(raw_name))
        if plan is not None:
            selector = plan.dataset_selector
        for field in ("provider", "source", "timeframe", "interval", "source_type"):
            value = selector.get(field)
            if value is None or not str(value).strip():
                continue
            if field == "source_type":
                if str(value).strip().upper() != catalog_source_type:
                    invalid(f"campaign dataset selector {field} does not match HISTORICAL")
            elif field in {"timeframe", "interval"}:
                if str(value).strip() != str(catalog.get("timeframe", "")).strip():
                    invalid(f"campaign dataset selector {field} does not match its catalog")
            else:
                catalog_source = str(
                    catalog.get("provider", catalog.get("source", ""))
                ).strip()
                if str(value).strip() != catalog_source:
                    invalid(f"campaign dataset selector {field} does not match its catalog")

        try:
            catalog_count = catalog.get("row_count")
            catalog_complete = float(catalog.get("completeness", 0.0))
        except (TypeError, ValueError, OverflowError):
            invalid("campaign dataset catalog row count or completeness is malformed")
        if (
            isinstance(catalog_count, bool)
            or not isinstance(catalog_count, int)
            or catalog_count <= 0
            or not math.isfinite(catalog_complete)
            or catalog_complete < 1.0
        ):
            invalid("campaign dataset catalog is empty or incomplete")

        if isinstance(boundary, Mapping):
            boundary_id = str(boundary.get("dataset_id", "")).strip()
            boundary_version = str(boundary.get("dataset_version", "")).strip()
            boundary_source = str(boundary.get("source_type", "")).strip().upper()
            if (
                boundary_id != identifier
                or boundary_version != version
                or boundary_source != "HISTORICAL"
            ):
                invalid("campaign dataset provenance does not match its frozen boundary")
            boundary_count = boundary.get("row_count")
            if (
                isinstance(boundary_count, bool)
                or not isinstance(boundary_count, int)
                or boundary_count != catalog_count
            ):
                invalid("campaign dataset row count does not match its frozen boundary")

        attestation_loader = getattr(self.store, "load_dataset_integrity_attestation", None)
        if not callable(attestation_loader):
            invalid(f"no persisted dataset attestation for {identifier}/{version}")
        try:
            attestation = attestation_loader(identifier, version)
        except Exception as exc:
            invalid(f"persisted dataset attestation could not be loaded for {identifier}/{version}: {exc}")
        if not isinstance(attestation, Mapping):
            invalid(f"no persisted dataset attestation for {identifier}/{version}")
        attestation_id = str(attestation.get("dataset_id", "")).strip()
        attestation_version = str(attestation.get("dataset_version", "")).strip()
        attestation_hash = str(attestation.get("attestation_hash", "")).strip()
        if (
            attestation_id != identifier
            or attestation_version != version
            or not attestation_hash
        ):
            invalid("campaign dataset attestation identity or hash is mismatched")
        if expected_attestation_hash and attestation_hash != str(expected_attestation_hash).strip():
            invalid("campaign reassessment evidence does not match the current attestation")
        if isinstance(boundary, Mapping):
            frozen_hash = str(boundary.get("attestation_hash", "")).strip()
            if frozen_hash and frozen_hash != attestation_hash:
                invalid("campaign dataset attestation changed after the boundary was frozen")
        if str(attestation.get("status", "")).strip().upper() != "CURRENT":
            invalid("campaign dataset attestation is not CURRENT")
        if str(attestation.get("source_type", "")).strip().upper() != "HISTORICAL":
            invalid("campaign dataset attestation source_type is not HISTORICAL")
        if str(attestation.get("market_type", "")).strip().lower() != MarketType.PREDICTION.value:
            invalid("campaign dataset attestation market_type is not prediction")
        if str(attestation.get("contamination_result", "")).strip().upper() != "PASS":
            invalid("campaign dataset attestation reports forward contamination")
        attestation_count = attestation.get("row_count")
        try:
            attestation_complete = float(attestation.get("completeness", 0.0))
        except (TypeError, ValueError, OverflowError):
            invalid("campaign dataset attestation completeness is malformed")
        if (
            isinstance(attestation_count, bool)
            or not isinstance(attestation_count, int)
            or attestation_count != catalog_count
            or not math.isfinite(attestation_complete)
            or attestation_complete < 1.0
        ):
            invalid("campaign dataset attestation does not match its catalog")
        return dict(attestation)

    def _validate_persisted_dataset_provenance(
        self,
        plan: ExperimentPlan,
        *,
        legacy_document: Mapping[str, Any] | None = None,
    ) -> Mapping[str, Any]:
        """Require an exact, current store attestation before prediction research."""
        if plan.market_type is not MarketType.PREDICTION:
            return {}
        dataset_id = str(plan.dataset_id or "").strip()
        dataset_version = str(plan.dataset_version or "").strip()
        if not dataset_id or not dataset_version:
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                "prediction research requires an exact persisted dataset id and version",
            )
        if dataset_version.casefold() in _MUTABLE_DATASET_VERSION_ALIASES:
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                f"dataset version {dataset_version!r} is a mutable alias; an immutable dataset version is required",
            )

        catalog_loader = getattr(self.store, "load_dataset_catalog", None)
        if not callable(catalog_loader):
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                f"store has no exact persisted dataset catalog for {dataset_id}/{dataset_version}",
            )
        try:
            catalog = catalog_loader(dataset_id, dataset_version)
        except Exception as exc:
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                f"persisted dataset catalog could not be loaded for {dataset_id}/{dataset_version}",
            ) from exc
        if not isinstance(catalog, Mapping):
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                f"no exact persisted dataset catalog for {dataset_id}/{dataset_version}",
            )
        catalog_id = str(catalog.get("dataset_id", "")).strip()
        catalog_version = str(catalog.get("dataset_version", catalog.get("version", ""))).strip()
        if (
            catalog_id != dataset_id
            or catalog_version != dataset_version
            or catalog_version.casefold() in _MUTABLE_DATASET_VERSION_ALIASES
        ):
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                "dataset catalog identity does not match the exact plan binding",
            )
        if str(catalog.get("market_type", "")).strip().lower() != MarketType.PREDICTION.value:
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                "dataset catalog market_type is not prediction",
            )
        catalog_source_type = str(catalog.get("source_type", "")).strip().upper()
        if catalog_source_type != "HISTORICAL":
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                f"dataset catalog source_type {catalog_source_type or '<missing>'} is not HISTORICAL",
            )
        catalog_instrument = str(catalog.get("instrument", "")).strip()
        scope_instrument = str(plan.market_scope.instrument or "").strip()
        if scope_instrument and catalog_instrument != scope_instrument:
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                "dataset catalog instrument does not match the exact plan market-scope instrument",
            )
        catalog_metadata = catalog.get("metadata")
        if isinstance(catalog_metadata, Mapping):
            metadata_instrument = str(catalog_metadata.get("instrument", "")).strip()
            if metadata_instrument and metadata_instrument != catalog_instrument:
                raise AutonomousResearchError(
                    "DATASET_PROVENANCE_INVALID",
                    "dataset catalog instrument metadata conflicts with its canonical instrument",
                )

        selector = plan.dataset_selector
        declared_selectors: dict[str, list[Any]] = {
            name: [selector.get(name)]
            for name in ("provider", "source", "timeframe", "interval", "source_type")
            if selector.get(name) is not None and str(selector.get(name)).strip()
        }
        if legacy_document is not None:
            nested = legacy_document.get("experiment_plan")
            nested = nested if isinstance(nested, Mapping) else {}
            for source in (legacy_document, nested):
                raw_selector = source.get("dataset_selector")
                if isinstance(raw_selector, Mapping):
                    for name in ("provider", "source", "timeframe", "interval", "source_type"):
                        value = raw_selector.get(name)
                        if value is not None and str(value).strip():
                            declared_selectors.setdefault(name, []).append(value)
                for raw_name, name in (
                    ("dataset_source", "source"),
                    ("dataset_source_type", "source_type"),
                    ("dataset_timeframe", "timeframe"),
                ):
                    value = source.get(raw_name)
                    if value is not None and str(value).strip():
                        declared_selectors.setdefault(name, []).append(value)
        catalog_sources = [
            str(catalog.get(name)).strip()
            for name in ("provider", "source")
            if catalog.get(name) is not None and str(catalog.get(name)).strip()
        ]
        if len(set(catalog_sources)) > 1:
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                "dataset catalog provider and source selectors disagree",
            )
        catalog_source = catalog_sources[0] if catalog_sources else ""
        for name in ("provider", "source"):
            for declared in declared_selectors.get(name, ()):
                if str(declared).strip() != catalog_source:
                    raise AutonomousResearchError(
                        "DATASET_PROVENANCE_INVALID",
                        f"dataset selector {name} does not match the exact catalog provider/source",
                    )
        catalog_timeframe = str(catalog.get("timeframe", "")).strip()
        for name in ("timeframe", "interval"):
            for declared in declared_selectors.get(name, ()):
                if str(declared).strip() != catalog_timeframe:
                    raise AutonomousResearchError(
                        "DATASET_PROVENANCE_INVALID",
                        f"dataset selector {name} does not match the exact catalog timeframe",
                    )
        for declared_source_type in declared_selectors.get("source_type", ()):
            if str(declared_source_type).strip().upper() != catalog_source_type:
                raise AutonomousResearchError(
                    "DATASET_PROVENANCE_INVALID",
                    "dataset selector source_type does not match the exact catalog",
                )

        attestation_loader = getattr(self.store, "load_dataset_integrity_attestation", None)
        if not callable(attestation_loader):
            raise AutonomousResearchError(
                "DATASET_ATTESTATION_MISSING",
                f"store has no persisted dataset attestation for {dataset_id}/{dataset_version}",
            )
        try:
            attestation = attestation_loader(dataset_id, dataset_version)
        except Exception as exc:
            raise AutonomousResearchError(
                "DATASET_ATTESTATION_MISSING",
                f"persisted dataset attestation could not be loaded for {dataset_id}/{dataset_version}",
            ) from exc
        if not isinstance(attestation, Mapping):
            raise AutonomousResearchError(
                "DATASET_ATTESTATION_MISSING",
                f"no persisted dataset attestation for {dataset_id}/{dataset_version}",
            )
        if (
            str(attestation.get("dataset_id", "")).strip() != dataset_id
            or str(attestation.get("dataset_version", "")).strip() != dataset_version
            or not str(attestation.get("attestation_hash", "")).strip()
        ):
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                "persisted dataset attestation identity or hash does not match the exact plan binding",
            )
        status = str(attestation.get("status", "")).strip().upper()
        if status != "CURRENT":
            reason = str(attestation.get("reason") or status or "UNKNOWN").strip().upper()
            raise AutonomousResearchError(
                "DATASET_ATTESTATION_STALE",
                f"persisted dataset attestation is not CURRENT ({reason})",
            )
        provenance_payload = {
            "market_type": MarketType.PREDICTION.value,
            "dataset_id": dataset_id,
            "dataset_version": dataset_version,
            "dataset_provenance": {
                "dataset_id": dataset_id,
                "dataset_version": dataset_version,
                "source_type": catalog_source_type,
                "time_split": plan.methodology.get("time_split"),
            },
        }
        quality = evaluate_prediction_data_quality(
            self.store,
            provenance_payload,
            verify_attestation=False,
        )

        reasons = quality.get("reasons", ())
        if (
            quality.get("historical_data_integrity_passed") is not True
            or quality.get("historical_provenance_complete") is not True
            or quality.get("historical_rows_nonempty") is not True
            or quality.get("historical_no_forward_contamination") is not True
        ):
            detail = "; ".join(str(reason) for reason in reasons if str(reason).strip())
            raise AutonomousResearchError(
                "DATASET_PROVENANCE_INVALID",
                detail or f"persisted dataset provenance is invalid for {dataset_id}/{dataset_version}",
            )
        return quality
    def _revalidate_generated_queue_item(
        self,
        item: ResearchQueueItem,
        plan: ExperimentPlan,
        payload: Mapping[str, Any],
    ) -> None:
        """Revalidate attestation only for self-authenticating worker items."""
        internal = _generated_queue_provenance(payload)
        if internal is None:
            return
        if (
            internal.get("schema") != _GENERATED_QUEUE_PROVENANCE_SCHEMA
            or internal.get("generated") is not True
            or str(internal.get("kind", "")).strip() not in _GENERATED_QUEUE_KINDS
        ):
            raise AutonomousResearchError(
                "GENERATED_PROVENANCE_INVALID",
                "generated queue provenance marker is malformed",
            )
        expected_identity = str(internal.get("proposal_identity", "")).strip()
        if not expected_identity or expected_identity != _proposal_identity(payload):
            raise AutonomousResearchError(
                "GENERATED_PROVENANCE_INVALID",
                "generated queue provenance does not match the canonical proposal identity",
            )
        dataset_id = str(plan.dataset_id or "").strip()
        dataset_version = str(plan.dataset_version or "").strip()
        if (
            str(internal.get("dataset_id", "")).strip() != dataset_id
            or str(internal.get("dataset_version", "")).strip() != dataset_version
        ):
            raise AutonomousResearchError(
                "GENERATED_PROVENANCE_INVALID",
                "generated queue provenance dataset binding does not match the canonical plan",
            )
        self._validate_persisted_dataset_provenance(plan)
        attestation_loader = getattr(self.store, "load_dataset_integrity_attestation", None)
        if not callable(attestation_loader):
            raise AutonomousResearchError(
                "DATASET_ATTESTATION_MISSING",
                f"generated queue item has no persisted dataset attestation for {dataset_id}/{dataset_version}",
            )
        try:
            attestation = attestation_loader(dataset_id, dataset_version)
        except Exception as exc:
            raise AutonomousResearchError(
                "DATASET_ATTESTATION_MISSING",
                f"generated queue item attestation could not be loaded for {dataset_id}/{dataset_version}",
            ) from exc
        current_hash = (
            str(attestation.get("attestation_hash", "")).strip()
            if isinstance(attestation, Mapping)
            else ""
        )
        expected_hash = str(internal.get("attestation_hash", "")).strip()
        if not expected_hash or current_hash != expected_hash:
            raise AutonomousResearchError(
                "DATASET_ATTESTATION_CHANGED",
                "generated queue item attestation changed after enqueue",
            )

    def _load_prediction_dataset_by_version(self, version: str) -> Any | None:
        """Load a datasetless prediction plan only when its version is unambiguous."""
        connection = getattr(self.store, "connection", None)
        execute = getattr(connection, "execute", None)
        if callable(execute):
            try:
                matches = execute(
                    "SELECT dataset_id, 'datasets' AS source FROM datasets WHERE version=? "
                    "UNION ALL "
                    "SELECT dataset_id, 'dataset_catalog' AS source "
                    "FROM dataset_catalog WHERE dataset_version=? "
                    "ORDER BY dataset_id, source",
                    (str(version), str(version)),
                ).fetchall()
            except Exception as exc:
                raise AutonomousResearchError(
                    "INSUFFICIENT_DATA",
                    f"immutable dataset lookup failed for version {version}",
                ) from exc
            if len(matches) > 1:
                identities = ", ".join(f"{row[1]}:{row[0]}" for row in matches)
                raise AutonomousResearchError(
                    "INSUFFICIENT_DATA",
                    f"ambiguous immutable datasets at version {version}: {identities}",
                )
            if not matches:
                return None
            dataset_id = str(matches[0][0]).strip()
            loader = getattr(self.store, "load_dataset", None)
            if callable(loader):
                return loader(dataset_id, version)
            return None

        finder = getattr(self.store, "load_dataset_by_version", None)
        if callable(finder):
            found = finder(version)
            if isinstance(found, Mapping):
                found_version = str(found.get("version", found.get("dataset_version", ""))).strip()
                if found_version == str(version):
                    return found.get("records")
        return None

    def _load_split(
        self,
        plan: ExperimentPlan,
        *,
        boundary_override: Mapping[str, Any] | None = None,
    ) -> tuple[list[Mapping[str, Any]], Any]:
        records: Any = None
        if plan.dataset_version.lower() in {"latest", "current", "default", "unversioned"}:
            if plan.market_type is MarketType.CRYPTO_SPOT:
                raise AutonomousResearchError(
                    "INSUFFICIENT_DATA",
                    "crypto dataset_version must be immutable and versioned",
                )
            raise AutonomousResearchError(
                "INSUFFICIENT_DATA",
                "dataset_version must identify an immutable version",
            )
        if plan.market_type is MarketType.CRYPTO_SPOT:
            self._crypto_binding(plan)
            if not plan.dataset_id:
                raise AutonomousResearchError(
                    "INSUFFICIENT_DATA",
                    "crypto_spot research requires a versioned dataset_id",
                )
            loader = getattr(self.store, "load_dataset_record", None)
            if callable(loader):
                record = loader(plan.dataset_id, plan.dataset_version)
                if isinstance(record, Mapping):
                    record_version = str(record.get("version", record.get("dataset_version", ""))).strip()
                    if record_version and record_version != plan.dataset_version:
                        raise AutonomousResearchError(
                            "CRYPTO_PROVENANCE_MISMATCH",
                            "dataset record version does not match the plan",
                        )
                    records = record.get("records")
            if records is None:
                records = self.store.load_dataset(plan.dataset_id, plan.dataset_version)
        elif plan.dataset_id:
            records = self.store.load_dataset(plan.dataset_id, plan.dataset_version)
        else:
            records = self._load_prediction_dataset_by_version(plan.dataset_version)
        if records is None:
            raise AutonomousResearchError(
                "INSUFFICIENT_DATA",
                f"no immutable dataset {plan.dataset_id or '*'} at version {plan.dataset_version}",
            )
        if isinstance(records, Mapping):
            records = records.get("records", records.get("rows", records.get("observations", ())))
        if not isinstance(records, (list, tuple)):
            raise AutonomousResearchError("INSUFFICIENT_DATA", "dataset records are not a bounded sequence")
        rows = [_normalize_row(item) for item in list(records)[:_MAX_DATASET_ROWS]]
        rows = [row for row in rows if row is not None]
        boundary = boundary_override if boundary_override is not None else plan.dataset_boundary
        expected_digest = (
            str(boundary.get("ordered_row_manifest_digest", boundary.get("content_hash", ""))).strip()
            if isinstance(boundary, Mapping)
            else ""
        )
        if expected_digest:
            boundary_ordered = sorted(
                rows,
                key=lambda row: (
                    parse_timestamp(row.get("timestamp", row.get("source_timestamp")))
                    or datetime.min.replace(tzinfo=timezone.utc),
                    _campaign_row_identity(row, 0),
                    _hash_document(row),
                ),
            )
            actual_provenance = _campaign_compact_row_provenance(boundary_ordered)
            if (
                actual_provenance["row_count"] != int(boundary.get("row_count", -1))
                or actual_provenance["exact_cutoff"] != boundary.get("exact_cutoff")
                or actual_provenance["ordered_row_manifest_digest"] != expected_digest
            ):
                raise AutonomousResearchError(
                    "DATASET_PROVENANCE_INVALID",
                    "dataset rows changed after the campaign boundary was locked",
                )
        rows = self._apply_plan_filters(plan, rows)
        rows = self._apply_model_document(plan, rows)
        if not rows:
            # A schema-valid paper intent must remain durable when the immutable
            # dataset is empty after scope/model filters.  Keep the historical
            # partition empty; no observations or qualification are inferred.
            empty_start = datetime(1970, 1, 1, tzinfo=timezone.utc)
            return [], split_dataset(
                (),
                empty_start,
                empty_start + timedelta(microseconds=1),
                empty_start + timedelta(microseconds=2),
                dataset_version=plan.dataset_version,
                require_nonempty=False,
            )
        for feature in plan.allowed_features:
            if feature in {"timestamp", "market_id", "symbol", "expiry", "settlement", "question", "resolution_criteria"}:
                continue
            if not any(_value(row, feature) is not None for row in rows):
                raise AutonomousResearchError("INSUFFICIENT_DATA", f"dataset has no values for feature {feature}")
        stamps = [parse_timestamp(_value(row, "timestamp")) for row in rows]
        if any(stamp is None for stamp in stamps):
            raise AutonomousResearchError("INSUFFICIENT_DATA", "dataset contains rows without timestamps")
        ordered = [
            row
            for _, row in sorted(
                zip(stamps, rows),
                key=lambda pair: (pair[0], _value(pair[1], "market_id", "")),
            )
        ]

        def sparse_split() -> Any:
            # Preserve the immutable rows even when there are too few
            # distinct time boundaries to form three non-empty partitions.
            first_stamp = parse_timestamp(_value(ordered[0], "timestamp"))
            if first_stamp is None:
                raise AutonomousResearchError("INSUFFICIENT_DATA", "dataset timestamps are invalid")
            return split_dataset(
                ordered,
                first_stamp + timedelta(microseconds=1),
                first_stamp + timedelta(microseconds=2),
                first_stamp + timedelta(microseconds=3),
                dataset_version=plan.dataset_version,
                require_nonempty=False,
            )

        if len(ordered) < 3:
            # Keep the immutable rows and their chronological partition even
            # when historical evidence is too small to backtest.  The caller
            # records the already-registered paper intent as SCHEMA_VALIDATED;
            # no historical metrics or forward authority are inferred here.
            return ordered, sparse_split()
        train_count = max(1, int(len(ordered) * 0.60))
        validation_count = max(1, int(len(ordered) * 0.20))
        if train_count + validation_count >= len(ordered):
            train_count = max(1, len(ordered) - 2)
            validation_count = 1
        train_end = parse_timestamp(_value(ordered[train_count], "timestamp"))
        validation_end = parse_timestamp(_value(ordered[train_count + validation_count], "timestamp"))
        holdout_end = parse_timestamp(_value(ordered[-1], "timestamp"))
        if train_end is None or validation_end is None or holdout_end is None:
            raise AutonomousResearchError("INSUFFICIENT_DATA", "dataset timestamps are invalid")
        split = split_dataset(
            ordered,
            train_end,
            validation_end,
            holdout_end + timedelta(microseconds=1),
            dataset_version=plan.dataset_version,
            require_nonempty=False,
        )
        if not split.train or not split.validation or not split.holdout:
            return ordered, sparse_split()
        # The locked holdout is evaluated once after the complete trial set is
        # fixed. It never feeds selection, mutation, Hermes, or qualification.
        return ordered, split

    def _apply_plan_filters(self, plan: ExperimentPlan, rows: Sequence[Mapping[str, Any]]) -> list[Mapping[str, Any]]:
        # Historical qualification is bound only to the plan's explicit
        # top-level filters; current market-scope filters belong to forward
        # resolution and must not remove PRICE_PROXY history rows.
        filters = dict(plan.filters)
        restrictions = dict(plan.regime_restrictions)
        supported = {
            "entry_price",
            "minimum_hours_to_resolution",
            "maximum_hours_to_resolution",
            "min_liquidity",
            "max_spread",
            "regime",
            "regimes",
            "category",
        }
        unknown = sorted(set(filters) - supported)
        if unknown:
            raise AutonomousResearchError("UNSUPPORTED_FEATURE", f"unsupported plan filters: {unknown}")
        supported_restrictions = {"regime", "regimes", "allowed_regimes", "allowed_states"}
        unknown_restrictions = sorted(set(restrictions) - supported_restrictions)
        if unknown_restrictions:
            raise AutonomousResearchError(
                "UNSUPPORTED_FEATURE",
                f"unsupported regime restrictions: {unknown_restrictions}",
            )
        allowed_regimes = filters.get("regime", filters.get("regimes"))
        restricted_regimes = restrictions.get(
            "allowed_regimes",
            restrictions.get("allowed_states", restrictions.get("regime", restrictions.get("regimes"))),
        )
        if allowed_regimes is not None and restricted_regimes is not None:
            allowed_regimes = _as_regime_set(allowed_regimes, "regime filter") & _as_regime_set(
                restricted_regimes,
                "regime restrictions",
            )
        elif allowed_regimes is None:
            allowed_regimes = restricted_regimes
        elif allowed_regimes is not None:
            allowed_regimes = _as_regime_set(allowed_regimes, "regime filter")
        target_markets = set(plan.target_markets)
        target_instrument = plan.target_instrument
        target_instrument_key = _normal_symbol(target_instrument) if target_instrument else ""
        historical_polymarket_scope = (
            plan.market_type is MarketType.PREDICTION and target_instrument_key == "POLYMARKET"
        )
        result: list[Mapping[str, Any]] = []
        for row in rows:
            market_id = str(_value(row, "market_id", "")).strip()
            if target_markets and market_id not in target_markets:
                continue
            if historical_polymarket_scope:
                # Historical price-history rows may omit venue identity.  The
                # exact dataset selector and its immutable attestation bind
                # those rows; an explicitly supplied identity still has to
                # agree with the canonical Polymarket scope.
                row_symbol = _binding_value(_value(row, "symbol"))
                row_instrument = _binding_value(_value(row, "instrument"))
                if row_symbol is not None and _normal_symbol(row_symbol) != target_instrument_key:
                    continue
                if row_instrument is not None and _normal_symbol(row_instrument) != target_instrument_key:
                    continue
            elif target_instrument:
                symbol = str(_value(row, "symbol", _value(row, "instrument", ""))).strip()
                if target_instrument not in {market_id, symbol}:
                    continue
            if "category" in filters:
                actual_category = str(_value(row, "category", "") or "").strip().casefold()
                expected_category = filters["category"]
                expected_categories = (
                    expected_category
                    if isinstance(expected_category, (list, tuple, set))
                    else (expected_category,)
                )
                if actual_category not in {str(item).strip().casefold() for item in expected_categories if str(item).strip()}:
                    continue
            price = _finite(_value(row, "yes_mid", _value(row, "yes_ask")), math.nan)
            if "entry_price" in filters and not _in_bound(price, filters["entry_price"]):
                continue
            seconds = _time_to_expiry(row)
            if "minimum_hours_to_resolution" in filters:
                minimum = _finite(filters["minimum_hours_to_resolution"], math.nan) * 3600.0
                if not math.isfinite(seconds) or seconds < minimum:
                    continue
            if "maximum_hours_to_resolution" in filters:
                maximum = _finite(filters["maximum_hours_to_resolution"], math.nan) * 3600.0
                if not math.isfinite(seconds) or seconds > maximum:
                    continue
            liquidity = _finite(_value(row, "liquidity"), math.nan)
            if "min_liquidity" in filters and (not math.isfinite(liquidity) or liquidity < _finite(filters["min_liquidity"], math.inf)):
                continue
            spread = _finite(_value(row, "spread"), math.nan)
            if "max_spread" in filters and (not math.isfinite(spread) or spread > _finite(filters["max_spread"], -math.inf)):
                continue
            if allowed_regimes is not None:
                regime = _value(row, "regime", _value(row, "regime_state"))
                if str(regime) not in allowed_regimes:
                    continue
            result.append(row)
        return result

    @staticmethod
    def _apply_model_document(plan: ExperimentPlan, rows: Sequence[Mapping[str, Any]]) -> list[Mapping[str, Any]]:
        model = plan.model_for()
        if model is None:
            return list(rows)
        result: list[Mapping[str, Any]] = []
        for row in rows:
            clean = dict(row)
            probability = evaluate_model_document_probability(model, clean)
            if probability is not None:
                clean["model_probability"] = probability
            result.append(clean)
        return result

    def _evaluate_datasets(
        self,
        plan: ExperimentPlan,
        strategy: StrategyDefinition,
        train: Sequence[Mapping[str, Any]],
        validation: Sequence[Mapping[str, Any]],
        holdout: Sequence[Mapping[str, Any]] = (),
    ) -> dict[str, Mapping[str, Any]]:
        result: dict[str, Mapping[str, Any]] = {
            "train": self._run_backtest(plan, strategy, train),
            "validation": self._run_backtest(plan, strategy, validation),
        }
        if holdout:
            # This is an attested, chronological review only.  It is not part
            # of variant selection, mutation, or canary qualification.
            result["holdout"] = self._run_backtest(plan, strategy, holdout)
        return result

    @staticmethod
    def _run_backtest(plan: ExperimentPlan, strategy: StrategyDefinition, rows: Sequence[Mapping[str, Any]]) -> Mapping[str, Any]:
        methodology = plan.methodology
        assumptions = plan.assumptions if isinstance(plan.assumptions, Mapping) else {}
        initial_cash = _finite(methodology.get("initial_cash"), 10_000.0)
        fee_bps = _finite(assumptions.get("fee_bps"), _finite(methodology.get("fee_bps"), 0.0))
        slippage_bps = _finite(assumptions.get("slippage_bps"), _finite(methodology.get("slippage_bps"), 0.0))
        allocation = _finite(methodology.get("allocation"), 0.25)
        if (
            not math.isfinite(initial_cash)
            or initial_cash <= 0
            or not math.isfinite(fee_bps)
            or fee_bps < 0
            or not math.isfinite(slippage_bps)
            or slippage_bps < 0
        ):
            raise AutonomousResearchError("INVALID_PLAN", "cost assumptions must be finite and non-negative")
        holding_period = 1
        research_mode: str | None = None
        exit_policy: Mapping[str, Any] | None = None
        if plan.market_type is MarketType.PREDICTION:
            research_mode = str(plan.research_mode or methodology.get("research_mode") or "PRICE_PROXY_RESEARCH").strip().upper()
            exit_policy = dict(plan.exit_policy) if isinstance(plan.exit_policy, Mapping) else {
                "type": "fixed_holding_period",
                "holding_period": 1,
            }
            holding_period = exit_policy.get("holding_period")
            if isinstance(holding_period, bool) or not isinstance(holding_period, int) or holding_period < 1:
                raise AutonomousResearchError("INVALID_PLAN", "exit_policy.holding_period must be a bounded positive integer")
            result = run_prediction_research_mode(
                rows,
                strategy,
                mode=research_mode,
                initial_cash=initial_cash,
                fee_bps=fee_bps,
                slippage_bps=slippage_bps,
                allocation=max(0.0, min(1.0, allocation)),
                resolutions=None,
                model_document=plan.model_document,
                holding_period=holding_period,
                observation_horizon=(
                    dict(plan.observation_horizon)
                    if isinstance(plan.observation_horizon, Mapping)
                    else {"unit": "observations", "count": holding_period}
                ),
                exit_policy=exit_policy,
            )
        else:
            result = CryptoBacktester(
                initial_cash=initial_cash,
                fee_bps=fee_bps,
                slippage_bps=slippage_bps,
                allocation=max(0.0, min(1.0, allocation)),
                symbol=plan.target_instrument or "ASSET",
            ).run(rows, strategy, symbol=plan.target_instrument or "ASSET")
        metrics = {str(key): _finite(value, 0.0) for key, value in result.metrics.items() if _is_finite_number(value)}
        settled = len(result.outcomes)
        if plan.market_type is MarketType.PREDICTION:
            expectancy = metrics.get("roi", 0.0) if settled else metrics.get("expected_value", metrics.get("roi", 0.0))
        else:
            expectancy = metrics.get("expectancy", metrics.get("total_return", 0.0))
        curve_values = [_finite(item.get("equity"), 0.0) for item in result.equity_curve if isinstance(item, Mapping)]
        returns = [current / previous - 1.0 for previous, current in zip(curve_values, curve_values[1:]) if previous > 0]
        confidence = bootstrap_confidence_interval(
            returns or [expectancy],
            resamples=min(256, max(32, len(returns or [expectancy]) * 8)),
            seed=0,
        )
        sample_count = len(rows)
        independent = len({str(_value(row, "market_id", _value(row, "symbol", index))) for index, row in enumerate(rows)})
        liquidity_values = [_finite(_value(row, "liquidity"), math.nan) for row in rows]
        liquidity_values = [value for value in liquidity_values if math.isfinite(value)]
        regimes = {
            str(_value(row, "regime", _value(row, "regime_state", "unknown")))
            for row in rows
            if _value(row, "regime", _value(row, "regime_state")) is not None
        }
        result_quality = result.quality.value if hasattr(result.quality, "value") else str(result.quality)
        summary = {
            "sample_count": sample_count,
            "independent_samples": independent,
            "filled_trades": len(result.fills),
            "settled_markets": settled,
            "expectancy": expectancy,
            "roi": metrics.get("roi", metrics.get("total_return", 0.0)),
            "max_drawdown": metrics.get("max_drawdown", 0.0),
            "calibration": max(0.0, min(1.0, 1.0 - metrics.get("ece", 0.0))) if settled else 0.0,
            "liquidity": mean(liquidity_values) if liquidity_values else 0.0,
            "regime_count": len(regimes) if regimes else (1 if rows else 0),
            "quality": result_quality,
            "assumption_version": assumptions.get("version"),
            "cost_assumptions": {
                "fee_bps": fee_bps,
                "slippage_bps": slippage_bps,
            },
            "exit_policy": dict(exit_policy) if exit_policy is not None else None,
            "observation_horizon": (
                dict(plan.observation_horizon)
                if isinstance(plan.observation_horizon, Mapping)
                else {"unit": "observations", "count": holding_period}
            ),
            "research_mode": research_mode,
            "execution_simulation": False,
            "costs": metrics.get("fees", 0.0) + metrics.get("slippage", 0.0),
            "confidence_lower_bound": _finite(confidence.get("lower"), 0.0),
            "confidence_interval": {
                "lower": _finite(confidence.get("lower"), 0.0),
                "upper": _finite(confidence.get("upper"), 0.0),
                "count": int(confidence.get("count", 0)),
            },
            "metrics": metrics,
            "outcomes": settled,
        }
        return summary

    def _advance_candidate(
        self,
        plan: ExperimentPlan,
        candidate_id: str,
        strategy: StrategyDefinition,
        evaluation: Mapping[str, Mapping[str, Any]],
        *,
        variant_count: int,
        validation_scores: Mapping[str, float],
        now: datetime,
        generation: int,
        lineage: Sequence[str],
        crypto_binding: Mapping[str, Any] | None = None,
    ) -> Mapping[str, Any]:
        if plan.market_type is MarketType.CRYPTO_SPOT and crypto_binding is None:
            crypto_binding = self._crypto_binding(plan)
        candidate = self.lifecycle.get(candidate_id)
        if candidate is None:
            raise AutonomousResearchError("INVALID_CANDIDATE", f"candidate {candidate_id} is not registered")
        if candidate.stage is CandidateStage.REJECTED:
            return {"candidate_id": candidate_id, "stage": candidate.stage.value, "reason": candidate.rejection_reason}
        if candidate.stage in {CandidateStage.PAPER_FORWARD, CandidateStage.PAPER_PROMOTABLE}:
            return {"candidate_id": candidate_id, "stage": candidate.stage.value}
        base = {
            "candidate_id": candidate_id,
            "hypothesis_id": plan.hypothesis_id,
            "plan_id": plan.plan_id,
            **_scope_binding(plan),
            **_strategy_metadata(strategy),
            "plan_hash": plan.plan_hash,
            "dataset_id": plan.dataset_id,
            "dataset_version": plan.dataset_version,
            "dataset_provenance": {
                "dataset_id": plan.dataset_id,
                "dataset_version": plan.dataset_version,
                "time_split": plan.methodology.get("time_split"),
                "universe": dict(plan.universe or {}),
            },
            "assumptions": dict(plan.assumptions),
            "cost_assumptions": {
                "fee_bps": plan.assumptions.get("fee_bps"),
                "slippage_bps": plan.assumptions.get("slippage_bps"),
                "roundtrip_fee_bps": plan.assumptions.get("roundtrip_fee_bps"),
                "roundtrip_slippage_bps": plan.assumptions.get("roundtrip_slippage_bps"),
                "sensitivity": plan.assumptions.get("cost_sensitivity"),
            },
            "exit_policy": dict(plan.exit_policy),
            "research_mode": plan.research_mode,
            "experiment_family": plan.experiment_family,
            "generation": generation,
            "lineage": list(dict.fromkeys([*(str(value) for value in lineage), *([candidate_id] if generation else [])])),
            "market_type": plan.market_type.value,
            "paper_only": True,
            "holdout_used": False,
        }
        if crypto_binding is not None:
            base["crypto_provenance"] = dict(crypto_binding)
        if candidate.stage is CandidateStage.IDEA:
            candidate = self.lifecycle.advance(
                candidate_id,
                CandidateStage.SCHEMA_VALIDATED,
                {
                    **base,
                    "schema_valid": True,
                    "referenced_features": list(plan.allowed_features),
                    "parameter_ranges_bounded": True,
                },
                reason="declarative experiment schema validated",
            )
        train = dict(evaluation["train"])
        validation = dict(evaluation["validation"])
        if candidate.stage is CandidateStage.SCHEMA_VALIDATED:
            candidate = self.lifecycle.advance(
                candidate_id,
                CandidateStage.BACKTESTED,
                {
                    **base,
                    "backtest_complete": True,
                    "train": _compact_evidence(train),
                    "costs_included": True,
                    "raw_observations": train.get("sample_count", 0),
                    "data_quality": train.get("quality"),
                },
                reason="bounded historical simulation completed with costs",
            )
        validation_expectancy = _finite(validation.get("expectancy"), 0.0)
        if validation_expectancy < 0.0:
            self.lifecycle.reject(
                candidate_id,
                "negative_validation_expectancy",
                evidence={
                    **base,
                    "validation_complete": True,
                    "validation": _compact_evidence(validation),
                    "benchmark_comparison": {"baseline_expectancy": 0.0, "delta": validation_expectancy},
                },
                expected_stage=candidate.stage,
                expected_payload=candidate.payload,
            )
            return {
                "candidate_id": candidate_id,
                "reason": "negative_validation_expectancy",
                "reason_code": "NEGATIVE_VALIDATION_EXPECTANCY",
            }
        if candidate.stage is CandidateStage.BACKTESTED:
            candidate = self.lifecycle.advance(
                candidate_id,
                CandidateStage.VALIDATED,
                {
                    **base,
                    "validation_complete": True,
                    "validation": _compact_evidence(validation),
                    "validation_expectancy": validation_expectancy,
                    "benchmark_comparison": {"baseline_expectancy": 0.0, "delta": validation_expectancy},
                },
                reason="chronological validation completed without locked feedback",
            )
        stability = neighboring_parameter_stability(validation_scores)
        stability_value = _finite(stability.get("stable_fraction"), 0.0)
        sample_check = minimum_sample_check(
            int(validation.get("sample_count", 0)),
            trades=int(validation.get("filled_trades", 0)),
            min_observations=plan.min_samples,
            min_trades=plan.min_trades,
        )
        data_quality = train.get("quality", validation.get("quality"))
        policy_quality = evaluate_prediction_data_quality(
            self.store,
            {
                **base,
                "data_quality": data_quality,
                "validation_execution_quality": validation.get("quality"),
            },
        )
        if policy_quality.get("applicable"):
            quality_passed = bool(policy_quality.get("canary_data_quality_acceptable"))
        else:
            if isinstance(data_quality, Mapping):
                quality_passed = data_quality.get("passed")
                if not isinstance(quality_passed, bool):
                    quality_passed = str(
                        data_quality.get("label", data_quality.get("quality", ""))
                    ).strip().upper() in {"HIGH", "MEDIUM", "GOOD", "PASS", "PASSED"}
            else:
                quality_passed = str(data_quality or "").strip().upper() in {
                    "HIGH", "MEDIUM", "GOOD", "PASS", "PASSED",
                }
        robust_evidence = {
            **base,
            "data_quality": data_quality,
            "data_quality_passed": bool(quality_passed),
            **persisted_quality_fields(policy_quality),
            "robustness_passed": bool(sample_check["passed"] and stability_value >= 0.60 and validation_expectancy >= 0.0),
            "minimum_sample_check": sample_check,
            "validation_stability": stability_value,
            "validation_stability_summary": stability,
            "multiple_testing": {
                "variants_tested": variant_count,
                "selected_from_variants": variant_count,
                "selection_metric": "validation_expectancy",
                "locked_partition_used_for_selection": False,
            },
            "validation_regime_behavior": {"regimes": validation.get("regime_count", 0)},
            "validation_execution_quality": validation.get("quality"),
            "validation_confidence_interval": validation.get("confidence_interval"),
            "validation_expectancy": validation_expectancy,
            "validation_confidence_lower_bound": _finite(validation.get("confidence_lower_bound"), 0.0),
            "validation_calibration": _finite(validation.get("calibration"), 0.0),
        }
        if candidate.stage is CandidateStage.VALIDATED:
            if not sample_check["passed"]:
                self.lifecycle.reject(
                    candidate_id,
                    "INSUFFICIENT_DATA",
                    evidence=robust_evidence,
                    expected_stage=candidate.stage,
                    expected_payload=candidate.payload,
                )
                return {
                    "candidate_id": candidate_id,
                    "reason": "INSUFFICIENT_DATA",
                    "reason_code": "INSUFFICIENT_DATA",
                }
            if stability_value < 0.60:
                self.lifecycle.reject(
                    candidate_id,
                    "unstable_neighbor_parameters",
                    evidence=robust_evidence,
                    expected_stage=candidate.stage,
                    expected_payload=candidate.payload,
                )
                return {
                    "candidate_id": candidate_id,
                    "reason": "unstable_neighbor_parameters",
                    "reason_code": "UNSTABLE_NEIGHBOR_PARAMETERS",
                }
            candidate = self.lifecycle.advance(
                candidate_id,
                CandidateStage.ROBUSTNESS_CHECKED,
                robust_evidence,
                reason="bounded validation robustness checks completed",
            )
        if candidate.stage is CandidateStage.ROBUSTNESS_CHECKED and bool(base.get("selection_excluded")):
            return {
                "candidate_id": candidate_id,
                "stage": candidate.stage.value,
                "validation_expectancy": validation_expectancy,
                "variant_count": variant_count,
                "forward_test_id": None,
                "research_only": True,
                "paper_only": True,
                **_strategy_metadata(strategy),
            }
        if candidate.stage is CandidateStage.ROBUSTNESS_CHECKED:
            model_document = plan.model_for() or {"type": "deterministic"}
            dataset_attestation = self._dataset_attestation(
                plan,
                strict=generation > 0 and plan.market_type is MarketType.PREDICTION,
            )
            setup_fields = _operational_setup_fields(
                strategy.to_dict(),
                plan,
                dataset_attestation=dataset_attestation,
                dataset_boundary=plan.dataset_boundary,
            )
            if setup_fields:
                model_document = {"model_required": False}
            strategy_hash = _content_hash(strategy.to_dict())
            rolling_strategy_document = dict(strategy.to_dict())
            rolling_strategy_document.pop("strategy_id", None)
            rolling_strategy_hash = _rolling_hash(rolling_strategy_document)
            if plan.market_type is MarketType.CRYPTO_SPOT:
                # Crypto autonomous candidates are historical research only.
                # They are deliberately never registered with ForwardTestRegistry.
                risk_snapshot = {"execution_capability": "none", "max_position_fraction": 0.0}
                forward_config = {
                    "paper_only": True,
                    "execution_capability": "none",
                    "plan_id": plan.plan_id,
                    "dataset_id": plan.dataset_id,
                    "dataset_version": plan.dataset_version,
                    "strategy_document": strategy.to_dict(),
                    "model_document": dict(model_document),
                }
            else:
                risk_snapshot = {"max_position_fraction": 0.05}
                forward_config = {
                    "execution": "paper_only",
                    "market_authority_required": True,
                    "plan_id": plan.plan_id,
                    "dataset_id": plan.dataset_id,
                    "dataset_version": plan.dataset_version,
                    "strategy_document": strategy.to_dict(),
                    "model_document": dict(model_document),
                }
            forward_config.update(setup_fields)
            forward_config["candidate_id"] = candidate_id
            forward_config["observation_intent"] = True
            forward_config.update(_scope_binding(plan))
            forward_config["assumptions"] = dict(plan.assumptions)
            forward_config["cost_assumptions"] = {
                "fee_bps": plan.assumptions.get("fee_bps"),
                "slippage_bps": plan.assumptions.get("slippage_bps"),
                "roundtrip_fee_bps": plan.assumptions.get("roundtrip_fee_bps"),
                "roundtrip_slippage_bps": plan.assumptions.get("roundtrip_slippage_bps"),
                "sensitivity": plan.assumptions.get("cost_sensitivity"),
            }
            forward_config["exit_policy"] = dict(plan.exit_policy)
            forward_config["research_mode"] = plan.research_mode
            forward_config["paper_assumptions"] = {
                "fees": {
                    "model": "proportional",
                    "fee_bps": str(plan.assumptions.get("fee_bps", 10)),
                },
                "slippage": {
                    "model": "proportional",
                    "slippage_bps": str(plan.assumptions.get("slippage_bps", 5)),
                },
            }
            strategy_version_id = "strategy-version-" + _rolling_hash(
                {"strategy_hash": rolling_strategy_hash, "candidate_id": candidate_id}
            ).removeprefix("sha256:")[:40]
            research_trial_id = "research-trial-" + _rolling_hash(
                {
                    "candidate_id": candidate_id,
                    "strategy_version_id": strategy_version_id,
                    "source_config_hash": plan.plan_hash,
                }
            ).removeprefix("sha256:")[:40]
            forward_config["strategy_version_id"] = strategy_version_id
            forward_config["research_trial_id"] = research_trial_id
            forward_config["candidate_id"] = candidate_id
            forward_config["plan_id"] = plan.plan_id
            forward_config["strategy_hash"] = strategy_hash
            forward_config["source_strategy_hash"] = strategy_hash
            forward_config["rolling_strategy_hash"] = rolling_strategy_hash
            if plan.market_type is not MarketType.CRYPTO_SPOT:
                forward_config = _canonical_forward_config(forward_config)
            config_hash = _hash_document({"config": forward_config, "risk_limits": risk_snapshot})
            model_hash = _content_hash(model_document)
            frozen_hash = hashlib.sha256("|".join((strategy_hash, model_hash, config_hash)).encode("utf-8")).hexdigest()
            candidate = self.lifecycle.advance(
                candidate_id,
                CandidateStage.FROZEN,
                {
                    **robust_evidence,
                    **base,
                    "frozen": True,
                    "strategy_hash": strategy_hash,
                    "source_strategy_hash": strategy_hash,
                    "rolling_strategy_hash": rolling_strategy_hash,
                    "strategy_version_id": strategy_version_id,
                    "research_trial_id": research_trial_id,
                    "model_hash": model_hash,
                    "config_hash": config_hash,
                    "frozen_hash": frozen_hash,
                    "risk_snapshot": risk_snapshot,
                    "dataset_provenance": {
                        "dataset_id": plan.dataset_id,
                        "dataset_version": plan.dataset_version,
                        "time_split": plan.methodology.get("time_split"),
                        "universe": dict(plan.universe or {}),
                    },
                    "dataset_attestation": dict(dataset_attestation),
                    "experiment_budget_lineage": {
                        "budget_id": AUTONOMOUS_BUDGET_ID,
                        "family": plan.experiment_family,
                        "variants_tested": variant_count,
                    },
                },
                reason="exact strategy, model, configuration, risk, and provenance frozen",
            )
            if plan.market_type is MarketType.CRYPTO_SPOT:
                return {
                    "candidate_id": candidate_id,
                    "stage": candidate.stage.value,
                    "validation_expectancy": validation_expectancy,
                    "variant_count": variant_count,
                    "forward_test_id": None,
                    "execution_capability": "none",
                    "paper_only": True,
                    "crypto_provenance": dict(crypto_binding or {}),
                }
            required_independent_samples = self.config.promotion_criteria.min_independent_samples
            # A zero explicit threshold means no independent-sample
            # qualification bound; it must not collapse current authority to
            # one market.  Runtime defaults still bind authority to their
            # required sample count, bounded by the global safety cap.
            authority_market_cap = min(
                PAPER_MARKET_AUTHORITY_CAP,
                required_independent_samples or PAPER_MARKET_AUTHORITY_CAP,
            )
            authority = self.store.candidate_forward_requirements(
                candidate_ids=(candidate_id,),
                now=now,
                max_candidates=1,
                max_markets_per_candidate=authority_market_cap,
                max_total_markets=authority_market_cap,
            )
            authority_candidate = (
                authority.get("candidates", [])[0]
                if isinstance(authority.get("candidates"), list) and authority.get("candidates")
                else {}
            )
            allowed_markets = tuple(
                str(item).strip()
                for item in authority_candidate.get("permitted_market_ids", ())
                if str(item).strip()
            )
            if (
                authority_candidate.get("resolution") != "RESOLVED"
                or not allowed_markets
            ):
                return {
                    "candidate_id": candidate_id,
                    "stage": candidate.stage.value,
                    "validation_expectancy": validation_expectancy,
                    "variant_count": variant_count,
                    "forward_test_id": None,
                    "reason_code": authority_candidate.get(
                        "reason_code", "CANDIDATE_FORWARD_MARKET_UNRESOLVED"
                    ),
                    "research_only": True,
                    "paper_only": True,
                }
            registry = ForwardTestRegistry(self.store)
            spec = registry.register_forward_test(
                strategy=strategy.to_dict(),
                model=dict(model_document),
                registration_timestamp=now,
                now=now,
                config=forward_config,
                bankroll=10_000.0,
                allowed_markets=allowed_markets,
                risk_limits=risk_snapshot,
                experiment_id="forward-" + candidate_id,
                strategy_version_id=strategy_version_id,
                research_trial_id=research_trial_id,
            )
            candidate = self.lifecycle.advance(
                candidate_id,
                CandidateStage.PAPER_FORWARD,
                {
                    **base,
                    "paper_forward_started": True,
                    "forward_test_id": spec.experiment_id,
                    # Preserve the registry's real current-time provenance on
                    # the lifecycle record; never reconstruct it from history.
                    "registration_timestamp": spec.registration_timestamp.isoformat(),
                    "forward_evidence": {
                        "evidence_scope": "forward_only",
                        "forward_order_attempts": 0,
                        "forward_successful_order_attempts": 0,
                        "forward_failed_order_attempts": 0,
                        "fills": 0,
                        "partial_fills": 0,
                        "no_fill_orders": 0,
                        "forward_independent_resolved_bets": 0,
                        "forward_expectancy": None,
                        "forward_confidence_lower_bound": None,
                        "forward_stability": None,
                        "forward_calibration": None,
                        "forward_max_drawdown": 0.0,
                        "paper_only": True,
                    },
                    "selection_excluded": True,
                    "allocation_active": False,
                    "canary_armed": False,
                    "execution_scope": "OBSERVATION",
                    "observation_only_lineage": True,
                    "holdout_used": False,
                },
                reason="genuine forward registration created at current time",
            )
        return {
            "candidate_id": candidate_id,
            "stage": candidate.stage.value,
            "validation_expectancy": validation_expectancy,
            "variant_count": variant_count,
            "forward_test_id": candidate.payload.get("forward_test_id"),
        }

    def _generate_mutations(
        self,
        plan: ExperimentPlan,
        prepared: Sequence[Mapping[str, Any]],
        validation_scores: Mapping[str, float],
        now: datetime,
        *,
        lineage: Sequence[str] = (),
    ) -> tuple[str, ...]:
        if not self.config.mutation_enabled or self.config.max_children_per_parent <= 0:
            return ()
        if not prepared:
            return ()
        current = ensure_utc(now)
        daily_limit = self.config.max_experiments_per_day
        daily_since: datetime | None = None
        daily_until: datetime | None = None
        if daily_limit is not None:
            daily_since = datetime(current.year, current.month, current.day, tzinfo=timezone.utc)
            daily_until = daily_since + timedelta(days=1)
        parent = max(prepared, key=lambda item: (validation_scores.get(str(item["candidate_id"]), float("-inf")), str(item["candidate_id"])))
        parent_id = str(parent["candidate_id"])
        lifecycle = self.lifecycle.get(parent_id)
        if lifecycle is None or lifecycle.stage not in {CandidateStage.ROBUSTNESS_CHECKED, CandidateStage.FROZEN, CandidateStage.PAPER_FORWARD, CandidateStage.PAPER_PROMOTABLE}:
            return ()
        generation = int(lifecycle.payload.get("generation", 0))
        if generation >= self.config.max_generation_depth:
            return ()
        existing = self.store.load_candidate_lifecycle(limit=10_000)
        children = 0
        if isinstance(existing, list):
            children = sum(
                1
                for record in existing
                if isinstance(record, Mapping)
                and isinstance(record.get("payload"), Mapping)
                and str(record["payload"].get("parent_id", "")) == parent_id
            )
        remaining = max(0, self.config.max_children_per_parent - children)
        if daily_limit is not None:
            assert daily_since is not None and daily_until is not None
            daily_count = self.store.count_experiment_budget_reservations(
                AUTONOMOUS_BUDGET_ID,
                since=daily_since,
                until=daily_until,
            )
            remaining = min(remaining, max(0, daily_limit - daily_count))
        if remaining <= 0:
            return ()
        strategy = parent["strategy"]
        # Experiment plans are untrusted input.  The node owns the shared
        # autonomous budget namespace; never let plan-declared limits poison
        # its persisted immutable limits.
        budget = ExperimentBudget(
            budget_id=AUTONOMOUS_BUDGET_ID,
            total_limit=self.config.total_limit,
            per_family_limit=self.config.family_limit,
        )
        engine = DeterministicMutationEngine(store=self.store, lifecycle=self.lifecycle, budget=budget, seed=0)
        try:
            generated = engine.mutate(
                strategy,
                parent_id=parent_id,
                generation=generation + 1,
                max_variants=remaining,
                provenance={
                    "plan_id": plan.plan_id,
                    "hypothesis_id": plan.hypothesis_id,
                    "validation_only": True,
                    "market_scope_hash": plan.market_scope_hash,
                    "market_scope": plan.market_scope.as_dict(),
                    "market_scope_version": plan.market_scope_version,
                    "dataset_selector": dict(plan.as_dict()["dataset_selector"]),
                    "locked_partition_used": False,
                    "crypto_provenance": dict(self._crypto_binding(plan) or {}),
                },
                lineage=lineage,
                timestamp=now,
                daily_limit=daily_limit,
                daily_since=daily_since,
                daily_until=daily_until,
            )
        except (RuntimeError, ValueError):
            return ()
        child_ids: list[str] = []
        attestation_hash: str | None = None
        if plan.market_type is MarketType.PREDICTION:
            attestation_loader = getattr(self.store, "load_dataset_integrity_attestation", None)
            if callable(attestation_loader) and plan.dataset_id and plan.dataset_version:
                try:
                    attestation = attestation_loader(plan.dataset_id, plan.dataset_version)
                except Exception:
                    attestation = None
                if isinstance(attestation, Mapping):
                    attestation_hash = str(attestation.get("attestation_hash", "")).strip() or None
        for child in generated:
            child_document = child.strategy.to_dict()
            child_document["strategy_id"] = child.candidate_id
            child_strategy = load_strategy(child_document)
            child_payload = {
                "candidate_id": child.candidate_id,
                "hypothesis_id": plan.hypothesis_id,
                "plan_id": plan.plan_id,
                "plan_hash": plan.plan_hash,
                **_scope_binding(plan),
                "experiment_plan": plan.as_dict(),
                "strategy": child_strategy.to_dict(),
                "parameters": dict(child_strategy.parameters),
                "variant_id": "mutation-" + child.candidate_id,
                "generation": child.generation,
                "parent_id": child.parent_id,
                "lineage": list(child.lineage),
                "dataset_version": plan.dataset_version,
                "dataset_id": plan.dataset_id,
                "paper_only": True,
                "holdout_used": False,
                "crypto_provenance": dict(self._crypto_binding(plan) or {}),
            }
            child_payload = _mark_generated_queue_payload(
                child_payload,
                kind="mutation_child",
                dataset_id=plan.dataset_id,
                dataset_version=plan.dataset_version,
                attestation_hash=attestation_hash,
            )
            self.store.save_strategy_if_absent(child_strategy.id, child_strategy.to_dict())
            self.store.save_experiment_if_absent(
                child.candidate_id,
                {
                    "run_id": child.candidate_id,
                    "status": "IDEA",
                    "strategy_id": child_strategy.id,
                    "strategy": child_strategy.to_dict(),
                    "variant": dict(child_strategy.parameters),
                    "candidate_id": child.candidate_id,
                    "hypothesis_id": plan.hypothesis_id,
                    "plan_id": plan.plan_id,
                    "plan_hash": plan.plan_hash,
                    **_scope_binding(plan),
                    "dataset_id": plan.dataset_id,
                    "dataset_version": plan.dataset_version,
                    "generation": child.generation,
                    "parent_id": child.parent_id,
                    "lineage": list(child.lineage),
                    "paper_only": True,
                    "holdout_used": False,
                },
                strategy_id=child_strategy.id,
            )
            self.bus.submit_candidate(
                child_payload,
                dedupe_key="candidate:" + child.candidate_id,
                lineage=child.lineage,
                available_at=now,
            )
            child_ids.append(child.candidate_id)
        return tuple(child_ids)

    def _reserve_candidate(self, plan: ExperimentPlan, candidate_id: str, now: datetime) -> None:
        current = ensure_utc(now)
        daily_since: datetime | None = None
        daily_until: datetime | None = None
        if self.config.max_experiments_per_day is not None:
            daily_since = datetime(current.year, current.month, current.day, tzinfo=timezone.utc)
            daily_until = daily_since + timedelta(days=1)
        try:
            self.store.reserve_experiment_budget(
                AUTONOMOUS_BUDGET_ID,
                total_limit=self.config.total_limit,
                per_family_limit=self.config.family_limit,
                family=plan.experiment_family,
                reservation_key=candidate_id,
                timestamp=current,
                daily_limit=self.config.max_experiments_per_day,
                daily_since=daily_since,
                daily_until=daily_until,
            )
        except RuntimeError as exc:
            reason = (
                "EXPERIMENT_DAILY_LIMIT_EXCEEDED"
                if str(exc) == "experiment daily budget exhausted"
                else "EXPERIMENT_BUDGET_EXCEEDED"
            )
            raise AutonomousResearchError(reason, str(exc)) from exc
    def _candidate_payload(
        self,
        plan: ExperimentPlan,
        candidate_id: str,
        strategy: StrategyDefinition,
        parameters: Mapping[str, Any],
        *,
        variant_id: str,
        generation: int,
        lineage: Sequence[str],
        dataset_attestation: Mapping[str, Any] | None = None,
        include_live_extensions: bool = True,
    ) -> dict[str, Any]:
        return {
            "candidate_id": candidate_id,
            "hypothesis_id": plan.hypothesis_id,
            "plan_id": plan.plan_id,
            "plan_hash": plan.plan_hash,
            **_scope_binding(plan),
            "experiment_plan": plan.as_dict(),
            "strategy": strategy.to_dict(),
            **_operational_setup_fields(
                strategy.to_dict(),
                plan,
                dataset_attestation=dataset_attestation,
                dataset_boundary=plan.dataset_boundary,
                include_live_extensions=include_live_extensions,
            ),
            "parameters": dict(parameters),
            "variant_id": variant_id,
            "generation": generation,
            "lineage": list(lineage),
            "dataset_id": plan.dataset_id,
            "dataset_version": plan.dataset_version,
            "experiment_family": plan.experiment_family,
            "paper_only": True,
            **({"legacy_predeclared": True} if not include_live_extensions else {}),
            "holdout_used": False,
        }

    def _hypothesis_result(
        self,
        plan: ExperimentPlan,
        results: Sequence[Mapping[str, Any]],
        mutations: Sequence[str],
        *,
        split_counts: Mapping[str, int] | None = None,
    ) -> dict[str, Any]:
        rejected = [item for item in results if item.get("stage") == CandidateStage.REJECTED.value]
        selected_stages = (
            {CandidateStage.FROZEN.value}
            if plan.market_type is MarketType.CRYPTO_SPOT
            else {CandidateStage.PAPER_FORWARD.value, CandidateStage.PAPER_PROMOTABLE.value}
        )
        selected = [
            item
            for item in results
            if item.get("stage") in selected_stages
            and not bool(item.get("selection_excluded"))
            and str(item.get("research_role", "")).strip().upper() != "ZERO_EDGE_CONTROL"
        ]
        reason_codes = [
            str(value).strip()
            for item in results
            for value in (item.get("reason_code"),)
            if value is not None and str(value).strip()
        ]
        if not reason_codes:
            reason_codes = [
                str(item.get("reason")).strip()
                for item in results
                if re.fullmatch(r"[A-Z][A-Z0-9_]{2,63}", str(item.get("reason", "")).strip())
            ]
        reason_code = next(iter(dict.fromkeys(reason_codes)), None)
        summary_reason = next(
            (
                str(item.get("reason")).strip()
                for item in results
                if item.get("reason") is not None and str(item.get("reason")).strip()
            ),
            None,
        )
        supported_edge = bool(selected)
        insufficient_data = not supported_edge and any(
            str(item.get("reason_code", "")).strip().upper() == "INSUFFICIENT_DATA"
            for item in results
        )
        if supported_edge:
            summary_reason = None
        reasons: dict[str, int] = {}
        for item in rejected:
            reason = str(item.get("reason", "rejected"))
            reasons[reason] = reasons.get(reason, 0) + 1
        trial_manifest = [
            {
                "trial_index": index,
                "candidate_id": item.get("candidate_id"),
                "stage": item.get("stage"),
                "dataset_row_count": item.get("dataset_row_count"),
                "train_sample_count": item.get("train_sample_count"),
                "validation_sample_count": item.get("validation_sample_count"),
                "holdout_sample_count": item.get("holdout_sample_count"),
                "validation_expectancy": item.get("validation_expectancy"),
                "validation_filled_trades": item.get("validation_filled_trades"),
                "required_validation_samples": item.get("required_validation_samples"),
                "required_validation_trades": item.get("required_validation_trades"),
                "minimum_sample_check": item.get("minimum_sample_check"),
                "research_role": item.get("research_role"),
                "selection_excluded": bool(item.get("selection_excluded")),
                "proven_zero_edge": bool(item.get("proven_zero_edge")),
                "holdout_evaluated": bool(item.get("holdout_evaluated")),
                "holdout_used_for_selection": bool(item.get("holdout_used_for_selection")),
            }
            for index, item in enumerate(results)
        ]
        split = {
            str(name): int(value)
            for name, value in dict(split_counts or {}).items()
            if not isinstance(value, bool)
        }
        split.setdefault("dataset_row_count", 0)
        split.setdefault("train_sample_count", 0)
        split.setdefault("validation_sample_count", 0)
        split.setdefault("holdout_sample_count", 0)
        return {
            "accepted": supported_edge,
            "reason_code": None if supported_edge else reason_code,
            "reason": summary_reason,
            "kind": "hypothesis",
            "hypothesis_id": plan.hypothesis_id,
            "plan_id": plan.plan_id,
            "plan_hash": plan.plan_hash,
            **_scope_binding(plan),
            "status": (
                "accepted_research_only"
                if plan.market_type is MarketType.CRYPTO_SPOT and selected
                else "accepted" if selected
                else "insufficient_data" if insufficient_data
                else "unsupported_by_validation"
            ),
            "dataset_row_count": split["dataset_row_count"],
            "train_sample_count": split["train_sample_count"],
            "validation_sample_count": split["validation_sample_count"],
            "holdout_sample_count": split["holdout_sample_count"],
            "split": {
                "train": split["train_sample_count"],
                "validation": split["validation_sample_count"],
                "holdout": split["holdout_sample_count"],
            },
            "supported_edge": supported_edge,
            "blocker": None if supported_edge else "INSUFFICIENT_DATA" if insufficient_data else "NO_SUPPORTED_EDGE",
            "next_action": "AWAIT_PAPER_EVIDENCE" if supported_edge else "CONTINUE_RESEARCH_AND_PAPER",
            "variants_tested": len(results),
            "selected_from_variants": len(selected),
            "selected_candidate_ids": [
                str(item.get("candidate_id"))
                for item in selected
                if str(item.get("candidate_id", "")).strip()
            ],
            "trial_manifest": trial_manifest,
            "candidate_results": [
                {
                    "candidate_id": item.get("candidate_id"),
                    "stage": item.get("stage"),
                    "reason": item.get("reason"),
                    "reason_code": item.get("reason_code"),
                    "forward_test_id": item.get("forward_test_id"),
                    "dataset_row_count": item.get("dataset_row_count"),
                    "train_sample_count": item.get("train_sample_count"),
                    "validation_sample_count": item.get("validation_sample_count"),
                    "holdout_sample_count": item.get("holdout_sample_count"),
                    "validation_filled_trades": item.get("validation_filled_trades"),
                    "required_validation_samples": item.get("required_validation_samples"),
                    "required_validation_trades": item.get("required_validation_trades"),
                    "minimum_sample_check": item.get("minimum_sample_check"),
                    "validation": item.get("validation"),
                    "research_role": item.get("research_role"),
                    "selection_excluded": bool(item.get("selection_excluded")),
                    "proven_zero_edge": bool(item.get("proven_zero_edge")),
                    "holdout_evaluated": bool(item.get("holdout_evaluated")),
                    "holdout_used_for_selection": bool(item.get("holdout_used_for_selection")),
                    "holdout": item.get("holdout"),
                }
                for item in results
            ],
            "rejected_reasons": dict(sorted(reasons.items())),
            "mutation_candidates": list(mutations[:_MAX_QUEUE_RESULT_ITEMS]),
            "experiment_family": plan.experiment_family,
            "dataset_version": plan.dataset_version,
            "data_quality": "PRICE_PROXY_RESEARCH" if plan.market_type is MarketType.PREDICTION else "OHLCV_SIMULATED",
            "paper_only": True,
            "research_only": plan.market_type is MarketType.CRYPTO_SPOT,
            "holdout_used": False,
            "holdout_evaluated": any(
                bool(item.get("holdout_evaluated")) for item in results
            ),
            "holdout_locked": not any(
                bool(item.get("holdout_evaluated")) for item in results
            ),
            "holdout_selection_fence": "validation_only",
        }

    @staticmethod
    def _forward_evidence_identity(
        spec: Any,
        observations: Sequence[Mapping[str, Any]],
        execution_events: Sequence[Mapping[str, Any]],
        ledgers: Sequence[Mapping[str, Any]],
        fills: Sequence[Any] = (),
        operational_identity: Mapping[str, Any] | None = None,
    ) -> str:
        """Hash immutable paper records so unchanged evidence is idempotent."""
        def rows(items: Sequence[Mapping[str, Any]], identifier: str) -> list[dict[str, Any]]:
            result: list[dict[str, Any]] = []
            for item in items:
                value = item if isinstance(item, Mapping) else {}
                record_id = str(value.get(identifier, "")).strip()
                if not record_id:
                    record_id = _hash_document(value)
                result.append(
                    {
                        "id": record_id,
                        "market_id": str(value.get("market_id", "")).strip(),
                        "timestamp": str(value.get("timestamp", value.get("resolved_at", ""))),
                        "payload_hash": _hash_document(value.get("payload", value)),
                        "status": str(value.get("status", "")).strip().upper(),
                    }
                )
            return sorted(result, key=lambda row: (row["id"], row["market_id"], row["timestamp"], row["payload_hash"]))

        expected_experiment_id = str(getattr(spec, "experiment_id", "")).strip()
        expected_strategy_hash = str(getattr(spec, "strategy_hash", "")).strip()
        fill_identity_fields = (
            "order_id",
            "market_id",
            "symbol",
            "timestamp",
            "side",
            "quantity",
            "price",
            "fees",
            "slippage",
            "strategy_id",
            "expected_probability",
            "executable_probability",
            "paper_experiment_id",
            "execution_status",
            "requested_quantity",
            "partial",
            "outcome",
        )

        def fill_rows(items: Sequence[Any]) -> list[dict[str, Any]]:
            result: list[dict[str, Any]] = []
            for index, item in enumerate(items):
                if index >= _MAX_FORWARD_ROWS:
                    break
                if isinstance(item, Fill):
                    metadata = item.metadata if isinstance(item.metadata, Mapping) else {}
                    paper_experiment_id = str(metadata.get("paper_experiment_id", "")).strip()
                    strategy_id = str(item.strategy_id).strip()
                    if paper_experiment_id != expected_experiment_id or strategy_id != expected_strategy_hash:
                        continue
                    canonical = {
                        "order_id": str(item.order_id).strip(),
                        "market_id": str(item.market_id or item.symbol).strip(),
                        "symbol": str(item.symbol).strip(),
                        "timestamp": ensure_utc(item.timestamp).isoformat(),
                        "side": getattr(item.side, "value", item.side),
                        "quantity": item.quantity,
                        "price": item.price,
                        "fees": item.fees,
                        "slippage": item.slippage,
                        "strategy_id": strategy_id,
                        "expected_probability": item.expected_probability,
                        "executable_probability": item.executable_probability,
                        "paper_experiment_id": paper_experiment_id,
                        "execution_status": metadata.get("execution_status"),
                        "requested_quantity": metadata.get("requested_quantity"),
                        "partial": metadata.get("partial"),
                        "outcome": metadata.get("outcome"),
                    }
                elif isinstance(item, Mapping):
                    metadata = item.get("metadata")
                    metadata = metadata if isinstance(metadata, Mapping) else {}
                    paper_experiment_id = str(
                        item.get("paper_experiment_id", metadata.get("paper_experiment_id", ""))
                    ).strip()
                    strategy_id = str(item.get("strategy_id", "")).strip()
                    if paper_experiment_id != expected_experiment_id or strategy_id != expected_strategy_hash:
                        continue
                    canonical = {
                        key: item.get(key, metadata.get(key))
                        for key in fill_identity_fields
                    }
                    canonical["order_id"] = str(canonical.get("order_id") or "").strip()
                    canonical["market_id"] = str(
                        canonical.get("market_id") or canonical.get("symbol") or ""
                    ).strip()
                    canonical["symbol"] = str(canonical.get("symbol") or "").strip()
                    canonical["timestamp"] = str(canonical.get("timestamp") or "")
                    canonical["side"] = getattr(canonical.get("side"), "value", canonical.get("side"))
                    canonical["strategy_id"] = strategy_id
                    canonical["paper_experiment_id"] = paper_experiment_id
                else:
                    continue
                result.append(
                    {
                        "id": canonical["order_id"] or _hash_document(canonical),
                        **canonical,
                    }
                )
            return sorted(
                result,
                key=lambda row: (
                    row["id"],
                    row["market_id"],
                    row["timestamp"],
                    _canonical_binding(row),
                ),
            )

        config = spec.config if isinstance(getattr(spec, "config", None), Mapping) else {}
        scope = {
            name: config.get(name)
            for name in (
                "plan_id",
                "plan_hash",
                "market_scope_hash",
                "market_scope_version",
                "dataset_selector",
                "dataset_id",
                "dataset_version",
                "dataset_attestation",
                "dataset_boundary",
            )
        }
        return _hash_document(
            {
                "forward_test_id": str(getattr(spec, "experiment_id", "")),
                "strategy_hash": str(getattr(spec, "strategy_hash", "")),
                "model_hash": str(getattr(spec, "model_hash", "")),
                "allowed_markets": list(getattr(spec, "allowed_markets", ()) or ()),
                "scope": scope,
                "observations": rows(observations, "observation_id"),
                "execution_events": rows(execution_events, "event_id"),
                "ledgers": rows(ledgers, "bet_id"),
                "fills": fill_rows(fills),
                "operational_identity": dict(
                    operational_identity
                    if isinstance(operational_identity, Mapping)
                    else _operational_identity_projection(scope, config)
                ),
            }
        )

    def _forward_evidence(self, record: Mapping[str, Any], now: datetime) -> dict[str, Any]:
        payload = record.get("payload", {})
        payload = dict(payload) if isinstance(payload, Mapping) else {}
        forward_id = str(payload.get("forward_test_id", "")).strip()
        if not forward_id:
            raise ValueError("candidate has no forward test")
        spec = ForwardTestRegistry(self.store).get(forward_id)
        if spec is None:
            raise ValueError(f"missing forward test {forward_id}")
        spec_config = spec.config if isinstance(spec.config, Mapping) else {}
        try:
            paper_lineage = _rolling_source_binding(
                {"payload": spec_config, "strategy_hash": spec.strategy_hash}
            )
        except (TypeError, ValueError):
            paper_lineage = {}
        observations = self.store.list_paper_observations(forward_id, limit=_MAX_FORWARD_ROWS)
        fills: list[Fill] = []
        try:
            stored_fills = self.store.load_fills(strategy_id=spec.strategy_hash)
        except Exception:
            stored_fills = ()
        for fill in stored_fills:
            if str(fill.metadata.get("paper_experiment_id", "")) != forward_id:
                continue
            fills.append(fill)
            if len(fills) >= _MAX_FORWARD_ROWS:
                break
        event_records = self.store.list_paper_execution_events(forward_id, limit=_MAX_FORWARD_ROWS)
        ledger_records = self.store.list_paper_bet_ledger(forward_id, limit=_MAX_FORWARD_ROWS)
        terminal_by_market: dict[str, str] = {}
        observed_markets: set[str] = set()
        for row in observations:
            item = row.get("payload", {}) if isinstance(row, Mapping) else {}
            item = item if isinstance(item, Mapping) else {}
            market_id = str(row.get("market_id", item.get("market_id", ""))).strip()
            if market_id:
                observed_markets.add(market_id)
            settlement = _settlement_name(item.get("settlement"))
            if settlement in {"resolved_yes", "resolved_no", "void"} and market_id:
                terminal_by_market[market_id] = settlement

        fills_by_market: dict[str, list[Fill]] = {}
        for fill in fills:
            fills_by_market.setdefault(str(fill.market_id or fill.symbol), []).append(fill)
        observation_open_by_market: dict[str, datetime] = {}
        for observation in observations:
            if not isinstance(observation, Mapping):
                continue
            observation_payload = observation.get("payload")
            observation_payload = (
                observation_payload
                if isinstance(observation_payload, Mapping)
                else {}
            )
            observation_market = str(
                observation.get(
                    "market_id",
                    observation_payload.get("market_id", ""),
                )
            ).strip()
            observation_time = _rolling_timestamp(
                observation.get("timestamp")
                or observation_payload.get("timestamp")
                or observation.get("observed_at")
                or observation_payload.get("observed_at")
            )
            if observation_market and observation_time is not None:
                previous = observation_open_by_market.get(observation_market)
                if previous is None or observation_time < previous:
                    observation_open_by_market[observation_market] = observation_time

        def complete_resolved_ledger(
            source_ledger: Mapping[str, Any],
            market: str,
        ) -> dict[str, Any]:
            ledger = dict(source_ledger)
            rolling_hash = _binding_value(paper_lineage.get("rolling_strategy_hash"))
            source_hash = _binding_value(
                paper_lineage.get("source_strategy_hash")
            ) or _binding_value(spec.strategy_hash)
            if rolling_hash is not None:
                ledger["strategy_hash"] = rolling_hash
                ledger["rolling_strategy_hash"] = rolling_hash
            elif source_hash is not None:
                ledger["strategy_hash"] = source_hash
            if source_hash is not None:
                ledger["source_strategy_hash"] = source_hash
            for field in (
                "strategy_version_id",
                "research_trial_id",
                "candidate_id",
                "plan_id",
            ):
                value = paper_lineage.get(field)
                if value is not None:
                    ledger[field] = value
            shortages: list[str] = []
            for field in ("net_pnl", "fees", "slippage", "capital_at_risk"):
                value = ledger.get(field)
                if value is None or not _is_finite_number(value):
                    shortages.append(field)
            resolved_time = _rolling_timestamp(ledger.get("resolved_at"))
            if resolved_time is None:
                shortages.append("resolved_at")
            source_open_time = next(
                (
                    stamp
                    for name in (
                        "observation_open_timestamp",
                        "observation_opened_at",
                        "open_timestamp",
                        "opened_at",
                        "observation_timestamp",
                        "observation_at",
                        "available_from",
                        "coverage_from",
                        "window_start",
                    )
                    if (stamp := _rolling_timestamp(ledger.get(name))) is not None
                ),
                None,
            )
            if (
                source_open_time is not None
                and resolved_time is not None
                and source_open_time > resolved_time
            ):
                shortages.append("observation_open_timestamp_after_resolved_at")
            open_time = observation_open_by_market.get(market) or source_open_time
            if open_time is None:
                market_fills = fills_by_market.get(market, ())
                if market_fills:
                    open_time = min(ensure_utc(fill.timestamp) for fill in market_fills)
            if open_time is None:
                shortages.append("observation_open_timestamp")
            elif resolved_time is not None and open_time > resolved_time:
                shortages.append("observation_open_timestamp_after_resolved_at")
            if shortages:
                ledger["accounting_shortage"] = {
                    "code": "PAPER_RESOLVED_BET_ACCOUNTING_INCOMPLETE",
                    "fields": sorted(set(shortages)),
                }
                return ledger
            capital = Decimal(str(ledger["capital_at_risk"]))
            net_pnl = Decimal(str(ledger["net_pnl"]))
            if not capital.is_finite() or capital <= Decimal("0"):
                ledger["accounting_shortage"] = {
                    "code": "PAPER_RESOLVED_BET_ACCOUNTING_INCOMPLETE",
                    "fields": ["capital_at_risk_nonpositive"],
                }
                return ledger
            drawdown = min(Decimal("1"), max(Decimal("0"), -net_pnl / capital))
            ledger.pop("accounting_shortage", None)
            ledger.update(
                {
                    "allocated_capital": ledger["capital_at_risk"],
                    "allocated_capital_net_return": ledger["net_pnl"],
                    "realized_pnl": ledger["net_pnl"],
                    "unrealized_pnl": 0.0,
                    "costs": ledger["slippage"],
                    "completed_outcomes": 1,
                    # Reliability means the settlement/accounting contract
                    # completed, never that this bet was profitable.
                    "reliability": 1.0,
                    "drawdown": float(drawdown),
                    "observation_open_timestamp": open_time.isoformat(),
                    "available_from": open_time.isoformat(),
                    "coverage_from": open_time.isoformat(),
                    "available_through": resolved_time.isoformat(),
                    "coverage_through": resolved_time.isoformat(),
                }
            )
            return ledger
        ledger_by_market: dict[str, Mapping[str, Any]] = {}
        for row in ledger_records:
            if not isinstance(row, Mapping):
                continue
            market_id = str(row.get("market_id", "")).strip()
            source_ledger = row.get("payload")
            if not market_id or not isinstance(source_ledger, Mapping):
                continue
            ledger = dict(source_ledger)
            for field in ("bet_id", "outcome", "resolution", "resolved_at"):
                if field not in ledger and row.get(field) is not None:
                    value = row.get(field)
                    ledger[field] = value.isoformat() if isinstance(value, datetime) else value
            ledger = complete_resolved_ledger(ledger, market_id)
            ledger_by_market[market_id] = ledger
            resolved_time = _rolling_timestamp(ledger.get("resolved_at"))
            if (
                ledger.get("bet_id")
                and ledger.get("outcome")
                and ledger.get("resolution")
                and resolved_time is not None
            ):
                self.store.save_paper_bet_ledger(
                    str(ledger["bet_id"]),
                    forward_id,
                    market_id,
                    spec.strategy_hash,
                    str(ledger["outcome"]),
                    str(ledger["resolution"]),
                    resolved_time,
                    ledger,
                )
        for market_id, resolution in terminal_by_market.items():
            if market_id in ledger_by_market:
                continue
            resolved_at = next(
                (
                    stamp
                    for row in observations
                    if isinstance(row, Mapping)
                    and isinstance(row.get("payload"), Mapping)
                    and str(
                        row.get("market_id", row["payload"].get("market_id", ""))
                    ).strip()
                    == market_id
                    and _settlement_name(row["payload"].get("settlement")) == resolution
                    if (stamp := _rolling_timestamp(
                        row.get("timestamp")
                        or row["payload"].get("timestamp")
                        or row.get("observed_at")
                        or row["payload"].get("observed_at")
                    )) is not None
                ),
                None,
            )
            if resolved_at is None:
                continue
            ledger = build_resolved_bet(
                experiment_id=forward_id,
                market_id=market_id,
                strategy_id=spec.strategy_hash,
                settlement=resolution,
                resolved_at=resolved_at,
                fills=fills_by_market.get(market_id, ()),
            )
            if ledger is not None:
                ledger = complete_resolved_ledger(ledger, market_id)
                self.store.save_paper_bet_ledger(
                    ledger["bet_id"],
                    forward_id,
                    market_id,
                    spec.strategy_hash,
                    ledger["outcome"],
                    ledger["resolution"],
                    parse_timestamp(ledger["resolved_at"]) or now,
                    ledger,
                )
                ledger_by_market[market_id] = ledger
        ledgers = list(ledger_by_market.values())

        if not event_records:
            event_records = [
                {
                    "market_id": str(fill.market_id or fill.symbol),
                    "status": str(fill.metadata.get("execution_status", "FULL_FILL")).upper(),
                    "payload": {
                        "market_id": str(fill.market_id or fill.symbol),
                        "status": str(fill.metadata.get("execution_status", "FULL_FILL")).upper(),
                        "outcomes": ["SIGNAL", "ORDER_ATTEMPT", str(fill.metadata.get("execution_status", "FULL_FILL")).upper()],
                        "order_attempted": True,
                        "requested_quantity": _finite(fill.metadata.get("requested_quantity"), fill.quantity),
                        "filled_quantity": fill.quantity,
                        "liquidity": fill.metadata.get("liquidity"),
                        "spread_paid": fill.metadata.get("spread_paid", 0.0),
                        "depth_consumed": fill.metadata.get("depth_consumed", 0.0),
                    },
                }
                for fill in fills
            ]
        event_payloads = [
            row.get("payload", {})
            for row in event_records
            if isinstance(row, Mapping) and isinstance(row.get("payload"), Mapping)
        ]
        attempt_events = [
            event
            for event in event_payloads
            if bool(event.get("order_attempted"))
            or "ORDER_ATTEMPT" in tuple(event.get("outcomes", ()))
        ]
        successful_events = [
            event
            for event in attempt_events
            if str(event.get("status", "")).upper() in {"FULL_FILL", "PARTIAL_FILL"}
            and _finite(event.get("filled_quantity"), 0.0) > 0
        ]
        no_fill_events = [event for event in attempt_events if str(event.get("status", "")).upper() == "NO_FILL"]
        risk_rejected_events = [
            event for event in attempt_events if str(event.get("status", "")).upper() == "RISK_REJECTED"
        ]
        requested_quantity = sum(max(0.0, _finite(event.get("requested_quantity"), 0.0)) for event in attempt_events)
        filled_quantity = sum(max(0.0, _finite(event.get("filled_quantity"), 0.0)) for event in attempt_events)
        partial_fills = sum(
            1
            for fill in fills
            if bool(fill.metadata.get("partial"))
            or str(fill.metadata.get("execution_status", "")).upper() == "PARTIAL_FILL"
        )
        liquidity_rejections = sum(
            1
            for event in no_fill_events
            if bool(event.get("liquidity_rejected"))
            or str(event.get("reason", "")).lower() in {"insufficient_liquidity", "invalid_order_book"}
        )
        order_attempts = len(attempt_events)
        successful_order_attempts = len(successful_events)
        failed_order_attempts = sum(
            1
            for event in attempt_events
            if str(event.get("status", "")).upper() in {"NO_FILL", "RISK_REJECTED"}
        )
        markets_signaled = {
            str(event.get("market_id", "")).strip()
            for event in event_payloads
            if str(event.get("market_id", "")).strip()
            and "SIGNAL" in tuple(event.get("outcomes", ()))
            and str(event.get("status", "")).upper() != "NO_SIGNAL"
        }
        markets_traded = {str(fill.market_id or fill.symbol).strip() for fill in fills}
        markets_resolved = set(terminal_by_market)
        resolved_positions = sum(int(_finite(ledger.get("positions"), 0.0)) for ledger in ledgers)
        resolved_pnls = [_finite(ledger.get("net_pnl"), math.nan) for ledger in ledgers]
        resolved_pnls = [value for value in resolved_pnls if math.isfinite(value)]
        resolved_rois = [_finite(ledger.get("roi"), math.nan) for ledger in ledgers]
        resolved_rois = [value for value in resolved_rois if math.isfinite(value)]
        forward_expectancy = mean(resolved_pnls) if resolved_pnls else None
        forward_roi = mean(resolved_rois) if resolved_rois else None
        confidence_interval = (
            bootstrap_confidence_interval(
                resolved_pnls,
                resamples=min(256, max(32, len(resolved_pnls) * 8)),
                seed=0,
            )
            if resolved_pnls
            else None
        )
        raw_confidence_lower_bound = (
            _finite(confidence_interval.get("lower"), math.nan)
            if isinstance(confidence_interval, Mapping)
            else math.nan
        )
        forward_confidence_lower_bound = (
            raw_confidence_lower_bound
            if math.isfinite(raw_confidence_lower_bound)
            else None
        )
        forward_stability = (
            sum(1 for value in resolved_rois if value >= 0.0) / len(resolved_rois)
            if len(resolved_rois) >= 2
            else None
        )
        calibration_rows: list[dict[str, float]] = []
        for ledger in ledgers:
            probability = _finite(ledger.get("expected_probability_at_entry"), math.nan)
            resolution = _settlement_name(ledger.get("resolution"))
            if math.isfinite(probability) and 0.0 <= probability <= 1.0 and resolution in {"resolved_yes", "resolved_no"}:
                calibration_rows.append(
                    {
                        "probability": probability,
                        "outcome": 1.0 if resolution == "resolved_yes" else 0.0,
                    }
                )
        forward_calibration = (
            max(0.0, min(1.0, 1.0 - expected_calibration_error(calibration_rows)))
            if calibration_rows
            else None
        )
        state_record = self.store.load_paper_state(forward_id) or {}
        state = state_record.get("state", {}) if isinstance(state_record, Mapping) else {}
        portfolio = state.get("portfolio", {}) if isinstance(state, Mapping) else {}
        risk_state = state.get("risk", {}) if isinstance(state, Mapping) else {}
        duration = max(0.0, (ensure_utc(now) - spec.registration_timestamp).total_seconds())
        risk_equity = _finite(risk_state.get("equity"), spec.bankroll)
        equity = _finite(portfolio.get("equity"), risk_equity)
        prior_peak = max(
            _finite(payload.get("forward_peak_equity"), spec.bankroll),
            _finite(state.get("forward_peak_equity"), spec.bankroll),
        )
        peak = max(prior_peak, equity)
        calculated_drawdown = max(0.0, 1.0 - equity / peak) if peak > 0 else 0.0
        drawdown = max(
            calculated_drawdown,
            _finite(state.get("forward_max_drawdown"), 0.0),
            _finite(risk_state.get("drawdown"), 0.0),
        )
        event_liquidity = [
            _finite(event.get("liquidity"), math.nan)
            for event in attempt_events
            if math.isfinite(_finite(event.get("liquidity"), math.nan))
        ]
        regime_values: set[str] = set()
        for event in attempt_events:
            regime = event.get("regime", event.get("regime_state"))
            if regime is not None and str(regime).strip():
                regime_values.add(str(regime).strip())
        average_slippage = (
            sum(float(fill.slippage) * float(fill.quantity) for fill in fills) / filled_quantity
            if filled_quantity > 0
            else None
        )
        spread_paid = (
            sum(
                max(0.0, _finite(event.get("spread_paid"), 0.0))
                * max(0.0, _finite(event.get("filled_quantity"), 0.0))
                for event in attempt_events
            )
            / filled_quantity
            if filled_quantity > 0
            else None
        )
        risk_reasons = risk_state.get("reasons", ()) if isinstance(risk_state, Mapping) else ()
        risk_reasons = tuple(str(reason) for reason in risk_reasons) if isinstance(risk_reasons, (list, tuple, set)) else ()
        hard_risk_reasons = {
            "max_loss",
            "max_drawdown",
            "max_daily_loss",
            "max_cvar",
            "emergency_kill_switch",
        }
        execution_impossible = (
            order_attempts > 0
            and order_attempts >= self.config.promotion_criteria.min_order_attempts_for_execution_rejection
            and successful_order_attempts == 0
        )
        forward_liquidity = mean(event_liquidity) if event_liquidity else None
        independent_resolved_bets = len(ledgers)
        unresolved_markets = markets_traded - markets_resolved
        total_gross = sum(_finite(ledger.get("gross_pnl"), 0.0) for ledger in ledgers)
        total_fees = sum(_finite(ledger.get("fees"), 0.0) for ledger in ledgers)
        total_slippage = sum(_finite(ledger.get("slippage"), 0.0) for ledger in ledgers)
        total_net = sum(_finite(ledger.get("net_pnl"), 0.0) for ledger in ledgers)
        operational_identity = _operational_identity_projection(
            spec_config,
            *event_payloads,
            *ledgers,
        )
        if (
            (
                operational_identity.get("operational_setup") is not None
                or operational_identity.get("operational_setup_hash") not in (None, "")
            )
            and operational_identity.get("settings_config_id") in (None, "")
        ):
            active_loader = getattr(self.store, "load_canary_setting_config", None)
            active_settings = None
            if callable(active_loader):
                try:
                    active_settings = active_loader(status="ACTIVE")
                except (TypeError, ValueError, RuntimeError):
                    active_settings = None
            if isinstance(active_settings, Mapping):
                values = active_settings.get("values", active_settings.get("settings"))
                if isinstance(values, Mapping):
                    operational_identity["active_settings"] = dict(values)
                operational_identity["settings_config_id"] = active_settings.get("config_id")
                operational_identity["settings_generation"] = active_settings.get("generation")
                operational_identity["settings_config_hash"] = active_settings.get(
                    "config_hash"
                )
                operational_identity["operational_settings_available"] = True
            else:
                operational_identity["operational_settings_available"] = False
                operational_identity["operational_settings_blocker"] = (
                    "ACTIVE_SETTINGS_UNAVAILABLE"
                )
        operational_evidence = _operational_stage_projection(
            rows=observations,
            events=event_records,
            fills=fills,
            ledgers=ledgers,
            remaining_positions=unresolved_markets,
            valid_observations=len(observations),
        )
        evidence = {
            "forward_test_id": forward_id,
            "evidence_scope": "forward_only",
            "forward_duration_seconds": duration,
            "markets_observed": len(observed_markets),
            "markets_signaled": len(markets_signaled),
            "markets_traded": len(markets_traded),
            "markets_resolved": len(markets_resolved),
            "forward_trades": successful_order_attempts,
            "trades": successful_order_attempts,
            "forward_order_attempts": order_attempts,
            "order_attempts": order_attempts,
            "forward_successful_order_attempts": successful_order_attempts,
            "successful_order_attempts": successful_order_attempts,
            "forward_failed_order_attempts": failed_order_attempts,
            "failed_order_attempts": failed_order_attempts,
            "risk_rejected_orders": len(risk_rejected_events),
            "fills": len(fills),
            "partial_fills": partial_fills,
            "no_fill_orders": len(no_fill_events),
            "no_fills": len(no_fill_events),
            "observations_without_signal": sum(
                1 for event in event_payloads if str(event.get("status", "")).upper() == "NO_SIGNAL"
            ),
            "requested_quantity": requested_quantity,
            "filled_quantity": filled_quantity,
            "fill_ratio": min(1.0, filled_quantity / requested_quantity) if requested_quantity > 0 else None,
            "depth_consumed": sum(max(0.0, _finite(event.get("depth_consumed"), 0.0)) for event in attempt_events),
            "average_slippage": average_slippage,
            "spread_paid": spread_paid,
            "orders_rejected_for_liquidity": liquidity_rejections,
            "forward_liquidity": forward_liquidity,
            "positions_opened": len({(str(fill.market_id or fill.symbol), str(fill.metadata.get("outcome", "yes"))) for fill in fills}),
            "resolved_positions": resolved_positions,
            "independent_markets_traded": len(markets_traded),
            "forward_independent_resolved_bets": independent_resolved_bets,
            "independent_resolved_bets": independent_resolved_bets,
            "unresolved_markets": len(unresolved_markets),
            "unresolved_fills": sum(
                1
                for fill in fills
                if str(fill.market_id or fill.symbol) not in ledger_by_market
            ),
            "forward_gross_pnl": total_gross if ledgers else None,
            "forward_fees": total_fees if ledgers else None,
            "forward_slippage": total_slippage if ledgers else None,
            "forward_net_pnl": total_net if ledgers else None,
            "forward_expectancy": forward_expectancy,
            "forward_roi": forward_roi,
            "forward_confidence_interval": (
                dict(confidence_interval) if isinstance(confidence_interval, Mapping) else None
            ),
            "forward_confidence_lower_bound": forward_confidence_lower_bound,
            "forward_stability": forward_stability,
            "forward_calibration": forward_calibration,
            "forward_max_drawdown": drawdown,
            "forward_peak_equity": peak,
            "forward_regime_count": len(regime_values),
            "risk_breach": bool(set(risk_reasons) & hard_risk_reasons),
            "model_invalid": False,
            "invariant_violation": False,
            "execution_impossible": execution_impossible,
            "resolved_bet_ids": [str(ledger.get("bet_id", "")) for ledger in ledgers],
            "forward_evidence_identity": self._forward_evidence_identity(
                spec,
                observations,
                event_records,
                ledgers,
                fills,
                operational_identity,
            ),
            "paper_only": True,
            "forward_benchmark_comparison": (
                {"baseline_expectancy": 0.0, "delta": forward_expectancy}
                if forward_expectancy is not None
                else None
            ),
        }
        evidence["operational_evidence"] = dict(operational_evidence)
        evidence.update(dict(operational_evidence))
        for source_name, output_name in (
            ("gross_result", "gross_pnl"),
            ("realized_result", "realized_result"),
            ("unrealized_result", "unrealized_result"),
            ("net_result", "net_pnl"),
        ):
            evidence[output_name] = operational_evidence.get(source_name)
        for name, value in operational_identity.items():
            evidence[name] = value
        if operational_identity:
            evidence["evidence_scope"] = "forward_operational_paper"
        # Operational projections retain Decimal arithmetic until this
        # lifecycle boundary.  Use the rolling evidence canonical projection
        # once, after nested and direct compatibility aliases are assembled,
        # so every candidate payload is JSON-safe without changing exact
        # decimal meaning or dropping sparse fields.
        canonical_evidence = _rolling_plain(evidence)
        return dict(canonical_evidence)
    def _evaluate_forward_candidate(self, candidate_id: str, now: datetime) -> CandidateLifecycle | None:
        record = self.lifecycle.get(candidate_id)
        if record is None or record.stage is not CandidateStage.PAPER_FORWARD:
            return record
        evidence = self._forward_evidence(record.as_record(), now)
        updated = self.lifecycle.record_evidence(
            candidate_id,
            evidence,
            expected_stage=CandidateStage.PAPER_FORWARD,
            expected_handoff=record.payload,
            reason="forward result evaluation",
        )
        reasons = self.config.promotion_criteria.evaluate({**updated.payload, **evidence})
        hard_reasons = self.config.promotion_criteria.hard_rejection_reasons(evidence)
        if hard_reasons:
            return self.lifecycle.reject(
                candidate_id,
                hard_reasons[0],
                evidence=evidence,
                expected_stage=CandidateStage.PAPER_FORWARD,
                expected_payload=updated.payload,
            )
        if not reasons:
            return self.lifecycle.advance(
                candidate_id,
                CandidateStage.PAPER_PROMOTABLE,
                {**evidence, "holdout_used": False},
                reason="paper-forward criteria passed; human review required",
            )
        return updated
def _legacy_recovery_document(record: Mapping[str, Any]) -> Mapping[str, Any] | None:
    """Extract JSON evidence before handing a lifecycle row to legacy logic.

    ``load_candidate_lifecycle`` adds metadata such as ``updated_at`` to the
    outer row.  That metadata is useful for ordering but is not part of the
    persisted candidate document and cannot be inspected by the bounded legacy
    classifier.  Keep the document authoritative, using row metadata only
    when the payload omitted its candidate identity.
    """
    payload = record.get("payload")
    if not isinstance(payload, Mapping):
        return None
    document = dict(payload)
    for name in (
        "candidate_id",
        "frozen_hash",
        "predecessor_candidate_id",
        "predecessor_frozen_hash",
        "stage",
    ):
        if name not in document and record.get(name) is not None:
            document[name] = record[name]
    return document


def _nested_legacy_target_market_ids(payload: Mapping[str, Any]) -> tuple[Any, ...] | str | None:
    """Return the nested legacy target binding, if one was persisted."""
    plan = payload.get("experiment_plan")
    if not isinstance(plan, Mapping):
        return None
    target = plan.get("target")
    if not isinstance(target, Mapping):
        return None
    for name in ("market_ids", "exact_market_ids", "markets"):
        if name in target:
            value = target[name]
            if isinstance(value, str):
                return value
            if isinstance(value, (list, tuple, set, frozenset)):
                return tuple(value)
            return (value,)
    return None


def _legacy_recovery_state_digest(evidence: Mapping[str, Any]) -> str:
    """Digest only stable blocker/provenance state, not retry telemetry."""
    material = {
        name: evidence.get(name)
        for name in (
            "predecessor_candidate_id",
            "predecessor_frozen_hash",
            "classification",
            "reason_code",
            "progress",
            "blocker",
            "next_action",
            "scope_hash",
            "scope_version",
            "successor_id",
            "provenance_state",
        )
    }
    return "sha256:" + hashlib.sha256(_canonical_binding(material).encode("utf-8")).hexdigest()


def _legacy_recovery_key(
    record: Mapping[str, Any],
    candidate_id: str | None,
    frozen_hash: str | None,
) -> str:
    """Build a stable identity for one predecessor recovery attempt."""
    material = {
        "candidate_id": candidate_id,
        "frozen_hash": frozen_hash,
        "record": record,
    }
    return (
        "legacy-scope-recovery:"
        + hashlib.sha256(_canonical_binding(material).encode("utf-8")).hexdigest()[:32]
    )
def _candidate_id(
    plan: ExperimentPlan,
    parameters: Mapping[str, Any],
    *,
    generation: int,
    observation_handoff: Mapping[str, Any] | None = None,
) -> str:
    material: dict[str, Any] = {
        "plan_id": plan.plan_id,
        "plan_hash": plan.plan_hash,
        "parameters": dict(parameters),
        "generation": generation,
    }
    if isinstance(observation_handoff, Mapping) and observation_handoff:
        # Successor identity is distinct from the immutable predecessor while
        # retaining only bounded queue lineage in the candidate hash.
        material["observation_handoff"] = {
            "version": str(observation_handoff.get("version", "")).strip(),
            "predecessor_queue_id": str(
                observation_handoff.get("predecessor_queue_id", "")
            ).strip(),
            "predecessor_dedupe_key": str(
                observation_handoff.get("predecessor_dedupe_key", "")
            ).strip(),
        }
    token = json.dumps(
        material,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )
    return "candidate-" + hashlib.sha256(token.encode("utf-8")).hexdigest()[:24]

def _mutation_candidate_id(parent_id: str, generation: int, strategy: StrategyDefinition) -> str:
    document = strategy.to_dict()
    document.pop("strategy_id", None)
    token = json.dumps(
        {"parent": str(parent_id), "generation": generation, "strategy": document, "seed": 0},
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    )
    return "mutation-" + hashlib.sha256(token.encode("utf-8")).hexdigest()[:24]

def _normalize_hypothesis_payload(
    payload: Mapping[str, Any],
    item: ResearchQueueItem | None = None,
    *,
    source_fallback: str | None = None,
) -> dict[str, Any]:
    result = dict(payload)
    item_id = item.item_id if item is not None else ""
    hypothesis_id = str(result.get("proposal_id", result.get("hypothesis_id", ""))).strip() or item_id
    assumptions = result.get("assumptions", {})
    assumptions = assumptions if isinstance(assumptions, Mapping) else {}
    if hypothesis_id or "proposal_id" in result:
        result.setdefault("proposal_id", hypothesis_id)
    if item is not None:
        default_source = item.author or item.source or "hermes"
    else:
        default_source = source_fallback or "hermes"
    result.setdefault("source", str(result.get("author", default_source)) or "hermes")
    result.setdefault("tests", ["bounded chronological backtest and validation"])
    market_type = result.get("market_type")
    plan_value = result.get("experiment_plan")
    if isinstance(plan_value, Mapping):
        market_type = plan_value.get("market_type", market_type)
    # Prediction proposals retain their historical compatibility default. A
    # crypto proposal must state its immutable dataset version explicitly.
    if str(market_type or "prediction").strip().lower() != MarketType.CRYPTO_SPOT.value:
        result.setdefault("dataset_version", assumptions.get("dataset_version", "axiom-persisted-v1"))
    result.setdefault("time_split", "train-validation-holdout")
    result.setdefault("paper_only", True)
    if "experiment_plan" not in result and isinstance(assumptions.get("experiment_plan"), Mapping):
        result["experiment_plan"] = assumptions["experiment_plan"]
    return result


def _normalize_row(value: Any) -> dict[str, Any] | None:
    if isinstance(value, Mapping):
        row = dict(value)
        nested = row.get("snapshot")
        if isinstance(nested, Mapping):
            merged = dict(nested)
            merged.update({key: child for key, child in row.items() if key != "snapshot"})
            row = merged
        payload = row.get("payload")
        if isinstance(payload, Mapping) and isinstance(payload.get("snapshot"), Mapping):
            merged = dict(payload["snapshot"])
            merged.update({key: child for key, child in row.items() if key != "payload"})
            row = merged
        # Historical PRICE_PROXY records may persist the observed probability
        # under ``price``.  This is a representation normalization, not a
        # quote synthesis: bid/ask fields remain absent when they were absent
        # in the source dataset.
        if row.get("yes_mid") is None and row.get("price") is not None:
            row["yes_mid"] = row["price"]
        return row
    return None


def _value(row: Mapping[str, Any], name: str, default: Any = None) -> Any:
    return row.get(name, default)

def _normal_symbol(value: Any) -> str:
    return str(value).replace("/", "").replace("-", "").replace("_", "").strip().upper()


def _time_to_expiry(row: Mapping[str, Any]) -> float:
    direct = _finite(row.get("time_to_expiry_seconds"), math.nan)
    if math.isfinite(direct):
        return direct
    stamp = parse_timestamp(row.get("timestamp"))
    expiry = parse_timestamp(row.get("expiry"))
    if stamp is None or expiry is None:
        return math.nan
    return (expiry - stamp).total_seconds()


def _as_regime_set(value: Any, name: str) -> set[str]:
    if isinstance(value, str):
        values = {value}
    elif isinstance(value, (list, tuple, set)):
        values = {str(item) for item in value if str(item).strip()}
    else:
        raise AutonomousResearchError("UNSUPPORTED_FEATURE", f"{name} must be text or a bounded list")
    if not values:
        raise AutonomousResearchError("UNSUPPORTED_FEATURE", f"{name} must not be empty")
    return values


def _in_bound(value: float, bound: Any) -> bool:
    if not math.isfinite(value):
        return False
    if isinstance(bound, (list, tuple)):
        if len(bound) == 2:
            low, high = _finite(bound[0], math.nan), _finite(bound[1], math.nan)
            return math.isfinite(low) and math.isfinite(high) and min(low, high) <= value <= max(low, high)
        return any(abs(value - _finite(item, math.nan)) <= 1e-12 for item in bound if math.isfinite(_finite(item, math.nan)))
    target = _finite(bound, math.nan)
    return math.isfinite(target) and abs(value - target) <= 1e-12


def _has_book(rows: Sequence[Mapping[str, Any]]) -> bool:
    return any(isinstance(row.get("order_book"), Mapping) or isinstance(row.get("yes_order_book"), Mapping) for row in rows)


def _finite(value: Any, default: float = 0.0) -> float:
    try:
        number = float(value)
    except (TypeError, ValueError):
        return float(default)
    return number if math.isfinite(number) else float(default)


def _settlement_name(value: Any) -> str:
    if isinstance(value, SettlementState):
        return value.value
    return str(value or "").strip().lower()


def _is_finite_number(value: Any) -> bool:
    try:
        return math.isfinite(float(value))
    except (TypeError, ValueError):
        return False


def _hash_document(value: Any) -> str:
    encoded = json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False, default=str)
    return "sha256:" + hashlib.sha256(encoded.encode("utf-8")).hexdigest()


